};

export default Dashboard;

export type Language = 'en' | 'ml' | 'ta';

export enum PrayerStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  MISSED = 'missed',
  EXCUSED = 'excused'
}

export interface UserProfile {
  name: string;
  age: number;
  sex: 'male' | 'female';
  place: string;
  preferredLanguage: Language;
  isLoggedIn: boolean;
}

export interface PrayerLog {
  fajr: PrayerStatus;
  dhuhr: PrayerStatus;
  asr: PrayerStatus;
  maghrib: PrayerStatus;
  isha: PrayerStatus;
}

export interface FastingLog {
  status: 'none' | 'completed' | 'missed' | 'excused';
  type: 'ramadan' | 'sunnah';
}

export interface QuranProgress {
  surah: string;
  ayah: string;
  lastUpdated: string;
}

export interface DhikrChallenge {
  title: string;
  target: number;
  current: number;
}

export interface DhikrHistoryEntry {
  id: string;
  title: string;
  target: number;
  current: number;
  date: string;
}

export interface PrayerTimings {
  Fajr: string;
  Dhuhr: string;
  Asr: string;
  Maghrib: string;
  Isha: string;
  Sunrise: string;
}

export interface QadaReminder {
  id: string;
  time: string;
  enabled: boolean;
}

export interface AppState {
  profile: UserProfile | null;
  prayerLogs: Record<string, PrayerLog>;
  sunnahLogs: Record<string, string[]>;
  fastingLogs: Record<string, FastingLog>;
  quranProgress: QuranProgress;
  dhikrCount: number;
  dhikrChallenge: DhikrChallenge;
  dhikrHistory: DhikrHistoryEntry[];
  isHaydNifas: boolean;
  haydStartDate: string | null;
  settings: {
    notificationsEnabled: boolean;
    locationEnabled: boolean;
    qadaReminders: QadaReminder[];
  };
  todayTimings: PrayerTimings | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';

const STORAGE_KEY = 'ibadathi_app_state_v3';

const initialState: AppState = {
  profile: null,
  prayerLogs: {},
  sunnahLogs: {},
  fastingLogs: {},
  quranProgress: { surah: '', ayah: '', lastUpdated: '' },
  dhikrCount: 0,
  dhikrChallenge: { title: 'SubhanAllah', target: 100, current: 0 },
  dhikrHistory: [],
  isHaydNifas: false,
  haydStartDate: null,
  settings: {
    notificationsEnabled: false,
    locationEnabled: false,
    qadaReminders: []
  },
  todayTimings: null
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    state.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla'>(
    state.profile?.isLoggedIn ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  // Fetch Prayer Timings
  useEffect(() => {
    if (state.profile?.isLoggedIn && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ 
              ...prev, 
              todayTimings: data.data.timings,
              settings: { ...prev.settings, locationEnabled: true }
            }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.profile?.isLoggedIn]);

  // Combined Notification Loop
  useEffect(() => {
    if (!state.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      // 1. Check current Fard prayers
      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];

          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;

            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      // 2. Check Qada reminders
      for (const reminder of state.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;

          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, state.settings.notificationsEnabled, state.settings.qadaReminders, currentLanguage]);

  const handleLogin = (profile: UserProfile) => {
    setState(prev => ({ 
      ...prev, 
      profile: { ...profile, isLoggedIn: true, preferredLanguage: currentLanguage } 
    }));
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, profile: null, isLoggedIn: false }));
    setCurrentView('welcome');
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    setState(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING,
        dhuhr: PrayerStatus.PENDING,
        asr: PrayerStatus.PENDING,
        maghrib: PrayerStatus.PENDING,
        isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    setState(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName)
        ? currentDaySunnah.filter(name => name !== sunnahName)
        : [...currentDaySunnah, sunnahName];
      return {
        ...prev,
        sunnahLogs: {
          ...prev.sunnahLogs,
          [date]: updated
        }
      };
    });
  };

  const toggleNotifications = async () => {
    if (!state.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else {
        alert("Please allow notifications in your browser settings.");
      }
    } else {
      setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
    }
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    setState(prev => ({
      ...prev,
      settings: { ...prev.settings, qadaReminders: reminders }
    }));
  };

  const toggleHayd = (isActive: boolean) => {
    setState(prev => ({
      ...prev,
      isHaydNifas: isActive,
      haydStartDate: isActive ? new Date().toISOString().split('T')[0] : null
    }));
  };

  const archiveChallenge = () => {
    setState(prev => {
      const newEntry: DhikrHistoryEntry = {
        id: Date.now().toString(),
        title: prev.dhikrChallenge.title,
        target: prev.dhikrChallenge.target,
        current: prev.dhikrChallenge.current,
        date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newEntry, ...prev.dhikrHistory],
        dhikrChallenge: { ...prev.dhikrChallenge, current: 0 }
      };
    });
  };

  const renderView = () => {
    if (currentView === 'welcome') {
      return (
        <Welcome 
          onEnter={() => setCurrentView('login')} 
          language={currentLanguage} 
          setLanguage={setCurrentLanguage}
          t={t}
        />
      );
    }

    if (currentView === 'login') {
      return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} />;
    }

    if (!state.profile) return null;

    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            setCurrentView={setCurrentView} 
            t={t} 
            onLogout={handleLogout} 
            toggleNotifications={toggleNotifications}
          />
        );
      case 'fard':
        return (
          <FardPrayers 
            state={state} 
            updatePrayerStatus={updatePrayerStatus} 
            toggleSunnahStatus={toggleSunnahStatus}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'qadah':
        return (
          <QadahCalendar 
            state={state} 
            updatePrayerStatus={updatePrayerStatus} 
            updateReminders={updateQadaReminders}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'women':
        return <WomensSpace state={state} toggleHayd={toggleHayd} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={state} 
            updateCount={(c) => setState(p => ({ ...p, dhikrCount: c }))} 
            updateChallenge={(c) => setState(p => ({ ...p, dhikrChallenge: { ...p.dhikrChallenge, current: c } }))}
            updateChallengeSettings={(s) => setState(p => ({ ...p, dhikrChallenge: { ...p.dhikrChallenge, ...s } }))}
            archiveChallenge={archiveChallenge}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return (
          <QuranTracker 
            state={state} 
            onUpdate={(progress) => setState(p => ({ ...p, quranProgress: progress }))} 
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'fasting':
        return (
          <FastingTracker 
            state={state} 
            updateFasting={(date, log) => setState(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [date]: log } }))}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} />;
    }
  };

  return (
    <div className="min-h-screen relative">
      <div className="islamic-pattern fixed inset-0 pointer-events-none"></div>
      <main className="relative z-10 max-w-md mx-auto min-h-screen bg-white shadow-xl overflow-x-hidden">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState, DhikrChallenge } from '../types';

interface DhikrCounterProps {
  state: AppState;
  updateCount: (count: number) => void;
  updateChallenge: (count: number) => void;
  updateChallengeSettings: (settings: Partial<DhikrChallenge>) => void;
  archiveChallenge: () => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const DhikrCounter: React.FC<DhikrCounterProps> = ({ state, updateCount, updateChallenge, updateChallengeSettings, archiveChallenge, setCurrentView, t }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [editTitle, setEditTitle] = useState(state.dhikrChallenge.title);
  const [editTarget, setEditTarget] = useState(state.dhikrChallenge.target.toString());

  const handleCount = () => {
    updateCount(state.dhikrCount + 1);
    updateChallenge(state.dhikrChallenge.current + 1);

    if ('vibrate' in navigator) {
      navigator.vibrate(50);
    }
  };

  const resetCount = () => {
    if (confirm(t('reset') + "?")) {
      updateCount(0);
    }
  };

  const handleSaveSettings = () => {
    const targetVal = parseInt(editTarget);
    if (isNaN(targetVal) || targetVal <= 0) {
      alert("Please enter a valid target number.");
      return;
    }
    updateChallengeSettings({
      title: editTitle,
      target: targetVal
    });
    setIsEditing(false);
  };

  const handleArchive = () => {
    archiveChallenge();
    alert(t('archiveSuccess'));
  };

  if (showHistory) {
    return (
      <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up">
        <div className="p-6 flex items-center justify-between bg-[#064e3b] text-white">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(false)} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10">
              <i className="fas fa-chevron-left text-xs"></i>
            </button>
            <h1 className="text-xl font-bold tracking-tight">{t('history')}</h1>
          </div>
        </div>

        <div className="p-6 flex-1 overflow-y-auto space-y-4">
          {state.dhikrHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-slate-300">
               <i className="fas fa-box-open text-5xl mb-4 opacity-20"></i>
               <p className="text-sm font-black uppercase tracking-widest">{t('noHistory')}</p>
            </div>
          ) : (
            state.dhikrHistory.map((entry) => {
              const percentage = Math.round((entry.current / entry.target) * 100);
              const dateObj = new Date(entry.date);
              return (
                <div key={entry.id} className="bg-white p-5 rounded-[28px] border border-emerald-50 shadow-sm shadow-emerald-900/5 flex flex-col gap-3">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-sm font-black text-[#064e3b]">{entry.title}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
                        {dateObj.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                      </p>
                    </div>
                    <div className="px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                      <span className="text-[10px] font-black text-emerald-700">{percentage}%</span>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <div className="w-full bg-slate-50 h-2 rounded-full overflow-hidden border border-slate-100">
                       <div 
                        className="bg-emerald-500 h-full rounded-full transition-all duration-1000"
                        style={{ width: `${Math.min(100, percentage)}%` }}
                       ></div>
                    </div>
                    <div className="flex justify-between items-center text-[9px] font-black text-slate-400 uppercase tracking-widest">
                       <span>{entry.current} / {entry.target}</span>
                       <span>Archived</span>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up">
      {/* Header */}
      <div className="p-6 flex items-center justify-between bg-[#064e3b] text-white">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h1 className="text-xl font-bold tracking-tight">{t('dhikr')}</h1>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => setShowHistory(true)} 
            className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10"
          >
            <i className="fas fa-history text-xs"></i>
          </button>
          <button 
            onClick={() => setIsEditing(!isEditing)} 
            className={`w-10 h-10 flex items-center justify-center rounded-full transition-all ${isEditing ? 'bg-white text-[#064e3b]' : 'bg-white/10 hover:bg-white/20'}`}
          >
            <i className="fas fa-sliders text-xs"></i>
          </button>
        </div>
      </div>

      <div className="p-8 flex flex-col items-center flex-1 justify-between gap-10 relative">
        {/* Settings Overlay */}
        {isEditing && (
          <div className="absolute inset-0 bg-[#fdfbf7]/98 z-20 p-8 flex flex-col items-center justify-center animate-fade-up">
            <div className="w-16 h-16 bg-emerald-50 rounded-3xl flex items-center justify-center mb-6">
               <i className="fas fa-gear text-[#064e3b] text-2xl"></i>
            </div>
            <h2 className="text-xl font-black text-[#064e3b] mb-8 uppercase tracking-widest">Challenge Settings</h2>
            <div className="w-full space-y-6 mb-10 max-w-xs">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Challenge Title</label>
                <input 
                  type="text"
                  className="w-full p-5 bg-white border border-emerald-50 rounded-[24px] focus:ring-4 focus:ring-emerald-500/10 outline-none shadow-sm font-bold text-[#064e3b]"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  placeholder="e.g. SubhanAllah"
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Daily Target</label>
                <input 
                  type="number"
                  className="w-full p-5 bg-white border border-emerald-50 rounded-[24px] focus:ring-4 focus:ring-emerald-500/10 outline-none shadow-sm font-bold text-[#064e3b]"
                  value={editTarget}
                  onChange={(e) => setEditTarget(e.target.value)}
                  placeholder="e.g. 100"
                />
              </div>
            </div>
            <div className="flex gap-4 w-full max-w-xs">
              <button 
                onClick={() => setIsEditing(false)}
                className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-[24px] font-black text-[10px] uppercase tracking-widest"
              >
                Cancel
              </button>
              <button 
                onClick={handleSaveSettings}
                className="flex-1 py-4 bg-[#064e3b] text-white rounded-[24px] font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-900/20 active:scale-95 transition-all"
              >
                Save Changes
              </button>
            </div>
          </div>
        )}

        <div className="text-center mt-4">
          <p className="text-emerald-800/40 text-[10px] uppercase tracking-[0.4em] font-black mb-4">Total Recitations</p>
          <div className="text-8xl font-black text-[#064e3b] tracking-tighter tabular-nums drop-shadow-sm">
            {state.dhikrCount.toLocaleString()}
          </div>
        </div>

        {/* Tactile Counter Button */}
        <button 
          onClick={handleCount}
          className="relative w-72 h-72 group"
        >
           <div className="absolute inset-0 bg-[#064e3b] rounded-full blur-[40px] opacity-10 group-active:opacity-20 transition-opacity"></div>
           <div className="absolute inset-0 bg-gradient-to-br from-emerald-500 to-[#064e3b] rounded-full shadow-[0_30px_60px_-12px_rgba(6,78,59,0.4)] transform group-active:scale-90 transition-all duration-75 flex items-center justify-center border-[8px] border-white/20">
              <i className="fas fa-fingerprint text-white text-7xl opacity-90"></i>
           </div>
        </button>

        {/* Active Challenge Progress Card */}
        <div className="w-full max-w-sm bg-white p-7 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50">
          <div className="flex justify-between items-end mb-4">
            <div>
              <h3 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">{t('challenge')}</h3>
              <p className="text-sm font-bold text-[#064e3b]">{state.dhikrChallenge.title}</p>
            </div>
            <div className="text-right">
              <span className="text-2xl font-black text-[#064e3b]">
                {Math.round((state.dhikrChallenge.current / state.dhikrChallenge.target) * 100)}%
              </span>
            </div>
          </div>
          <div className="w-full bg-emerald-50 h-3 rounded-full overflow-hidden border border-emerald-100 mb-4">
            <div 
              className="bg-[#064e3b] h-full transition-all duration-500 ease-out"
              style={{ width: `${Math.min(100, (state.dhikrChallenge.current / state.dhikrChallenge.target) * 100)}%` }}
            ></div>
          </div>

          <div className="flex justify-between items-center mb-6">
             <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Progress Today</span>
             <span className="text-[10px] text-emerald-800 font-black tracking-widest">{state.dhikrChallenge.current} / {state.dhikrChallenge.target}</span>
          </div>

          <button 
            onClick={handleArchive}
            className="w-full py-4 bg-emerald-50 text-emerald-700 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] border border-emerald-100 hover:bg-emerald-100 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            <i className="fas fa-box-archive text-[12px]"></i>
            {t('completeAndArchive')}
          </button>
        </div>

        <button 
          onClick={resetCount}
          className="text-slate-300 hover:text-rose-400 transition-colors text-[10px] uppercase tracking-[0.3em] font-black flex items-center gap-2 mb-2"
        >
          <i className="fas fa-trash-can text-[8px]"></i>
          {t('reset')} Counter
        </button>
      </div>
    </div>
  );
};

