import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';

const STORAGE_KEY = 'ibadathi_app_state_v3';

const initialState: AppState = {
  profile: null,
  prayerLogs: {},
  sunnahLogs: {},
  fastingLogs: {},
  quranProgress: { surah: '', ayah: '', lastUpdated: '' },
  dhikrCount: 0,
  dhikrChallenge: { title: 'SubhanAllah', target: 100, current: 0 },
  dhikrHistory: [],
  isHaydNifas: false,
  haydStartDate: null,
  settings: {
    notificationsEnabled: false,
    locationEnabled: false,
    qadaReminders: []
  },
  todayTimings: null
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    state.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla'>(
    state.profile?.isLoggedIn ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  // Fetch Prayer Timings
  useEffect(() => {
    if (state.profile?.isLoggedIn && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ 
              ...prev, 
              todayTimings: data.data.timings,
              settings: { ...prev.settings, locationEnabled: true }
            }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.profile?.isLoggedIn]);

  // Combined Notification Loop
  useEffect(() => {
    if (!state.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      // 1. Check current Fard prayers
      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];

          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;

            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      // 2. Check Qada reminders
      for (const reminder of state.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;

          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, state.settings.notificationsEnabled, state.settings.qadaReminders, currentLanguage]);

  const handleLogin = (profile: UserProfile) => {
    setState(prev => ({ 
      ...prev, 
      profile: { ...profile, isLoggedIn: true, preferredLanguage: currentLanguage } 
    }));
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, profile: null, isLoggedIn: false }));
    setCurrentView('welcome');
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    setState(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING,
        dhuhr: PrayerStatus.PENDING,
        asr: PrayerStatus.PENDING,
        maghrib: PrayerStatus.PENDING,
        isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    setState(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName)
        ? currentDaySunnah.filter(name => name !== sunnahName)
        : [...currentDaySunnah, sunnahName];
      return {
        ...prev,
        sunnahLogs: {
          ...prev.sunnahLogs,
          [date]: updated
        }
      };
    });
  };

  const toggleNotifications = async () => {
    if (!state.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else {
        alert("Please allow notifications in your browser settings.");
      }
    } else {
      setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
    }
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    setState(prev => ({
      ...prev,
      settings: { ...prev.settings, qadaReminders: reminders }
    }));
  };

  const toggleHayd = (isActive: boolean) => {
    setState(prev => ({
      ...prev,
      isHaydNifas: isActive,
      haydStartDate: isActive ? new Date().toISOString().split('T')[0] : null
    }));
  };

  const archiveChallenge = () => {
    setState(prev => {
      const newEntry: DhikrHistoryEntry = {
        id: Date.now().toString(),
        title: prev.dhikrChallenge.title,
        target: prev.dhikrChallenge.target,
        current: prev.dhikrChallenge.current,
        date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newEntry, ...prev.dhikrHistory],
        dhikrChallenge: { ...prev.dhikrChallenge, current: 0 }
      };
    });
  };

  const renderView = () => {
    if (currentView === 'welcome') {
      return (
        <Welcome 
          onEnter={() => setCurrentView('login')} 
          language={currentLanguage} 
          setLanguage={setCurrentLanguage}
          t={t}
        />
      );
    }

    if (currentView === 'login') {
      return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} />;
    }

    if (!state.profile) return null;

    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            setCurrentView={setCurrentView} 
            t={t} 
            onLogout={handleLogout} 
            toggleNotifications={toggleNotifications}
            updatePrayerStatus={updatePrayerStatus}
          />
        );
      case 'fard':
        return (
          <FardPrayers 
            state={state} 
            updatePrayerStatus={updatePrayerStatus} 
            toggleSunnahStatus={toggleSunnahStatus}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'qadah':
        return (
          <QadahCalendar 
            state={state} 
            updatePrayerStatus={updatePrayerStatus} 
            updateReminders={updateQadaReminders}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'women':
        return <WomensSpace state={state} toggleHayd={toggleHayd} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={state} 
            updateCount={(c) => setState(p => ({ ...p, dhikrCount: c }))} 
            updateChallenge={(c) => setState(p => ({ ...p, dhikrChallenge: { ...p.dhikrChallenge, current: c } }))}
            updateChallengeSettings={(s) => setState(p => ({ ...p, dhikrChallenge: { ...p.dhikrChallenge, ...s } }))}
            archiveChallenge={archiveChallenge}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return (
          <QuranTracker 
            state={state} 
            onUpdate={(progress) => setState(p => ({ ...p, quranProgress: progress }))} 
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'fasting':
        return (
          <FastingTracker 
            state={state} 
            updateFasting={(date, log) => setState(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [date]: log } }))}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="min-h-screen relative">
      <div className="islamic-pattern fixed inset-0 pointer-events-none"></div>
      <main className="relative z-10 max-w-md mx-auto min-h-screen bg-white shadow-xl overflow-x-hidden">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: AppState;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;

    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-600' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-emerald-100 text-teal-800', iconColor: 'text-teal-600' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-600' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-amber-50 to-amber-100 text-amber-900', iconColor: 'text-amber-600' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-800', iconColor: 'text-indigo-600' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-emerald-50 to-teal-50 text-emerald-900', iconColor: 'text-emerald-500' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-500' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;

    const timingsMinutes: { name: string; total: number; time: string }[] = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });

    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex: number;
    let isTomorrow = false;

    if (nextIndex === -1) {
      nextIndex = 0;
      prevIndex = timingsMinutes.length - 1;
      isTomorrow = true;
    } else {
      prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1;
    }

    const next = timingsMinutes[nextIndex];
    const prev = timingsMinutes[prevIndex];

    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;

    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));

    const hh = Math.floor(diff / 60);
    const mm = diff % 60;

    return {
      next,
      timeLeft: `${hh}h ${mm}m`,
      progress,
      activeName: prev.name,
      timingsMinutes
    };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="pb-24 animate-fade-up">
      {/* Header */}
      <header className="relative bg-[#064e3b] text-white pt-10 pb-20 px-6 rounded-b-[40px] shadow-2xl overflow-hidden">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/5 rounded-full blur-3xl"></div>
        <div className="absolute top-20 -left-10 w-32 h-32 bg-emerald-400/10 rounded-full blur-2xl"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-md">
                <i className="fas fa-mosque text-emerald-300 text-xl"></i>
              </div>
              <div>
                <h2 className="text-[10px] text-emerald-200/60 uppercase tracking-[0.2em] font-bold">{t('welcome')}</h2>
                <h1 className="text-xl font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={toggleNotifications}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-emerald-500 shadow-lg shadow-emerald-500/20' : 'bg-white/10 hover:bg-white/20'}`}
              >
                <i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-xs`} title={t('notifications')}></i>
              </button>
              <button 
                onClick={onLogout} 
                className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-all border border-white/10"
              >
                <i className="fas fa-power-off text-sm text-rose-300"></i>
              </button>
            </div>
          </div>

          <div className="flex gap-4">
            <div className="flex-1 bg-white/5 backdrop-blur-md p-4 rounded-3xl border border-white/10">
              <span className="text-[10px] text-emerald-300/80 uppercase font-bold tracking-widest block mb-1">{t('dhikr')}</span>
              <span className="text-2xl font-black">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 bg-white/5 backdrop-blur-md p-4 rounded-3xl border border-white/10">
              <span className="text-[10px] text-emerald-300/80 uppercase font-bold tracking-widest block mb-1">{t('lastRead')}</span>
              <span className="text-sm font-bold truncate block">
                {state.quranProgress.surah || 'Not set'}
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Next Prayer Card */}
      <div className="px-6 -mt-10 mb-6">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden group">
          <div className="flex items-center justify-between mb-4">
            <div>
              <span className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.2em] block mb-1">{t('nextPrayer')}</span>
              <div className="flex items-center gap-3">
                <h2 className="text-3xl font-black text-[#064e3b] capitalize">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <div className="px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                  <span className="text-xs font-black text-emerald-600">{prayerTimingData?.next.time}</span>
                </div>
              </div>
            </div>
            <div className="text-right">
              <span className="text-2xl font-black text-emerald-500 drop-shadow-sm">{prayerTimingData?.timeLeft || '--:--'}</span>
              <span className="text-[9px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>

          <div className="mb-2">
            <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden p-0.5 border border-slate-50 shadow-inner">
              <div 
                className="bg-gradient-to-r from-emerald-400 via-emerald-500 to-emerald-600 h-full rounded-full transition-all duration-1000 ease-in-out shadow-[0_0_8px_rgba(16,185,129,0.3)]"
                style={{ width: `${prayerTimingData?.progress || 0}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Today's Fard Prayers Section */}
      <div className="px-6 mb-8">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden">
          <div className="flex items-center justify-between mb-5">
            <div className="flex items-center gap-2">
              <div className="w-2 h-6 bg-emerald-600 rounded-full"></div>
              <h3 className="text-sm font-black text-[#064e3b] uppercase tracking-widest">{t('todayPrayers')}</h3>
            </div>
            {state.isHaydNifas && (
              <span className="text-[9px] font-black px-3 py-1 bg-pink-50 text-pink-600 rounded-full border border-pink-100 uppercase tracking-tighter">
                {t('excused')} Mode
              </span>
            )}
          </div>

          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              const isAnimating = animatingPrayer === p;

              // Missed detection: If not completed and time has passed
              let isMissed = false;
              if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                const timing = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                if (timing && timing.total < currentTimeMinutes) {
                  isMissed = true;
                }
              }

              return (
                <button
                  key={p}
                  disabled={state.isHaydNifas}
                  onClick={() => handlePrayerToggle(p)}
                  className={`relative flex flex-col items-center p-3 rounded-2xl transition-all duration-300 border ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-50 border-emerald-100 text-emerald-700 shadow-sm shadow-emerald-900/5' 
                      : isMissed 
                        ? 'bg-rose-50 border-rose-100 text-rose-700 shadow-sm shadow-rose-900/5' 
                        : 'bg-slate-50 border-transparent text-slate-400'
                  } ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-50 grayscale cursor-not-allowed' : 'active:scale-90'}`}
                >
                  {isAnimating && (
                    <div className="absolute inset-0 pointer-events-none rounded-2xl animate-ripple-glow"></div>
                  )}

                  <span className="text-[8px] font-black uppercase tracking-tighter mb-2">{t(p).substring(0, 3)}</span>

                  <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-600 text-white' 
                      : isMissed 
                        ? 'bg-rose-500 text-white' 
                        : 'bg-white text-slate-200 shadow-inner'
                  }`}>
                    {status === PrayerStatus.COMPLETED ? (
                      <i className="fas fa-check text-[10px] animate-check-draw"></i>
                    ) : isMissed ? (
                      <i className="fas fa-exclamation text-[10px]"></i>
                    ) : (
                      <i className="fas fa-circle text-[6px]"></i>
                    )}
                  </div>

                  {state.isHaydNifas && (
                    <div className="mt-2 text-[7px] font-bold text-pink-400 uppercase tracking-tighter">
                      Excused
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Menu Items Grid */}
      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        {menuItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setCurrentView(item.id)}
            className={`flex flex-col items-center justify-center p-6 rounded-[28px] shadow-sm hover:shadow-xl transition-all active:scale-95 bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden`}
          >
            <div className="absolute -bottom-2 -right-2 opacity-[0.03] group-hover:scale-125 transition-transform duration-500">
               <i className={`fas ${item.icon} text-6xl`}></i>
            </div>
            <div className={`w-14 h-14 rounded-2xl ${item.iconColor} bg-white/80 shadow-inner flex items-center justify-center mb-4 transition-transform group-hover:scale-110`}>
              <i className={`fas ${item.icon} text-2xl`}></i>
            </div>
            <span className="text-xs font-extrabold text-center uppercase tracking-wider">{item.label}</span>
          </button>
        ))}
      </div>

      {/* Daily Hadith */}
      <div className="px-6 mb-8">
        <div className="bg-white p-7 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-[0.03] group-hover:opacity-[0.05] transition-opacity">
            <i className="fas fa-quote-right text-7xl"></i>
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4">
              <span className="bg-emerald-600 text-[10px] text-white font-extrabold px-3 py-1 rounded-full uppercase tracking-widest">
                {t('hadithTitle')}
              </span>
              <div className="h-px flex-1 bg-emerald-50"></div>
            </div>
            <div className="space-y-4">
              <p className="text-[#064e3b] arabic-font text-xl leading-relaxed text-right font-bold" dir="rtl">
                {dailyHadith.arabic}
              </p>
              <p className="text-[#1a2e2a] font-medium leading-[1.8] italic text-sm border-l-2 border-emerald-100 pl-4">
                "{dailyHadith[userLang]}"
              </p>
            </div>
            <div className="flex items-center justify-end text-[10px] font-bold text-emerald-700/60 uppercase tracking-[0.1em] mt-4">
              <i className="fas fa-bookmark mr-2 text-[8px]"></i>
              {dailyHadith.reference}
            </div>
          </div>
        </div>
      </div>

      <div className="px-6">
        <div className="bg-gradient-to-br from-[#064e3b] to-[#042f24] p-6 rounded-[32px] text-white shadow-xl shadow-emerald-950/20 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-10">
            <i className="fas fa-star-and-crescent text-4xl"></i>
          </div>
          <div className="flex justify-between items-center mb-4">
            <div>
              <h3 className="text-emerald-200 text-[10px] uppercase font-black tracking-widest mb-1">{t('challenge')}</h3>
              <p className="text-sm font-bold">{state.dhikrChallenge.title}</p>
            </div>
            <div className="text-right">
              <span className="text-xl font-black text-emerald-400">
                {Math.round((state.dhikrChallenge.current / state.dhikrChallenge.target) * 100)}%
              </span>
            </div>
          </div>
          <div className="w-full bg-white/10 h-2.5 rounded-full overflow-hidden mb-3 border border-white/5">
            <div 
              className="bg-gradient-to-r from-emerald-400 to-teal-300 h-full transition-all duration-1000 ease-out rounded-full shadow-[0_0_10px_rgba(52,211,153,0.5)]"
              style={{ width: `${Math.min(100, (state.dhikrChallenge.current / state.dhikrChallenge.target) * 100)}%` }}
            ></div>
          </div>
          <div className="flex justify-between items-center text-[10px] text-emerald-200/70 font-bold uppercase">
             <span>Current Progress</span>
             <span className="text-white font-black">{state.dhikrChallenge.current} / {state.dhikrChallenge.target}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { AppState, PrayerStatus, QadaReminder } from '../types';
import { PRAYERS } from '../constants';

interface QadahCalendarProps {
  state: AppState;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  updateReminders: (reminders: QadaReminder[]) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QadahCalendar: React.FC<QadahCalendarProps> = ({ state, updatePrayerStatus, updateReminders, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(new Date().toISOString().split('T')[0]);
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [showRemindersModal, setShowRemindersModal] = useState(false);

  const month = viewDate.getMonth();
  const year = viewDate.getFullYear();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const days = useMemo(() => {
    const arr = [];
    for (let i = 0; i < firstDayOfMonth; i++) {
      arr.push(null);
    }
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      arr.push(dateStr);
    }
    return arr;
  }, [month, year]);

  const getDaySummary = (dateStr: string) => {
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 'none';

    const values = Object.values(logs);
    if (values.every(v => v === PrayerStatus.EXCUSED)) return 'excused';
    if (values.every(v => v === PrayerStatus.COMPLETED || v === PrayerStatus.EXCUSED)) return 'completed';
    if (values.some(v => v === PrayerStatus.MISSED)) return 'missed';
    return 'pending';
  };

  const getMissedCount = (dateStr: string) => {
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 0;
    return PRAYERS.filter(p => logs[p] === PrayerStatus.MISSED).length;
  };

  const nextMonth = () => setViewDate(new Date(year, month + 1, 1));
  const prevMonth = () => setViewDate(new Date(year, month - 1, 1));

  const monthName = viewDate.toLocaleString(state.profile?.preferredLanguage || 'en', { month: 'long' });

  const totalMissedStats = useMemo(() => {
    let missed = 0;
    Object.values(state.prayerLogs).forEach(day => {
      PRAYERS.forEach(p => {
        if (day[p] === PrayerStatus.MISSED) missed++;
      });
    });
    return missed;
  }, [state.prayerLogs]);

  const selectedDayLogs = selectedDate ? (state.prayerLogs[selectedDate] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  }) : null;

  const handleStatusChange = (prayer: string, status: PrayerStatus) => {
    if (selectedDate) {
      if (status === PrayerStatus.COMPLETED) {
        setAnimatingPrayer(prayer);
        setTimeout(() => setAnimatingPrayer(null), 800);
      }
      updatePrayerStatus(selectedDate, prayer as any, status);
    }
  };

  const handleBulkStatusChange = (status: PrayerStatus) => {
    if (selectedDate) {
      PRAYERS.forEach(prayer => {
        updatePrayerStatus(selectedDate, prayer, status);
      });
      if (status === PrayerStatus.COMPLETED) {
         setAnimatingPrayer('bulk');
         setTimeout(() => setAnimatingPrayer(null), 1000);
      }
    }
  };

  const addReminder = () => {
    const newReminders = [...state.settings.qadaReminders, {
      id: Date.now().toString(),
      time: '09:00',
      enabled: true
    }];
    updateReminders(newReminders);
  };

  const removeReminder = (id: string) => {
    const newReminders = state.settings.qadaReminders.filter(r => r.id !== id);
    updateReminders(newReminders);
  };

  const updateReminderTime = (id: string, time: string) => {
    const newReminders = state.settings.qadaReminders.map(r => r.id === id ? { ...r, time } : r);
    updateReminders(newReminders);
  };

  const toggleReminder = (id: string) => {
    const newReminders = state.settings.qadaReminders.map(r => r.id === id ? { ...r, enabled: !r.enabled } : r);
    updateReminders(newReminders);
  };

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up relative">
      {/* Header */}
      <div className="p-6 bg-[#064e3b] text-white flex items-center justify-between shadow-lg rounded-b-[32px] z-20">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 border border-white/10 transition-all active:scale-90">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t('qadah')}</h1>
            <p className="text-[10px] text-emerald-300/60 font-black uppercase tracking-widest">{monthName} {year}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => setShowRemindersModal(true)}
            className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 border border-white/10 transition-all active:scale-90 relative"
          >
            <i className="fas fa-bell text-xs"></i>
            {state.settings.qadaReminders.some(r => r.enabled) && (
              <span className="absolute top-2 right-2 w-2 h-2 bg-emerald-400 rounded-full border-2 border-[#064e3b]"></span>
            )}
          </button>
          <div className="bg-rose-500/20 px-4 py-2 rounded-2xl border border-rose-500/30 flex items-center gap-2">
             <span className="text-xs font-black text-rose-200">{totalMissedStats}</span>
             <span className="text-[8px] font-bold uppercase tracking-tighter text-rose-100/60">Pending</span>
          </div>
        </div>
      </div>

      {/* Calendar Controls */}
      <div className="p-6 flex items-center justify-between">
        <button onClick={prevMonth} className="w-12 h-12 flex items-center justify-center text-emerald-800 hover:bg-emerald-50 rounded-2xl transition-all active:scale-90">
          <i className="fas fa-chevron-left"></i>
        </button>
        <h2 className="text-lg font-black text-[#064e3b]">{monthName} {year}</h2>
        <button onClick={nextMonth} className="w-12 h-12 flex items-center justify-center text-emerald-800 hover:bg-emerald-50 rounded-2xl transition-all active:scale-90">
          <i className="fas fa-chevron-right"></i>
        </button>
      </div>

      {/* Calendar Grid */}
      <div className="px-6 pb-6">
        <div className="grid grid-cols-7 text-center mb-4">
          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
            <span key={d} className="text-[10px] font-black text-slate-400 tracking-widest">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-2">
          {days.map((dateStr, idx) => {
            if (!dateStr) return <div key={`empty-${idx}`} className="h-10" />;

            const summary = getDaySummary(dateStr);
            const missedCount = getMissedCount(dateStr);
            const dayNum = dateStr.split('-')[2];
            const isToday = dateStr === new Date().toISOString().split('T')[0];
            const isSelected = selectedDate === dateStr;

            return (
              <button
                key={dateStr}
                onClick={() => setSelectedDate(dateStr)}
                className={`h-12 rounded-2xl flex flex-col items-center justify-center relative transition-all active:scale-90 border-2 ${
                  isSelected ? 'border-emerald-600' : 'border-transparent'
                } ${
                  summary === 'completed' ? 'bg-emerald-100 text-emerald-800' :
                  summary === 'missed' ? 'bg-rose-100 text-rose-800' :
                  summary === 'excused' ? 'bg-pink-100 text-pink-800' : 'bg-white text-[#064e3b]'
                }`}
              >
                <span className={`text-xs font-black ${isToday ? 'underline decoration-2' : ''}`}>{parseInt(dayNum)}</span>
                {missedCount > 0 && (
                  <div className="absolute -top-1 -right-1 w-4 h-4 bg-rose-500 rounded-full flex items-center justify-center border-2 border-white">
                    <span className="text-[8px] text-white font-black">{missedCount}</span>
                  </div>
                )}
                {summary !== 'none' && summary !== 'missed' && <div className="w-1 h-1 rounded-full bg-current mt-1"></div>}
              </button>
            );
          })}
        </div>
      </div>

      {/* Selected Day Detail */}
      <div className="px-6 flex-1">
        {selectedDate && (
          <div className="bg-white rounded-[32px] p-6 shadow-xl shadow-emerald-900/5 border border-emerald-50 mb-8 animate-fade-up">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-sm font-black text-[#064e3b] uppercase tracking-widest">
                {new Date(selectedDate).toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'short' })}
              </h3>

              <div className="flex gap-2">
                <button 
                  onClick={() => handleBulkStatusChange(PrayerStatus.COMPLETED)}
                  className="px-3 py-1.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-emerald-900/10 active:scale-90 transition-all"
                >
                  <i className="fas fa-check-double mr-1"></i> {t('markAllCompleted')}
                </button>
                <button 
                  onClick={() => handleBulkStatusChange(PrayerStatus.MISSED)}
                  className="px-3 py-1.5 bg-rose-500 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-rose-900/10 active:scale-90 transition-all"
                >
                  <i className="fas fa-times-circle mr-1"></i> {t('markAllMissed')}
                </button>
              </div>
            </div>

            <div className={`space-y-3 ${animatingPrayer === 'bulk' ? 'animate-ripple-glow' : ''}`}>
              {PRAYERS.map(prayer => {
                const status = selectedDayLogs?.[prayer] || PrayerStatus.PENDING;
                const isAnimating = animatingPrayer === prayer;
                return (
                  <div key={prayer} className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50 border-rose-100' : 'bg-slate-50 border-slate-100'
                  } ${isAnimating ? 'animate-ripple-glow' : ''}`}>
                    <span className="capitalize font-bold text-sm">{t(prayer)}</span>
                    <div className="flex gap-2">
                       <button 
                        onClick={() => handleStatusChange(prayer, status === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${
                          status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white text-slate-300'
                        }`}
                       >
                         <i className="fas fa-check text-xs"></i>
                       </button>
                       <button 
                        onClick={() => handleStatusChange(prayer, status === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)}
                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${
                          status === PrayerStatus.MISSED ? 'bg-rose-500 text-white' : 'bg-white text-slate-300'
                        }`}
                       >
                         <i className="fas fa-xmark text-xs"></i>
                       </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Reminders Modal */}
      {showRemindersModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-[#064e3b]/40 backdrop-blur-sm animate-fade-up">
          <div className="bg-[#fdfbf7] w-full max-w-sm rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[85vh] border border-white">
            <div className="p-8 bg-[#064e3b] text-white flex justify-between items-center relative overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-10">
                <i className="fas fa-bell text-6xl"></i>
              </div>
              <div className="relative z-10">
                <h2 className="text-xl font-black tracking-tight">{t('qadaReminders')}</h2>
                <p className="text-[10px] text-emerald-200/60 uppercase font-black tracking-widest">{t('reminders')}</p>
              </div>
              <button 
                onClick={() => setShowRemindersModal(false)} 
                className="relative z-10 w-10 h-10 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-all active:scale-90"
              >
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="p-6 overflow-y-auto flex-1 space-y-4">
              {state.settings.qadaReminders.length === 0 ? (
                <div className="py-16 text-center text-slate-300">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6">
                    <i className="fas fa-bell-slash text-4xl opacity-20"></i>
                  </div>
                  <p className="text-sm font-bold uppercase tracking-widest">{t('noReminders') || 'No reminders set'}</p>
                </div>
              ) : (
                state.settings.qadaReminders.map(reminder => (
                  <div 
                    key={reminder.id} 
                    className={`p-5 rounded-[32px] border transition-all duration-300 flex flex-col gap-4 ${
                      reminder.enabled 
                      ? 'bg-white border-emerald-50 shadow-md shadow-emerald-900/5' 
                      : 'bg-slate-50 border-slate-100 opacity-60 grayscale'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${reminder.enabled ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-200 text-slate-400'}`}>
                           <i className="fas fa-clock text-xs"></i>
                        </div>
                        <div>
                          <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Scheduled Time</p>
                          <p className="text-sm font-black text-[#064e3b]">{reminder.time}</p>
                        </div>
                      </div>
                      <button 
                        onClick={() => toggleReminder(reminder.id)}
                        className={`w-14 h-7 rounded-full relative transition-all border-2 ${
                          reminder.enabled ? 'bg-emerald-600 border-emerald-600' : 'bg-slate-300 border-slate-300'
                        }`}
                      >
                        <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow-sm transition-all ${reminder.enabled ? 'left-8' : 'left-1'}`}></div>
                      </button>
                    </div>

                    <div className="flex items-center gap-3 pt-2 border-t border-slate-50">
                      <div className="flex-1 relative">
                        <input 
                          type="time" 
                          value={reminder.time}
                          onChange={(e) => updateReminderTime(reminder.id, e.target.value)}
                          className={`w-full bg-white border border-emerald-50 rounded-[20px] p-3 pl-10 font-black text-[#064e3b] outline-none shadow-sm transition-all focus:ring-4 focus:ring-emerald-500/10 appearance-none`}
                        />
                        <i className="fas fa-clock absolute left-4 top-1/2 -translate-y-1/2 text-emerald-800/40 pointer-events-none"></i>
                      </div>
                      <button 
                        onClick={() => removeReminder(reminder.id)} 
                        className="w-12 h-12 flex items-center justify-center text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"
                      >
                        <i className="fas fa-trash-can"></i>
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="p-8 bg-white border-t border-slate-50">
              <button 
                onClick={addReminder}
                className="w-full py-5 bg-[#064e3b] text-white rounded-[24px] font-black uppercase tracking-widest text-sm shadow-2xl shadow-emerald-900/10 active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                <i className="fas fa-plus-circle text-lg"></i> 
                <span>{t('addReminder')}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default QadahCalendar;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: AppState;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;

    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-600' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-emerald-100 text-teal-800', iconColor: 'text-teal-600' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-600' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-amber-50 to-amber-100 text-amber-900', iconColor: 'text-amber-600' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-800', iconColor: 'text-indigo-600' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-emerald-50 to-teal-50 text-emerald-900', iconColor: 'text-emerald-500' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-500' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;

    const timingsMinutes: { name: string; total: number; time: string }[] = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });

    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex: number;
    let isTomorrow = false;

    if (nextIndex === -1) {
      nextIndex = 0;
      prevIndex = timingsMinutes.length - 1;
      isTomorrow = true;
    } else {
      prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1;
    }

    const next = timingsMinutes[nextIndex];
    const prev = timingsMinutes[prevIndex];

    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;

    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));

    const hh = Math.floor(diff / 60);
    const mm = diff % 60;

    return {
      next,
      timeLeft: `${hh}h ${mm}m`,
      progress,
      activeName: prev.name,
      timingsMinutes
    };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="pb-24 animate-fade-up">
      {/* Daily Hadith Banner - Prominent Placement */}
      <div className="px-6 pt-6 mb-4">
        <div className="bg-[#fcfaf2] p-5 rounded-[32px] border border-emerald-50 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-3 opacity-[0.05] group-hover:scale-110 transition-transform">
            <i className="fas fa-quote-right text-5xl"></i>
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-3">
              <span className="bg-emerald-600/10 text-emerald-800 text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-widest border border-emerald-100">
                {t('hadithTitle')}
              </span>
              <div className="h-px flex-1 bg-emerald-100/50"></div>
            </div>
            <div className="space-y-3">
              <p className="text-emerald-900 arabic-font text-lg leading-relaxed text-right font-bold" dir="rtl">
                {dailyHadith.arabic}
              </p>
              <p className="text-emerald-950 font-medium leading-relaxed italic text-[11px] pl-3 border-l-2 border-emerald-200">
                "{dailyHadith[userLang]}"
              </p>
            </div>
            <div className="flex items-center justify-end text-[8px] font-black text-emerald-700/40 uppercase tracking-[0.2em] mt-3">
              {dailyHadith.reference}
            </div>
          </div>
        </div>
      </div>

      {/* Header */}
      <header className="relative bg-[#064e3b] text-white pt-10 pb-20 px-6 rounded-b-[40px] shadow-2xl overflow-hidden">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/5 rounded-full blur-3xl"></div>
        <div className="absolute top-20 -left-10 w-32 h-32 bg-emerald-400/10 rounded-full blur-2xl"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-md">
                <i className="fas fa-mosque text-emerald-300 text-xl"></i>
              </div>
              <div>
                <h2 className="text-[10px] text-emerald-200/60 uppercase tracking-[0.2em] font-bold">{t('welcome')}</h2>
                <h1 className="text-xl font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={toggleNotifications}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-emerald-500 shadow-lg shadow-emerald-500/20' : 'bg-white/10 hover:bg-white/20'}`}
              >
                <i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-xs`} title={t('notifications')}></i>
              </button>
              <button 
                onClick={onLogout} 
                className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-all border border-white/10"
              >
                <i className="fas fa-power-off text-sm text-rose-300"></i>
              </button>
            </div>
          </div>

          <div className="flex gap-4">
            <div className="flex-1 bg-white/5 backdrop-blur-md p-4 rounded-3xl border border-white/10">
              <span className="text-[10px] text-emerald-300/80 uppercase font-bold tracking-widest block mb-1">{t('dhikr')}</span>
              <span className="text-2xl font-black">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 bg-white/5 backdrop-blur-md p-4 rounded-3xl border border-white/10">
              <span className="text-[10px] text-emerald-300/80 uppercase font-bold tracking-widest block mb-1">{t('lastRead')}</span>
              <span className="text-sm font-bold truncate block">
                {state.quranProgress.surah || 'Not set'}
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Next Prayer Card */}
      <div className="px-6 -mt-10 mb-6">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden group">
          <div className="flex items-center justify-between mb-4">
            <div>
              <span className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.2em] block mb-1">{t('nextPrayer')}</span>
              <div className="flex items-center gap-3">
                <h2 className="text-3xl font-black text-[#064e3b] capitalize">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <div className="px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                  <span className="text-xs font-black text-emerald-600">{prayerTimingData?.next.time}</span>
                </div>
              </div>
            </div>
            <div className="text-right">
              <span className="text-2xl font-black text-emerald-500 drop-shadow-sm">{prayerTimingData?.timeLeft || '--:--'}</span>
              <span className="text-[9px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>

          <div className="mb-2">
            <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden p-0.5 border border-slate-50 shadow-inner">
              <div 
                className="bg-gradient-to-r from-emerald-400 via-emerald-500 to-emerald-600 h-full rounded-full transition-all duration-1000 ease-in-out shadow-[0_0_8px_rgba(16,185,129,0.3)]"
                style={{ width: `${prayerTimingData?.progress || 0}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Today's Fard Prayers Section */}
      <div className="px-6 mb-8">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden">
          <div className="flex items-center justify-between mb-5">
            <div className="flex items-center gap-2">
              <div className="w-2 h-6 bg-emerald-600 rounded-full"></div>
              <h3 className="text-sm font-black text-[#064e3b] uppercase tracking-widest">{t('todayPrayers')}</h3>
            </div>
            {state.isHaydNifas && (
              <span className="text-[9px] font-black px-3 py-1 bg-pink-50 text-pink-600 rounded-full border border-pink-100 uppercase tracking-tighter">
                {t('excused')} Mode
              </span>
            )}
          </div>

          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              const isAnimating = animatingPrayer === p;

              // Missed detection: If not completed and time has passed
              let isMissed = false;
              if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                const timing = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                if (timing && timing.total < currentTimeMinutes) {
                  isMissed = true;
                }
              }

              return (
                <button
                  key={p}
                  disabled={state.isHaydNifas}
                  onClick={() => handlePrayerToggle(p)}
                  className={`relative flex flex-col items-center p-3 rounded-2xl transition-all duration-300 border ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-50 border-emerald-100 text-emerald-700 shadow-sm shadow-emerald-900/5' 
                      : isMissed 
                        ? 'bg-rose-50 border-rose-100 text-rose-700 shadow-sm shadow-rose-900/5' 
                        : 'bg-slate-50 border-transparent text-slate-400'
                  } ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-50 grayscale cursor-not-allowed' : 'active:scale-90'}`}
                >
                  {isAnimating && (
                    <div className="absolute inset-0 pointer-events-none rounded-2xl animate-ripple-glow"></div>
                  )}

                  <span className="text-[8px] font-black uppercase tracking-tighter mb-2">{t(p).substring(0, 3)}</span>

                  <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-600 text-white' 
                      : isMissed 
                        ? 'bg-rose-500 text-white' 
                        : 'bg-white text-slate-200 shadow-inner'
                  }`}>
                    {status === PrayerStatus.COMPLETED ? (
                      <i className="fas fa-check text-[10px] animate-check-draw"></i>
                    ) : isMissed ? (
                      <i className="fas fa-exclamation text-[10px]"></i>
                    ) : (
                      <i className="fas fa-circle text-[6px]"></i>
                    )}
                  </div>

                  {state.isHaydNifas && (
                    <div className="mt-2 text-[7px] font-bold text-pink-400 uppercase tracking-tighter">
                      Excused
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Menu Items Grid */}
      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        {menuItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setCurrentView(item.id)}
            className={`flex flex-col items-center justify-center p-6 rounded-[28px] shadow-sm hover:shadow-xl transition-all active:scale-95 bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden`}
          >
            <div className="absolute -bottom-2 -right-2 opacity-[0.03] group-hover:scale-125 transition-transform duration-500">
               <i className={`fas ${item.icon} text-6xl`}></i>
            </div>
            <div className={`w-14 h-14 rounded-2xl ${item.iconColor} bg-white/80 shadow-inner flex items-center justify-center mb-4 transition-transform group-hover:scale-110`}>
              <i className={`fas ${item.icon} text-2xl`}></i>
            </div>
            <span className="text-xs font-extrabold text-center uppercase tracking-wider">{item.label}</span>
          </button>
        ))}
      </div>

      <div className="px-6">
        <div className="bg-gradient-to-br from-[#064e3b] to-[#042f24] p-6 rounded-[32px] text-white shadow-xl shadow-emerald-950/20 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-10">
            <i className="fas fa-star-and-crescent text-4xl"></i>
          </div>
          <div className="flex justify-between items-center mb-4">
            <div>
              <h3 className="text-emerald-200 text-[10px] uppercase font-black tracking-widest mb-1">{t('challenge')}</h3>
              <p className="text-sm font-bold">{state.dhikrChallenge.title}</p>
            </div>
            <div className="text-right">
              <span className="text-xl font-black text-emerald-400">
                {Math.round((state.dhikrChallenge.current / state.dhikrChallenge.target) * 100)}%
              </span>
            </div>
          </div>
          <div className="w-full bg-white/10 h-2.5 rounded-full overflow-hidden mb-3 border border-white/5">
            <div 
              className="bg-gradient-to-r from-emerald-400 to-teal-300 h-full transition-all duration-1000 ease-out rounded-full shadow-[0_0_10px_rgba(52,211,153,0.5)]"
              style={{ width: `${Math.min(100, (state.dhikrChallenge.current / state.dhikrChallenge.target) * 100)}%` }}
            ></div>
          </div>
          <div className="flex justify-between items-center text-[10px] text-emerald-200/70 font-bold uppercase">
             <span>Current Progress</span>
             <span className="text-white font-black">{state.dhikrChallenge.current} / {state.dhikrChallenge.target}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export type Language = 'en' | 'ml' | 'ta';

export enum PrayerStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  MISSED = 'missed',
  EXCUSED = 'excused'
}

export interface UserProfile {
  name: string;
  age: number;
  sex: 'male' | 'female';
  place: string;
  preferredLanguage: Language;
  isLoggedIn: boolean;
}

export interface PrayerLog {
  fajr: PrayerStatus;
  dhuhr: PrayerStatus;
  asr: PrayerStatus;
  maghrib: PrayerStatus;
  isha: PrayerStatus;
}

export interface FastingLog {
  status: 'none' | 'completed' | 'missed' | 'excused';
  type: 'ramadan' | 'sunnah';
}

export interface QuranProgress {
  surah: string;
  ayah: string;
  lastUpdated: string;
}

export interface DhikrChallenge {
  id: string;
  title: string;
  arabic: string;
  target: number;
  current: number;
  lastReset?: string;
}

export interface DhikrHistoryEntry {
  id: string;
  title: string;
  target: number;
  current: number;
  date: string;
}

export interface PrayerTimings {
  Fajr: string;
  Dhuhr: string;
  Asr: string;
  Maghrib: string;
  Isha: string;
  Sunrise: string;
}

export interface QadaReminder {
  id: string;
  time: string;
  enabled: boolean;
}

export interface AppState {
  profile: UserProfile | null;
  prayerLogs: Record<string, PrayerLog>;
  sunnahLogs: Record<string, string[]>;
  fastingLogs: Record<string, FastingLog>;
  quranProgress: QuranProgress;
  dhikrCount: number;
  activeChallenges: DhikrChallenge[];
  dhikrHistory: DhikrHistoryEntry[];
  isHaydNifas: boolean;
  haydStartDate: string | null;
  settings: {
    notificationsEnabled: boolean;
    locationEnabled: boolean;
    qadaReminders: QadaReminder[];
  };
  todayTimings: PrayerTimings | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';

const STORAGE_KEY = 'ibadathi_app_state_v4';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const initialState: AppState = {
  profile: null,
  prayerLogs: {},
  sunnahLogs: {},
  fastingLogs: {},
  quranProgress: { surah: '', ayah: '', lastUpdated: '' },
  dhikrCount: 0,
  activeChallenges: INITIAL_DHIKRS,
  dhikrHistory: [],
  isHaydNifas: false,
  haydStartDate: null,
  settings: {
    notificationsEnabled: false,
    locationEnabled: false,
    qadaReminders: []
  },
  todayTimings: null
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    state.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla'>(
    state.profile?.isLoggedIn ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  // Daily Reset for Dhikr
  useEffect(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = state.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      setState(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.activeChallenges]);

  // Fetch Prayer Timings
  useEffect(() => {
    if (state.profile?.isLoggedIn && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ 
              ...prev, 
              todayTimings: data.data.timings,
              settings: { ...prev.settings, locationEnabled: true }
            }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.profile?.isLoggedIn]);

  // Combined Notification Loop
  useEffect(() => {
    if (!state.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];

          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;

            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      for (const reminder of state.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;

          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, state.settings.notificationsEnabled, state.settings.qadaReminders, currentLanguage]);

  const handleLogin = (profile: UserProfile) => {
    setState(prev => ({ 
      ...prev, 
      profile: { ...profile, isLoggedIn: true, preferredLanguage: currentLanguage } 
    }));
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, profile: null, isLoggedIn: false }));
    setCurrentView('welcome');
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    setState(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING,
        dhuhr: PrayerStatus.PENDING,
        asr: PrayerStatus.PENDING,
        maghrib: PrayerStatus.PENDING,
        isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    setState(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    setState(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;

      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(),
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };

      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => 
          c.id === challengeId ? { ...c, current: 0 } : c
        )
      };
    });
  };

  const renderView = () => {
    if (currentView === 'welcome') {
      return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    }
    if (currentView === 'login') {
      return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} />;
    }
    if (!state.profile) return null;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={state} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={state} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={state} toggleHayd={toggleHayd} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={state} 
            updateProgress={updateChallengeProgress}
            archiveChallenge={archiveChallengeById}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return <QuranTracker state={state} onUpdate={(p) => setState(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={state} updateFasting={(d, l) => setState(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    setState(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!state.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      else alert("Please allow notifications in your browser settings.");
    } else setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  return (
    <div className="min-h-screen relative">
      <div className="islamic-pattern fixed inset-0 pointer-events-none"></div>
      <main className="relative z-10 max-w-md mx-auto min-h-screen bg-white shadow-xl overflow-x-hidden">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppState, DhikrChallenge } from '../types';

interface DhikrCounterProps {
  state: AppState;
  updateProgress: (id: string, delta: number) => void;
  archiveChallenge: (id: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const DhikrCounter: React.FC<DhikrCounterProps> = ({ state, updateProgress, archiveChallenge, setCurrentView, t }) => {
  const [activeChallengeId, setActiveChallengeId] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [justCompleted, setJustCompleted] = useState(false);

  const activeChallenge = state.activeChallenges.find(c => c.id === activeChallengeId);

  const handleIncrement = () => {
    if (!activeChallengeId || !activeChallenge) return;

    // Haptic Feedback
    if ('vibrate' in navigator) {
      navigator.vibrate(40);
    }

    if (activeChallenge.current < activeChallenge.target) {
      updateProgress(activeChallengeId, 1);

      // Check for completion
      if (activeChallenge.current + 1 === activeChallenge.target) {
        setJustCompleted(true);
        if ('vibrate' in navigator) {
          navigator.vibrate([100, 50, 100]);
        }
      }
    }
  };

  const handleArchive = () => {
    if (activeChallengeId) {
      archiveChallenge(activeChallengeId);
      setActiveChallengeId(null);
      setJustCompleted(false);
    }
  };

  if (showHistory) {
    return (
      <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up">
        <div className="p-6 flex items-center justify-between bg-[#064e3b] text-white">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(false)} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10 active:scale-90">
              <i className="fas fa-chevron-left text-xs"></i>
            </button>
            <h1 className="text-xl font-bold tracking-tight">{t('history')}</h1>
          </div>
        </div>
        <div className="p-6 flex-1 overflow-y-auto space-y-4">
          {state.dhikrHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-slate-300">
               <i className="fas fa-box-open text-5xl mb-4 opacity-20"></i>
               <p className="text-sm font-black uppercase tracking-widest">{t('noHistory')}</p>
            </div>
          ) : (
            state.dhikrHistory.map((entry) => {
              const percentage = Math.round((entry.current / entry.target) * 100);
              return (
                <div key={entry.id} className="bg-white p-5 rounded-[28px] border border-emerald-50 shadow-sm shadow-emerald-900/5">
                  <div className="flex justify-between items-start mb-2">
                    <div>
                      <h3 className="text-sm font-black text-[#064e3b]">{t(entry.title)}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                        {new Date(entry.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                      </p>
                    </div>
                    <span className="text-[10px] font-black text-emerald-700 bg-emerald-50 px-3 py-1 rounded-full">{percentage}%</span>
                  </div>
                  <div className="w-full bg-slate-50 h-1.5 rounded-full overflow-hidden">
                    <div className="bg-emerald-500 h-full transition-all" style={{ width: `${Math.min(100, percentage)}%` }}></div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    );
  }

  // Active Counting View
  if (activeChallengeId && activeChallenge) {
    const progress = Math.min(100, (activeChallenge.current / activeChallenge.target) * 100);
    const isCompleted = activeChallenge.current >= activeChallenge.target;

    return (
      <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up">
        <div className="p-6 flex items-center justify-between bg-[#064e3b] text-white">
          <div className="flex items-center gap-4">
            <button onClick={() => { setActiveChallengeId(null); setJustCompleted(false); }} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10 active:scale-90">
              <i className="fas fa-chevron-left text-xs"></i>
            </button>
            <h1 className="text-xl font-bold tracking-tight">{t(activeChallenge.title)}</h1>
          </div>
        </div>

        <div className="p-8 flex flex-col items-center flex-1 justify-between gap-8 py-12">
          <div className="text-center">
            <h2 className="text-emerald-800/40 text-[10px] uppercase font-black tracking-[0.4em] mb-4">Challenge Active</h2>
            <p className="arabic-font text-5xl text-[#064e3b] font-bold mb-2" dir="rtl">{activeChallenge.arabic}</p>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">{t(activeChallenge.title)}</p>
          </div>

          <div className="relative flex items-center justify-center">
             <div className="text-9xl font-black text-[#064e3b] tracking-tighter tabular-nums drop-shadow-sm opacity-10 absolute pointer-events-none select-none">
               {activeChallenge.current}
             </div>

             {/* Main Counter Button */}
             <button 
                onClick={handleIncrement}
                disabled={isCompleted}
                className={`relative w-64 h-64 group flex items-center justify-center rounded-full transition-all duration-150 transform ${isCompleted ? 'scale-90 grayscale opacity-50' : 'active:scale-90'}`}
             >
                <div className={`absolute inset-0 rounded-full blur-[40px] opacity-10 transition-opacity ${isCompleted ? 'bg-emerald-200' : 'bg-[#064e3b] group-active:opacity-30'}`}></div>
                <div className="absolute inset-0 bg-gradient-to-br from-emerald-500 to-[#064e3b] rounded-full shadow-2xl border-[10px] border-white/30 flex items-center justify-center overflow-hidden">
                   <div className="text-white text-7xl font-black drop-shadow-lg">
                      {activeChallenge.current}
                   </div>
                   {/* Visual Pulse for Click */}
                   {!isCompleted && <div className="absolute inset-0 bg-white/5 opacity-0 group-active:opacity-100 transition-opacity"></div>}
                </div>
             </button>
          </div>

          <div className="w-full max-w-sm space-y-6">
            <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 text-center relative overflow-hidden">
               {justCompleted && (
                 <div className="absolute inset-0 bg-emerald-600 flex flex-col items-center justify-center z-10 animate-fade-up">
                    <i className="fas fa-check-circle text-white text-4xl mb-3 animate-check-draw"></i>
                    <h3 className="text-white font-black uppercase text-sm tracking-widest">{t('challengeComplete')}</h3>
                    <button 
                      onClick={handleArchive}
                      className="mt-6 bg-white text-emerald-700 px-8 py-3 rounded-full font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95"
                    >
                      {t('completeAndArchive')}
                    </button>
                 </div>
               )}

               <div className="flex justify-between items-end mb-3 px-1">
                  <span className="text-[10px] text-emerald-800/40 font-black uppercase tracking-widest">Progress</span>
                  <span className="text-sm font-black text-[#064e3b]">{activeChallenge.current} / {activeChallenge.target}</span>
               </div>

               <div className="w-full bg-emerald-50 h-3 rounded-full overflow-hidden border border-emerald-100 mb-4">
                  <div 
                    className="bg-[#064e3b] h-full transition-all duration-300 ease-out"
                    style={{ width: `${progress}%` }}
                  ></div>
               </div>

               <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                 {isCompleted ? t('challengeComplete') : t('tapToCount')}
               </p>
            </div>

            <button 
              onClick={() => { setActiveChallengeId(null); setJustCompleted(false); }}
              className="w-full py-4 bg-slate-50 text-slate-400 rounded-2xl font-black text-[10px] uppercase tracking-widest border border-slate-100 hover:bg-slate-100 transition-all active:scale-95"
            >
              {t('back')} to Challenges
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Grid List View
  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up">
      <div className="p-6 flex items-center justify-between bg-[#064e3b] text-white">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10 active:scale-90">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h1 className="text-xl font-bold tracking-tight">{t('dhikrList')}</h1>
        </div>
        <button 
          onClick={() => setShowHistory(true)} 
          className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/10 active:scale-90"
        >
          <i className="fas fa-history text-xs"></i>
        </button>
      </div>

      <div className="p-6 flex-1 overflow-y-auto">
        <div className="grid grid-cols-1 gap-4 pb-8">
          {state.activeChallenges.map((challenge) => {
            const progress = Math.min(100, (challenge.current / challenge.target) * 100);
            const isCompleted = challenge.current >= challenge.target;

            return (
              <button 
                key={challenge.id}
                onClick={() => setActiveChallengeId(challenge.id)}
                className={`flex flex-col p-6 rounded-[32px] border transition-all text-left group relative overflow-hidden ${
                  isCompleted 
                    ? 'bg-emerald-50 border-emerald-100 opacity-80' 
                    : 'bg-white border-emerald-50 shadow-sm hover:shadow-xl hover:scale-[1.02] active:scale-95'
                }`}
              >
                {isCompleted && (
                  <div className="absolute top-4 right-4 text-emerald-600">
                    <i className="fas fa-check-circle text-lg"></i>
                  </div>
                )}

                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-sm font-black text-[#064e3b] uppercase tracking-wider mb-1">
                      {t(challenge.title)}
                    </h3>
                    <p className="arabic-font text-xl text-emerald-800 font-bold" dir="rtl">{challenge.arabic}</p>
                  </div>
                </div>

                <div className="mt-auto space-y-3">
                  <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest">
                    <span className={isCompleted ? 'text-emerald-600' : 'text-slate-400'}>
                      {isCompleted ? t('completed') : t('progress')}
                    </span>
                    <span className="text-emerald-800">{challenge.current} / {challenge.target}</span>
                  </div>
                  <div className="w-full bg-slate-50 h-2 rounded-full overflow-hidden border border-slate-100">
                    <div 
                      className={`h-full transition-all duration-1000 ${isCompleted ? 'bg-emerald-500' : 'bg-emerald-600'}`} 
                      style={{ width: `${progress}%` }}
                    ></div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>

        <div className="bg-[#064e3b]/5 p-8 rounded-[32px] text-center border border-emerald-50/50">
           <i className="fas fa-hand-holding-heart text-emerald-700/20 text-4xl mb-4"></i>
           <p className="text-[#064e3b]/60 text-xs italic leading-relaxed">
             "For without doubt in the remembrance of Allah do hearts find rest." (13:28)
           </p>
        </div>
      </div>
    </div>
  );
};

export default DhikrCounter;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';

const STORAGE_KEY = 'ibadathi_app_state_v4';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const initialState: AppState = {
  profile: null,
  prayerLogs: {},
  sunnahLogs: {},
  fastingLogs: {},
  quranProgress: { surah: '', ayah: '', lastUpdated: '' },
  dhikrCount: 0,
  activeChallenges: INITIAL_DHIKRS,
  dhikrHistory: [],
  isHaydNifas: false,
  haydStartDate: null,
  settings: {
    notificationsEnabled: false,
    locationEnabled: false,
    qadaReminders: []
  },
  todayTimings: null
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    state.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla'>(
    state.profile?.isLoggedIn ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  // Daily Reset for Dhikr
  useEffect(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = state.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      setState(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.activeChallenges]);

  // Fetch Prayer Timings
  useEffect(() => {
    if (state.profile?.isLoggedIn && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ 
              ...prev, 
              todayTimings: data.data.timings,
              settings: { ...prev.settings, locationEnabled: true }
            }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.profile?.isLoggedIn]);

  // Combined Notification Loop
  useEffect(() => {
    if (!state.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];

          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;

            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      for (const reminder of state.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;

          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, state.settings.notificationsEnabled, state.settings.qadaReminders, currentLanguage]);

  const handleLogin = (profile: UserProfile) => {
    setState(prev => ({ 
      ...prev, 
      profile: { ...profile, isLoggedIn: true, preferredLanguage: currentLanguage } 
    }));
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, profile: null, isLoggedIn: false }));
    setCurrentView('welcome');
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    setState(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING,
        dhuhr: PrayerStatus.PENDING,
        asr: PrayerStatus.PENDING,
        maghrib: PrayerStatus.PENDING,
        isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    setState(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    setState(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;

      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(),
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };

      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => 
          c.id === challengeId ? { ...c, current: 0 } : c
        )
      };
    });
  };

  // Fix: Added missing toggleHayd function for WomensSpace
  const toggleHayd = (active: boolean) => {
    setState(prev => ({
      ...prev,
      isHaydNifas: active,
      haydStartDate: active ? new Date().toISOString() : null
    }));
  };

  const renderView = () => {
    if (currentView === 'welcome') {
      return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    }
    if (currentView === 'login') {
      return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} />;
    }
    if (!state.profile) return null;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={state} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={state} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={state} toggleHayd={toggleHayd} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={state} 
            updateProgress={updateChallengeProgress}
            archiveChallenge={archiveChallengeById}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return <QuranTracker state={state} onUpdate={(p) => setState(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={state} updateFasting={(d, l) => setState(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    setState(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!state.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      else alert("Please allow notifications in your browser settings.");
    } else setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  return (
    <div className="min-h-screen relative">
      <div className="islamic-pattern fixed inset-0 pointer-events-none"></div>
      <main className="relative z-10 max-w-md mx-auto min-h-screen bg-white shadow-xl overflow-x-hidden">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: AppState;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;

    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-600' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-emerald-100 text-teal-800', iconColor: 'text-teal-600' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-600' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-amber-50 to-amber-100 text-amber-900', iconColor: 'text-amber-600' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-800', iconColor: 'text-indigo-600' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-emerald-50 to-teal-50 text-emerald-900', iconColor: 'text-emerald-500' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-500' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;

    const timingsMinutes: { name: string; total: number; time: string }[] = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });

    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex: number;
    let isTomorrow = false;

    if (nextIndex === -1) {
      nextIndex = 0;
      prevIndex = timingsMinutes.length - 1;
      isTomorrow = true;
    } else {
      prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1;
    }

    const next = timingsMinutes[nextIndex];
    const prev = timingsMinutes[prevIndex];

    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;

    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));

    const hh = Math.floor(diff / 60);
    const mm = diff % 60;

    return {
      next,
      timeLeft: `${hh}h ${mm}m`,
      progress,
      activeName: prev.name,
      timingsMinutes
    };
  }, [state.todayTimings, currentTimeMinutes]);

  // Fix: Access the first challenge as dhikrChallenge property doesn't exist on AppState
  const featuredChallenge = state.activeChallenges[0];

  return (
    <div className="pb-24 animate-fade-up">
      {/* Daily Hadith Banner - Prominent Placement */}
      <div className="px-6 pt-6 mb-4">
        <div className="bg-[#fcfaf2] p-5 rounded-[32px] border border-emerald-50 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-3 opacity-[0.05] group-hover:scale-110 transition-transform">
            <i className="fas fa-quote-right text-5xl"></i>
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-3">
              <span className="bg-emerald-600/10 text-emerald-800 text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-widest border border-emerald-100">
                {t('hadithTitle')}
              </span>
              <div className="h-px flex-1 bg-emerald-100/50"></div>
            </div>
            <div className="space-y-3">
              <p className="text-emerald-900 arabic-font text-lg leading-relaxed text-right font-bold" dir="rtl">
                {dailyHadith.arabic}
              </p>
              <p className="text-emerald-950 font-medium leading-relaxed italic text-[11px] pl-3 border-l-2 border-emerald-200">
                "{dailyHadith[userLang]}"
              </p>
            </div>
            <div className="flex items-center justify-end text-[8px] font-black text-emerald-700/40 uppercase tracking-[0.2em] mt-3">
              {dailyHadith.reference}
            </div>
          </div>
        </div>
      </div>

      {/* Header */}
      <header className="relative bg-[#064e3b] text-white pt-10 pb-20 px-6 rounded-b-[40px] shadow-2xl overflow-hidden">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/5 rounded-full blur-3xl"></div>
        <div className="absolute top-20 -left-10 w-32 h-32 bg-emerald-400/10 rounded-full blur-2xl"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-md">
                <i className="fas fa-mosque text-emerald-300 text-xl"></i>
              </div>
              <div>
                <h2 className="text-[10px] text-emerald-200/60 uppercase tracking-[0.2em] font-bold">{t('welcome')}</h2>
                <h1 className="text-xl font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={toggleNotifications}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-emerald-500 shadow-lg shadow-emerald-500/20' : 'bg-white/10 hover:bg-white/20'}`}
              >
                <i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-xs`} title={t('notifications')}></i>
              </button>
              <button 
                onClick={onLogout} 
                className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-all border border-white/10"
              >
                <i className="fas fa-power-off text-sm text-rose-300"></i>
              </button>
            </div>
          </div>

          <div className="flex gap-4">
            <div className="flex-1 bg-white/5 backdrop-blur-md p-4 rounded-3xl border border-white/10">
              <span className="text-[10px] text-emerald-300/80 uppercase font-bold tracking-widest block mb-1">{t('dhikr')}</span>
              <span className="text-2xl font-black">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 bg-white/5 backdrop-blur-md p-4 rounded-3xl border border-white/10">
              <span className="text-[10px] text-emerald-300/80 uppercase font-bold tracking-widest block mb-1">{t('lastRead')}</span>
              <span className="text-sm font-bold truncate block">
                {state.quranProgress.surah || 'Not set'}
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Next Prayer Card */}
      <div className="px-6 -mt-10 mb-6">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden group">
          <div className="flex items-center justify-between mb-4">
            <div>
              <span className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.2em] block mb-1">{t('nextPrayer')}</span>
              <div className="flex items-center gap-3">
                <h2 className="text-3xl font-black text-[#064e3b] capitalize">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <div className="px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                  <span className="text-xs font-black text-emerald-600">{prayerTimingData?.next.time}</span>
                </div>
              </div>
            </div>
            <div className="text-right">
              <span className="text-2xl font-black text-emerald-500 drop-shadow-sm">{prayerTimingData?.timeLeft || '--:--'}</span>
              <span className="text-[9px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>

          <div className="mb-2">
            <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden p-0.5 border border-slate-50 shadow-inner">
              <div 
                className="bg-gradient-to-r from-emerald-400 via-emerald-500 to-emerald-600 h-full rounded-full transition-all duration-1000 ease-in-out shadow-[0_0_8px_rgba(16,185,129,0.3)]"
                style={{ width: `${prayerTimingData?.progress || 0}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Today's Fard Prayers Section */}
      <div className="px-6 mb-8">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden">
          <div className="flex items-center justify-between mb-5">
            <div className="flex items-center gap-2">
              <div className="w-2 h-6 bg-emerald-600 rounded-full"></div>
              <h3 className="text-sm font-black text-[#064e3b] uppercase tracking-widest">{t('todayPrayers')}</h3>
            </div>
            {state.isHaydNifas && (
              <span className="text-[9px] font-black px-3 py-1 bg-pink-50 text-pink-600 rounded-full border border-pink-100 uppercase tracking-tighter">
                {t('excused')} Mode
              </span>
            )}
          </div>

          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              const isAnimating = animatingPrayer === p;

              // Missed detection: If not completed and time has passed
              let isMissed = false;
              if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                const timing = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                if (timing && timing.total < currentTimeMinutes) {
                  isMissed = true;
                }
              }

              return (
                <button
                  key={p}
                  disabled={state.isHaydNifas}
                  onClick={() => handlePrayerToggle(p)}
                  className={`relative flex flex-col items-center p-3 rounded-2xl transition-all duration-300 border ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-50 border-emerald-100 text-emerald-700 shadow-sm shadow-emerald-900/5' 
                      : isMissed 
                        ? 'bg-rose-50 border-rose-100 text-rose-700 shadow-sm shadow-rose-900/5' 
                        : 'bg-slate-50 border-transparent text-slate-400'
                  } ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-50 grayscale cursor-not-allowed' : 'active:scale-90'}`}
                >
                  {isAnimating && (
                    <div className="absolute inset-0 pointer-events-none rounded-2xl animate-ripple-glow"></div>
                  )}

                  <span className="text-[8px] font-black uppercase tracking-tighter mb-2">{t(p).substring(0, 3)}</span>

                  <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-600 text-white' 
                      : isMissed 
                        ? 'bg-rose-500 text-white' 
                        : 'bg-white text-slate-200 shadow-inner'
                  }`}>
                    {status === PrayerStatus.COMPLETED ? (
                      <i className="fas fa-check text-[10px] animate-check-draw"></i>
                    ) : isMissed ? (
                      <i className="fas fa-exclamation text-[10px]"></i>
                    ) : (
                      <i className="fas fa-circle text-[6px]"></i>
                    )}
                  </div>

                  {state.isHaydNifas && (
                    <div className="mt-2 text-[7px] font-bold text-pink-400 uppercase tracking-tighter">
                      Excused
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Menu Items Grid */}
      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        {menuItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setCurrentView(item.id)}
            className={`flex flex-col items-center justify-center p-6 rounded-[28px] shadow-sm hover:shadow-xl transition-all active:scale-95 bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden`}
