import React, { useState, useMemo } from 'react';
import { AppState, PrayerStatus, QadaReminder } from '../types';
import { PRAYERS } from '../constants';

interface QadahCalendarProps {
  state: AppState;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  updateReminders: (reminders: QadaReminder[]) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QadahCalendar: React.FC<QadahCalendarProps> = ({ state, updatePrayerStatus, updateReminders, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(new Date().toISOString().split('T')[0]);
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [showRemindersModal, setShowRemindersModal] = useState(false);

  const month = viewDate.getMonth();
  const year = viewDate.getFullYear();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const days = useMemo(() => {
    const arr = [];
    for (let i = 0; i < firstDayOfMonth; i++) {
      arr.push(null);
    }
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      arr.push(dateStr);
    }
    return arr;
  }, [month, year]);

  const getDaySummary = (dateStr: string) => {
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 'none';

    const values = Object.values(logs);
    if (values.every(v => v === PrayerStatus.EXCUSED)) return 'excused';
    if (values.every(v => v === PrayerStatus.COMPLETED || v === PrayerStatus.EXCUSED)) return 'completed';
    if (values.some(v => v === PrayerStatus.MISSED)) return 'missed';
    return 'pending';
  };

  const getMissedCount = (dateStr: string) => {
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 0;
    return PRAYERS.filter(p => logs[p] === PrayerStatus.MISSED).length;
  };

  const nextMonth = () => setViewDate(new Date(year, month + 1, 1));
  const prevMonth = () => setViewDate(new Date(year, month - 1, 1));

  const monthName = viewDate.toLocaleString(state.profile?.preferredLanguage || 'en', { month: 'long' });

  const totalMissedStats = useMemo(() => {
    let missed = 0;
    Object.values(state.prayerLogs).forEach(day => {
      PRAYERS.forEach(p => {
        if (day[p] === PrayerStatus.MISSED) missed++;
      });
    });
    return missed;
  }, [state.prayerLogs]);

  const selectedDayLogs = selectedDate ? (state.prayerLogs[selectedDate] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  }) : null;

  const handleStatusChange = (prayer: string, status: PrayerStatus) => {
    if (selectedDate) {
      if (status === PrayerStatus.COMPLETED) {
        setAnimatingPrayer(prayer);
        setTimeout(() => setAnimatingPrayer(null), 800);
      }
      updatePrayerStatus(selectedDate, prayer as any, status);
    }
  };

  const handleBulkStatusChange = (status: PrayerStatus) => {
    if (selectedDate) {
      PRAYERS.forEach(prayer => {
        updatePrayerStatus(selectedDate, prayer, status);
      });
      if (status === PrayerStatus.COMPLETED) {
         setAnimatingPrayer('bulk');
         setTimeout(() => setAnimatingPrayer(null), 1000);
      }
    }
  };

  const addReminder = () => {
    const newReminders = [...state.settings.qadaReminders, {
      id: Date.now().toString(),
      time: '09:00',
      enabled: true
    }];
    updateReminders(newReminders);
  };

  const removeReminder = (id: string) => {
    const newReminders = state.settings.qadaReminders.filter(r => r.id !== id);
    updateReminders(newReminders);
  };

  const updateReminderTime = (id: string, time: string) => {
    const newReminders = state.settings.qadaReminders.map(r => r.id === id ? { ...r, time } : r);
    updateReminders(newReminders);
  };

  const toggleReminder = (id: string) => {
    const newReminders = state.settings.qadaReminders.map(r => r.id === id ? { ...r, enabled: !r.enabled } : r);
    updateReminders(newReminders);
  };

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up relative">
      {/* Premium Header */}
      <div className="p-8 pb-10 bg-[#064e3b] text-white flex items-center justify-between shadow-2xl rounded-b-[48px] z-20 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-5 rotate-12">
           <i className="fas fa-kaaba text-9xl"></i>
        </div>
        <div className="flex items-center gap-5 relative z-10">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-[20px] hover:bg-white/20 border border-white/10 transition-all active:scale-90 rtl:rotate-180 shadow-lg">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-2xl font-black tracking-tight">{t('qadah')}</h1>
            <p className="text-[10px] text-emerald-300 font-black uppercase tracking-[0.3em]">{monthName} {year}</p>
          </div>
        </div>
        <div className="flex gap-3 relative z-10">
          <button 
            onClick={() => setShowRemindersModal(true)}
            className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-[20px] hover:bg-white/20 border border-white/10 transition-all active:scale-90 relative shadow-lg"
          >
            <i className="fas fa-bell text-sm"></i>
            {state.settings.qadaReminders.some(r => r.enabled) && (
              <span className="absolute top-3 right-3 w-2.5 h-2.5 bg-emerald-400 rounded-full border-2 border-[#064e3b] animate-pulse"></span>
            )}
          </button>
          <div className="bg-rose-500/20 px-4 py-2 rounded-2xl border border-rose-500/30 flex items-center gap-3 backdrop-blur-sm">
             <span className="text-sm font-black text-rose-100">{totalMissedStats}</span>
             <span className="text-[9px] font-black uppercase tracking-tighter text-rose-200/60">Fails</span>
          </div>
        </div>
      </div>

      {/* Calendar Navigation */}
      <div className="px-8 pt-10 flex items-center justify-between mb-6">
        <button onClick={prevMonth} className="w-14 h-14 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-[24px] transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
          <i className="fas fa-chevron-left text-sm"></i>
        </button>
        <h2 className="text-xl font-black text-[#064e3b] tracking-tight">{monthName} {year}</h2>
        <button onClick={nextMonth} className="w-14 h-14 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-[24px] transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
          <i className="fas fa-chevron-right text-sm"></i>
        </button>
      </div>

      {/* Calendar Grid - Spirits are higher here */}
      <div className="px-8 pb-8">
        <div className="grid grid-cols-7 text-center mb-6">
          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
            <span key={d} className="text-[10px] font-black text-slate-300 tracking-[0.3em]">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-3">
          {days.map((dateStr, idx) => {
            if (!dateStr) return <div key={`empty-${idx}`} className="h-12" />;

            const summary = getDaySummary(dateStr);
            const missedCount = getMissedCount(dateStr);
            const dayNum = dateStr.split('-')[2];
            const isToday = dateStr === new Date().toISOString().split('T')[0];
            const isSelected = selectedDate === dateStr;

            return (
              <button
                key={dateStr}
                onClick={() => setSelectedDate(dateStr)}
                className={`h-14 rounded-[20px] flex flex-col items-center justify-center relative transition-all active:scale-90 border-2 ${
                  isSelected ? 'border-emerald-600 shadow-xl shadow-emerald-900/10' : 'border-transparent'
                } ${
                  summary === 'completed' ? 'bg-emerald-50 text-emerald-800' :
                  summary === 'missed' ? 'bg-rose-50 text-rose-800' :
                  summary === 'excused' ? 'bg-pink-50 text-pink-700' : 'bg-white shadow-sm text-slate-400'
                }`}
              >
                <span className={`text-sm font-black ${isToday ? 'text-emerald-600 underline decoration-2 underline-offset-4' : (isSelected ? 'text-emerald-900' : '')}`}>
                  {parseInt(dayNum)}
                </span>
                {missedCount > 0 && (
                  <div className="absolute -top-1.5 -right-1.5 w-5 h-5 bg-rose-500 rounded-full flex items-center justify-center border-2 border-white shadow-lg">
                    <span className="text-[9px] text-white font-black">{missedCount}</span>
                  </div>
                )}
                {summary !== 'none' && summary !== 'missed' && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500/40 mt-1"></div>}
              </button>
            );
          })}
        </div>
      </div>

      {/* Day Details with Bulk Actions */}
      <div className="px-8 flex-1 pb-10">
        {selectedDate && (
          <div className="bg-white rounded-[40px] p-8 shadow-2xl shadow-emerald-900/5 border border-emerald-50/50 mb-8 animate-fade-up">
            <div className="flex flex-col gap-6 mb-8">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.4em] mb-1">Journal Entry</p>
                  <h3 className="text-lg font-black text-[#064e3b]">
                    {new Date(selectedDate).toLocaleDateString(state.profile?.preferredLanguage, { weekday: 'long', day: 'numeric', month: 'short' })}
                  </h3>
                </div>

                <div className="flex gap-3">
                  <button 
                    onClick={() => handleBulkStatusChange(PrayerStatus.COMPLETED)}
                    className="w-12 h-12 bg-emerald-50 text-emerald-700 rounded-2xl flex items-center justify-center shadow-sm border border-emerald-100 active:scale-90 transition-all group"
                    title={t('markAllCompleted')}
                  >
                    <i className="fas fa-check-double text-sm group-hover:scale-110"></i>
                  </button>
                  <button 
                    onClick={() => handleBulkStatusChange(PrayerStatus.MISSED)}
                    className="w-12 h-12 bg-rose-50 text-rose-700 rounded-2xl flex items-center justify-center shadow-sm border border-rose-100 active:scale-90 transition-all group"
                    title={t('markAllMissed')}
                  >
                    <i className="fas fa-times-circle text-sm group-hover:scale-110"></i>
                  </button>
                </div>
              </div>
            </div>

            <div className={`space-y-4 ${animatingPrayer === 'bulk' ? 'animate-ripple-glow' : ''}`}>
              {PRAYERS.map(prayer => {
                const status = selectedDayLogs?.[prayer] || PrayerStatus.PENDING;
                const isAnimating = animatingPrayer === prayer;
                return (
                  <div key={prayer} className={`flex items-center justify-between p-5 rounded-[24px] border transition-all duration-300 ${
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50/50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50/50 border-rose-100' : 'bg-slate-50/50 border-slate-100'
                  } ${isAnimating ? 'animate-ripple-glow scale-[1.02]' : ''}`}>
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${
                        status === PrayerStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' :
                        status === PrayerStatus.MISSED ? 'bg-rose-100 text-rose-700' : 'bg-white text-slate-300'
                      }`}>
                        <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check' : (status === PrayerStatus.MISSED ? 'fa-xmark' : 'fa-clock')} text-xs`}></i>
                      </div>
                      <span className="capitalize font-black text-sm text-[#064e3b] tracking-wide">{t(prayer)}</span>
                    </div>
                    <div className="flex gap-3">
                       <button 
                        onClick={() => handleStatusChange(prayer, status === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                        className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${
                          status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white text-slate-200 border border-slate-100'
                        }`}
                       >
                         <i className="fas fa-check text-xs"></i>
                       </button>
                       <button 
                        onClick={() => handleStatusChange(prayer, status === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)}
                        className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${
                          status === PrayerStatus.MISSED ? 'bg-rose-500 text-white shadow-lg' : 'bg-white text-slate-200 border border-slate-100'
                        }`}
                       >
                         <i className="fas fa-times text-xs"></i>
                       </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Modern Reminders Modal */}
      {showRemindersModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-[#064e3b]/60 backdrop-blur-xl animate-fade-up">
          <div className="bg-[#fdfbf7] w-full max-w-sm rounded-[48px] shadow-3xl overflow-hidden flex flex-col max-h-[85vh] border border-white/50 relative">
            <div className="absolute top-[-10%] left-[-10%] w-48 h-48 bg-emerald-600/10 rounded-full blur-3xl"></div>

            <div className="p-10 pb-8 bg-[#064e3b] text-white flex justify-between items-center relative overflow-hidden">
              <div className="relative z-10">
                <p className="text-[10px] text-emerald-200/60 uppercase font-black tracking-[0.4em] mb-1">{t('reminders')}</p>
                <h2 className="text-2xl font-black tracking-tight">{t('qadaReminders')}</h2>
              </div>
              <button 
                onClick={() => setShowRemindersModal(false)} 
                className="relative z-10 w-12 h-12 bg-white/10 rounded-[20px] flex items-center justify-center hover:bg-white/20 transition-all active:scale-90 border border-white/10 shadow-lg"
              >
                <i className="fas fa-times text-sm"></i>
              </button>
            </div>

            <div className="p-8 overflow-y-auto flex-1 space-y-6 relative z-10">
              {state.settings.qadaReminders.length === 0 ? (
                <div className="py-24 text-center">
                  <div className="w-24 h-24 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
                    <i className="fas fa-bell-slash text-5xl text-emerald-900/10"></i>
                  </div>
                  <p className="text-xs font-black uppercase tracking-[0.3em] text-slate-300">Quiet Time</p>
                  <p className="text-slate-400 text-xs mt-3 px-10 leading-relaxed font-semibold">Start your journey by adding a daily makeup prayer reminder.</p>
                </div>
              ) : (
                state.settings.qadaReminders.map(reminder => (
                  <div 
                    key={reminder.id} 
                    className={`p-6 rounded-[32px] border transition-all duration-500 group relative ${
                      reminder.enabled 
                      ? 'bg-white border-emerald-50 shadow-xl shadow-emerald-900/5' 
                      : 'bg-slate-50/50 border-slate-100 opacity-60 grayscale'
                    }`}
                  >
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-4">
                        <div className={`w-12 h-12 rounded-[20px] flex items-center justify-center shadow-inner transition-colors ${reminder.enabled ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-200 text-slate-400'}`}>
                           <i className="fas fa-clock-rotate-left text-sm"></i>
                        </div>
                        <div>
                          <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-300 mb-1">Alert Time</p>
                          <p className="text-xl font-black text-[#064e3b]">{reminder.time}</p>
                        </div>
                      </div>

                      {/* Premium Toggle Switch */}
                      <button 
                        onClick={() => toggleReminder(reminder.id)}
                        className={`w-16 h-9 rounded-full relative transition-all duration-500 border-2 ${
                          reminder.enabled ? 'bg-emerald-600 border-emerald-600 shadow-lg shadow-emerald-900/10' : 'bg-slate-300 border-slate-300'
                        }`}
                      >
                        <div className={`absolute top-1 w-6 h-6 rounded-full bg-white shadow-xl transition-all duration-500 transform ${reminder.enabled ? 'ltr:translate-x-8 rtl:-translate-x-8' : 'translate-x-1'}`}></div>
                      </button>
                    </div>

                    <div className="flex items-center gap-4 pt-5 border-t border-slate-50">
                      <div className="flex-1 relative group">
                        <input 
                          type="time" 
                          value={reminder.time}
                          onChange={(e) => updateReminderTime(reminder.id, e.target.value)}
                          className="w-full bg-slate-50/80 border border-transparent rounded-[20px] p-4 pl-12 font-black text-[#064e3b] outline-none shadow-inner transition-all focus:bg-white focus:border-emerald-200 focus:ring-4 focus:ring-emerald-500/5 appearance-none cursor-pointer"
                        />
                        <i className="fas fa-edit absolute ltr:left-5 rtl:right-5 top-1/2 -translate-y-1/2 text-emerald-800/30 pointer-events-none group-focus-within:text-emerald-600 transition-colors"></i>
                      </div>
                      <button 
                        onClick={() => removeReminder(reminder.id)} 
                        className="w-14 h-14 flex items-center justify-center text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-[22px] transition-all bg-white shadow-sm border border-slate-50"
                      >
                        <i className="fas fa-trash-can text-sm"></i>
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="p-10 pt-4 bg-white/50 backdrop-blur-md">
              <button 
                onClick={addReminder}
                className="w-full py-6 bg-[#064e3b] text-white rounded-[28px] font-black uppercase tracking-[0.2em] text-sm shadow-2xl shadow-emerald-900/20 active:scale-95 transition-all flex items-center justify-center gap-4 hover:bg-emerald-900 group"
              >
                <i className="fas fa-plus-circle text-xl group-hover:rotate-90 transition-transform"></i> 
                <span>{t('addReminder')}</span>
              </button>
              <p className="mt-6 text-[10px] text-center text-slate-400 font-bold uppercase tracking-[0.2em] opacity-60">Consistency is Key to Faith</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default QadahCalendar;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';

const STORAGE_KEY = 'ibadathi_app_state_v4';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const initialState: AppState = {
  profile: null,
  prayerLogs: {},
  sunnahLogs: {},
  fastingLogs: {},
  quranProgress: { surah: '', ayah: '', lastUpdated: '' },
  dhikrCount: 0,
  activeChallenges: INITIAL_DHIKRS,
  dhikrHistory: [],
  isHaydNifas: false,
  haydStartDate: null,
  settings: {
    notificationsEnabled: false,
    locationEnabled: false,
    qadaReminders: []
  },
  todayTimings: null
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    state.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla'>(
    state.profile?.isLoggedIn ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  // Daily Reset for Dhikr
  useEffect(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = state.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      setState(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.activeChallenges]);

  // Fetch Prayer Timings
  useEffect(() => {
    if (state.profile?.isLoggedIn && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ 
              ...prev, 
              todayTimings: data.data.timings,
              settings: { ...prev.settings, locationEnabled: true }
            }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.profile?.isLoggedIn]);

  // Combined Notification Loop
  useEffect(() => {
    if (!state.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];

          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;

            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      for (const reminder of state.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;

          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, state.settings.notificationsEnabled, state.settings.qadaReminders, currentLanguage]);

  const handleLogin = (profile: UserProfile) => {
    setState(prev => ({ 
      ...prev, 
      profile: { ...profile, isLoggedIn: true, preferredLanguage: currentLanguage } 
    }));
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, profile: null, isLoggedIn: false }));
    setCurrentView('welcome');
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    setState(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING,
        dhuhr: PrayerStatus.PENDING,
        asr: PrayerStatus.PENDING,
        maghrib: PrayerStatus.PENDING,
        isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    setState(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    setState(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;

      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(),
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };

      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => 
          c.id === challengeId ? { ...c, current: 0 } : c
        )
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    setState(prev => ({
      ...prev,
      isHaydNifas: active,
      haydStartDate: active ? new Date().toISOString() : null
    }));
  };

  const renderView = () => {
    if (currentView === 'welcome') {
      return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    }
    if (currentView === 'login') {
      return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} />;
    }
    if (!state.profile) return null;

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={state} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={state} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={state} toggleHayd={toggleHayd} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={state} 
            updateProgress={updateChallengeProgress}
            archiveChallenge={archiveChallengeById}
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return <QuranTracker state={state} onUpdate={(p) => setState(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={state} updateFasting={(d, l) => setState(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={state} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    setState(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!state.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      else alert("Please allow notifications in your browser settings.");
    } else setState(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  return (
    <div className={`min-h-screen relative ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <div className="islamic-pattern fixed inset-0 pointer-events-none"></div>
      <main className="relative z-10 max-w-md mx-auto min-h-screen bg-white shadow-xl overflow-x-hidden border-x border-emerald-50/50">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: AppState;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;

    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-700' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-700' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-amber-50 to-amber-100 text-amber-900', iconColor: 'text-amber-700' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-blue-50 to-blue-100 text-blue-900', iconColor: 'text-blue-700' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-900', iconColor: 'text-indigo-700' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-green-50 to-green-100 text-green-900', iconColor: 'text-green-700' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-600' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;

    const timingsMinutes: { name: string; total: number; time: string }[] = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });

    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex: number;
    let isTomorrow = false;

    if (nextIndex === -1) {
      nextIndex = 0;
      prevIndex = timingsMinutes.length - 1;
      isTomorrow = true;
    } else {
      prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1;
    }

    const next = timingsMinutes[nextIndex];
    const prev = timingsMinutes[prevIndex];

    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;

    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));

    const hh = Math.floor(diff / 60);
    const mm = diff % 60;

    return {
      next,
      timeLeft: `${hh}h ${mm}m`,
      progress,
      activeName: prev.name,
      timingsMinutes
    };
  }, [state.todayTimings, currentTimeMinutes]);

  const featuredChallenge = state.activeChallenges[0];

  return (
    <div className="pb-24 view-transition">
      {/* Daily Hadith Banner */}
      <div className="px-6 pt-6 mb-4">
        <div className="bg-white p-6 rounded-[32px] border border-emerald-50 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-[0.03] pointer-events-none rtl:left-0 rtl:right-auto rtl:-scale-x-100">
            <i className="fas fa-quote-right text-6xl"></i>
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-4">
              <span className="bg-emerald-600/10 text-emerald-800 text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-emerald-100/50">
                {t('hadithTitle')}
              </span>
              <div className="h-px flex-1 bg-emerald-100/30"></div>
            </div>
            <div className="space-y-4">
              <p className="text-emerald-900 arabic-font text-xl leading-relaxed text-right font-medium" dir="rtl">
                {dailyHadith.arabic}
              </p>
              {userLang !== 'ar' && (
                <p className="text-slate-600 font-medium leading-relaxed italic text-xs pl-3 border-l-2 border-gold-classic/40 rtl:pl-0 rtl:pr-3 rtl:border-l-0 rtl:border-r-2">
                  "{dailyHadith[userLang]}"
                </p>
              )}
            </div>
            <div className="flex items-center justify-end mt-4">
              <span className="text-[9px] font-semibold text-slate-400 uppercase tracking-widest">
                {dailyHadith.reference}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Header Profile Section */}
      <header className="relative bg-emerald-900 text-white pt-10 pb-20 px-6 rounded-b-[48px] shadow-2xl overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-[80px] -mr-32 -mt-32"></div>
        <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-400/5 rounded-full blur-[60px] -ml-24 -mb-24"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-lg">
                <i className="fas fa-user-circle text-emerald-200 text-2xl"></i>
              </div>
              <div className="ltr:text-left rtl:text-right">
                <h2 className="text-[10px] text-emerald-300/80 uppercase tracking-[0.2em] font-bold mb-1">{t('welcome')}</h2>
                <h1 className="text-2xl font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-3">
              <button 
                onClick={toggleNotifications}
                className={`w-11 h-11 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-gold-classic text-white shadow-lg shadow-gold-classic/20' : 'bg-white/10 hover:bg-white/20'}`}
              >
                <i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-sm`}></i>
              </button>
              <button 
                onClick={onLogout} 
                className="w-11 h-11 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-all border border-white/10"
              >
                <i className="fas fa-power-off text-sm text-rose-300"></i>
              </button>
            </div>
          </div>

          <div className="flex gap-4">
            <div className="flex-1 glass-card bg-white/5 p-4 rounded-3xl ltr:text-left rtl:text-right">
              <span className="text-[10px] text-emerald-300/60 uppercase font-black tracking-widest block mb-1">{t('dhikr')}</span>
              <span className="text-2xl font-black tabular-nums">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 glass-card bg-white/5 p-4 rounded-3xl ltr:text-left rtl:text-right">
              <span className="text-[10px] text-emerald-300/60 uppercase font-black tracking-widest block mb-1">{t('lastRead')}</span>
              <span className="text-sm font-bold truncate block mt-1">
                {state.quranProgress.surah || '---'}
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Next Prayer Floating Card */}
      <div className="px-6 -mt-10 mb-8">
        <div className="bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden">
          <div className="flex items-center justify-between mb-5">
            <div className="ltr:text-left rtl:text-right">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('nextPrayer')}</span>
              <div className="flex items-center gap-4">
                <h2 className="text-3xl font-black text-emerald-900 capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <div className="px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                  <span className="text-xs font-bold text-emerald-700 tabular-nums">{prayerTimingData?.next.time}</span>
                </div>
              </div>
            </div>
            <div className="ltr:text-right rtl:text-left">
              <span className="text-2xl font-black text-gold-classic tabular-nums">{prayerTimingData?.timeLeft || '--:--'}</span>
              <span className="text-[9px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>

          <div className="mb-2">
            <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden p-0.5 shadow-inner">
              <div 
                className="bg-emerald-600 h-full rounded-full transition-all duration-1000 ease-in-out ltr:origin-left rtl:origin-right"
                style={{ width: `${prayerTimingData?.progress || 0}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Daily Prayers Quick-Toggle Section */}
      <div className="px-6 mb-8">
        <div className="bg-white p-6 rounded-[36px] shadow-sm border border-emerald-50/50">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-6 bg-gold-classic rounded-full"></div>
              <h3 className="text-sm font-black text-emerald-900 uppercase tracking-widest">{t('todayPrayers')}</h3>
            </div>
            {state.isHaydNifas && (
              <span className="text-[10px] font-bold px-3 py-1 bg-rose-50 text-rose-600 rounded-full border border-rose-100 uppercase tracking-tighter">
                {t('excused')}
              </span>
            )}
          </div>

          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              const isAnimating = animatingPrayer === p;

              let isMissed = false;
              if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                const timing = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                if (timing && timing.total < currentTimeMinutes) {
                  isMissed = true;
                }
              }

              return (
                <button
                  key={p}
                  disabled={state.isHaydNifas}
                  onClick={() => handlePrayerToggle(p)}
                  className={`relative flex flex-col items-center p-3 rounded-2xl transition-all duration-300 border active-scale ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-50 border-emerald-100 text-emerald-800' 
                      : isMissed 
                        ? 'bg-rose-50 border-rose-100 text-rose-700' 
                        : 'bg-slate-50 border-transparent text-slate-400'
                  } ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-40 grayscale cursor-not-allowed' : ''}`}
                >
                  {isAnimating && (
                    <div className="absolute inset-0 pointer-events-none rounded-2xl animate-ripple-glow"></div>
                  )}

                  <span className="text-[9px] font-bold uppercase tracking-tighter mb-3">{t(p).substring(0, 3)}</span>

                  <div className={`w-9 h-9 rounded-full flex items-center justify-center transition-all ${
                    status === PrayerStatus.COMPLETED 
                      ? 'bg-emerald-600 text-white shadow-md' 
                      : isMissed 
                        ? 'bg-rose-500 text-white shadow-md' 
                        : 'bg-white text-slate-200 border border-slate-100'
                  }`}>
                    {status === PrayerStatus.COMPLETED ? (
                      <i className="fas fa-check text-[11px]"></i>
                    ) : isMissed ? (
                      <i className="fas fa-exclamation text-[11px]"></i>
                    ) : (
                      <i className="fas fa-circle text-[6px]"></i>
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Main Grid Navigation */}
      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        {menuItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setCurrentView(item.id)}
            className={`flex flex-col items-center justify-center p-6 rounded-[32px] transition-all active-scale bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden`}
          >
            <div className="absolute -bottom-4 -right-4 opacity-[0.04] group-hover:scale-125 transition-transform duration-500 pointer-events-none">
               <i className={`fas ${item.icon} text-7xl`}></i>
            </div>
            <div className={`w-14 h-14 rounded-2xl ${item.iconColor} bg-white shadow-sm flex items-center justify-center mb-4 transition-transform group-hover:scale-110`}>
              <i className={`fas ${item.icon} text-2xl`}></i>
            </div>
            <span className="text-[11px] font-bold text-center uppercase tracking-widest text-slate-800">{item.label}</span>
          </button>
        ))}
      </div>

      {/* Featured Dhikr Challenge Section */}
      {featuredChallenge && (
        <div className="px-6">
          <div className="bg-emerald-950 p-6 rounded-[36px] text-white shadow-xl relative overflow-hidden border border-emerald-800">
            <div className="absolute top-0 right-0 p-6 opacity-[0.05] pointer-events-none">
              <i className="fas fa-star-and-crescent text-5xl"></i>
            </div>
            <div className="flex justify-between items-center mb-5 rtl:flex-row-reverse">
              <div className="ltr:text-left rtl:text-right">
                <h3 className="text-emerald-400 text-[10px] uppercase font-black tracking-widest mb-1">{t('challenge')}</h3>
                <p className="text-base font-bold tracking-tight">{t(featuredChallenge.title)}</p>
              </div>
              <div className="ltr:text-right rtl:text-left">
                <span className="text-2xl font-black text-gold-classic tabular-nums">
                  {Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%
                </span>
              </div>
            </div>
            <div className="w-full bg-emerald-800/50 h-2.5 rounded-full overflow-hidden mb-4 p-0.5">
              <div 
                className="bg-gold-classic h-full transition-all duration-1000 ease-out rounded-full shadow-[0_0_12px_rgba(212,175,55,0.4)] ltr:origin-left rtl:origin-right"
                style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}
              ></div>
            </div>
            <div className="flex justify-between items-center text-[10px] text-emerald-400 font-bold uppercase rtl:flex-row-reverse">
               <span className="opacity-60">{t('progress')}</span>
               <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { AppState, PrayerStatus } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: AppState;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = [
  'Fajr Sunnah (2)',
  'Dhuhr Before (4)',
  'Dhuhr After (2)',
  'Maghrib Sunnah (2)',
  'Isha Sunnah (2)',
  'Witr (1/3)'
];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);

  const today = new Date().toISOString().split('T')[0];

  const fardLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleFardStatusChange = (prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    const currentStatus = fardLogs[prayer];
    const newStatus = currentStatus === status ? PrayerStatus.PENDING : status;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }

    updatePrayerStatus(today, prayer, newStatus);
  };

  const handleSunnahToggle = (sunnah: string) => {
    const isCompleted = sunnahLogs.includes(sunnah);
    if (!isCompleted) {
      setAnimatingPrayer(sunnah);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([15, 30]);
      }
    }
    toggleSunnahStatus(today, sunnah);
  };

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] view-transition">
      {/* Premium Navigation Header */}
      <div className="p-6 bg-emerald-900 text-white flex flex-col gap-6 shadow-xl rounded-b-[40px] z-20">
        <div className="flex items-center gap-5">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-2xl hover:bg-white/20 transition-all active-scale border border-white/10 rtl:rotate-180">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t('fard')} & {t('sunnah')}</h1>
            <p className="text-[10px] text-emerald-300/80 font-bold uppercase tracking-widest mt-0.5">Daily Tracker</p>
          </div>
        </div>

        <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 backdrop-blur-md">
          <button 
            onClick={() => setActiveTab('fard')}
            className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60 hover:text-white'}`}
          >
            {t('fard')}
          </button>
          <button 
            onClick={() => setActiveTab('sunnah')}
            className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60 hover:text-white'}`}
          >
            {t('sunnah')}
          </button>
        </div>
      </div>

      {/* Main List Section */}
      <div className="p-6 space-y-6 flex-1 overflow-y-auto">
        <div className="text-center pb-4 border-b border-emerald-50">
          <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">
            {new Date().toLocaleDateString(state.profile?.preferredLanguage, { weekday: 'long', month: 'long', day: 'numeric' })}
          </span>
        </div>

        {activeTab === 'fard' ? (
          <div className="space-y-4">
            {PRAYERS.map((prayer) => {
              const status = fardLogs[prayer];
              const isAnimating = animatingPrayer === prayer;
              return (
                <div 
                  key={prayer} 
                  className={`transition-all border p-5 rounded-[32px] flex items-center justify-between group ${
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50 border-rose-100' : 'bg-white border-emerald-50 shadow-sm'
                  } ${isAnimating ? 'animate-ripple-glow animate-success-pop' : ''} rtl:flex-row-reverse`}
                >
                  <div className="flex flex-col ltr:items-start rtl:items-end">
                    <span className={`capitalize font-bold text-base tracking-tight ${
                      status === PrayerStatus.COMPLETED ? 'text-emerald-900' : 
                      status === PrayerStatus.MISSED ? 'text-rose-900' : 'text-slate-800'
                    }`}>{t(prayer)}</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">Obligatory</span>
                  </div>
                  <div className="flex gap-3">
                    <button 
                      onClick={() => handleFardStatusChange(prayer, PrayerStatus.COMPLETED)}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active-scale ${
                        status === PrayerStatus.COMPLETED 
                        ? 'bg-emerald-600 text-white shadow-lg' 
                        : 'bg-white text-slate-300 border border-slate-100 hover:border-emerald-200 hover:text-emerald-600'
                      }`}
                    >
                      <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check-circle' : 'fa-check'} text-lg`}></i>
                    </button>
                    <button 
                      disabled={isExcused}
                      onClick={() => handleFardStatusChange(prayer, PrayerStatus.MISSED)}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active-scale ${
                        status === PrayerStatus.MISSED 
                        ? 'bg-rose-500 text-white shadow-lg' 
                        : isExcused 
                          ? 'bg-slate-50 text-slate-200 opacity-40 cursor-not-allowed border border-slate-100' 
                          : 'bg-white text-slate-300 border border-slate-100 hover:border-rose-200 hover:text-rose-500'
                      }`}
                    >
                      <i className={`fas ${status === PrayerStatus.MISSED ? 'fa-times-circle' : 'fa-times'} text-lg`}></i>
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="space-y-4">
            {SUNNAH_PRAYERS.map((sunnah) => {
              const isCompleted = sunnahLogs.includes(sunnah);
              const isAnimating = animatingPrayer === sunnah;
              return (
                <div 
                  key={sunnah} 
                  className={`transition-all p-5 rounded-[32px] flex items-center justify-between border ${
                    isCompleted ? 'bg-emerald-50 border-emerald-100' : 'bg-white border-emerald-50 shadow-sm'
                  } ${isAnimating ? 'animate-ripple-glow animate-success-pop' : ''} rtl:flex-row-reverse`}
                >
                  <div className="flex flex-col ltr:items-start rtl:items-end">
                    <span className={`font-bold text-sm ${isCompleted ? 'text-emerald-900' : 'text-slate-800'}`}>{sunnah}</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">Recommended</span>
                  </div>
                  <button 
                    disabled={isExcused}
                    onClick={() => handleSunnahToggle(sunnah)}
                    className={`px-5 py-3 rounded-2xl font-bold text-[10px] uppercase tracking-widest transition-all active-scale ${
                      isCompleted 
                      ? 'bg-emerald-600 text-white shadow-lg' 
                      : isExcused 
                        ? 'bg-slate-50 text-slate-200 cursor-not-allowed border border-slate-100' 
                        : 'bg-white text-slate-400 border border-slate-100 hover:border-emerald-200 hover:text-emerald-600'
                    }`}
                  >
                    {isCompleted ? <i className="fas fa-check-circle mr-2"></i> : null}
                    {isCompleted ? t('completed') : t('pending')}
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Bottom Quotes with Arabic Support */}
      <div className="p-10 text-center bg-white border-t border-emerald-50">
        <div className="max-w-xs mx-auto space-y-4">
          <p className="arabic-font text-emerald-800 text-lg leading-relaxed" dir="rtl">
            أَقِمِ الصَّلَاةَ لِدُلُوكِ الشَّمْسِ إِلَىٰ غَسَقِ اللَّيْلِ
          </p>
          <p className="text-slate-500 text-[11px] font-medium leading-relaxed italic opacity-80">
            {state.profile?.preferredLanguage === 'ar' 
              ? "«أول ما يحاسب عليه العبد يوم القيامة من عمله صلاته»"
              : "\"Establish prayer at the decline of the sun [from its meridian] until the darkness of the night...\" (Qur'an 17:78)"}
          </p>
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState } from 'react';
import { UserProfile, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile) => void;
  t: (key: string) => string;
  initialLanguage: Language;
}

