          <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('name')}</label>
          <input 
            type="text" required
            className="w-full px-6 py-4 bg-white border border-emerald-50 rounded-[24px] focus:ring-4 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-300"
