            <div className={`w-14 h-14 rounded-2xl ${item.iconColor} bg-white shadow-sm flex items-center justify-center mb-4 transition-transform group-hover:scale-110`}>
              <i className={`fas ${item.icon} text-2xl`}></i>
            </div>
            <span className="text-[11px] font-bold text-center uppercase tracking-widest text-slate-800">{item.label}</span>
          </button>
        ))}
      </div>

      {/* Featured Challenge */}
      {featuredChallenge && (
        <div className="px-6">
          <div className="bg-emerald-950 p-6 rounded-[36px] text-white shadow-xl relative overflow-hidden border border-emerald-800">
            <div className="absolute top-0 right-0 p-6 opacity-[0.05] pointer-events-none">
              <i className="fas fa-star-and-crescent text-5xl"></i>
            </div>
            <div className="flex justify-between items-center mb-5 rtl:flex-row-reverse">
              <div className="ltr:text-left rtl:text-right">
                <h3 className="text-emerald-400 text-[10px] uppercase font-black tracking-widest mb-1">{t('challenge')}</h3>
                <p className="text-base font-bold tracking-tight">{t(featuredChallenge.title)}</p>
              </div>
              <div className="ltr:text-right rtl:text-left">
                <span className="text-2xl font-black text-gold-classic tabular-nums">
                  {Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%
                </span>
              </div>
            </div>
            <div className="w-full bg-emerald-800/50 h-2.5 rounded-full overflow-hidden mb-4 p-0.5">
              <div 
                className="bg-gold-classic h-full transition-all duration-1000 ease-out rounded-full shadow-[0_0_12px_rgba(212,175,55,0.4)] ltr:origin-left rtl:origin-right"
                style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}
              ></div>
            </div>
            <div className="flex justify-between items-center text-[10px] text-emerald-400 font-bold uppercase rtl:flex-row-reverse">
               <span className="opacity-60">{t('progress')}</span>
               <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

