import React, { useState } from 'react';
import { UserData, FastingLog, PrayerTimings } from '../types';

interface FastingTrackerProps {
  // Corrected state type from AppState to UserData with todayTimings
  state: UserData & { todayTimings: PrayerTimings | null };
  updateFasting: (date: string, log: FastingLog) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const FastingTracker: React.FC<FastingTrackerProps> = ({ state, updateFasting, setCurrentView, t }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const currentLog = state.fastingLogs[selectedDate] || { status: 'none', type: 'ramadan' };

  const handleStatus = (status: FastingLog['status'], type: FastingLog['type']) => {
    updateFasting(selectedDate, { status, type });
  };

  // Explicitly type 'l' as FastingLog to resolve the 'unknown' property access error
  const completedTotal = Object.values(state.fastingLogs).filter((l: FastingLog) => l.status === 'completed').length;

  return (
    <div className="flex flex-col min-h-screen">
      <div className="p-4 flex items-center gap-4 bg-indigo-600 text-white">
        <button onClick={() => setCurrentView('dashboard')} className="p-2"><i className="fas fa-arrow-left"></i></button>
        <h1 className="text-xl font-bold">{t('fasting')}</h1>
      </div>

      <div className="p-6">
        <div className="bg-indigo-50 p-8 rounded-3xl mb-8 text-center border border-indigo-100 flex items-center justify-between">
          <div className="text-left">
            <h2 className="text-xs text-indigo-400 font-black uppercase tracking-widest">{t('completed')}</h2>
            <p className="text-4xl font-black text-indigo-900">{completedTotal}</p>
          </div>
