export default FastingTracker;

import React, { useState, useMemo } from 'react';
import { UserData, FastingLog, PrayerTimings } from '../types';

interface FastingTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateFasting: (date: string, log: FastingLog) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const FastingTracker: React.FC<FastingTrackerProps> = ({ state, updateFasting, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'ramadan' | 'daily'>('ramadan');
  const [selectedYear] = useState('1446H'); // Mock current Hijri year for exhibition

  // We use a specific key format for Ramadan days: "ramadan-{year}-{day}"
  const ramadanDays = Array.from({ length: 30 }, (_, i) => i + 1);

  const getRamadanLog = (day: number) => {
    const key = `ramadan-${selectedYear}-${day}`;
    return state.fastingLogs[key] || { status: 'none', type: 'ramadan' };
  };

  const toggleRamadanStatus = (day: number) => {
    const key = `ramadan-${selectedYear}-${day}`;
    const current = getRamadanLog(day);

    let nextStatus: FastingLog['status'] = 'none';
    if (current.status === 'none') nextStatus = 'completed';
    else if (current.status === 'completed') nextStatus = 'missed';
    else if (current.status === 'missed') {
       if (state.profile?.sex === 'female') nextStatus = 'excused';
       else nextStatus = 'none';
    } else if (current.status === 'excused') {
       nextStatus = 'none';
    }

    updateFasting(key, { status: nextStatus, type: 'ramadan' });

    if (nextStatus === 'completed' && 'vibrate' in navigator) {
      navigator.vibrate(50);
    }
  };

  const stats = useMemo(() => {
    let completed = 0;
    let missed = 0;
    let excused = 0;
    ramadanDays.forEach(day => {
      const log = getRamadanLog(day);
      if (log.status === 'completed') completed++;
      if (log.status === 'missed') missed++;
      if (log.status === 'excused') excused++;
    });
    return { completed, missed, excused, pendingQada: missed + excused };
  }, [state.fastingLogs, ramadanDays]);

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] view-transition">
      {/* Premium Header */}
      <div className="p-6 bg-emerald-900 text-white flex flex-col gap-6 shadow-xl rounded-b-[40px] z-20">
        <div className="flex items-center gap-5">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-2xl hover:bg-white/20 transition-all active-scale border border-white/10 rtl:rotate-180">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t('fasting')}</h1>
            <p className="text-[10px] text-emerald-300/80 font-bold uppercase tracking-widest mt-0.5">Spiritual Discipline</p>
          </div>
        </div>

        <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 backdrop-blur-md">
          <button 
            onClick={() => setActiveTab('ramadan')}
            className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'ramadan' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60'}`}
          >
            Ramadan Calendar
          </button>
          <button 
            onClick={() => setActiveTab('daily')}
            className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'daily' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60'}`}
          >
            Sunnah Fasts
          </button>
        </div>
      </div>

      <div className="p-6 flex-1 overflow-y-auto pb-24">
        {activeTab === 'ramadan' ? (
          <div className="space-y-8 animate-fade-up">
            {/* Stats Summary Card */}
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-5 rounded-[32px] border border-emerald-50 shadow-sm flex flex-col items-center text-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('completed')}</span>
                <span className="text-3xl font-black text-emerald-600">{stats.completed}</span>
              </div>
              <div className="bg-white p-5 rounded-[32px] border border-rose-50 shadow-sm flex flex-col items-center text-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Pending Qadāʾ</span>
                <span className="text-3xl font-black text-rose-600">{stats.pendingQada}</span>
              </div>
            </div>

            {/* Ramadan Grid */}
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50 relative overflow-hidden">
               <div className="absolute top-0 right-0 p-4 opacity-[0.02] rotate-12">
                  <i className="fas fa-moon text-9xl"></i>
               </div>

               <div className="flex justify-between items-center mb-8 relative z-10">
                 <div>
                    <h3 className="text-lg font-black text-emerald-900">Ramadan {selectedYear}</h3>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Islamic Month of Mercy</p>
                 </div>
                 <div className="flex items-center gap-4 text-[9px] font-bold">
                    <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-emerald-500"></div>Done</div>
                    <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-rose-500"></div>Fail</div>
                 </div>
               </div>

               <div className="grid grid-cols-5 gap-4">
                 {ramadanDays.map(day => {
                   const log = getRamadanLog(day);
                   return (
                     <button
