                       {/* Subtle label for excused */}
                       {log.status === 'excused' && (
                         <div className="absolute -top-1 -right-1 w-3 h-3 bg-pink-500 rounded-full border-2 border-white"></div>
                       )}
                     </button>
                   );
                 })}
               </div>
            </div>

            <div className="bg-emerald-50 p-6 rounded-[32px] border border-emerald-100 relative overflow-hidden">
               <h4 className="text-emerald-900 font-bold text-sm mb-2 flex items-center gap-2">
                 <i className="fas fa-info-circle text-emerald-600"></i>
                 Qadāʾ Requirement
               </h4>
               <p className="text-emerald-800/70 text-xs leading-relaxed">
                 Fasts missed due to travel, sickness, or {state.profile?.sex === 'female' ? 'menstruation' : 'other reasons'} <b>must</b> be made up after Ramadan and before the next one begins.
               </p>
            </div>
          </div>
        ) : (
          <div className="space-y-6 animate-fade-up">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50">
               <h3 className="text-lg font-black text-emerald-900 mb-6">Track Other Fasts</h3>

               <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Select Date</label>
                    <input 
                      type="date" 
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/5 focus:border-emerald-200 outline-none transition-all font-bold text-emerald-900"
                      defaultValue={new Date().toISOString().split('T')[0]}
                    />
                 </div>

                 <div className="grid grid-cols-1 gap-3 pt-4">
                    {['Mondays & Thursdays', 'White Days (13,14,15)', 'Day of Arafah', 'Ashura'].map((type, idx) => (
                      <button key={idx} className="flex items-center justify-between p-5 bg-white border border-emerald-50 rounded-3xl hover:bg-emerald-50 transition-all group">
                         <span className="font-bold text-slate-700">{type}</span>
                         <div className="w-10 h-10 rounded-2xl bg-emerald-50 text-emerald-600 flex items-center justify-center transition-all group-hover:bg-emerald-600 group-hover:text-white">
                            <i className="fas fa-plus"></i>
