import React, { useState, useMemo } from 'react';
import { UserData, PrayerStatus, QadaReminder, PrayerTimings, HealthPeriod } from '../types';
import { PRAYERS } from '../constants';

interface QadahCalendarProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  updateReminders: (reminders: QadaReminder[]) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QadahCalendar: React.FC<QadahCalendarProps> = ({ state, updatePrayerStatus, updateReminders, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(new Date().toISOString().split('T')[0]);
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [showRemindersModal, setShowRemindersModal] = useState(false);

  const month = viewDate.getMonth();
  const year = viewDate.getFullYear();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const days = useMemo(() => {
    const arr = [];
    for (let i = 0; i < firstDayOfMonth; i++) arr.push(null);
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      arr.push(dateStr);
    }
    return arr;
  }, [month, year]);

  const getDaySummary = (dateStr: string) => {
    if (isDateInHayd(dateStr)) return 'excused';
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 'none';
    const values = Object.values(logs);
    if (values.every(v => v === PrayerStatus.COMPLETED || v === PrayerStatus.EXCUSED)) return 'completed';
    if (values.some(v => v === PrayerStatus.MISSED)) return 'missed';
    return 'pending';
  };

  const nextMonth = () => setViewDate(new Date(year, month + 1, 1));
  const prevMonth = () => setViewDate(new Date(year, month - 1, 1));
  const monthName = viewDate.toLocaleString(state.profile?.preferredLanguage || 'en', { month: 'long' });

  const stats = useMemo(() => {
    let missed = 0;
    let excused = 0;
    Object.keys(state.prayerLogs).forEach(date => {
      const day = state.prayerLogs[date];
      PRAYERS.forEach(p => {
        if (day[p] === PrayerStatus.MISSED) missed++;
        if (day[p] === PrayerStatus.EXCUSED) excused++;
      });
    });
    // Add full days from healthPeriods that might not be in prayerLogs yet
    state.healthPeriods.forEach(p => {
        const start = new Date(p.start);
        const end = p.end ? new Date(p.end) : new Date();
        const diffDays = Math.ceil(Math.abs(end.getTime() - start.getTime()) / (1000 * 3600 * 24)) + 1;
        // This is a rough estimate for summary; precise counting happens by actual log keys elsewhere
    });
    return { missed, excused };
  }, [state.prayerLogs, state.healthPeriods]);

  const selectedDayLogs = selectedDate ? (state.prayerLogs[selectedDate] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  }) : null;

  const handleStatusChange = (prayer: string, status: PrayerStatus) => {
    if (selectedDate) {
      if (status === PrayerStatus.COMPLETED) {
        setAnimatingPrayer(prayer);
        setTimeout(() => setAnimatingPrayer(null), 800);
      }
      updatePrayerStatus(selectedDate, prayer as any, status);
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up relative">
      <div className="p-8 pb-10 bg-[#064e3b] text-white flex items-center justify-between shadow-2xl rounded-b-[48px] z-20 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-5 rotate-12">
           <i className="fas fa-kaaba text-9xl"></i>
        </div>
        <div className="flex items-center gap-5 relative z-10">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-[20px] hover:bg-white/20 border border-white/10 transition-all active:scale-90 rtl:rotate-180 shadow-lg">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-2xl font-black tracking-tight">{t('qadah')}</h1>
            <p className="text-[10px] text-emerald-300 font-black uppercase tracking-[0.3em]">{monthName} {year}</p>
          </div>
        </div>
        <div className="flex gap-2 relative z-10">
          <div className="bg-rose-500/20 px-3 py-2 rounded-xl border border-rose-500/30 flex items-center gap-2 backdrop-blur-sm">
             <span className="text-sm font-black text-rose-100">{stats.missed}</span>
             <span className="text-[8px] font-black uppercase text-rose-200/60">Qada</span>
          </div>
          <div className="bg-pink-500/20 px-3 py-2 rounded-xl border border-pink-500/30 flex items-center gap-2 backdrop-blur-sm">
             <span className="text-sm font-black text-pink-100">{stats.excused}</span>
             <span className="text-[8px] font-black uppercase text-pink-200/60">Excused</span>
          </div>
        </div>
      </div>

      <div className="px-8 pt-8 flex items-center justify-between mb-4">
        <button onClick={prevMonth} className="w-12 h-12 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-[20px] transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
          <i className="fas fa-chevron-left text-xs"></i>
        </button>
        <h2 className="text-lg font-black text-[#064e3b] tracking-tight">{monthName} {year}</h2>
        <button onClick={nextMonth} className="w-12 h-12 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-[20px] transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
          <i className="fas fa-chevron-right text-xs"></i>
        </button>
      </div>

      <div className="px-8 pb-4">
        <div className="grid grid-cols-7 text-center mb-4">
          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
            <span key={d} className="text-[9px] font-black text-slate-300 tracking-[0.3em]">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-2">
          {days.map((dateStr, idx) => {
            if (!dateStr) return <div key={`empty-${idx}`} className="h-10" />;
            const summary = getDaySummary(dateStr);
            const isSelected = selectedDate === dateStr;
            const isToday = dateStr === new Date().toISOString().split('T')[0];
            const dayNum = dateStr.split('-')[2];

            return (
              <button
                key={dateStr}
                onClick={() => setSelectedDate(dateStr)}
                className={`h-12 rounded-[16px] flex flex-col items-center justify-center relative transition-all active:scale-90 border-2 ${
                  isSelected ? 'border-emerald-600 shadow-md' : 'border-transparent'
                } ${
                  summary === 'completed' ? 'bg-emerald-50 text-emerald-800' :
                  summary === 'missed' ? 'bg-rose-50 text-rose-800' :
                  summary === 'excused' ? 'bg-pink-50 text-pink-700 bg-[radial-gradient(#fbcfe8_1px,transparent_1px)] [background-size:4px_4px]' : 'bg-white shadow-sm text-slate-400'
                }`}
              >
                <span className={`text-xs font-black ${isToday ? 'text-emerald-600 underline decoration-2' : ''}`}>{parseInt(dayNum)}</span>
              </button>
            );
          })}
        </div>
      </div>

      <div className="px-8 flex-1 pb-10">
        {selectedDate && (
          <div className="bg-white rounded-[32px] p-6 shadow-xl shadow-emerald-900/5 border border-emerald-50/50 mb-8 animate-fade-up">
            <div className="flex justify-between items-center mb-6">
              <div>
                <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-[0.3em] mb-1">Journal Entry</p>
                <h3 className="text-base font-black text-[#064e3b]">
                  {new Date(selectedDate).toLocaleDateString(state.profile?.preferredLanguage, { weekday: 'long', day: 'numeric', month: 'short' })}
                </h3>
              </div>
              {isDateInHayd(selectedDate) && (
                <div className="bg-pink-50 text-pink-600 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border border-pink-100">
                  {t('excused')}
                </div>
              )}
            </div>

            <div className="space-y-3">
              {PRAYERS.map(prayer => {
                const status = isDateInHayd(selectedDate) ? PrayerStatus.EXCUSED : (selectedDayLogs?.[prayer] || PrayerStatus.PENDING);
                return (
                  <div key={prayer} className={`flex items-center justify-between p-4 rounded-[20px] border transition-all ${
                    status === PrayerStatus.EXCUSED ? 'bg-pink-50/30 border-pink-100' :
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50/50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50/50 border-rose-100' : 'bg-slate-50/50 border-slate-100'
                  }`}>
                    <div className="flex items-center gap-3">
                      <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${
                        status === PrayerStatus.EXCUSED ? 'bg-pink-100 text-pink-500' :
                        status === PrayerStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' :
                        status === PrayerStatus.MISSED ? 'bg-rose-100 text-rose-700' : 'bg-white text-slate-300'
                      }`}>
                        <i className={`fas ${status === PrayerStatus.EXCUSED ? 'fa-leaf' : (status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-clock')} text-[10px]`}></i>
                      </div>
                      <span className="capitalize font-black text-xs text-[#064e3b] tracking-wide">{t(prayer)}</span>
                    </div>

                    {!isDateInHayd(selectedDate) && (
                      <div className="flex gap-2">
                         <button onClick={() => handleStatusChange(prayer, status === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                           <i className="fas fa-check text-[10px]"></i>
                         </button>
                         <button onClick={() => handleStatusChange(prayer, status === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${status === PrayerStatus.MISSED ? 'bg-rose-500 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                           <i className="fas fa-times text-[10px]"></i>
                         </button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default QadahCalendar;

import React, { useState, useMemo } from 'react';
import { UserData, FastingLog, PrayerTimings, HealthPeriod } from '../types';

interface FastingTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateFasting: (date: string, log: FastingLog) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const FastingTracker: React.FC<FastingTrackerProps> = ({ state, updateFasting, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'ramadan' | 'daily'>('ramadan');
  const [selectedYear] = useState('1446H'); // Mock current Hijri year for exhibition

  const ramadanDays = Array.from({ length: 30 }, (_, i) => i + 1);

  const isDayInHayd = (day: number): boolean => {
    // Note: This is a simulation since Ramadan days aren't absolute dates without a start date.
    // For exhibition, we'll assume Ramadan 1446H starts on 2025-03-01
    const ramadanStartDate = new Date("2025-03-01");
    const targetDate = new Date(ramadanStartDate);
    targetDate.setDate(targetDate.getDate() + (day - 1));
    const dateStr = targetDate.toISOString().split('T')[0];

    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate.getTime() >= start && targetDate.getTime() <= end;
    });
  };

  const getRamadanLog = (day: number) => {
    const key = `ramadan-${selectedYear}-${day}`;
    if (isDayInHayd(day)) return { status: 'excused', type: 'ramadan' } as FastingLog;
    return state.fastingLogs[key] || { status: 'none', type: 'ramadan' };
  };

  const toggleRamadanStatus = (day: number) => {
    if (isDayInHayd(day)) return; // Status is fixed as excused

    const key = `ramadan-${selectedYear}-${day}`;
    const current = getRamadanLog(day);
    let nextStatus: FastingLog['status'] = 'none';

    if (current.status === 'none') nextStatus = 'completed';
    else if (current.status === 'completed') nextStatus = 'missed';
    else nextStatus = 'none';

    updateFasting(key, { status: nextStatus, type: 'ramadan' });
    if (nextStatus === 'completed' && 'vibrate' in navigator) navigator.vibrate(50);
  };

  const stats = useMemo(() => {
    let completed = 0;
    let missed = 0;
    let excused = 0;
    ramadanDays.forEach(day => {
      const log = getRamadanLog(day);
      if (log.status === 'completed') completed++;
      if (log.status === 'missed') missed++;
      if (log.status === 'excused') excused++;
    });
    // Missed and Excused both require Qada according to rulings.
    return { completed, missed, excused, pendingQada: missed + excused };
  }, [state.fastingLogs, state.healthPeriods, ramadanDays]);

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] view-transition pb-24">
      <div className="p-6 bg-emerald-900 text-white flex flex-col gap-6 shadow-xl rounded-b-[40px] z-20">
        <div className="flex items-center gap-5">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-2xl hover:bg-white/20 transition-all active-scale border border-white/10 rtl:rotate-180">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t('fasting')}</h1>
            <p className="text-[10px] text-emerald-300/80 font-bold uppercase tracking-widest mt-0.5">Spiritual Discipline</p>
          </div>
        </div>

        <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 backdrop-blur-md">
          <button onClick={() => setActiveTab('ramadan')} className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'ramadan' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60'}`}>Ramadan</button>
          <button onClick={() => setActiveTab('daily')} className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'daily' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60'}`}>Sunnah</button>
        </div>
      </div>

      <div className="p-6 flex-1 overflow-y-auto">
        {activeTab === 'ramadan' ? (
          <div className="space-y-8 animate-fade-up">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-5 rounded-[32px] border border-emerald-50 shadow-sm flex flex-col items-center text-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('completed')}</span>
                <span className="text-3xl font-black text-emerald-600">{stats.completed}</span>
              </div>
              <div className="bg-white p-5 rounded-[32px] border border-rose-50 shadow-sm flex flex-col items-center text-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Pending Qadāʾ</span>
                <div className="flex items-baseline gap-1">
                  <span className="text-3xl font-black text-rose-600">{stats.pendingQada}</span>
                  {stats.excused > 0 && <span className="text-[10px] text-pink-500 font-bold">(+{stats.excused} {t('excused')})</span>}
                </div>
              </div>
            </div>

            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50 relative overflow-hidden">
               <div className="absolute top-0 right-0 p-4 opacity-[0.02] rotate-12"><i className="fas fa-moon text-9xl"></i></div>
               <div className="flex justify-between items-center mb-8 relative z-10">
                 <div>
                    <h3 className="text-lg font-black text-emerald-900">Ramadan {selectedYear}</h3>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Exemption Logic Enabled</p>
                 </div>
               </div>

               <div className="grid grid-cols-5 gap-3">
                 {ramadanDays.map(day => {
                   const log = getRamadanLog(day);
                   return (
                     <button
                       key={day}
                       onClick={() => toggleRamadanStatus(day)}
                       className={`h-14 rounded-2xl flex flex-col items-center justify-center transition-all active-scale relative border-2 ${
                         log.status === 'completed' ? 'bg-emerald-50 border-emerald-100 text-emerald-700' :
                         log.status === 'missed' ? 'bg-rose-50 border-rose-100 text-rose-700' :
                         log.status === 'excused' ? 'bg-pink-50 border-pink-100 text-pink-700 bg-[radial-gradient(#fbcfe8_1px,transparent_1px)] [background-size:4px_4px]' :
                         'bg-slate-50 border-transparent text-slate-400'
                       }`}
                     >
                       <span className="text-xs font-black">{day}</span>
                       <div className="mt-1">
                         {log.status === 'completed' && <i className="fas fa-check text-[10px]"></i>}
                         {log.status === 'missed' && <i className="fas fa-xmark text-[10px]"></i>}
                         {log.status === 'excused' && <i className="fas fa-droplet text-[8px]"></i>}
                       </div>
                     </button>
                   );
                 })}
               </div>
            </div>

            <div className="bg-amber-50 p-6 rounded-[32px] border border-amber-100">
               <h4 className="text-amber-900 font-bold text-xs mb-2 uppercase tracking-widest">Women's Fasting Note</h4>
               <p className="text-amber-800/70 text-[10px] leading-relaxed font-semibold">
                 Days highlighted in pink are exempted from fasting due to Hayd or Nifās. <b>Important:</b> Islamic law requires these fasts to be made up later, which is why they are included in your total Qadāʾ count.
               </p>
            </div>
          </div>
        ) : (
          <div className="space-y-6 animate-fade-up">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50 text-center py-20">
               <i className="fas fa-sun text-4xl text-emerald-100 mb-4"></i>
               <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Sunnah Tracking Coming Soon</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FastingTracker;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';

const USERS_STORAGE_KEY = 'ibadathi_mock_users_v5';
const SESSION_KEY = 'ibadathi_active_session_v5';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    return {
      currentUser: activeSession,
      users: savedUsers ? JSON.parse(savedUsers) : {},
      todayTimings: null
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    currentUserData?.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about'>(
    state.currentUser ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  useEffect(() => {
    if (!state.currentUser || !currentUserData) return;
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = currentUserData.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      updateActiveUser(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.currentUser, currentUserData?.activeChallenges]);

  useEffect(() => {
    if (state.currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ ...prev, todayTimings: data.data.timings }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!currentUserData?.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];
          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;
            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      for (const reminder of currentUserData.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;
          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, currentUserData?.settings.notificationsEnabled, currentUserData?.settings.qadaReminders, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => ({
      ...prev,
      users: {
        ...prev.users,
        [prev.currentUser!]: updater(prev.users[prev.currentUser!])
      }
    }));
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    if (isNew) {
      const newUserData: UserData = {
        profile,
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };
      setState(prev => ({
        ...prev,
        currentUser: profile.username,
        users: { ...prev.users, [profile.username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: profile.username }));
      setCurrentLanguage(profile.preferredLanguage);
    }
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const isDateInHayd = (dateStr: string, periods: HealthPeriod[]): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return periods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000); 
      return targetDate >= start && targetDate <= end;
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(prev => {
      const newPeriod: HealthPeriod = { id: Date.now().toString(), start, end };
      const updatedPeriods = [...prev.healthPeriods, newPeriod];

      const newPrayerLogs = { ...prev.prayerLogs };
      const newFastingLogs = { ...prev.fastingLogs };

      Object.keys(newPrayerLogs).forEach(date => {
        if (isDateInHayd(date, [newPeriod])) {
          PRAYERS.forEach(p => { newPrayerLogs[date][p] = PrayerStatus.EXCUSED; });
        }
      });

      return { ...prev, healthPeriods: updatedPeriods, prayerLogs: newPrayerLogs, fastingLogs: newFastingLogs };
    });
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(prev => ({
      ...prev,
      healthPeriods: prev.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    updateActiveUser(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    updateActiveUser(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;
      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(), title: challenge.title, target: challenge.target, current: challenge.current, date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => c.id === challengeId ? { ...c, current: 0 } : c)
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(prev => {
      const newState = { ...prev, isHaydNifas: active };
      if (active) {
        const start = new Date().toISOString().split('T')[0];
        const newPeriod: HealthPeriod = { id: 'active-period', start, end: null };
        newState.healthPeriods = [...prev.healthPeriods, newPeriod];
        newState.haydStartDate = start;
      } else {
        const today = new Date().toISOString().split('T')[0];
        newState.healthPeriods = prev.healthPeriods.map(p => p.end === null ? { ...p, end: today } : p);
        newState.haydStartDate = null;
      }
      return newState;
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!currentUserData) return;
    if (!currentUserData.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else alert("Please allow notifications in your browser settings.");
    } else updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    updateActiveUser(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return null;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateChallengeProgress} archiveChallenge={archiveChallengeById} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className={`min-h-screen relative w-full h-full ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <div className="islamic-pattern fixed inset-0 pointer-events-none"></div>
      <main className="relative z-10 w-full h-full min-h-screen bg-white overflow-y-auto">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;

    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-700' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-700' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-amber-50 to-amber-100 text-amber-900', iconColor: 'text-amber-700' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-blue-50 to-blue-100 text-blue-900', iconColor: 'text-blue-700' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-900', iconColor: 'text-indigo-700' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-green-50 to-green-100 text-green-900', iconColor: 'text-green-700' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-600' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;

    const timingsMinutes: { name: string; total: number; time: string }[] = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });

    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex: number;
    let isTomorrow = false;

    if (nextIndex === -1) {
      nextIndex = 0;
      prevIndex = timingsMinutes.length - 1;
      isTomorrow = true;
    } else {
      prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1;
    }

    const next = timingsMinutes[nextIndex];
    const prev = timingsMinutes[prevIndex];

    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;

    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));

    const hh = Math.floor(diff / 60);
    const mm = diff % 60;

    return {
      next,
      timeLeft: `${hh}h ${mm}m`,
      progress,
      activeName: prev.name,
      timingsMinutes
    };
  }, [state.todayTimings, currentTimeMinutes]);

  const featuredChallenge = state.activeChallenges[0];

  return (
    <div className="pb-24 view-transition w-full min-h-screen bg-slate-50/30 flex flex-col items-center">

      {/* Daily Hadith Banner */}
      <div className="w-full px-4 pt-6 mb-4 max-w-7xl">
        <div className="bg-white p-6 md:p-10 rounded-[32px] md:rounded-[48px] border border-emerald-50 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-[0.03] pointer-events-none rtl:left-0 rtl:right-auto rtl:-scale-x-100">
            <i className="fas fa-quote-right text-6xl md:text-8xl"></i>
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-3 mb-4">
              <span className="bg-emerald-600/10 text-emerald-800 text-[10px] md:text-xs font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-emerald-100/50">
                {t('hadithTitle')}
              </span>
              <div className="h-px flex-1 bg-emerald-100/30"></div>
            </div>
            <div className="space-y-4 md:space-y-6">
              <p className="text-emerald-900 arabic-font text-2xl md:text-4xl leading-relaxed text-right font-medium" dir="rtl">
                {dailyHadith.arabic}
              </p>
              {userLang !== 'ar' && (
                <p className="text-slate-600 font-medium leading-relaxed italic text-sm md:text-lg pl-3 border-l-2 border-gold-classic/40 rtl:pl-0 rtl:pr-3 rtl:border-l-0 rtl:border-r-2">
                  "{dailyHadith[userLang]}"
                </p>
              )}
            </div>
            <div className="flex items-center justify-end mt-4">
              <span className="text-[9px] md:text-xs font-semibold text-slate-400 uppercase tracking-widest">
                {dailyHadith.reference}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Header Profile Section */}
      <header className="relative w-full bg-emerald-900 text-white pt-10 pb-20 px-6 rounded-b-[48px] shadow-2xl overflow-hidden flex flex-col items-center">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-[80px] -mr-32 -mt-32"></div>
        <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-400/5 rounded-full blur-[60px] -ml-24 -mb-24"></div>

        <div className="relative z-10 w-full max-w-7xl">
          <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-6">
            <div className="flex items-center gap-4 md:gap-6">
              <div className="w-16 h-16 md:w-20 md:h-20 bg-white/10 rounded-[24px] md:rounded-[32px] flex items-center justify-center border border-white/20 backdrop-blur-lg">
                <i className="fas fa-user-circle text-emerald-200 text-3xl md:text-4xl"></i>
              </div>
              <div className="ltr:text-left rtl:text-right">
                <h2 className="text-[10px] md:text-xs text-emerald-300/80 uppercase tracking-[0.2em] font-bold mb-1">{t('welcome')}</h2>
                <h1 className="text-2xl md:text-4xl font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setCurrentView('about')} className="w-12 h-12 md:w-14 md:h-14 rounded-full flex items-center justify-center transition-all border border-white/10 bg-white/10 hover:bg-white/20" title={t('about')}><i className="fas fa-circle-info text-base"></i></button>
              <button onClick={toggleNotifications} className={`w-12 h-12 md:w-14 md:h-14 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-gold-classic text-white shadow-lg shadow-gold-classic/20' : 'bg-white/10 hover:bg-white/20'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-base`}></i></button>
              <button onClick={onLogout} className="w-12 h-12 md:w-14 md:h-14 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-all border border-white/10"><i className="fas fa-power-off text-base text-rose-300"></i></button>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 md:gap-8 justify-center">
            <div className="flex-1 max-w-md glass-card bg-white/5 p-6 rounded-[32px] md:rounded-[40px] ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[10px] md:text-xs text-emerald-300/60 uppercase font-black tracking-widest block mb-2">{t('dhikr')}</span>
              <span className="text-3xl md:text-5xl font-black tabular-nums">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 max-w-md glass-card bg-white/5 p-6 rounded-[32px] md:rounded-[40px] ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[10px] md:text-xs text-emerald-300/60 uppercase font-black tracking-widest block mb-2">{t('lastRead')}</span>
              <span className="text-xl md:text-3xl font-bold truncate block mt-1">
                {state.quranProgress.surah || '---'}
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <div className="w-full max-w-7xl px-4 md:px-8">

        {/* Next Prayer Floating Card */}
        <div className="-mt-12 mb-12 flex justify-center">
          <div className="w-full max-w-3xl bg-white p-8 md:p-12 rounded-[40px] md:rounded-[56px] shadow-2xl shadow-emerald-900/10 border border-emerald-50 relative overflow-hidden">
            <div className="flex flex-col md:flex-row items-center justify-between gap-8 mb-8">
              <div className="text-center md:ltr:text-left md:rtl:text-right">
                <span className="text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest block mb-2">{t('nextPrayer')}</span>
                <div className="flex flex-col md:flex-row items-center gap-4">
                  <h2 className="text-4xl md:text-6xl font-black text-emerald-900 capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                  <div className="px-5 py-2 bg-emerald-50 rounded-full border border-emerald-100">
                    <span className="text-sm md:text-lg font-bold text-emerald-700 tabular-nums">{prayerTimingData?.next.time}</span>
                  </div>
                </div>
              </div>
              <div className="text-center md:ltr:text-right md:rtl:text-left">
                <span className="text-4xl md:text-6xl font-black text-gold-classic tabular-nums">{prayerTimingData?.timeLeft || '--:--'}</span>
                <span className="text-[10px] md:text-xs font-bold text-slate-400 block uppercase tracking-tighter">Remaining Time</span>
              </div>
            </div>
            <div className="w-full bg-slate-100 h-3 md:h-4 rounded-full overflow-hidden p-1 shadow-inner">
              <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000 ease-in-out" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>
        </div>

        {/* Daily Prayers Summary Grid */}
        <div className="mb-12">
          <div className="bg-white p-8 md:p-12 rounded-[40px] md:rounded-[56px] shadow-sm border border-emerald-50/50">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="w-2 h-8 md:h-12 bg-gold-classic rounded-full"></div>
                <h3 className="text-lg md:text-2xl font-black text-emerald-900 uppercase tracking-widest">{t('todayPrayers')}</h3>
              </div>
              {state.isHaydNifas && (
                <span className="text-xs md:text-sm font-bold px-5 py-2 bg-rose-50 text-rose-600 rounded-full border border-rose-100 uppercase tracking-tighter">
                  {t('excused')}
                </span>
              )}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-5 gap-4 md:gap-8">
              {PRAYERS.map((p) => {
                const status = todayLogs[p];
                const isAnimating = animatingPrayer === p;
                let isMissed = false;
                if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                  const timing = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                  if (timing && timing.total < currentTimeMinutes) isMissed = true;
                }

                return (
                  <button
                    key={p}
                    disabled={state.isHaydNifas}
                    onClick={() => handlePrayerToggle(p)}
                    className={`relative flex flex-col items-center p-6 md:p-8 rounded-[32px] md:rounded-[48px] transition-all duration-300 border active-scale ${
                      status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 
                      isMissed ? 'bg-rose-50 border-rose-100 text-rose-700' : 'bg-slate-50 border-transparent text-slate-400'
                    } ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-40 grayscale cursor-not-allowed' : ''}`}
                  >
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-widest mb-4">{t(p)}</span>
                    <div className={`w-12 h-12 md:w-16 md:h-16 rounded-full flex items-center justify-center transition-all ${
                      status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white shadow-xl' : 
                      isMissed ? 'bg-rose-500 text-white shadow-xl' : 'bg-white text-slate-200 border border-slate-100'
                    }`}>
                      {status === PrayerStatus.COMPLETED ? <i className="fas fa-check text-base md:text-xl"></i> : 
                       isMissed ? <i className="fas fa-exclamation text-base md:text-xl"></i> : <i className="fas fa-circle text-[8px]"></i>}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Responsive Grid Navigation */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 md:gap-8 mb-12">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`flex flex-col items-center justify-center p-10 md:p-14 rounded-[40px] md:rounded-[56px] transition-all active-scale bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden shadow-sm hover:shadow-xl`}
            >
              <div className="absolute -bottom-8 -right-8 opacity-[0.04] group-hover:scale-125 transition-transform duration-500 pointer-events-none">
                 <i className={`fas ${item.icon} text-9xl`}></i>
              </div>
              <div className={`w-16 h-16 md:w-20 md:h-20 rounded-[28px] md:rounded-[36px] ${item.iconColor} bg-white shadow-sm flex items-center justify-center mb-6 transition-transform group-hover:rotate-6`}>
                <i className={`fas ${item.icon} text-3xl md:text-4xl`}></i>
              </div>
              <span className="text-sm md:text-lg font-black text-center uppercase tracking-widest text-slate-800">{item.label}</span>
            </button>
          ))}
        </div>

        {/* Featured Challenge Footer Section */}
        {featuredChallenge && (
          <div className="w-full flex justify-center pb-12">
            <div className="w-full max-w-4xl bg-emerald-950 p-8 md:p-12 rounded-[40px] md:rounded-[56px] text-white shadow-2xl relative overflow-hidden border border-emerald-800">
              <div className="absolute top-0 right-0 p-8 opacity-[0.05] pointer-events-none">
                <i className="fas fa-star-and-crescent text-8xl"></i>
              </div>
              <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                <div className="text-center md:ltr:text-left md:rtl:text-right">
                  <h3 className="text-emerald-400 text-[10px] md:text-xs uppercase font-black tracking-widest mb-2">{t('challenge')}</h3>
                  <p className="text-2xl md:text-4xl font-bold tracking-tight">{t(featuredChallenge.title)}</p>
                </div>
                <div className="text-center md:ltr:text-right md:rtl:text-left">
                  <span className="text-4xl md:text-6xl font-black text-gold-classic tabular-nums">
                    {Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%
                  </span>
                </div>
              </div>
              <div className="w-full bg-emerald-800/50 h-4 rounded-full overflow-hidden mb-6 p-1">
                <div className="bg-gold-classic h-full transition-all duration-1000 ease-out rounded-full shadow-[0_0_20px_rgba(212,175,55,0.4)]" style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}></div>
              </div>
              <div className="flex justify-between items-center text-xs md:text-sm text-emerald-400 font-bold uppercase">
                 <span className="opacity-60">{t('progress')}</span>
                 <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

