    currentUserData?.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about'>(
    state.currentUser ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  useEffect(() => {
    if (!state.currentUser || !currentUserData) return;
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = currentUserData.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      updateActiveUser(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.currentUser, currentUserData?.activeChallenges]);

  useEffect(() => {
    if (state.currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ ...prev, todayTimings: data.data.timings }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!currentUserData?.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];
          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;
            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      for (const reminder of currentUserData.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;
          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, currentUserData?.settings.notificationsEnabled, currentUserData?.settings.qadaReminders, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => ({
      ...prev,
      users: {
        ...prev.users,
        [prev.currentUser!]: updater(prev.users[prev.currentUser!])
      }
    }));
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    if (isNew) {
      const newUserData: UserData = {
        profile,
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };
      setState(prev => ({
        ...prev,
        currentUser: profile.username,
        users: { ...prev.users, [profile.username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: profile.username }));
      setCurrentLanguage(profile.preferredLanguage);
    }
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const isDateInHayd = (dateStr: string, periods: HealthPeriod[]): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return periods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000); 
      return targetDate >= start && targetDate <= end;
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(prev => {
      const newPeriod: HealthPeriod = { id: Date.now().toString(), start, end };
      const updatedPeriods = [...prev.healthPeriods, newPeriod];

      const newPrayerLogs = { ...prev.prayerLogs };
      const newFastingLogs = { ...prev.fastingLogs };

      Object.keys(newPrayerLogs).forEach(date => {
        if (isDateInHayd(date, [newPeriod])) {
          PRAYERS.forEach(p => { newPrayerLogs[date][p] = PrayerStatus.EXCUSED; });
        }
      });

      return { ...prev, healthPeriods: updatedPeriods, prayerLogs: newPrayerLogs, fastingLogs: newFastingLogs };
    });
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(prev => ({
      ...prev,
      healthPeriods: prev.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    updateActiveUser(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    updateActiveUser(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;
      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(), title: challenge.title, target: challenge.target, current: challenge.current, date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => c.id === challengeId ? { ...c, current: 0 } : c)
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(prev => {
      const newState = { ...prev, isHaydNifas: active };
      if (active) {
        const start = new Date().toISOString().split('T')[0];
        const newPeriod: HealthPeriod = { id: 'active-period', start, end: null };
        newState.healthPeriods = [...prev.healthPeriods, newPeriod];
        newState.haydStartDate = start;
      } else {
        const today = new Date().toISOString().split('T')[0];
        newState.healthPeriods = prev.healthPeriods.map(p => p.end === null ? { ...p, end: today } : p);
        newState.haydStartDate = null;
      }
      return newState;
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!currentUserData) return;
    if (!currentUserData.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else alert("Please allow notifications in your browser settings.");
    } else updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    updateActiveUser(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return null;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateChallengeProgress} archiveChallenge={archiveChallengeById} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;

    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-700' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-700' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-amber-50 to-amber-100 text-amber-900', iconColor: 'text-amber-700' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-blue-50 to-blue-100 text-blue-900', iconColor: 'text-blue-700' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-900', iconColor: 'text-indigo-700' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-green-50 to-green-100 text-green-900', iconColor: 'text-green-700' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-600' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;

    const timingsMinutes: { name: string; total: number; time: string }[] = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });

    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex: number;
    let isTomorrow = false;

    if (nextIndex === -1) {
      nextIndex = 0;
      prevIndex = timingsMinutes.length - 1;
      isTomorrow = true;
    } else {
      prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1;
    }

    const next = timingsMinutes[nextIndex];
    const prev = timingsMinutes[prevIndex];

    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;

    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));

    const hh = Math.floor(diff / 60);
    const mm = diff % 60;

    return {
      next,
      timeLeft: `${hh}h ${mm}m`,
      progress,
      activeName: prev.name,
      timingsMinutes
    };
  }, [state.todayTimings, currentTimeMinutes]);

  const featuredChallenge = state.activeChallenges[0];

  return (
    <div className="h-full w-full flex flex-col bg-slate-50/30 overflow-hidden view-transition">

      {/* Fixed Sticky Header Section */}
      <header className="relative w-full bg-emerald-900 text-white pt-10 pb-16 px-6 rounded-b-[48px] shadow-2xl overflow-hidden shrink-0">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-[80px] -mr-32 -mt-32"></div>
        <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col items-center">
          <div className="flex flex-col md:flex-row justify-between items-center w-full mb-6 gap-6">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 bg-white/10 rounded-[22px] flex items-center justify-center border border-white/20 backdrop-blur-lg">
                <i className="fas fa-user-circle text-emerald-200 text-2xl"></i>
              </div>
              <div className="ltr:text-left rtl:text-right">
                <h2 className="text-[10px] text-emerald-300/80 uppercase tracking-widest font-bold">{t('welcome')}</h2>
                <h1 className="text-xl font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setCurrentView('about')} className="w-10 h-10 rounded-full flex items-center justify-center transition-all border border-white/10 bg-white/10 hover:bg-white/20"><i className="fas fa-circle-info text-sm"></i></button>
              <button onClick={toggleNotifications} className={`w-10 h-10 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-gold-classic' : 'bg-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-sm`}></i></button>
              <button onClick={onLogout} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center border border-white/10"><i className="fas fa-power-off text-sm text-rose-300"></i></button>
            </div>
          </div>

          <div className="flex gap-4 w-full">
            <div className="flex-1 glass-card bg-white/5 p-4 rounded-[28px] ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[9px] text-emerald-300/60 uppercase font-black tracking-widest block">{t('dhikr')}</span>
              <span className="text-xl font-black tabular-nums">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 glass-card bg-white/5 p-4 rounded-[28px] ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[9px] text-emerald-300/60 uppercase font-black tracking-widest block">{t('lastRead')}</span>
              <span className="text-sm font-bold truncate block mt-0.5">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Internal Scrollable Content Area */}
      <div className="scroll-container w-full">
        <div className="w-full max-w-7xl mx-auto flex flex-col items-center px-4">

          {/* Next Prayer Floating Card */}
          <div className="-mt-10 mb-8 w-full">
            <div className="bg-white p-8 rounded-[40px] shadow-2xl shadow-emerald-900/10 border border-emerald-50 relative overflow-hidden">
              <div className="flex flex-col md:flex-row items-center justify-between gap-6 mb-6">
                <div className="text-center md:ltr:text-left">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('nextPrayer')}</span>
                  <div className="flex items-center gap-3">
                    <h2 className="text-3xl font-black text-emerald-900 capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                    <div className="px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                      <span className="text-xs font-bold text-emerald-700 tabular-nums">{prayerTimingData?.next.time}</span>
                    </div>
                  </div>
                </div>
                <div className="text-center md:ltr:text-right">
                  <span className="text-3xl font-black text-gold-classic tabular-nums">{prayerTimingData?.timeLeft || '--:--'}</span>
                  <span className="text-[9px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
                </div>
              </div>
              <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden p-0.5 shadow-inner">
                <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
              </div>
            </div>
          </div>

          {/* Daily Hadith Banner */}
          <div className="w-full mb-8">
            <div className="bg-white p-6 rounded-[32px] border border-emerald-50 shadow-sm relative overflow-hidden">
              <div className="relative z-10">
                <div className="flex items-center gap-3 mb-4">
                  <span className="bg-emerald-600/10 text-emerald-800 text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest border border-emerald-100/50">
                    {t('hadithTitle')}
                  </span>
                </div>
                <p className="text-emerald-900 arabic-font text-xl leading-relaxed text-right font-medium" dir="rtl">
                  {dailyHadith.arabic}
                </p>
                {userLang !== 'ar' && (
                  <p className="text-slate-600 font-medium leading-relaxed italic text-sm mt-3 border-l-2 border-gold-classic/40 pl-3">
                    "{dailyHadith[userLang]}"
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Daily Prayers Summary Grid */}
          <div className="w-full mb-8">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-sm font-black text-emerald-900 uppercase tracking-widest">{t('todayPrayers')}</h3>
                {state.isHaydNifas && (
                  <span className="text-[10px] font-bold px-3 py-1 bg-rose-50 text-rose-600 rounded-full border border-rose-100 uppercase">
                    {t('excused')}
                  </span>
                )}
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
                {PRAYERS.map((p) => {
                  const status = todayLogs[p];
                  const isAnimating = animatingPrayer === p;
                  let isMissed = false;
                  if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                    const timing = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                    if (timing && timing.total < currentTimeMinutes) isMissed = true;
                  }

                  return (
                    <button
                      key={p}
                      disabled={state.isHaydNifas}
                      onClick={() => handlePrayerToggle(p)}
                      className={`flex flex-col items-center p-4 rounded-[28px] transition-all border active-scale ${
                        status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 
                        isMissed ? 'bg-rose-50 border-rose-100 text-rose-700' : 'bg-slate-50 border-transparent text-slate-400'
                      } ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-40 grayscale cursor-not-allowed' : ''}`}
                    >
                      <span className="text-[9px] font-black uppercase tracking-widest mb-3">{t(p)}</span>
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
                        status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white shadow-lg' : 
                        isMissed ? 'bg-rose-500 text-white shadow-lg' : 'bg-white text-slate-200 border border-slate-100'
                      }`}>
                        {status === PrayerStatus.COMPLETED ? <i className="fas fa-check text-xs"></i> : 
                         isMissed ? <i className="fas fa-exclamation text-xs"></i> : <i className="fas fa-circle text-[6px]"></i>}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Responsive Grid Navigation */}
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 w-full mb-8">
            {menuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setCurrentView(item.id)}
                className={`flex flex-col items-center justify-center p-6 rounded-[32px] transition-all active-scale bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden shadow-sm`}
              >
                <div className={`w-12 h-12 rounded-[22px] ${item.iconColor} bg-white shadow-sm flex items-center justify-center mb-4 transition-transform group-hover:rotate-6`}>
                  <i className={`fas ${item.icon} text-xl`}></i>
                </div>
                <span className="text-[10px] font-black text-center uppercase tracking-widest text-slate-800">{item.label}</span>
              </button>
            ))}
          </div>

          {/* Featured Challenge Footer Section */}
          {featuredChallenge && (
            <div className="w-full pb-12">
              <div className="w-full bg-emerald-950 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden border border-emerald-800">
                <div className="flex justify-between items-center mb-6">
                  <div>
                    <h3 className="text-emerald-400 text-[10px] uppercase font-black tracking-widest mb-1">{t('challenge')}</h3>
                    <p className="text-xl font-bold tracking-tight">{t(featuredChallenge.title)}</p>
                  </div>
                  <span className="text-3xl font-black text-gold-classic tabular-nums">
                    {Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%
                  </span>
                </div>
                <div className="w-full bg-emerald-800/50 h-3 rounded-full overflow-hidden mb-4 p-0.5">
                  <div className="bg-gold-classic h-full rounded-full transition-all" style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-[10px] text-emerald-400 font-bold uppercase">
                   <span className="opacity-60">{t('progress')}</span>
                   <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = [
  'Fajr Sunnah (2)',
  'Dhuhr Before (4)',
  'Dhuhr After (2)',
  'Maghrib Sunnah (2)',
  'Isha Sunnah (2)',
  'Witr (1/3)'
];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);

  const today = new Date().toISOString().split('T')[0];

  const fardLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleFardStatusChange = (prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    const currentStatus = fardLogs[prayer];
    const newStatus = currentStatus === status ? PrayerStatus.PENDING : status;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }

    updatePrayerStatus(today, prayer, newStatus);
  };

  const handleSunnahToggle = (sunnah: string) => {
    const isCompleted = sunnahLogs.includes(sunnah);
    if (!isCompleted) {
      setAnimatingPrayer(sunnah);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([15, 30]);
      }
    }
    toggleSunnahStatus(today, sunnah);
  };

  return (
    <div className="h-full w-full flex flex-col bg-[#fdfbf7] overflow-hidden view-transition">
      {/* Fixed Navigation Header */}
      <div className="p-6 bg-emerald-900 text-white flex flex-col gap-6 shadow-xl rounded-b-[40px] z-20 shrink-0">
        <div className="flex items-center gap-5">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-2xl hover:bg-white/20 transition-all active-scale border border-white/10 rtl:rotate-180">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t('fard')} & {t('sunnah')}</h1>
            <p className="text-[10px] text-emerald-300/80 font-bold uppercase tracking-widest mt-0.5">Daily Tracker</p>
          </div>
        </div>

        <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 backdrop-blur-md">
          <button 
            onClick={() => setActiveTab('fard')}
            className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60 hover:text-white'}`}
          >
            {t('fard')}
          </button>
          <button 
            onClick={() => setActiveTab('sunnah')}
            className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60 hover:text-white'}`}
          >
            {t('sunnah')}
          </button>
        </div>
      </div>

      {/* Internal Scrollable Area */}
      <div className="scroll-container p-6 space-y-6">
        <div className="text-center pb-4 border-b border-emerald-50">
          <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">
            {new Date().toLocaleDateString(state.profile?.preferredLanguage, { weekday: 'long', month: 'long', day: 'numeric' })}
          </span>
        </div>

        {activeTab === 'fard' ? (
          <div className="space-y-4">
            {PRAYERS.map((prayer) => {
              const status = fardLogs[prayer];
              const isAnimating = animatingPrayer === prayer;
              return (
                <div 
                  key={prayer} 
                  className={`transition-all border p-5 rounded-[32px] flex items-center justify-between group ${
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50 border-rose-100' : 'bg-white border-emerald-50 shadow-sm'
                  } ${isAnimating ? 'animate-ripple-glow animate-success-pop' : ''} rtl:flex-row-reverse`}
                >
                  <div className="flex flex-col ltr:items-start rtl:items-end">
                    <span className={`capitalize font-bold text-base tracking-tight ${
                      status === PrayerStatus.COMPLETED ? 'text-emerald-900' : 
                      status === PrayerStatus.MISSED ? 'text-rose-900' : 'text-slate-800'
                    }`}>{t(prayer)}</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">Obligatory</span>
                  </div>
                  <div className="flex gap-3">
                    <button 
                      onClick={() => handleFardStatusChange(prayer, PrayerStatus.COMPLETED)}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active-scale ${
                        status === PrayerStatus.COMPLETED 
                        ? 'bg-emerald-600 text-white shadow-lg' 
                        : 'bg-white text-slate-300 border border-slate-100 hover:border-emerald-200 hover:text-emerald-600'
                      }`}
                    >
                      <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check-circle' : 'fa-check'} text-lg`}></i>
                    </button>
                    <button 
                      disabled={isExcused}
                      onClick={() => handleFardStatusChange(prayer, PrayerStatus.MISSED)}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active-scale ${
                        status === PrayerStatus.MISSED 
                        ? 'bg-rose-500 text-white shadow-lg' 
                        : isExcused 
                          ? 'bg-slate-50 text-slate-200 opacity-40 cursor-not-allowed border border-slate-100' 
                          : 'bg-white text-slate-300 border border-slate-100 hover:border-rose-200 hover:text-rose-500'
                      }`}
                    >
                      <i className={`fas ${status === PrayerStatus.MISSED ? 'fa-times-circle' : 'fa-times'} text-lg`}></i>
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="space-y-4">
            {SUNNAH_PRAYERS.map((sunnah) => {
              const isCompleted = sunnahLogs.includes(sunnah);
              const isAnimating = animatingPrayer === sunnah;
              return (
                <div 
                  key={sunnah} 
                  className={`transition-all p-5 rounded-[32px] flex items-center justify-between border ${
                    isCompleted ? 'bg-emerald-50 border-emerald-100' : 'bg-white border-emerald-50 shadow-sm'
                  } ${isAnimating ? 'animate-ripple-glow animate-success-pop' : ''} rtl:flex-row-reverse`}
                >
                  <div className="flex flex-col ltr:items-start rtl:items-end">
                    <span className={`font-bold text-sm ${isCompleted ? 'text-emerald-900' : 'text-slate-800'}`}>{sunnah}</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">Recommended</span>
                  </div>
                  <button 
                    disabled={isExcused}
                    onClick={() => handleSunnahToggle(sunnah)}
                    className={`px-5 py-3 rounded-2xl font-bold text-[10px] uppercase tracking-widest transition-all active-scale ${
                      isCompleted 
                      ? 'bg-emerald-600 text-white shadow-lg' 
                      : isExcused 
                        ? 'bg-slate-50 text-slate-200 cursor-not-allowed border border-slate-100' 
                        : 'bg-white text-slate-400 border border-slate-100 hover:border-emerald-200 hover:text-emerald-600'
                    }`}
                  >
                    {isCompleted ? <i className="fas fa-check-circle mr-2"></i> : null}
                    {isCompleted ? t('completed') : t('pending')}
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Static Footer (part of scroll area) */}
        <div className="py-10 text-center">
          <p className="arabic-font text-emerald-800 text-lg leading-relaxed" dir="rtl">
            أَقِمِ الصَّلَاةَ لِدُلُوكِ الشَّمْسِ إِلَىٰ غَسَقِ اللَّيْلِ
          </p>
          <p className="text-slate-500 text-[11px] font-medium leading-relaxed italic opacity-80 mt-2">
            {state.profile?.preferredLanguage === 'ar' 
              ? "«أول ما يحاسب عليه العبد يوم القيامة من عمله صلاته»"
              : "\"Establish prayer at the decline of the sun...\" (Qur'an 17:78)"}
          </p>
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';

const USERS_STORAGE_KEY = 'ibadathi_mock_users_v5';
const SESSION_KEY = 'ibadathi_active_session_v5';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    return {
      currentUser: activeSession,
      users: savedUsers ? JSON.parse(savedUsers) : {},
      todayTimings: null
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    currentUserData?.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about'>(
    state.currentUser ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  useEffect(() => {
    if (!state.currentUser || !currentUserData) return;
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = currentUserData.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      updateActiveUser(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.currentUser, currentUserData?.activeChallenges]);

  useEffect(() => {
    if (state.currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ ...prev, todayTimings: data.data.timings }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!currentUserData?.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];
          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;
            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }

      for (const reminder of currentUserData.settings.qadaReminders) {
        if (reminder.enabled && reminder.time === timeStr && lastNotifiedRef.current !== `qada-${reminder.id}-${timeStr}`) {
          lastNotifiedRef.current = `qada-${reminder.id}-${timeStr}`;
          if (Notification.permission === 'granted') {
            new Notification(t('qadaAlertTitle'), {
              body: t('qadaAlertBody'),
              icon: 'https://picsum.photos/192/192'
            });
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, currentUserData?.settings.notificationsEnabled, currentUserData?.settings.qadaReminders, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => ({
      ...prev,
      users: {
        ...prev.users,
        [prev.currentUser!]: updater(prev.users[prev.currentUser!])
      }
    }));
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    if (isNew) {
      const newUserData: UserData = {
        profile,
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };
      setState(prev => ({
        ...prev,
        currentUser: profile.username,
        users: { ...prev.users, [profile.username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: profile.username }));
      setCurrentLanguage(profile.preferredLanguage);
    }
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const isDateInHayd = (dateStr: string, periods: HealthPeriod[]): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return periods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000); 
      return targetDate >= start && targetDate <= end;
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(prev => {
      const newPeriod: HealthPeriod = { id: Date.now().toString(), start, end };
      const updatedPeriods = [...prev.healthPeriods, newPeriod];

      const newPrayerLogs = { ...prev.prayerLogs };
      const newFastingLogs = { ...prev.fastingLogs };

      Object.keys(newPrayerLogs).forEach(date => {
        if (isDateInHayd(date, [newPeriod])) {
          PRAYERS.forEach(p => { newPrayerLogs[date][p] = PrayerStatus.EXCUSED; });
        }
      });

      return { ...prev, healthPeriods: updatedPeriods, prayerLogs: newPrayerLogs, fastingLogs: newFastingLogs };
    });
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(prev => ({
      ...prev,
      healthPeriods: prev.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    updateActiveUser(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    updateActiveUser(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;
      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(), title: challenge.title, target: challenge.target, current: challenge.current, date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => c.id === challengeId ? { ...c, current: 0 } : c)
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(prev => {
      const newState = { ...prev, isHaydNifas: active };
      if (active) {
        const start = new Date().toISOString().split('T')[0];
        const newPeriod: HealthPeriod = { id: 'active-period', start, end: null };
        newState.healthPeriods = [...prev.healthPeriods, newPeriod];
        newState.haydStartDate = start;
      } else {
        const today = new Date().toISOString().split('T')[0];
        newState.healthPeriods = prev.healthPeriods.map(p => p.end === null ? { ...p, end: today } : p);
        newState.haydStartDate = null;
      }
      return newState;
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!currentUserData) return;
    if (!currentUserData.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else alert("Please allow notifications in your browser settings.");
    } else updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    updateActiveUser(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return null;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateChallengeProgress} archiveChallenge={archiveChallengeById} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import ZakatCalculator from './components/ZakatCalculator';
import AboutHelp from './components/AboutHelp';

const USERS_STORAGE_KEY = 'ibadathi_mock_users_v5';
const SESSION_KEY = 'ibadathi_active_session_v5';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    return {
      currentUser: activeSession,
      users: savedUsers ? JSON.parse(savedUsers) : {},
      todayTimings: null
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    currentUserData?.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'zakat'>(
    state.currentUser ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  useEffect(() => {
    if (!state.currentUser || !currentUserData) return;
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = currentUserData.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      updateActiveUser(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.currentUser, currentUserData?.activeChallenges]);

  useEffect(() => {
    if (state.currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ ...prev, todayTimings: data.data.timings }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!currentUserData?.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];
          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;
            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, currentUserData?.settings.notificationsEnabled, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => ({
      ...prev,
      users: {
        ...prev.users,
        [prev.currentUser!]: updater(prev.users[prev.currentUser!])
      }
    }));
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    if (isNew) {
      const newUserData: UserData = {
        profile,
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };
      setState(prev => ({
        ...prev,
        currentUser: profile.username,
        users: { ...prev.users, [profile.username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: profile.username }));
      setCurrentLanguage(profile.preferredLanguage);
    }
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const isDateInHayd = (dateStr: string, periods: HealthPeriod[]): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return periods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000); 
      return targetDate >= start && targetDate <= end;
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(prev => {
      const newPeriod: HealthPeriod = { id: Date.now().toString(), start, end };
      const updatedPeriods = [...prev.healthPeriods, newPeriod];

      const newPrayerLogs = { ...prev.prayerLogs };
      const newFastingLogs = { ...prev.fastingLogs };

      Object.keys(newPrayerLogs).forEach(date => {
        if (isDateInHayd(date, [newPeriod])) {
          PRAYERS.forEach(p => { newPrayerLogs[date][p] = PrayerStatus.EXCUSED; });
        }
      });

      return { ...prev, healthPeriods: updatedPeriods, prayerLogs: newPrayerLogs, fastingLogs: newFastingLogs };
    });
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(prev => ({
      ...prev,
      healthPeriods: prev.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    updateActiveUser(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    updateActiveUser(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;
      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(), title: challenge.title, target: challenge.target, current: challenge.current, date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => c.id === challengeId ? { ...c, current: 0 } : c)
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(prev => {
      const newState = { ...prev, isHaydNifas: active };
      if (active) {
        const start = new Date().toISOString().split('T')[0];
        const newPeriod: HealthPeriod = { id: 'active-period', start, end: null };
        newState.healthPeriods = [...prev.healthPeriods, newPeriod];
        newState.haydStartDate = start;
      } else {
        const today = new Date().toISOString().split('T')[0];
        newState.healthPeriods = prev.healthPeriods.map(p => p.end === null ? { ...p, end: today } : p);
        newState.haydStartDate = null;
      }
      return newState;
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!currentUserData) return;
    if (!currentUserData.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else alert("Please allow notifications in your browser settings.");
    } else updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    updateActiveUser(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return null;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateChallengeProgress} archiveChallenge={archiveChallengeById} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'zakat':
        return <ZakatCalculator setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;
    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) navigator.vibrate([20, 40]);
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-700' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-700' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-amber-50 to-emerald-50 text-emerald-900', iconColor: 'text-emerald-700' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-blue-50 to-blue-100 text-blue-900', iconColor: 'text-blue-700' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-900', iconColor: 'text-indigo-700' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-green-50 to-green-100 text-green-900', iconColor: 'text-green-700' },
    { id: 'zakat', label: t('zakat'), icon: 'fa-coins', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-700' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-600' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name, timingsMinutes };
  }, [state.todayTimings, currentTimeMinutes]);

  const featuredChallenge = state.activeChallenges[0];

  return (
    <div className="h-full w-full flex flex-col bg-slate-50/30 overflow-hidden view-transition pt-8">

      {/* Fixed Sticky Header Section */}
      <header className="relative w-full bg-[#064e3b] text-white pt-8 pb-12 px-6 rounded-b-[40px] shadow-2xl overflow-hidden shrink-0">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-[80px] -mr-32 -mt-32"></div>
        <div className="relative z-10 w-full flex flex-col items-center">
          <div className="flex justify-between items-center w-full mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-lg">
                <i className="fas fa-user text-emerald-200"></i>
              </div>
              <div className="ltr:text-left rtl:text-right">
                <h2 className="text-[9px] text-emerald-300 uppercase tracking-widest font-bold">{t('welcome')}</h2>
                <h1 className="text-lg font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setCurrentView('about')} className="w-9 h-9 rounded-full flex items-center justify-center transition-all border border-white/10 bg-white/10"><i className="fas fa-info text-xs"></i></button>
              <button onClick={toggleNotifications} className={`w-9 h-9 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-gold-classic' : 'bg-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-xs`}></i></button>
              <button onClick={onLogout} className="w-9 h-9 bg-white/10 rounded-full flex items-center justify-center border border-white/10"><i className="fas fa-power-off text-xs text-rose-300"></i></button>
            </div>
          </div>

          <div className="flex gap-3 w-full">
            <div className="flex-1 glass-card bg-white/5 p-4 rounded-3xl ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[9px] text-emerald-300/60 uppercase font-black tracking-widest block">{t('dhikr')}</span>
              <span className="text-xl font-black tabular-nums">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 glass-card bg-white/5 p-4 rounded-3xl ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[9px] text-emerald-300/60 uppercase font-black tracking-widest block">{t('lastRead')}</span>
              <span className="text-sm font-bold truncate block mt-0.5">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Internal Scrollable Content Area */}
      <div className="scroll-container w-full">
        <div className="w-full flex flex-col items-center px-4 pt-4">

          {/* Daily Hadith Banner - AT THE TOP OF CONTENT */}
          <div className="w-full mb-6">
            <div className="bg-white p-6 rounded-[32px] border border-emerald-50 shadow-sm relative overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-[0.03] rotate-12"><i className="fas fa-quote-right text-6xl"></i></div>
              <div className="relative z-10">
                <div className="flex items-center gap-2 mb-3">
                  <span className="bg-emerald-600/10 text-emerald-800 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest">
                    {t('hadithTitle')}
                  </span>
                </div>
                <p className="text-emerald-900 arabic-font text-lg leading-relaxed text-right font-medium" dir="rtl">
                  {dailyHadith.arabic}
                </p>
                {userLang !== 'ar' && (
                  <p className="text-slate-600 font-medium leading-relaxed italic text-xs mt-3 border-l-2 border-gold-classic/40 pl-3">
                    "{dailyHadith[userLang]}"
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Next Prayer Floating Card */}
          <div className="mb-6 w-full">
            <div className="bg-white p-6 rounded-[40px] shadow-2xl shadow-emerald-900/10 border border-emerald-50 relative overflow-hidden">
              <div className="flex items-center justify-between gap-4 mb-4">
                <div className="ltr:text-left">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('nextPrayer')}</span>
                  <div className="flex items-center gap-2">
                    <h2 className="text-2xl font-black text-emerald-900 capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                    <div className="px-2 py-0.5 bg-emerald-50 rounded-full border border-emerald-100">
                      <span className="text-[10px] font-bold text-emerald-700 tabular-nums">{prayerTimingData?.next.time}</span>
                    </div>
                  </div>
                </div>
                <div className="ltr:text-right">
                  <span className="text-2xl font-black text-gold-classic tabular-nums">{prayerTimingData?.timeLeft || '--:--'}</span>
                  <span className="text-[8px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
                </div>
              </div>
              <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden p-0.5">
                <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
              </div>
            </div>
          </div>

          {/* Today's Prayers Summary */}
          <div className="w-full mb-6">
            <div className="bg-white p-6 rounded-[36px] shadow-sm border border-emerald-50">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xs font-black text-emerald-900 uppercase tracking-widest">{t('todayPrayers')}</h3>
                {state.isHaydNifas && <span className="text-[8px] font-black px-2 py-1 bg-rose-50 text-rose-600 rounded-full border border-rose-100 uppercase">{t('excused')}</span>}
              </div>
              <div className="grid grid-cols-5 gap-2">
                {PRAYERS.map((p) => {
                  const status = todayLogs[p], isAnimating = animatingPrayer === p;
                  let isMissed = false;
                  if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                    const tmg = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                    if (tmg && tmg.total < currentTimeMinutes) isMissed = true;
                  }
                  return (
                    <button key={p} disabled={state.isHaydNifas} onClick={() => handlePrayerToggle(p)} className={`flex flex-col items-center p-3 rounded-3xl border active-scale ${status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : isMissed ? 'bg-rose-50 border-rose-100 text-rose-700' : 'bg-slate-50 border-transparent text-slate-400'} ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-40 grayscale cursor-not-allowed' : ''}`}>
                      <span className="text-[8px] font-black uppercase tracking-widest mb-2">{t(p)}</span>
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : isMissed ? 'bg-rose-500 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                        {status === PrayerStatus.COMPLETED ? <i className="fas fa-check text-[10px]"></i> : isMissed ? <i className="fas fa-times text-[10px]"></i> : <i className="fas fa-circle text-[4px]"></i>}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Menu Navigation Grid */}
          <div className="grid grid-cols-2 gap-3 w-full mb-8">
            {menuItems.map((item) => (
              <button key={item.id} onClick={() => setCurrentView(item.id)} className={`flex flex-col items-center justify-center p-6 rounded-[32px] transition-all active-scale bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden shadow-sm`}>
                <div className={`w-10 h-10 rounded-2xl ${item.iconColor} bg-white shadow-sm flex items-center justify-center mb-3 transition-transform group-hover:rotate-6`}>
                  <i className={`fas ${item.icon} text-lg`}></i>
                </div>
                <span className="text-[9px] font-black text-center uppercase tracking-widest text-slate-800">{item.label}</span>
              </button>
            ))}
          </div>

          {/* Featured Challenge Footer Section */}
          {featuredChallenge && (
            <div className="w-full pb-10">
              <div className="w-full bg-[#064e3b] p-6 rounded-[36px] text-white shadow-2xl relative overflow-hidden">
                <div className="flex justify-between items-center mb-4">
                  <div><h3 className="text-emerald-400 text-[8px] uppercase font-black tracking-widest mb-1">{t('challenge')}</h3><p className="text-lg font-bold tracking-tight">{t(featuredChallenge.title)}</p></div>
                  <span className="text-2xl font-black text-gold-classic tabular-nums">{Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%</span>
                </div>
                <div className="w-full bg-emerald-800/50 h-2 rounded-full overflow-hidden mb-3 p-0.5">
                  <div className="bg-gold-classic h-full rounded-full transition-all" style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-[9px] text-emerald-400 font-bold uppercase">
                   <span className="opacity-60">{t('progress')}</span>
                   <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import ZakatCalculator from './components/ZakatCalculator';
import AboutHelp from './components/AboutHelp';

const USERS_STORAGE_KEY = 'ibadathi_mock_users_v5';
const SESSION_KEY = 'ibadathi_active_session_v5';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    return {
      currentUser: activeSession,
      users: savedUsers ? JSON.parse(savedUsers) : {},
      todayTimings: null
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    currentUserData?.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'zakat'>(
    state.currentUser ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  useEffect(() => {
    if (!state.currentUser || !currentUserData) return;
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = currentUserData.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      updateActiveUser(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.currentUser, currentUserData?.activeChallenges]);

  useEffect(() => {
    if (state.currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ ...prev, todayTimings: data.data.timings }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!currentUserData?.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];
          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;
            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, currentUserData?.settings.notificationsEnabled, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => ({
      ...prev,
      users: {
        ...prev.users,
        [prev.currentUser!]: updater(prev.users[prev.currentUser!])
      }
    }));
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    if (isNew) {
      const newUserData: UserData = {
        profile,
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };
      setState(prev => ({
        ...prev,
        currentUser: profile.username,
        users: { ...prev.users, [profile.username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: profile.username }));
      setCurrentLanguage(profile.preferredLanguage);
    }
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const isDateInHayd = (dateStr: string, periods: HealthPeriod[]): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return periods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000); 
      return targetDate >= start && targetDate <= end;
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(prev => {
      const newPeriod: HealthPeriod = { id: Date.now().toString(), start, end };
      const updatedPeriods = [...prev.healthPeriods, newPeriod];

      const newPrayerLogs = { ...prev.prayerLogs };
      const newFastingLogs = { ...prev.fastingLogs };

      Object.keys(newPrayerLogs).forEach(date => {
        if (isDateInHayd(date, [newPeriod])) {
          PRAYERS.forEach(p => { newPrayerLogs[date][p] = PrayerStatus.EXCUSED; });
        }
      });

      return { ...prev, healthPeriods: updatedPeriods, prayerLogs: newPrayerLogs, fastingLogs: newFastingLogs };
    });
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(prev => ({
      ...prev,
      healthPeriods: prev.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    updateActiveUser(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    updateActiveUser(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;
      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(), title: challenge.title, target: challenge.target, current: challenge.current, date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => c.id === challengeId ? { ...c, current: 0 } : c)
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(prev => {
      const newState = { ...prev, isHaydNifas: active };
      if (active) {
        const start = new Date().toISOString().split('T')[0];
        const newPeriod: HealthPeriod = { id: 'active-period', start, end: null };
        newState.healthPeriods = [...prev.healthPeriods, newPeriod];
        newState.haydStartDate = start;
      } else {
        const today = new Date().toISOString().split('T')[0];
        newState.healthPeriods = prev.healthPeriods.map(p => p.end === null ? { ...p, end: today } : p);
        newState.haydStartDate = null;
      }
      return newState;
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!currentUserData) return;
    if (!currentUserData.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else alert("Please allow notifications in your browser settings.");
    } else updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    updateActiveUser(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return null;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateChallengeProgress} archiveChallenge={archiveChallengeById} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'zakat':
        return <ZakatCalculator setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className={`min-h-screen relative w-full h-full ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <main className="relative z-10 w-full h-full min-h-screen bg-white overflow-y-auto">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (mode === 'login') {
      const user = users[formData.username];
      if (!user) {
        setError("User not found.");
        return;
      }
      if (user.profile.password !== formData.password) {
        setError("Incorrect password.");
        return;
      }
      onLogin(user.profile, false);
    } else {
      if (!formData.username || !formData.password || !formData.name) {
        setError("Please fill required fields.");
        return;
      }
      if (users[formData.username]) {
        setError("Username already exists.");
        return;
      }

      // Removed non-existent isLoggedIn property from UserProfile
      onLogin({
        username: formData.username,
        name: formData.name,
        age: parseInt(formData.age) || 0,
        sex: formData.sex,
        place: formData.place,
        preferredLanguage: formData.preferredLanguage,
        password: formData.password
      }, true);
    }
  };

  return (
    <div className="p-8 flex flex-col items-center justify-center min-h-screen bg-[#fdfbf7] view-transition">
      <div className="w-24 h-24 bg-emerald-900 rounded-[36px] flex items-center justify-center mb-6 shadow-2xl border-4 border-white rotate-3">
        <i className="fas fa-mosque text-3xl text-emerald-100"></i>
      </div>
      <h1 className="text-4xl font-black text-emerald-900 mb-2 tracking-tighter">Ibadathi</h1>
      <div className="h-1 w-12 bg-gold-classic rounded-full mb-8"></div>

      <div className="flex bg-emerald-50 p-1 rounded-2xl mb-8 w-full max-w-[280px]">
        <button 
          onClick={() => { setMode('login'); setError(null); }}
          className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('login')}
        </button>
        <button 
          onClick={() => { setMode('register'); setError(null); }}
          className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('register')}
        </button>
      </div>

      <form onSubmit={handleSubmit} className="w-full space-y-5 max-w-sm">
        {error && (
          <div className="bg-rose-50 text-rose-600 p-4 rounded-2xl text-[10px] font-bold text-center border border-rose-100 animate-pulse">
            <i className="fas fa-exclamation-circle mr-2"></i> {error}
          </div>
        )}

        <div className="space-y-1.5">
          <label className="block text-[9px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('username')}</label>
          <input 
            type="text" required
