                <i className={`fas ${item.icon} text-3xl md:text-4xl`}></i>
              </div>
              <span className="text-sm md:text-lg font-black text-center uppercase tracking-widest text-slate-800">{item.label}</span>
            </button>
          ))}
        </div>

        {/* Featured Challenge Footer Section */}
        {featuredChallenge && (
          <div className="w-full flex justify-center pb-12">
            <div className="w-full max-w-4xl bg-emerald-950 p-8 md:p-12 rounded-[40px] md:rounded-[56px] text-white shadow-2xl relative overflow-hidden border border-emerald-800">
              <div className="absolute top-0 right-0 p-8 opacity-[0.05] pointer-events-none">
                <i className="fas fa-star-and-crescent text-8xl"></i>
              </div>
              <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                <div className="text-center md:ltr:text-left md:rtl:text-right">
                  <h3 className="text-emerald-400 text-[10px] md:text-xs uppercase font-black tracking-widest mb-2">{t('challenge')}</h3>
                  <p className="text-2xl md:text-4xl font-bold tracking-tight">{t(featuredChallenge.title)}</p>
                </div>
                <div className="text-center md:ltr:text-right md:rtl:text-left">
                  <span className="text-4xl md:text-6xl font-black text-gold-classic tabular-nums">
                    {Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%
                  </span>
                </div>
              </div>
              <div className="w-full bg-emerald-800/50 h-4 rounded-full overflow-hidden mb-6 p-1">
                <div className="bg-gold-classic h-full transition-all duration-1000 ease-out rounded-full shadow-[0_0_20px_rgba(212,175,55,0.4)]" style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}></div>
              </div>
              <div className="flex justify-between items-center text-xs md:text-sm text-emerald-400 font-bold uppercase">
                 <span className="opacity-60">{t('progress')}</span>
                 <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

