          <i className="fas fa-chevron-left text-sm"></i>
        </button>
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{t('zakat')}</h1>
          <p className="text-[10px] text-rose-200/80 font-bold uppercase tracking-[0.3em] mt-0.5">Financial Obligation</p>
        </div>
      </div>

      <div className="p-8 scroll-container">
        <div className="mb-8 bg-rose-50 p-6 rounded-[32px] border border-rose-100 flex items-center gap-6 shadow-sm">
          <div className="w-16 h-16 bg-rose-600 rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-rose-200">
            <i className="fas fa-coins"></i>
          </div>
          <div>
            <h2 className="font-black text-rose-900 text-xl">{t('zakat')}</h2>
            <p className="text-xs text-rose-700 font-medium italic">"And establish prayer and give zakah..." (Qur'an 2:110)</p>
          </div>
        </div>

        <div className="space-y-6">
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1">{t('totalWealth')}</label>
            <input 
              type="number" 
              placeholder="0.00"
              className="w-full p-5 bg-white border border-emerald-50 rounded-[24px] text-2xl font-bold focus:ring-4 focus:ring-rose-600/10 outline-none shadow-sm text-emerald-900"
              value={wealth}
              onChange={(e) => setWealth(e.target.value)}
            />
          </div>

          <button 
            onClick={calculate}
            className="w-full py-5 bg-rose-600 text-white rounded-[24px] font-black text-sm uppercase tracking-widest shadow-xl shadow-rose-900/20 active:scale-95 transition-all"
          >
            {t('calculate')}
          </button>

          {result !== null && (
            <div className="bg-emerald-50 border border-emerald-100 p-8 rounded-[32px] text-center animate-fade-up shadow-lg">
              <p className="text-emerald-600 text-[10px] font-black uppercase tracking-widest mb-2">{t('zakatAmount')}</p>
              <h2 className="text-4xl font-black text-emerald-800">
                {result.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </h2>
            </div>
          )}
        </div>

        <div className="mt-12 text-xs text-slate-400 bg-slate-50 p-6 rounded-[32px] border border-slate-100 shadow-sm">
          <h3 className="font-bold text-slate-600 mb-2 uppercase tracking-widest text-[10px]">Important Note</h3>
          <p className="leading-relaxed font-medium">Zakat is mandatory on wealth that has reached the Nisab (minimum threshold) and has been held for one complete lunar year. This calculator provides a basic estimate based on the standard 2.5% rate on total wealth. Please consult with a knowledgeable scholar for precise calculations and rulings for your specific situation.</p>
        </div>
      </div>
    </div>
  );
};

