                {t('hadithTitle')}
              </span>
              <div className="h-px flex-1 bg-emerald-100/30"></div>
            </div>
            <div className="space-y-4 md:space-y-6">
              <p className="text-emerald-900 arabic-font text-2xl md:text-4xl leading-relaxed text-right font-medium" dir="rtl">
