interface QadahCalendarProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  updateReminders: (reminders: QadaReminder[]) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QadahCalendar: React.FC<QadahCalendarProps> = ({ state, updatePrayerStatus, updateReminders, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(new Date().toISOString().split('T')[0]);
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [showRemindersModal, setShowRemindersModal] = useState(false);

  const month = viewDate.getMonth();
  const year = viewDate.getFullYear();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const days = useMemo(() => {
    const arr = [];
    for (let i = 0; i < firstDayOfMonth; i++) arr.push(null);
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      arr.push(dateStr);
    }
    return arr;
  }, [month, year]);

  const getDaySummary = (dateStr: string) => {
    if (isDateInHayd(dateStr)) return 'excused';
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 'none';
    const values = Object.values(logs);
    if (values.every(v => v === PrayerStatus.COMPLETED || v === PrayerStatus.EXCUSED)) return 'completed';
    if (values.some(v => v === PrayerStatus.MISSED)) return 'missed';
    return 'pending';
  };

  const nextMonth = () => setViewDate(new Date(year, month + 1, 1));
  const prevMonth = () => setViewDate(new Date(year, month - 1, 1));
  const monthName = viewDate.toLocaleString(state.profile?.preferredLanguage || 'en', { month: 'long' });

  const stats = useMemo(() => {
    let missed = 0;
    let excused = 0;
    Object.keys(state.prayerLogs).forEach(date => {
      const day = state.prayerLogs[date];
      PRAYERS.forEach(p => {
        if (day[p] === PrayerStatus.MISSED) missed++;
        if (day[p] === PrayerStatus.EXCUSED) excused++;
      });
    });
    // Add full days from healthPeriods that might not be in prayerLogs yet
    state.healthPeriods.forEach(p => {
        const start = new Date(p.start);
        const end = p.end ? new Date(p.end) : new Date();
        const diffDays = Math.ceil(Math.abs(end.getTime() - start.getTime()) / (1000 * 3600 * 24)) + 1;
        // This is a rough estimate for summary; precise counting happens by actual log keys elsewhere
    });
    return { missed, excused };
  }, [state.prayerLogs, state.healthPeriods]);

  const selectedDayLogs = selectedDate ? (state.prayerLogs[selectedDate] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  }) : null;

  const handleStatusChange = (prayer: string, status: PrayerStatus) => {
    if (selectedDate) {
      if (status === PrayerStatus.COMPLETED) {
        setAnimatingPrayer(prayer);
        setTimeout(() => setAnimatingPrayer(null), 800);
      }
      updatePrayerStatus(selectedDate, prayer as any, status);
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up relative pb-24">
      <div className="p-8 pb-10 bg-[#064e3b] text-white flex items-center justify-between shadow-2xl rounded-b-[48px] z-20 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-5 rotate-12">
           <i className="fas fa-kaaba text-9xl"></i>
        </div>
        <div className="flex items-center gap-5 relative z-10">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-[20px] hover:bg-white/20 border border-white/10 transition-all active:scale-90 rtl:rotate-180 shadow-lg">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-2xl font-black tracking-tight">{t('qadah')}</h1>
            <p className="text-[10px] text-emerald-300 font-black uppercase tracking-[0.3em]">{monthName} {year}</p>
          </div>
        </div>
        <div className="flex gap-2 relative z-10">
          <div className="bg-rose-500/20 px-3 py-2 rounded-xl border border-rose-500/30 flex items-center gap-2 backdrop-blur-sm">
             <span className="text-sm font-black text-rose-100">{stats.missed}</span>
             <span className="text-[8px] font-black uppercase text-rose-200/60">Qada</span>
          </div>
          <div className="bg-pink-500/20 px-3 py-2 rounded-xl border border-pink-500/30 flex items-center gap-2 backdrop-blur-sm">
             <span className="text-sm font-black text-pink-100">{stats.excused}</span>
             <span className="text-[8px] font-black uppercase text-pink-200/60">Excused</span>
          </div>
        </div>
      </div>

      <div className="px-8 pt-8 flex items-center justify-between mb-4">
        <button onClick={prevMonth} className="w-12 h-12 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-[20px] transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
          <i className="fas fa-chevron-left text-xs"></i>
        </button>
        <h2 className="text-lg font-black text-[#064e3b] tracking-tight">{monthName} {year}</h2>
        <button onClick={nextMonth} className="w-12 h-12 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-[20px] transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
          <i className="fas fa-chevron-right text-xs"></i>
        </button>
      </div>

      <div className="px-8 pb-4">
        <div className="grid grid-cols-7 text-center mb-4">
          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
            <span key={d} className="text-[9px] font-black text-slate-300 tracking-[0.3em]">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-2">
          {days.map((dateStr, idx) => {
            if (!dateStr) return <div key={`empty-${idx}`} className="h-10" />;
            const summary = getDaySummary(dateStr);
            const isSelected = selectedDate === dateStr;
            const isToday = dateStr === new Date().toISOString().split('T')[0];
            const dayNum = dateStr.split('-')[2];

            return (
              <button
                key={dateStr}
                onClick={() => setSelectedDate(dateStr)}
                className={`h-12 rounded-[16px] flex flex-col items-center justify-center relative transition-all active:scale-90 border-2 ${
                  isSelected ? 'border-emerald-600 shadow-md' : 'border-transparent'
                } ${
                  summary === 'completed' ? 'bg-emerald-50 text-emerald-800' :
                  summary === 'missed' ? 'bg-rose-50 text-rose-800' :
                  summary === 'excused' ? 'bg-pink-50 text-pink-700 bg-[radial-gradient(#fbcfe8_1px,transparent_1px)] [background-size:4px_4px]' : 'bg-white shadow-sm text-slate-400'
                }`}
              >
                <span className={`text-xs font-black ${isToday ? 'text-emerald-600 underline decoration-2' : ''}`}>{parseInt(dayNum)}</span>
              </button>
            );
          })}
        </div>
      </div>

      <div className="px-8 flex-1 pb-10 scroll-container">
        {selectedDate && (
          <div className="bg-white rounded-[32px] p-6 shadow-xl shadow-emerald-900/5 border border-emerald-50/50 mb-8 animate-fade-up">
            <div className="flex justify-between items-center mb-6">
              <div>
                <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-[0.3em] mb-1">Journal Entry</p>
                <h3 className="text-base font-black text-[#064e3b]">
                  {new Date(selectedDate).toLocaleDateString(state.profile?.preferredLanguage || 'en', { weekday: 'long', day: 'numeric', month: 'short' })}
                </h3>
              </div>
              {isDateInHayd(selectedDate) && (
                <div className="bg-pink-50 text-pink-600 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border border-pink-100">
                  {t('excused')}
                </div>
              )}
            </div>

            <div className="space-y-3">
              {PRAYERS.map(prayer => {
                const status = isDateInHayd(selectedDate) ? PrayerStatus.EXCUSED : (selectedDayLogs?.[prayer] || PrayerStatus.PENDING);
                return (
                  <div key={prayer} className={`flex items-center justify-between p-4 rounded-[20px] border transition-all ${
                    status === PrayerStatus.EXCUSED ? 'bg-pink-50/30 border-pink-100' :
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50/50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50/50 border-rose-100' : 'bg-slate-50/50 border-slate-100'
                  }`}>
                    <div className="flex items-center gap-3">
                      <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${
                        status === PrayerStatus.EXCUSED ? 'bg-pink-100 text-pink-500' :
                        status === PrayerStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' :
                        status === PrayerStatus.MISSED ? 'bg-rose-100 text-rose-700' : 'bg-white text-slate-300'
                      }`}>
                        <i className={`fas ${status === PrayerStatus.EXCUSED ? 'fa-leaf' : (status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-clock')} text-[10px]`}></i>
                      </div>
                      <span className="capitalize font-black text-xs text-[#064e3b] tracking-wide">{t(prayer)}</span>
                    </div>

                    {!isDateInHayd(selectedDate) && (
                      <div className="flex gap-2">
                         <button onClick={() => handleStatusChange(prayer, status === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                           <i className="fas fa-check text-[10px]"></i>
                         </button>
                         <button onClick={() => handleStatusChange(prayer, status === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${status === PrayerStatus.MISSED ? 'bg-rose-500 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                           <i className="fas fa-times text-[10px]"></i>
                         </button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

