          }`}>
            <i className="fas fa-droplet"></i>
          </div>
          <h2 className="text-xl font-black text-emerald-900 mb-2">{t('haydMode')}</h2>
          <p className="text-slate-400 text-xs font-semibold mb-6 px-4">
            {state.isHaydNifas 
              ? "Period mode is active. Your daily prayers are automatically exempted from obligation." 
              : "Activate this mode manually when your period starts to automate tracking."}
