          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-emerald-900 uppercase tracking-widest flex items-center gap-2">
               <i className="fas fa-calendar-alt text-gold-classic"></i>
               Period History
            </h3>
            <button 
              onClick={() => setShowAdd(!showAdd)}
              className="w-10 h-10 bg-emerald-50 text-emerald-700 rounded-full flex items-center justify-center border border-emerald-100 transition-all hover:bg-emerald-100 active:scale-90"
            >
