import React, { useState, useMemo } from 'react';
import { UserData, FastingLog, PrayerTimings, HealthPeriod } from '../types';

interface FastingTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateFasting: (date: string, log: FastingLog) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const FastingTracker: React.FC<FastingTrackerProps> = ({ state, updateFasting, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'ramadan' | 'daily'>('ramadan');
  const [selectedYear] = useState('1446H'); // Mock current Hijri year for exhibition

  const ramadanDays = Array.from({ length: 30 }, (_, i) => i + 1);

  const isDayInHayd = (day: number): boolean => {
    // Note: This is a simulation since Ramadan days aren't absolute dates without a start date.
    // For exhibition, we'll assume Ramadan 1446H starts on 2025-03-01
    const ramadanStartDate = new Date("2025-03-01");
    const targetDate = new Date(ramadanStartDate);
    targetDate.setDate(targetDate.getDate() + (day - 1));
    const dateStr = targetDate.toISOString().split('T')[0];

    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate.getTime() >= start && targetDate.getTime() <= end;
    });
  };

  const getRamadanLog = (day: number) => {
    const key = `ramadan-${selectedYear}-${day}`;
    if (isDayInHayd(day)) return { status: 'excused', type: 'ramadan' } as FastingLog;
    return state.fastingLogs[key] || { status: 'none', type: 'ramadan' };
  };

  const toggleRamadanStatus = (day: number) => {
    if (isDayInHayd(day)) return; // Status is fixed as excused

    const key = `ramadan-${selectedYear}-${day}`;
    const current = getRamadanLog(day);
    let nextStatus: FastingLog['status'] = 'none';

    if (current.status === 'none') nextStatus = 'completed';
    else if (current.status === 'completed') nextStatus = 'missed';
    else nextStatus = 'none';

    updateFasting(key, { status: nextStatus, type: 'ramadan' });
    if (nextStatus === 'completed' && 'vibrate' in navigator) navigator.vibrate(50);
  };

  const stats = useMemo(() => {
    let completed = 0;
    let missed = 0;
    let excused = 0;
    ramadanDays.forEach(day => {
      const log = getRamadanLog(day);
      if (log.status === 'completed') completed++;
      if (log.status === 'missed') missed++;
      if (log.status === 'excused') excused++;
    });
    // Missed and Excused both require Qada according to rulings.
    return { completed, missed, excused, pendingQada: missed + excused };
  }, [state.fastingLogs, state.healthPeriods, ramadanDays]);

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] view-transition pb-24">
      <div className="p-8 pb-10 bg-emerald-900 text-white flex flex-col gap-6 shadow-xl rounded-b-[48px] z-20">
        <div className="flex items-center gap-5">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-[20px] hover:bg-white/20 transition-all active-scale border border-white/10 rtl:rotate-180">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-2xl font-bold tracking-tight">{t('fasting')}</h1>
            <p className="text-[10px] text-emerald-300/80 font-bold uppercase tracking-[0.3em] mt-0.5">Spiritual Discipline</p>
          </div>
        </div>

        <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 backdrop-blur-md">
          <button onClick={() => setActiveTab('ramadan')} className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'ramadan' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60'}`}>Ramadan</button>
          <button onClick={() => setActiveTab('daily')} className={`flex-1 py-3 px-4 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all ${activeTab === 'daily' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60'}`}>Sunnah</button>
        </div>
      </div>

      <div className="p-8 flex-1 overflow-y-auto">
        {activeTab === 'ramadan' ? (
          <div className="space-y-8 animate-fade-up">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-5 rounded-[32px] border border-emerald-50 shadow-sm flex flex-col items-center text-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('completed')}</span>
                <span className="text-3xl font-black text-emerald-600">{stats.completed}</span>
              </div>
              <div className="bg-white p-5 rounded-[32px] border border-rose-50 shadow-sm flex flex-col items-center text-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Pending Qadāʾ</span>
                <div className="flex items-baseline gap-1">
                  <span className="text-3xl font-black text-rose-600">{stats.pendingQada}</span>
                  {stats.excused > 0 && <span className="text-[10px] text-pink-500 font-bold">(+{stats.excused} {t('excused')})</span>}
                </div>
              </div>
            </div>

            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50 relative overflow-hidden">
               <div className="absolute top-0 right-0 p-4 opacity-[0.02] rotate-12"><i className="fas fa-moon text-9xl"></i></div>
               <div className="flex justify-between items-center mb-8 relative z-10">
                 <div>
                    <h3 className="text-lg font-black text-emerald-900">Ramadan {selectedYear}</h3>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Exemption Logic Enabled</p>
                 </div>
               </div>

               <div className="grid grid-cols-5 gap-3">
                 {ramadanDays.map(day => {
                   const log = getRamadanLog(day);
                   return (
                     <button
                       key={day}
                       onClick={() => toggleRamadanStatus(day)}
                       className={`h-14 rounded-2xl flex flex-col items-center justify-center transition-all active-scale relative border-2 ${
                         log.status === 'completed' ? 'bg-emerald-50 border-emerald-100 text-emerald-700' :
                         log.status === 'missed' ? 'bg-rose-50 border-rose-100 text-rose-700' :
                         log.status === 'excused' ? 'bg-pink-50 border-pink-100 text-pink-700 bg-[radial-gradient(#fbcfe8_1px,transparent_1px)] [background-size:4px_4px]' :
                         'bg-slate-50 border-transparent text-slate-400'
                       }`}
                     >
                       <span className="text-xs font-black">{day}</span>
                       <div className="mt-1">
                         {log.status === 'completed' && <i className="fas fa-check text-[10px]"></i>}
                         {log.status === 'missed' && <i className="fas fa-xmark text-[10px]"></i>}
                         {log.status === 'excused' && <i className="fas fa-droplet text-[8px]"></i>}
                       </div>
                     </button>
                   );
                 })}
               </div>
            </div>

            <div className="bg-amber-50 p-6 rounded-[32px] border border-amber-100">
               <h4 className="text-amber-900 font-bold text-xs mb-2 uppercase tracking-widest">Women's Fasting Note</h4>
               <p className="text-amber-800/70 text-[10px] leading-relaxed font-semibold">
                 Days highlighted in pink are exempted from fasting due to Hayd or Nifās. <b>Important:</b> Islamic law requires these fasts to be made up later, which is why they are included in your total Qadāʾ count.
               </p>
            </div>
          </div>
        ) : (
          <div className="space-y-6 animate-fade-up">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-emerald-50/50 text-center py-20">
               <i className="fas fa-sun text-4xl text-emerald-100 mb-4"></i>
               <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Sunnah Tracking Coming Soon</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FastingTracker;

