import React, { useState, useEffect, useCallback } from 'react';

interface QiblaFinderProps {
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const KAABA_COORDS = { lat: 21.422487, lng: 39.826206 };

const QiblaFinder: React.FC<QiblaFinderProps> = ({ setCurrentView, t }) => {
  const [qiblaAngle, setQiblaAngle] = useState<number | null>(null);
  const [compassHeading, setCompassHeading] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);
  const [locationLoaded, setLocationLoaded] = useState(false);

  const calculateQibla = useCallback((lat: number, lng: number) => {
    const phiK = (KAABA_COORDS.lat * Math.PI) / 180;
    const phi = (lat * Math.PI) / 180;
    const deltaL = ((KAABA_COORDS.lng - lng) * Math.PI) / 180;

    const angle = Math.atan2(
      Math.sin(deltaL),
      Math.cos(phi) * Math.tan(phiK) - Math.sin(phi) * Math.cos(deltaL)
    );

    let qiblaDegree = (angle * 180) / Math.PI;
    if (qiblaDegree < 0) qiblaDegree += 360;
    setQiblaAngle(qiblaDegree);
  }, []);

  useEffect(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          calculateQibla(position.coords.latitude, position.coords.longitude);
          setLocationLoaded(true);
        },
        (err) => {
          setError("Location access denied. Please enable location to find Qibla direction.");
          console.error(err);
        }
      );
    } else {
      setError("Geolocation is not supported by your browser.");
    }
  }, [calculateQibla]);

  useEffect(() => {
    const handleOrientation = (event: DeviceOrientationEvent) => {
      let heading = 0;
      // iOS check
      if ((event as any).webkitCompassHeading !== undefined) {
        heading = (event as any).webkitCompassHeading;
      } else if (event.alpha !== null) {
        // Android absolute orientation
        heading = 360 - event.alpha;
      }
      setCompassHeading(heading);
    };

    // Permission check for iOS 13+
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      (DeviceOrientationEvent as any).requestPermission()
        .then((permissionState: string) => {
          if (permissionState === 'granted') {
            window.addEventListener('deviceorientation', handleOrientation);
          }
        })
        .catch(console.error);
    } else {
      window.addEventListener('deviceorientation', handleOrientation);
    }

    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, []);

  const relativeQibla = qiblaAngle !== null ? (qiblaAngle - compassHeading + 360) % 360 : 0;
  const isAligned = Math.abs(relativeQibla) < 5 || Math.abs(relativeQibla - 360) < 5;

  return (
    <div className="flex flex-col min-h-screen bg-[#fdfbf7] animate-fade-up pb-24">
      {/* Header */}
      <div className="p-8 pb-10 bg-[#064e3b] text-white flex items-center gap-5 shadow-xl rounded-b-[48px] z-20">
        <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-[20px] hover:bg-white/20 transition-all border border-white/10 rtl:rotate-180">
          <i className="fas fa-chevron-left text-sm"></i>
        </button>
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{t('qibla')}</h1>
          <p className="text-[10px] text-emerald-300/80 font-bold uppercase tracking-[0.3em] mt-0.5">Direction Finder</p>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-8 gap-10 scroll-container">
        <div className="text-center max-w-xs">
          <p className="text-[#064e3b]/60 text-xs font-black uppercase tracking-widest mb-2">Direction of Kaaba</p>
          <h2 className="text-2xl font-bold text-[#064e3b]">Holy Masjid al-Haram</h2>
          <p className="text-slate-400 text-[10px] mt-2 italic">Makkah, Saudi Arabia</p>
        </div>

        {error ? (
          <div className="bg-rose-50 border border-rose-100 p-6 rounded-[32px] text-center max-w-sm w-full">
            <i className="fas fa-location-slash text-rose-500 text-3xl mb-4"></i>
            <p className="text-rose-900 text-sm font-bold">{error}</p>
          </div>
        ) : (
          <div className="relative w-64 h-64 md:w-80 md:h-80 lg:w-96 lg:h-96 flex items-center justify-center max-w-full">
            {/* Outer Compass Ring */}
            <div 
              className="absolute inset-0 border-[12px] border-emerald-50 rounded-full shadow-inner transition-transform duration-200"
              style={{ transform: `rotate(${-compassHeading}deg)` }}
            >
              <div className="absolute top-2 left-1/2 -translate-x-1/2 text-[10px] font-black text-emerald-800">N</div>
              <div className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[10px] font-black text-emerald-800">S</div>
              <div className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] font-black text-emerald-800">W</div>
              <div className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-black text-emerald-800">E</div>
            </div>

            {/* Qibla Indicator */}
            <div 
              className={`absolute inset-0 flex items-center justify-center transition-all duration-300 ${isAligned ? 'scale-110' : ''}`}
              style={{ transform: `rotate(${relativeQibla}deg)` }}
            >
              <div className="relative flex flex-col items-center">
                {/* Arrow head */}
                <div className={`w-8 h-8 flex items-center justify-center mb-[-4px] transition-colors ${isAligned ? 'text-emerald-500 animate-bounce' : 'text-slate-300'}`}>
                   <i className="fas fa-kaaba text-2xl"></i>
                </div>
                <div className={`w-1 h-32 rounded-full transition-colors ${isAligned ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-slate-200'}`}></div>
                <div className="absolute -top-12">
                   <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${isAligned ? 'bg-emerald-600 text-white shadow-xl' : 'bg-transparent text-slate-300'}`}>
                      {isAligned ? 'Aligned' : ''}
                   </div>
                </div>
              </div>
            </div>

            {/* Center Point */}
            <div className="w-16 h-16 bg-white rounded-full shadow-2xl border-4 border-emerald-50 z-10 flex items-center justify-center overflow-hidden">
               <i className="fas fa-star-and-crescent text-emerald-600 text-xl"></i>
            </div>
          </div>
        )}

        <div className="w-full max-w-sm bg-white p-6 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 flex flex-col items-center text-center">
           {!locationLoaded && !error && (
             <div className="flex items-center gap-2 text-emerald-600 font-bold text-sm">
                <i className="fas fa-spinner fa-spin"></i>
                Locating your position...
             </div>
           )}
           {locationLoaded && (
             <>
               <span className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.3em] mb-3">Compass Instructions</span>
               <p className="text-slate-500 text-xs leading-relaxed">
                 {t('qibla') === 'بوصلة القبلة' 
                    ? "أمسك جهازك بشكل أفقي وقم بالتدوير حتى يشير رمز الكعبة إلى الأعلى مباشرة."
                    : "Hold your device flat and rotate until the Kaaba icon is pointing directly up."}
                 {isAligned && <span className="text-emerald-600 font-bold block mt-1">You are now facing the Qibla!</span>}
               </p>
             </>
           )}
        </div>

        <p className="text-[10px] text-slate-300 font-bold uppercase tracking-[0.2em]">
           Precision based on magnetic sensors
        </p>
      </div>
    </div>
  );
};

export default QiblaFinder;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import ZakatCalculator from './components/ZakatCalculator';
import AboutHelp from './components/AboutHelp';

const USERS_STORAGE_KEY = 'ibadathi_mock_users_v5';
const SESSION_KEY = 'ibadathi_active_session_v5';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    return {
      currentUser: activeSession,
      users: savedUsers ? JSON.parse(savedUsers) : {},
      todayTimings: null
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(
    currentUserData?.profile?.preferredLanguage || 'en'
  );

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'zakat'>(
    state.currentUser ? 'dashboard' : 'welcome'
  );

  const lastNotifiedRef = useRef<string | null>(null);

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  useEffect(() => {
    if (!state.currentUser || !currentUserData) return;
    const todayStr = new Date().toISOString().split('T')[0];
    const firstChallenge = currentUserData.activeChallenges[0];
    if (firstChallenge && firstChallenge.lastReset !== todayStr) {
      updateActiveUser(prev => ({
        ...prev,
        activeChallenges: prev.activeChallenges.map(c => ({ ...c, current: 0, lastReset: todayStr }))
      }));
    }
  }, [state.currentUser, currentUserData?.activeChallenges]);

  useEffect(() => {
    if (state.currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        try {
          const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${pos.coords.latitude}&longitude=${pos.coords.longitude}&method=2`);
          const data = await res.json();
          if (data.code === 200) {
            setState(prev => ({ ...prev, todayTimings: data.data.timings }));
          }
        } catch (err) {
          console.error("Failed to fetch timings", err);
        }
      });
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!currentUserData?.settings.notificationsEnabled) return;

    const interval = setInterval(() => {
      const now = new Date();
      const currentH = String(now.getHours()).padStart(2, '0');
      const currentM = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${currentH}:${currentM}`;

      if (state.todayTimings) {
        for (const p of PRAYERS) {
          const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
          const pTime = state.todayTimings[pKey];
          if (pTime === timeStr && lastNotifiedRef.current !== `prayer-${p}-${timeStr}`) {
            lastNotifiedRef.current = `prayer-${p}-${timeStr}`;
            if (Notification.permission === 'granted') {
              new Notification(t('prayerAlertTitle'), {
                body: t('prayerAlertBody').replace('{prayer}', t(p)),
                icon: 'https://picsum.photos/192/192'
              });
            }
          }
        }
      }
    }, 30000);

    return () => clearInterval(interval);
  }, [state.todayTimings, currentUserData?.settings.notificationsEnabled, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => ({
      ...prev,
      users: {
        ...prev.users,
        [prev.currentUser!]: updater(prev.users[prev.currentUser!])
      }
    }));
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    if (isNew) {
      const newUserData: UserData = {
        profile,
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };
      setState(prev => ({
        ...prev,
        currentUser: profile.username,
        users: { ...prev.users, [profile.username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: profile.username }));
      setCurrentLanguage(profile.preferredLanguage);
    }
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const isDateInHayd = (dateStr: string, periods: HealthPeriod[]): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return periods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000); 
      return targetDate >= start && targetDate <= end;
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(prev => {
      const dayLogs = prev.prayerLogs[date] || {
        fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
      };
      return {
        ...prev,
        prayerLogs: {
          ...prev.prayerLogs,
          [date]: { ...dayLogs, [prayer]: status }
        }
      };
    });
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(prev => {
      const newPeriod: HealthPeriod = { id: Date.now().toString(), start, end };
      const updatedPeriods = [...prev.healthPeriods, newPeriod];

      const newPrayerLogs = { ...prev.prayerLogs };
      const newFastingLogs = { ...prev.fastingLogs };

      Object.keys(newPrayerLogs).forEach(date => {
        if (isDateInHayd(date, [newPeriod])) {
          PRAYERS.forEach(p => { newPrayerLogs[date][p] = PrayerStatus.EXCUSED; });
        }
      });

      return { ...prev, healthPeriods: updatedPeriods, prayerLogs: newPrayerLogs, fastingLogs: newFastingLogs };
    });
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(prev => ({
      ...prev,
      healthPeriods: prev.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const updateChallengeProgress = (challengeId: string, delta: number) => {
    updateActiveUser(prev => ({
      ...prev,
      dhikrCount: prev.dhikrCount + delta,
      activeChallenges: prev.activeChallenges.map(c => 
        c.id === challengeId ? { ...c, current: c.current + delta } : c
      )
    }));
  };

  const archiveChallengeById = (challengeId: string) => {
    updateActiveUser(prev => {
      const challenge = prev.activeChallenges.find(c => c.id === challengeId);
      if (!challenge) return prev;
      const newHistoryEntry: DhikrHistoryEntry = {
        id: Date.now().toString(), title: challenge.title, target: challenge.target, current: challenge.current, date: new Date().toISOString()
      };
      return {
        ...prev,
        dhikrHistory: [newHistoryEntry, ...prev.dhikrHistory],
        activeChallenges: prev.activeChallenges.map(c => c.id === challengeId ? { ...c, current: 0 } : c)
      };
    });
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(prev => {
      const newState = { ...prev, isHaydNifas: active };
      if (active) {
        const start = new Date().toISOString().split('T')[0];
        const newPeriod: HealthPeriod = { id: 'active-period', start, end: null };
        newState.healthPeriods = [...prev.healthPeriods, newPeriod];
        newState.haydStartDate = start;
      } else {
        const today = new Date().toISOString().split('T')[0];
        newState.healthPeriods = prev.healthPeriods.map(p => p.end === null ? { ...p, end: today } : p);
        newState.haydStartDate = null;
      }
      return newState;
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(prev => {
      const currentDaySunnah = prev.sunnahLogs[date] || [];
      const updated = currentDaySunnah.includes(sunnahName) ? currentDaySunnah.filter(n => n !== sunnahName) : [...currentDaySunnah, sunnahName];
      return { ...prev, sunnahLogs: { ...prev.sunnahLogs, [date]: updated } };
    });
  };

  const toggleNotifications = async () => {
    if (!currentUserData) return;
    if (!currentUserData.settings.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: true } }));
      } else alert("Please allow notifications in your browser settings.");
    } else updateActiveUser(p => ({ ...p, settings: { ...p.settings, notificationsEnabled: false } }));
  };

  const updateQadaReminders = (reminders: QadaReminder[]) => {
    updateActiveUser(prev => ({ ...prev, settings: { ...prev.settings, qadaReminders: reminders } }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return null;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={updateQadaReminders} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateChallengeProgress} archiveChallenge={archiveChallengeById} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(prev => ({ ...prev, quranProgress: p }))} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(p => ({ ...p, fastingLogs: { ...p.fastingLogs, [d]: l } }))} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'zakat':
        return <ZakatCalculator setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={toggleNotifications} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (mode === 'login') {
      const user = users[formData.username];
      if (!user) {
        setError("User not found.");
        return;
      }
      if (user.profile.password !== formData.password) {
        setError("Incorrect password.");
        return;
      }
      onLogin(user.profile, false);
    } else {
      if (!formData.username || !formData.password || !formData.name) {
        setError("Please fill required fields.");
        return;
      }
      if (users[formData.username]) {
        setError("Username already exists.");
        return;
      }

      // Removed non-existent isLoggedIn property from UserProfile
      onLogin({
        username: formData.username,
        name: formData.name,
        age: parseInt(formData.age) || 0,
        sex: formData.sex,
        place: formData.place,
        preferredLanguage: formData.preferredLanguage,
        password: formData.password
      }, true);
    }
  };

  return (
    <div className="p-5 flex flex-col items-center justify-center h-full bg-[#fdfbf7] view-transition">
      <div className="w-16 h-16 bg-emerald-900 rounded-[28px] flex items-center justify-center mb-4 shadow-xl border-2 border-white rotate-3">
        <i className="fas fa-mosque text-2xl text-emerald-100"></i>
      </div>
      <h1 className="text-3xl font-black text-emerald-900 mb-1 tracking-tighter">Ibadathi</h1>
      <div className="h-0.5 w-8 bg-gold-classic rounded-full mb-6"></div>

      <div className="flex bg-emerald-50 p-1 rounded-xl mb-6 w-full max-w-[240px]">
        <button 
          onClick={() => { setMode('login'); setError(null); }}
          className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('login')}
        </button>
        <button 
          onClick={() => { setMode('register'); setError(null); }}
          className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('register')}
        </button>
      </div>

      <form onSubmit={handleSubmit} className="w-full space-y-3 max-w-xs">
        {error && (
          <div className="bg-rose-50 text-rose-600 p-3 rounded-xl text-[9px] font-bold text-center border border-rose-100 animate-pulse">
            <i className="fas fa-exclamation-circle mr-1"></i> {error}
          </div>
        )}

        <div className="space-y-1">
          <label className="block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('username')}</label>
          <input 
            type="text" required
            className="w-full px-4 py-3 bg-white border border-emerald-50 rounded-[18px] focus:ring-2 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm"
            placeholder="muslim_seeker"
            value={formData.username}
            onChange={e => setFormData({...formData, username: e.target.value})}
          />
        </div>

        {mode === 'register' && (
          <>
            <div className="space-y-1">
              <label className="block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('name')}</label>
              <input 
                type="text" required
                className="w-full px-4 py-3 bg-white border border-emerald-50 rounded-[18px] focus:ring-2 focus:ring-emerald-600/5 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm"
                placeholder="Abdullah Al-Fulan"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('age')}</label>
                <input 
                  type="number"
                  className="w-full px-4 py-3 bg-white border border-emerald-50 rounded-[18px] focus:ring-2 focus:ring-emerald-600/5 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm"
                  placeholder="25"
                  value={formData.age}
                  onChange={e => setFormData({...formData, age: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('sex')}</label>
                <select 
                  className="w-full px-4 py-3 bg-white border border-emerald-50 rounded-[18px] focus:ring-2 focus:ring-emerald-600/5 outline-none shadow-sm transition-all font-semibold text-emerald-900 appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22none%22%20viewBox%3D%220%200%2024%2024%22%20stroke%3D%22%2364748b%22%3E%3Cpath%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%222%22%20d%3D%22M19%209l-7%207-7-7%22%20%2F%3E%3C%2Fsvg%3E')] bg-[length:0.8em_0.8em] bg-[right_1rem_center] bg-no-repeat text-sm"
                  value={formData.sex}
                  onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                >
                  <option value="male">{t('male')}</option>
                  <option value="female">{t('female')}</option>
                </select>
              </div>
            </div>

            <div className="space-y-1">
              <label className="block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('place')}</label>
              <input 
                type="text"
                className="w-full px-4 py-3 bg-white border border-emerald-50 rounded-[18px] focus:ring-2 focus:ring-emerald-600/5 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm"
                placeholder="Makkah, KSA"
                value={formData.place}
                onChange={e => setFormData({...formData, place: e.target.value})}
              />
            </div>
          </>
        )}

        <div className="space-y-1">
          <label className="block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1">{t('password')}</label>
          <input 
            type="password" required
            className="w-full px-4 py-3 bg-white border border-emerald-50 rounded-[18px] focus:ring-2 focus:ring-emerald-600/5 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm"
            placeholder="••••••••"
            value={formData.password}
            onChange={e => setFormData({...formData, password: e.target.value})}
          />
        </div>

        <button 
          type="submit"
          className="w-full btn-emerald font-black py-4 rounded-[20px] transition-all active-scale mt-3 uppercase tracking-[0.2em] text-[10px]"
        >
          {mode === 'login' ? t('login') : t('register')}
        </button>
      </form>

      <div className="mt-8 flex items-center gap-3 opacity-10">
        <i className="fas fa-hand-holding-heart text-emerald-900 text-xl"></i>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;
    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) navigator.vibrate([20, 40]);
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-700' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-700' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-amber-50 to-emerald-50 text-emerald-900', iconColor: 'text-emerald-700' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-blue-50 to-blue-100 text-blue-900', iconColor: 'text-blue-700' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-900', iconColor: 'text-indigo-700' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-green-50 to-green-100 text-green-900', iconColor: 'text-green-700' },
    { id: 'zakat', label: t('zakat'), icon: 'fa-coins', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-700' },
  ];

  if (state.profile?.sex === 'female') {
    menuItems.push({ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-600' });
  }

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name, timingsMinutes };
  }, [state.todayTimings, currentTimeMinutes]);

  const featuredChallenge = state.activeChallenges[0];

  return (
    <div className="h-full w-full flex flex-col bg-slate-50/30 overflow-hidden view-transition pt-8">

      {/* Fixed Sticky Header Section */}
      <header className="relative w-full bg-[#064e3b] text-white pt-8 pb-12 px-4 rounded-b-[40px] shadow-2xl overflow-hidden shrink-0">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-[80px] -mr-32 -mt-32"></div>
        <div className="relative z-10 w-full flex flex-col items-center">
          <div className="flex justify-between items-center w-full mb-4">
            <div className="flex items-center gap-2">
              <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center border border-white/20 backdrop-blur-lg">
                <i className="fas fa-user text-emerald-200 text-sm"></i>
              </div>
              <div className="ltr:text-left rtl:text-right">
                <h2 className="text-[8px] text-emerald-300 uppercase tracking-widest font-bold">{t('welcome')}</h2>
                <h1 className="text-base font-bold tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-1.5">
              <button onClick={() => setCurrentView('about')} className="w-8 h-8 rounded-full flex items-center justify-center transition-all border border-white/10 bg-white/10"><i className="fas fa-info text-[10px]"></i></button>
              <button onClick={toggleNotifications} className={`w-8 h-8 rounded-full flex items-center justify-center transition-all border border-white/10 ${state.settings.notificationsEnabled ? 'bg-gold-classic' : 'bg-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-[10px]`}></i></button>
              <button onClick={onLogout} className="w-8 h-8 bg-white/10 rounded-full flex items-center justify-center border border-white/10"><i className="fas fa-power-off text-[10px] text-rose-300"></i></button>
            </div>
          </div>

          <div className="flex gap-2 w-full">
            <div className="flex-1 glass-card bg-white/5 p-3 rounded-2xl ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[8px] text-emerald-300/60 uppercase font-black tracking-widest block">{t('dhikr')}</span>
              <span className="text-lg font-black tabular-nums">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 glass-card bg-white/5 p-3 rounded-2xl ltr:text-left rtl:text-right border border-white/10">
              <span className="text-[8px] text-emerald-300/60 uppercase font-black tracking-widest block">{t('lastRead')}</span>
              <span className="text-xs font-bold truncate block mt-0.5">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content Area - No Scroll here, designed to fit */}
      <div className="w-full flex flex-col items-center flex-1 px-4 py-2 overflow-hidden">

        {/* Daily Hadith Banner - AT THE TOP OF CONTENT */}
        <div className="w-full mb-3">
          <div className="bg-white p-4 rounded-[28px] border border-emerald-50 shadow-sm relative overflow-hidden">
            <div className="absolute top-0 right-0 p-2 opacity-[0.03] rotate-12"><i className="fas fa-quote-right text-4xl"></i></div>
            <div className="relative z-10">
              <div className="flex items-center gap-1.5 mb-2">
                <span className="bg-emerald-600/10 text-emerald-800 text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest">
                  {t('hadithTitle')}
                </span>
              </div>
              <p className="text-emerald-900 arabic-font text-sm leading-relaxed text-right font-medium" dir="rtl">
                {dailyHadith.arabic}
              </p>
              {userLang !== 'ar' && (
                <p className="text-slate-600 font-medium leading-relaxed italic text-[9px] mt-2 border-l border-gold-classic/40 pl-2">
                  "{dailyHadith[userLang]}"
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Next Prayer Floating Card */}
        <div className="mb-3 w-full">
          <div className="bg-white p-4 rounded-[32px] shadow-xl shadow-emerald-900/5 border border-emerald-50 relative overflow-hidden">
            <div className="flex items-center justify-between gap-3 mb-3">
              <div className="ltr:text-left">
                <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-0.5">{t('nextPrayer')}</span>
                <div className="flex items-center gap-1.5">
                  <h2 className="text-xl font-black text-emerald-900 capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                  <div className="px-1.5 py-0.5 bg-emerald-50 rounded-full border border-emerald-100">
                    <span className="text-[8px] font-bold text-emerald-700 tabular-nums">{prayerTimingData?.next.time}</span>
                  </div>
                </div>
              </div>
              <div className="ltr:text-right">
                <span className="text-xl font-black text-gold-classic tabular-nums">{prayerTimingData?.timeLeft || '--:--'}</span>
                <span className="text-[7px] font-bold text-slate-400 block uppercase tracking-tighter">Remaining</span>
              </div>
            </div>
            <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden p-0.5">
              <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>
        </div>

        {/* Today's Prayers Summary */}
        <div className="w-full mb-3">
          <div className="bg-white p-4 rounded-[30px] shadow-sm border border-emerald-50">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-[9px] font-black text-emerald-900 uppercase tracking-widest">{t('todayPrayers')}</h3>
              {state.isHaydNifas && <span className="text-[7px] font-black px-1.5 py-0.5 bg-rose-50 text-rose-600 rounded-full border border-rose-100 uppercase">{t('excused')}</span>}
            </div>
            <div className="grid grid-cols-5 gap-1.5">
              {PRAYERS.map((p) => {
                const status = todayLogs[p], isAnimating = animatingPrayer === p;
                let isMissed = false;
                if (status === PrayerStatus.PENDING && prayerTimingData?.timingsMinutes) {
                  const tmg = prayerTimingData.timingsMinutes.find(tm => tm.name === p);
                  if (tmg && tmg.total < currentTimeMinutes) isMissed = true;
                }
                return (
                  <button key={p} disabled={state.isHaydNifas} onClick={() => handlePrayerToggle(p)} className={`flex flex-col items-center p-2 rounded-2xl border active-scale ${status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : isMissed ? 'bg-rose-50 border-rose-100 text-rose-700' : 'bg-slate-50 border-transparent text-slate-400'} ${isAnimating ? 'animate-success-pop' : ''} ${state.isHaydNifas ? 'opacity-40 grayscale cursor-not-allowed' : ''}`}>
                    <span className="text-[7px] font-black uppercase tracking-widest mb-1.5">{t(p)}</span>
                    <div className={`w-6 h-6 rounded-full flex items-center justify-center transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : isMissed ? 'bg-rose-500 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                      {status === PrayerStatus.COMPLETED ? <i className="fas fa-check text-[8px]"></i> : isMissed ? <i className="fas fa-times text-[8px]"></i> : <i className="fas fa-circle text-[3px]"></i>}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Menu Navigation Grid */}
        <div className="grid grid-cols-2 gap-2 w-full mb-3">
          {menuItems.map((item) => (
            <button key={item.id} onClick={() => setCurrentView(item.id)} className={`flex flex-col items-center justify-center p-4 rounded-[28px] transition-all active-scale bg-gradient-to-br ${item.color} border border-white group relative overflow-hidden shadow-sm`}>
              <div className={`w-8 h-8 rounded-xl ${item.iconColor} bg-white shadow-sm flex items-center justify-center mb-2 transition-transform group-hover:rotate-6`}>
                <i className={`fas ${item.icon} text-base`}></i>
              </div>
              <span className="text-[8px] font-black text-center uppercase tracking-widest text-slate-800">{item.label}</span>
            </button>
          ))}
        </div>

        {/* Featured Challenge Footer Section */}
        {featuredChallenge && (
          <div className="w-full pb-4">
            <div className="w-full bg-[#064e3b] p-4 rounded-[30px] text-white shadow-xl relative overflow-hidden">
              <div className="flex justify-between items-center mb-3">
                <div><h3 className="text-emerald-400 text-[7px] uppercase font-black tracking-widest mb-0.5">{t('challenge')}</h3><p className="text-sm font-bold tracking-tight">{t(featuredChallenge.title)}</p></div>
                <span className="text-xl font-black text-gold-classic tabular-nums">{Math.round((featuredChallenge.current / featuredChallenge.target) * 100)}%</span>
              </div>
              <div className="w-full bg-emerald-800/50 h-1.5 rounded-full overflow-hidden mb-2 p-0.5">
                <div className="bg-gold-classic h-full rounded-full transition-all" style={{ width: `${Math.min(100, (featuredChallenge.current / featuredChallenge.target) * 100)}%` }}></div>
              </div>
              <div className="flex justify-between items-center text-[7px] text-emerald-400 font-bold uppercase">
                 <span className="opacity-60">{t('progress')}</span>
                 <span className="text-white font-black tabular-nums">{featuredChallenge.current} / {featuredChallenge.target}</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = [
  'Fajr Sunnah (2)',
  'Dhuhr Before (4)',
  'Dhuhr After (2)',
  'Maghrib Sunnah (2)',
  'Isha Sunnah (2)',
  'Witr (1/3)'
];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);

  const today = new Date().toISOString().split('T')[0];

  const fardLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING,
    dhuhr: PrayerStatus.PENDING,
    asr: PrayerStatus.PENDING,
    maghrib: PrayerStatus.PENDING,
    isha: PrayerStatus.PENDING
  };

  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleFardStatusChange = (prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    const currentStatus = fardLogs[prayer];
    const newStatus = currentStatus === status ? PrayerStatus.PENDING : status;

    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([20, 40]);
      }
    }

    updatePrayerStatus(today, prayer, newStatus);
  };

  const handleSunnahToggle = (sunnah: string) => {
    const isCompleted = sunnahLogs.includes(sunnah);
    if (!isCompleted) {
      setAnimatingPrayer(sunnah);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) {
        navigator.vibrate([15, 30]);
      }
    }
    toggleSunnahStatus(today, sunnah);
  };

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] overflow-hidden view-transition">
      {/* Fixed Navigation Header */}
      <div className="p-4 pt-10 pb-6 bg-emerald-900 text-white flex flex-col gap-4 shadow-xl rounded-b-[40px] z-20 shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-xl hover:bg-white/20 transition-all active-scale border border-white/10 rtl:rotate-180">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{t('fard')} & {t('sunnah')}</h1>
            <p className="text-[9px] text-emerald-300/80 font-bold uppercase tracking-[0.2em] mt-0.5">Daily Tracker</p>
          </div>
        </div>

        <div className="flex bg-white/5 p-1 rounded-xl border border-white/5 backdrop-blur-md">
          <button 
            onClick={() => setActiveTab('fard')}
            className={`flex-1 py-2.5 px-3 rounded-lg font-bold text-[10px] uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60 hover:text-white'}`}
          >
            {t('fard')}
          </button>
          <button 
            onClick={() => setActiveTab('sunnah')}
            className={`flex-1 py-2.5 px-3 rounded-lg font-bold text-[10px] uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/60 hover:text-white'}`}
          >
            {t('sunnah')}
          </button>
        </div>
      </div>

      {/* Internal Content Area - No Scroll */}
      <div className="flex flex-col flex-1 p-4 overflow-hidden">
        <div className="text-center pb-3 border-b border-emerald-50 mb-4 shrink-0">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
            {new Date().toLocaleDateString(state.profile?.preferredLanguage || 'en', { weekday: 'long', month: 'long', day: 'numeric' })}
          </span>
        </div>

        {activeTab === 'fard' ? (
          <div className="flex-1 space-y-2 overflow-hidden flex flex-col"> {/* Use flex column to manage vertical space */}
            {PRAYERS.map((prayer) => {
              const status = fardLogs[prayer];
              const isAnimating = animatingPrayer === prayer;
              return (
                <div 
                  key={prayer} 
                  className={`transition-all border p-3 rounded-[24px] flex items-center justify-between group ${
                    status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100' : 
                    status === PrayerStatus.MISSED ? 'bg-rose-50 border-rose-100' : 'bg-white border-emerald-50 shadow-sm'
                  } ${isAnimating ? 'animate-ripple-glow animate-success-pop' : ''} rtl:flex-row-reverse`}
                >
                  <div className="flex flex-col ltr:items-start rtl:items-end">
                    <span className={`capitalize font-bold text-sm tracking-tight ${
                      status === PrayerStatus.COMPLETED ? 'text-emerald-900' : 
                      status === PrayerStatus.MISSED ? 'text-rose-900' : 'text-slate-800'
                    }`}>{t(prayer)}</span>
                    <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Obligatory</span>
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={() => handleFardStatusChange(prayer, PrayerStatus.COMPLETED)}
                      className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-scale ${
                        status === PrayerStatus.COMPLETED 
                        ? 'bg-emerald-600 text-white shadow-md' 
                        : 'bg-white text-slate-300 border border-slate-100 hover:border-emerald-200 hover:text-emerald-600'
                      }`}
                    >
                      <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check-circle' : 'fa-check'} text-base`}></i>
                    </button>
                    <button 
                      disabled={isExcused}
                      onClick={() => handleFardStatusChange(prayer, PrayerStatus.MISSED)}
                      className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-scale ${
                        status === PrayerStatus.MISSED 
                        ? 'bg-rose-500 text-white shadow-md' 
                        : isExcused 
                          ? 'bg-slate-50 text-slate-200 opacity-40 cursor-not-allowed border border-slate-100' 
                          : 'bg-white text-slate-300 border border-slate-100 hover:border-rose-200 hover:text-rose-500'
                      }`}
                    >
                      <i className={`fas ${status === PrayerStatus.MISSED ? 'fa-times-circle' : 'fa-times'} text-base`}></i>
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="flex-1 space-y-2 overflow-hidden flex flex-col"> {/* Use flex column to manage vertical space */}
            {SUNNAH_PRAYERS.map((sunnah) => {
              const isCompleted = sunnahLogs.includes(sunnah);
              const isAnimating = animatingPrayer === sunnah;
              return (
                <div 
                  key={sunnah} 
                  className={`transition-all p-3 rounded-[24px] flex items-center justify-between border ${
                    isCompleted ? 'bg-emerald-50 border-emerald-100' : 'bg-white border-emerald-50 shadow-sm'
                  } ${isAnimating ? 'animate-ripple-glow animate-success-pop' : ''} rtl:flex-row-reverse`}
                >
                  <div className="flex flex-col ltr:items-start rtl:items-end">
                    <span className={`font-bold text-sm ${isCompleted ? 'text-emerald-900' : 'text-slate-800'}`}>{sunnah}</span>
                    <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Recommended</span>
                  </div>
                  <button 
                    disabled={isExcused}
                    onClick={() => handleSunnahToggle(sunnah)}
                    className={`px-4 py-2 rounded-xl font-bold text-[9px] uppercase tracking-widest transition-all active-scale shadow-md ${
                      isCompleted 
                      ? 'bg-emerald-600 text-white' 
                      : isExcused 
                        ? 'bg-slate-50 text-slate-200 cursor-not-allowed border border-slate-100' 
                        : 'bg-white text-slate-400 border border-slate-100 hover:border-emerald-200 hover:text-emerald-600'
                    }`}
                  >
                    {isCompleted ? <i className="fas fa-check-circle mr-1"></i> : null}
                    {isCompleted ? t('completed') : t('pending')}
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Static Footer (part of content area, shrunk) */}
        <div className="py-4 text-center shrink-0">
          <p className="arabic-font text-emerald-800 text-sm leading-relaxed" dir="rtl">
            أَقِمِ الصَّلَاةَ لِدُلُوكِ الشَّمْسِ إِلَىٰ غَسَقِ اللَّيْلِ
          </p>
          <p className="text-slate-500 text-[8px] font-medium leading-relaxed italic opacity-80 mt-1">
            {state.profile?.preferredLanguage === 'ar' 
              ? "«أول ما يحاسب عليه العبد يوم القيامة من عمله صلاته»"
              : "\"Establish prayer at the decline of the sun...\" (Qur'an 17:78)"}
          </p>
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState, useMemo } from 'react';
import { UserData, PrayerStatus, QadaReminder, PrayerTimings, HealthPeriod } from '../types';
import { PRAYERS } from '../constants';

interface QadahCalendarProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  updateReminders: (reminders: QadaReminder[]) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QadahCalendar: React.FC<QadahCalendarProps> = ({ state, updatePrayerStatus, updateReminders, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(new Date().toISOString().split('T')[0]);
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [showRemindersModal, setShowRemindersModal] = useState(false); // Modal for reminders

  const month = viewDate.getMonth();
  const year = viewDate.getFullYear();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const days = useMemo(() => {
    const arr = [];
    for (let i = 0; i < firstDayOfMonth; i++) arr.push(null);
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      arr.push(dateStr);
    }
    return arr;
  }, [month, year]);

  const getDaySummary = (dateStr: string) => {
    if (isDateInHayd(dateStr)) return 'excused';
    const logs = state.prayerLogs[dateStr];
    if (!logs) return 'none';
    const values = Object.values(logs);
    if (values.every(v => v === PrayerStatus.COMPLETED || v === PrayerStatus.EXCUSED)) return 'completed';
    if (values.some(v => v === PrayerStatus.MISSED)) return 'missed';
    return 'pending';
  };

  const nextMonth = () => setViewDate(new Date(year, month + 1, 1));
  const prevMonth = () => setViewDate(new Date(year, month - 1, 1));
  const monthName = viewDate.toLocaleString(state.profile?.preferredLanguage || 'en', { month: 'long' });

  const stats = useMemo(() => {
    let missed = 0;
    let excused = 0;
    Object.keys(state.prayerLogs).forEach(date => {
      const day = state.prayerLogs[date];
      PRAYERS.forEach(p => {
        if (day[p] === PrayerStatus.MISSED) missed++;
        if (day[p] === PrayerStatus.EXCUSED) excused++;
      });
    });
    // For this summary, we only count what's explicitly logged or excused within logs.
    return { missed, excused };
  }, [state.prayerLogs]);

  const selectedDayLogs = selectedDate ? (state.prayerLogs[selectedDate] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  }) : null;

  const handleStatusChange = (prayer: string, status: PrayerStatus) => {
    if (selectedDate) {
      if (status === PrayerStatus.COMPLETED) {
        setAnimatingPrayer(prayer);
        setTimeout(() => setAnimatingPrayer(null), 800);
      }
      updatePrayerStatus(selectedDate, prayer as any, status);
    }
  };

  // Reminder Logic (simplified for non-scrolling, would be in a modal)
  const [reminders, setLocalReminders] = useState<QadaReminder[]>(state.settings.qadaReminders);
  const addLocalReminder = () => {
    setLocalReminders([...reminders, { id: Date.now().toString(), time: '00:00', enabled: true }]);
  };
  const updateLocalReminder = (id: string, newTime: string, enabled: boolean) => {
    setLocalReminders(reminders.map(r => r.id === id ? { ...r, time: newTime, enabled: enabled } : r));
  };
  const removeLocalReminder = (id: string) => {
    setLocalReminders(reminders.filter(r => r.id !== id));
  };
  const saveReminders = () => {
    updateReminders(reminders);
    setShowRemindersModal(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] animate-fade-up relative">
      <div className="p-4 pt-10 pb-6 bg-[#064e3b] text-white flex items-center justify-between shadow-xl rounded-b-[40px] z-20 relative overflow-hidden shrink-0">
        <div className="absolute top-0 right-0 p-4 opacity-5 rotate-12">
           <i className="fas fa-kaaba text-7xl"></i>
        </div>
        <div className="flex items-center gap-3 relative z-10">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-xl hover:bg-white/20 border border-white/10 transition-all active:scale-90 rtl:rotate-180 shadow-md">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <div>
            <h1 className="text-xl font-black tracking-tight">{t('qadah')}</h1>
            <p className="text-[9px] text-emerald-300 font-black uppercase tracking-[0.2em]">{monthName} {year}</p>
          </div>
        </div>
        <div className="flex gap-1.5 relative z-10">
          <div className="bg-rose-500/20 px-2 py-1.5 rounded-lg border border-rose-500/30 flex items-center gap-1 backdrop-blur-sm">
             <span className="text-xs font-black text-rose-100">{stats.missed}</span>
             <span className="text-[7px] font-black uppercase text-rose-200/60">Qada</span>
          </div>
          <div className="bg-pink-500/20 px-2 py-1.5 rounded-lg border border-pink-500/30 flex items-center gap-1 backdrop-blur-sm">
             <span className="text-xs font-black text-pink-100">{stats.excused}</span>
             <span className="text-[7px] font-black uppercase text-pink-200/60">Excused</span>
          </div>
        </div>
      </div>

      <div className="flex flex-col flex-1 overflow-hidden"> {/* No scroll here */}
        <div className="px-4 pt-4 flex items-center justify-between mb-3 shrink-0">
          <button onClick={prevMonth} className="w-10 h-10 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-xl transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h2 className="text-base font-black text-[#064e3b] tracking-tight">{monthName} {year}</h2>
          <button onClick={nextMonth} className="w-10 h-10 flex items-center justify-center text-emerald-900 bg-white shadow-sm border border-emerald-50 rounded-xl transition-all hover:bg-emerald-50 active:scale-90 rtl:rotate-180">
            <i className="fas fa-chevron-right text-xs"></i>
          </button>
        </div>

        <div className="px-4 pb-3 shrink-0">
          <div className="grid grid-cols-7 text-center mb-2">
            {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
              <span key={d} className="text-[8px] font-black text-slate-300 tracking-[0.2em]">{d}</span>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {days.map((dateStr, idx) => {
              if (!dateStr) return <div key={`empty-${idx}`} className="h-8" />;
              const summary = getDaySummary(dateStr);
              const isSelected = selectedDate === dateStr;
              const isToday = dateStr === new Date().toISOString().split('T')[0];
              const dayNum = dateStr.split('-')[2];

              return (
                <button
                  key={dateStr}
                  onClick={() => setSelectedDate(dateStr)}
                  className={`h-8 rounded-lg flex flex-col items-center justify-center relative transition-all active:scale-90 border-2 ${
                    isSelected ? 'border-emerald-600 shadow-md' : 'border-transparent'
                  } ${
                    summary === 'completed' ? 'bg-emerald-50 text-emerald-800' :
                    summary === 'missed' ? 'bg-rose-50 text-rose-800' :
                    summary === 'excused' ? 'bg-pink-50 text-pink-700 bg-[radial-gradient(#fbcfe8_1px,transparent_1px)] [background-size:3px_3px]' : 'bg-white shadow-sm text-slate-400'
                  }`}
                >
                  <span className={`text-[10px] font-black ${isToday ? 'text-emerald-600 underline decoration-2' : ''}`}>{parseInt(dayNum)}</span>
                </button>
              );
            })}
          </div>
        </div>

        {selectedDate && (
          <div className="px-4 py-2 flex-1 overflow-hidden flex flex-col"> {/* No scroll here, inner content managed by flex */}
            <div className="bg-white rounded-[28px] p-4 shadow-xl shadow-emerald-900/5 border border-emerald-50/50 mb-3 animate-fade-up shrink-0">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <p className="text-[8px] font-black text-emerald-800/40 uppercase tracking-[0.2em] mb-0.5">Journal Entry</p>
                  <h3 className="text-sm font-black text-[#064e3b]">
                    {new Date(selectedDate).toLocaleDateString(state.profile?.preferredLanguage || 'en', { weekday: 'short', day: 'numeric', month: 'short' })}
                  </h3>
                </div>
                {isDateInHayd(selectedDate) && (
                  <div className="bg-pink-50 text-pink-600 px-2 py-1 rounded-full text-[8px] font-black uppercase tracking-widest border border-pink-100">
                    {t('excused')}
                  </div>
                )}
              </div>

              <div className="space-y-2">
                {PRAYERS.map(prayer => {
                  const status = isDateInHayd(selectedDate) ? PrayerStatus.EXCUSED : (selectedDayLogs?.[prayer] || PrayerStatus.PENDING);
                  return (
                    <div key={prayer} className={`flex items-center justify-between p-3 rounded-[16px] border transition-all ${
                      status === PrayerStatus.EXCUSED ? 'bg-pink-50/30 border-pink-100' :
                      status === PrayerStatus.COMPLETED ? 'bg-emerald-50/50 border-emerald-100' : 
                      status === PrayerStatus.MISSED ? 'bg-rose-50/50 border-rose-100' : 'bg-slate-50/50 border-slate-100'
                    }`}>
                      <div className="flex items-center gap-2">
                        <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${
                          status === PrayerStatus.EXCUSED ? 'bg-pink-100 text-pink-500' :
                          status === PrayerStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' :
                          status === PrayerStatus.MISSED ? 'bg-rose-100 text-rose-700' : 'bg-white text-slate-300'
                        }`}>
                          <i className={`fas ${status === PrayerStatus.EXCUSED ? 'fa-leaf' : (status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-clock')} text-[9px]`}></i>
                        </div>
                        <span className="capitalize font-black text-xs text-[#064e3b] tracking-wide">{t(prayer)}</span>
                      </div>

                      {!isDateInHayd(selectedDate) && (
                        <div className="flex gap-1.5">
                           <button onClick={() => handleStatusChange(prayer, status === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} className={`w-9 h-9 rounded-lg flex items-center justify-center transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                             <i className="fas fa-check text-[9px]"></i>
                           </button>
                           <button onClick={() => handleStatusChange(prayer, status === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)} className={`w-9 h-9 rounded-lg flex items-center justify-center transition-all ${status === PrayerStatus.MISSED ? 'bg-rose-500 text-white' : 'bg-white text-slate-200 border border-slate-100'}`}>
                             <i className="fas fa-times text-[9px]"></i>
                           </button>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Reminders button */}
            <button onClick={() => setShowRemindersModal(true)} className="w-full py-2 bg-emerald-50 text-emerald-700 rounded-2xl font-black text-[9px] uppercase tracking-widest border border-emerald-100 shadow-sm active:scale-95 transition-all shrink-0">
              {t('qadaReminders')}
            </button>
          </div>
        )}
      </div>

      {/* Reminders Modal - this will take over the screen */}
      {showRemindersModal && (
        <div className="absolute inset-0 bg-[#fdfbf7] flex flex-col p-4 z-30 animate-fade-up">
