          <button onClick={saveReminders} className="w-full py-3 bg-gold-classic text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg active:scale-95 transition-all shrink-0">
            {t('save')} Reminders
          </button>
        </div>
      )}
    </div>
  );
};

