                    <div className="w-9 h-9 bg-rose-50 text-rose-500 rounded-lg flex items-center justify-center">
                       <i className="fas fa-tint text-xs"></i>
                    </div>
                    <div>
                      <p className="text-xs font-black text-emerald-900">{p.start} {p.end ? `— ${p.end}` : ' (Active)'}</p>
