import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;
    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) navigator.vibrate([20, 40]);
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'from-emerald-50 to-emerald-100 text-emerald-800', iconColor: 'text-emerald-700' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'from-teal-50 to-teal-100 text-teal-800', iconColor: 'text-teal-700' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'from-amber-50 to-emerald-50 text-emerald-900', iconColor: 'text-emerald-700' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'from-blue-50 to-blue-100 text-blue-900', iconColor: 'text-blue-700' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'from-indigo-50 to-indigo-100 text-indigo-900', iconColor: 'text-indigo-700' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'from-green-50 to-green-100 text-green-900', iconColor: 'text-green-700' },
    { id: 'zakat', label: t('zakat'), icon: 'fa-coins', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-700' },
    ...(state.profile?.sex === 'female' ? [{ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'from-rose-50 to-rose-100 text-rose-900', iconColor: 'text-rose-600' }] : [])
  ];

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name, timingsMinutes };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="h-full w-full flex flex-col bg-slate-50/30 overflow-hidden view-transition pt-8">
      {/* Header Profile Section - Compact */}
      <header className="relative w-full bg-[#064e3b] text-white pt-6 pb-8 px-4 rounded-b-[32px] shadow-lg shrink-0">
        <div className="relative z-10 w-full flex flex-col gap-3">
          <div className="flex justify-between items-center w-full">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center border border-white/20">
                <i className="fas fa-user text-emerald-200 text-xs"></i>
              </div>
              <h1 className="text-sm font-bold truncate max-w-[120px]">{state.profile?.name}</h1>
            </div>
            <div className="flex gap-1">
              <button onClick={() => setCurrentView('about')} className="w-7 h-7 rounded-full flex items-center justify-center bg-white/10"><i className="fas fa-info text-[9px]"></i></button>
              <button onClick={toggleNotifications} className={`w-7 h-7 rounded-full flex items-center justify-center ${state.settings.notificationsEnabled ? 'bg-gold-classic' : 'bg-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-[9px]`}></i></button>
              <button onClick={onLogout} className="w-7 h-7 bg-white/10 rounded-full flex items-center justify-center"><i className="fas fa-power-off text-[9px] text-rose-300"></i></button>
            </div>
          </div>

          <div className="flex gap-1.5">
            <div className="flex-1 bg-white/5 p-2 rounded-xl border border-white/10">
              <span className="text-[7px] text-emerald-300/60 uppercase font-black block">{t('dhikr')}</span>
              <span className="text-sm font-black tabular-nums">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 bg-white/5 p-2 rounded-xl border border-white/10">
              <span className="text-[7px] text-emerald-300/60 uppercase font-black block">{t('lastRead')}</span>
              <span className="text-[10px] font-bold truncate block">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Scroll-free content area */}
      <div className="flex-1 px-3 flex flex-col justify-around py-2 overflow-hidden">
        {/* Next Prayer - Tighter */}
        <div className="bg-white p-3 rounded-2xl shadow-sm border border-emerald-50 relative overflow-hidden">
          <div className="flex items-center justify-between gap-2">
            <div className="ltr:text-left">
              <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest block mb-0.5">{t('nextPrayer')}</span>
              <div className="flex items-center gap-1">
                <h2 className="text-lg font-black text-emerald-900 capitalize">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <span className="text-[7px] font-bold text-emerald-700 bg-emerald-50 px-1 rounded">{prayerTimingData?.next.time}</span>
              </div>
            </div>
            <div className="ltr:text-right">
              <span className="text-lg font-black text-gold-classic tabular-nums">{prayerTimingData?.timeLeft || '--:--'}</span>
              <span className="text-[7px] font-bold text-slate-400 block uppercase">Left</span>
            </div>
          </div>
          <div className="w-full bg-slate-100 h-1 rounded-full overflow-hidden mt-2">
            <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
          </div>
        </div>

        {/* Hadith - Ultra compact */}
        <div className="bg-white p-3 rounded-2xl border border-emerald-50 shadow-sm overflow-hidden">
          <span className="bg-emerald-600/10 text-emerald-800 text-[6px] font-black px-1.5 py-0.5 rounded-full uppercase mb-1 inline-block">HADITH</span>
          <p className="text-emerald-900 arabic-font text-[11px] leading-tight text-right mb-1" dir="rtl">{dailyHadith.arabic}</p>
          <p className="text-slate-500 italic text-[8px] leading-tight line-clamp-2">"{dailyHadith[userLang]}"</p>
        </div>

        {/* Prayer Grid Summary - Tighter */}
        <div className="bg-white p-3 rounded-2xl shadow-sm border border-emerald-50">
          <div className="flex justify-between items-center mb-2">
             <h3 className="text-[8px] font-black text-emerald-900 uppercase">{t('todayPrayers')}</h3>
             {state.isHaydNifas && <span className="text-[6px] px-1 bg-rose-50 text-rose-600 rounded-full">{t('excused')}</span>}
          </div>
          <div className="grid grid-cols-5 gap-1">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              return (
                <button key={p} disabled={state.isHaydNifas} onClick={() => handlePrayerToggle(p)} className={`flex flex-col items-center p-1.5 rounded-xl border ${status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-slate-50 border-transparent text-slate-400'} ${state.isHaydNifas ? 'opacity-40' : ''}`}>
                  <span className="text-[6px] font-black uppercase mb-1">{t(p).substring(0,3)}</span>
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white border border-slate-100'}`}>
                    <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-circle'} text-[6px]`}></i>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {/* Navigation Grid - 2x4 for perfect fit */}
        <div className="grid grid-cols-4 gap-2">
          {menuItems.map((item) => (
            <button key={item.id} onClick={() => setCurrentView(item.id)} className={`flex flex-col items-center justify-center p-2 rounded-2xl bg-gradient-to-br ${item.color} border border-white shadow-sm active-scale`}>
              <i className={`fas ${item.icon} text-sm mb-1 ${item.iconColor}`}></i>
              <span className="text-[7px] font-black text-center uppercase tracking-tighter truncate w-full">{item.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] overflow-hidden view-transition">
      <div className="p-4 pt-10 pb-4 bg-emerald-900 text-white shrink-0 shadow-lg rounded-b-[32px]">
        <div className="flex items-center gap-3 mb-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-lg font-bold tracking-tight">{t('fard')}</h1>
        </div>
        <div className="flex bg-white/5 p-1 rounded-xl">
          <button onClick={() => setActiveTab('fard')} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest ${activeTab === 'fard' ? 'bg-white text-emerald-900 shadow' : 'text-white/60'}`}>{t('fard')}</button>
          <button onClick={() => setActiveTab('sunnah')} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest ${activeTab === 'sunnah' ? 'bg-white text-emerald-900 shadow' : 'text-white/60'}`}>{t('sunnah')}</button>
        </div>
      </div>

      <div className="flex-1 p-3 flex flex-col justify-between overflow-hidden">
        <div className="text-center mb-3 shrink-0">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-emerald-50 pb-1">
            {new Date().toLocaleDateString(state.profile?.preferredLanguage || 'en', { weekday: 'long', day: 'numeric', month: 'short' })}
          </span>
        </div>

        <div className="grid grid-cols-2 gap-2 flex-1">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p) => {
            const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
            const isMissed = activeTab === 'fard' && fardLogs[p as any] === PrayerStatus.MISSED;

            return (
              <button
                key={p}
                onClick={() => handleToggle(p, activeTab)}
                disabled={isExcused}
                className={`relative flex flex-col items-center justify-center p-3 rounded-2xl border transition-all h-24 ${
                  isDone ? 'bg-emerald-50 border-emerald-200' : isMissed ? 'bg-rose-50 border-rose-200' : 'bg-white border-emerald-50 shadow-sm'
                } ${isExcused ? 'opacity-40 grayscale' : 'active-scale'}`}
              >
                <span className={`text-[10px] font-black uppercase tracking-widest mb-2 ${isDone ? 'text-emerald-800' : 'text-slate-800'}`}>
                  {t(p).split(' ')[0]}
                </span>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${isDone ? 'bg-emerald-600 text-white' : 'bg-white border border-slate-100 text-slate-300'}`}>
                  <i className={`fas ${isDone ? 'fa-check' : 'fa-hand-pointer'} text-[10px]`}></i>
                </div>
                {activeTab === 'fard' && !isDone && !isExcused && (
                   <div onClick={(e) => { e.stopPropagation(); updatePrayerStatus(today, p as any, PrayerStatus.MISSED); }} className="absolute top-1 right-1 w-5 h-5 bg-rose-500 rounded-full flex items-center justify-center text-white text-[8px] shadow-sm"><i className="fas fa-times"></i></div>
                )}
              </button>
            );
          })}
        </div>

        <div className="py-4 text-center border-t border-emerald-50 shrink-0">
          <p className="arabic-font text-emerald-800 text-[11px]" dir="rtl">أَقِمِ الصَّلَاةَ لِدُلُوكِ الشَّمْسِ</p>
          <p className="text-slate-400 text-[7px] font-medium italic mt-1 leading-none italic opacity-70 px-4">"Establish prayer at the decline of the sun..." (17:78)</p>
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState, useMemo } from 'react';
import { UserData, PrayerStatus, QadaReminder, PrayerTimings, HealthPeriod } from '../types';
import { PRAYERS } from '../constants';

interface QadahCalendarProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  updateReminders: (reminders: QadaReminder[]) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QadahCalendar: React.FC<QadahCalendarProps> = ({ state, updatePrayerStatus, updateReminders, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(new Date().toISOString().split('T')[0]);

  const month = viewDate.getMonth(), year = viewDate.getFullYear();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const days = useMemo(() => {
    const arr = [];
    for (let i = 0; i < firstDayOfMonth; i++) arr.push(null);
    for (let i = 1; i <= daysInMonth; i++) {
      arr.push(`${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`);
    }
    return arr;
  }, [month, year]);

  const selectedDayLogs = selectedDate ? (state.prayerLogs[selectedDate] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING }) : null;

  const handleStatus = (prayer: string, status: PrayerStatus) => {
    if (selectedDate) updatePrayerStatus(selectedDate, prayer as any, status);
  };

  const monthName = viewDate.toLocaleString('default', { month: 'short' });

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] animate-fade-up overflow-hidden">
      <div className="p-4 pt-10 pb-4 bg-[#064e3b] text-white flex items-center justify-between shrink-0 shadow-lg rounded-b-[32px]">
        <div className="flex items-center gap-3">
          <button onClick={() => setCurrentView('dashboard')} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-lg font-black tracking-tight">{t('qadah')}</h1>
        </div>
        <div className="text-[9px] font-black uppercase text-emerald-300 bg-white/5 px-2 py-1 rounded-lg border border-white/10">{monthName} {year}</div>
      </div>

      <div className="flex-1 p-3 flex flex-col gap-2 overflow-hidden justify-between">
        <div className="bg-white p-2.5 rounded-2xl border border-emerald-50 shadow-sm shrink-0">
          <div className="flex items-center justify-between mb-2">
            <button onClick={() => setViewDate(new Date(year, month - 1, 1))} className="w-7 h-7 flex items-center justify-center text-emerald-900"><i className="fas fa-chevron-left text-[9px]"></i></button>
            <h2 className="text-xs font-black text-[#064e3b] uppercase tracking-widest">{monthName} {year}</h2>
            <button onClick={() => setViewDate(new Date(year, month + 1, 1))} className="w-7 h-7 flex items-center justify-center text-emerald-900"><i className="fas fa-chevron-right text-[9px]"></i></button>
          </div>
          <div className="grid grid-cols-7 gap-1">
            {['S','M','T','W','T','F','S'].map(d => <span key={d} className="text-[7px] text-center font-black text-slate-300">{d}</span>)}
            {days.map((dateStr, idx) => {
              if (!dateStr) return <div key={`empty-${idx}`} className="h-6" />;
              const isSelected = selectedDate === dateStr, isToday = dateStr === new Date().toISOString().split('T')[0], dayNum = dateStr.split('-')[2];
              const h = isDateInHayd(dateStr);
              return (
                <button key={dateStr} onClick={() => setSelectedDate(dateStr)} className={`h-6 rounded-md flex items-center justify-center text-[9px] font-black transition-all ${isSelected ? 'bg-emerald-600 text-white' : isToday ? 'bg-emerald-50 text-emerald-600 border border-emerald-200' : h ? 'bg-pink-50 text-pink-400' : 'bg-slate-50 text-slate-400'}`}>{parseInt(dayNum)}</button>
              );
            })}
          </div>
        </div>

        {selectedDate && (
          <div className="bg-white rounded-2xl p-3 shadow-md border border-emerald-50 flex-1 overflow-hidden flex flex-col justify-between">
            <div className="flex justify-between items-center mb-2">
              <span className="text-[9px] font-black text-[#064e3b] uppercase tracking-widest">{new Date(selectedDate).toLocaleDateString(undefined, { day: 'numeric', month: 'short' })} LOG</span>
              {isDateInHayd(selectedDate) && <span className="text-[7px] font-black text-pink-600 uppercase">EXCUSED</span>}
            </div>

            <div className="grid grid-cols-2 gap-2 flex-1">
              {PRAYERS.map(prayer => {
                const s = isDateInHayd(selectedDate) ? PrayerStatus.EXCUSED : (selectedDayLogs?.[prayer] || PrayerStatus.PENDING);
                return (
                  <div key={prayer} className={`flex flex-col p-2 rounded-xl border ${s === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100' : s === PrayerStatus.MISSED ? 'bg-rose-50 border-rose-100' : 'bg-slate-50 border-slate-100'}`}>
                    <span className="text-[8px] font-black text-[#064e3b] uppercase mb-1">{t(prayer)}</span>
                    <div className="flex gap-1">
                      <button onClick={() => handleStatus(prayer, s === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} className={`flex-1 h-6 rounded flex items-center justify-center ${s === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white border text-slate-300'}`} disabled={isDateInHayd(selectedDate)}><i className="fas fa-check text-[8px]"></i></button>
                      <button onClick={() => handleStatus(prayer, s === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)} className={`flex-1 h-6 rounded flex items-center justify-center ${s === PrayerStatus.MISSED ? 'bg-rose-500 text-white' : 'bg-white border text-slate-300'}`} disabled={isDateInHayd(selectedDate)}><i className="fas fa-times text-[8px]"></i></button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default QadahCalendar;

import React, { useState, useMemo } from 'react';
import { UserData, FastingLog, PrayerTimings, HealthPeriod } from '../types';

interface FastingTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateFasting: (date: string, log: FastingLog) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const FastingTracker: React.FC<FastingTrackerProps> = ({ state, updateFasting, setCurrentView, t }) => {
  const [subView, setSubView] = useState<'stats' | 'ramadan' | 'sunnah'>('stats');
  const selectedYear = '1446H';
  const ramadanDays = Array.from({ length: 30 }, (_, i) => i + 1);

  const getRamadanLog = (day: number) => {
    const ramadanStartDate = new Date("2025-03-01");
    const targetDate = new Date(ramadanStartDate);
    targetDate.setDate(targetDate.getDate() + (day - 1));
    const h = state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime(), end = p.end ? new Date(p.end).getTime() : new Date().getTime() + 8640000000;
      return targetDate.getTime() >= start && targetDate.getTime() <= end;
    });
    if (h) return { status: 'excused', type: 'ramadan' } as FastingLog;
    return state.fastingLogs[`ramadan-${selectedYear}-${day}`] || { status: 'none', type: 'ramadan' };
  };

  const toggle = (day: number) => {
    const log = getRamadanLog(day);
    if (log.status === 'excused') return;
    const next: FastingLog['status'] = log.status === 'none' ? 'completed' : log.status === 'completed' ? 'missed' : 'none';
    updateFasting(`ramadan-${selectedYear}-${day}`, { status: next, type: 'ramadan' });
  };

  const stats = useMemo(() => {
    let c = 0, m = 0, e = 0;
    ramadanDays.forEach(d => {
      const l = getRamadanLog(d);
      if (l.status === 'completed') c++; else if (l.status === 'missed') m++; else if (l.status === 'excused') e++;
    });
    return { completed: c, pendingQada: m + e };
  }, [state.fastingLogs, state.healthPeriods]);

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] overflow-hidden view-transition">
      <div className="p-4 pt-10 pb-4 bg-emerald-900 text-white shrink-0 shadow-lg rounded-b-[32px]">
        <div className="flex items-center gap-3 mb-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-lg font-bold tracking-tight">{t('fasting')}</h1>
        </div>
        <div className="flex bg-white/5 p-1 rounded-xl">
          <button onClick={() => setSubView('stats')} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase ${subView === 'stats' ? 'bg-white text-emerald-900' : 'text-white/60'}`}>Stats</button>
          <button onClick={() => setSubView('ramadan')} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase ${subView === 'ramadan' ? 'bg-white text-emerald-900' : 'text-white/60'}`}>Ramadan</button>
          <button onClick={() => setSubView('sunnah')} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase ${subView === 'sunnah' ? 'bg-white text-emerald-900' : 'text-white/60'}`}>Sunnah</button>
        </div>
      </div>

      <div className="flex-1 p-3 flex flex-col justify-around overflow-hidden">
        {subView === 'stats' && (
          <div className="space-y-4 animate-fade-up">
            <div className="bg-white p-5 rounded-2xl border border-emerald-50 text-center shadow-sm">
               <span className="text-[9px] font-black text-slate-400 uppercase">Fasting Progress</span>
               <div className="flex justify-around items-center mt-3">
                 <div><p className="text-2xl font-black text-emerald-600">{stats.completed}</p><p className="text-[7px] uppercase">Done</p></div>
                 <div className="h-8 w-px bg-slate-100"></div>
                 <div><p className="text-2xl font-black text-rose-600">{stats.pendingQada}</p><p className="text-[7px] uppercase">Qada Due</p></div>
               </div>
            </div>
            <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100">
               <h4 className="text-amber-900 font-bold text-[8px] uppercase mb-1">Rulings</h4>
               <p className="text-amber-800/70 text-[9px] leading-tight font-semibold italic">Ramadan fasts missed due to illness or health periods must be recorded and made up (Qada) before the next Ramadan.</p>
            </div>
          </div>
        )}

        {subView === 'ramadan' && (
          <div className="flex-1 flex flex-col justify-between overflow-hidden animate-fade-up">
            <div className="flex-1 grid grid-cols-5 gap-1.5">
              {ramadanDays.map(day => {
                const log = getRamadanLog(day);
                return (
                  <button key={day} onClick={() => toggle(day)} className={`h-11 rounded-lg flex flex-col items-center justify-center border-2 ${log.status === 'completed' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : log.status === 'missed' ? 'bg-rose-50 border-rose-200 text-rose-700' : log.status === 'excused' ? 'bg-pink-50 border-pink-200 text-pink-700' : 'bg-slate-50 border-transparent text-slate-400'}`}>
                    <span className="text-[8px] font-black">{day}</span>
                    <i className={`fas ${log.status === 'completed' ? 'fa-check' : log.status === 'missed' ? 'fa-times' : log.status === 'excused' ? 'fa-droplet' : ''} text-[6px] mt-0.5`}></i>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {subView === 'sunnah' && (
          <div className="h-full flex items-center justify-center animate-fade-up text-center px-6">
            <div>
              <i className="fas fa-sun text-4xl text-amber-100 mb-3"></i>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Sunnah Tracking Coming Soon</p>
              <p className="text-slate-300 text-[8px] mt-1">Mondays, Thursdays, and Ayyam al-Bidh</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FastingTracker;

import React, { useState, useEffect } from 'react';
import { UserData, DhikrChallenge, PrayerTimings } from '../types';

interface DhikrCounterProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateProgress: (id: string, delta: number) => void;
  archiveChallenge: (id: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const ITEMS_PER_PAGE = 4;

const DhikrCounter: React.FC<DhikrCounterProps> = ({ state, updateProgress, archiveChallenge, setCurrentView, t }) => {
  const [activeChallengeId, setActiveChallengeId] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [historyPage, setHistoryPage] = useState(0);
  const [justCompleted, setJustCompleted] = useState(false);

  const activeChallenge = state.activeChallenges.find(c => c.id === activeChallengeId);

  const handleIncrement = () => {
    if (!activeChallengeId || !activeChallenge) return;
    if ('vibrate' in navigator) navigator.vibrate(40);
    if (activeChallenge.current < activeChallenge.target) {
      updateProgress(activeChallengeId, 1);
      if (activeChallenge.current + 1 === activeChallenge.target) {
        setJustCompleted(true);
        if ('vibrate' in navigator) navigator.vibrate([100, 50, 100]);
      }
    }
  };

  if (showHistory) {
    const totalPages = Math.ceil(state.dhikrHistory.length / ITEMS_PER_PAGE);
    const visibleHistory = state.dhikrHistory.slice(historyPage * ITEMS_PER_PAGE, (historyPage + 1) * ITEMS_PER_PAGE);

    return (
      <div className="flex flex-col h-full bg-[#fdfbf7] animate-fade-up">
        <div className="p-4 pt-10 pb-6 bg-[#064e3b] text-white shrink-0 shadow-lg rounded-b-[32px]">
          <div className="flex items-center gap-3">
            <button onClick={() => setShowHistory(false)} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-lg font-bold tracking-tight">{t('history')}</h1>
          </div>
        </div>
        <div className="flex-1 p-4 flex flex-col justify-between overflow-hidden">
          <div className="space-y-2 flex-1">
            {state.dhikrHistory.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full opacity-20"><i className="fas fa-box-open text-3xl mb-2"></i><p className="text-[10px] uppercase font-black">{t('noHistory')}</p></div>
            ) : (
              visibleHistory.map((entry) => {
                const perc = Math.round((entry.current / entry.target) * 100);
                return (
                  <div key={entry.id} className="bg-white p-3 rounded-2xl border border-emerald-50 shadow-sm">
                    <div className="flex justify-between items-start mb-1">
                      <h3 className="text-[10px] font-black text-[#064e3b] uppercase truncate w-2/3">{t(entry.title)}</h3>
                      <span className="text-[8px] font-black text-emerald-700 bg-emerald-50 px-1.5 rounded">{perc}%</span>
                    </div>
                    <p className="text-[7px] text-slate-400 font-bold uppercase mb-2">{new Date(entry.date).toLocaleDateString()}</p>
                    <div className="w-full bg-slate-50 h-1 rounded-full overflow-hidden"><div className="bg-emerald-500 h-full" style={{ width: `${Math.min(100, perc)}%` }}></div></div>
                  </div>
                );
              })
            )}
          </div>
          {totalPages > 1 && (
            <div className="flex justify-between items-center bg-white p-2 rounded-xl border border-emerald-50 shadow-sm shrink-0">
               <button disabled={historyPage === 0} onClick={() => setHistoryPage(p => p - 1)} className="w-8 h-8 flex items-center justify-center bg-emerald-50 rounded-lg disabled:opacity-30"><i className="fas fa-chevron-left text-[8px]"></i></button>
               <span className="text-[8px] font-black uppercase text-slate-400">Page {historyPage + 1} of {totalPages}</span>
               <button disabled={historyPage === totalPages - 1} onClick={() => setHistoryPage(p => p + 1)} className="w-8 h-8 flex items-center justify-center bg-emerald-50 rounded-lg disabled:opacity-30"><i className="fas fa-chevron-right text-[8px]"></i></button>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (activeChallengeId && activeChallenge) {
    return (
      <div className="flex flex-col h-full bg-[#fdfbf7] animate-fade-up">
        <div className="p-4 pt-10 pb-6 bg-[#064e3b] text-white shrink-0 shadow-lg rounded-b-[32px]">
          <div className="flex items-center gap-3">
            <button onClick={() => { setActiveChallengeId(null); setJustCompleted(false); }} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-lg font-bold tracking-tight truncate w-2/3">{t(activeChallenge.title)}</h1>
          </div>
        </div>

        <div className="flex-1 p-4 flex flex-col items-center justify-around overflow-hidden">
          <div className="text-center">
            <p className="arabic-font text-3xl text-[#064e3b] font-bold mb-1" dir="rtl">{activeChallenge.arabic}</p>
            <p className="text-slate-400 text-[8px] font-bold uppercase tracking-widest">{t(activeChallenge.title)}</p>
          </div>

          <button onClick={handleIncrement} disabled={activeChallenge.current >= activeChallenge.target} className="relative w-40 h-40 group flex items-center justify-center active-scale">
             <div className="absolute inset-0 bg-gradient-to-br from-emerald-500 to-[#064e3b] rounded-full shadow-xl border-4 border-white/30 flex items-center justify-center overflow-hidden">
                <span className="text-white text-5xl font-black">{activeChallenge.current}</span>
             </div>
          </button>

          <div className="w-full max-w-xs space-y-4">
            <div className="bg-white p-4 rounded-2xl shadow-md border border-emerald-50 text-center relative overflow-hidden h-32 flex flex-col justify-center">
               {justCompleted ? (
                 <div className="animate-fade-up">
                    <i className="fas fa-check-circle text-emerald-600 text-2xl mb-1"></i>
                    <h3 className="text-emerald-900 font-black uppercase text-[10px] mb-2">COMPLETE</h3>
                    <button onClick={() => { archiveChallenge(activeChallengeId); setActiveChallengeId(null); setJustCompleted(false); }} className="bg-emerald-600 text-white px-4 py-1.5 rounded-full font-black text-[8px] uppercase">Archive</button>
                 </div>
               ) : (
                 <>
                   <div className="flex justify-between items-end mb-2 px-1 text-[8px] font-black uppercase text-slate-400"><span>Progress</span><span>{activeChallenge.current} / {activeChallenge.target}</span></div>
                   <div className="w-full bg-emerald-50 h-1.5 rounded-full overflow-hidden mb-3"><div className="bg-[#064e3b] h-full transition-all duration-300" style={{ width: `${Math.min(100, (activeChallenge.current/activeChallenge.target)*100)}%` }}></div></div>
                   <p className="text-[7px] text-slate-300 font-bold uppercase">{t('tapToCount')}</p>
                 </>
               )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] animate-fade-up">
      <div className="p-4 pt-10 pb-6 bg-[#064e3b] text-white flex items-center justify-between shrink-0 shadow-lg rounded-b-[32px]">
        <div className="flex items-center gap-3">
          <button onClick={() => setCurrentView('dashboard')} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-lg font-bold tracking-tight">{t('dhikrList')}</h1>
        </div>
        <button onClick={() => setShowHistory(true)} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-history text-xs"></i></button>
      </div>

      <div className="flex-1 p-3 flex flex-col gap-2 overflow-hidden justify-around">
        <div className="grid grid-cols-1 gap-1.5">
          {state.activeChallenges.slice(0, 4).map((challenge) => {
            const perc = Math.min(100, (challenge.current / challenge.target) * 100);
            return (
              <button key={challenge.id} onClick={() => setActiveChallengeId(challenge.id)} className="flex flex-col p-3 rounded-2xl bg-white border border-emerald-50 shadow-sm active-scale text-left">
                <div className="flex justify-between items-start mb-1">
                  <h3 className="text-[10px] font-black text-[#064e3b] uppercase truncate w-2/3">{t(challenge.title)}</h3>
                  <i className={`fas ${perc === 100 ? 'fa-check-circle text-emerald-500' : 'fa-play text-slate-200'} text-[9px]`}></i>
                </div>
                <div className="w-full bg-slate-50 h-1 rounded-full overflow-hidden"><div className="bg-emerald-600 h-full" style={{ width: `${perc}%` }}></div></div>
              </button>
            );
          })}
        </div>
        <div className="bg-emerald-50 p-3 rounded-2xl border border-emerald-100 text-center">
           <p className="text-[#064e3b]/60 text-[8px] italic leading-tight px-4">"Verily, in the remembrance of Allah do hearts find rest." (13:28)</p>
        </div>
      </div>
    </div>
  );
};

export default DhikrCounter;

