import React, { useState, useEffect } from 'react';
import { UserData, DhikrChallenge, PrayerTimings } from '../types';

interface DhikrCounterProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateProgress: (id: string, delta: number) => void;
  archiveChallenge: (id: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const ITEMS_PER_PAGE = 4;

const DhikrCounter: React.FC<DhikrCounterProps> = ({ state, updateProgress, archiveChallenge, setCurrentView, t }) => {
  const [activeChallengeId, setActiveChallengeId] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [historyPage, setHistoryPage] = useState(0);
  const [justCompleted, setJustCompleted] = useState(false);

  const activeChallenge = state.activeChallenges.find(c => c.id === activeChallengeId);

  const handleIncrement = () => {
    if (!activeChallengeId || !activeChallenge) return;
    if ('vibrate' in navigator) navigator.vibrate(40);
    if (activeChallenge.current < activeChallenge.target) {
      updateProgress(activeChallengeId, 1);
      if (activeChallenge.current + 1 === activeChallenge.target) {
        setJustCompleted(true);
        if ('vibrate' in navigator) navigator.vibrate([100, 50, 100]);
      }
    }
  };

  if (showHistory) {
    const totalPages = Math.ceil(state.dhikrHistory.length / ITEMS_PER_PAGE);
    const visibleHistory = state.dhikrHistory.slice(historyPage * ITEMS_PER_PAGE, (historyPage + 1) * ITEMS_PER_PAGE);

    return (
      <div className="flex flex-col h-full bg-[#f8fafc] animate-fade-up">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(false)} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-xl font-bold tracking-tight">{t('history')}</h1>
          </div>
        </div>
        <div className="flex-1 p-5 flex flex-col justify-between overflow-hidden">
          <div className="space-y-3 flex-1">
            {state.dhikrHistory.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full opacity-10 grayscale"><i className="fas fa-box-open text-6xl mb-4"></i><p className="text-xs uppercase font-black tracking-widest">{t('noHistory')}</p></div>
            ) : (
              visibleHistory.map((entry) => {
                const perc = Math.round((entry.current / entry.target) * 100);
                return (
                  <div key={entry.id} className="bg-white p-4 rounded-3xl border border-slate-50 shadow-premium group">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h3 className="text-[11px] font-black text-[#064e3b] uppercase tracking-wide truncate w-48">{t(entry.title)}</h3>
                        <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-1">{new Date(entry.date).toLocaleDateString()}</p>
                      </div>
                      <span className="text-[10px] font-black text-[#c5a059] bg-[#c5a059]/10 px-2 py-1 rounded-lg">{perc}%</span>
                    </div>
                    <div className="w-full bg-slate-50 h-1.5 rounded-full overflow-hidden p-0.5"><div className="bg-[#c5a059] h-full rounded-full transition-all" style={{ width: `${Math.min(100, perc)}%` }}></div></div>
                  </div>
                );
              })
            )}
          </div>
          {totalPages > 1 && (
            <div className="flex justify-between items-center bg-white p-2.5 rounded-2xl border border-slate-100 shadow-premium shrink-0">
               <button disabled={historyPage === 0} onClick={() => setHistoryPage(p => p - 1)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-xl disabled:opacity-20 active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Page {historyPage + 1} of {totalPages}</span>
               <button disabled={historyPage === totalPages - 1} onClick={() => setHistoryPage(p => p + 1)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-xl disabled:opacity-20 active:scale-90 transition-all"><i className="fas fa-chevron-right text-xs"></i></button>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (activeChallengeId && activeChallenge) {
    return (
      <div className="flex flex-col h-full bg-[#f8fafc] animate-fade-up">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={() => { setActiveChallengeId(null); setJustCompleted(false); }} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-lg font-bold tracking-tight truncate w-2/3">{t(activeChallenge.title)}</h1>
          </div>
        </div>

        <div className="flex-1 p-6 flex flex-col items-center justify-around overflow-hidden">
          <div className="text-center w-full">
            <p className="arabic-font text-5xl text-[#064e3b] font-bold mb-3 drop-shadow-sm" dir="rtl">{activeChallenge.arabic}</p>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">{t(activeChallenge.title)}</p>
          </div>

          <button 
            onClick={handleIncrement} 
            disabled={activeChallenge.current >= activeChallenge.target} 
            className="relative w-48 h-48 group flex items-center justify-center transition-all duration-150 active:scale-[0.92]"
          >
             <div className="absolute inset-0 bg-gradient-to-br from-[#10b981] to-[#064e3b] rounded-full shadow-[0_25px_50px_-12px_rgba(6,78,59,0.4)] border-8 border-white flex items-center justify-center overflow-hidden">
                <div className="absolute inset-0 bg-white opacity-0 group-active:opacity-10 transition-opacity"></div>
                <span className="text-white text-6xl font-black drop-shadow-lg tracking-tighter">{activeChallenge.current}</span>
             </div>
             {/* Ring Progress Overlay */}
             <div className="absolute inset-[-10px] border-4 border-slate-100 rounded-full"></div>
             <div className="absolute inset-[-10px] border-4 border-[#c5a059] rounded-full transition-all duration-300 opacity-20" style={{ clipPath: `inset(0 ${100 - (activeChallenge.current/activeChallenge.target)*100}% 0 0)` }}></div>
          </button>

          <div className="w-full max-w-xs space-y-4">
            <div className="bg-white p-5 rounded-[42px] shadow-premium border border-slate-50 text-center relative overflow-hidden h-36 flex flex-col justify-center">
               {justCompleted ? (
                 <div className="animate-fade-up flex flex-col items-center">
                    <div className="w-10 h-10 bg-emerald-100 rounded-full flex items-center justify-center mb-2 animate-bounce">
                      <i className="fas fa-check text-emerald-600 text-lg"></i>
                    </div>
                    <h3 className="text-emerald-900 font-black uppercase text-xs tracking-widest mb-3">Mabrook! Complete</h3>
                    <button onClick={() => { archiveChallenge(activeChallengeId); setActiveChallengeId(null); setJustCompleted(false); }} className="bg-[#c5a059] text-white px-8 py-2.5 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all">Archive</button>
                 </div>
               ) : (
                 <>
                   <div className="flex justify-between items-end mb-2 px-1 text-[10px] font-black uppercase tracking-widest text-slate-400"><span>Progress</span><span className="text-emerald-900 font-bold">{activeChallenge.current} / {activeChallenge.target}</span></div>
                   <div className="w-full bg-slate-50 h-2 rounded-full overflow-hidden p-0.5 shadow-inner mb-3"><div className="bg-[#064e3b] h-full rounded-full transition-all duration-300 shadow-[0_0_8px_rgba(6,78,59,0.3)]" style={{ width: `${Math.min(100, (activeChallenge.current/activeChallenge.target)*100)}%` }}></div></div>
                   <p className="text-[9px] text-slate-300 font-black uppercase tracking-[0.2em]">{t('tapToCount')}</p>
                 </>
               )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] animate-fade-up">
      <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white flex items-center justify-between shrink-0 shadow-emerald-premium rounded-b-[42px]">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-xl font-bold tracking-tight">{t('dhikrList')}</h1>
        </div>
        <button onClick={() => setShowHistory(true)} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-history text-xs"></i></button>
      </div>

      <div className="flex-1 p-4 flex flex-col gap-3 overflow-hidden justify-around">
        <div className="grid grid-cols-1 gap-2.5">
          {state.activeChallenges.slice(0, 4).map((challenge) => {
            const perc = Math.min(100, (challenge.current / challenge.target) * 100);
            return (
              <button key={challenge.id} onClick={() => setActiveChallengeId(challenge.id)} className="flex flex-col p-4 rounded-3xl bg-white border border-slate-50 shadow-premium active:scale-[0.98] transition-all text-left group">
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-[11px] font-black text-[#064e3b] uppercase tracking-wide truncate w-2/3 group-hover:text-emerald-700">{t(challenge.title)}</h3>
                  <div className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${perc === 100 ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-50 text-slate-300 group-hover:bg-emerald-50 group-hover:text-emerald-600'}`}>
                    <i className={`fas ${perc === 100 ? 'fa-check' : 'fa-play'} text-[10px]`}></i>
                  </div>
                </div>
                <div className="w-full bg-slate-50 h-1.5 rounded-full overflow-hidden p-0.5"><div className="bg-[#064e3b] h-full rounded-full transition-all" style={{ width: `${perc}%` }}></div></div>
              </button>
            );
          })}
        </div>
        <div className="bg-emerald-50/50 p-4 rounded-3xl border border-emerald-100 text-center relative overflow-hidden">
           <div className="absolute top-0 right-0 p-2 opacity-[0.05] pointer-events-none"><i className="fas fa-leaf text-4xl"></i></div>
           <p className="text-[#064e3b]/80 text-[10px] italic leading-relaxed font-medium px-4">"{t('remembranceVerse')}"</p>
        </div>
      </div>
    </div>
  );
};

