              <span className="text-[9px] sm:text-[11px] font-bold text-center uppercase tracking-tighter text-slate-600 truncate w-full group-hover:text-emerald-900">{item.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

