import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout }) => {
  const stats = useMemo(() => {
    let totalFard = 0;
    let completedFard = 0;
    let missedFard = 0;

    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
        if (status === PrayerStatus.MISSED) missedFard++;
      });
    });

    const totalFasting = Object.keys(state.fastingLogs).length;
    const completedFasting = Object.values(state.fastingLogs).filter(l => l.status === 'completed').length;

    // Simple consistency calculation
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 1;
    let level = 'levelBeginner';
    let color = 'text-slate-500';
    let bg = 'bg-slate-50';

    if (ratio > 0.9) {
      level = 'levelElite';
      color = 'text-gold-classic';
      bg = 'bg-[#f3e9d2]';
    } else if (ratio > 0.7) {
      level = 'levelAdvanced';
      color = 'text-emerald-600';
      bg = 'bg-emerald-50';
    } else if (ratio > 0.4) {
      level = 'levelConsistent';
      color = 'text-teal-600';
      bg = 'bg-teal-50';
    }

    return { completedFard, missedFard, completedFasting, level, color, bg, ratio };
  }, [state]);

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] overflow-hidden view-transition">
      <div className="p-6 pt-12 pb-8 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px] sm:rounded-b-[54px]">
        <div className="flex items-center gap-4 mb-6">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 sm:w-12 sm:h-12 flex items-center justify-center bg-white/10 rounded-xl sm:rounded-2xl border border-white/10 active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs sm:text-sm"></i></button>
          <div>
            <h1 className="text-xl sm:text-2xl font-bold tracking-tight">{t('myAccount')}</h1>
            <p className="text-[10px] sm:text-[12px] font-black text-emerald-300 uppercase tracking-widest opacity-60">Spiritual Profile</p>
          </div>
        </div>

        <div className="bg-white/5 backdrop-blur-md p-5 rounded-3xl border border-white/10 flex items-center gap-4">
          <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center border-4 border-white/20 shadow-lg">
             <i className="fas fa-user-circle text-emerald-900 text-3xl"></i>
          </div>
          <div className="overflow-hidden">
             <h2 className="text-lg font-black truncate">{state.profile.name}</h2>
             <p className="text-emerald-300 text-[10px] uppercase font-black tracking-widest">@{state.profile.username}</p>
          </div>
        </div>
      </div>

      <div className="flex-1 p-5 sm:p-8 flex flex-col justify-between overflow-hidden">
        {/* Consistency Level */}
        <div className={`p-5 rounded-3xl border border-slate-100 shadow-premium flex items-center justify-between ${stats.bg} transition-all`}>
           <div>
             <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('consistency')}</span>
             <h3 className={`text-xl font-black ${stats.color}`}>{t(stats.level)}</h3>
           </div>
           <div className="w-12 h-12 rounded-full border-4 border-white shadow-md flex items-center justify-center bg-white">
              <span className="text-xs font-black text-emerald-900">{Math.round(stats.ratio * 100)}%</span>
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 gap-4 mt-4">
           <div className="bg-white p-4 rounded-3xl shadow-premium border border-slate-50">
              <i className="fas fa-check-circle text-emerald-500 text-sm mb-2"></i>
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block">{t('completed')}</span>
              <p className="text-xl font-black text-emerald-900">{stats.completedFard}</p>
           </div>
           <div className="bg-white p-4 rounded-3xl shadow-premium border border-slate-50">
              <i className="fas fa-times-circle text-rose-500 text-sm mb-2"></i>
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block">{t('missed')}</span>
              <p className="text-xl font-black text-rose-900">{stats.missedFard}</p>
           </div>
           <div className="bg-white p-4 rounded-3xl shadow-premium border border-slate-50">
              <i className="fas fa-moon text-indigo-500 text-sm mb-2"></i>
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block">{t('fasting')}</span>
              <p className="text-xl font-black text-indigo-900">{stats.completedFasting}</p>
           </div>
           <div className="bg-white p-4 rounded-3xl shadow-premium border border-slate-50">
              <i className="fas fa-pray text-gold-classic text-sm mb-2"></i>
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block">{t('dhikr')}</span>
              <p className="text-xl font-black text-gold-classic">{state.dhikrCount.toLocaleString()}</p>
           </div>
