import React, { useState, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);
  const [usernameSuggestion, setUsernameSuggestion] = useState<string | null>(null);

  // Real-time username validation for registration
  useEffect(() => {
    if (mode === 'register' && formData.username.trim().length > 2) {
      const normalized = formData.username.trim().toLowerCase();
      if (users[normalized]) {
        // Generate suggestion
        const suggestion = `${normalized}${Math.floor(Math.random() * 999)}`;
        setUsernameSuggestion(suggestion);
      } else {
        setUsernameSuggestion(null);
      }
    } else {
      setUsernameSuggestion(null);
    }
  }, [formData.username, mode, users]);

  const validate = () => {
    const username = formData.username.trim().toLowerCase();
    if (!username) return "Username is required.";
    if (!formData.password.trim()) return "Password is required.";

    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (users[username]) return "Username is already taken.";
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setIsAuthenticating(true);
    const username = formData.username.trim().toLowerCase();

    // Professional authentication simulation
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[username];
        if (!user) {
          setError("User not found.");
          setIsAuthenticating(false);
          return;
        }
        if (user.profile.password !== formData.password) {
          setError("Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: username,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const applySuggestion = () => {
    if (usernameSuggestion) {
      setFormData({ ...formData, username: usernameSuggestion });
      setUsernameSuggestion(null);
    }
  };

  const inputClasses = "w-full px-4 py-2.5 bg-white border border-emerald-50 rounded-[16px] focus:ring-2 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-xs";
  const labelClasses = "block text-[8px] font-bold text-slate-500 uppercase tracking-widest ml-1 mb-0.5";

  return (
    <div className="p-5 flex flex-col items-center justify-center h-full bg-[#fdfbf7] view-transition overflow-hidden">
      <div className="w-14 h-14 bg-emerald-900 rounded-[24px] flex items-center justify-center mb-3 shadow-xl border-2 border-white rotate-3 shrink-0">
        <i className="fas fa-mosque text-xl text-emerald-100"></i>
      </div>
      <h1 className="text-2xl font-black text-emerald-900 mb-1 tracking-tighter shrink-0">Ibadathi</h1>
      <div className="h-0.5 w-6 bg-gold-classic rounded-full mb-4 shrink-0"></div>

      <div className="flex bg-emerald-50 p-1 rounded-xl mb-4 w-full max-w-[200px] shrink-0">
        <button 
          type="button"
          onClick={() => { setMode('login'); setError(null); }}
          className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('login')}
        </button>
        <button 
          type="button"
          onClick={() => { setMode('register'); setError(null); }}
          className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('register')}
        </button>
      </div>

      <form onSubmit={handleSubmit} className="w-full space-y-2.5 max-w-[280px] flex-1 flex flex-col justify-center overflow-hidden">
        {error && (
          <div className="bg-rose-50 text-rose-600 p-2 rounded-lg text-[8px] font-bold text-center border border-rose-100 animate-pulse shrink-0">
            <i className="fas fa-exclamation-circle mr-1"></i> {error}
          </div>
        )}

        <div className="space-y-0.5 shrink-0">
          <label className={labelClasses}>{t('username')}</label>
          <input 
            type="text" 
            className={`${inputClasses} ${usernameSuggestion ? 'border-amber-200 bg-amber-50/10' : ''}`}
            placeholder="muslim_seeker"
            value={formData.username}
            onChange={e => setFormData({...formData, username: e.target.value})}
            required
          />
          {usernameSuggestion && (
            <div className="mt-1 flex items-center justify-between px-1">
              <span className="text-[7px] font-bold text-amber-600 uppercase tracking-tighter">Taken. Try this:</span>
              <button 
                type="button"
                onClick={applySuggestion}
                className="text-[7px] font-black text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-100 hover:bg-emerald-100 transition-colors"
              >
                {usernameSuggestion}
              </button>
            </div>
          )}
        </div>

        {mode === 'register' ? (
          <div className="space-y-2.5 shrink-0">
            <div className="space-y-0.5">
              <label className={labelClasses}>{t('name')}</label>
              <input 
                type="text"
                className={inputClasses}
                placeholder="Abdullah Al-Fulan"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-0.5">
                <label className={labelClasses}>{t('age')}</label>
                <input 
                  type="number"
                  className={inputClasses}
                  placeholder="25"
                  value={formData.age}
                  onChange={e => setFormData({...formData, age: e.target.value})}
                  required
                />
              </div>
              <div className="space-y-0.5">
                <label className={labelClasses}>{t('sex')}</label>
                <select 
                  className={`${inputClasses} appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22none%22%20viewBox%3D%220%200%2024%2024%22%20stroke%3D%22%2364748b%22%3E%3Cpath%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%222%22%20d%3D%22M19%209l-7%207-7-7%22%20%2F%3E%3C%2Fsvg%3E')] bg-[length:0.7em_0.7em] bg-[right_0.75rem_center] bg-no-repeat`}
                  value={formData.sex}
                  onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                >
                  <option value="male">{t('male')}</option>
                  <option value="female">{t('female')}</option>
                </select>
              </div>
            </div>

            <div className="space-y-0.5">
              <label className={labelClasses}>{t('place')}</label>
              <input 
                type="text"
                className={inputClasses}
                placeholder="Makkah, KSA"
                value={formData.place}
                onChange={e => setFormData({...formData, place: e.target.value})}
                required
              />
            </div>
          </div>
        ) : null}

        <div className="space-y-0.5 shrink-0">
          <label className={labelClasses}>{t('password')}</label>
          <input 
            type="password"
            className={inputClasses}
            placeholder="••••••••"
            value={formData.password}
            onChange={e => setFormData({...formData, password: e.target.value})}
            required
          />
        </div>

        <button 
          type="submit"
          disabled={isAuthenticating}
          className="w-full bg-emerald-900 text-white font-black py-3 rounded-[16px] transition-all active:scale-[0.98] mt-2 uppercase tracking-[0.2em] text-[9px] flex items-center justify-center gap-2 shrink-0 disabled:opacity-50 shadow-lg shadow-emerald-900/20"
        >
          {isAuthenticating ? (
            <i className="fas fa-spinner fa-spin"></i>
          ) : (
            mode === 'login' ? t('login') : t('register')
          )}
        </button>
      </form>

      <div className="mt-4 flex items-center gap-2 opacity-10 shrink-0">
        <i className="fas fa-hand-holding-heart text-emerald-900 text-lg"></i>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import ZakatCalculator from './components/ZakatCalculator';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// Solid, versioned storage keys to prevent "user not found" issues
const USERS_STORAGE_KEY = 'ibadathi_users_registry_v1.0';
const SESSION_KEY = 'ibadathi_current_session_v1.0';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 100, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 100, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 100, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12",
  Sunrise: "06:34",
  Dhuhr: "12:28",
  Asr: "15:42",
  Maghrib: "18:22",
  Isha: "19:38"
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);

      // Ensure we always have an object for users
      const parsedUsers = savedUsers ? JSON.parse(savedUsers) : {};

      return {
        currentUser: activeSession,
        users: parsedUsers,
        todayTimings: DEFAULT_TIMINGS
      };
    } catch (e) {
      console.error("Critical storage failure", e);
      return { currentUser: null, users: {}, todayTimings: DEFAULT_TIMINGS };
    }
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      return state.users[state.currentUser].profile.preferredLanguage;
    }
    return 'en';
  });

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'zakat' | 'account'>(() => {
    return state.currentUser ? 'dashboard' : 'welcome';
  });

  // Critical effect for real-time storage sync
  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();

    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username }, // Normalize username
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };

      setState(prev => ({
        ...prev,
        currentUser: username,
        users: { ...prev.users, [username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }

    setCurrentLanguage(profile.preferredLanguage);
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const currentUser = prev.currentUser!;
      const userToUpdate = prev.users[currentUser];
      if (!userToUpdate) return prev;

      return {
        ...prev,
        users: {
          ...prev.users,
          [currentUser]: updater(userToUpdate)
        }
      };
    });
  };

  // Worship handlers remain the same but are now more reliable due to better updateActiveUser logic
  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(user => {
      const currentLogs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return {
        ...user,
        prayerLogs: { ...user.prayerLogs, [date]: { ...currentLogs, [prayer]: status } }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(user => {
      const current = user.sunnahLogs[date] || [];
      const updated = current.includes(sunnahName) ? current.filter(s => s !== sunnahName) : [...current, sunnahName];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: updated } };
    });
  };

  const updateDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const updatedChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: Math.min(c.target, c.current + delta) } : c
      );
      return { ...user, activeChallenges: updatedChallenges, dhikrCount: user.dhikrCount + delta };
    });
  };

  const archiveDhikrChallenge = (id: string) => {
    updateActiveUser(user => {
      const challenge = user.activeChallenges.find(c => c.id === id);
      if (!challenge) return user;
      const historyEntry: DhikrHistoryEntry = {
        id: `${id}-${Date.now()}`,
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };
      const resetChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: 0 } : c
      );
      return { ...user, activeChallenges: resetChallenges, dhikrHistory: [historyEntry, ...user.dhikrHistory] };
    });
  };

  const updateQuran = (progress: QuranProgress) => {
    updateActiveUser(user => ({ ...user, quranProgress: progress }));
  };

  const updateFasting = (date: string, log: FastingLog) => {
    updateActiveUser(user => ({
      ...user,
      fastingLogs: { ...user.fastingLogs, [date]: log }
    }));
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(user => ({ ...user, isHaydNifas: active }));
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: [...user.healthPeriods, { id: Date.now().toString(), start, end }]
    }));
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: user.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateDhikrProgress} archiveChallenge={archiveDhikrChallenge} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={updateQuran} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={updateFasting} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'zakat':
        return <ZakatCalculator setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
