import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;
    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) navigator.vibrate([20, 40]);
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', color: 'bg-white text-emerald-800', iconBg: 'bg-emerald-50' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', color: 'bg-white text-teal-800', iconBg: 'bg-teal-50' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', color: 'bg-white text-amber-900', iconBg: 'bg-amber-50' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', color: 'bg-white text-blue-900', iconBg: 'bg-blue-50' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', color: 'bg-white text-indigo-900', iconBg: 'bg-indigo-50' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', color: 'bg-white text-green-900', iconBg: 'bg-green-50' },
    { id: 'account', label: t('myAccount'), icon: 'fa-user-circle', color: 'bg-white text-gold-900', iconBg: 'bg-[#f3e9d2]' },
    ...(state.profile?.sex === 'female' ? [{ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', color: 'bg-white text-rose-900', iconBg: 'bg-rose-50' }] : [])
  ];

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name, timingsMinutes };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="h-full w-full flex flex-col bg-[#f8fafc] overflow-hidden view-transition pt-10 sm:pt-14 lg:pt-16">
      {/* Header Profile Section */}
      <header className="relative w-full bg-[#064e3b] text-white pt-6 pb-10 px-6 sm:px-8 rounded-b-[42px] sm:rounded-b-[54px] shadow-emerald-premium shrink-0">
        <div className="absolute top-0 right-0 w-48 h-48 bg-[#c5a059] opacity-[0.07] rounded-full blur-[60px] -mr-20 -mt-20"></div>
        <div className="relative z-10 w-full flex flex-col gap-4">
          <div className="flex justify-between items-center w-full">
            <div className="flex items-center gap-3">
              <div 
                onClick={() => setCurrentView('account')}
                className="w-10 h-10 sm:w-12 sm:h-12 bg-white/10 rounded-xl sm:rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-md cursor-pointer active:scale-90 transition-all"
              >
                <i className="fas fa-user text-emerald-200 text-sm sm:text-base"></i>
              </div>
              <div>
                <span className="text-[9px] sm:text-[10px] font-black text-emerald-300 uppercase tracking-widest block opacity-70">Marhaban</span>
                <h1 className="text-base sm:text-lg font-bold truncate max-w-[140px] sm:max-w-[200px] tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setCurrentView('about')} className="w-9 h-9 sm:w-10 sm:h-10 rounded-xl flex items-center justify-center bg-white/10 border border-white/10 hover:bg-white/20 transition-all active:scale-95"><i className="fas fa-info text-[10px] sm:text-xs"></i></button>
              <button onClick={toggleNotifications} className={`w-9 h-9 sm:w-10 sm:h-10 rounded-xl flex items-center justify-center border transition-all active:scale-95 ${state.settings.notificationsEnabled ? 'bg-[#c5a059] border-[#c5a059] shadow-lg' : 'bg-white/10 border-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-[10px] sm:text-xs`}></i></button>
            </div>
          </div>

          <div className="flex gap-3">
            <div className="flex-1 bg-white/5 backdrop-blur-sm p-3 rounded-2xl sm:rounded-3xl border border-white/10">
              <span className="text-[7px] sm:text-[9px] text-emerald-300/80 uppercase font-black tracking-widest block mb-0.5">{t('dhikr')}</span>
              <span className="text-base sm:text-xl font-black tabular-nums tracking-tighter">{state.dhikrCount.toLocaleString()}</span>
            </div>
            <div className="flex-1 bg-white/5 backdrop-blur-sm p-3 rounded-2xl sm:rounded-3xl border border-white/10">
              <span className="text-[7px] sm:text-[9px] text-emerald-300/80 uppercase font-black tracking-widest block mb-0.5">{t('lastRead')}</span>
              <span className="text-[11px] sm:text-[13px] font-bold truncate block tracking-tight">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <div className="flex-1 px-5 sm:px-8 flex flex-col justify-around py-5 overflow-hidden">

        {/* Next Prayer Card */}
        <div className="bg-white p-5 rounded-3xl sm:rounded-[40px] shadow-premium border border-slate-50 relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-50 rounded-full blur-[30px] -mr-12 -mt-12 transition-all"></div>
          <div className="flex items-center justify-between gap-2 relative z-10">
            <div className="ltr:text-left">
              <span className="text-[9px] sm:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-1">{t('nextPrayer')}</span>
              <div className="flex items-center gap-3">
                <h2 className="text-xl sm:text-2xl font-black text-emerald-900 capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <span className="text-[10px] sm:text-[12px] font-black text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-lg border border-emerald-100">{prayerTimingData?.next.time}</span>
              </div>
            </div>
            <div className="ltr:text-right">
              <span className="text-2xl sm:text-3xl font-black text-[#c5a059] tabular-nums tracking-tighter">{prayerTimingData?.timeLeft || '--:--'}</span>
              <span className="text-[8px] sm:text-[10px] font-black text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>
          <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden mt-4 p-0.5">
            <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(16,185,129,0.3)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
          </div>
        </div>

        {/* Hadith Section */}
        <div className="bg-white p-5 rounded-3xl sm:rounded-[40px] border border-slate-50 shadow-premium overflow-hidden relative">
          <span className="bg-[#c5a059]/10 text-[#c5a059] text-[8px] sm:text-[10px] font-black px-2.5 py-1 rounded-full uppercase tracking-widest mb-3 inline-block">Daily Guidance</span>
          <p className="text-[#064e3b] arabic-font text-base sm:text-lg leading-tight text-right mb-3 font-bold" dir="rtl">{dailyHadith.arabic}</p>
          <p className="text-slate-500 italic text-[10px] sm:text-[12px] leading-relaxed line-clamp-2 border-l-2 border-emerald-50 pl-3">"{dailyHadith[userLang]}"</p>
        </div>

        {/* Today's Prayers Summary */}
        <div className="bg-white p-5 rounded-3xl sm:rounded-[40px] shadow-premium border border-slate-50">
          <div className="flex justify-between items-center mb-3">
             <h3 className="text-[10px] sm:text-[12px] font-black text-emerald-900 uppercase tracking-widest">{t('todayPrayers')}</h3>
             {state.isHaydNifas && <span className="text-[8px] font-bold px-2 py-0.5 bg-rose-50 text-rose-600 rounded-full border border-rose-100">{t('excused')}</span>}
          </div>
          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              return (
                <button 
                  key={p} 
                  disabled={state.isHaydNifas} 
                  onClick={() => handlePrayerToggle(p)} 
                  className={`flex flex-col items-center p-2.5 rounded-2xl sm:rounded-3xl border-2 transition-all active:scale-95 ${status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-100 text-emerald-800 shadow-sm' : 'bg-slate-50 border-transparent text-slate-300'} ${state.isHaydNifas ? 'opacity-30' : ''}`}
                >
                  <span className="text-[8px] sm:text-[10px] font-black uppercase mb-2 tracking-tighter">{t(p).substring(0,3)}</span>
                  <div className={`w-7 h-7 sm:w-9 sm:h-9 rounded-xl sm:rounded-2xl flex items-center justify-center shadow-sm transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white border border-slate-100'}`}>
                    <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-circle'} text-[10px] sm:text-xs`}></i>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {/* Navigation Grid - Adaptive Column Count */}
        <div className="grid grid-cols-4 sm:grid-cols-4 lg:grid-cols-4 gap-3">
          {menuItems.map((item) => (
            <button 
              key={item.id} 
              onClick={() => setCurrentView(item.id)} 
              className={`flex flex-col items-center justify-center p-3 rounded-3xl sm:rounded-[36px] transition-all active:scale-90 border border-slate-50 shadow-premium hover:shadow-lg group bg-white`}
            >
              <div className={`w-10 h-10 sm:w-12 sm:h-12 rounded-2xl sm:rounded-[20px] ${item.iconBg} flex items-center justify-center mb-2 transition-all group-hover:rotate-6`}>
                <i className={`fas ${item.icon} text-lg sm:text-xl`}></i>
              </div>
              <span className="text-[9px] sm:text-[11px] font-bold text-center uppercase tracking-tighter text-slate-600 truncate w-full group-hover:text-emerald-900">{item.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export type Language = 'en' | 'ml' | 'ta' | 'ar';

export enum PrayerStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  MISSED = 'missed',
  EXCUSED = 'excused'
}

export interface UserProfile {
  username: string;
  name: string;
  age: number;
  sex: 'male' | 'female';
  place: string;
  preferredLanguage: Language;
  password?: string; // Stored in mock backend
}

export interface PrayerLog {
  fajr: PrayerStatus;
  dhuhr: PrayerStatus;
  asr: PrayerStatus;
  maghrib: PrayerStatus;
  isha: PrayerStatus;
}

export interface FastingLog {
  status: 'none' | 'completed' | 'missed' | 'excused';
  type: 'ramadan' | 'sunnah';
}

export interface QuranProgress {
  surah: string;
  ayah: string;
  lastUpdated: string;
}

export interface DhikrChallenge {
  id: string;
  title: string;
  arabic: string;
  target: number;
  current: number;
  lastReset?: string;
}

export interface DhikrHistoryEntry {
  id: string;
  title: string;
  target: number;
  current: number;
  date: string;
}

export interface PrayerTimings {
  Fajr: string;
  Dhuhr: string;
  Asr: string;
  Maghrib: string;
  Isha: string;
  Sunrise: string;
}

export interface QadaReminder {
  id: string;
  time: string;
  enabled: boolean;
}

export interface HealthPeriod {
  id: string;
  start: string; // ISO Date string
  end: string | null; // null if active
}

// This represents the data for a SINGLE user
export interface UserData {
  profile: UserProfile;
  prayerLogs: Record<string, PrayerLog>;
  sunnahLogs: Record<string, string[]>;
  fastingLogs: Record<string, FastingLog>;
  quranProgress: QuranProgress;
  dhikrCount: number;
  activeChallenges: DhikrChallenge[];
  activeDhikrId: string | null; // Tracked active challenge for the counter
  dhikrHistory: DhikrHistoryEntry[];
  isHaydNifas: boolean;
  haydStartDate: string | null;
  healthPeriods: HealthPeriod[];
  settings: {
    notificationsEnabled: boolean;
    locationEnabled: boolean;
    qadaReminders: QadaReminder[];
  };
}

export interface AppState {
  currentUser: string | null; // username
  users: Record<string, UserData>; // Mock database
  todayTimings: PrayerTimings | null;
}

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// Solid, versioned storage keys to prevent "user not found" issues
const USERS_STORAGE_KEY = 'ibadathi_users_registry_v1.0';
const SESSION_KEY = 'ibadathi_current_session_v1.0';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12",
  Sunrise: "06:34",
  Dhuhr: "12:28",
  Asr: "15:42",
  Maghrib: "18:22",
  Isha: "19:38"
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const savedUsers = localStorage.getItem(USERS_STORAGE_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      const parsedUsers = savedUsers ? JSON.parse(savedUsers) : {};

      return {
        currentUser: activeSession,
        users: parsedUsers,
        todayTimings: DEFAULT_TIMINGS
      };
    } catch (e) {
      console.error("Critical storage failure", e);
      return { currentUser: null, users: {}, todayTimings: DEFAULT_TIMINGS };
    }
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      return state.users[state.currentUser].profile.preferredLanguage;
    }
    return 'en';
  });

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'account'>(() => {
    return state.currentUser ? 'dashboard' : 'welcome';
  });

  useEffect(() => {
    localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();

    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username },
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        activeDhikrId: null,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };

      setState(prev => ({
        ...prev,
        currentUser: username,
        users: { ...prev.users, [username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }

    setCurrentLanguage(profile.preferredLanguage);
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const currentUser = prev.currentUser!;
      const userToUpdate = prev.users[currentUser];
      if (!userToUpdate) return prev;

      return {
        ...prev,
        users: {
          ...prev.users,
          [currentUser]: updater(userToUpdate)
        }
      };
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(user => {
      const currentLogs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return {
        ...user,
        prayerLogs: { ...user.prayerLogs, [date]: { ...currentLogs, [prayer]: status } }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(user => {
      const current = user.sunnahLogs[date] || [];
      const updated = current.includes(sunnahName) ? current.filter(s => s !== sunnahName) : [...current, sunnahName];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: updated } };
    });
  };

  const setActiveDhikr = (id: string | null) => {
    updateActiveUser(user => ({ ...user, activeDhikrId: id }));
  };

  const updateDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const updatedChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: c.current + delta } : c
      );
      return { ...user, activeChallenges: updatedChallenges, dhikrCount: user.dhikrCount + delta };
    });
  };

  const archiveDhikrChallenge = (id: string) => {
    updateActiveUser(user => {
      const challenge = user.activeChallenges.find(c => c.id === id);
      if (!challenge) return user;
      const historyEntry: DhikrHistoryEntry = {
        id: `${id}-${Date.now()}`,
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };
      const resetChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: 0 } : c
      );
      return { 
        ...user, 
        activeChallenges: resetChallenges, 
        dhikrHistory: [historyEntry, ...user.dhikrHistory],
        activeDhikrId: null // Clear active on archive
      };
    });
  };

  const updateQuran = (progress: QuranProgress) => {
    updateActiveUser(user => ({ ...user, quranProgress: progress }));
  };

  const updateFasting = (date: string, log: FastingLog) => {
    updateActiveUser(user => ({
      ...user,
      fastingLogs: { ...user.fastingLogs, [date]: log }
    }));
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(user => ({ ...user, isHaydNifas: active }));
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: [...user.healthPeriods, { id: Date.now().toString(), start, end }]
    }));
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: user.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateDhikrProgress} archiveChallenge={archiveDhikrChallenge} setActiveDhikr={setActiveDhikr} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={updateQuran} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={updateFasting} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { UserData, DhikrChallenge, PrayerTimings } from '../types';

interface DhikrCounterProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateProgress: (id: string, delta: number) => void;
  archiveChallenge: (id: string) => void;
  setActiveDhikr: (id: string | null) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const ITEMS_PER_PAGE = 4;

const DhikrCounter: React.FC<DhikrCounterProps> = ({ state, updateProgress, archiveChallenge, setActiveDhikr, setCurrentView, t }) => {
  const [showHistory, setShowHistory] = useState(false);
  const [historyPage, setHistoryPage] = useState(0);
  const [tapAnimation, setTapAnimation] = useState(false);

  // Derived state from global user data
  const activeChallenge = useMemo(() => {
    return state.activeChallenges.find(c => c.id === state.activeDhikrId);
  }, [state.activeChallenges, state.activeDhikrId]);

  const handleIncrement = () => {
    if (!state.activeDhikrId || !activeChallenge) return;

    // Haptic feedback
    if ('vibrate' in navigator) navigator.vibrate(40);

    // Visual feedback
    setTapAnimation(true);
    setTimeout(() => setTapAnimation(false), 100);

    updateProgress(state.activeDhikrId, 1);

    // Completion feedback
    if (activeChallenge.current + 1 === activeChallenge.target) {
      if ('vibrate' in navigator) navigator.vibrate([100, 50, 100]);
    }
  };

  const handleSelectChallenge = (id: string) => {
    setActiveDhikr(id);
  };

  const handleBack = () => {
    if (state.activeDhikrId) {
      setActiveDhikr(null);
    } else {
      setCurrentView('dashboard');
    }
  };

  const isCompleted = activeChallenge && activeChallenge.current >= activeChallenge.target;

  if (showHistory) {
    const totalPages = Math.ceil(state.dhikrHistory.length / ITEMS_PER_PAGE);
    const visibleHistory = state.dhikrHistory.slice(historyPage * ITEMS_PER_PAGE, (historyPage + 1) * ITEMS_PER_PAGE);

    return (
      <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(false)} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-xl font-bold tracking-tight">{t('history')}</h1>
          </div>
        </div>
        <div className="flex-1 p-5 flex flex-col justify-between overflow-hidden">
          <div className="space-y-3 flex-1 overflow-y-auto">
            {state.dhikrHistory.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full opacity-10 grayscale"><i className="fas fa-box-open text-6xl mb-4"></i><p className="text-xs uppercase font-black tracking-widest">{t('noHistory')}</p></div>
            ) : (
              visibleHistory.map((entry) => {
                const perc = Math.round((entry.current / entry.target) * 100);
                return (
                  <div key={entry.id} className="bg-white p-4 rounded-3xl border border-slate-50 shadow-premium group">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h3 className="text-[11px] font-black text-[#064e3b] uppercase tracking-wide truncate w-48">{t(entry.title)}</h3>
                        <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-1">{new Date(entry.date).toLocaleDateString()}</p>
                      </div>
                      <span className="text-[10px] font-black text-[#c5a059] bg-[#c5a059]/10 px-2 py-1 rounded-lg">{perc}%</span>
                    </div>
                    <div className="w-full bg-slate-50 h-1.5 rounded-full overflow-hidden p-0.5"><div className="bg-[#c5a059] h-full rounded-full transition-all" style={{ width: `${Math.min(100, perc)}%` }}></div></div>
                  </div>
                );
              })
            )}
          </div>
          {totalPages > 1 && (
            <div className="flex justify-between items-center bg-white p-2.5 rounded-2xl border border-slate-100 shadow-premium shrink-0 mt-4">
               <button disabled={historyPage === 0} onClick={() => setHistoryPage(p => p - 1)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-xl disabled:opacity-20 active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Page {historyPage + 1} of {totalPages}</span>
               <button disabled={historyPage === totalPages - 1} onClick={() => setHistoryPage(p => p + 1)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-xl disabled:opacity-20 active:scale-90 transition-all"><i className="fas fa-chevron-right text-xs"></i></button>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (activeChallenge) {
    return (
      <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={handleBack} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-lg font-bold tracking-tight truncate w-2/3">{t(activeChallenge.title)}</h1>
          </div>
        </div>

        <div className="flex-1 p-6 flex flex-col items-center justify-around overflow-hidden">
          <div className="text-center w-full">
            <p className="arabic-font text-5xl text-[#064e3b] font-bold mb-3 drop-shadow-sm min-h-[60px] flex items-center justify-center" dir="rtl">{activeChallenge.arabic}</p>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">{t(activeChallenge.title)}</p>
          </div>

          <button 
            onClick={handleIncrement} 
            className={`relative w-56 h-56 group flex items-center justify-center transition-all duration-75 ${tapAnimation ? 'scale-90' : 'active:scale-95'}`}
          >
             <div className={`absolute inset-0 bg-gradient-to-br from-[#10b981] to-[#064e3b] rounded-full shadow-[0_25px_50px_-12px_rgba(6,78,59,0.4)] border-8 border-white flex items-center justify-center overflow-hidden transition-all ${isCompleted ? 'shadow-[0_0_30px_#10b981]' : ''}`}>
                <div className="absolute inset-0 bg-white opacity-0 group-active:opacity-10 transition-opacity"></div>
                <div className="flex flex-col items-center">
                   <span className="text-white text-7xl font-black drop-shadow-lg tracking-tighter tabular-nums">{activeChallenge.current}</span>
                   <span className="text-emerald-100/50 text-[10px] font-black uppercase tracking-widest mt-[-5px]">Target: {activeChallenge.target}</span>
                </div>
             </div>
             {/* Ring Progress Overlay */}
             <svg className="absolute inset-[-15px] w-[calc(100%+30px)] h-[calc(100%+30px)] rotate-[-90deg]">
               <circle 
                 cx="50%" cy="50%" r="48%" 
                 className="stroke-slate-100 fill-none stroke-[6]"
               />
               <circle 
                 cx="50%" cy="50%" r="48%" 
                 className={`stroke-[#c5a059] fill-none stroke-[6] transition-all duration-300`}
                 strokeDasharray="1000"
                 strokeDashoffset={1000 - (Math.min(100, (activeChallenge.current/activeChallenge.target)*100) * 10)}
                 strokeLinecap="round"
               />
             </svg>
          </button>

          <div className="w-full max-w-xs space-y-4">
            <div className="bg-white p-6 rounded-[42px] shadow-premium border border-slate-50 text-center relative overflow-hidden h-40 flex flex-col justify-center">
               {isCompleted ? (
                 <div className="animate-fade-up flex flex-col items-center">
                    <div className="w-12 h-12 bg-emerald-100 rounded-full flex items-center justify-center mb-3 animate-bounce">
                      <i className="fas fa-check text-emerald-600 text-xl"></i>
                    </div>
                    <h3 className="text-emerald-900 font-black uppercase text-xs tracking-widest mb-4">Target Achieved</h3>
                    <div className="flex gap-2">
                      <button onClick={handleIncrement} className="bg-emerald-50 text-emerald-700 px-4 py-2 rounded-2xl font-black text-[9px] uppercase tracking-widest active:scale-95">Continue</button>
                      <button onClick={() => archiveChallenge(state.activeDhikrId!)} className="bg-[#c5a059] text-white px-6 py-2 rounded-2xl font-black text-[9px] uppercase tracking-widest shadow-xl active:scale-95">Archive</button>
                    </div>
                 </div>
               ) : (
                 <>
                   <div className="flex justify-between items-end mb-3 px-1 text-[10px] font-black uppercase tracking-widest text-slate-400">
                     <span>Progress</span>
                     <span className="text-emerald-900 font-bold">{Math.round((activeChallenge.current/activeChallenge.target)*100)}%</span>
                   </div>
                   <div className="w-full bg-slate-50 h-3 rounded-full overflow-hidden p-1 shadow-inner mb-4">
                     <div className="bg-[#064e3b] h-full rounded-full transition-all duration-300 shadow-[0_0_10px_rgba(6,78,59,0.3)]" style={{ width: `${Math.min(100, (activeChallenge.current/activeChallenge.target)*100)}%` }}></div>
                   </div>
                   <p className="text-[9px] text-slate-300 font-black uppercase tracking-[0.2em] animate-pulse">{t('tapToCount')}</p>
                 </>
               )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
      <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white flex items-center justify-between shrink-0 shadow-emerald-premium rounded-b-[42px]">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-xl font-bold tracking-tight">{t('dhikrList')}</h1>
        </div>
        <button onClick={() => setShowHistory(true)} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-history text-xs"></i></button>
      </div>

      <div className="flex-1 p-4 flex flex-col gap-3 overflow-y-auto pb-10">
        <div className="grid grid-cols-1 gap-3 mt-2">
          {state.activeChallenges.map((challenge) => {
            const perc = Math.min(100, (challenge.current / challenge.target) * 100);
            return (
              <button 
                key={challenge.id} 
                onClick={() => handleSelectChallenge(challenge.id)} 
                className="flex flex-col p-5 rounded-[32px] bg-white border border-slate-50 shadow-premium active:scale-[0.98] transition-all text-left group relative overflow-hidden"
              >
                <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-50 opacity-0 group-hover:opacity-100 rounded-full blur-2xl -mr-12 -mt-12 transition-all"></div>

                <div className="flex justify-between items-start mb-3 relative z-10">
                  <div className="flex-1">
                    <h3 className="text-[12px] font-black text-[#064e3b] uppercase tracking-wide truncate pr-4 group-hover:text-emerald-700">{t(challenge.title)}</h3>
                    <p className="arabic-font text-xl text-emerald-800/40 mt-1 line-clamp-1" dir="rtl">{challenge.arabic}</p>
                  </div>
                  <div className={`w-10 h-10 rounded-2xl flex items-center justify-center transition-all ${perc === 100 ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-50 text-slate-300 group-hover:bg-emerald-50 group-hover:text-emerald-600'}`}>
                    <i className={`fas ${perc === 100 ? 'fa-check' : 'fa-play'} text-sm`}></i>
                  </div>
                </div>

                <div className="relative z-10">
                  <div className="flex justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1.5">
                    <span>{challenge.current} / {challenge.target}</span>
                    <span>{Math.round(perc)}%</span>
                  </div>
                  <div className="w-full bg-slate-50 h-2 rounded-full overflow-hidden p-0.5">
                    <div className="bg-[#064e3b] h-full rounded-full transition-all" style={{ width: `${perc}%` }}></div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>

        <div className="bg-emerald-50/50 p-6 rounded-[36px] border border-emerald-100 text-center relative overflow-hidden mt-4 shrink-0">
           <div className="absolute top-0 right-0 p-4 opacity-[0.05] pointer-events-none"><i className="fas fa-leaf text-5xl"></i></div>
           <p className="text-[#064e3b]/80 text-[11px] italic leading-relaxed font-medium px-4">"{t('remembranceVerse')}"</p>
        </div>
      </div>
    </div>
  );
};

export default DhikrCounter;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// UNIFIED STORAGE KEYS - DO NOT CHANGE
const USERS_DB_KEY = 'ibadathi_v1_users_database';
const SESSION_KEY = 'ibadathi_v1_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12",
  Sunrise: "06:34",
  Dhuhr: "12:28",
  Asr: "15:42",
  Maghrib: "18:22",
  Isha: "19:38"
};

const App: React.FC = () => {
  // Load initial state from LocalStorage
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    const parsedUsers = savedUsers ? JSON.parse(savedUsers) : {};

    return {
      currentUser: activeSession, // This is the username
      users: parsedUsers,
      todayTimings: DEFAULT_TIMINGS
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      return state.users[state.currentUser].profile.preferredLanguage;
    }
    return 'en';
  });

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'account'>(() => {
    return state.currentUser ? 'dashboard' : 'welcome';
  });

  // Sync state to LocalStorage whenever users or session changes
  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();

    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username },
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        activeDhikrId: null,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };

      setState(prev => ({
        ...prev,
        currentUser: username,
        users: { ...prev.users, [username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }

    setCurrentLanguage(profile.preferredLanguage);
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const currentUser = prev.currentUser!;
      const userToUpdate = prev.users[currentUser];
      if (!userToUpdate) return prev;

      return {
        ...prev,
        users: {
          ...prev.users,
          [currentUser]: updater(userToUpdate)
        }
      };
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(user => {
      const currentLogs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return {
        ...user,
        prayerLogs: { ...user.prayerLogs, [date]: { ...currentLogs, [prayer]: status } }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(user => {
      const current = user.sunnahLogs[date] || [];
      const updated = current.includes(sunnahName) ? current.filter(s => s !== sunnahName) : [...current, sunnahName];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: updated } };
    });
  };

  const setActiveDhikr = (id: string | null) => {
    updateActiveUser(user => ({ ...user, activeDhikrId: id }));
  };

  const updateDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const updatedChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: c.current + delta } : c
      );
      return { ...user, activeChallenges: updatedChallenges, dhikrCount: user.dhikrCount + delta };
    });
  };

  const archiveDhikrChallenge = (id: string) => {
    updateActiveUser(user => {
      const challenge = user.activeChallenges.find(c => c.id === id);
      if (!challenge) return user;
      const historyEntry: DhikrHistoryEntry = {
        id: `${id}-${Date.now()}`,
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };
      const resetChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: 0 } : c
      );
      return { 
        ...user, 
        activeChallenges: resetChallenges, 
        dhikrHistory: [historyEntry, ...user.dhikrHistory],
        activeDhikrId: null
      };
    });
  };

  const updateQuran = (progress: QuranProgress) => {
    updateActiveUser(user => ({ ...user, quranProgress: progress }));
  };

  const updateFasting = (date: string, log: FastingLog) => {
    updateActiveUser(user => ({
      ...user,
      fastingLogs: { ...user.fastingLogs, [date]: log }
    }));
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(user => ({ ...user, isHaydNifas: active }));
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: [...user.healthPeriods, { id: Date.now().toString(), start, end }]
    }));
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: user.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return <DhikrCounter state={compositeState} updateProgress={updateDhikrProgress} archiveChallenge={archiveDhikrChallenge} setActiveDhikr={setActiveDhikr} setCurrentView={setCurrentView} t={t} />;
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={updateQuran} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={updateFasting} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  // Real-time username validation
  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);
  const isUsernameTaken = useMemo(() => mode === 'register' && usernameNormalized.length > 2 && !!users[usernameNormalized], [usernameNormalized, mode, users]);

  // Suggestions for taken usernames
  const suggestions = useMemo(() => {
    if (!isUsernameTaken) return [];
    const base = usernameNormalized;
    return [
      `${base}${Math.floor(Math.random() * 99)}`,
      `${base}_seeker`,
      `${base}${new Date().getFullYear()}`
    ];
  }, [isUsernameTaken, usernameNormalized]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password.trim()) return "Password is required.";

    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (users[usernameNormalized]) return "Username is already taken.";
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setIsAuthenticating(true);

    // Simulate network delay for premium feel
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user) {
          setError("User not found.");
          setIsAuthenticating(false);
          return;
        }
        if (user.profile.password !== formData.password) {
          setError("Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const inputClasses = "w-full px-4 py-3 bg-white border border-slate-100 rounded-[20px] focus:ring-2 focus:ring-emerald-600/10 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm";
  const labelClasses = "block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1.5";

  return (
    <div className="p-6 flex flex-col items-center justify-center h-full bg-[#fdfbf7] view-transition overflow-hidden">
      <div className="w-16 h-16 bg-emerald-900 rounded-[28px] flex items-center justify-center mb-4 shadow-2xl border-2 border-white rotate-3 shrink-0">
        <i className="fas fa-mosque text-2xl text-emerald-100"></i>
      </div>
      <h1 className="text-3xl font-black text-emerald-900 mb-1 tracking-tighter shrink-0">Ibadathi</h1>
      <p className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.2em] mb-6 shrink-0">Sacred Companion</p>

      <div className="flex bg-emerald-50 p-1.5 rounded-2xl mb-6 w-full max-w-[240px] shrink-0 border border-emerald-100/50">
        <button 
          type="button"
          onClick={() => { setMode('login'); setError(null); }}
          className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('login')}
        </button>
        <button 
          type="button"
          onClick={() => { setMode('register'); setError(null); }}
          className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('register')}
        </button>
      </div>

      <form onSubmit={handleSubmit} className="w-full space-y-4 max-w-[320px] flex-1 flex flex-col justify-center overflow-y-auto pr-1">
        {error && (
          <div className="bg-rose-50 text-rose-600 p-3 rounded-2xl text-[10px] font-bold text-center border border-rose-100 animate-fade-up shrink-0">
            <i className="fas fa-exclamation-circle mr-2"></i> {error}
          </div>
        )}

        <div className="space-y-1.5 shrink-0">
          <label className={labelClasses}>{t('username')}</label>
          <div className="relative">
            <input 
              type="text" 
              className={`${inputClasses} ${isUsernameTaken ? 'border-amber-300 bg-amber-50/20' : ''}`}
              placeholder="muslim_seeker"
              value={formData.username}
              onChange={e => setFormData({...formData, username: e.target.value.toLowerCase()})}
              required
            />
            {formData.username.length > 2 && !isUsernameTaken && mode === 'register' && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 animate-pulse">
                <i className="fas fa-check-circle"></i>
              </div>
            )}
          </div>
          {isUsernameTaken && (
