export default Login;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  // Normalize username for checks
  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  // Instant availability check
  const usernameStatus = useMemo(() => {
    if (mode === 'login' || usernameNormalized.length < 3) return 'idle';
    return users[usernameNormalized] ? 'taken' : 'available';
  }, [usernameNormalized, mode, users]);

  // Dynamic suggestions
  const suggestions = useMemo(() => {
    if (usernameStatus !== 'taken') return [];
    const base = usernameNormalized;
    const items = [
      `${base}${Math.floor(Math.random() * 99) + 1}`,
      `${base}_ibadathi`,
      `${base}_seeker`
    ];
    // Filter out duplicates if random luck is bad
    return [...new Set(items)].filter(s => !users[s.toLowerCase()]);
  }, [usernameStatus, usernameNormalized, users]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password.trim()) return "Password is required.";

    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (usernameStatus === 'taken') return t('usernameTaken');
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setIsAuthenticating(true);

    // Simulate premium delay
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user) {
          setError("User not found.");
          setIsAuthenticating(false);
          return;
        }
        if (user.profile.password !== formData.password) {
          setError("Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 600);
  };

  const inputClasses = "w-full px-4 py-3 bg-white border border-slate-100 rounded-[20px] focus:ring-2 focus:ring-emerald-600/10 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm";
  const labelClasses = "block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1.5";

  return (
    <div className="p-6 flex flex-col items-center justify-center h-full bg-[#fdfbf7] view-transition overflow-hidden">
      <div className="w-16 h-16 bg-emerald-900 rounded-[28px] flex items-center justify-center mb-4 shadow-2xl border-2 border-white rotate-3 shrink-0">
        <i className="fas fa-mosque text-2xl text-emerald-100"></i>
      </div>
      <h1 className="text-3xl font-black text-emerald-900 mb-1 tracking-tighter shrink-0">Ibadathi</h1>
      <p className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.2em] mb-6 shrink-0">Sacred Companion</p>

      <div className="flex bg-emerald-50 p-1.5 rounded-2xl mb-6 w-full max-w-[240px] shrink-0 border border-emerald-100/50">
        <button 
          type="button"
          onClick={() => { setMode('login'); setError(null); }}
          className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('login')}
        </button>
        <button 
          type="button"
          onClick={() => { setMode('register'); setError(null); }}
          className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('register')}
        </button>
      </div>

      <form onSubmit={handleSubmit} className="w-full space-y-4 max-w-[320px] flex-1 flex flex-col justify-center overflow-y-auto pr-1">
        {error && (
          <div className="bg-rose-50 text-rose-600 p-3 rounded-2xl text-[10px] font-bold text-center border border-rose-100 animate-fade-up shrink-0">
            <i className="fas fa-exclamation-circle mr-2"></i> {error}
          </div>
        )}

        <div className="space-y-1.5 shrink-0">
          <label className={labelClasses}>{t('username')}</label>
          <div className="relative">
            <input 
              type="text" 
              className={`${inputClasses} ${usernameStatus === 'taken' ? 'border-rose-300 bg-rose-50/10' : usernameStatus === 'available' ? 'border-emerald-300 bg-emerald-50/10' : ''}`}
              placeholder="muslim_seeker"
              value={formData.username}
              onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})}
              required
            />
            {usernameStatus === 'available' && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-600 animate-fade-in">
                <i className="fas fa-check-circle"></i>
              </div>
            )}
            {usernameStatus === 'taken' && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-rose-600 animate-shake">
                <i className="fas fa-times-circle"></i>
              </div>
            )}
          </div>

          {/* Real-time availability messages */}
          {usernameStatus === 'available' && (
            <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest ml-1 animate-fade-up">
              <i className="fas fa-info-circle mr-1"></i> {t('usernameAvailable')}
            </p>
          )}
          {usernameStatus === 'taken' && (
            <div className="animate-fade-up">
              <p className="text-[9px] font-black text-rose-600 uppercase tracking-widest ml-1">
                <i className="fas fa-exclamation-triangle mr-1"></i> {t('usernameTaken')}
              </p>

              {/* Dynamic Suggestions */}
              <div className="mt-3 p-3 bg-rose-50/50 rounded-2xl border border-rose-100/50">
                <p className="text-[8px] font-black text-rose-800/60 uppercase tracking-widest mb-2">{t('suggestions')}</p>
                <div className="flex flex-wrap gap-2">
                  {suggestions.map(s => (
                    <button 
                      key={s} 
                      type="button"
                      onClick={() => setFormData({...formData, username: s})}
                      className="bg-white px-2.5 py-1.5 rounded-xl text-[9px] font-black text-rose-900 border border-rose-200 active:scale-95 transition-all shadow-sm hover:border-emerald-400 hover:text-emerald-700"
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        {mode === 'register' ? (
          <div className="space-y-4 shrink-0 animate-fade-up">
            <div className="space-y-1.5">
              <label className={labelClasses}>{t('name')}</label>
              <input 
                type="text"
                className={inputClasses}
                placeholder="Abdullah Al-Fulan"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className={labelClasses}>{t('age')}</label>
                <input 
                  type="number"
                  className={inputClasses}
                  placeholder="25"
                  value={formData.age}
                  onChange={e => setFormData({...formData, age: e.target.value})}
                  required
                />
              </div>
              <div className="space-y-1.5">
                <label className={labelClasses}>{t('sex')}</label>
                <select 
                  className={`${inputClasses} appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22none%22%20viewBox%3D%220%200%2024%2024%22%20stroke%3D%22%2364748b%22%3E%3Cpath%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%222%22%20d%3D%22M19%209l-7%207-7-7%22%20%2F%3E%3C%2Fsvg%3E')] bg-[length:0.8em_0.8em] bg-[right_1rem_center] bg-no-repeat`}
                  value={formData.sex}
                  onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                >
                  <option value="male">{t('male')}</option>
                  <option value="female">{t('female')}</option>
                </select>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className={labelClasses}>{t('place')}</label>
              <input 
                type="text"
                className={inputClasses}
                placeholder="Makkah, KSA"
                value={formData.place}
                onChange={e => setFormData({...formData, place: e.target.value})}
                required
              />
            </div>
          </div>
        ) : null}

        <div className="space-y-1.5 shrink-0">
          <label className={labelClasses}>{t('password')}</label>
          <input 
            type="password"
            className={inputClasses}
            placeholder="••••••••"
            value={formData.password}
            onChange={e => setFormData({...formData, password: e.target.value})}
            required
          />
        </div>

        <button 
          type="submit"
          disabled={isAuthenticating || (mode === 'register' && usernameStatus !== 'available')}
          className="w-full bg-emerald-900 text-white font-black py-4 rounded-[24px] transition-all active:scale-[0.98] mt-4 uppercase tracking-[0.25em] text-[10px] flex items-center justify-center gap-3 shrink-0 disabled:opacity-30 shadow-2xl shadow-emerald-900/20"
        >
          {isAuthenticating ? (
            <i className="fas fa-spinner fa-spin"></i>
          ) : (
            <>
              {mode === 'login' ? t('login') : t('register')}
              <i className="fas fa-arrow-right text-[8px] opacity-40"></i>
            </>
          )}
        </button>
      </form>

      <div className="mt-8 flex items-center gap-2 opacity-5 shrink-0 grayscale">
        <i className="fas fa-award text-emerald-900 text-xl"></i>
      </div>
    </div>
  );
};

export default Login;

export type Language = 'en' | 'ml' | 'ta' | 'ar';

export enum PrayerStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  MISSED = 'missed',
  EXCUSED = 'excused'
}

export interface UserProfile {
  username: string;
  name: string;
  age: number;
  sex: 'male' | 'female';
  place: string;
  preferredLanguage: Language;
  password?: string; // Stored in mock backend
}

export interface PrayerLog {
  fajr: PrayerStatus;
  dhuhr: PrayerStatus;
  asr: PrayerStatus;
  maghrib: PrayerStatus;
  isha: PrayerStatus;
}

export interface FastingLog {
  status: 'none' | 'completed' | 'missed' | 'excused';
  type: 'ramadan' | 'sunnah';
}

export interface QuranProgress {
  surah: string;
  ayah: string;
  lastUpdated: string;
}

export interface DhikrChallenge {
  id: string;
  title: string;
  arabic: string;
  target: number;
  current: number;
  lastReset?: string;
}

export interface PersonalDhikr {
  id: string;
  name: string;
  totalCount: number;
  dailyCount: number;
  sessionCount: number;
  lastUpdated: string;
}

export interface DhikrHistoryEntry {
  id: string;
  title: string;
  target: number;
  current: number;
  date: string;
}

export interface PrayerTimings {
  Fajr: string;
  Dhuhr: string;
  Asr: string;
  Maghrib: string;
  Isha: string;
  Sunrise: string;
}

export interface QadaReminder {
  id: string;
  time: string;
  enabled: boolean;
}

export interface HealthPeriod {
  id: string;
  start: string; // ISO Date string
  end: string | null; // null if active
}

// This represents the data for a SINGLE user
export interface UserData {
  profile: UserProfile;
  prayerLogs: Record<string, PrayerLog>;
  sunnahLogs: Record<string, string[]>;
  fastingLogs: Record<string, FastingLog>;
  quranProgress: QuranProgress;
  dhikrCount: number;
  activeChallenges: DhikrChallenge[];
  personalDhikrs: PersonalDhikr[];
  activeDhikrId: string | null; // Tracked active challenge for the counter
  dhikrHistory: DhikrHistoryEntry[];
  isHaydNifas: boolean;
  haydStartDate: string | null;
  healthPeriods: HealthPeriod[];
  settings: {
    notificationsEnabled: boolean;
    locationEnabled: boolean;
    qadaReminders: QadaReminder[];
  };
}

export interface AppState {
  currentUser: string | null; // username
  users: Record<string, UserData>; // Mock database
  todayTimings: PrayerTimings | null;
}

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PersonalDhikr, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// UNIFIED STORAGE KEYS - DO NOT CHANGE
const USERS_DB_KEY = 'ibadathi_v1_users_database';
const SESSION_KEY = 'ibadathi_v1_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12",
  Sunrise: "06:34",
  Dhuhr: "12:28",
  Asr: "15:42",
  Maghrib: "18:22",
  Isha: "19:38"
};

const App: React.FC = () => {
  // Load initial state from LocalStorage
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    const parsedUsers = savedUsers ? JSON.parse(savedUsers) : {};

    return {
      currentUser: activeSession, // This is the username
      users: parsedUsers,
      todayTimings: DEFAULT_TIMINGS
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      return state.users[state.currentUser].profile.preferredLanguage;
    }
    return 'en';
  });

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'account'>(() => {
    return state.currentUser ? 'dashboard' : 'welcome';
  });

  // Sync state to LocalStorage whenever users or session changes
  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();

    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username },
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        personalDhikrs: [],
        activeDhikrId: null,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };

      setState(prev => ({
        ...prev,
        currentUser: username,
        users: { ...prev.users, [username]: newUserData }
      }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }

    setCurrentLanguage(profile.preferredLanguage);
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const currentUser = prev.currentUser!;
      const userToUpdate = prev.users[currentUser];
      if (!userToUpdate) return prev;

      return {
        ...prev,
        users: {
          ...prev.users,
          [currentUser]: updater(userToUpdate)
        }
      };
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(user => {
      const currentLogs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return {
        ...user,
        prayerLogs: { ...user.prayerLogs, [date]: { ...currentLogs, [prayer]: status } }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(user => {
      const current = user.sunnahLogs[date] || [];
      const updated = current.includes(sunnahName) ? current.filter(s => s !== sunnahName) : [...current, sunnahName];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: updated } };
    });
  };

  const setActiveDhikr = (id: string | null) => {
    updateActiveUser(user => ({ ...user, activeDhikrId: id }));
  };

  const updateDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const updatedChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: c.current + delta } : c
      );
      return { ...user, activeChallenges: updatedChallenges, dhikrCount: user.dhikrCount + delta };
    });
  };

  const updatePersonalDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const today = new Date().toISOString().split('T')[0];
      const updatedDhikrs = user.personalDhikrs.map(d => {
        if (d.id === id) {
          const isNewDay = d.lastUpdated.split('T')[0] !== today;
          return {
            ...d,
            totalCount: d.totalCount + delta,
            dailyCount: isNewDay ? delta : d.dailyCount + delta,
            sessionCount: d.sessionCount + delta,
            lastUpdated: new Date().toISOString()
          };
        }
        return d;
      });
      return { ...user, personalDhikrs: updatedDhikrs, dhikrCount: user.dhikrCount + delta };
    });
  };

  const addPersonalDhikr = (name: string) => {
    updateActiveUser(user => {
      const newDhikr: PersonalDhikr = {
        id: `personal-${Date.now()}`,
        name,
        totalCount: 0,
        dailyCount: 0,
        sessionCount: 0,
        lastUpdated: new Date().toISOString()
      };
      return { ...user, personalDhikrs: [newDhikr, ...user.personalDhikrs] };
    });
  };

  const resetPersonalDhikrSession = (id: string) => {
    updateActiveUser(user => {
      const updatedDhikrs = user.personalDhikrs.map(d => 
        d.id === id ? { ...d, sessionCount: 0 } : d
      );
      return { ...user, personalDhikrs: updatedDhikrs };
    });
  };

  const deletePersonalDhikr = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      personalDhikrs: user.personalDhikrs.filter(d => d.id !== id)
    }));
  };

  const archiveDhikrChallenge = (id: string) => {
    updateActiveUser(user => {
      const challenge = user.activeChallenges.find(c => c.id === id);
      if (!challenge) return user;
      const historyEntry: DhikrHistoryEntry = {
        id: `${id}-${Date.now()}`,
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };
      const resetChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: 0 } : c
      );
      return { 
        ...user, 
        activeChallenges: resetChallenges, 
        dhikrHistory: [historyEntry, ...user.dhikrHistory],
        activeDhikrId: null
      };
    });
  };

  const updateQuran = (progress: QuranProgress) => {
    updateActiveUser(user => ({ ...user, quranProgress: progress }));
  };

  const updateFasting = (date: string, log: FastingLog) => {
    updateActiveUser(user => ({
      ...user,
      fastingLogs: { ...user.fastingLogs, [date]: log }
    }));
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(user => ({ ...user, isHaydNifas: active }));
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: [...user.healthPeriods, { id: Date.now().toString(), start, end }]
    }));
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: user.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={compositeState} 
            updateProgress={updateDhikrProgress} 
            updatePersonalProgress={updatePersonalDhikrProgress}
            addPersonalDhikr={addPersonalDhikr}
            resetPersonalSession={resetPersonalDhikrSession}
            deletePersonalDhikr={deletePersonalDhikr}
            archiveChallenge={archiveDhikrChallenge} 
            setActiveDhikr={setActiveDhikr} 
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={updateQuran} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={updateFasting} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { UserData, DhikrChallenge, PersonalDhikr, PrayerTimings } from '../types';

interface DhikrCounterProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateProgress: (id: string, delta: number) => void;
  updatePersonalProgress: (id: string, delta: number) => void;
  addPersonalDhikr: (name: string) => void;
  resetPersonalSession: (id: string) => void;
  deletePersonalDhikr: (id: string) => void;
  archiveChallenge: (id: string) => void;
  setActiveDhikr: (id: string | null) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const ITEMS_PER_PAGE = 4;

const DhikrCounter: React.FC<DhikrCounterProps> = ({ 
  state, 
  updateProgress, 
  updatePersonalProgress,
  addPersonalDhikr,
  resetPersonalSession,
  deletePersonalDhikr,
  archiveChallenge, 
  setActiveDhikr, 
  setCurrentView, 
  t 
}) => {
  const [activeTab, setActiveTab] = useState<'challenges' | 'personal'>('challenges');
  const [showHistory, setShowHistory] = useState(false);
  const [historyPage, setHistoryPage] = useState(0);
  const [tapAnimation, setTapAnimation] = useState(false);
  const [isAddingDhikr, setIsAddingDhikr] = useState(false);
  const [newDhikrName, setNewDhikrName] = useState('');
  const [activePersonalId, setActivePersonalId] = useState<string | null>(null);

  // Derived state from global user data
  const activeChallenge = useMemo(() => {
    return state.activeChallenges.find(c => c.id === state.activeDhikrId);
  }, [state.activeChallenges, state.activeDhikrId]);

  const activePersonal = useMemo(() => {
    return state.personalDhikrs.find(d => d.id === activePersonalId);
  }, [state.personalDhikrs, activePersonalId]);

  const handleIncrementChallenge = () => {
    if (!state.activeDhikrId || !activeChallenge) return;
    if ('vibrate' in navigator) navigator.vibrate(40);
    setTapAnimation(true);
    setTimeout(() => setTapAnimation(false), 100);
    updateProgress(state.activeDhikrId, 1);
    if (activeChallenge.current + 1 === activeChallenge.target) {
      if ('vibrate' in navigator) navigator.vibrate([100, 50, 100]);
    }
  };

  const handleIncrementPersonal = () => {
    if (!activePersonalId || !activePersonal) return;
    if ('vibrate' in navigator) navigator.vibrate(40);
    setTapAnimation(true);
    setTimeout(() => setTapAnimation(false), 100);
    updatePersonalProgress(activePersonalId, 1);
  };

  const handleAddDhikr = () => {
    if (newDhikrName.trim()) {
      addPersonalDhikr(newDhikrName.trim());
      setNewDhikrName('');
      setIsAddingDhikr(false);
    }
  };

  const handleBack = () => {
    if (state.activeDhikrId) {
      setActiveDhikr(null);
    } else if (activePersonalId) {
      setActivePersonalId(null);
    } else {
      setCurrentView('dashboard');
    }
  };

  const isChallengeCompleted = activeChallenge && activeChallenge.current >= activeChallenge.target;

  // History View
  if (showHistory) {
    const totalPages = Math.ceil(state.dhikrHistory.length / ITEMS_PER_PAGE);
    const visibleHistory = state.dhikrHistory.slice(historyPage * ITEMS_PER_PAGE, (historyPage + 1) * ITEMS_PER_PAGE);

    return (
      <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(false)} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-xl font-bold tracking-tight">{t('history')}</h1>
          </div>
        </div>
        <div className="flex-1 p-5 flex flex-col justify-between overflow-hidden">
          <div className="space-y-3 flex-1 overflow-y-auto">
            {state.dhikrHistory.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full opacity-10 grayscale"><i className="fas fa-box-open text-6xl mb-4"></i><p className="text-xs uppercase font-black tracking-widest">{t('noHistory')}</p></div>
            ) : (
              visibleHistory.map((entry) => {
                const perc = Math.round((entry.current / entry.target) * 100);
                return (
                  <div key={entry.id} className="bg-white p-4 rounded-3xl border border-slate-50 shadow-premium group">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h3 className="text-[11px] font-black text-[#064e3b] uppercase tracking-wide truncate w-48">{t(entry.title)}</h3>
                        <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-1">{new Date(entry.date).toLocaleDateString()}</p>
                      </div>
                      <span className="text-[10px] font-black text-[#c5a059] bg-[#c5a059]/10 px-2 py-1 rounded-lg">{perc}%</span>
                    </div>
                    <div className="w-full bg-slate-50 h-1.5 rounded-full overflow-hidden p-0.5"><div className="bg-[#c5a059] h-full rounded-full transition-all" style={{ width: `${Math.min(100, perc)}%` }}></div></div>
                  </div>
                );
              })
            )}
          </div>
          {totalPages > 1 && (
            <div className="flex justify-between items-center bg-white p-2.5 rounded-2xl border border-slate-100 shadow-premium shrink-0 mt-4">
               <button disabled={historyPage === 0} onClick={() => setHistoryPage(p => p - 1)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-xl disabled:opacity-20 active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Page {historyPage + 1} of {totalPages}</span>
               <button disabled={historyPage === totalPages - 1} onClick={() => setHistoryPage(p => p + 1)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-xl disabled:opacity-20 active:scale-90 transition-all"><i className="fas fa-chevron-right text-xs"></i></button>
            </div>
          )}
        </div>
      </div>
    );
  }

  // Active Challenge Counter View
  if (activeChallenge) {
    return (
      <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={handleBack} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-lg font-bold tracking-tight truncate w-2/3">{t(activeChallenge.title)}</h1>
          </div>
        </div>

        <div className="flex-1 p-6 flex flex-col items-center justify-around overflow-hidden">
          <div className="text-center w-full">
            <p className="arabic-font text-5xl text-[#064e3b] font-bold mb-3 drop-shadow-sm min-h-[60px] flex items-center justify-center" dir="rtl">{activeChallenge.arabic}</p>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">{t(activeChallenge.title)}</p>
          </div>

          <button 
            onClick={handleIncrementChallenge} 
            className={`relative w-56 h-56 group flex items-center justify-center transition-all duration-75 ${tapAnimation ? 'scale-90' : 'active:scale-95'}`}
          >
             <div className={`absolute inset-0 bg-gradient-to-br from-[#10b981] to-[#064e3b] rounded-full shadow-[0_25px_50px_-12px_rgba(6,78,59,0.4)] border-8 border-white flex items-center justify-center overflow-hidden transition-all ${isChallengeCompleted ? 'shadow-[0_0_30px_#10b981]' : ''}`}>
                <div className="absolute inset-0 bg-white opacity-0 group-active:opacity-10 transition-opacity"></div>
                <div className="flex flex-col items-center">
                   <span className="text-white text-7xl font-black drop-shadow-lg tracking-tighter tabular-nums">{activeChallenge.current}</span>
                   <span className="text-emerald-100/50 text-[10px] font-black uppercase tracking-widest mt-[-5px]">Target: {activeChallenge.target}</span>
                </div>
             </div>
             <svg className="absolute inset-[-15px] w-[calc(100%+30px)] h-[calc(100%+30px)] rotate-[-90deg]">
               <circle cx="50%" cy="50%" r="48%" className="stroke-slate-100 fill-none stroke-[6]" />
               <circle cx="50%" cy="50%" r="48%" className={`stroke-[#c5a059] fill-none stroke-[6] transition-all duration-300`} strokeDasharray="1000" strokeDashoffset={1000 - (Math.min(100, (activeChallenge.current/activeChallenge.target)*100) * 10)} strokeLinecap="round" />
             </svg>
          </button>

          <div className="w-full max-w-xs space-y-4">
            <div className="bg-white p-6 rounded-[42px] shadow-premium border border-slate-50 text-center relative overflow-hidden h-40 flex flex-col justify-center">
               {isChallengeCompleted ? (
                 <div className="animate-fade-up flex flex-col items-center">
                    <div className="w-12 h-12 bg-emerald-100 rounded-full flex items-center justify-center mb-3 animate-bounce">
                      <i className="fas fa-check text-emerald-600 text-xl"></i>
                    </div>
                    <h3 className="text-emerald-900 font-black uppercase text-xs tracking-widest mb-4">Target Achieved</h3>
                    <div className="flex gap-2">
                      <button onClick={handleIncrementChallenge} className="bg-emerald-50 text-emerald-700 px-4 py-2 rounded-2xl font-black text-[9px] uppercase tracking-widest active:scale-95">Continue</button>
                      <button onClick={() => archiveChallenge(state.activeDhikrId!)} className="bg-[#c5a059] text-white px-6 py-2 rounded-2xl font-black text-[9px] uppercase tracking-widest shadow-xl active:scale-95">Archive</button>
                    </div>
                 </div>
               ) : (
                 <>
                   <div className="flex justify-between items-end mb-3 px-1 text-[10px] font-black uppercase tracking-widest text-slate-400">
                     <span>Progress</span>
                     <span className="text-emerald-900 font-bold">{Math.round((activeChallenge.current/activeChallenge.target)*100)}%</span>
                   </div>
                   <div className="w-full bg-slate-50 h-3 rounded-full overflow-hidden p-1 shadow-inner mb-4">
                     <div className="bg-[#064e3b] h-full rounded-full transition-all duration-300 shadow-[0_0_10px_rgba(6,78,59,0.3)]" style={{ width: `${Math.min(100, (activeChallenge.current/activeChallenge.target)*100)}%` }}></div>
                   </div>
                   <p className="text-[9px] text-slate-300 font-black uppercase tracking-[0.2em] animate-pulse">{t('tapToCount')}</p>
                 </>
               )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Active Personal Dhikr Counter View
  if (activePersonal) {
    return (
      <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
        <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
          <div className="flex items-center gap-4">
            <button onClick={handleBack} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-lg font-bold tracking-tight truncate w-2/3">{activePersonal.name}</h1>
          </div>
        </div>

        <div className="flex-1 p-6 flex flex-col items-center justify-around overflow-hidden">
          <div className="text-center w-full">
            <h2 className="text-4xl font-black text-emerald-900 mb-2 tracking-tight">{activePersonal.name}</h2>
            <p className="text-slate-400 text-[9px] font-black uppercase tracking-widest">{t('personal')}</p>
          </div>

          <button 
            onClick={handleIncrementPersonal} 
            className={`relative w-64 h-64 group flex items-center justify-center transition-all duration-75 ${tapAnimation ? 'scale-90' : 'active:scale-95'}`}
          >
             <div className="absolute inset-0 bg-gradient-to-br from-[#c5a059] to-[#8d6e35] rounded-full shadow-2xl border-8 border-white flex flex-col items-center justify-center overflow-hidden">
                <span className="text-white text-8xl font-black drop-shadow-lg tracking-tighter tabular-nums">{activePersonal.sessionCount}</span>
                <span className="text-amber-100/50 text-[10px] font-black uppercase tracking-widest mt-[-5px]">{t('session')}</span>
             </div>
             <div className="absolute -inset-2 border-2 border-dashed border-amber-200/40 rounded-full animate-spin-slow pointer-events-none"></div>
          </button>

          <div className="w-full max-w-sm grid grid-cols-2 gap-4">
            <div className="bg-white p-5 rounded-[32px] shadow-premium border border-slate-50 text-center">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('daily')}</span>
              <p className="text-2xl font-black text-emerald-900 tabular-nums">{activePersonal.dailyCount}</p>
            </div>
            <div className="bg-white p-5 rounded-[32px] shadow-premium border border-slate-50 text-center">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('total')}</span>
              <p className="text-2xl font-black text-emerald-900 tabular-nums">{activePersonal.totalCount}</p>
            </div>
            <button 
              onClick={() => resetPersonalSession(activePersonalId!)} 
              className="col-span-2 py-4 bg-emerald-50 text-emerald-700 rounded-3xl font-black text-[10px] uppercase tracking-[0.2em] active:scale-95 transition-all shadow-sm flex items-center justify-center gap-2"
            >
              <i className="fas fa-undo text-[8px]"></i> {t('resetSession')}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Main Lists View
  return (
    <div className="flex flex-col h-full bg-[#f8fafc] view-transition">
      <div className="p-5 pt-12 pb-6 bg-[#064e3b] text-white shrink-0 shadow-emerald-premium rounded-b-[42px]">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-chevron-left text-xs"></i></button>
            <h1 className="text-xl font-bold tracking-tight">{t('dhikr')}</h1>
          </div>
          <button onClick={() => setShowHistory(true)} className="w-10 h-10 flex items-center justify-center bg-white/10 border border-white/10 rounded-xl active:scale-90 transition-all"><i className="fas fa-history text-xs"></i></button>
        </div>

        <div className="flex bg-white/5 p-1 rounded-2xl border border-white/10 backdrop-blur-sm">
          <button 
            onClick={() => setActiveTab('challenges')} 
            className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'challenges' ? 'bg-white text-emerald-900 shadow-xl' : 'text-white/40'}`}
          >
            {t('challenge')}
          </button>
          <button 
            onClick={() => setActiveTab('personal')} 
            className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-900 shadow-xl' : 'text-white/40'}`}
          >
            {t('personal')}
          </button>
        </div>
      </div>

      <div className="flex-1 p-4 flex flex-col gap-3 overflow-y-auto pb-10">
        {activeTab === 'challenges' ? (
          <div className="grid grid-cols-1 gap-3 mt-2">
            {state.activeChallenges.map((challenge) => {
              const perc = Math.min(100, (challenge.current / challenge.target) * 100);
              return (
                <button 
                  key={challenge.id} 
                  onClick={() => setActiveDhikr(challenge.id)} 
                  className="flex flex-col p-5 rounded-[32px] bg-white border border-slate-50 shadow-premium active:scale-[0.98] transition-all text-left group relative overflow-hidden"
                >
                  <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-50 opacity-0 group-hover:opacity-100 rounded-full blur-2xl -mr-12 -mt-12 transition-all"></div>
                  <div className="flex justify-between items-start mb-3 relative z-10">
                    <div className="flex-1">
                      <h3 className="text-[12px] font-black text-[#064e3b] uppercase tracking-wide truncate pr-4 group-hover:text-emerald-700">{t(challenge.title)}</h3>
                      <p className="arabic-font text-xl text-emerald-800/40 mt-1 line-clamp-1" dir="rtl">{challenge.arabic}</p>
                    </div>
                    <div className={`w-10 h-10 rounded-2xl flex items-center justify-center transition-all ${perc === 100 ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-50 text-slate-300 group-hover:bg-emerald-50 group-hover:text-emerald-600'}`}>
                      <i className={`fas ${perc === 100 ? 'fa-check' : 'fa-play'} text-sm`}></i>
                    </div>
                  </div>
                  <div className="relative z-10">
                    <div className="flex justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1.5">
                      <span>{challenge.current} / {challenge.target}</span>
                      <span>{Math.round(perc)}%</span>
                    </div>
                    <div className="w-full bg-slate-50 h-2 rounded-full overflow-hidden p-0.5">
                      <div className="bg-[#064e3b] h-full rounded-full transition-all" style={{ width: `${perc}%` }}></div>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        ) : (
          <div className="space-y-3 mt-2">
            <button 
              onClick={() => setIsAddingDhikr(true)} 
              className="w-full p-6 rounded-[32px] bg-white border-2 border-dashed border-emerald-100 text-emerald-700 flex flex-col items-center justify-center gap-3 active:scale-95 transition-all group"
            >
              <div className="w-12 h-12 bg-emerald-50 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform"><i className="fas fa-plus"></i></div>
              <span className="text-[10px] font-black uppercase tracking-widest">{t('addDhikr')}</span>
            </button>

            {state.personalDhikrs.map((d) => (
              <div key={d.id} className="relative group">
                <button 
                  onClick={() => setActivePersonalId(d.id)}
                  className="w-full flex items-center justify-between p-5 rounded-[32px] bg-white border border-slate-50 shadow-premium active:scale-[0.98] transition-all text-left"
                >
                  <div className="flex-1">
                    <h3 className="text-[13px] font-black text-emerald-900 uppercase tracking-tight">{d.name}</h3>
                    <div className="flex gap-3 mt-1 text-[8px] font-black text-slate-400 uppercase tracking-widest">
                      <span>{t('total')}: {d.totalCount}</span>
                      <span className="text-emerald-600">{t('daily')}: {d.dailyCount}</span>
                    </div>
                  </div>
                  <div className="w-10 h-10 bg-emerald-50 rounded-2xl flex items-center justify-center text-emerald-600">
                    <i className="fas fa-hand-pointer"></i>
                  </div>
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); deletePersonalDhikr(d.id); }}
                  className="absolute -top-1 -right-1 w-7 h-7 bg-rose-50 text-rose-300 rounded-full flex items-center justify-center text-[8px] border border-rose-100 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <i className="fas fa-trash"></i>
                </button>
              </div>
            ))}
          </div>
        )}

        <div className="bg-emerald-50/50 p-6 rounded-[36px] border border-emerald-100 text-center relative overflow-hidden mt-4 shrink-0">
           <div className="absolute top-0 right-0 p-4 opacity-[0.05] pointer-events-none"><i className="fas fa-leaf text-5xl"></i></div>
           <p className="text-[#064e3b]/80 text-[11px] italic leading-relaxed font-medium px-4">"{t('remembranceVerse')}"</p>
        </div>
      </div>

      {/* Add Dhikr Modal Overlay */}
      {isAddingDhikr && (
        <div className="absolute inset-0 z-[100] bg-[#064e3b]/80 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in">
          <div className="w-full max-w-sm bg-white rounded-[40px] p-8 shadow-2xl animate-fade-up">
            <h3 className="text-2xl font-black text-emerald-900 mb-6 tracking-tight text-center">{t('addDhikr')}</h3>
            <div className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">{t('dhikrName')}</label>
                <input 
                  type="text" 
                  autoFocus
                  className="w-full p-4 bg-slate-50 border border-slate-100 rounded-[20px] focus:ring-2 focus:ring-emerald-500/10 outline-none text-emerald-900 font-bold"
                  placeholder="e.g. Subhanallah"
                  value={newDhikrName}
                  onChange={e => setNewDhikrName(e.target.value)}
                  onKeyPress={e => e.key === 'Enter' && handleAddDhikr()}
                />
              </div>
              <div className="flex gap-3 pt-2">
                <button onClick={() => setIsAddingDhikr(false)} className="flex-1 py-4 text-slate-400 font-black text-[10px] uppercase tracking-widest">{t('back')}</button>
                <button onClick={handleAddDhikr} className="flex-1 py-4 bg-[#064e3b] text-white rounded-[20px] font-black text-[10px] uppercase tracking-widest shadow-xl">{t('save')}</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DhikrCounter;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { UserData, QuranProgress, PrayerTimings } from '../types';
import { SURAHS } from '../constants';

interface QuranTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  onUpdate: (progress: QuranProgress) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QuranTracker: React.FC<QuranTrackerProps> = ({ state, onUpdate, setCurrentView, t }) => {
  const [surahInput, setSurahInput] = useState(state.quranProgress.surah || '');
  const [ayahInput, setAyahInput] = useState(state.quranProgress.ayah || '');
  const [juzInput, setJuzInput] = useState(state.quranProgress.juz || '');
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSurahs = useMemo(() => {
    if (!surahInput) return SURAHS.slice(0, 5);
    return SURAHS.filter(s => s.toLowerCase().includes(surahInput.toLowerCase())).slice(0, 5);
  }, [surahInput]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSave = () => {
    onUpdate({
      surah: surahInput,
      ayah: ayahInput,
      juz: juzInput,
      lastUpdated: new Date().toISOString()
    });
    if ('vibrate' in navigator) navigator.vibrate(40);
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc] animate-fade-up">
      <div className="p-6 pt-12 pb-10 bg-gradient-to-br from-amber-600 to-amber-800 text-white shadow-xl rounded-b-[48px] z-20 shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={() => setCurrentView('dashboard')} className="w-12 h-12 flex items-center justify-center bg-white/10 rounded-2xl border border-white/20 active:scale-90">
            <i className="fas fa-chevron-left"></i>
          </button>
          <div>
            <h1 className="text-2xl font-black tracking-tight">{t('quran')}</h1>
            <p className="text-[10px] text-amber-200 font-black uppercase tracking-[0.2em]">Divine Guidance</p>
          </div>
        </div>
      </div>

      <div className="flex-1 p-6 flex flex-col gap-6 overflow-y-auto">
        <div className="bg-white p-6 rounded-[36px] shadow-premium border border-amber-50 relative overflow-hidden text-center">
          <div className="absolute top-0 right-0 w-32 h-32 bg-amber-50 rounded-full -mr-16 -mt-16 blur-3xl opacity-50"></div>
          <div className="w-16 h-16 bg-gradient-to-br from-amber-100 to-amber-200 rounded-3xl flex items-center justify-center mx-auto mb-4 text-amber-600 text-2xl animate-float shadow-lg">
            <i className="fas fa-book-open"></i>
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('lastRead')}</p>
          <h2 className="text-xl font-black text-emerald-900 leading-tight">
            {state.quranProgress.surah ? `${state.quranProgress.surah}, ${t('ayah')} ${state.quranProgress.ayah}` : '---'}
          </h2>
          {state.quranProgress.juz && <p className="text-[10px] font-bold text-amber-600 mt-1 uppercase tracking-widest">{t('juz')} {state.quranProgress.juz}</p>}
        </div>

        <div className="space-y-6">
          <div className="space-y-2 relative" ref={dropdownRef}>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">{t('surah')}</label>
            <input 
              type="text" 
              placeholder="e.g. Al-Baqarah"
              className="w-full p-4.5 bg-white border border-slate-100 rounded-[24px] focus:ring-4 focus:ring-amber-500/10 outline-none shadow-sm font-bold text-emerald-900"
              value={surahInput}
              onFocus={() => setShowDropdown(true)}
              onChange={(e) => {
                setSurahInput(e.target.value);
                setShowDropdown(true);
              }}
            />
            {showDropdown && filteredSurahs.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[24px] shadow-2xl border border-slate-50 p-2 z-50 animate-fade-in">
                {filteredSurahs.map(s => (
                  <button 
                    key={s}
                    onClick={() => {
                      setSurahInput(s);
                      setShowDropdown(false);
                    }}
                    className="w-full text-left px-5 py-3 hover:bg-amber-50 rounded-xl text-sm font-bold text-emerald-900 transition-colors"
                  >
                    {s}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">{t('juz')}</label>
              <input 
                type="number" 
                placeholder="1-30"
                className="w-full p-4.5 bg-white border border-slate-100 rounded-[24px] focus:ring-4 focus:ring-amber-500/10 outline-none shadow-sm font-bold text-emerald-900"
                value={juzInput}
                onChange={(e) => setJuzInput(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">{t('ayah')}</label>
              <input 
                type="number" 
                placeholder="Verse #"
                className="w-full p-4.5 bg-white border border-slate-100 rounded-[24px] focus:ring-4 focus:ring-amber-500/10 outline-none shadow-sm font-bold text-emerald-900"
                value={ayahInput}
                onChange={(e) => setAyahInput(e.target.value)}
              />
            </div>
          </div>

          <button 
            onClick={handleSave}
            className="w-full py-5 bg-gradient-to-r from-amber-600 to-amber-700 text-white rounded-[28px] font-black text-sm uppercase tracking-[0.2em] shadow-xl shadow-amber-900/20 active:scale-95 transition-all"
          >
            {t('save')}
          </button>
        </div>

        <div className="mt-4 glass-card p-6 rounded-[36px] border border-amber-100 shadow-sm relative overflow-hidden shrink-0">
          <div className="absolute top-0 right-0 p-4 opacity-[0.05] pointer-events-none rotate-12"><i className="fas fa-moon text-6xl"></i></div>
          <h3 className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-3 flex items-center gap-2">
            <i className="fas fa-sparkles text-[10px]"></i>
            {t('quranVirtue')}
          </h3>
          <div className="space-y-4">
            <p className="text-emerald-900 arabic-font text-xl leading-relaxed text-right font-bold" dir="rtl">
              مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ
            </p>
            <p className="text-slate-500 text-[11px] leading-relaxed italic border-l-2 border-amber-200 pl-4 font-medium">
              "Whoever reads a letter from the Book of Allah, he will have a reward. And that reward will be multiplied by ten..."
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QuranTracker;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;
    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) navigator.vibrate([20, 40]);
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', iconBg: 'bg-emerald-50 text-emerald-600', gradient: 'from-emerald-50 to-emerald-100' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', iconBg: 'bg-teal-50 text-teal-600', gradient: 'from-teal-50 to-teal-100' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', iconBg: 'bg-amber-50 text-amber-600', gradient: 'from-amber-50 to-amber-100' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', iconBg: 'bg-blue-50 text-blue-600', gradient: 'from-blue-50 to-blue-100' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', iconBg: 'bg-indigo-50 text-indigo-600', gradient: 'from-indigo-50 to-indigo-100' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', iconBg: 'bg-green-50 text-green-600', gradient: 'from-green-50 to-green-100' },
    { id: 'account', label: t('myAccount'), icon: 'fa-user-circle', iconBg: 'bg-orange-50 text-orange-600', gradient: 'from-orange-50 to-orange-100' },
    ...(state.profile?.sex === 'female' ? [{ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', iconBg: 'bg-rose-50 text-rose-600', gradient: 'from-rose-50 to-rose-100' }] : [])
  ];

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name, timingsMinutes };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="h-full w-full flex flex-col bg-[#fdfbf7] overflow-hidden view-transition">
      <header className="relative w-full bg-emerald-900 text-white pt-10 pb-12 px-8 rounded-b-[60px] shadow-emerald-premium shrink-0">
        <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-400/10 rounded-full blur-3xl -mr-24 -mt-24 pointer-events-none"></div>
        <div className="relative z-10 w-full flex flex-col gap-6">
          <div className="flex justify-between items-center w-full">
            <div className="flex items-center gap-4">
              <div 
                onClick={() => setCurrentView('account')}
                className="w-14 h-14 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-xl cursor-pointer active:scale-90 transition-all shadow-xl"
              >
                <i className="fas fa-user-circle text-emerald-200 text-2xl"></i>
              </div>
              <div>
                <span className="text-[10px] font-black text-emerald-300 uppercase tracking-[0.2em] block opacity-70">Marhaban</span>
                <h1 className="text-xl font-black truncate max-w-[200px] tracking-tight">{state.profile?.name}</h1>
              </div>
            </div>
            <div className="flex gap-2.5">
              <button onClick={() => setCurrentView('about')} className="w-11 h-11 rounded-2xl flex items-center justify-center bg-white/10 border border-white/10 hover:bg-white/20 transition-all active:scale-95"><i className="fas fa-info text-xs"></i></button>
              <button onClick={toggleNotifications} className={`w-11 h-11 rounded-2xl flex items-center justify-center border transition-all active:scale-95 shadow-lg ${state.settings.notificationsEnabled ? 'bg-amber-500 border-amber-400 text-white' : 'bg-white/10 border-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-xs`}></i></button>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white/5 backdrop-blur-md p-4 rounded-[32px] border border-white/10 shadow-inner">
              <span className="text-[8px] text-emerald-300 font-black uppercase tracking-[0.2em] block mb-1">{t('dhikr')}</span>
              <div className="flex items-baseline gap-1.5">
                <span className="text-2xl font-black tabular-nums tracking-tighter">{state.dhikrCount.toLocaleString()}</span>
                <i className="fas fa-sparkles text-[10px] text-amber-300"></i>
              </div>
            </div>
            <div className="bg-white/5 backdrop-blur-md p-4 rounded-[32px] border border-white/10 shadow-inner">
              <span className="text-[8px] text-emerald-300 font-black uppercase tracking-[0.2em] block mb-1">{t('lastRead')}</span>
              <span className="text-sm font-black truncate block tracking-tight">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      <div className="flex-1 px-6 flex flex-col justify-around py-6 overflow-hidden">
        <div className="bg-white p-6 rounded-[48px] shadow-premium border border-slate-50 relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50 rounded-full blur-3xl -mr-16 -mt-16 transition-all group-hover:bg-emerald-100"></div>
          <div className="flex items-center justify-between relative z-10">
            <div>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em] block mb-2">{t('nextPrayer')}</span>
              <div className="flex items-center gap-3">
                <h2 className="text-3xl font-black text-emerald-900 capitalize tracking-tighter">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <div className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-xl text-[10px] font-black border border-emerald-100 shadow-sm">{prayerTimingData?.next.time}</div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-3xl font-black text-amber-600 tabular-nums tracking-tighter">{prayerTimingData?.timeLeft || '--:--'}</div>
              <span className="text-[9px] font-black text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>
          <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden mt-6 p-1">
            <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(16,185,129,0.4)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-[48px] border border-slate-50 shadow-premium overflow-hidden relative">
          <div className="flex items-center gap-2 mb-3">
            <span className="bg-amber-100 text-amber-600 text-[9px] font-black px-3 py-1.5 rounded-full uppercase tracking-widest inline-block">Daily Wisdom</span>
            <i className="fas fa-quote-right text-emerald-50 opacity-20 text-3xl absolute right-6 top-6"></i>
          </div>
          <p className="text-emerald-900 arabic-font text-lg leading-tight text-right mb-4 font-bold" dir="rtl">{dailyHadith.arabic}</p>
          <p className="text-slate-500 italic text-xs leading-relaxed border-l-4 border-emerald-100 pl-4">"{dailyHadith[userLang]}"</p>
        </div>

        <div className="bg-white p-6 rounded-[48px] shadow-premium border border-slate-50">
          <div className="flex justify-between items-center mb-4">
             <h3 className="text-[10px] font-black text-emerald-900 uppercase tracking-[0.2em]">{t('todayPrayers')}</h3>
             {state.isHaydNifas && <span className="text-[9px] font-black px-3 py-1 bg-rose-50 text-rose-600 rounded-full border border-rose-100">{t('excused')}</span>}
          </div>
          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              return (
                <button 
                  key={p} 
                  disabled={state.isHaydNifas} 
                  onClick={() => handlePrayerToggle(p)} 
                  className={`flex flex-col items-center p-3 rounded-[32px] border-2 transition-all active:scale-90 ${status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-200 shadow-lg text-emerald-800' : 'bg-slate-50 border-transparent text-slate-300'} ${state.isHaydNifas ? 'opacity-30' : ''}`}
                >
                  <span className="text-[9px] font-black uppercase mb-3 tracking-tighter">{t(p).substring(0,3)}</span>
                  <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shadow-md transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white border border-slate-100'}`}>
                    <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-circle'} text-xs`}></i>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4">
          {menuItems.map((item) => (
            <button 
              key={item.id} 
              onClick={() => setCurrentView(item.id)} 
              className={`flex flex-col items-center justify-center p-4 rounded-[42px] transition-all active:scale-90 border border-slate-50 shadow-premium hover:shadow-xl group bg-white bg-gradient-to-b ${item.gradient}`}
            >
              <div className={`w-12 h-12 rounded-[22px] ${item.iconBg} flex items-center justify-center mb-3 transition-all group-hover:-translate-y-1 group-hover:rotate-6 shadow-md border-4 border-white`}>
