    let parsedUsers: Record<string, UserData> = {};
    try {
      parsedUsers = savedUsers ? JSON.parse(savedUsers) : {};
    } catch (e) {
      console.error("Failed to parse users database", e);
    }

    // Ensure the currentUser actually exists in the users database to prevent stale session errors
    const currentUser = (activeSession && parsedUsers[activeSession]) ? activeSession : null;

    return {
      currentUser, 
      users: parsedUsers,
      todayTimings: DEFAULT_TIMINGS
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      return state.users[state.currentUser].profile.preferredLanguage;
    }
    return 'en';
  });

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'account'>(() => {
    return (state.currentUser && state.users[state.currentUser]) ? 'dashboard' : 'welcome';
  });

  // Sync state to LocalStorage whenever users or session changes
  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();

    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username }, // Ensure username is saved in profile
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        personalDhikrs: [],
        activeDhikrId: null,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };

      setState(prev => ({
        ...prev,
        currentUser: username,
        users: { ...prev.users, [username]: newUserData }
      }));
    } else {
      // For existing users, update current user session
      setState(prev => ({ ...prev, currentUser: username }));
    }

    setCurrentLanguage(profile.preferredLanguage);
    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const currentUser = prev.currentUser!;
      const userToUpdate = prev.users[currentUser];
      if (!userToUpdate) return prev;

      return {
        ...prev,
        users: {
          ...prev.users,
          [currentUser]: updater(userToUpdate)
        }
      };
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(user => {
      const currentLogs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return {
        ...user,
        prayerLogs: { ...user.prayerLogs, [date]: { ...currentLogs, [prayer]: status } }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(user => {
      const current = user.sunnahLogs[date] || [];
      const updated = current.includes(sunnahName) ? current.filter(s => s !== sunnahName) : [...current, sunnahName];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: updated } };
    });
  };

  const setActiveDhikr = (id: string | null) => {
    updateActiveUser(user => ({ ...user, activeDhikrId: id }));
  };

  const updateDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const updatedChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: c.current + delta } : c
      );
      return { ...user, activeChallenges: updatedChallenges, dhikrCount: user.dhikrCount + delta };
    });
  };

  const updatePersonalDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const today = new Date().toISOString().split('T')[0];
      const updatedDhikrs = user.personalDhikrs.map(d => {
        if (d.id === id) {
          const isNewDay = d.lastUpdated.split('T')[0] !== today;
          return {
            ...d,
            totalCount: d.totalCount + delta,
            dailyCount: isNewDay ? delta : d.dailyCount + delta,
            sessionCount: d.sessionCount + delta,
            lastUpdated: new Date().toISOString()
          };
        }
        return d;
      });
      return { ...user, personalDhikrs: updatedDhikrs, dhikrCount: user.dhikrCount + delta };
    });
  };

  const addPersonalDhikr = (name: string) => {
    updateActiveUser(user => {
      const newDhikr: PersonalDhikr = {
        id: `personal-${Date.now()}`,
        name,
        totalCount: 0,
        dailyCount: 0,
        sessionCount: 0,
        lastUpdated: new Date().toISOString()
      };
      return { ...user, personalDhikrs: [newDhikr, ...user.personalDhikrs] };
    });
  };

  const resetPersonalSession = (id: string) => {
    updateActiveUser(user => {
      const updatedDhikrs = user.personalDhikrs.map(d => 
        d.id === id ? { ...d, sessionCount: 0 } : d
      );
      return { ...user, personalDhikrs: updatedDhikrs };
    });
  };

  const deletePersonalDhikr = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      personalDhikrs: user.personalDhikrs.filter(d => d.id !== id)
    }));
  };

  const archiveDhikrChallenge = (id: string) => {
    updateActiveUser(user => {
      const challenge = user.activeChallenges.find(c => c.id === id);
      if (!challenge) return user;
      const historyEntry: DhikrHistoryEntry = {
        id: `${id}-${Date.now()}`,
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };
      const resetChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: 0 } : c
      );
      return { 
        ...user, 
        activeChallenges: resetChallenges, 
        dhikrHistory: [historyEntry, ...user.dhikrHistory],
        activeDhikrId: null
      };
    });
  };

  const updateQuran = (progress: QuranProgress) => {
    updateActiveUser(user => ({ ...user, quranProgress: progress }));
  };

  const updateFasting = (date: string, log: FastingLog) => {
    updateActiveUser(user => ({
      ...user,
      fastingLogs: { ...user.fastingLogs, [date]: log }
    }));
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(user => ({ ...user, isHaydNifas: active }));
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: [...user.healthPeriods, { id: Date.now().toString(), start, end }]
    }));
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: user.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={compositeState} 
            updateProgress={updateDhikrProgress} 
            updatePersonalProgress={updatePersonalDhikrProgress}
            addPersonalDhikr={addPersonalDhikr}
            resetPersonalSession={resetPersonalSession}
            deletePersonalDhikr={deletePersonalDhikr}
            archiveChallenge={archiveDhikrChallenge} 
            setActiveDhikr={setActiveDhikr} 
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={updateQuran} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={updateFasting} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [animatingPrayer, setAnimatingPrayer] = useState<string | null>(null);
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const handlePrayerToggle = (prayer: typeof PRAYERS[number]) => {
    if (state.isHaydNifas) return;
    const currentStatus = todayLogs[prayer];
    const newStatus = currentStatus === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
    if (newStatus === PrayerStatus.COMPLETED) {
      setAnimatingPrayer(prayer);
      setTimeout(() => setAnimatingPrayer(null), 800);
      if ('vibrate' in navigator) navigator.vibrate([20, 40]);
    }
    updatePrayerStatus(today, prayer, newStatus);
  };

  const menuItems = [
    { id: 'fard', label: t('fard'), icon: 'fa-kaaba', iconBg: 'bg-emerald-50 text-emerald-600', gradient: 'from-emerald-50 to-emerald-100' },
    { id: 'qibla', label: t('qibla'), icon: 'fa-compass', iconBg: 'bg-teal-50 text-teal-600', gradient: 'from-teal-50 to-teal-100' },
    { id: 'qadah', label: t('qadah'), icon: 'fa-calendar-day', iconBg: 'bg-amber-50 text-amber-600', gradient: 'from-amber-50 to-amber-100' },
    { id: 'quran', label: t('quran'), icon: 'fa-book-open', iconBg: 'bg-blue-50 text-blue-600', gradient: 'from-blue-50 to-blue-100' },
    { id: 'fasting', label: t('fasting'), icon: 'fa-moon', iconBg: 'bg-indigo-50 text-indigo-600', gradient: 'from-indigo-50 to-indigo-100' },
    { id: 'dhikr', label: t('dhikr'), icon: 'fa-seedling', iconBg: 'bg-green-50 text-green-600', gradient: 'from-green-50 to-green-100' },
    { id: 'account', label: t('myAccount'), icon: 'fa-user-circle', iconBg: 'bg-orange-50 text-orange-600', gradient: 'from-orange-50 to-orange-100' },
    ...(state.profile?.sex === 'female' ? [{ id: 'women', label: t('womensSpace'), icon: 'fa-leaf', iconBg: 'bg-rose-50 text-rose-600', gradient: 'from-rose-50 to-rose-100' }] : [])
  ];

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name, timingsMinutes };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="h-full w-full flex flex-col bg-[#fdfbf7] overflow-hidden view-transition">
      <header className="relative w-full bg-emerald-900 text-white pt-10 pb-12 px-8 rounded-b-[60px] shadow-emerald-premium shrink-0">
        <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-400/10 rounded-full blur-3xl -mr-24 -mt-24 pointer-events-none"></div>
        <div className="relative z-10 w-full flex flex-col gap-6">
          <div className="flex justify-between items-center w-full">
            <div className="flex items-center gap-4">
              <div 
                onClick={() => setCurrentView('account')}
                className="w-14 h-14 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20 backdrop-blur-xl cursor-pointer active:scale-90 transition-all shadow-xl"
              >
                <i className="fas fa-user-circle text-emerald-200 text-2xl"></i>
              </div>
              <div className="overflow-hidden">
                <div className="flex items-baseline gap-2">
                  <span className="text-[10px] font-black text-emerald-300 uppercase tracking-[0.2em] block opacity-70 shrink-0">Marhaban</span>
                  <span className="text-[10px] font-black text-emerald-300/40 uppercase tracking-widest truncate opacity-60">@{state.profile?.username || 'user'}</span>
                </div>
                <h1 className="text-xl font-black truncate max-w-[200px] tracking-tight">{state.profile?.name || 'Habibi'}</h1>
              </div>
            </div>
            <div className="flex gap-2.5">
              <button onClick={() => setCurrentView('about')} className="w-11 h-11 rounded-2xl flex items-center justify-center bg-white/10 border border-white/10 hover:bg-white/20 transition-all active:scale-95"><i className="fas fa-info text-xs"></i></button>
              <button onClick={toggleNotifications} className={`w-11 h-11 rounded-2xl flex items-center justify-center border transition-all active:scale-95 shadow-lg ${state.settings.notificationsEnabled ? 'bg-amber-500 border-amber-400 text-white' : 'bg-white/10 border-white/10'}`}><i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'} text-xs`}></i></button>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white/5 backdrop-blur-md p-4 rounded-[32px] border border-white/10 shadow-inner">
              <span className="text-[8px] text-emerald-300 font-black uppercase tracking-[0.2em] block mb-1">{t('dhikr')}</span>
              <div className="flex items-baseline gap-1.5">
                <span className="text-2xl font-black tabular-nums tracking-tighter">{state.dhikrCount.toLocaleString()}</span>
                <i className="fas fa-sparkles text-[10px] text-amber-300"></i>
              </div>
            </div>
            <div className="bg-white/5 backdrop-blur-md p-4 rounded-[32px] border border-white/10 shadow-inner">
              <span className="text-[8px] text-emerald-300 font-black uppercase tracking-[0.2em] block mb-1">{t('lastRead')}</span>
              <span className="text-sm font-black truncate block tracking-tight">{state.quranProgress.surah || '---'}</span>
            </div>
          </div>
        </div>
      </header>

      <div className="flex-1 px-6 flex flex-col justify-around py-6 overflow-hidden">
        <div className="bg-white p-6 rounded-[48px] shadow-premium border border-slate-50 relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50 rounded-full blur-3xl -mr-16 -mt-16 transition-all group-hover:bg-emerald-100"></div>
          <div className="flex items-center justify-between relative z-10">
            <div>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em] block mb-2">{t('nextPrayer')}</span>
              <div className="flex items-center gap-3">
                <h2 className="text-3xl font-black text-emerald-900 capitalize tracking-tighter">{prayerTimingData ? t(prayerTimingData.next.name) : '--'}</h2>
                <div className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-xl text-[10px] font-black border border-emerald-100 shadow-sm">{prayerTimingData?.next.time}</div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-3xl font-black text-amber-600 tabular-nums tracking-tighter">{prayerTimingData?.timeLeft || '--:--'}</div>
              <span className="text-[9px] font-black text-slate-400 block uppercase tracking-tighter">Remaining</span>
            </div>
          </div>
          <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden mt-6 p-1">
            <div className="bg-emerald-600 h-full rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(16,185,129,0.4)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-[48px] border border-slate-50 shadow-premium overflow-hidden relative">
          <div className="flex items-center gap-2 mb-3">
            <span className="bg-amber-100 text-amber-600 text-[9px] font-black px-3 py-1.5 rounded-full uppercase tracking-widest inline-block">Daily Wisdom</span>
            <i className="fas fa-quote-right text-emerald-50 opacity-20 text-3xl absolute right-6 top-6"></i>
          </div>
          <p className="text-emerald-900 arabic-font text-lg leading-tight text-right mb-4 font-bold" dir="rtl">{dailyHadith.arabic}</p>
          <p className="text-slate-500 italic text-xs leading-relaxed border-l-4 border-emerald-100 pl-4">"{dailyHadith[userLang]}"</p>
        </div>

        <div className="bg-white p-6 rounded-[48px] shadow-premium border border-slate-50">
          <div className="flex justify-between items-center mb-4">
             <h3 className="text-[10px] font-black text-emerald-900 uppercase tracking-[0.2em]">{t('todayPrayers')}</h3>
             {state.isHaydNifas && <span className="text-[9px] font-black px-3 py-1 bg-rose-50 text-rose-600 rounded-full border border-rose-100">{t('excused')}</span>}
          </div>
          <div className="grid grid-cols-5 gap-3">
            {PRAYERS.map((p) => {
              const status = todayLogs[p];
              return (
                <button 
                  key={p} 
                  disabled={state.isHaydNifas} 
                  onClick={() => handlePrayerToggle(p)} 
                  className={`flex flex-col items-center p-3 rounded-[32px] border-2 transition-all active:scale-90 ${status === PrayerStatus.COMPLETED ? 'bg-emerald-50 border-emerald-200 shadow-lg text-emerald-800' : 'bg-slate-50 border-transparent text-slate-300'} ${state.isHaydNifas ? 'opacity-30' : ''}`}
                >
                  <span className="text-[9px] font-black uppercase mb-3 tracking-tighter">{t(p).substring(0,3)}</span>
                  <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shadow-md transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-white border border-slate-100'}`}>
                    <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-circle'} text-xs`}></i>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4">
          {menuItems.map((item) => (
            <button 
              key={item.id} 
              onClick={() => setCurrentView(item.id)} 
              className={`flex flex-col items-center justify-center p-4 rounded-[42px] transition-all active:scale-90 border border-slate-50 shadow-premium hover:shadow-xl group bg-white bg-gradient-to-b ${item.gradient}`}
            >
              <div className={`w-12 h-12 rounded-[22px] ${item.iconBg} flex items-center justify-center mb-3 transition-all group-hover:-translate-y-1 group-hover:rotate-6 shadow-md border-4 border-white`}>
                <i className={`fas ${item.icon} text-xl`}></i>
              </div>
              <span className="text-[10px] font-black text-center uppercase tracking-tighter text-slate-700 truncate w-full group-hover:text-emerald-900">{item.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  // Normalize username for checks
  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  // Instant availability check
  const usernameStatus = useMemo(() => {
    if (mode === 'login' || usernameNormalized.length < 3) return 'idle';
    return users[usernameNormalized] ? 'taken' : 'available';
  }, [usernameNormalized, mode, users]);

  // Dynamic suggestions
  const suggestions = useMemo(() => {
    if (usernameStatus !== 'taken') return [];
    const base = usernameNormalized;
    const items = [
      `${base}${Math.floor(Math.random() * 99) + 1}`,
      `${base}_ibadathi`,
      `${base}_seeker`
    ];
    return [...new Set(items)].filter(s => !users[s.toLowerCase()]);
  }, [usernameStatus, usernameNormalized, users]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password) return "Password is required.";

    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (usernameStatus === 'taken') return t('usernameTaken');
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setIsAuthenticating(true);

    // Simulate authentication processing delay
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];

        // Check if user exists
        if (!user) {
          setError("User not found.");
          setIsAuthenticating(false);
          return;
        }

        // Refined password check: strict case-sensitive comparison
        const storedPassword = user.profile.password;
        if (storedPassword !== formData.password) {
          setError("Incorrect password.");
          setIsAuthenticating(false);
          return;
        }

        // If successful, login
        onLogin(user.profile, false);
      } else {
        // Registration logic
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password // Plain text for mock backend persistence
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 600);
  };

  const inputClasses = "w-full px-4 py-3 bg-white border border-slate-100 rounded-[20px] focus:ring-2 focus:ring-emerald-600/10 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-200 text-sm";
  const labelClasses = "block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1.5";

  return (
    <div className="p-6 flex flex-col items-center justify-center h-full bg-[#fdfbf7] view-transition overflow-hidden">
      <div className="w-16 h-16 bg-emerald-900 rounded-[28px] flex items-center justify-center mb-4 shadow-2xl border-2 border-white rotate-3 shrink-0">
        <i className="fas fa-mosque text-2xl text-emerald-100"></i>
      </div>
      <h1 className="text-3xl font-black text-emerald-900 mb-1 tracking-tighter shrink-0">Ibadathi</h1>
      <p className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.2em] mb-6 shrink-0">Sacred Companion</p>

      <div className="flex bg-emerald-50 p-1.5 rounded-2xl mb-6 w-full max-w-[240px] shrink-0 border border-emerald-100/50">
        <button 
          type="button"
          onClick={() => { setMode('login'); setError(null); }}
          className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('login')}
        </button>
        <button 
          type="button"
          onClick={() => { setMode('register'); setError(null); }}
          className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40'}`}
        >
          {t('register')}
        </button>
      </div>

      <form onSubmit={handleSubmit} className="w-full space-y-4 max-w-[320px] flex-1 flex flex-col justify-center overflow-y-auto pr-1">
        {error && (
          <div className="bg-rose-50 text-rose-600 p-3 rounded-2xl text-[10px] font-bold text-center border border-rose-100 animate-fade-up shrink-0">
            <i className="fas fa-exclamation-circle mr-2"></i> {error}
          </div>
        )}

        <div className="space-y-1.5 shrink-0">
          <label className={labelClasses}>{t('username')}</label>
          <div className="relative">
            <input 
              type="text" 
              className={`${inputClasses} ${usernameStatus === 'taken' ? 'border-rose-300 bg-rose-50/10' : usernameStatus === 'available' ? 'border-emerald-300 bg-emerald-50/10' : ''}`}
              placeholder="muslim_seeker"
              value={formData.username}
              onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})}
              required
            />
            {usernameStatus === 'available' && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-600 animate-fade-in">
                <i className="fas fa-check-circle"></i>
              </div>
            )}
            {usernameStatus === 'taken' && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-rose-600 animate-shake">
                <i className="fas fa-times-circle"></i>
              </div>
            )}
          </div>

          {usernameStatus === 'available' && (
            <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest ml-1 animate-fade-up">
              <i className="fas fa-info-circle mr-1"></i> {t('usernameAvailable')}
            </p>
          )}
          {usernameStatus === 'taken' && (
            <div className="animate-fade-up">
              <p className="text-[9px] font-black text-rose-600 uppercase tracking-widest ml-1">
                <i className="fas fa-exclamation-triangle mr-1"></i> {t('usernameTaken')}
              </p>
              <div className="mt-3 p-3 bg-rose-50/50 rounded-2xl border border-rose-100/50">
                <p className="text-[8px] font-black text-rose-800/60 uppercase tracking-widest mb-2">{t('suggestions')}</p>
                <div className="flex flex-wrap gap-2">
                  {suggestions.map(s => (
                    <button 
                      key={s} 
                      type="button"
                      onClick={() => setFormData({...formData, username: s})}
                      className="bg-white px-2.5 py-1.5 rounded-xl text-[9px] font-black text-rose-900 border border-rose-200 active:scale-95 transition-all shadow-sm hover:border-emerald-400 hover:text-emerald-700"
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        {mode === 'register' && (
          <div className="space-y-4 shrink-0 animate-fade-up">
            <div className="space-y-1.5">
              <label className={labelClasses}>{t('name')}</label>
              <input 
                type="text"
                className={inputClasses}
                placeholder="Abdullah Al-Fulan"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className={labelClasses}>{t('age')}</label>
                <input 
                  type="number"
                  className={inputClasses}
                  placeholder="25"
                  value={formData.age}
                  onChange={e => setFormData({...formData, age: e.target.value})}
                  required
                />
              </div>
              <div className="space-y-1.5">
                <label className={labelClasses}>{t('sex')}</label>
                <select 
                  className={`${inputClasses} appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22none%22%20viewBox%3D%220%200%2024%2024%22%20stroke%3D%22%2364748b%22%3E%3Cpath%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%222%22%20d%3D%22M19%209l-7%207-7-7%22%20%2F%3E%3C%2Fsvg%3E')] bg-[length:0.8em_0.8em] bg-[right_1rem_center] bg-no-repeat`}
                  value={formData.sex}
                  onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                >
                  <option value="male">{t('male')}</option>
                  <option value="female">{t('female')}</option>
                </select>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className={labelClasses}>{t('place')}</label>
              <input 
                type="text"
                className={inputClasses}
                placeholder="Makkah, KSA"
                value={formData.place}
                onChange={e => setFormData({...formData, place: e.target.value})}
                required
              />
            </div>
          </div>
        )}

        <div className="space-y-1.5 shrink-0">
          <label className={labelClasses}>{t('password')}</label>
          <input 
            type="password"
            className={inputClasses}
            placeholder="••••••••"
            value={formData.password}
            onChange={e => setFormData({...formData, password: e.target.value})}
            required
          />
        </div>

        <button 
          type="submit"
          disabled={isAuthenticating || (mode === 'register' && usernameStatus !== 'available')}
          className="w-full bg-emerald-900 text-white font-black py-4 rounded-[24px] transition-all active:scale-[0.98] mt-4 uppercase tracking-[0.25em] text-[10px] flex items-center justify-center gap-3 shrink-0 disabled:opacity-30 shadow-2xl shadow-emerald-900/20"
        >
          {isAuthenticating ? (
            <i className="fas fa-spinner fa-spin"></i>
          ) : (
            <>
              {mode === 'login' ? t('login') : t('register')}
              <i className="fas fa-arrow-right text-[8px] opacity-40"></i>
            </>
          )}
        </button>
      </form>

      <div className="mt-8 flex items-center gap-2 opacity-5 shrink-0 grayscale">
        <i className="fas fa-award text-emerald-900 text-xl"></i>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PersonalDhikr, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// UNIFIED STORAGE KEYS - DO NOT CHANGE
const USERS_DB_KEY = 'ibadathi_v1_users_database';
const SESSION_KEY = 'ibadathi_v1_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12",
  Sunrise: "06:34",
  Dhuhr: "12:28",
  Asr: "15:42",
  Maghrib: "18:22",
  Isha: "19:38"
};

const App: React.FC = () => {
  // Load initial state from LocalStorage with robust validation
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);

    let parsedUsers: Record<string, UserData> = {};
    try {
      parsedUsers = savedUsers ? JSON.parse(savedUsers) : {};
    } catch (e) {
      console.error("Failed to parse users database", e);
    }

    // Ensure the currentUser actually exists in the users database to prevent stale session errors
    const currentUser = (activeSession && parsedUsers[activeSession]) ? activeSession : null;

    return {
      currentUser, 
      users: parsedUsers,
      todayTimings: DEFAULT_TIMINGS
    };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      return state.users[state.currentUser].profile.preferredLanguage;
    }
    return 'en';
  });

  const [currentView, setCurrentView] = useState<'welcome' | 'login' | 'dashboard' | 'fard' | 'qadah' | 'women' | 'dhikr' | 'quran' | 'fasting' | 'qibla' | 'about' | 'account'>(() => {
    return (state.currentUser && state.users[state.currentUser]) ? 'dashboard' : 'welcome';
  });

  // Sync state to LocalStorage whenever users or session changes
  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();

    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username }, // Ensure username is saved in profile
        prayerLogs: {},
        sunnahLogs: {},
        fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0,
        activeChallenges: INITIAL_DHIKRS,
        personalDhikrs: [],
        activeDhikrId: null,
        dhikrHistory: [],
        isHaydNifas: false,
        haydStartDate: null,
        healthPeriods: [],
        settings: {
          notificationsEnabled: false,
          locationEnabled: false,
          qadaReminders: []
        }
      };

      setState(prev => ({
        ...prev,
        currentUser: username,
        users: { ...prev.users, [username]: newUserData }
      }));
    } else {
      // Restore language from saved profile for existing users
      if (profile.preferredLanguage) {
        setCurrentLanguage(profile.preferredLanguage);
      }
      setState(prev => ({ ...prev, currentUser: username }));
    }

    setCurrentView('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setCurrentView('welcome');
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const currentUser = prev.currentUser!;
      const userToUpdate = prev.users[currentUser];
      if (!userToUpdate) return prev;

      return {
        ...prev,
        users: {
          ...prev.users,
          [currentUser]: updater(userToUpdate)
        }
      };
    });
  };

  const updatePrayerStatus = (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => {
    updateActiveUser(user => {
      const currentLogs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return {
        ...user,
        prayerLogs: { ...user.prayerLogs, [date]: { ...currentLogs, [prayer]: status } }
      };
    });
  };

  const toggleSunnahStatus = (date: string, sunnahName: string) => {
    updateActiveUser(user => {
      const current = user.sunnahLogs[date] || [];
      const updated = current.includes(sunnahName) ? current.filter(s => s !== sunnahName) : [...current, sunnahName];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: updated } };
    });
  };

  const setActiveDhikr = (id: string | null) => {
    updateActiveUser(user => ({ ...user, activeDhikrId: id }));
  };

  const updateDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const updatedChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: c.current + delta } : c
      );
      return { ...user, activeChallenges: updatedChallenges, dhikrCount: user.dhikrCount + delta };
    });
  };

  const updatePersonalDhikrProgress = (id: string, delta: number) => {
    updateActiveUser(user => {
      const today = new Date().toISOString().split('T')[0];
      const updatedDhikrs = user.personalDhikrs.map(d => {
        if (d.id === id) {
          const isNewDay = d.lastUpdated.split('T')[0] !== today;
          return {
            ...d,
            totalCount: d.totalCount + delta,
            dailyCount: isNewDay ? delta : d.dailyCount + delta,
            sessionCount: d.sessionCount + delta,
            lastUpdated: new Date().toISOString()
          };
        }
        return d;
      });
      return { ...user, personalDhikrs: updatedDhikrs, dhikrCount: user.dhikrCount + delta };
    });
  };

  const addPersonalDhikr = (name: string) => {
    updateActiveUser(user => {
      const newDhikr: PersonalDhikr = {
        id: `personal-${Date.now()}`,
        name,
        totalCount: 0,
        dailyCount: 0,
        sessionCount: 0,
        lastUpdated: new Date().toISOString()
      };
      return { ...user, personalDhikrs: [newDhikr, ...user.personalDhikrs] };
    });
  };

  const resetPersonalSession = (id: string) => {
    updateActiveUser(user => {
      const updatedDhikrs = user.personalDhikrs.map(d => 
        d.id === id ? { ...d, sessionCount: 0 } : d
      );
      return { ...user, personalDhikrs: updatedDhikrs };
    });
  };

  const deletePersonalDhikr = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      personalDhikrs: user.personalDhikrs.filter(d => d.id !== id)
    }));
  };

  const archiveDhikrChallenge = (id: string) => {
    updateActiveUser(user => {
      const challenge = user.activeChallenges.find(c => c.id === id);
      if (!challenge) return user;
      const historyEntry: DhikrHistoryEntry = {
        id: `${id}-${Date.now()}`,
        title: challenge.title,
        target: challenge.target,
        current: challenge.current,
        date: new Date().toISOString()
      };
      const resetChallenges = user.activeChallenges.map(c => 
        c.id === id ? { ...c, current: 0 } : c
      );
      return { 
        ...user, 
        activeChallenges: resetChallenges, 
        dhikrHistory: [historyEntry, ...user.dhikrHistory],
        activeDhikrId: null
      };
    });
  };

  const updateQuran = (progress: QuranProgress) => {
    updateActiveUser(user => ({ ...user, quranProgress: progress }));
  };

  const updateFasting = (date: string, log: FastingLog) => {
    updateActiveUser(user => ({
      ...user,
      fastingLogs: { ...user.fastingLogs, [date]: log }
    }));
  };

  const toggleHayd = (active: boolean) => {
    updateActiveUser(user => ({ ...user, isHaydNifas: active }));
  };

  const addHealthPeriod = (start: string, end: string | null) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: [...user.healthPeriods, { id: Date.now().toString(), start, end }]
    }));
  };

  const removeHealthPeriod = (id: string) => {
    updateActiveUser(user => ({
      ...user,
      healthPeriods: user.healthPeriods.filter(p => p.id !== id)
    }));
  };

  const isRTL = currentLanguage === 'ar';
  const langClass = currentLanguage === 'ml' ? 'ml-font' : currentLanguage === 'ta' ? 'ta-font' : '';

  const renderView = () => {
    if (currentView === 'welcome') return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;
    if (currentView === 'login') return <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />;
    if (!currentUserData) return <Welcome onEnter={() => setCurrentView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />;

    const compositeState = { ...currentUserData, todayTimings: state.todayTimings };

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'fard':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setCurrentView} t={t} />;
      case 'qadah':
        return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={setCurrentView} t={t} />;
      case 'women':
        return <WomensSpace state={compositeState} toggleHayd={toggleHayd} addHealthPeriod={addHealthPeriod} removeHealthPeriod={removeHealthPeriod} setCurrentView={setCurrentView} t={t} />;
      case 'dhikr':
        return (
          <DhikrCounter 
            state={compositeState} 
            updateProgress={updateDhikrProgress} 
            updatePersonalProgress={updatePersonalDhikrProgress}
            addPersonalDhikr={addPersonalDhikr}
            resetPersonalSession={resetPersonalSession}
            deletePersonalDhikr={deletePersonalDhikr}
            archiveChallenge={archiveDhikrChallenge} 
            setActiveDhikr={setActiveDhikr} 
            setCurrentView={setCurrentView} 
            t={t} 
          />
        );
      case 'quran':
        return <QuranTracker state={compositeState} onUpdate={updateQuran} setCurrentView={setCurrentView} t={t} />;
      case 'fasting':
        return <FastingTracker state={compositeState} updateFasting={updateFasting} setCurrentView={setCurrentView} t={t} />;
      case 'qibla':
        return <QiblaFinder setCurrentView={setCurrentView} t={t} />;
      case 'about':
        return <AboutHelp setCurrentView={setCurrentView} t={t} />;
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} />;
      default:
        return <Dashboard state={compositeState} setCurrentView={setCurrentView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
    }
  };

  return (
    <div className="app-viewport">
      <div className="islamic-pattern"></div>
      <div className={`h-full w-full relative overflow-hidden flex flex-col ${isRTL ? 'arabic-font' : ''} ${langClass}`} dir={isRTL ? 'rtl' : 'ltr'}>
        <main className="relative z-10 w-full h-full bg-white flex flex-col overflow-hidden">
          {renderView()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PersonalDhikr, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

const USERS_DB_KEY = 'ibadathi_v1_users_database';
const SESSION_KEY = 'ibadathi_v1_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let parsedUsers: Record<string, UserData> = {};
    try { parsedUsers = savedUsers ? JSON.parse(savedUsers) : {}; } catch (e) {}
    const currentUser = (activeSession && parsedUsers[activeSession]) ? activeSession : null;
    return { currentUser, users: parsedUsers, todayTimings: DEFAULT_TIMINGS };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;
  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    return (state.currentUser && state.users[state.currentUser]) ? state.users[state.currentUser].profile.preferredLanguage : 'en';
  });

  // Central View Management
  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [isAuth, setIsAuth] = useState<boolean>(!!state.currentUser);

  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
      setIsAuth(true);
    } else {
      localStorage.removeItem(SESSION_KEY);
      setIsAuth(false);
    }
  }, [state.users, state.currentUser]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { notificationsEnabled: false, locationEnabled: false, qadaReminders: [] }
      };
      setState(prev => ({ ...prev, currentUser: username, users: { ...prev.users, [username]: newUserData } }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }
    setCurrentLanguage(profile.preferredLanguage);
    setActiveTab('home');
    setSubView(null);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('home');
    setSubView(null);
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  // Event Handlers (Shared with subcomponents)
  const updatePrayerStatus = (date: string, prayer: any, status: PrayerStatus) => {
    updateActiveUser(user => {
      const logs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return { ...user, prayerLogs: { ...user.prayerLogs, [date]: { ...logs, [prayer]: status } } };
    });
  };

  const toggleSunnahStatus = (date: string, sunnah: string) => {
    updateActiveUser(user => {
      const cur = user.sunnahLogs[date] || [];
      const upd = cur.includes(sunnah) ? cur.filter(s => s !== sunnah) : [...cur, sunnah];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: upd } };
    });
  };

  if (!isAuth) {
    return (
      <div className="app-viewport animate-fade-in">
        <main className="h-full flex flex-col">
          {subView === 'login' ? (
            <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} />
          ) : (
            <Welcome onEnter={() => setSubView('login')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
          )}
        </main>
      </div>
    );
  }

  const compositeState = { ...currentUserData!, todayTimings: state.todayTimings };

  const renderContent = () => {
    // Sub-views take priority
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'qadah') return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeState} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home':
        return <Dashboard state={compositeState} setCurrentView={setSubView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'prayer':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setSubView} t={t} />;
      case 'challenges':
        return (
          <DhikrCounter 
            state={compositeState} 
            updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
            updatePersonalProgress={(id, d) => updateActiveUser(u => {
              const today = new Date().toISOString().split('T')[0];
              const upd = u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd);
              return { ...u, personalDhikrs: upd, dhikrCount: u.dhikrCount + d };
            })}
            addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
            resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
            deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
            archiveChallenge={(id) => updateActiveUser(u => {
              const c = u.activeChallenges.find(x => x.id === id);
              if (!c) return u;
              const hist = { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() };
              return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [hist, ...u.dhikrHistory], activeDhikrId: null };
            })}
            setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))}
            setCurrentView={setSubView} t={t} 
          />
        );
      case 'tracker':
        return (
          <div className="scroll-container p-6 space-y-4">
            <h2 className="text-2xl font-black text-emerald-900 mb-2">My Progress</h2>
            <div className="grid grid-cols-1 gap-4">
              <div onClick={() => setSubView('quran')} className="card-premium flex items-center gap-4 btn-ripple cursor-pointer">
                <div className="w-12 h-12 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-xl"><i className="fas fa-book-open"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900">{t('quran')}</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest">{compositeState.quranProgress.surah || 'Not started'}</p>
                </div>
                <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
              </div>
              <div onClick={() => setSubView('fasting')} className="card-premium flex items-center gap-4 btn-ripple cursor-pointer">
                <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl"><i className="fas fa-moon"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900">{t('fasting')}</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest">30 Days goal</p>
                </div>
                <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
              </div>
              <div onClick={() => setSubView('qadah')} className="card-premium flex items-center gap-4 btn-ripple cursor-pointer">
                <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center text-xl"><i className="fas fa-calendar-check"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900">{t('qadah')}</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest">Missed prayers log</p>
                </div>
                <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
              </div>
              {compositeState.profile.sex === 'female' && (
                <div onClick={() => setSubView('women')} className="card-premium flex items-center gap-4 btn-ripple cursor-pointer">
                  <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center text-xl"><i className="fas fa-leaf"></i></div>
                  <div className="flex-1">
                    <h3 className="font-black text-emerald-900">{t('womensSpace')}</h3>
                    <p className="text-[10px] text-slate-400 uppercase tracking-widest">Excused period tracking</p>
                  </div>
                  <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
                </div>
              )}
            </div>
          </div>
        );
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setSubView} t={t} onLogout={handleLogout} />;
      default: return null;
    }
  };

  return (
    <div className="app-viewport animate-fade-in" dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative">
        {renderContent()}
      </main>

      {!subView && (
        <nav className="bottom-nav">
          <button onClick={() => setActiveTab('home')} className={`nav-item ${activeTab === 'home' ? 'active' : ''}`}>
            <i className="fas fa-house"></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">Home</span>
          </button>
          <button onClick={() => setActiveTab('prayer')} className={`nav-item ${activeTab === 'prayer' ? 'active' : ''}`}>
            <i className="fas fa-kaaba"></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">Prayer</span>
          </button>
          <button onClick={() => setActiveTab('tracker')} className={`nav-item ${activeTab === 'tracker' ? 'active' : ''}`}>
            <i className="fas fa-chart-simple"></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">Tracker</span>
          </button>
          <button onClick={() => setActiveTab('challenges')} className={`nav-item ${activeTab === 'challenges' ? 'active' : ''}`}>
            <i className="fas fa-bolt"></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">Tasks</span>
          </button>
          <button onClick={() => setActiveTab('account')} className={`nav-item ${activeTab === 'account' ? 'active' : ''}`}>
            <i className="fas fa-user"></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">Account</span>
          </button>
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[today] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  return (
    <div className="h-full flex flex-col bg-slate-50 overflow-hidden">
      {/* Fixed Header */}
      <header className="bg-white p-6 pt-12 pb-4 flex justify-between items-center z-10">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-emerald-900 rounded-2xl flex items-center justify-center text-white shadow-lg">
             <i className="fas fa-user text-xl"></i>
          </div>
          <div>
            <h1 className="text-xl font-black text-emerald-900 leading-none mb-1">Assalamu Alaikum</h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{state.profile.name}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setCurrentView('qibla')} className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-600 active:scale-95 transition-all"><i className="fas fa-compass"></i></button>
          <button onClick={() => setCurrentView('about')} className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-600 active:scale-95 transition-all"><i className="fas fa-circle-info"></i></button>
        </div>
      </header>

      {/* Scrollable Main Area */}
      <div className="scroll-container px-6 space-y-6 pt-4">
        {/* Next Prayer Card - Uber Inspired Hero */}
        <div className="bg-emerald-900 p-8 rounded-[32px] text-white relative overflow-hidden shadow-2xl shadow-emerald-900/20">
          <div className="absolute top-0 right-0 w-40 h-40 bg-emerald-400/10 rounded-full -mr-10 -mt-10 blur-3xl"></div>
          <div className="relative z-10">
            <span className="text-[10px] font-black text-emerald-300 uppercase tracking-widest block mb-1">UP NEXT</span>
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-4xl font-black capitalize tracking-tighter">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <p className="text-emerald-100/60 text-sm mt-1">{prayerTimingData?.next.time}</p>
              </div>
              <div className="text-right">
                <p className="text-2xl font-black tabular-nums">{prayerTimingData?.timeLeft}</p>
                <p className="text-[8px] font-black text-emerald-400 uppercase">REMAINING</p>
              </div>
            </div>
            <div className="w-full bg-emerald-800/50 h-1.5 rounded-full mt-6 overflow-hidden">
               <div className="bg-emerald-400 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>
        </div>

        {/* Quick Summary Grid */}
        <div className="grid grid-cols-2 gap-4">
          <div className="card-premium">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-2">DHIKR STREAK</span>
             <div className="flex items-baseline gap-2">
               <span className="text-2xl font-black text-emerald-900">{state.dhikrCount.toLocaleString()}</span>
               <i className="fas fa-sparkles text-amber-500 text-xs"></i>
             </div>
          </div>
          <div className="card-premium">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-2">QURAN LOG</span>
             <p className="text-sm font-black text-emerald-900 truncate">{state.quranProgress.surah || '---'}</p>
          </div>
        </div>

        {/* Daily Hadith Card */}
        <div className="card-premium border-l-4 border-emerald-600 relative group active:scale-[0.99] transition-all">
          <div className="flex items-center gap-2 mb-3">
            <span className="px-2 py-1 bg-emerald-50 text-emerald-700 text-[8px] font-black rounded-lg uppercase">HADITH OF THE DAY</span>
          </div>
          <p className="text-emerald-900 arabic-font text-xl leading-relaxed text-right mb-4 font-bold" dir="rtl">{dailyHadith.arabic}</p>
          <p className="text-slate-500 italic text-[11px] leading-relaxed border-l-2 border-emerald-100 pl-4">"{dailyHadith[userLang]}"</p>
        </div>

        {/* Today's Activity Section */}
        <div>
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-4">TODAY'S PROGRESS</h3>
          <div className="space-y-3">
             {PRAYERS.map(p => {
               const status = todayLogs[p];
               return (
                 <div key={p} onClick={() => updatePrayerStatus(today, p, status === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} className="card-premium flex items-center justify-between py-4 btn-ripple cursor-pointer">
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${status === PrayerStatus.COMPLETED ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-300'}`}>
                        <i className={`fas ${status === PrayerStatus.COMPLETED ? 'fa-check' : 'fa-circle-notch'} text-sm`}></i>
                      </div>
                      <div>
                        <p className="font-black text-emerald-900 capitalize text-sm">{t(p)}</p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase">{state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}</p>
                      </div>
                    </div>
                    {status === PrayerStatus.COMPLETED && <span className="text-[8px] font-black text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full uppercase">COMPLETED</span>}
                 </div>
               );
             })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 overflow-hidden">
      <header className="bg-white p-6 pt-12 pb-4 flex justify-between items-center z-10 shrink-0">
        <div>
          <h1 className="text-2xl font-black text-emerald-900 mb-1">{t('prayer')}</h1>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Daily Fulfillment</p>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl">
          <button onClick={() => setActiveTab('fard')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === 'fard' ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-400'}`}>{t('fard')}</button>
          <button onClick={() => setActiveTab('sunnah')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === 'sunnah' ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-400'}`}>{t('sunnah')}</button>
        </div>
      </header>

      <div className="scroll-container px-6 pt-4 space-y-4">
        {isExcused && (
          <div className="bg-rose-50 p-4 rounded-2xl border border-rose-100 flex items-center gap-3">
            <i className="fas fa-droplet text-rose-500"></i>
            <p className="text-rose-900 text-[10px] font-black uppercase tracking-widest">{t('excused')} - Rest well</p>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p) => {
            const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
            const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;

            return (
              <div 
                key={p} 
                onClick={() => !isExcused && handleToggle(p, activeTab)} 
                className={`card-premium flex items-center justify-between py-5 btn-ripple cursor-pointer border-2 ${isDone ? 'border-emerald-600' : 'border-transparent'} ${isExcused ? 'opacity-40 grayscale' : ''}`}
              >
                <div className="flex items-center gap-5">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl transition-all ${isDone ? 'bg-emerald-600 text-white shadow-xl' : 'bg-slate-100 text-slate-300'}`}>
                    <i className={`fas ${isDone ? 'fa-check' : 'fa-kaaba'}`}></i>
                  </div>
                  <div>
                    <h3 className="font-black text-emerald-900 capitalize">{t(p)}</h3>
                    {time && <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{time}</p>}
                  </div>
                </div>
                {isDone && (
                  <div className="flex flex-col items-end">
                    <span className="text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full uppercase">Mabrook</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="bg-emerald-50 p-6 rounded-[32px] text-center border border-emerald-100/50 mt-8">
           <p className="arabic-font text-emerald-900 text-2xl font-bold mb-2">الصلاة خير من النوم</p>
           <p className="text-emerald-700/60 text-[9px] font-black uppercase tracking-widest">Prayer is better than sleep</p>
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0, missedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
        if (status === PrayerStatus.MISSED) missedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 1;
    let levelKey = 'levelBeginner', colorClass = 'text-slate-500', icon = 'fa-seedling';
    if (ratio >= 0.9 && totalFard > 30) { levelKey = 'levelElite'; colorClass = 'text-[#c5a059]'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { levelKey = 'levelAdvanced'; colorClass = 'text-emerald-600'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { levelKey = 'levelConsistent'; colorClass = 'text-teal-600'; icon = 'fa-leaf'; }
    return { completedFard, missedFard, levelKey, colorClass, ratio, icon };
  }, [state]);

  return (
    <div className="h-full flex flex-col bg-slate-50 overflow-hidden">
      <header className="bg-white p-6 pt-12 pb-6 flex items-center gap-4 z-10 shrink-0">
        <div className="w-16 h-16 bg-emerald-900 rounded-3xl flex items-center justify-center text-white shadow-xl">
           <i className="fas fa-user-circle text-3xl"></i>
        </div>
        <div>
          <h1 className="text-2xl font-black text-emerald-900 leading-none mb-1">{state.profile.name}</h1>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">@{state.profile.username}</p>
        </div>
      </header>

      <div className="scroll-container px-6 pt-2 space-y-6">
        {/* Achievement Card */}
        <div className="bg-white p-8 rounded-[32px] shadow-premium flex flex-col items-center text-center border border-slate-50 relative overflow-hidden">
           <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl mb-3 bg-emerald-50 ${stats.colorClass} shadow-inner`}>
             <i className={`fas ${stats.icon}`}></i>
           </div>
           <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('consistency')}</span>
           <h3 className={`text-3xl font-black ${stats.colorClass} tracking-tighter mb-4`}>{t(stats.levelKey)}</h3>
           <div className="w-full bg-slate-50 h-2 rounded-full overflow-hidden">
              <div className="bg-emerald-600 h-full rounded-full transition-all" style={{ width: `${stats.ratio * 100}%` }}></div>
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 gap-4">
           <div className="card-premium">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-2">PRAYERS DONE</span>
              <p className="text-2xl font-black text-emerald-900">{stats.completedFard}</p>
           </div>
           <div className="card-premium">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-2">DHIKR TOTAL</span>
              <p className="text-2xl font-black text-emerald-900">{state.dhikrCount.toLocaleString()}</p>
           </div>
        </div>

        {/* Settings/Account Actions */}
        <div className="space-y-3">
          <button className="card-premium w-full flex items-center justify-between btn-ripple">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-slate-100 text-slate-500 rounded-xl flex items-center justify-center"><i className="fas fa-id-card"></i></div>
              <span className="font-black text-emerald-900 text-sm">Profile Details</span>
            </div>
            <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
          </button>
          <button onClick={() => setCurrentView('about')} className="card-premium w-full flex items-center justify-between btn-ripple">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-slate-100 text-slate-500 rounded-xl flex items-center justify-center"><i className="fas fa-circle-info"></i></div>
              <span className="font-black text-emerald-900 text-sm">Help & About</span>
            </div>
            <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
          </button>
          <button onClick={onLogout} className="card-premium w-full flex items-center justify-between bg-rose-50 border-rose-100 btn-ripple">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-rose-100 text-rose-600 rounded-xl flex items-center justify-center"><i className="fas fa-power-off"></i></div>
              <span className="font-black text-rose-900 text-sm">{t('logout')}</span>
            </div>
          </button>
        </div>

        <div className="pt-8 text-center text-slate-300 text-[10px] font-black uppercase tracking-widest pb-10">
           Ibadathi v5.5 • 1446 AH
        </div>
      </div>
    </div>
  );
};

