                <p className="text-4xl font-black tabular-nums tracking-tight">{prayerTimingData?.timeLeft}</p>
                <p className="text-[9px] font-black text-emerald-400 uppercase tracking-widest mt-1">REMAINING</p>
              </div>
            </div>
            <div className="w-full bg-emerald-800/60 h-2.5 rounded-full mt-8 overflow-hidden p-1 shadow-inner">
               <div className="bg-emerald-400 h-full rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(52,211,153,0.4)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>

          {/* Feature Grid - Fluid Responsive columns */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="card-premium flex items-center gap-5">
               <div className="w-14 h-14 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-2xl"><i className="fas fa-fire-flame-curved"></i></div>
               <div>
                 <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">STREAK</span>
                 <p className="text-2xl font-black text-emerald-900">{state.dhikrCount.toLocaleString()}</p>
               </div>
            </div>
            <div className="card-premium flex items-center gap-5">
               <div className="w-14 h-14 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-2xl"><i className="fas fa-book-quran"></i></div>
               <div className="overflow-hidden">
                 <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">READING</span>
                 <p className="text-lg font-black text-emerald-900 truncate">{state.quranProgress.surah || '---'}</p>
               </div>
            </div>
          </div>

          {/* Today's Tasks - Adaptive columns */}
          <div>
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest ml-1 mb-6">TODAY'S OBLIGATIONS</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
               {PRAYERS.map(p => {
                 const status = todayLogs[p];
                 const isDone = status === PrayerStatus.COMPLETED;
                 return (
                   <div 
                     key={p} 
                     onClick={() => updatePrayerStatus(today, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                     className="card-premium flex items-center justify-between py-6 btn-ripple cursor-pointer bg-white"
                   >
                      <div className="flex items-center gap-5">
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-md ${isDone ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-300'}`}>
                          <i className={`fas ${isDone ? 'fa-check' : 'fa-circle-notch'} text-lg`}></i>
                        </div>
                        <div>
                          <p className="font-black text-emerald-900 capitalize text-base">{t(p)}</p>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                            {state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}
                          </p>
                        </div>
                      </div>
                      {isDone && <i className="fas fa-sparkles text-amber-400 text-sm animate-pulse"></i>}
                   </div>
                 );
               })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  const usernameStatus = useMemo(() => {
    if (mode === 'login' || usernameNormalized.length < 3) return 'idle';
    return users[usernameNormalized] ? 'taken' : 'available';
  }, [usernameNormalized, mode, users]);

  const suggestions = useMemo(() => {
    if (usernameStatus !== 'taken') return [];
    const base = usernameNormalized;
    return [
      `${base}${Math.floor(Math.random() * 99) + 1}`,
      `${base}_ibadathi`,
      `${base}_seeker`
    ].filter(s => !users[s.toLowerCase()]);
  }, [usernameStatus, usernameNormalized, users]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password) return "Password is required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (usernameStatus === 'taken') return t('usernameTaken');
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setIsAuthenticating(true);
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "User not found." : "Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const inputClasses = "w-full px-5 py-4 bg-white border border-slate-100 rounded-[24px] focus:ring-4 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-semibold text-emerald-900 placeholder:text-slate-300 text-sm";
  const labelClasses = "block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 mb-2";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] w-full overflow-hidden">
      {/* Scrollable Form Container */}
      <div className="flex-1 overflow-y-auto px-6 pt-12 pb-8 flex flex-col items-center">
        {/* Brand Header */}
        <div className="flex flex-col items-center mb-8 shrink-0">
          <div className="w-20 h-20 bg-emerald-900 rounded-[32px] flex items-center justify-center mb-4 shadow-2xl border-4 border-white rotate-3 group active:rotate-0 transition-transform">
            <i className="fas fa-mosque text-3xl text-emerald-100"></i>
          </div>
          <h1 className="text-4xl font-black text-emerald-900 mb-1 tracking-tighter">Ibadathi</h1>
          <p className="text-[11px] font-black text-emerald-800/40 uppercase tracking-[0.3em]">Sacred Companion</p>
        </div>

        {/* Mode Switcher */}
        <div className="flex bg-emerald-50/50 p-1.5 rounded-[24px] mb-8 w-full max-w-[280px] shrink-0 border border-emerald-100/50">
          <button 
            type="button"
            onClick={() => { setMode('login'); setError(null); }}
            className={`flex-1 py-3 rounded-[18px] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40 hover:text-emerald-900/60'}`}
          >
            {t('login')}
          </button>
          <button 
            type="button"
            onClick={() => { setMode('register'); setError(null); }}
            className={`flex-1 py-3 rounded-[18px] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg' : 'text-emerald-900/40 hover:text-emerald-900/60'}`}
          >
            {t('register')}
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="w-full max-w-[360px] space-y-6 flex flex-col">
          {error && (
            <div className="bg-rose-50 text-rose-600 p-4 rounded-[20px] text-[11px] font-bold text-center border border-rose-100 animate-shake shrink-0">
              <i className="fas fa-exclamation-circle mr-2"></i> {error}
            </div>
          )}

          {/* Username Field - ALWAYS VISIBLE */}
          <div className="space-y-2">
            <label className={labelClasses}>{t('username')}</label>
            <div className="relative">
              <input 
                type="text" 
                className={`${inputClasses} ${usernameStatus === 'taken' ? 'border-rose-300' : usernameStatus === 'available' ? 'border-emerald-400' : ''}`}
                placeholder="muslim_seeker"
                value={formData.username}
                onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})}
                required
              />
              <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-2">
                {usernameStatus === 'available' && <i className="fas fa-check-circle text-emerald-500 animate-fade-in"></i>}
                {usernameStatus === 'taken' && <i className="fas fa-times-circle text-rose-500 animate-fade-in"></i>}
              </div>
            </div>
            {usernameStatus === 'taken' && mode === 'register' && (
              <div className="animate-fade-up bg-rose-50/50 p-4 rounded-[20px] border border-rose-100/50 mt-2">
                <p className="text-[9px] font-black text-rose-800/60 uppercase tracking-widest mb-3">{t('suggestions')}</p>
                <div className="flex flex-wrap gap-2">
                  {suggestions.map(s => (
                    <button 
                      key={s} 
                      type="button"
                      onClick={() => setFormData({...formData, username: s})}
                      className="bg-white px-3 py-2 rounded-xl text-[10px] font-black text-rose-900 border border-rose-100 active:scale-95 transition-all shadow-sm"
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Registration Extra Fields */}
          {mode === 'register' && (
            <div className="space-y-6 animate-fade-in">
              <div className="space-y-2">
                <label className={labelClasses}>{t('name')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Abdullah Al-Fulan"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className={labelClasses}>{t('age')}</label>
                  <input 
                    type="number"
                    className={inputClasses}
                    placeholder="25"
                    value={formData.age}
                    onChange={e => setFormData({...formData, age: e.target.value})}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <label className={labelClasses}>{t('sex')}</label>
                  <select 
                    className={`${inputClasses} appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22none%22%20viewBox%3D%220%200%2024%2024%22%20stroke%3D%22%23cbd5e1%22%3E%3Cpath%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%222%22%20d%3D%22M19%209l-7%207-7-7%22%20%2F%3E%3C%2Fsvg%3E')] bg-[length:1em_1em] bg-[right_1.25rem_center] bg-no-repeat`}
                    value={formData.sex}
                    onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                  >
                    <option value="male">{t('male')}</option>
                    <option value="female">{t('female')}</option>
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className={labelClasses}>{t('place')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Makkah, KSA"
                  value={formData.place}
                  onChange={e => setFormData({...formData, place: e.target.value})}
                  required
                />
              </div>
            </div>
          )}

          {/* Password Field */}
          <div className="space-y-2">
            <label className={labelClasses}>{t('password')}</label>
            <input 
              type="password"
              className={inputClasses}
              placeholder="••••••••"
              value={formData.password}
              onChange={e => setFormData({...formData, password: e.target.value})}
              required
            />
          </div>

          {/* Action Button */}
          <button 
            type="submit"
            disabled={isAuthenticating || (mode === 'register' && usernameStatus !== 'available')}
            className="w-full bg-emerald-900 text-white font-black py-5 rounded-[28px] transition-all active:scale-[0.98] mt-4 uppercase tracking-[0.2em] text-xs flex items-center justify-center gap-3 disabled:opacity-30 shadow-2xl shadow-emerald-900/20"
          >
            {isAuthenticating ? (
              <i className="fas fa-spinner fa-spin"></i>
            ) : (
              <>
                {mode === 'login' ? t('login') : t('register')}
                <i className="fas fa-arrow-right text-[10px] opacity-40"></i>
              </>
            )}
          </button>
        </form>

        <div className="mt-12 text-slate-200 text-[10px] font-black uppercase tracking-[0.3em]">
           Ibadathi © 1446
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  // Calendar State
  const [calDate, setCalDate] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[todayStr] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  // Calendar Logic
  const calendarDays = useMemo(() => {
    const year = calDate.getFullYear();
    const month = calDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();

    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push(`${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`);
    }
    return days;
  }, [calDate]);

  return (
    <div className="h-full flex flex-col bg-slate-50 overflow-hidden w-full">
      {/* Fluid Fixed Header */}
      <header className="bg-white p-6 pt-12 pb-4 shadow-sm z-10 w-full flex justify-center">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-emerald-900 rounded-2xl flex items-center justify-center text-white shadow-lg">
               <i className="fas fa-user text-2xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-black text-emerald-900 leading-none mb-1">Assalamu Alaikum</h1>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{state.profile.name}</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button onClick={() => setCurrentView('qibla')} className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-600 active:scale-90 transition-all shadow-sm"><i className="fas fa-compass text-lg"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-600 active:scale-90 transition-all shadow-sm"><i className="fas fa-circle-info text-lg"></i></button>
          </div>
        </div>
      </header>

      {/* Responsive Scrollable Content */}
      <div className="scroll-container px-6 pt-6 space-y-8 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-8">

          {/* Daily Hadith */}
          <div className="card-premium border-l-8 border-emerald-600 relative group active:scale-[0.99] transition-all bg-white">
            <div className="flex items-center gap-2 mb-4">
              <span className="px-3 py-1.5 bg-emerald-50 text-emerald-700 text-[10px] font-black rounded-xl uppercase tracking-widest">WISDOM FOR TODAY</span>
            </div>
            <p className="text-emerald-900 arabic-font text-3xl leading-relaxed text-right mb-6 font-bold" dir="rtl">{dailyHadith.arabic}</p>
            <p className="text-slate-500 italic text-sm leading-relaxed border-l-4 border-emerald-100 pl-6 font-medium">"{dailyHadith[userLang]}"</p>
          </div>

          {/* Next Prayer Hero */}
          <div className="bg-emerald-900 p-10 rounded-[40px] text-white relative overflow-hidden shadow-2xl shadow-emerald-900/30">
            <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-400/10 rounded-full -mr-20 -mt-20 blur-3xl"></div>
            <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div>
                <span className="text-[11px] font-black text-emerald-300 uppercase tracking-widest block mb-2">UP NEXT</span>
                <h2 className="text-5xl font-black capitalize tracking-tighter">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <p className="text-emerald-100/70 text-lg mt-2 font-medium">{prayerTimingData?.next.time}</p>
              </div>
              <div className="text-left md:text-right">
                <p className="text-4xl font-black tabular-nums tracking-tight">{prayerTimingData?.timeLeft}</p>
                <p className="text-[9px] font-black text-emerald-400 uppercase tracking-widest mt-1">REMAINING</p>
              </div>
            </div>
            <div className="w-full bg-emerald-800/60 h-2.5 rounded-full mt-8 overflow-hidden p-1 shadow-inner">
               <div className="bg-emerald-400 h-full rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(52,211,153,0.4)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>

          {/* Prayer Calendar Section */}
          <div className="space-y-4">
            <div className="flex justify-between items-end px-1">
              <div>
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">PRAYER CALENDAR</h3>
                <p className="text-xl font-black text-emerald-900 uppercase">
                  {calDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
                </p>
              </div>
              <div className="flex gap-2">
                <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() - 1, 1))} className="w-10 h-10 bg-white rounded-xl border border-slate-100 flex items-center justify-center text-slate-400 hover:text-emerald-600 transition-colors"><i className="fas fa-chevron-left text-xs"></i></button>
                <button onClick={() => setCalDate(new Date())} className="px-4 h-10 bg-white rounded-xl border border-slate-100 text-[10px] font-black uppercase tracking-widest text-emerald-900">Today</button>
                <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() + 1, 1))} className="w-10 h-10 bg-white rounded-xl border border-slate-100 flex items-center justify-center text-slate-400 hover:text-emerald-600 transition-colors"><i className="fas fa-chevron-right text-xs"></i></button>
              </div>
            </div>

            <div className="card-premium overflow-hidden !p-4 bg-white">
              <div className="grid grid-cols-7 gap-1 mb-2">
                {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
                  <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-2">{d}</div>
                ))}
              </div>
              <div className="grid grid-cols-7 gap-1">
                {calendarDays.map((dateStr, idx) => {
                  if (!dateStr) return <div key={`empty-${idx}`} className="h-16 md:h-24"></div>;

                  const isToday = dateStr === todayStr;
                  const inHayd = isDateInHayd(dateStr);
                  const logs = state.prayerLogs[dateStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };
                  const dayNum = dateStr.split('-')[2];

                  return (
                    <div 
                      key={dateStr}
                      className={`h-16 md:h-24 rounded-2xl border flex flex-col items-center justify-between p-1.5 transition-all group ${isToday ? 'border-emerald-600 bg-emerald-50/50' : inHayd ? 'border-pink-100 bg-pink-50/30' : 'border-slate-50 hover:bg-slate-50/50'}`}
                    >
                      <span className={`text-[10px] font-black ${isToday ? 'text-emerald-700' : inHayd ? 'text-pink-600' : 'text-slate-400'}`}>
                        {parseInt(dayNum)}
