            <div className="flex overflow-x-auto gap-4 pb-4 px-1 -mx-1 no-scrollbar snap-x lg:grid lg:grid-cols-4 lg:overflow-visible">

              {/* Prayer Obligations (Conditionally Hidden for Hayd) */}
              {!inHaydToday && PRAYERS.map(p => {
                const status = todayLogs[p];
                const isDone = status === PrayerStatus.COMPLETED;
                const isUpcoming = prayerTimingData?.next.name === p;
                return (
                  <div 
                    key={p} 
                    onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                    className={`min-w-[160px] snap-center p-5 rounded-[28px] border-2 transition-all cursor-pointer flex flex-col gap-4 bg-white dark:bg-slate-800 shadow-sm hover:shadow-md ${isDone ? 'border-emerald-100 dark:border-emerald-900/50 bg-emerald-50/20 dark:bg-emerald-900/10' : isUpcoming ? 'border-amber-400 dark:border-amber-500 shadow-amber-900/5' : 'border-slate-100 dark:border-slate-700'} active:scale-95`}
                  >
                    <div className="flex items-center justify-between">
                      <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${isDone ? 'bg-emerald-600 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-300 dark:text-slate-500'}`}>
