                      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                        {state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}
                      </p>
                    </div>
                    <div className={`h-1 w-full rounded-full ${isDone ? 'bg-emerald-600' : 'bg-rose-400'}`}></div>
                  </div>
                );
              })}

              {/* Fasting Obligation */}
              <div 
                onClick={() => setCurrentView('fasting')}
                className={`min-w-[160px] snap-center p-5 rounded-[28px] border-2 transition-all cursor-pointer flex flex-col gap-4 bg-white dark:bg-slate-800 shadow-sm ${fastingToday.status === 'completed' ? 'border-emerald-100 dark:border-emerald-900/50 bg-emerald-50/20 dark:bg-emerald-900/10' : fastingToday.status === 'excused' ? 'border-pink-100 dark:border-pink-900/50 bg-pink-50/20 dark:bg-pink-900/10' : 'border-slate-100 dark:border-slate-700'} active:scale-95`}
              >
