              <div className="grid grid-cols-7 gap-1 mb-2">
                {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
                  <div key={d} className="text-center text-[10px] font-black text-slate-300 dark:text-slate-600 uppercase py-2">{d}</div>
                ))}
              </div>
              <div className="grid grid-cols-7 gap-1">
                {calendarDays.map((dateStr, idx) => {
                  if (!dateStr) return <div key={`empty-${idx}`} className="h-16 md:h-24"></div>;

                  const isToday = dateStr === todayStr;
                  const inHayd = isDateInHayd(dateStr);
                  const logs = state.prayerLogs[dateStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };
                  const dayNum = dateStr.split('-')[2];

                  return (
                    <div 
                      key={dateStr}
                      className={`h-16 md:h-24 rounded-2xl border flex flex-col items-center justify-between p-1.5 transition-all group ${isToday ? 'border-emerald-600 bg-emerald-50/50 dark:bg-emerald-900/20' : inHayd ? 'border-pink-100 dark:border-pink-900/30 bg-pink-50/30 dark:bg-pink-900/10' : 'border-slate-50 dark:border-slate-700 hover:bg-slate-50/50 dark:hover:bg-slate-700/50'}`}
                    >
                      <span className={`text-[10px] font-black ${isToday ? 'text-emerald-700 dark:text-emerald-400' : inHayd ? 'text-pink-600 dark:text-pink-400' : 'text-slate-400 dark:text-slate-500'}`}>
                        {parseInt(dayNum)}
                      </span>

                      {inHayd ? (
                        <div className="flex-1 flex items-center justify-center">
                          <i className="fas fa-leaf text-[10px] text-pink-300 dark:text-pink-700"></i>
                        </div>
                      ) : (
                        <div className="flex flex-wrap gap-0.5 justify-center mt-1">
                          {PRAYERS.map(p => {
                            const status = logs[p as keyof typeof logs];
                            const color = status === 'completed' ? 'bg-emerald-500' : status === 'missed' ? 'bg-rose-400' : 'bg-slate-200 dark:bg-slate-700';
                            return (
                              <div key={p} title={p} className={`w-1.5 h-1.5 md:w-2 md:h-2 rounded-full ${color}`}></div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

