import React, { useState, useMemo } from 'react';
import { UserData, DhikrChallenge, PersonalDhikr, PrayerTimings } from '../types';

interface DhikrCounterProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateProgress: (id: string, delta: number) => void;
  updatePersonalProgress: (id: string, delta: number) => void;
  addPersonalDhikr: (name: string) => void;
  resetPersonalSession: (id: string) => void;
  deletePersonalDhikr: (id: string) => void;
  archiveChallenge: (id: string) => void;
  setActiveDhikr: (id: string | null) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const DhikrCounter: React.FC<DhikrCounterProps> = ({ 
  state, updateProgress, updatePersonalProgress, addPersonalDhikr, resetPersonalSession, deletePersonalDhikr, archiveChallenge, setActiveDhikr, setCurrentView, t 
}) => {
  const [activeTab, setActiveTab] = useState<'challenges' | 'personal'>('challenges');
  const [tapAnimation, setTapAnimation] = useState(false);
  const [isAddingDhikr, setIsAddingDhikr] = useState(false);
  const [newDhikrName, setNewDhikrName] = useState('');
  const [activePersonalId, setActivePersonalId] = useState<string | null>(null);

  const activeChallenge = useMemo(() => state.activeChallenges.find(c => c.id === state.activeDhikrId), [state.activeChallenges, state.activeDhikrId]);
  const activePersonal = useMemo(() => state.personalDhikrs.find(d => d.id === activePersonalId), [state.personalDhikrs, activePersonalId]);

  const handleIncrementChallenge = () => {
    if (!state.activeDhikrId || !activeChallenge) return;
    if ('vibrate' in navigator) navigator.vibrate(50);
    setTapAnimation(true); setTimeout(() => setTapAnimation(false), 150);
    updateProgress(state.activeDhikrId, 1);
  };

  const handleIncrementPersonal = () => {
    if (!activePersonalId || !activePersonal) return;
    if ('vibrate' in navigator) navigator.vibrate(60);
    setTapAnimation(true); setTimeout(() => setTapAnimation(false), 150);
    updatePersonalProgress(activePersonalId, 1);
  };

  // Modern Counter View
  if (activeChallenge || activePersonal) {
    const title = activeChallenge ? t(activeChallenge.title) : activePersonal?.name;
    const current = activeChallenge ? activeChallenge.current : activePersonal?.sessionCount;
    const target = activeChallenge ? activeChallenge.target : 0;
    const arabic = activeChallenge ? activeChallenge.arabic : '';
    const increment = activeChallenge ? handleIncrementChallenge : handleIncrementPersonal;

    // Choose a color theme based on the dhikr
    const themeClass = activeChallenge?.id === 'salawat' ? 'from-emerald-700 to-emerald-950' : 
                      activeChallenge?.id === 'astaghfirullah' ? 'from-slate-700 to-slate-900' :
                      activeChallenge?.id === 'allahuakbar' ? 'from-amber-600 to-amber-900' :
                      'from-emerald-800 to-teal-950';

    return (
      <div className={`h-full flex flex-col bg-gradient-to-b ${themeClass} text-white animate-fade-in`}>
        <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20">
           <div className="absolute top-1/4 -left-20 w-80 h-80 bg-white/20 rounded-full blur-3xl"></div>
           <div className="absolute bottom-1/4 -right-20 w-80 h-80 bg-white/10 rounded-full blur-3xl"></div>
        </div>

        <header className="p-6 pt-12 pb-4 flex items-center justify-between relative z-10">
          <button onClick={() => { setActiveDhikr(null); setActivePersonalId(null); }} className="w-12 h-12 bg-white/10 backdrop-blur-xl rounded-2xl flex items-center justify-center border border-white/20 active:scale-90 transition-all"><i className="fas fa-arrow-left"></i></button>
          <div className="flex flex-col items-end">
             <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em]">Current Session</span>
             <p className="text-xl font-black tabular-nums">{current}</p>
          </div>
        </header>

        <div className="flex-1 flex flex-col items-center justify-around py-12 relative z-10">
          <div className="text-center px-8 space-y-6">
            <h1 className="text-2xl font-black tracking-tight mb-2 opacity-60 uppercase tracking-[0.3em] text-sm">{title}</h1>
            <p className="arabic-font text-6xl font-black mb-6 drop-shadow-2xl leading-relaxed" dir="rtl">{arabic}</p>
          </div>

          <button 
            onClick={increment} 
            className={`w-72 h-72 rounded-[64px] bg-white text-emerald-950 flex flex-col items-center justify-center shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] transition-all duration-200 ${tapAnimation ? 'scale-[0.88] bg-emerald-50' : 'active:scale-95'}`}
          >
             <span className="text-9xl font-black tabular-nums tracking-tighter transition-all">{current}</span>
             <div className="h-1 w-20 bg-emerald-100 rounded-full mt-2"></div>
          </button>

          <div className="w-full px-10 text-center space-y-8">
             {activeChallenge && activeChallenge.current >= activeChallenge.target && (
               <button 
                 onClick={() => archiveChallenge(activeChallenge.id)} 
                 className="w-full py-6 bg-gradient-to-r from-emerald-400 to-teal-500 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.3em] shadow-2xl animate-bounce border-b-4 border-emerald-600"
               >
                 Mabrook! Archive Task
               </button>
             )}
             <div className="space-y-2">
               <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.4em] flex items-center justify-center gap-2">
                 <i className="fas fa-fingerprint text-xs"></i>
                 TAP TO RECITE
               </p>
               {activeChallenge && (
                 <p className="text-white/20 text-[9px] font-bold uppercase">Target: {activeChallenge.target}</p>
               )}
             </div>
          </div>
        </div>
      </div>
    );
  }

  // Selection View
  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white dark:bg-slate-900 p-6 pt-12 pb-6 flex justify-between items-center z-10 shadow-sm border-b dark:border-slate-800">
        <div>
          <h1 className="text-3xl font-black text-emerald-950 dark:text-emerald-100 mb-1 tracking-tighter">Tasks</h1>
          <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Spiritual Momentum</p>
        </div>
        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-2xl">
          <button onClick={() => setActiveTab('challenges')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'challenges' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-md' : 'text-slate-400'}`}>DAILY</button>
          <button onClick={() => setActiveTab('personal')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-md' : 'text-slate-400'}`}>MY OWN</button>
        </div>
      </header>

      <div className="scroll-container px-6 pt-8 space-y-6">
        {activeTab === 'challenges' ? (
          state.activeChallenges.map((c, idx) => {
            const perc = Math.min(100, (c.current / c.target) * 100);
            const isDone = perc === 100;
            // Diverse colorful accents
            const accentColors = ['emerald', 'amber', 'sky', 'violet', 'rose', 'teal'];
            const accent = accentColors[idx % accentColors.length];

            return (
              <div 
                key={c.id} 
                onClick={() => setActiveDhikr(c.id)} 
                className={`card-premium dark:bg-slate-800 group cursor-pointer relative overflow-hidden transition-all hover:translate-y-[-4px] active:scale-[0.98] border-2 ${isDone ? `border-${accent}-500 bg-${accent}-50/10` : 'border-transparent'}`}
              >
                <div className="flex justify-between items-start relative z-10">
                  <div className="flex-1 overflow-hidden space-y-2">
                    <h3 className="font-black text-emerald-950 dark:text-emerald-50 uppercase text-base tracking-tight">{t(c.title)}</h3>
                    <p className="arabic-font text-2xl text-emerald-800/60 dark:text-emerald-400/60 truncate" dir="rtl">{c.arabic}</p>
                  </div>
                  <div className={`w-14 h-14 rounded-[22px] flex items-center justify-center shadow-lg transition-all ${isDone ? `bg-gradient-to-br from-${accent}-500 to-${accent}-700 text-white` : 'bg-slate-50 dark:bg-slate-700 text-slate-300'}`}>
                    <i className={`fas ${isDone ? 'fa-check-double' : 'fa-play'} text-lg`}></i>
                  </div>
                </div>
                <div className="mt-6 space-y-2">
                  <div className="flex justify-between items-end">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{c.current} / {c.target}</span>
                    <span className={`text-[10px] font-black text-${accent}-600 dark:text-${accent}-400 uppercase tracking-widest`}>{Math.round(perc)}%</span>
                  </div>
                  <div className="w-full bg-slate-100 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                     <div className={`bg-${accent}-500 h-full rounded-full transition-all duration-700 shadow-[0_0_10px_rgba(0,0,0,0.1)]`} style={{ width: `${perc}%` }}></div>
                  </div>
                </div>
              </div>
            );
          })
        ) : (
          <div className="space-y-6">
            <button onClick={() => setIsAddingDhikr(true)} className="w-full p-10 rounded-[48px] border-4 border-dashed border-emerald-100 dark:border-slate-800 text-emerald-700 dark:text-emerald-500 flex flex-col items-center gap-3 transition-all hover:bg-emerald-50 dark:hover:bg-slate-800/50 active:scale-95 group">
              <div className="w-16 h-16 bg-emerald-50 dark:bg-slate-700 rounded-3xl flex items-center justify-center transition-transform group-hover:scale-110">
                <i className="fas fa-plus text-2xl"></i>
              </div>
              <span className="font-black text-[12px] uppercase tracking-[0.3em]">Start New Remembrance</span>
            </button>
            {state.personalDhikrs.map(d => (
              <div key={d.id} onClick={() => setActivePersonalId(d.id)} className="card-premium dark:bg-slate-800 flex items-center justify-between group cursor-pointer hover:shadow-2xl transition-all active:scale-[0.98]">
                <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-gradient-to-br from-sky-400 to-sky-600 text-white rounded-[22px] flex items-center justify-center text-xl shadow-lg shadow-sky-400/20 group-hover:rotate-6 transition-transform">
                    <i className="fas fa-moon"></i>
                  </div>
                  <div>
                    <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-lg tracking-tight uppercase">{d.name}</h3>
                    <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest">Lifetime: {d.totalCount}</p>
                  </div>
                </div>
                <div className="w-10 h-10 bg-slate-50 dark:bg-slate-700 text-slate-300 dark:text-slate-500 rounded-xl flex items-center justify-center group-hover:text-emerald-600 transition-colors"><i className="fas fa-chevron-right text-xs"></i></div>
              </div>
            ))}
          </div>
        )}
      </div>

      {isAddingDhikr && (
        <div className="absolute inset-0 z-[100] bg-emerald-950/80 backdrop-blur-xl flex items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-sm bg-white dark:bg-slate-800 rounded-[56px] p-10 shadow-2xl space-y-8 animate-fade-up">
            <div className="text-center space-y-2">
              <h2 className="text-3xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">Custom Task</h2>
              <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">What would you like to recite?</p>
            </div>
            <input 
              type="text" 
              placeholder="e.g. Istighfar" 
              value={newDhikrName} 
              onChange={e => setNewDhikrName(e.target.value)} 
              className="w-full p-6 bg-slate-50 dark:bg-slate-700 border border-slate-100 dark:border-slate-600 rounded-[32px] outline-none font-black text-xl text-emerald-900 dark:text-emerald-50 placeholder:text-slate-300 focus:ring-4 focus:ring-emerald-500/10 transition-all" 
            />
            <div className="flex gap-4">
               <button onClick={() => setIsAddingDhikr(false)} className="flex-1 py-5 text-slate-400 dark:text-slate-500 font-black uppercase text-[11px] tracking-widest">Cancel</button>
               <button onClick={() => { addPersonalDhikr(newDhikrName); setIsAddingDhikr(false); setNewDhikrName(''); }} className="flex-1 py-5 bg-gradient-to-r from-emerald-600 to-emerald-800 text-white rounded-[28px] font-black uppercase text-[11px] tracking-widest shadow-xl shadow-emerald-900/20 active:scale-95 transition-all">Create</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DhikrCounter;

import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData, FastingLog } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  const [calDate, setCalDate] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[todayStr] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const dailyHadith = useMemo(() => {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / (1000 * 60 * 60 * 24));
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const inHaydToday = isDateInHayd(todayStr);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  const calendarDays = useMemo(() => {
    const year = calDate.getFullYear();
    const month = calDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();

    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) {
      days.push(`${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`);
    }
    return days;
  }, [calDate]);

  const activeDhikr = state.activeChallenges[0] || null;
  const fastingToday: FastingLog = state.fastingLogs[`ramadan-1446H-${new Date().getDate()}`] || { status: 'none', type: 'ramadan' };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden w-full transition-colors duration-500">
      {/* Header with soft blur */}
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl p-6 pt-12 pb-6 z-20 w-full flex justify-center sticky top-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 bg-gradient-to-br from-emerald-600 to-teal-700 rounded-3xl flex items-center justify-center text-white shadow-2xl shadow-emerald-600/20 transform hover:rotate-6 transition-transform">
               <i className="fas fa-mosque text-2xl"></i>
            </div>
            <div>
              <h1 className="text-3xl font-black text-emerald-950 dark:text-emerald-50 leading-none mb-1 tracking-tighter">Salam,</h1>
              <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em]">{state.profile.name}</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button onClick={() => setCurrentView('qibla')} className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 active:scale-90 transition-all shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-50 dark:border-slate-700"><i className="fas fa-compass text-xl"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center text-amber-500 dark:text-amber-400 active:scale-90 transition-all shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-50 dark:border-slate-700"><i className="fas fa-star-and-crescent text-xl"></i></button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-6 pt-8 space-y-10 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-10">

          {/* Wisdom Hero Card */}
          <div className="card-premium border-l-[16px] border-emerald-600 dark:border-emerald-500 relative group transition-all bg-white dark:bg-slate-800 overflow-hidden shadow-2xl shadow-emerald-900/5">
            <div className="absolute -right-12 -top-12 w-48 h-48 bg-emerald-50 dark:bg-emerald-900/10 rounded-full blur-[80px] opacity-40"></div>
            <div className="flex items-center gap-3 mb-6 relative z-10">
              <span className="px-4 py-2 bg-emerald-50 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-300 text-[10px] font-black rounded-full uppercase tracking-[0.2em] border border-emerald-100 dark:border-emerald-800">DAILY WISDOM</span>
            </div>
            <p className="text-emerald-950 dark:text-emerald-50 arabic-font text-4xl leading-relaxed text-right mb-8 font-black drop-shadow-sm" dir="rtl">{dailyHadith.arabic}</p>
            <p className="text-slate-500 dark:text-slate-400 italic text-base leading-relaxed border-l-4 border-emerald-100 dark:border-emerald-800 pl-6 font-medium">"{dailyHadith[userLang]}"</p>
          </div>

          {/* Dynamic Progress Hero */}
          <div className="bg-gradient-to-br from-emerald-800 via-teal-900 to-slate-900 p-12 rounded-[56px] text-white relative overflow-hidden shadow-2xl shadow-emerald-900/40 animate-fade-up">
            <div className="absolute top-0 right-0 w-96 h-96 bg-emerald-400/20 rounded-full -mr-40 -mt-40 blur-[120px]"></div>
            <div className="absolute bottom-0 left-0 w-72 h-72 bg-sky-500/10 rounded-full -ml-20 -mb-20 blur-[100px]"></div>

            <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-10">
              <div className="space-y-3">
                <div className="flex items-center gap-2.5">
                  <span className="w-2.5 h-2.5 rounded-full bg-emerald-400 indicator-pulse"></span>
                  <span className="text-[12px] font-black text-emerald-300 uppercase tracking-[0.4em]">CURRENTLY</span>
                </div>
                <h2 className="text-7xl font-black capitalize tracking-tighter drop-shadow-2xl">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <div className="flex items-center gap-3 text-emerald-100/70 font-bold bg-white/5 backdrop-blur-md px-4 py-2 rounded-full w-fit border border-white/10">
                  <i className="far fa-clock text-base"></i>
                  <span className="text-xl">{prayerTimingData?.next.time}</span>
                </div>
              </div>
              <div className="text-left md:text-right bg-white/10 backdrop-blur-xl p-8 rounded-[40px] border border-white/20 shadow-2xl">
                <p className="text-6xl font-black tabular-nums tracking-tighter text-emerald-300">{prayerTimingData?.timeLeft}</p>
                <p className="text-[11px] font-black text-emerald-400/80 uppercase tracking-[0.3em] mt-2">REMAINING TIME</p>
              </div>
            </div>

            <div className="w-full bg-black/20 h-4 rounded-full mt-12 overflow-hidden p-1 shadow-inner relative progress-shimmer">
               <div className="bg-gradient-to-r from-emerald-400 to-sky-400 h-full rounded-full transition-all duration-1000 shadow-[0_0_25px_rgba(52,211,153,0.6)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>

          {/* Path of Worship Section */}
          <div className="space-y-8">
            <div className="flex justify-between items-center px-2">
              <h3 className="text-[12px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.4em] flex items-center gap-3">
                <span className="w-2 h-2 rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/40"></span>
                MY JOURNEY TODAY
              </h3>
            </div>

            <div className="flex overflow-x-auto gap-6 pb-8 px-2 -mx-2 no-scrollbar snap-x lg:grid lg:grid-cols-4 lg:overflow-visible">

              {!inHaydToday && PRAYERS.map((p, idx) => {
                const status = todayLogs[p];
                const isDone = status === PrayerStatus.COMPLETED;
                const isUpcoming = prayerTimingData?.next.name === p;

                // Assign distinct colors to prayers for vibrancy
                const prayerThemes = ['emerald', 'teal', 'sky', 'blue', 'indigo'];
                const theme = prayerThemes[idx % prayerThemes.length];

                return (
                  <div 
                    key={p} 
                    onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                    className={`min-w-[200px] snap-center p-8 rounded-[48px] border-2 transition-all cursor-pointer flex flex-col gap-6 bg-white dark:bg-slate-800 shadow-2xl hover:-translate-y-2 ${isDone ? `border-${theme}-200 dark:border-${theme}-900 bg-${theme}-50/20 dark:bg-${theme}-900/10` : isUpcoming ? 'border-amber-400 dark:border-amber-500/50 ring-4 ring-amber-500/5' : 'border-slate-50 dark:border-slate-700/50'} active:scale-95`}
                  >
                    <div className="flex items-center justify-between">
                      <div className={`w-14 h-14 rounded-[26px] flex items-center justify-center transition-all ${isDone ? `bg-gradient-to-br from-${theme}-500 to-${theme}-700 text-white shadow-xl shadow-${theme}-500/30` : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500'}`}>
                        <i className={`fas ${isDone ? 'fa-check' : 'fa-moon'} text-xl`}></i>
                      </div>
                      {isUpcoming && (
                        <span className="flex h-3.5 w-3.5 relative">
                          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3.5 w-3.5 bg-amber-500"></span>
                        </span>
                      )}
                    </div>
                    <div>
                      <p className="font-black text-emerald-950 dark:text-emerald-50 capitalize text-xl tracking-tighter">{t(p)}</p>
                      <p className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest mt-1.5">
                        {state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}
                      </p>
                    </div>
                    <div className={`h-2 w-full rounded-full ${isDone ? `bg-${theme}-500` : 'bg-slate-100 dark:bg-slate-700'}`}></div>
                  </div>
                );
              })}

              {/* Fasting Card - Violet/Indigo Theme */}
              <div 
                onClick={() => setCurrentView('fasting')}
                className={`min-w-[200px] snap-center p-8 rounded-[48px] border-2 transition-all cursor-pointer flex flex-col gap-6 bg-white dark:bg-slate-800 shadow-2xl hover:-translate-y-2 ${fastingToday.status === 'completed' ? 'border-violet-200 bg-violet-50/20' : fastingToday.status === 'excused' ? 'border-pink-200 bg-pink-50/20' : 'border-slate-50 dark:border-slate-700/50'}`}
              >
                <div className={`w-14 h-14 rounded-[26px] flex items-center justify-center ${fastingToday.status === 'completed' ? 'bg-gradient-to-br from-violet-500 to-indigo-600 text-white shadow-xl shadow-violet-500/30' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500'}`}>
                  <i className="fas fa-moon text-xl"></i>
                </div>
                <div>
                  <p className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tighter">Fasting</p>
                  <p className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest mt-1.5">
                    {fastingToday.status === 'completed' ? 'ACHIEVED' : fastingToday.status === 'excused' ? 'EXEMPTED' : 'LOG FAST'}
                  </p>
                </div>
                <div className={`h-2 w-full rounded-full ${fastingToday.status === 'completed' ? 'bg-violet-500' : 'bg-slate-100 dark:bg-slate-700'}`}></div>
              </div>

              {/* Dhikr Card - Sky/Cyan Theme */}
              {activeDhikr && (
                <div 
                  onClick={() => setCurrentView('challenges')}
                  className={`min-w-[200px] snap-center p-8 rounded-[48px] border-2 transition-all cursor-pointer flex flex-col gap-6 bg-white dark:bg-slate-800 shadow-2xl hover:-translate-y-2 ${activeDhikr.current >= activeDhikr.target ? 'border-sky-200 bg-sky-50/20' : 'border-slate-100 dark:border-slate-700/50'}`}
                >
                  <div className={`w-14 h-14 rounded-[26px] flex items-center justify-center ${activeDhikr.current >= activeDhikr.target ? 'bg-gradient-to-br from-sky-400 to-teal-500 text-white shadow-xl shadow-sky-400/30' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500'}`}>
                    <i className="fas fa-bolt text-xl"></i>
                  </div>
                  <div className="overflow-hidden">
                    <p className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tighter truncate">{t(activeDhikr.title)}</p>
                    <p className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest mt-1.5">
