                      className={`h-full transition-all duration-700 ${activeDhikr.current >= activeDhikr.target ? 'bg-sky-500' : 'bg-sky-300'}`} 
                      style={{ width: `${Math.min(100, (activeDhikr.current / activeDhikr.target) * 100)}%` }}
