                </div>
              )}
            </div>
          </div>

          {/* Quick Stats Grid with vibrant backgrounds */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="card-premium flex items-center gap-8 bg-gradient-to-br from-emerald-50/50 to-white dark:from-emerald-950/30 dark:to-slate-800/40 border-emerald-100/50 dark:border-emerald-900/30 group">
               <div className="w-20 h-20 bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 rounded-[32px] flex items-center justify-center text-4xl shadow-2xl shadow-emerald-900/5 group-hover:scale-110 transition-transform"><i className="fas fa-fire-flame-curved"></i></div>
               <div>
                 <span className="text-[11px] font-black text-emerald-800/40 dark:text-emerald-400/40 uppercase tracking-[0.3em] block mb-1.5">TOTAL STREAK</span>
                 <p className="text-4xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter tabular-nums">{state.dhikrCount.toLocaleString()}</p>
               </div>
            </div>
            <div className="card-premium flex items-center gap-8 bg-gradient-to-br from-amber-50/50 to-white dark:from-amber-950/30 dark:to-slate-800/40 border-amber-100/50 dark:border-amber-900/30 group">
               <div className="w-20 h-20 bg-white dark:bg-slate-700 text-amber-500 dark:text-amber-400 rounded-[32px] flex items-center justify-center text-4xl shadow-2xl shadow-amber-900/5 group-hover:scale-110 transition-transform"><i className="fas fa-book-open-reader"></i></div>
               <div className="overflow-hidden">
                 <span className="text-[11px] font-black text-amber-800/40 dark:text-amber-400/40 uppercase tracking-[0.3em] block mb-1.5">QURAN PROGRESS</span>
