              <div className="flex gap-2.5 bg-slate-100/50 dark:bg-slate-800 p-1.5 rounded-[24px]">
                <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() - 1, 1))} className="w-11 h-11 bg-white dark:bg-slate-700 rounded-2xl flex items-center justify-center text-slate-400 hover:text-emerald-600 transition-all shadow-md active:scale-90"><i className="fas fa-chevron-left text-sm"></i></button>
                <button onClick={() => setCalDate(new Date())} className="px-5 h-11 bg-white dark:bg-slate-700 rounded-2xl text-[11px] font-black uppercase tracking-widest text-emerald-900 dark:text-emerald-100 shadow-md active:scale-90">TODAY</button>
                <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() + 1, 1))} className="w-11 h-11 bg-white dark:bg-slate-700 rounded-2xl flex items-center justify-center text-slate-400 hover:text-emerald-600 transition-all shadow-md active:scale-90"><i className="fas fa-chevron-right text-sm"></i></button>
