                {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => (
                  <div key={d} className="text-center text-[10px] font-black text-slate-300 dark:text-slate-600 uppercase py-2 tracking-[0.2em]">{d}</div>
                ))}
