              <div className="grid grid-cols-7 gap-3">
                {calendarDays.map((dateStr, idx) => {
                  if (!dateStr) return <div key={`empty-${idx}`} className="h-20 md:h-28"></div>;

                  const isToday = dateStr === todayStr;
                  const inHayd = isDateInHayd(dateStr);
                  const logs = state.prayerLogs[dateStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };
                  const dayNum = dateStr.split('-')[2];

                  return (
                    <div 
                      key={dateStr}
                      className={`h-20 md:h-28 rounded-[32px] border-2 flex flex-col items-center justify-between p-3 transition-all group ${isToday ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-900/30 scale-105 z-10 shadow-xl shadow-emerald-500/10' : inHayd ? 'border-pink-200 dark:border-pink-900/30 bg-pink-50/50 dark:bg-pink-900/20' : 'border-slate-50 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}
                    >
                      <span className={`text-[12px] font-black ${isToday ? 'text-emerald-700 dark:text-emerald-400' : inHayd ? 'text-pink-600 dark:text-pink-400' : 'text-slate-400 dark:text-slate-500'}`}>
                        {parseInt(dayNum)}
