                            const status = logs[p as keyof typeof logs];
                            const color = status === 'completed' ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]' : status === 'missed' ? 'bg-rose-400' : 'bg-slate-200 dark:bg-slate-700';
                            return (
                              <div key={p} title={p} className={`w-2.5 h-2.5 rounded-full transition-transform group-hover:scale-125 ${color}`}></div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>

              <div className="mt-10 flex flex-wrap gap-8 pt-8 border-t border-slate-100 dark:border-slate-700 justify-center">
                <div className="flex items-center gap-3 bg-emerald-50 dark:bg-emerald-900/30 px-5 py-2.5 rounded-full border border-emerald-100 dark:border-emerald-800">
                  <div className="w-3 h-3 rounded-full bg-emerald-500 shadow-md shadow-emerald-500/30"></div>
                  <span className="text-[11px] font-black text-emerald-800 dark:text-emerald-300 uppercase tracking-widest">Fulfilling</span>
                </div>
                <div className="flex items-center gap-3 bg-rose-50 dark:bg-rose-900/30 px-5 py-2.5 rounded-full border border-rose-100 dark:border-rose-800">
                  <div className="w-3 h-3 rounded-full bg-rose-400 shadow-md shadow-rose-400/30"></div>
                  <span className="text-[11px] font-black text-rose-800 dark:text-rose-300 uppercase tracking-widest">Missed</span>
                </div>
                <div className="flex items-center gap-3 bg-slate-50 dark:bg-slate-700 px-5 py-2.5 rounded-full border border-slate-100 dark:border-slate-600">
                  <div className="w-3 h-3 rounded-full bg-slate-300 dark:bg-slate-500 shadow-md"></div>
                  <span className="text-[11px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Pending</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden transition-colors duration-500">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl p-8 pt-14 pb-8 flex flex-col gap-6 z-10 shrink-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="flex justify-between items-center w-full content-limit">
          <div>
            <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-1 tracking-tighter">{t('fard')}</h1>
            <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Spiritual Fulfillment</p>
          </div>
          <div className="flex bg-slate-100/50 dark:bg-slate-800 p-1.5 rounded-[24px] shadow-inner">
            <button onClick={() => setActiveTab('fard')} className={`px-6 py-3 rounded-[18px] text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-lg' : 'text-slate-400'}`}>{t('fard')}</button>
            <button onClick={() => setActiveTab('sunnah')} className={`px-6 py-3 rounded-[18px] text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-lg' : 'text-slate-400'}`}>{t('sunnah')}</button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-6 pt-8 space-y-6 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-6">
          {isExcused && (
            <div className="bg-gradient-to-r from-rose-50 to-white dark:from-rose-950/20 dark:to-slate-900 p-6 rounded-[32px] border-2 border-rose-100 dark:border-rose-900/30 flex items-center gap-5 animate-fade-up">
              <div className="w-14 h-14 bg-rose-100 dark:bg-rose-900/40 rounded-2xl flex items-center justify-center text-rose-500">
                <i className="fas fa-leaf text-2xl"></i>
              </div>
              <div>
                <p className="text-rose-950 dark:text-rose-100 text-[11px] font-black uppercase tracking-widest mb-1">{t('excused')}</p>
                <p className="text-rose-700/60 dark:text-rose-400/60 text-sm font-medium">Rest well during your recovery period.</p>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 gap-5">
            {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p, idx) => {
              const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
              const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;

              // Vibrant color assignment
              const themes = ['emerald', 'teal', 'sky', 'blue', 'indigo', 'violet'];
              const theme = themes[idx % themes.length];

              return (
                <div 
                  key={p} 
                  onClick={() => !isExcused && handleToggle(p, activeTab)} 
                  className={`card-premium flex items-center justify-between py-6 btn-ripple cursor-pointer border-2 transition-all group ${isDone ? `border-${theme}-400 bg-${theme}-50/10 dark:bg-${theme}-900/10` : 'border-transparent dark:bg-slate-800'} ${isExcused ? 'opacity-30 grayscale cursor-not-allowed' : 'hover:border-slate-200 dark:hover:border-slate-700'}`}
                >
                  <div className="flex items-center gap-6">
                    <div className={`w-16 h-16 rounded-[28px] flex items-center justify-center text-2xl transition-all ${isDone ? `bg-gradient-to-br from-${theme}-500 to-${theme}-700 text-white shadow-2xl shadow-${theme}-500/30` : 'bg-slate-100 dark:bg-slate-700 text-slate-300 dark:text-slate-500'}`}>
                      <i className={`fas ${isDone ? 'fa-check-circle' : 'fa-kaaba'} group-hover:scale-110 transition-transform`}></i>
                    </div>
                    <div>
                      <h3 className="font-black text-emerald-950 dark:text-emerald-50 capitalize text-xl tracking-tight">{t(p)}</h3>
                      {time && <p className="text-[11px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mt-1">{time}</p>}
                    </div>
                  </div>
                  {isDone && (
                    <div className="flex flex-col items-end gap-1 animate-fade-in">
                      <span className={`text-[10px] font-black text-${theme}-600 dark:text-${theme}-400 bg-${theme}-50 dark:bg-${theme}-900/30 px-4 py-1.5 rounded-full uppercase tracking-widest border border-${theme}-100 dark:border-${theme}-800`}>Fulfilling</span>
                      <i className="fas fa-sparkles text-amber-400 text-xs"></i>
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          <div className="bg-gradient-to-br from-emerald-800 to-teal-900 p-10 rounded-[48px] text-center border-4 border-white dark:border-slate-800 shadow-2xl shadow-emerald-900/20 mt-12 relative overflow-hidden group">
             <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
             <p className="arabic-font text-white text-4xl font-black mb-3 drop-shadow-lg" dir="rtl">الصلاة خير من النوم</p>
             <p className="text-emerald-100/60 text-[11px] font-black uppercase tracking-[0.4em]">Prayer is more rewarding than sleep</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData, FastingLog } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  const [calDate, setCalDate] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[todayStr] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const inHaydToday = isDateInHayd(todayStr);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  const calendarDays = useMemo(() => {
    const year = calDate.getFullYear();
    const month = calDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) days.push(`${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`);
    return days;
  }, [calDate]);

  const activeDhikr = state.activeChallenges[0] || null;
  const fastingToday: FastingLog = state.fastingLogs[`ramadan-1446H-${new Date().getDate()}`] || { status: 'none', type: 'ramadan' };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden w-full">
      {/* Compact Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl px-4 py-3 z-20 w-full flex justify-center sticky top-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-emerald-600 to-teal-700 rounded-xl flex items-center justify-center text-white shadow-lg">
               <i className="fas fa-mosque text-lg"></i>
            </div>
            <div>
              <h1 className="text-lg font-black text-emerald-950 dark:text-emerald-50 leading-none">Salam,</h1>
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{state.profile.name}</p>
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setCurrentView('qibla')} className="w-9 h-9 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 border border-slate-100 dark:border-slate-700"><i className="fas fa-compass text-base"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-9 h-9 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-amber-500 dark:text-amber-400 border border-slate-100 dark:border-slate-700"><i className="fas fa-sparkles text-base"></i></button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-4 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-4">

          {/* Compact Hero Banner */}
          <div className="bg-gradient-to-br from-emerald-800 to-teal-900 p-6 rounded-[28px] text-white relative overflow-hidden shadow-xl animate-fade-up">
            <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-400/10 rounded-full -mr-32 -mt-32 blur-[80px]"></div>
            <div className="relative z-10 flex items-center justify-between">
              <div className="space-y-1">
                <span className="text-[9px] font-black text-emerald-300 uppercase tracking-[0.3em]">UP NEXT</span>
                <h2 className="text-4xl font-black capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <p className="text-emerald-100/70 text-sm font-medium">{prayerTimingData?.next.time}</p>
              </div>
              <div className="text-right bg-white/10 backdrop-blur-md p-4 rounded-[20px] border border-white/10">
                <p className="text-3xl font-black tabular-nums tracking-tighter text-emerald-300">{prayerTimingData?.timeLeft}</p>
                <p className="text-[8px] font-black text-emerald-400/60 uppercase tracking-widest">REMAINING</p>
              </div>
            </div>
            <div className="w-full bg-black/15 h-2 rounded-full mt-5 overflow-hidden p-0.5">
               <div className="bg-emerald-400 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>

          {/* Compact Obligations Grid */}
          <div className="space-y-3">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] px-1">DAILY PATH</h3>
            <div className="flex overflow-x-auto gap-3 pb-2 px-1 -mx-1 no-scrollbar snap-x">
              {!inHaydToday && PRAYERS.map((p, idx) => {
                const status = todayLogs[p];
                const isDone = status === PrayerStatus.COMPLETED;
                const isUpcoming = prayerTimingData?.next.name === p;
                const prayerThemes = ['emerald', 'teal', 'sky', 'blue', 'indigo'];
                const theme = prayerThemes[idx % prayerThemes.length];

                return (
                  <div 
                    key={p} 
                    onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                    className={`min-w-[130px] snap-center p-4 rounded-[24px] border transition-all cursor-pointer flex flex-col gap-3 bg-white dark:bg-slate-800 shadow-sm ${isDone ? `border-${theme}-200 bg-${theme}-50/10` : isUpcoming ? 'border-amber-400 ring-2 ring-amber-500/5' : 'border-slate-100 dark:border-slate-700'}`}
                  >
                    <div className="flex items-center justify-between">
                      <div className={`w-9 h-9 rounded-xl flex items-center justify-center ${isDone ? `bg-${theme}-500 text-white shadow-md` : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                        <i className={`fas ${isDone ? 'fa-check' : 'fa-moon'} text-xs`}></i>
                      </div>
