import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData, FastingLog } from '../types';
import { HADITHS, PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const userLang = (state.profile?.preferredLanguage || 'en') as Language;
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  const [calDate, setCalDate] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const todayLogs = state.prayerLogs[todayStr] || {
    fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING
  };

  const isDateInHayd = (dateStr: string): boolean => {
    const targetDate = new Date(dateStr).getTime();
    return state.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + (100 * 365 * 24 * 60 * 60 * 1000);
      return targetDate >= start && targetDate <= end;
    });
  };

  const inHaydToday = isDateInHayd(todayStr);

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  const calendarDays = useMemo(() => {
    const year = calDate.getFullYear();
    const month = calDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const lastDate = new Date(year, month + 1, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= lastDate; i++) days.push(`${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`);
    return days;
  }, [calDate]);

  const activeDhikr = state.activeChallenges[0] || null;
  const fastingToday: FastingLog = state.fastingLogs[`ramadan-1446H-${new Date().getDate()}`] || { status: 'none', type: 'ramadan' };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden w-full">
      {/* Compact Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl px-4 py-3 z-20 w-full flex justify-center sticky top-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-emerald-600 to-teal-700 rounded-xl flex items-center justify-center text-white shadow-lg">
               <i className="fas fa-mosque text-lg"></i>
            </div>
            <div>
              <h1 className="text-lg font-black text-emerald-950 dark:text-emerald-50 leading-none">Salam,</h1>
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{state.profile.name}</p>
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setCurrentView('qibla')} className="w-9 h-9 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 border border-slate-100 dark:border-slate-700"><i className="fas fa-compass text-base"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-9 h-9 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-amber-500 dark:text-amber-400 border border-slate-100 dark:border-slate-700"><i className="fas fa-sparkles text-base"></i></button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-4 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-4">

          {/* Compact Hero Banner */}
          <div className="bg-gradient-to-br from-emerald-800 to-teal-900 p-6 rounded-[28px] text-white relative overflow-hidden shadow-xl animate-fade-up">
            <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-400/10 rounded-full -mr-32 -mt-32 blur-[80px]"></div>
            <div className="relative z-10 flex items-center justify-between">
              <div className="space-y-1">
                <span className="text-[9px] font-black text-emerald-300 uppercase tracking-[0.3em]">UP NEXT</span>
                <h2 className="text-4xl font-black capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <p className="text-emerald-100/70 text-sm font-medium">{prayerTimingData?.next.time}</p>
              </div>
              <div className="text-right bg-white/10 backdrop-blur-md p-4 rounded-[20px] border border-white/10">
                <p className="text-3xl font-black tabular-nums tracking-tighter text-emerald-300">{prayerTimingData?.timeLeft}</p>
                <p className="text-[8px] font-black text-emerald-400/60 uppercase tracking-widest">REMAINING</p>
              </div>
            </div>
            <div className="w-full bg-black/15 h-2 rounded-full mt-5 overflow-hidden p-0.5">
               <div className="bg-emerald-400 h-full rounded-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
            </div>
          </div>

          {/* Compact Obligations Grid */}
          <div className="space-y-3">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] px-1">DAILY PATH</h3>
            <div className="flex overflow-x-auto gap-3 pb-2 px-1 -mx-1 no-scrollbar snap-x">
              {!inHaydToday && PRAYERS.map((p, idx) => {
                const status = todayLogs[p];
                const isDone = status === PrayerStatus.COMPLETED;
                const isUpcoming = prayerTimingData?.next.name === p;
                const prayerThemes = ['emerald', 'teal', 'sky', 'blue', 'indigo'];
                const theme = prayerThemes[idx % prayerThemes.length];

                return (
                  <div 
                    key={p} 
                    onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                    className={`min-w-[130px] snap-center p-4 rounded-[24px] border transition-all cursor-pointer flex flex-col gap-3 bg-white dark:bg-slate-800 shadow-sm ${isDone ? `border-${theme}-200 bg-${theme}-50/10` : isUpcoming ? 'border-amber-400 ring-2 ring-amber-500/5' : 'border-slate-100 dark:border-slate-700'}`}
                  >
                    <div className="flex items-center justify-between">
                      <div className={`w-9 h-9 rounded-xl flex items-center justify-center ${isDone ? `bg-${theme}-500 text-white shadow-md` : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                        <i className={`fas ${isDone ? 'fa-check' : 'fa-moon'} text-xs`}></i>
                      </div>
                      {isUpcoming && <span className="w-2 h-2 rounded-full bg-amber-500"></span>}
                    </div>
                    <div>
                      <p className="font-black text-emerald-950 dark:text-emerald-50 capitalize text-sm tracking-tight">{t(p)}</p>
                      <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}</p>
                    </div>
                  </div>
                );
              })}

              {/* Compact Fasting & Dhikr */}
              <div onClick={() => setCurrentView('fasting')} className={`min-w-[130px] snap-center p-4 rounded-[24px] border transition-all cursor-pointer flex flex-col gap-3 bg-white dark:bg-slate-800 shadow-sm ${fastingToday.status === 'completed' ? 'border-violet-200' : 'border-slate-100 dark:border-slate-700'}`}>
                <div className={`w-9 h-9 rounded-xl flex items-center justify-center ${fastingToday.status === 'completed' ? 'bg-violet-500 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                  <i className="fas fa-moon text-xs"></i>
                </div>
                <div>
                  <p className="font-black text-emerald-950 dark:text-emerald-50 text-sm tracking-tight">Fasting</p>
                  <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{fastingToday.status === 'completed' ? 'DONE' : 'LOG IT'}</p>
                </div>
              </div>

              {activeDhikr && (
                <div onClick={() => setCurrentView('challenges')} className={`min-w-[130px] snap-center p-4 rounded-[24px] border transition-all cursor-pointer flex flex-col gap-3 bg-white dark:bg-slate-800 shadow-sm ${activeDhikr.current >= activeDhikr.target ? 'border-sky-200' : 'border-slate-100 dark:border-slate-700'}`}>
                  <div className={`w-9 h-9 rounded-xl flex items-center justify-center ${activeDhikr.current >= activeDhikr.target ? 'bg-sky-500 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                    <i className="fas fa-bolt text-xs"></i>
                  </div>
                  <div>
                    <p className="font-black text-emerald-950 dark:text-emerald-50 text-sm tracking-tight truncate">{t(activeDhikr.title)}</p>
                    <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{activeDhikr.current}/{activeDhikr.target}</p>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Tighter Calendar Card */}
          <div className="card-premium !p-4 shadow-sm">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em]">JOURNEY MAP</h3>
              <div className="flex gap-1.5">
                <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() - 1, 1))} className="w-7 h-7 bg-slate-50 dark:bg-slate-700 rounded-lg flex items-center justify-center text-slate-400 hover:text-emerald-600"><i className="fas fa-chevron-left text-[8px]"></i></button>
                <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() + 1, 1))} className="w-7 h-7 bg-slate-50 dark:bg-slate-700 rounded-lg flex items-center justify-center text-slate-400 hover:text-emerald-600"><i className="fas fa-chevron-right text-[8px]"></i></button>
              </div>
            </div>
            <div className="grid grid-cols-7 gap-1.5">
              {['S','M','T','W','T','F','S'].map(d => <div key={d} className="text-center text-[7px] font-black text-slate-300 py-1">{d}</div>)}
              {calendarDays.map((dateStr, idx) => {
                if (!dateStr) return <div key={`empty-${idx}`} className="h-10"></div>;
                const isToday = dateStr === todayStr;
                const inHayd = isDateInHayd(dateStr);
                const dayNum = dateStr.split('-')[2];
                const logs = state.prayerLogs[dateStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };

                return (
                  <div 
                    key={dateStr}
                    className={`h-11 md:h-14 rounded-xl border flex flex-col items-center justify-between p-1.5 transition-all ${isToday ? 'border-emerald-500 bg-emerald-50/50' : inHayd ? 'border-pink-200 bg-pink-50/50' : 'border-slate-50 dark:border-slate-700'}`}
                  >
                    <span className={`text-[9px] font-black ${isToday ? 'text-emerald-700' : inHayd ? 'text-pink-600' : 'text-slate-400'}`}>{parseInt(dayNum)}</span>
                    {!inHayd && (
                      <div className="flex flex-wrap gap-0.5 justify-center">
                        {PRAYERS.map(p => {
                          const status = logs[p as keyof typeof logs];
                          const color = status === 'completed' ? 'bg-emerald-500' : status === 'missed' ? 'bg-rose-400' : 'bg-slate-200 dark:bg-slate-600';
                          return <div key={p} className={`w-1 h-1 rounded-full ${color}`}></div>;
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PersonalDhikr, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import QadahCalendar from './components/QadahCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';
import AuthSelection from './components/AuthSelection';

const USERS_DB_KEY = 'ibadathi_v1_users_database';
const SESSION_KEY = 'ibadathi_v1_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let parsedUsers: Record<string, UserData> = {};
    try { parsedUsers = savedUsers ? JSON.parse(savedUsers) : {}; } catch (e) {}
    const currentUser = (activeSession && parsedUsers[activeSession]) ? activeSession : null;
    return { currentUser, users: parsedUsers, todayTimings: DEFAULT_TIMINGS };
  });

  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;
  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    return (state.currentUser && state.users[state.currentUser]) ? state.users[state.currentUser].profile.preferredLanguage : 'en';
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [isAuth, setIsAuth] = useState<boolean>(!!state.currentUser);

  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
      setIsAuth(true);
    } else {
      localStorage.removeItem(SESSION_KEY);
      setIsAuth(false);
    }
  }, [state.users, state.currentUser]);

  // Handle Dark Mode Class
  useEffect(() => {
    const theme = currentUserData?.settings.theme || 'light';
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [currentUserData?.settings.theme]);

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { notificationsEnabled: false, locationEnabled: false, theme: 'light', qadaReminders: [] }
      };
      setState(prev => ({ ...prev, currentUser: username, users: { ...prev.users, [username]: newUserData } }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }
    setCurrentLanguage(profile.preferredLanguage);
    setActiveTab('home');
    setSubView(null);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('home');
    setSubView(null);
  };

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  const updatePrayerStatus = (date: string, prayer: any, status: PrayerStatus) => {
    updateActiveUser(user => {
      const logs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return { ...user, prayerLogs: { ...user.prayerLogs, [date]: { ...logs, [prayer]: status } } };
    });
  };

  const toggleSunnahStatus = (date: string, sunnah: string) => {
    updateActiveUser(user => {
      const cur = user.sunnahLogs[date] || [];
      const upd = cur.includes(sunnah) ? cur.filter(s => s !== sunnah) : [...cur, sunnah];
      return { ...user, sunnahLogs: { ...user.sunnahLogs, [date]: upd } };
    });
  };

  const toggleTheme = () => {
    updateActiveUser(u => ({
      ...u,
      settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' }
    }));
  };

  if (!isAuth) {
    return (
      <div className="app-viewport animate-fade-in bg-slate-900">
        <main className="h-full flex flex-col w-full overflow-hidden">
          {subView === 'auth-form' ? (
            <Login 
              onLogin={handleLogin} 
              t={t} 
              initialLanguage={currentLanguage} 
              users={state.users} 
              initialMode={authMode}
              onBack={() => setSubView('auth-choice')}
            />
          ) : subView === 'auth-choice' ? (
            <AuthSelection 
              t={t} 
              onSelect={(mode) => {
                setAuthMode(mode);
                setSubView('auth-form');
              }}
              onBack={() => setSubView(null)}
            />
          ) : (
            <Welcome onEnter={() => setSubView('auth-choice')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
          )}
        </main>
      </div>
    );
  }

  const compositeState = { ...currentUserData!, todayTimings: state.todayTimings };

  const renderContent = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeState} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeState} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'qadah') return <QadahCalendar state={compositeState} updatePrayerStatus={updatePrayerStatus} updateReminders={() => {}} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeState} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home':
        return <Dashboard state={compositeState} setCurrentView={setSubView} t={t} onLogout={handleLogout} toggleNotifications={() => {}} updatePrayerStatus={updatePrayerStatus} />;
      case 'prayer':
        return <FardPrayers state={compositeState} updatePrayerStatus={updatePrayerStatus} toggleSunnahStatus={toggleSunnahStatus} setCurrentView={setSubView} t={t} />;
      case 'challenges':
        return (
          <DhikrCounter 
            state={compositeState} 
            updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
            updatePersonalProgress={(id, d) => updateActiveUser(u => {
              const today = new Date().toISOString().split('T')[0];
              const upd = u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd);
              return { ...u, personalDhikrs: upd, dhikrCount: u.dhikrCount + d };
            })}
            addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
            resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
            deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
            archiveChallenge={(id) => updateActiveUser(u => {
              const c = u.activeChallenges.find(x => x.id === id);
              if (!c) return u;
              const hist = { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() };
              return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [hist, ...u.dhikrHistory], activeDhikrId: null };
            })}
            setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))}
            setCurrentView={setSubView} t={t} 
          />
        );
      case 'tracker':
        return (
          <div className="scroll-container p-6 w-full content-limit">
            <h2 className="text-3xl font-black text-emerald-900 dark:text-emerald-100 mb-6">My Progress</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="card-premium dark:bg-slate-800 dark:border-slate-700 flex items-center gap-4 bg-gradient-to-br from-emerald-50/50 to-white">
                <div className="w-14 h-14 bg-emerald-500 text-white rounded-2xl flex items-center justify-center text-2xl shadow-lg shadow-emerald-500/20"><i className="fas fa-fire"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-lg">Streak</h3>
                  <p className="text-xl font-black text-emerald-600 tabular-nums">{compositeState.dhikrCount.toLocaleString()}</p>
                </div>
              </div>
              <div onClick={() => setSubView('quran')} className="card-premium dark:bg-slate-800 dark:border-slate-700 flex items-center gap-4 btn-ripple cursor-pointer">
                <div className="w-14 h-14 bg-amber-50 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400 rounded-2xl flex items-center justify-center text-2xl"><i className="fas fa-book-open"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-lg">{t('quran')}</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest">{compositeState.quranProgress.surah || 'Not started'}</p>
                </div>
                <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
              </div>
              <div onClick={() => setSubView('fasting')} className="card-premium dark:bg-slate-800 dark:border-slate-700 flex items-center gap-4 btn-ripple cursor-pointer">
                <div className="w-14 h-14 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-2xl flex items-center justify-center text-2xl"><i className="fas fa-moon"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-lg">{t('fasting')}</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest">Goal tracked</p>
                </div>
                <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
              </div>
              <div onClick={() => setSubView('qadah')} className="card-premium dark:bg-slate-800 dark:border-slate-700 flex items-center gap-4 btn-ripple cursor-pointer">
                <div className="w-14 h-14 bg-rose-50 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-2xl flex items-center justify-center text-2xl"><i className="fas fa-calendar-check"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-lg">{t('qadah')}</h3>
                  <p className="text-[10px] text-slate-400 uppercase tracking-widest">Missed prayers log</p>
                </div>
                <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
              </div>
              {compositeState.profile.sex === 'female' && (
                <div onClick={() => setSubView('women')} className="card-premium dark:bg-slate-800 dark:border-slate-700 flex items-center gap-4 btn-ripple cursor-pointer">
                  <div className="w-14 h-14 bg-rose-50 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-2xl flex items-center justify-center text-2xl"><i className="fas fa-leaf"></i></div>
                  <div className="flex-1">
                    <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-lg">{t('womensSpace')}</h3>
                    <p className="text-[10px] text-slate-400 uppercase tracking-widest">Period tracking</p>
                  </div>
                  <i className="fas fa-chevron-right text-slate-300 text-xs"></i>
                </div>
              )}
            </div>
          </div>
        );
      case 'account':
        return <MyAccount state={compositeState} setCurrentView={setSubView} t={t} onLogout={handleLogout} toggleTheme={toggleTheme} />;
      default: return null;
    }
  };

  return (
    <div className="app-viewport animate-fade-in bg-ivory dark:bg-slate-900 dark:text-slate-100" dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative w-full h-full">
        {renderContent()}
      </main>

      {!subView && (
        <nav className="bottom-nav dark:bg-slate-900/95 dark:border-slate-800">
          <button onClick={() => setActiveTab('home')} className={`nav-item ${activeTab === 'home' ? 'active' : ''}`}>
            <i className="fas fa-house"></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">Home</span>
          </button>
