                  >
                    <div className="flex items-center justify-between">
                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isDone ? `bg-${theme}-500 text-white shadow-md` : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
