              })}

              {/* Compact Fasting & Dhikr */}
              <div onClick={() => setCurrentView('fasting')} className={`min-w-[105px] snap-center p-3 rounded-[20px] border transition-all cursor-pointer flex flex-col gap-2 bg-white dark:bg-slate-800 shadow-sm ${fastingToday.status === 'completed' ? 'border-violet-200' : 'border-slate-100 dark:border-slate-700'}`}>
