              </div>

              {activeDhikr && (
                <div onClick={() => setCurrentView('challenges')} className={`min-w-[105px] snap-center p-3 rounded-[20px] border transition-all cursor-pointer flex flex-col gap-2 bg-white dark:bg-slate-800 shadow-sm ${activeDhikr.current >= activeDhikr.target ? 'border-sky-200' : 'border-slate-100 dark:border-slate-700'}`}>
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${activeDhikr.current >= activeDhikr.target ? 'bg-sky-500 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
