import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
  initialMode?: 'login' | 'register';
  onBack?: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users, initialMode = 'login', onBack }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setMode(initialMode);
  }, [initialMode]);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  const usernameStatus = useMemo(() => {
    if (mode === 'login' || usernameNormalized.length < 3) return 'idle';
    return users[usernameNormalized] ? 'taken' : 'available';
  }, [usernameNormalized, mode, users]);

  const suggestions = useMemo(() => {
    if (usernameStatus !== 'taken') return [];
    const base = usernameNormalized;
    return [
      `${base}${Math.floor(Math.random() * 99) + 1}`,
      `${base}_i`,
      `${base}786`
    ].filter(s => !users[s.toLowerCase()]);
  }, [usernameStatus, usernameNormalized, users]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password) return "Password is required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (usernameStatus === 'taken') return t('usernameTaken');
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setIsAuthenticating(true);
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "User not found." : "Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const inputClasses = "w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl focus:ring-4 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-black text-emerald-900 dark:text-emerald-50 placeholder:text-slate-300 text-sm";
  const labelClasses = "block text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-900 w-full overflow-hidden animate-fade-in">
      {onBack && (
        <header className="px-6 py-4 flex items-center z-10 shrink-0">
          <button onClick={onBack} className="w-9 h-9 bg-emerald-50 dark:bg-slate-800 rounded-xl flex items-center justify-center text-emerald-900 dark:text-emerald-500 border border-emerald-100 dark:border-slate-700 active:scale-90 transition-all">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
        </header>
      )}

      <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col items-center">
        <div className="flex flex-col items-center mb-6 shrink-0">
          <div className="w-12 h-12 bg-gradient-to-br from-emerald-600 to-teal-800 rounded-[18px] flex items-center justify-center mb-3 shadow-xl border-2 border-white dark:border-slate-700 rotate-3 transition-transform">
            <i className="fas fa-kaaba text-xl text-white"></i>
          </div>
          <h1 className="text-2xl font-black text-emerald-900 dark:text-emerald-50 mb-0.5 tracking-tighter">Ibadathi</h1>
          <p className="text-[7px] font-black text-emerald-800/40 dark:text-emerald-400/30 uppercase tracking-[0.3em]">Sacred Companion</p>
        </div>

        <div className="flex bg-emerald-50/50 dark:bg-slate-800/50 p-1 rounded-2xl mb-6 w-full max-w-[240px] shrink-0 border border-emerald-100/50 dark:border-slate-700">
          <button 
            type="button"
            onClick={() => { setMode('login'); setError(null); }}
            className={`flex-1 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-md' : 'text-emerald-900/40 dark:text-slate-500'}`}
          >
            {t('login')}
          </button>
          <button 
            type="button"
            onClick={() => { setMode('register'); setError(null); }}
            className={`flex-1 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-md' : 'text-emerald-900/40 dark:text-slate-500'}`}
          >
            {t('register')}
          </button>
        </div>

        <form onSubmit={handleSubmit} className="w-full max-w-[320px] space-y-3.5 flex flex-col pb-10">
          {error && (
            <div className="bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 p-3 rounded-xl text-[10px] font-black text-center border border-rose-100 dark:border-rose-900/30 animate-shake">
              <i className="fas fa-exclamation-circle mr-1.5"></i> {error}
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>{t('username')}</label>
            <div className="relative">
              <input 
                type="text" 
                className={`${inputClasses} ${usernameStatus === 'taken' ? 'border-rose-300' : usernameStatus === 'available' ? 'border-emerald-400' : ''}`}
                placeholder="username"
                value={formData.username}
                onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})}
                required
              />
              <div className="absolute right-4 top-1/2 -translate-y-1/2">
                {usernameStatus === 'available' && <i className="fas fa-check-circle text-emerald-500 text-xs"></i>}
                {usernameStatus === 'taken' && <i className="fas fa-times-circle text-rose-500 text-xs"></i>}
              </div>
            </div>
            {usernameStatus === 'taken' && mode === 'register' && (
              <div className="bg-rose-50/50 dark:bg-rose-950/10 p-2 rounded-xl border border-rose-100/50 dark:border-rose-900/20 mt-1">
                <p className="text-[7px] font-black text-rose-800/50 uppercase tracking-widest mb-1">{t('suggestions')}</p>
                <div className="flex flex-wrap gap-1">
                  {suggestions.map(s => (
                    <button 
                      key={s} 
                      type="button"
                      onClick={() => setFormData({...formData, username: s})}
                      className="bg-white dark:bg-slate-700 px-2 py-1 rounded-lg text-[8px] font-black text-rose-900 dark:text-rose-200 border border-rose-100 dark:border-rose-900 shadow-sm"
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {mode === 'register' && (
            <div className="space-y-3.5 animate-fade-in">
              <div className="space-y-1">
                <label className={labelClasses}>{t('name')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Your Name"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <label className={labelClasses}>{t('age')}</label>
                  <input 
                    type="number"
                    className={inputClasses}
                    placeholder="25"
                    value={formData.age}
                    onChange={e => setFormData({...formData, age: e.target.value})}
                    required
                  />
                </div>
                <div className="space-y-1">
                  <label className={labelClasses}>{t('sex')}</label>
                  <select 
                    className={inputClasses}
                    value={formData.sex}
                    onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                  >
                    <option value="male" className="font-black">{t('male')}</option>
                    <option value="female" className="font-black">{t('female')}</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className={labelClasses}>{t('place')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Makkah"
                  value={formData.place}
                  onChange={e => setFormData({...formData, place: e.target.value})}
                  required
                />
              </div>
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>{t('password')}</label>
            <input 
              type="password"
              className={inputClasses}
              placeholder="••••••••"
              value={formData.password}
              onChange={e => setFormData({...formData, password: e.target.value})}
              required
            />
          </div>

          <button 
            type="submit"
            disabled={isAuthenticating || (mode === 'register' && usernameStatus !== 'available')}
            className="w-full bg-emerald-900 text-white font-black py-3.5 rounded-2xl transition-all active:scale-[0.98] mt-2 uppercase tracking-[0.2em] text-[10px] flex items-center justify-center gap-3 disabled:opacity-30 shadow-lg shadow-emerald-900/10"
          >
            {isAuthenticating ? <i className="fas fa-spinner fa-spin"></i> : <>{mode === 'login' ? t('login') : t('register')} <i className="fas fa-arrow-right text-[8px] opacity-40"></i></>}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl px-6 py-4 flex flex-col gap-4 z-10 shrink-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="flex justify-between items-center w-full content-limit">
          <div>
            <h1 className="text-2xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{t('fard')}</h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Spiritual Momentum</p>
          </div>
          <div className="flex bg-slate-100/50 dark:bg-slate-800 p-1 rounded-xl">
            <button onClick={() => setActiveTab('fard')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-sm' : 'text-slate-400'}`}>{t('fard')}</button>
            <button onClick={() => setActiveTab('sunnah')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-sm' : 'text-slate-400'}`}>{t('sunnah')}</button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-3 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-3">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p, idx) => {
            const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
            const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;
            const themes = ['emerald', 'teal', 'sky', 'blue', 'indigo', 'violet'];
            const theme = themes[idx % themes.length];

            return (
              <div 
                key={p} 
                onClick={() => !isExcused && handleToggle(p, activeTab)} 
                className={`card-premium !p-4 flex items-center justify-between btn-ripple border ${isDone ? `border-${theme}-200 bg-${theme}-50/5` : 'border-transparent dark:bg-slate-800'} ${isExcused ? 'opacity-30 grayscale' : ''}`}
              >
                <div className="flex items-center gap-4">
                  <div className={`w-11 h-11 rounded-xl flex items-center justify-center text-xl ${isDone ? `bg-gradient-to-br from-${theme}-500 to-${theme}-700 text-white shadow-lg` : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}`}>
                    <i className={`fas ${isDone ? 'fa-check-circle' : 'fa-kaaba'}`}></i>
                  </div>
                  <div>
                    <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-base tracking-tight">{t(p)}</h3>
                    {time && <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{time}</p>}
                  </div>
                </div>
                {isDone && <span className={`text-[8px] font-black text-${theme}-600 bg-${theme}-50 px-3 py-1 rounded-full uppercase tracking-widest`}>Done</span>}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState } from 'react';
import { UserData, PrayerTimings, HealthPeriod } from '../types';

interface WomensSpaceProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  toggleHayd: (active: boolean) => void;
  addHealthPeriod: (start: string, end: string | null) => void;
  removeHealthPeriod: (id: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const WomensSpace: React.FC<WomensSpaceProps> = ({ state, toggleHayd, addHealthPeriod, removeHealthPeriod, setCurrentView, t }) => {
  const [newStart, setNewStart] = useState(new Date().toISOString().split('T')[0]);
  const [newEnd, setNewEnd] = useState<string>('');
  const [showAdd, setShowAdd] = useState(false);

  const handleAdd = () => {
    if (!newStart) return;
    addHealthPeriod(newStart, newEnd || null);
    setShowAdd(false);
    setNewEnd('');
  };

  const recentPeriods = state.healthPeriods.slice(-2).reverse();

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] view-transition overflow-hidden">
      <div className="p-4 pt-10 pb-4 bg-emerald-900 text-white shrink-0 shadow-lg rounded-b-[32px]">
        <div className="flex items-center gap-3">
          <button onClick={() => setCurrentView('dashboard')} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-lg"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-lg font-black tracking-tight">{t('womensSpace')}</h1>
        </div>
      </div>

      <div className="flex-1 p-4 flex flex-col justify-around overflow-hidden">
        <div className={`p-4 rounded-2xl text-center border-2 transition-all ${state.isHaydNifas ? 'border-rose-100 bg-rose-50/30' : 'border-emerald-50 bg-white shadow-sm'} shrink-0`}>
          <div className={`w-12 h-12 mx-auto rounded-xl flex items-center justify-center mb-2 text-xl ${state.isHaydNifas ? 'bg-rose-500 text-white shadow-lg rotate-12' : 'bg-emerald-50 text-emerald-700'}`}><i className="fas fa-droplet"></i></div>
          <h2 className="text-xs font-black text-emerald-900 mb-1">{t('haydMode')}</h2>
          <button onClick={() => toggleHayd(!state.isHaydNifas)} className={`w-full py-2 rounded-xl font-black text-[8px] uppercase tracking-widest transition-all shadow-sm ${state.isHaydNifas ? 'bg-rose-500 text-white' : 'bg-[#064e3b] text-white'}`}>{state.isHaydNifas ? t('inactive') : t('active')}</button>
        </div>

        <div className="flex-1 flex flex-col justify-around overflow-hidden mt-2">
          <div className="flex items-center justify-between mb-1 shrink-0 px-1">
            <h3 className="text-[9px] font-black text-emerald-900 uppercase tracking-widest flex items-center gap-1"><i className="fas fa-history text-[10px] text-gold-classic"></i> Recent</h3>
            <button onClick={() => setShowAdd(!showAdd)} className="w-6 h-6 bg-emerald-50 text-emerald-700 rounded-full flex items-center justify-center border border-emerald-100 transition-all"><i className={`fas ${showAdd ? 'fa-times' : 'fa-plus'} text-[8px]`}></i></button>
          </div>

          <div className="flex-1 flex flex-col gap-1.5 overflow-hidden">
            {showAdd ? (
              <div className="bg-white p-3 rounded-2xl border border-emerald-50 shadow-lg animate-fade-up space-y-2 shrink-0">
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-0.5"><label className="text-[6px] font-black text-slate-400 uppercase tracking-widest ml-1">Start</label><input type="date" value={newStart} onChange={e => setNewStart(e.target.value)} className="w-full p-2 bg-slate-50 border border-slate-100 rounded-lg text-[9px] outline-none font-black" /></div>
                  <div className="space-y-0.5"><label className="text-[6px] font-black text-slate-400 uppercase tracking-widest ml-1">End</label><input type="date" value={newEnd} onChange={e => setNewEnd(e.target.value)} className="w-full p-2 bg-slate-50 border border-slate-100 rounded-lg text-[9px] outline-none font-black" /></div>
                </div>
                <button onClick={handleAdd} className="w-full py-2 bg-[#064e3b] text-white rounded-lg font-black text-[8px] uppercase tracking-widest shadow-md">Save</button>
              </div>
            ) : (
              recentPeriods.map(p => (
                <div key={p.id} className="bg-white p-2.5 rounded-xl border border-emerald-50 shadow-sm flex items-center justify-between shrink-0">
                  <div className="flex items-center gap-2"><div className="w-7 h-7 bg-rose-50 text-rose-500 rounded-lg flex items-center justify-center text-[9px]"><i className="fas fa-tint"></i></div><div><p className="text-[9px] font-black text-emerald-900 leading-none mb-0.5">{p.start.split('T')[0]}</p><p className="text-[7px] text-slate-400 uppercase font-black">Excused</p></div></div>
                  <button onClick={() => removeHealthPeriod(p.id)} className="w-6 h-6 text-rose-200"><i className="fas fa-trash text-[8px]"></i></button>
                </div>
              ))
            )}
            {!showAdd && recentPeriods.length === 0 && <div className="flex-1 border-2 border-dashed border-emerald-50 rounded-2xl flex items-center justify-center text-[8px] text-slate-300 font-black uppercase">No records</div>}
          </div>
        </div>

        <div className="bg-amber-50 p-3 rounded-2xl border border-amber-100 shrink-0 mt-2">
          <h3 className="font-black text-amber-800 text-[8px] mb-1 flex items-center gap-1"><i className="fas fa-circle-info text-[9px]"></i> Rules</h3>
          <ul className="space-y-1 text-[7px] text-amber-900/80 font-black">
            <li className="flex gap-1"><i className="fas fa-check-circle text-amber-500 mt-0.5"></i> <span>Prayer during periods are <b>exempted</b> and not made up.</span></li>
            <li className="flex gap-1"><i className="fas fa-exclamation-circle text-amber-500 mt-0.5"></i> <span>Ramadan fasts <b>must</b> be made up later (Qada).</span></li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default WomensSpace;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { UserData, QuranProgress, PrayerTimings } from '../types';
import { SURAHS } from '../constants';

interface QuranTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  onUpdate: (progress: QuranProgress) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QuranTracker: React.FC<QuranTrackerProps> = ({ state, onUpdate, setCurrentView, t }) => {
  const [surahInput, setSurahInput] = useState(state.quranProgress.surah || '');
  const [ayahInput, setAyahInput] = useState(state.quranProgress.ayah || '');
  const [juzInput, setJuzInput] = useState(state.quranProgress.juz || '');
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSurahs = useMemo(() => {
    if (!surahInput) return SURAHS.slice(0, 5);
    return SURAHS.filter(s => s.toLowerCase().includes(surahInput.toLowerCase())).slice(0, 5);
  }, [surahInput]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSave = () => {
    onUpdate({
      surah: surahInput,
      ayah: ayahInput,
      juz: juzInput,
      lastUpdated: new Date().toISOString()
    });
    if ('vibrate' in navigator) navigator.vibrate(40);
  };

  const inputClasses = "w-full p-3.5 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl focus:ring-4 focus:ring-amber-500/10 outline-none shadow-sm font-black text-emerald-900 dark:text-emerald-50 text-sm";
  const labelClasses = "text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-900 animate-fade-up">
      <div className="p-4 pt-10 pb-6 bg-gradient-to-br from-amber-600 to-amber-700 text-white shadow-xl rounded-b-[32px] z-20 shrink-0">
        <div className="flex items-center gap-3">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-xl border border-white/20 active:scale-90">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-xl font-black tracking-tight">{t('quran')}</h1>
            <p className="text-[9px] text-amber-200 font-black uppercase tracking-widest">Divine Journey</p>
          </div>
        </div>
      </div>

      <div className="flex-1 p-4 flex flex-col gap-5 overflow-y-auto">
        <div className="card-premium !p-5 text-center relative overflow-hidden bg-white dark:bg-slate-800 border-amber-50/50">
          <div className="absolute top-0 right-0 w-24 h-24 bg-amber-50 dark:bg-amber-900/10 rounded-full -mr-12 -mt-12 blur-2xl opacity-50"></div>
          <div className="w-12 h-12 bg-amber-50 dark:bg-amber-900/30 rounded-2xl flex items-center justify-center mx-auto mb-3 text-amber-600 text-xl shadow-md">
            <i className="fas fa-book-open"></i>
          </div>
          <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('lastRead')}</span>
          <h2 className="text-lg font-black text-emerald-950 dark:text-emerald-50 leading-tight">
            {state.quranProgress.surah ? `${state.quranProgress.surah}, ${t('ayah')} ${state.quranProgress.ayah}` : 'Not started'}
          </h2>
          {state.quranProgress.juz && <p className="text-[8px] font-black text-amber-600 mt-0.5 uppercase tracking-widest">{t('juz')} {state.quranProgress.juz}</p>}
        </div>

        <div className="space-y-4">
          <div className="space-y-1 relative" ref={dropdownRef}>
            <label className={labelClasses}>{t('surah')}</label>
            <input 
              type="text" 
              placeholder="e.g. Al-Baqarah"
              className={inputClasses}
              value={surahInput}
              onFocus={() => setShowDropdown(true)}
              onChange={(e) => { setSurahInput(e.target.value); setShowDropdown(true); }}
            />
            {showDropdown && filteredSurahs.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-50 dark:border-slate-700 p-1 z-50">
                {filteredSurahs.map(s => (
                  <button key={s} onClick={() => { setSurahInput(s); setShowDropdown(false); }} className="w-full text-left px-4 py-2 hover:bg-amber-50 dark:hover:bg-slate-700 rounded-lg text-xs font-black text-emerald-900 dark:text-emerald-50">{s}</button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className={labelClasses}>{t('juz')}</label>
              <input type="number" placeholder="1-30" className={inputClasses} value={juzInput} onChange={(e) => setJuzInput(e.target.value)} />
            </div>
            <div className="space-y-1">
              <label className={labelClasses}>{t('ayah')}</label>
              <input type="number" placeholder="Verse #" className={inputClasses} value={ayahInput} onChange={(e) => setAyahInput(e.target.value)} />
