          {/* Responsive Obligations Layout */}
          <div className="space-y-3">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] px-1">DAILY PATH</h3>
            <div className="flex md:grid md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 overflow-x-auto md:overflow-visible gap-2.5 pb-2 px-1 -mx-1 md:mx-0 md:px-0 no-scrollbar snap-x md:snap-none">
              {!inHaydToday && PRAYERS.map((p, idx) => {
                const status = todayLogs[p];
                const isDone = status === PrayerStatus.COMPLETED;
                const isUpcoming = prayerTimingData?.next.name === p;
                const prayerThemes = ['emerald', 'teal', 'sky', 'blue', 'indigo'];
                const theme = prayerThemes[idx % prayerThemes.length];

                return (
                  <div 
                    key={p} 
                    onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                    className={`min-w-[105px] md:min-w-0 snap-center p-3 rounded-[20px] border transition-all cursor-pointer flex flex-col gap-2 bg-white dark:bg-slate-800 shadow-sm ${isDone ? `border-${theme}-200 bg-${theme}-50/10` : isUpcoming ? 'border-amber-400 ring-2 ring-amber-500/5' : 'border-slate-100 dark:border-slate-700'}`}
                  >
                    <div className="flex items-center justify-between">
                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isDone ? `bg-${theme}-500 text-white shadow-md` : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}`}>
                        <i className={`fas ${isDone ? 'fa-check' : 'fa-moon'} text-[10px]`}></i>
                      </div>
                      {isUpcoming && <span className="w-1.5 h-1.5 rounded-full bg-amber-500"></span>}
                    </div>
                    <div>
                      <p className="font-black text-emerald-950 dark:text-emerald-50 capitalize text-[11px] tracking-tight truncate">{t(p)}</p>
                      <p className="text-[7px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}</p>
                    </div>
                  </div>
                );
              })}

              {/* Compact Fasting Card */}
              <div onClick={() => setCurrentView('fasting')} className={`min-w-[105px] md:min-w-0 snap-center p-3 rounded-[20px] border transition-all cursor-pointer flex flex-col gap-2 bg-white dark:bg-slate-800 shadow-sm ${fastingToday.status === 'completed' ? 'border-violet-200' : 'border-slate-100 dark:border-slate-700'}`}>
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${fastingToday.status === 'completed' ? 'bg-violet-500 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}`}>
                  <i className="fas fa-moon text-[10px]"></i>
                </div>
                <div>
                  <p className="font-black text-emerald-950 dark:text-emerald-50 text-[11px] tracking-tight">Fasting</p>
                  <p className="text-[7px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{fastingToday.status === 'completed' ? 'DONE' : 'LOG IT'}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Journey Map (Calendar) */}
          <div className="bg-white dark:bg-slate-800 p-6 rounded-[32px] shadow-sm border border-slate-100 dark:border-slate-700">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-1">JOURNEY MAP</h3>
                <h4 className="text-xl font-black text-emerald-950 dark:text-emerald-50 tracking-tight">{monthName}</h4>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() - 1, 1))} 
                  className="w-10 h-10 bg-slate-50 dark:bg-slate-700/50 rounded-xl flex items-center justify-center text-slate-400 hover:text-emerald-600 active:scale-95 transition-all"
                >
                  <i className="fas fa-chevron-left text-[10px]"></i>
                </button>
                <button 
                  onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() + 1, 1))} 
                  className="w-10 h-10 bg-slate-50 dark:bg-slate-700/50 rounded-xl flex items-center justify-center text-slate-400 hover:text-emerald-600 active:scale-95 transition-all"
                >
                  <i className="fas fa-chevron-right text-[10px]"></i>
                </button>
              </div>
            </div>

            <div className="grid grid-cols-7 gap-2.5">
              {['S','M','T','W','T','F','S'].map(d => (
                <div key={d} className="text-center text-[8px] font-black text-slate-300 dark:text-slate-600 pb-2 uppercase tracking-widest">{d}</div>
              ))}

              {calendarDays.map((dateStr, idx) => {
                if (!dateStr) return <div key={`empty-${idx}`} className="h-12" />;

                const isToday = dateStr === todayStr;
                const inHayd = isDateInHayd(dateStr);
                const dayNum = dateStr.split('-')[2];
                const logs = state.prayerLogs[dateStr];
                const fastingLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(dateStr))?.[1];

                return (
                  <button 
                    key={dateStr}
                    onClick={() => setCurrentView('qadah')}
                    className={`
                      relative h-14 rounded-2xl border flex flex-col items-center justify-between p-1.5 transition-all active:scale-90
                      ${isToday ? 'border-emerald-500 bg-emerald-50/20 dark:bg-emerald-900/10' : 
                        inHayd ? 'border-pink-100 dark:border-pink-900/30 bg-pink-50/30 dark:bg-pink-900/5' : 
                        'border-slate-50 dark:border-slate-700/50 bg-white dark:bg-slate-700/30'}
                    `}
                  >
                    <div className="flex justify-between w-full px-0.5">
                      <span className={`text-[9px] font-black ${isToday ? 'text-emerald-700' : inHayd ? 'text-pink-600' : 'text-slate-400'}`}>
                        {parseInt(dayNum)}
                      </span>
                      {fastingLog?.status === 'completed' && (
                        <i className="fas fa-moon text-[7px] text-amber-500"></i>
                      )}
                    </div>

                    {!inHayd && logs ? (
                      <div className="flex flex-wrap gap-0.5 justify-center w-full mb-1">
                        {PRAYERS.slice(0, 5).map(p => {
                          const status = logs[p as keyof typeof logs];
                          const color = status === 'completed' ? 'bg-emerald-500' : status === 'missed' ? 'bg-rose-500' : 'bg-slate-100 dark:bg-slate-600';
                          return <div key={p} className={`w-1 h-1 rounded-full ${color}`}></div>;
                        })}
                      </div>
                    ) : inHayd ? (
                      <i className="fas fa-leaf text-[8px] text-pink-300 mb-1"></i>
                    ) : (
                      <div className="h-1"></div>
                    )}
                  </button>
                );
              })}
            </div>

            <button 
              onClick={() => setCurrentView('qadah')}
              className="w-full mt-6 py-3.5 bg-slate-50 dark:bg-slate-700/40 text-slate-500 dark:text-slate-400 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em] flex items-center justify-center gap-2 hover:bg-emerald-50 hover:text-emerald-600 transition-all"
            >
              Open Worship Calendar
              <i className="fas fa-arrow-right text-[8px] opacity-40"></i>
            </button>
          </div>

        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';
import Logo from './Logo';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
  initialMode?: 'login' | 'register';
  onBack?: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users, initialMode = 'login', onBack }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setMode(initialMode);
  }, [initialMode]);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  const usernameStatus = useMemo(() => {
    if (mode === 'login' || usernameNormalized.length < 3) return 'idle';
    return users[usernameNormalized] ? 'taken' : 'available';
  }, [usernameNormalized, mode, users]);

  const suggestions = useMemo(() => {
    if (usernameStatus !== 'taken') return [];
    const base = usernameNormalized;
    return [
      `${base}${Math.floor(Math.random() * 99) + 1}`,
      `${base}_i`,
      `${base}786`
    ].filter(s => !users[s.toLowerCase()]);
  }, [usernameStatus, usernameNormalized, users]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password) return "Password is required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (usernameStatus === 'taken') return t('usernameTaken');
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setIsAuthenticating(true);
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "User not found." : "Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const inputClasses = "w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl focus:ring-4 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-black text-emerald-900 dark:text-emerald-50 placeholder:text-slate-300 text-sm";
  const labelClasses = "block text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-900 w-full overflow-hidden animate-fade-in">
      {onBack && (
        <header className="px-6 py-4 flex items-center z-10 shrink-0">
          <button onClick={onBack} className="w-9 h-9 bg-emerald-50 dark:bg-slate-800 rounded-xl flex items-center justify-center text-emerald-900 dark:text-emerald-500 border border-emerald-100 dark:border-slate-700 active:scale-90 transition-all">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
        </header>
      )}

      <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col items-center">
        <div className="flex flex-col items-center mb-6 shrink-0">
          <Logo size="md" className="mb-3" />
          <h1 className="text-2xl font-black text-emerald-900 dark:text-emerald-50 mb-0.5 tracking-tighter">Ibadathi</h1>
          <p className="text-[7px] font-black text-emerald-800/40 dark:text-emerald-400/30 uppercase tracking-[0.3em]">Sacred Companion</p>
        </div>

        <div className="flex bg-emerald-50/50 dark:bg-slate-800/50 p-1 rounded-2xl mb-6 w-full max-w-[240px] shrink-0 border border-emerald-100/50 dark:border-slate-700">
          <button 
            type="button"
            onClick={() => { setMode('login'); setError(null); }}
            className={`flex-1 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-md' : 'text-emerald-900/40 dark:text-slate-500'}`}
          >
            {t('login')}
          </button>
          <button 
            type="button"
            onClick={() => { setMode('register'); setError(null); }}
            className={`flex-1 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-md' : 'text-emerald-900/40 dark:text-slate-500'}`}
          >
            {t('register')}
          </button>
        </div>

        <form onSubmit={handleSubmit} className="w-full max-w-[320px] space-y-3.5 flex flex-col pb-10">
          {error && (
            <div className="bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 p-3 rounded-xl text-[10px] font-black text-center border border-rose-100 dark:border-rose-900/30 animate-shake">
              <i className="fas fa-exclamation-circle mr-1.5"></i> {error}
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>{t('username')}</label>
            <div className="relative">
              <input 
                type="text" 
                className={`${inputClasses} ${usernameStatus === 'taken' ? 'border-rose-300' : usernameStatus === 'available' ? 'border-emerald-400' : ''}`}
                placeholder="username"
                value={formData.username}
                onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})}
                required
              />
              <div className="absolute right-4 top-1/2 -translate-y-1/2">
                {usernameStatus === 'available' && <i className="fas fa-check-circle text-emerald-500 text-xs"></i>}
                {usernameStatus === 'taken' && <i className="fas fa-times-circle text-rose-500 text-xs"></i>}
              </div>
            </div>
            {usernameStatus === 'taken' && mode === 'register' && (
              <div className="bg-rose-50/50 dark:bg-rose-950/10 p-2 rounded-xl border border-rose-100/50 dark:border-rose-900/20 mt-1">
                <p className="text-[7px] font-black text-rose-800/50 uppercase tracking-widest mb-1">{t('suggestions')}</p>
                <div className="flex flex-wrap gap-1">
                  {suggestions.map(s => (
                    <button 
                      key={s} 
                      type="button"
                      onClick={() => setFormData({...formData, username: s})}
                      className="bg-white dark:bg-slate-700 px-2 py-1 rounded-lg text-[8px] font-black text-rose-900 dark:text-rose-200 border border-rose-100 dark:border-rose-900 shadow-sm"
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {mode === 'register' && (
            <div className="space-y-3.5 animate-fade-in">
              <div className="space-y-1">
                <label className={labelClasses}>{t('name')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Your Name"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <label className={labelClasses}>{t('age')}</label>
                  <input 
                    type="number"
                    className={inputClasses}
                    placeholder="25"
                    value={formData.age}
                    onChange={e => setFormData({...formData, age: e.target.value})}
                    required
                  />
                </div>
                <div className="space-y-1">
                  <label className={labelClasses}>{t('sex')}</label>
                  <select 
                    className={inputClasses}
                    value={formData.sex}
                    onChange={e => setFormData({...formData, sex: e.target.value as 'male' | 'female'})}
                  >
                    <option value="male" className="font-black">{t('male')}</option>
                    <option value="female" className="font-black">{t('female')}</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className={labelClasses}>{t('place')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Makkah"
                  value={formData.place}
                  onChange={e => setFormData({...formData, place: e.target.value})}
                  required
                />
              </div>
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>{t('password')}</label>
            <input 
              type="password"
              className={inputClasses}
              placeholder="••••••••"
              value={formData.password}
              onChange={e => setFormData({...formData, password: e.target.value})}
              required
            />
          </div>

          <button 
            type="submit"
            disabled={isAuthenticating || (mode === 'register' && usernameStatus !== 'available')}
            className="w-full bg-emerald-900 text-white font-black py-3.5 rounded-2xl transition-all active:scale-[0.98] mt-2 uppercase tracking-[0.2em] text-[10px] flex items-center justify-center gap-3 disabled:opacity-30 shadow-lg shadow-emerald-900/10"
          >
            {isAuthenticating ? <i className="fas fa-spinner fa-spin"></i> : <>{mode === 'login' ? t('login') : t('register')} <i className="fas fa-arrow-right text-[8px] opacity-40"></i></>}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleNotifications: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleNotifications }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 1;
    let levelKey = 'levelBeginner', colorClass = 'text-slate-500', bgClass = 'from-slate-400 to-slate-500', icon = 'fa-seedling';
    if (ratio >= 0.9) { levelKey = 'levelElite'; colorClass = 'text-amber-500'; bgClass = 'from-amber-400 to-amber-600'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { levelKey = 'levelAdvanced'; colorClass = 'text-emerald-600'; bgClass = 'from-emerald-500 to-emerald-700'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { levelKey = 'levelConsistent'; colorClass = 'text-teal-600'; bgClass = 'from-teal-500 to-teal-700'; icon = 'fa-leaf'; }
    return { completedFard, levelKey, colorClass, bgClass, ratio, icon };
  }, [state]);

  const isDark = state.settings.theme === 'dark';
  const notificationsEnabled = state.settings.notificationsEnabled;

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl px-6 py-6 flex items-center gap-4 shrink-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-14 h-14 bg-gradient-to-br from-emerald-800 to-teal-950 rounded-2xl flex items-center justify-center text-white shadow-lg">
           <i className="fas fa-user-circle text-2xl"></i>
        </div>
        <div>
          <h1 className="text-xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{state.profile.name}</h1>
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">@{state.profile.username}</p>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-6 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-6">
          {/* Rank Card */}
          <div className="card-premium p-6 flex flex-col items-center text-center">
             <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl mb-3 bg-gradient-to-br ${stats.bgClass} text-white shadow-lg`}>
               <i className={`fas ${stats.icon}`}></i>
             </div>
