import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl px-6 py-4 flex flex-col gap-4 z-10 shrink-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="flex justify-between items-center w-full content-limit">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-600 p-2 rounded-xl text-white shadow-md">
              <i className="fas fa-kaaba"></i>
            </div>
            <div>
              <h1 className="text-xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{t('fard')}</h1>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Spiritual Momentum</p>
            </div>
          </div>
          <div className="flex bg-slate-100/50 dark:bg-slate-800 p-1 rounded-xl">
            <button onClick={() => setActiveTab('fard')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-sm' : 'text-slate-400'}`}>{t('fard')}</button>
            <button onClick={() => setActiveTab('sunnah')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-sm' : 'text-slate-400'}`}>{t('sunnah')}</button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-3 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-3">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p, idx) => {
            const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
            const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;
            const themes = ['emerald', 'teal', 'sky', 'blue', 'indigo', 'violet'];
            const theme = themes[idx % themes.length];

            return (
              <div 
                key={p} 
                onClick={() => !isExcused && handleToggle(p, activeTab)} 
                className={`card-premium !p-4 flex items-center justify-between btn-ripple border ${isDone ? `border-${theme}-200 bg-${theme}-50/5` : 'border-transparent dark:bg-slate-800'} ${isExcused ? 'opacity-30 grayscale' : ''}`}
              >
                <div className="flex items-center gap-4">
                  <div className={`w-11 h-11 rounded-xl flex items-center justify-center text-xl ${isDone ? `bg-gradient-to-br from-${theme}-500 to-${theme}-700 text-white shadow-lg` : 'bg-slate-100 dark:bg-slate-700 text-slate-300'}`}>
                    <i className={`fas ${isDone ? 'fa-check-circle' : 'fa-kaaba'}`}></i>
                  </div>
                  <div>
                    <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-base tracking-tight">{t(p)}</h3>
                    {time && <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{time}</p>}
                  </div>
                </div>
                {isDone && <span className={`text-[9px] font-black text-${theme}-600 bg-${theme}-50 px-3 py-1 rounded-full uppercase tracking-widest`}>Done</span>}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleNotifications: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleNotifications }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 1;
    let levelKey = 'levelBeginner', colorClass = 'text-slate-500', bgClass = 'from-slate-400 to-slate-500', icon = 'fa-seedling';
    if (ratio >= 0.9) { levelKey = 'levelElite'; colorClass = 'text-amber-500'; bgClass = 'from-amber-400 to-amber-600'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { levelKey = 'levelAdvanced'; colorClass = 'text-emerald-600'; bgClass = 'from-emerald-500 to-emerald-700'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { levelKey = 'levelConsistent'; colorClass = 'text-teal-600'; bgClass = 'from-teal-500 to-teal-700'; icon = 'fa-leaf'; }
    return { completedFard, levelKey, colorClass, bgClass, ratio, icon };
  }, [state]);

  const isDark = state.settings.theme === 'dark';
  const notificationsEnabled = state.settings.notificationsEnabled;

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl px-6 py-8 flex items-center gap-4 shrink-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-14 h-14 bg-emerald-600 rounded-2xl shadow-xl flex items-center justify-center text-white text-2xl">
           <i className="fas fa-user"></i>
        </div>
        <div>
          <h1 className="text-2xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{state.profile.name}</h1>
          <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">@{state.profile.username}</p>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-6 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-6">
          {/* Rank Card */}
          <div className="card-premium p-6 flex flex-col items-center text-center">
             <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl mb-3 bg-gradient-to-br ${stats.bgClass} text-white shadow-lg`}>
               <i className={`fas ${stats.icon}`}></i>
             </div>
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('consistency')}</span>
             <h3 className={`text-2xl font-black ${stats.colorClass} tracking-tighter mb-4`}>{t(stats.levelKey)}</h3>
             <div className="w-full bg-slate-100 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                <div className="bg-emerald-500 h-full rounded-full transition-all duration-1000" style={{ width: `${stats.ratio * 100}%` }}></div>
             </div>
          </div>

          {/* Settings Section */}
          <div className="space-y-2">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Preferences</h3>

            <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between p-4 bg-white dark:bg-slate-800 border">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${isDark ? 'bg-slate-700 text-amber-400' : 'bg-amber-50 text-amber-600'}`}>
                  <i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i>
                </div>
                <span className="font-black text-emerald-950 dark:text-emerald-50 text-sm tracking-tight">{isDark ? 'Dark Mode' : 'Light Mode'}</span>
              </div>
            </button>

            <button onClick={toggleNotifications} className="card-premium w-full flex items-center justify-between p-4 bg-white dark:bg-slate-800 border">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${notificationsEnabled ? 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                  <i className={`fas ${notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'}`}></i>
                </div>
                <span className="font-black text-emerald-950 dark:text-emerald-50 text-sm tracking-tight">{notificationsEnabled ? t('notificationOn') : t('notificationOff')}</span>
              </div>
            </button>

            <button onClick={onLogout} className="card-premium w-full flex items-center gap-3 p-4 bg-rose-50 border-rose-100 dark:bg-rose-900/10 dark:border-rose-900/20 mt-4">
              <div className="w-10 h-10 bg-rose-100 dark:bg-rose-900/30 text-rose-600 rounded-xl flex items-center justify-center">
                <i className="fas fa-power-off text-sm"></i>
