import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';
import Logo from './Logo';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl px-6 py-5 flex flex-col gap-5 z-10 shrink-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="flex justify-between items-center w-full content-limit">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-50 dark:bg-emerald-900/30 p-2 rounded-2xl shadow-sm border border-emerald-100 dark:border-emerald-800">
              <Logo size="sm" />
            </div>
            <div>
              <h1 className="text-xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{t('fard')}</h1>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Spiritual Momentum</p>
            </div>
          </div>
          <div className="flex bg-slate-100/50 dark:bg-slate-800 p-1.5 rounded-[18px] border border-slate-200/50 dark:border-slate-700">
            <button onClick={() => setActiveTab('fard')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-md scale-[1.05]' : 'text-slate-400'}`}>{t('fard')}</button>
            <button onClick={() => setActiveTab('sunnah')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white dark:bg-slate-700 text-emerald-900 dark:text-emerald-50 shadow-md scale-[1.05]' : 'text-slate-400'}`}>{t('sunnah')}</button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-6 space-y-4 w-full flex flex-col items-center no-scrollbar">
        <div className="w-full content-limit space-y-4 pb-24">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p, idx) => {
            const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
            const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;

            // Vibrant theme mapping
            const colorThemes: Record<string, string> = {
              fajr: 'emerald', dhuhr: 'amber', asr: 'sky', maghrib: 'teal', isha: 'indigo', witr: 'violet',
              'Fajr Sunnah': 'emerald', 'Dhuhr Before': 'amber', 'Dhuhr After': 'amber', 'Maghrib Sunnah': 'teal', 'Isha Sunnah': 'indigo'
            };
            const theme = colorThemes[p] || 'slate';

            return (
              <div 
                key={p} 
                onClick={() => !isExcused && handleToggle(p, activeTab)} 
                className={`card-premium !p-5 flex items-center justify-between btn-ripple border-2 transition-all group animate-fade-up ${
                  isDone 
                    ? `border-${theme}-100 bg-${theme}-50/30 dark:bg-${theme}-900/10` 
                    : 'border-white dark:border-slate-800'
                } ${isExcused ? 'opacity-30 grayscale' : ''}`}
                style={{ animationDelay: `${idx * 0.05}s` }}
              >
                <div className="flex items-center gap-5">
                  <div className={`w-14 h-14 rounded-[24px] flex items-center justify-center text-2xl transition-all ${
                    isDone 
                      ? `bg-gradient-to-br from-${theme}-500 to-${theme}-600 text-white shadow-[0_10px_20px_-5px_rgba(0,0,0,0.15)]` 
                      : 'bg-slate-50 dark:bg-slate-800 text-slate-300 dark:text-slate-600'
                  }`}>
                    <i className={`fas ${isDone ? 'fa-check-circle' : 'fa-kaaba'}`}></i>
                  </div>
                  <div>
                    <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-lg tracking-tight leading-none mb-1.5">{t(p)}</h3>
                    <div className="flex items-center gap-2">
                       {time && <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{time}</p>}
                       {isDone && <span className="w-1 h-1 bg-slate-200 rounded-full"></span>}
                       {isDone && <span className={`text-[8px] font-black text-${theme}-600 dark:text-${theme}-400 uppercase tracking-widest`}>Completed</span>}
                    </div>
                  </div>
                </div>
                {!isDone && !isExcused && (
                  <div className="w-10 h-10 rounded-full border border-slate-100 dark:border-slate-800 flex items-center justify-center text-slate-200 group-hover:border-emerald-200 group-hover:text-emerald-300 transition-all">
                    <i className="fas fa-plus text-[10px]"></i>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';
import Logo from './Logo';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleNotifications: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleNotifications }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;
    let levelKey = 'levelBeginner', colorClass = 'text-slate-500', bgClass = 'from-slate-400 to-slate-500', icon = 'fa-seedling';
    if (ratio >= 0.9) { levelKey = 'levelElite'; colorClass = 'text-amber-500'; bgClass = 'from-amber-400 to-amber-600'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { levelKey = 'levelAdvanced'; colorClass = 'text-emerald-600'; bgClass = 'from-emerald-500 to-emerald-700'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { levelKey = 'levelConsistent'; colorClass = 'text-teal-600'; bgClass = 'from-teal-500 to-teal-700'; icon = 'fa-leaf'; }
    return { completedFard, levelKey, colorClass, bgClass, ratio, icon };
  }, [state]);

  const isDark = state.settings.theme === 'dark';
  const notificationsEnabled = state.settings.notificationsEnabled;

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
