        <div>
          <h1 className="text-2xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter leading-none mb-1.5">{state.profile.name}</h1>
          <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">@{state.profile.username}</p>
        </div>
      </header>

      <div className="scroll-container px-4 pt-6 space-y-8 w-full flex flex-col items-center pb-24 no-scrollbar">
        <div className="w-full content-limit space-y-8">
          {/* Rank Card */}
          <div className="card-premium p-8 flex flex-col items-center text-center relative overflow-hidden group">
             <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50/50 dark:bg-emerald-900/10 rounded-full -mr-16 -mt-16 blur-3xl opacity-50"></div>

             <div className={`w-20 h-20 rounded-[32px] flex items-center justify-center text-4xl mb-4 bg-gradient-to-br ${stats.bgClass} text-white shadow-xl group-hover:scale-110 transition-transform`}>
               <i className={`fas ${stats.icon}`}></i>
             </div>
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-2">{t('consistency')}</span>
             <h3 className={`text-3xl font-black ${stats.colorClass} tracking-tighter mb-5`}>{t(stats.levelKey)}</h3>

