import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
  initialMode?: 'login' | 'register';
  onBack?: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users, initialMode = 'login', onBack }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setMode(initialMode);
  }, [initialMode]);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  const validate = () => {
    if (!usernameNormalized) return "Username is required.";
    if (!formData.password) return "Password is required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name is required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age is required.";
      if (!formData.place.trim()) return "Place/Location is required.";
      if (users[usernameNormalized]) return t('usernameTaken');
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setIsAuthenticating(true);
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "User not found." : "Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const inputClasses = "w-full px-5 py-4 bg-white dark:bg-slate-800 border-2 border-slate-50 dark:border-slate-700 rounded-[24px] focus:ring-4 focus:ring-emerald-600/5 focus:border-emerald-200 outline-none shadow-sm transition-all font-black text-emerald-950 dark:text-emerald-50 placeholder:text-slate-200 text-sm";
  const labelClasses = "block text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] ml-2 mb-2";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-900 w-full overflow-hidden animate-fade-in relative">
      {/* Background decoration */}
      <div className="absolute top-[-5%] left-[-5%] w-64 h-64 bg-emerald-50/30 rounded-full blur-3xl pointer-events-none"></div>

      {onBack && (
        <header className="px-6 py-6 flex items-center z-10 shrink-0">
          <button onClick={onBack} className="w-11 h-11 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center text-emerald-900 dark:text-emerald-500 border border-slate-100 dark:border-slate-700 shadow-sm active:scale-90 transition-all">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
        </header>
      )}

      <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col items-center no-scrollbar">
        <div className="flex flex-col items-center mb-10 shrink-0 animate-fade-up">
          <h1 className="arabic-font text-6xl font-black text-emerald-950 dark:text-emerald-50 mb-2 tracking-tight" dir="rtl">عبادتي</h1>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Sacred Companion</p>
        </div>

        <div className="flex bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded-[24px] mb-8 w-full max-w-[280px] shrink-0 border border-slate-100 dark:border-slate-700 shadow-inner">
          <button 
            type="button"
            onClick={() => { setMode('login'); setError(null); }}
            className={`flex-1 py-3 rounded-[20px] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-lg scale-[1.05]' : 'text-slate-400'}`}
          >
            {t('login')}
          </button>
          <button 
            type="button"
            onClick={() => { setMode('register'); setError(null); }}
            className={`flex-1 py-3 rounded-[20px] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-lg scale-[1.05]' : 'text-slate-400'}`}
          >
            {t('register')}
          </button>
        </div>

        <form onSubmit={handleSubmit} className="w-full max-w-[340px] space-y-5 flex flex-col pb-20 animate-fade-up">
          {error && (
            <div className="bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 p-4 rounded-2xl text-[10px] font-black text-center border border-rose-100 dark:border-rose-900/30 shadow-sm">
              <i className="fas fa-exclamation-circle mr-2"></i> {error}
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>{t('username')}</label>
            <input 
              type="text" 
              className={inputClasses}
              placeholder="e.g. seeker123"
              value={formData.username}
              onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})}
              required
            />
          </div>

          {mode === 'register' && (
            <div className="space-y-5 animate-fade-in">
              <div className="space-y-1">
                <label className={labelClasses}>{t('name')}</label>
                <input 
                  type="text"
                  className={inputClasses}
                  placeholder="Full Name"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>{t('password')}</label>
            <input 
              type="password"
              className={inputClasses}
              placeholder="••••••••"
              value={formData.password}
              onChange={e => setFormData({...formData, password: e.target.value})}
              required
            />
          </div>

          <button 
            type="submit"
            disabled={isAuthenticating}
            className="w-full bg-emerald-900 text-white font-black py-5 rounded-[24px] transition-all active:scale-[0.98] mt-4 uppercase tracking-[0.3em] text-xs flex items-center justify-center gap-3 disabled:opacity-30 shadow-xl shadow-emerald-900/20 border-b-4 border-emerald-950"
          >
            {isAuthenticating ? <i className="fas fa-spinner fa-spin"></i> : <>{mode === 'login' ? t('login') : t('register')} <i className="fas fa-arrow-right text-[8px] opacity-40"></i></>}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData, FastingLog } from '../types';
import { PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const prayerLogsToday = state.prayerLogs[todayStr] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  const salawatChallenge = state.activeChallenges.find(c => c.id === 'salawat') || state.activeChallenges[0] || null;

  const obligations = useMemo(() => {
    const items = [];

    // 1. Fard Prayers Obligation
    if (!state.isHaydNifas) {
      const doneCount = PRAYERS.filter(p => prayerLogsToday[p] === PrayerStatus.COMPLETED).length;
      items.push({
        id: 'fard',
        title: t('fard'),
        subtitle: `${doneCount}/5 Done`,
        icon: 'fa-kaaba',
        status: doneCount === 5 ? 'completed' : 'pending',
        action: () => setCurrentView('prayer'),
        urgent: prayerTimingData?.next.name === 'fajr' || prayerTimingData?.next.name === 'maghrib'
      });
    }

    // 2. Salawat/Dhikr Obligation
    if (salawatChallenge) {
      const isDone = salawatChallenge.current >= salawatChallenge.target;
      items.push({
        id: 'salawat',
        title: t(salawatChallenge.title),
        subtitle: `${salawatChallenge.current}/${salawatChallenge.target}`,
        icon: 'fa-heart',
        status: isDone ? 'completed' : 'pending',
        action: () => setCurrentView('challenges'),
        urgent: !isDone && salawatChallenge.current < salawatChallenge.target / 2
      });
    }

    // 3. Fasting Obligation
    if (!state.isHaydNifas) {
      const fastingLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(todayStr))?.[1] as FastingLog | undefined;
      const isDone = fastingLog?.status === 'completed';
      items.push({
        id: 'fasting',
        title: t('fasting'),
        subtitle: isDone ? 'Completed' : 'Not Logged',
        icon: 'fa-moon',
        status: isDone ? 'completed' : 'pending',
        action: () => setCurrentView('fasting'),
        urgent: false
      });
    }

    // 4. Qada Obligation
    // Explicitly typing acc as number to avoid 'unknown' inference
    const missedTotal = Object.values(state.prayerLogs).reduce((acc: number, log) => {
      return acc + Object.values(log).filter(s => s === PrayerStatus.MISSED).length;
    }, 0);
    if (missedTotal > 0) {
      items.push({
        id: 'qadah',
        title: t('qadah'),
        subtitle: `${missedTotal} Pending`,
        icon: 'fa-calendar-check',
        status: 'pending',
        action: () => setCurrentView('qadah'),
        urgent: missedTotal > 10
      });
    }

    return items;
  }, [state, prayerLogsToday, salawatChallenge, t, todayStr, prayerTimingData]);

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden w-full">
      {/* Modern Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl px-4 py-4 z-20 w-full flex justify-center sticky top-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex flex-col">
            <h1 className="text-lg font-black text-slate-900 dark:text-emerald-50 leading-tight">Salam,</h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{state.profile.name}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setCurrentView('qibla')} className="w-10 h-10 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-blue-600 dark:text-blue-400 border border-slate-100 dark:border-slate-700 shadow-sm active:scale-90 transition-transform"><i className="fas fa-compass"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-10 h-10 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-emerald-500 dark:text-emerald-400 border border-slate-100 dark:border-slate-700 shadow-sm active:scale-90 transition-transform"><i className="fas fa-sparkles"></i></button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-8 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-8">

          {/* Polished Hero Banner with Blue-Green Gradient */}
          <div className="bg-gradient-to-br from-blue-700 via-teal-800 to-emerald-900 p-6 rounded-[32px] text-white relative overflow-hidden shadow-2xl animate-fade-up">
            <div className="absolute top-0 right-0 w-64 h-64 bg-blue-400/10 rounded-full -mr-32 -mt-32 blur-[80px]"></div>
            <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-400/5 rounded-full -ml-24 -mb-24 blur-[60px]"></div>

            <div className="relative z-10 flex items-center justify-between">
              <div className="space-y-1.5">
                <span className="text-[9px] font-black text-blue-200 uppercase tracking-[0.4em]">UP NEXT</span>
                <h2 className="text-4xl font-black capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <div className="flex items-center gap-2">
                   <i className="far fa-clock text-[10px] text-emerald-300/60"></i>
                   <p className="text-emerald-100/70 text-xs font-black tracking-widest">{prayerTimingData?.next.time}</p>
                </div>
              </div>
              <div className="text-right bg-white/10 backdrop-blur-xl p-5 rounded-[24px] border border-white/20 shadow-inner">
                <p className="text-3xl font-black tabular-nums tracking-tighter text-blue-200 leading-none mb-1">{prayerTimingData?.timeLeft}</p>
                <p className="text-[8px] font-black text-emerald-400/60 uppercase tracking-widest">REMAINING</p>
              </div>
            </div>

            <div className="relative mt-6 space-y-2">
              <div className="w-full bg-black/20 h-2.5 rounded-full overflow-hidden p-0.5">
                 <div className="bg-gradient-to-r from-blue-400 to-emerald-300 h-full rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(52,211,153,0.5)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
              </div>
              <div className="flex justify-between px-1">
                 <span className="text-[8px] font-black text-blue-300/60 uppercase tracking-widest">{prayerTimingData?.activeName}</span>
                 <span className="text-[8px] font-black text-emerald-300/60 uppercase tracking-widest">{prayerTimingData?.next.name}</span>
              </div>
            </div>
          </div>

          {/* Today's Obligations - Horizontal Card Layout */}
          <div className="space-y-4 animate-fade-up" style={{ animationDelay: '0.1s' }}>
            <div className="flex items-center justify-between px-2">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Today's Obligations</h3>
               <div className="h-[1px] flex-1 bg-slate-100 mx-4"></div>
            </div>

            <div className="flex overflow-x-auto pb-4 gap-4 no-scrollbar -mx-4 px-4 snap-x">
              {obligations.map((item, idx) => (
                <button
                  key={item.id}
                  onClick={item.action}
                  className={`flex-none w-[160px] snap-start card-premium dark:bg-slate-800 p-5 border-2 transition-all relative overflow-hidden flex flex-col justify-between h-[160px] group active:scale-95 ${item.urgent ? 'border-amber-400/50 shadow-lg ring-4 ring-amber-400/5' : item.status === 'completed' ? 'border-emerald-100 bg-emerald-50/10' : 'border-transparent'}`}
                >
                  <div className="flex justify-between items-start">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg shadow-sm transition-transform group-hover:scale-110 ${item.status === 'completed' ? 'bg-emerald-500 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                      <i className={`fas ${item.icon}`}></i>
                    </div>
                    <div className={`w-2.5 h-2.5 rounded-full ${item.status === 'completed' ? 'bg-emerald-500' : 'bg-rose-500'} animate-pulse`}></div>
                  </div>

                  <div className="text-left">
                    <h4 className="font-black text-slate-900 dark:text-emerald-50 uppercase text-[10px] tracking-widest leading-tight mb-1">{item.title}</h4>
                    <p className={`font-black text-[12px] tabular-nums ${item.status === 'completed' ? 'text-emerald-600' : 'text-slate-400'}`}>{item.subtitle}</p>
                  </div>

                  {item.urgent && (
                    <div className="absolute bottom-0 right-0 p-2 opacity-10">
                      <i className="fas fa-bolt text-3xl"></i>
                    </div>
                  )}
                </button>
              ))}

              {/* Encouragement Card if almost all are done */}
              {obligations.every(o => o.status === 'completed') && obligations.length > 0 && (
                <div className="flex-none w-[160px] snap-start card-premium bg-gradient-to-br from-emerald-500 to-teal-700 p-5 flex flex-col justify-center items-center text-center text-white border-transparent">
                   <i className="fas fa-check-circle text-3xl mb-3"></i>
                   <p className="text-[10px] font-black uppercase tracking-widest">Alhamdulillah!</p>
                   <p className="text-[8px] font-bold opacity-80 mt-1">All obligations met</p>
                </div>
              )}
            </div>
          </div>

          {/* Quick Trackers - Refined Grid */}
          <div className="grid grid-cols-2 gap-4 animate-fade-up" style={{ animationDelay: '0.2s' }}>
            <div onClick={() => setCurrentView('quran')} className="card-premium p-5 flex flex-col justify-between h-32 cursor-pointer group active:scale-[0.98] transition-all relative overflow-hidden bg-white dark:bg-slate-800">
               <div className="absolute top-0 right-0 w-16 h-16 bg-blue-50/50 rounded-full -mr-8 -mt-8 blur-xl"></div>
               <div className="w-10 h-10 rounded-2xl bg-blue-50 dark:bg-blue-900/30 text-blue-600 flex items-center justify-center group-hover:scale-110 transition-transform relative z-10">
                 <i className="fas fa-book-open text-sm"></i>
               </div>
               <div className="relative z-10">
                 <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('quran')}</p>
                 <h4 className="text-sm font-black text-slate-900 dark:text-emerald-50 truncate">{state.quranProgress.surah || 'Tap to Track'}</h4>
               </div>
            </div>
            <div onClick={() => setCurrentView('account')} className="card-premium p-5 flex flex-col justify-between h-32 cursor-pointer group active:scale-[0.98] transition-all relative overflow-hidden bg-white dark:bg-slate-800">
               <div className="absolute top-0 right-0 w-16 h-16 bg-emerald-50/50 rounded-full -mr-8 -mt-8 blur-xl"></div>
               <div className="w-10 h-10 rounded-2xl bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 flex items-center justify-center group-hover:scale-110 transition-transform relative z-10">
                 <i className="fas fa-gear text-sm"></i>
               </div>
               <div className="relative z-10">
                 <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Preferences</p>
                 <h4 className="text-sm font-black text-slate-900 dark:text-emerald-50 truncate">My Account</h4>
               </div>
            </div>
          </div>

          {/* Persistence Note */}
          <div className="text-center opacity-20 pb-12">
            <p className="text-[7px] font-black uppercase tracking-[0.4em]">Spiritually Rooted • Digitally Connected</p>
          </div>
        </div>
      </div>
    </div>
  );
};

