import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData, FastingLog } from '../types';
import { PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const prayerLogsToday = state.prayerLogs[todayStr] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  const salawatChallenge = state.activeChallenges.find(c => c.id === 'salawat') || state.activeChallenges[0] || null;

  const obligations = useMemo(() => {
    const items = [];

    // 1. Fard Prayers Obligation
    if (!state.isHaydNifas) {
      const doneCount = PRAYERS.filter(p => prayerLogsToday[p] === PrayerStatus.COMPLETED).length;
      items.push({
        id: 'fard',
        title: t('fard'),
        subtitle: `${doneCount}/5 Done`,
        icon: 'fa-kaaba',
        status: doneCount === 5 ? 'completed' : 'pending',
        action: () => setCurrentView('prayer'),
        urgent: prayerTimingData?.next.name === 'fajr' || prayerTimingData?.next.name === 'maghrib'
      });
    }

    // 2. Salawat/Dhikr Obligation
    if (salawatChallenge) {
      const isDone = salawatChallenge.current >= salawatChallenge.target;
      items.push({
        id: 'salawat',
        title: t(salawatChallenge.title),
        subtitle: `${salawatChallenge.current}/${salawatChallenge.target}`,
        icon: 'fa-heart',
        status: isDone ? 'completed' : 'pending',
        action: () => setCurrentView('challenges'),
        urgent: !isDone && salawatChallenge.current < salawatChallenge.target / 2
      });
    }

    // 3. Fasting Obligation
    if (!state.isHaydNifas) {
      const fastingLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(todayStr))?.[1] as FastingLog | undefined;
      const isDone = fastingLog?.status === 'completed';
      items.push({
        id: 'fasting',
        title: t('fasting'),
        subtitle: isDone ? 'Completed' : 'Not Logged',
        icon: 'fa-moon',
        status: isDone ? 'completed' : 'pending',
        action: () => setCurrentView('fasting'),
        urgent: false
      });
    }

    // 4. Qada Obligation
    // Fix: Explicitly type the result and callback arguments to ensure missedTotal is correctly inferred as number
    const missedTotal: number = Object.values(state.prayerLogs).reduce((acc: number, log: any) => {
      const logValues = Object.values(log) as PrayerStatus[];
      return acc + logValues.filter(s => s === PrayerStatus.MISSED).length;
    }, 0);
    if (missedTotal > 0) {
      items.push({
        id: 'qadah',
        title: t('qadah'),
        subtitle: `${missedTotal} Pending`,
        icon: 'fa-calendar-check',
        status: 'pending',
        action: () => setCurrentView('qadah'),
        urgent: missedTotal > 10
      });
    }

    return items;
  }, [state, prayerLogsToday, salawatChallenge, t, todayStr, prayerTimingData]);

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden w-full">
      {/* Modern Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl px-4 py-4 z-20 w-full flex justify-center sticky top-0 border-b border-slate-100/50 dark:border-slate-800/50">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex flex-col">
            <h1 className="text-lg font-black text-slate-900 dark:text-emerald-50 leading-tight">Salam,</h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{state.profile.name}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setCurrentView('qibla')} className="w-10 h-10 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-blue-600 dark:text-blue-400 border border-slate-100 dark:border-slate-700 shadow-sm active:scale-90 transition-transform"><i className="fas fa-compass"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-10 h-10 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-emerald-500 dark:text-emerald-400 border border-slate-100 dark:border-slate-700 shadow-sm active:scale-90 transition-transform"><i className="fas fa-sparkles"></i></button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-4 pt-4 space-y-8 w-full flex flex-col items-center">
        <div className="w-full content-limit space-y-8">

          {/* Polished Hero Banner with Blue-Green Gradient */}
          <div className="bg-gradient-to-br from-blue-700 via-teal-800 to-emerald-900 p-6 rounded-[32px] text-white relative overflow-hidden shadow-2xl animate-fade-up">
            <div className="absolute top-0 right-0 w-64 h-64 bg-blue-400/10 rounded-full -mr-32 -mt-32 blur-[80px]"></div>
            <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-400/5 rounded-full -ml-24 -mb-24 blur-[60px]"></div>

            <div className="relative z-10 flex items-center justify-between">
              <div className="space-y-1.5">
                <span className="text-[9px] font-black text-blue-200 uppercase tracking-[0.4em]">UP NEXT</span>
                <h2 className="text-4xl font-black capitalize tracking-tight">{prayerTimingData ? t(prayerTimingData.next.name) : '---'}</h2>
                <div className="flex items-center gap-2">
                   <i className="far fa-clock text-[10px] text-emerald-300/60"></i>
                   <p className="text-emerald-100/70 text-xs font-black tracking-widest">{prayerTimingData?.next.time}</p>
                </div>
              </div>
              <div className="text-right bg-white/10 backdrop-blur-xl p-5 rounded-[24px] border border-white/20 shadow-inner">
                <p className="text-3xl font-black tabular-nums tracking-tighter text-blue-200 leading-none mb-1">{prayerTimingData?.timeLeft}</p>
                <p className="text-[8px] font-black text-emerald-400/60 uppercase tracking-widest">REMAINING</p>
              </div>
            </div>

            <div className="relative mt-6 space-y-2">
              <div className="w-full bg-black/20 h-2.5 rounded-full overflow-hidden p-0.5">
                 <div className="bg-gradient-to-r from-blue-400 to-emerald-300 h-full rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(52,211,153,0.5)]" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
              </div>
              <div className="flex justify-between px-1">
                 <span className="text-[8px] font-black text-blue-300/60 uppercase tracking-widest">{prayerTimingData?.activeName}</span>
                 <span className="text-[8px] font-black text-emerald-300/60 uppercase tracking-widest">{prayerTimingData?.next.name}</span>
              </div>
            </div>
          </div>

          {/* Today's Obligations - Horizontal Card Layout */}
          <div className="space-y-4 animate-fade-up" style={{ animationDelay: '0.1s' }}>
            <div className="flex items-center justify-between px-2">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Today's Obligations</h3>
               <div className="h-[1px] flex-1 bg-slate-100 mx-4"></div>
            </div>

            <div className="flex overflow-x-auto pb-4 gap-4 no-scrollbar -mx-4 px-4 snap-x">
              {obligations.map((item, idx) => (
                <button
                  key={item.id}
                  onClick={item.action}
                  className={`flex-none w-[160px] snap-start card-premium dark:bg-slate-800 p-5 border-2 transition-all relative overflow-hidden flex flex-col justify-between h-[160px] group active:scale-95 ${item.urgent ? 'border-amber-400/50 shadow-lg ring-4 ring-amber-400/5' : item.status === 'completed' ? 'border-emerald-100 bg-emerald-50/10' : 'border-transparent'}`}
                >
                  <div className="flex justify-between items-start">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg shadow-sm transition-transform group-hover:scale-110 ${item.status === 'completed' ? 'bg-emerald-500 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                      <i className={`fas ${item.icon}`}></i>
                    </div>
                    <div className={`w-2.5 h-2.5 rounded-full ${item.status === 'completed' ? 'bg-emerald-500' : 'bg-rose-500'} animate-pulse`}></div>
                  </div>

                  <div className="text-left">
                    <h4 className="font-black text-slate-900 dark:text-emerald-50 uppercase text-[10px] tracking-widest leading-tight mb-1">{item.title}</h4>
                    <p className={`font-black text-[12px] tabular-nums ${item.status === 'completed' ? 'text-emerald-600' : 'text-slate-400'}`}>{item.subtitle}</p>
                  </div>

                  {item.urgent && (
                    <div className="absolute bottom-0 right-0 p-2 opacity-10">
                      <i className="fas fa-bolt text-3xl"></i>
                    </div>
                  )}
                </button>
              ))}

              {/* Encouragement Card if almost all are done */}
              {obligations.every(o => o.status === 'completed') && obligations.length > 0 && (
                <div className="flex-none w-[160px] snap-start card-premium bg-gradient-to-br from-emerald-500 to-teal-700 p-5 flex flex-col justify-center items-center text-center text-white border-transparent">
