          {/* Quick Trackers - Refined Grid */}
          <div className="grid grid-cols-2 gap-4 animate-fade-up" style={{ animationDelay: '0.2s' }}>
            <div onClick={() => setCurrentView('quran')} className="card-premium p-5 flex flex-col justify-between h-32 cursor-pointer group active:scale-[0.98] transition-all relative overflow-hidden bg-white dark:bg-slate-800">
               <div className="absolute top-0 right-0 w-16 h-16 bg-blue-50/50 rounded-full -mr-8 -mt-8 blur-xl"></div>
