            <div onClick={() => setCurrentView('account')} className="card-premium p-5 flex flex-col justify-between h-32 cursor-pointer group active:scale-[0.98] transition-all relative overflow-hidden bg-white dark:bg-slate-800">
               <div className="absolute top-0 right-0 w-16 h-16 bg-emerald-50/50 rounded-full -mr-8 -mt-8 blur-xl"></div>
               <div className="w-10 h-10 rounded-2xl bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 flex items-center justify-center group-hover:scale-110 transition-transform relative z-10">
                 <i className="fas fa-gear text-sm"></i>
               </div>
               <div className="relative z-10">
                 <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Preferences</p>
                 <h4 className="text-sm font-black text-slate-900 dark:text-emerald-50 truncate">My Account</h4>
               </div>
            </div>
          </div>

          {/* Persistence Note */}
          <div className="text-center opacity-20 pb-12">
            <p className="text-[7px] font-black uppercase tracking-[0.4em]">Spiritually Rooted • Digitally Connected</p>
          </div>
        </div>
      </div>
    </div>
  );
};

