import React, { useMemo, useState, useEffect } from 'react';
import { Language, PrayerTimings, PrayerStatus, UserData, FastingLog, PrayerLog } from '../types';
import { PRAYERS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleNotifications: () => void;
  updatePrayerStatus: (date: string, prayer: typeof PRAYERS[number], status: PrayerStatus) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, onLogout, toggleNotifications, updatePrayerStatus }) => {
  const [currentTimeMinutes, setCurrentTimeMinutes] = useState<number>(() => {
    const now = new Date();
    return now.getHours() * 60 + now.getMinutes();
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTimeMinutes(now.getHours() * 60 + now.getMinutes());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toISOString().split('T')[0];
  const prayerLogsToday = state.prayerLogs[todayStr] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };

  const prayerTimingData = useMemo(() => {
    if (!state.todayTimings) return null;
    const timingsMinutes = PRAYERS.map(p => {
      const pKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![pKey].split(':').map(Number);
      return { name: p, total: h * 60 + m, time: state.todayTimings![pKey] };
    });
    let nextIndex = timingsMinutes.findIndex(p => p.total > currentTimeMinutes);
    let prevIndex, isTomorrow = false;
    if (nextIndex === -1) { nextIndex = 0; prevIndex = timingsMinutes.length - 1; isTomorrow = true; }
    else { prevIndex = nextIndex === 0 ? timingsMinutes.length - 1 : nextIndex - 1; }
    const next = timingsMinutes[nextIndex], prev = timingsMinutes[prevIndex];
    const nextTotal = isTomorrow ? next.total + 1440 : next.total;
    const prevTotal = (nextIndex === 0 && !isTomorrow) ? prev.total - 1440 : prev.total;
    const diff = nextTotal - currentTimeMinutes;
    const progress = Math.max(0, Math.min(100, ((currentTimeMinutes - prevTotal) / (nextTotal - prevTotal)) * 100));
    return { next, timeLeft: `${Math.floor(diff / 60)}h ${diff % 60}m`, progress, activeName: prev.name };
  }, [state.todayTimings, currentTimeMinutes]);

  const salawatChallenge = state.activeChallenges.find(c => c.id === 'salawat') || state.activeChallenges[0] || null;

  const obligations = useMemo(() => {
    const items = [];
    if (!state.isHaydNifas) {
      const doneCount = PRAYERS.filter(p => prayerLogsToday[p] === PrayerStatus.COMPLETED).length;
      items.push({
        id: 'fard',
        title: t('fard'),
        subtitle: `${doneCount}/5`,
        icon: 'fa-kaaba',
        status: doneCount === 5 ? 'completed' : 'pending',
        action: () => setCurrentView('prayer'),
        urgent: prayerTimingData?.next.name === 'fajr'
      });
    }
    if (salawatChallenge) {
      const isDone = salawatChallenge.current >= salawatChallenge.target;
      items.push({
        id: 'salawat',
        title: 'Dhikr',
        subtitle: `${salawatChallenge.current}/${salawatChallenge.target}`,
        icon: 'fa-heart',
        status: isDone ? 'completed' : 'pending',
        action: () => setCurrentView('challenges'),
        urgent: false
      });
    }
    if (!state.isHaydNifas) {
      const fastingLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(todayStr))?.[1] as FastingLog | undefined;
      const isDone = fastingLog?.status === 'completed';
      items.push({
        id: 'fasting',
        title: t('fasting'),
        subtitle: isDone ? 'Log' : 'No',
        icon: 'fa-moon',
        status: isDone ? 'completed' : 'pending',
        action: () => setCurrentView('fasting'),
        urgent: false
      });
    }
    const missedTotal: number = Object.values(state.prayerLogs).reduce<number>((acc: number, log: PrayerLog) => {
      const logValues = Object.values(log) as PrayerStatus[];
      return acc + logValues.filter((s: PrayerStatus) => s === PrayerStatus.MISSED).length;
    }, 0);
    if (missedTotal > 0) {
      items.push({
        id: 'qadah',
        title: t('qadah'),
        subtitle: missedTotal,
        icon: 'fa-calendar-check',
        status: 'pending',
        action: () => setCurrentView('qadah'),
        urgent: missedTotal > 15
      });
    }
    return items;
  }, [state, prayerLogsToday, salawatChallenge, t, todayStr, prayerTimingData]);

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden w-full">
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl px-4 py-2 z-20 w-full flex justify-center sticky top-0 border-b border-slate-100 dark:border-slate-800 shrink-0">
        <div className="w-full content-limit flex justify-between items-center">
          <div className="flex flex-col">
            <h1 className="text-sm font-black text-slate-900 dark:text-emerald-50 leading-tight">Salam, {state.profile.name.split(' ')[0]}</h1>
            <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Worship Companion</p>
          </div>
          <div className="flex gap-1.5">
            <button onClick={() => setCurrentView('qibla')} className="w-8 h-8 bg-white dark:bg-slate-800 rounded-lg flex items-center justify-center text-blue-600 text-xs border border-slate-100 dark:border-slate-700 active:scale-90 transition-transform"><i className="fas fa-compass"></i></button>
            <button onClick={() => setCurrentView('about')} className="w-8 h-8 bg-white dark:bg-slate-800 rounded-lg flex items-center justify-center text-emerald-500 text-xs border border-slate-100 dark:border-slate-700 active:scale-90 transition-transform"><i className="fas fa-sparkles"></i></button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-3 pt-3 space-y-4 w-full flex flex-col items-center pb-20 no-scrollbar">
        <div className="w-full content-limit space-y-4">

          {/* Compact Hero Banner */}
          <div className="bg-gradient-to-br from-blue-700 via-teal-800 to-emerald-900 p-4 rounded-2xl text-white relative overflow-hidden shadow-lg animate-fade-up">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-400/5 rounded-full -mr-16 -mt-16 blur-3xl"></div>

            <div className="relative z-10 flex items-center justify-between">
              <div className="space-y-0.5">
                <span className="text-[8px] font-black text-blue-200 uppercase tracking-[0.2em]">NEXT: {prayerTimingData ? t(prayerTimingData.next.name) : '---'}</span>
                <div className="flex items-baseline gap-2">
                   <p className="text-2xl font-black tabular-nums tracking-tighter">{prayerTimingData?.timeLeft}</p>
                   <p className="text-[10px] font-black text-emerald-300/80 uppercase tracking-widest">Left</p>
                </div>
              </div>
              <div className="text-right glass-morphism p-2 rounded-xl border border-white/10">
                <p className="text-xs font-black text-blue-100 leading-none">{prayerTimingData?.next.time}</p>
              </div>
            </div>

            <div className="relative mt-3">
              <div className="w-full bg-black/20 h-1.5 rounded-full overflow-hidden">
                 <div className="bg-emerald-400 h-full transition-all duration-1000" style={{ width: `${prayerTimingData?.progress || 0}%` }}></div>
              </div>
            </div>
          </div>

          {/* Obligations - Compact horizontal scroll */}
          <div className="space-y-2 animate-fade-up">
            <h3 className="text-[8px] font-black text-slate-400 uppercase tracking-widest px-1">Active Obligations</h3>
            <div className="flex overflow-x-auto gap-2 no-scrollbar -mx-3 px-3">
              {obligations.map((item) => (
                <button
                  key={item.id}
                  onClick={item.action}
                  className={`flex-none w-28 card-premium flex flex-col gap-2 relative overflow-hidden border-2 ${item.urgent ? 'border-amber-400/30' : 'border-transparent'}`}
                >
                  <div className="flex justify-between items-center">
                    <div className={`w-7 h-7 rounded-lg flex items-center justify-center text-xs ${item.status === 'completed' ? 'bg-emerald-500 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                      <i className={`fas ${item.icon}`}></i>
                    </div>
                    {item.status === 'completed' && <i className="fas fa-check-circle text-[8px] text-emerald-500"></i>}
                  </div>
                  <div>
                    <h4 className="font-black text-slate-900 dark:text-emerald-50 uppercase text-[8px] tracking-tight truncate">{item.title}</h4>
                    <p className="font-black text-[10px] text-slate-400 tabular-nums">{item.subtitle}</p>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Quick Stats Grid */}
          <div className="grid grid-cols-2 gap-2.5 animate-fade-up">
            <div onClick={() => setCurrentView('quran')} className="card-premium h-20 flex flex-col justify-between cursor-pointer group active:scale-[0.98]">
               <div className="flex justify-between items-start">
                 <div className="w-7 h-7 rounded-lg bg-blue-50 dark:bg-blue-900/30 text-blue-600 flex items-center justify-center text-xs">
                   <i className="fas fa-book-open"></i>
                 </div>
                 <i className="fas fa-arrow-right text-[8px] text-slate-200"></i>
               </div>
               <div>
                 <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest mb-0.5">{t('quran')}</p>
                 <h4 className="text-[10px] font-black text-slate-900 dark:text-emerald-50 truncate">{state.quranProgress.surah || 'Log Start'}</h4>
               </div>
            </div>
            <div onClick={() => setCurrentView('fasting')} className="card-premium h-20 flex flex-col justify-between cursor-pointer group active:scale-[0.98]">
               <div className="flex justify-between items-start">
                 <div className="w-7 h-7 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 flex items-center justify-center text-xs">
                   <i className="fas fa-moon"></i>
                 </div>
                 <i className="fas fa-arrow-right text-[8px] text-slate-200"></i>
               </div>
               <div>
                 <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest mb-0.5">{t('fasting')}</p>
                 <h4 className="text-[10px] font-black text-slate-900 dark:text-emerald-50 truncate">Tracker</h4>
               </div>
            </div>
          </div>

          {/* Bottom Note */}
          <div className="text-center opacity-30 pt-4">
            <p className="text-[7px] font-black uppercase tracking-[0.2em]">Efficiency & Devotion</p>
          </div>
        </div>
      </div>
    </div>
  );
};

