import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const status = fardLogs[prayer] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED;
      updatePrayerStatus(today, prayer, status);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-gradient-to-r from-blue-900 to-emerald-900 px-4 py-3 flex flex-col gap-3 z-10 shrink-0 border-b border-white/5">
        <div className="flex justify-between items-center w-full content-limit">
          <div className="flex flex-col">
            <h1 className="text-sm font-black text-white tracking-tight">{t('fard')}</h1>
            <p className="text-[7px] font-black text-blue-200/50 uppercase tracking-widest">Daily Schedule</p>
          </div>
          <div className="flex bg-black/20 p-1 rounded-lg border border-white/10">
            <button onClick={() => setActiveTab('fard')} className={`px-4 py-1.5 rounded-md text-[8px] font-black uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white text-blue-900 shadow-sm' : 'text-white/40'}`}>{t('fard')}</button>
            <button onClick={() => setActiveTab('sunnah')} className={`px-4 py-1.5 rounded-md text-[8px] font-black uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white text-blue-900 shadow-sm' : 'text-white/40'}`}>{t('sunnah')}</button>
          </div>
        </div>
      </header>

      <div className="scroll-container px-3 pt-3 space-y-2 w-full flex flex-col items-center pb-20 no-scrollbar">
        <div className="w-full content-limit space-y-1.5 pb-10">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p, idx) => {
            const isDone = activeTab === 'fard' ? fardLogs[p as any] === PrayerStatus.COMPLETED : sunnahLogs.includes(p);
            const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;

            return (
              <button 
                key={p} 
                onClick={() => !isExcused && handleToggle(p, activeTab)} 
                className={`card-premium !p-3.5 flex items-center justify-between border transition-all animate-fade-up ${
                  isDone 
                    ? `border-emerald-100 dark:border-emerald-900/30 bg-emerald-50/20` 
                    : 'border-white dark:border-slate-800'
                } ${isExcused ? 'opacity-30' : ''}`}
                style={{ animationDelay: `${idx * 0.03}s` }}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-base transition-all ${
                    isDone 
                      ? `bg-emerald-500 text-white shadow-sm` 
                      : 'bg-slate-50 dark:bg-slate-800 text-slate-300'
                  }`}>
                    <i className={`fas ${isDone ? 'fa-check' : 'fa-kaaba'}`}></i>
                  </div>
                  <div className="text-left">
                    <h3 className="font-black text-slate-900 dark:text-emerald-50 text-xs tracking-tight">{t(p)}</h3>
                    <div className="flex items-center gap-1.5">
                       {time && <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{time}</p>}
                       {isDone && <span className="text-[7px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest">• Done</span>}
                    </div>
                  </div>
                </div>
                {!isDone && !isExcused && (
                  <div className="w-7 h-7 rounded-lg border border-slate-100 dark:border-slate-800 flex items-center justify-center text-slate-200">
                    <i className="fas fa-plus text-[8px]"></i>
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState, useMemo } from 'react';
import { UserData, DhikrChallenge, PersonalDhikr, PrayerTimings } from '../types';

interface DhikrCounterProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateProgress: (id: string, delta: number) => void;
  updatePersonalProgress: (id: string, delta: number) => void;
  addPersonalDhikr: (name: string) => void;
  resetPersonalSession: (id: string) => void;
  deletePersonalDhikr: (id: string) => void;
  archiveChallenge: (id: string) => void;
  setActiveDhikr: (id: string | null) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const DhikrCounter: React.FC<DhikrCounterProps> = ({ 
  state, updateProgress, updatePersonalProgress, addPersonalDhikr, resetPersonalSession, deletePersonalDhikr, archiveChallenge, setActiveDhikr, setCurrentView, t 
}) => {
  const [activeTab, setActiveTab] = useState<'challenges' | 'personal'>('challenges');
  const [tapAnimation, setTapAnimation] = useState(false);
  const [isAddingDhikr, setIsAddingDhikr] = useState(false);
  const [newDhikrName, setNewDhikrName] = useState('');
  const [activePersonalId, setActivePersonalId] = useState<string | null>(null);

  const activeChallenge = useMemo(() => state.activeChallenges.find(c => c.id === state.activeDhikrId), [state.activeChallenges, state.activeDhikrId]);
  const activePersonal = useMemo(() => state.personalDhikrs.find(d => d.id === activePersonalId), [state.personalDhikrs, activePersonalId]);

  const handleIncrement = (id: string, isPersonal: boolean) => {
    if ('vibrate' in navigator) navigator.vibrate(40);
    setTapAnimation(true); setTimeout(() => setTapAnimation(false), 100);
    if (isPersonal) updatePersonalProgress(id, 1);
    else updateProgress(id, 1);
  };

  if (activeChallenge || activePersonal) {
    const title = activeChallenge ? t(activeChallenge.title) : activePersonal?.name;
    const current = activeChallenge ? activeChallenge.current : activePersonal?.sessionCount;
    const arabic = activeChallenge ? activeChallenge.arabic : '';
    const id = activeChallenge ? activeChallenge.id : activePersonal!.id;
    const isPers = !!activePersonal;

    return (
      <div className="h-full flex flex-col bg-[#020617] text-white animate-fade-in">
        <header className="p-4 flex items-center justify-between z-10">
          <button onClick={() => { setActiveDhikr(null); setActivePersonalId(null); }} className="w-9 h-9 glass-morphism rounded-xl flex items-center justify-center border border-white/10"><i className="fas fa-arrow-left text-xs"></i></button>
          <div className="text-right">
             <span className="text-[7px] font-black text-white/30 uppercase tracking-widest">Reciting</span>
             <p className="text-xs font-black truncate max-w-[120px]">{title}</p>
          </div>
        </header>

        <div className="flex-1 flex flex-col items-center justify-center gap-10">
          <div className="text-center px-4">
            <p className="arabic-font text-5xl font-black mb-4 drop-shadow-xl" dir="rtl">{arabic}</p>
            <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest opacity-60">{title}</p>
          </div>

          <button 
            onClick={() => handleIncrement(id, isPers)} 
            className={`w-56 h-56 rounded-[50px] bg-white text-slate-950 flex flex-col items-center justify-center shadow-2xl transition-all duration-150 ${tapAnimation ? 'scale-90 opacity-80' : 'active:scale-95'}`}
          >
             <span className="text-8xl font-black tabular-nums tracking-tighter">{current}</span>
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-2">Tap to count</span>
          </button>

          {activeChallenge && activeChallenge.current >= activeChallenge.target && (
             <button onClick={() => archiveChallenge(id)} className="px-8 py-3 bg-emerald-600 rounded-full font-black text-[10px] uppercase tracking-widest shadow-lg animate-pulse">Archive Success</button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-gradient-to-r from-blue-900 to-emerald-900 p-4 pt-8 pb-4 flex justify-between items-center z-10 shadow-md">
        <h1 className="text-lg font-black text-white tracking-tight">Remembrance</h1>
        <div className="flex bg-black/20 p-1 rounded-xl">
          <button onClick={() => setActiveTab('challenges')} className={`px-4 py-1.5 rounded-lg text-[8px] font-black uppercase transition-all ${activeTab === 'challenges' ? 'bg-white text-blue-900' : 'text-white/40'}`}>Daily</button>
          <button onClick={() => setActiveTab('personal')} className={`px-4 py-1.5 rounded-lg text-[8px] font-black uppercase transition-all ${activeTab === 'personal' ? 'bg-white text-blue-900' : 'text-white/40'}`}>Custom</button>
        </div>
      </header>

      <div className="scroll-container px-3 pt-4 space-y-2 pb-20 no-scrollbar">
        {activeTab === 'challenges' ? (
          state.activeChallenges.map((c, idx) => {
            const perc = Math.min(100, (c.current / c.target) * 100);
            return (
              <div 
                key={c.id} 
                onClick={() => setActiveDhikr(c.id)} 
                className="card-premium !p-3 group cursor-pointer flex flex-col gap-2 transition-all hover:bg-slate-50 dark:hover:bg-slate-800/50 border-transparent hover:border-slate-100"
              >
                <div className="flex justify-between items-center">
                  <div className="overflow-hidden">
                    <h3 className="font-black text-slate-950 dark:text-emerald-50 uppercase text-[10px] tracking-tight">{t(c.title)}</h3>
                    <p className="arabic-font text-xs text-slate-400 truncate" dir="rtl">{c.arabic}</p>
                  </div>
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs ${perc === 100 ? 'bg-emerald-500 text-white' : 'bg-slate-50 dark:bg-slate-700 text-slate-300'}`}>
                    <i className="fas fa-play"></i>
                  </div>
                </div>
                <div className="w-full bg-slate-100 dark:bg-slate-800 h-1 rounded-full overflow-hidden">
                   <div className="bg-emerald-500 h-full transition-all duration-700" style={{ width: `${perc}%` }}></div>
                </div>
              </div>
            );
          })
        ) : (
          <div className="space-y-2">
            <button onClick={() => setIsAddingDhikr(true)} className="w-full py-6 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-800 text-slate-400 flex flex-col items-center gap-1 transition-all active:scale-95">
              <i className="fas fa-plus text-xs"></i>
              <span className="font-black text-[8px] uppercase tracking-widest">New Recitation</span>
            </button>
            {state.personalDhikrs.map(d => (
              <div key={d.id} onClick={() => setActivePersonalId(d.id)} className="card-premium !p-3 flex items-center justify-between group cursor-pointer">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 bg-blue-500 text-white rounded-lg flex items-center justify-center text-xs shadow-sm"><i className="fas fa-moon"></i></div>
                  <div>
                    <h3 className="font-black text-slate-900 dark:text-white text-[10px] uppercase tracking-tight">{d.name}</h3>
                    <p className="text-[7px] font-black text-slate-400 uppercase">Total: {d.totalCount}</p>
                  </div>
                </div>
                <i className="fas fa-chevron-right text-slate-200 text-[8px]"></i>
              </div>
            ))}
          </div>
        )}
      </div>

      {isAddingDhikr && (
        <div className="absolute inset-0 z-[110] bg-slate-950/60 backdrop-blur-md flex items-center justify-center p-6">
          <div className="w-full max-w-[300px] bg-white dark:bg-slate-900 rounded-[24px] p-6 shadow-2xl space-y-4 animate-fade-up">
            <h2 className="text-sm font-black text-slate-950 dark:text-white text-center uppercase tracking-widest">New Entry</h2>
            <input 
              type="text" 
              placeholder="Remembrance Name" 
              value={newDhikrName} 
              onChange={e => setNewDhikrName(e.target.value)} 
              className="w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl outline-none font-black text-xs text-slate-900 dark:text-white" 
            />
            <div className="flex gap-2">
               <button onClick={() => setIsAddingDhikr(false)} className="flex-1 py-2 text-slate-400 font-black uppercase text-[8px] tracking-widest">Close</button>
               <button onClick={() => { addPersonalDhikr(newDhikrName); setIsAddingDhikr(false); setNewDhikrName(''); }} className="flex-1 py-3 bg-emerald-600 text-white rounded-xl font-black uppercase text-[8px] tracking-widest shadow-md">Create</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DhikrCounter;

import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
  initialMode?: 'login' | 'register';
  onBack?: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users, initialMode = 'login', onBack }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setMode(initialMode);
  }, [initialMode]);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  const validate = () => {
    if (!usernameNormalized) return "Username required.";
    if (!formData.password) return "Password required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name required.";
      if (!formData.age) return "Age required.";
      if (!formData.place.trim()) return "Place required.";
      if (users[usernameNormalized]) return "Taken.";
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setIsAuthenticating(true);
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "No user." : "Wrong pw.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age) || 0,
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 600);
  };

  const inputClasses = "w-full px-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-emerald-500/10 outline-none transition-all font-bold text-slate-900 dark:text-emerald-50 text-xs";
  const labelClasses = "block text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-900 w-full overflow-hidden animate-fade-in">
      <header className="px-4 py-4 flex items-center justify-between shrink-0">
        <button onClick={onBack} className="w-8 h-8 bg-white dark:bg-slate-800 rounded-lg flex items-center justify-center border border-slate-100 dark:border-slate-700 active:scale-90"><i className="fas fa-chevron-left text-[10px]"></i></button>
        <h1 className="arabic-font text-3xl font-black text-emerald-950 dark:text-emerald-50 tracking-tight" dir="rtl">عبادتي</h1>
      </header>

      <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col items-center no-scrollbar">
        <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl mb-6 w-full max-w-[240px] shrink-0 border border-slate-200/50">
          <button onClick={() => setMode('login')} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-900 text-white shadow-sm' : 'text-slate-400'}`}>Login</button>
          <button onClick={() => setMode('register')} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-900 text-white shadow-sm' : 'text-slate-400'}`}>Join</button>
        </div>

        <form onSubmit={handleSubmit} className="w-full max-w-[280px] space-y-3.5 flex flex-col animate-fade-up">
          {error && <div className="bg-rose-50 text-rose-600 p-2.5 rounded-lg text-[9px] font-black text-center border border-rose-100">{error}</div>}

          <div className="space-y-0.5">
            <label className={labelClasses}>User</label>
            <input type="text" className={inputClasses} value={formData.username} onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/\s/g, '')})} required />
          </div>

          {mode === 'register' && (
            <div className="space-y-3.5 animate-fade-in">
              <div className="space-y-0.5">
                <label className={labelClasses}>Full Name</label>
                <input type="text" className={inputClasses} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required />
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div className="space-y-0.5">
                  <label className={labelClasses}>Age</label>
                  <input type="number" className={inputClasses} value={formData.age} onChange={e => setFormData({...formData, age: e.target.value})} required />
                </div>
                <div className="space-y-0.5">
                  <label className={labelClasses}>Place</label>
                  <input type="text" className={inputClasses} value={formData.place} onChange={e => setFormData({...formData, place: e.target.value})} required />
                </div>
              </div>
            </div>
          )}

          <div className="space-y-0.5">
            <label className={labelClasses}>Password</label>
            <input type="password" className={inputClasses} value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} required />
          </div>

          <button 
            type="submit"
            disabled={isAuthenticating}
            className="w-full bg-emerald-900 text-white font-black py-3.5 rounded-xl transition-all active:scale-95 mt-2 uppercase tracking-widest text-[10px] flex items-center justify-center gap-2 disabled:opacity-30 shadow-md"
          >
            {isAuthenticating ? <i className="fas fa-spinner fa-spin"></i> : <>{mode === 'login' ? 'Login' : 'Create'} <i className="fas fa-arrow-right text-[7px] opacity-40"></i></>}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleNotifications: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleNotifications }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;
    let levelKey = 'levelBeginner', bgClass = 'from-slate-400 to-slate-500', icon = 'fa-seedling';
    if (ratio >= 0.9) { levelKey = 'levelElite'; bgClass = 'from-amber-400 to-amber-600'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { levelKey = 'levelAdvanced'; bgClass = 'from-emerald-500 to-emerald-700'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { levelKey = 'levelConsistent'; bgClass = 'from-teal-500 to-teal-700'; icon = 'fa-leaf'; }
    return { levelKey, bgClass, ratio, icon };
  }, [state]);

  const isDark = state.settings.theme === 'dark';
  const notificationsEnabled = state.settings.notificationsEnabled;

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-900 overflow-hidden">
      <header className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl px-4 py-6 flex flex-col shrink-0 border-b border-slate-100 dark:border-slate-800">
        <h1 className="text-xl font-black text-emerald-950 dark:text-emerald-50 tracking-tight leading-none mb-1">{state.profile.name}</h1>
        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">@{state.profile.username}</p>
      </header>

      <div className="scroll-container px-3 pt-4 space-y-6 w-full flex flex-col items-center pb-24 no-scrollbar">
        <div className="w-full content-limit space-y-6">
          {/* Compact Rank Card */}
          <div className="card-premium p-6 flex flex-col items-center text-center relative overflow-hidden">
             <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl mb-3 bg-gradient-to-br ${stats.bgClass} text-white shadow-md`}>
               <i className={`fas ${stats.icon}`}></i>
             </div>
             <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest mb-1">Consistency Level</span>
             <h3 className="text-xl font-black text-emerald-900 dark:text-emerald-100 tracking-tight mb-4">{t(stats.levelKey)}</h3>

             <div className="w-full space-y-1.5">
               <div className="w-full bg-slate-50 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden border border-slate-100 dark:border-slate-700">
                  <div className="bg-emerald-500 h-full transition-all duration-1000" style={{ width: `${stats.ratio * 100}%` }}></div>
               </div>
               <div className="flex justify-between px-1">
                 <span className="text-[7px] font-black text-slate-300 uppercase">Start</span>
                 <span className="text-[7px] font-black text-emerald-400 uppercase">Max</span>
               </div>
             </div>
          </div>

          <div className="space-y-2">
            <h3 className="text-[8px] font-black text-slate-300 dark:text-slate-600 uppercase tracking-widest ml-1">Settings</h3>

            <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between p-3.5">
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm ${isDark ? 'bg-slate-700 text-amber-400' : 'bg-amber-50 text-amber-600'}`}>
                  <i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i>
                </div>
                <span className="font-black text-emerald-950 dark:text-emerald-50 text-xs tracking-tight">Dark Mode</span>
              </div>
              <div className={`w-9 h-5 rounded-full p-1 transition-colors ${isDark ? 'bg-emerald-600' : 'bg-slate-200'}`}>
                <div className={`w-3 h-3 bg-white rounded-full shadow-sm transition-transform ${isDark ? 'translate-x-4' : 'translate-x-0'}`}></div>
              </div>
            </button>

            <button onClick={toggleNotifications} className="card-premium w-full flex items-center justify-between p-3.5">
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm ${notificationsEnabled ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-400'}`}>
                  <i className={`fas ${notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'}`}></i>
                </div>
                <span className="font-black text-emerald-950 dark:text-emerald-50 text-xs tracking-tight">Alerts</span>
              </div>
              <div className={`w-9 h-5 rounded-full p-1 transition-colors ${notificationsEnabled ? 'bg-emerald-600' : 'bg-slate-200'}`}>
                <div className={`w-3 h-3 bg-white rounded-full shadow-sm transition-transform ${notificationsEnabled ? 'translate-x-4' : 'translate-x-0'}`}></div>
              </div>
            </button>

            <button onClick={onLogout} className="card-premium w-full flex items-center gap-3 p-3.5 bg-rose-50 border-rose-100 dark:bg-rose-900/10 dark:border-rose-900/20 mt-4 active:scale-95 transition-all">
              <div className="w-8 h-8 bg-rose-100 dark:bg-rose-900/30 text-rose-600 rounded-lg flex items-center justify-center text-xs">
                <i className="fas fa-power-off"></i>
              </div>
              <span className="font-black text-rose-900 dark:text-rose-100 text-xs tracking-tight">Log Out</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MyAccount;

