        </div>
      );
      case 'account': return <MyAccount state={compositeState!} setCurrentView={setSubView} t={t} onLogout={handleLogout} toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} />;
      default: return null;
    }
  };

  return (
    <div className="app-viewport bg-ivory dark:bg-slate-950" dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative w-full h-full">
        {renderView()}
      </main>
      {!subView && (
        <nav className="bottom-nav">
          <button onClick={() => setActiveTab('home')} className={`nav-item ${activeTab === 'home' ? 'active' : ''}`}><i className="fas fa-mosque"></i><span className="text-[8px] font-black uppercase tracking-widest">Home</span></button>
          <button onClick={() => setActiveTab('prayer')} className={`nav-item ${activeTab === 'prayer' ? 'active' : ''}`}><i className="fas fa-kaaba"></i><span className="text-[8px] font-black uppercase tracking-widest">Calendar</span></button>
          <button onClick={() => setActiveTab('tracker')} className={`nav-item ${activeTab === 'tracker' ? 'active' : ''}`}><i className="fas fa-compass"></i><span className="text-[8px] font-black uppercase tracking-widest">Tracker</span></button>
          <button onClick={() => setActiveTab('challenges')} className={`nav-item ${activeTab === 'challenges' ? 'active' : ''}`}><i className="fas fa-star-and-crescent"></i><span className="text-[8px] font-black uppercase tracking-widest">Dhikr</span></button>
          <button onClick={() => setActiveTab('account')} className={`nav-item ${activeTab === 'account' ? 'active' : ''}`}><i className="fas fa-user"></i><span className="text-[8px] font-black uppercase tracking-widest">Me</span></button>
