import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const todayStr = currentTime.toISOString().split('T')[0];
  const logs = state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const randomHadith = useMemo(() => {
    const dayOfYear = Math.floor((currentTime.getTime() - new Date(currentTime.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24);
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const [h, m] = state.todayTimings![p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings].split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  return (
    <div className="scroll-container px-4 pt-8 content-limit w-full">
      {/* Hadith Section */}
      <div className="bg-gradient-to-br from-emerald-900 to-teal-950 p-6 rounded-[32px] text-white shadow-xl relative overflow-hidden mb-6 animate-fade-up">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16 blur-3xl"></div>
        <div className="flex items-center gap-3 mb-4">
          <div className="w-8 h-8 bg-gold-500 rounded-lg flex items-center justify-center text-xs text-white shadow-lg"><i className="fas fa-quote-left"></i></div>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-300">{t('hadithTitle')}</span>
        </div>
        <p className="arabic-font text-xl mb-4 leading-relaxed" dir="rtl">{randomHadith.arabic}</p>
        <p className="text-[11px] font-medium leading-relaxed opacity-80 border-l-2 border-gold-500 pl-4 italic">"{randomHadith[state.profile.preferredLanguage as keyof typeof randomHadith]}"</p>
      </div>

      {/* Next Prayer Card */}
      <div className="card-premium mb-6 animate-fade-up stagger-1 border-emerald-100 flex items-center justify-between !p-5">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 text-white rounded-2xl flex items-center justify-center text-xl shadow-lg shadow-emerald-500/20"><i className="fas fa-kaaba"></i></div>
          <div>
            <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-sm">{t('nextPrayer')}</h3>
            <p className="text-xl font-black tracking-tighter text-emerald-700 capitalize">{nextPrayer ? t(nextPrayer.name) : '---'} • {nextPrayer?.time}</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t('time')}</p>
          <p className="text-lg font-black text-emerald-600 tabular-nums">-{nextPrayer?.diffH}h {nextPrayer?.diffM}m</p>
        </div>
      </div>

      {/* Fard Prayers Horizontal */}
      <div className="mb-8 animate-fade-up stagger-2">
        <div className="flex justify-between items-center px-1 mb-4">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Daily Obligation</h3>
          <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">{PRAYERS.filter(p => logs[p] === 'completed').length}/5 Done</span>
        </div>
        <div className="flex gap-3 overflow-x-auto no-scrollbar -mx-4 px-4">
          {PRAYERS.map(p => {
            const isDone = logs[p] === PrayerStatus.COMPLETED;
            return (
              <button 
                key={p} 
                onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                className={`flex-none w-28 p-4 rounded-3xl border-2 transition-all active:scale-95 ${isDone ? 'bg-emerald-600 border-emerald-500 text-white shadow-lg' : 'bg-white dark:bg-slate-900 border-slate-50 dark:border-slate-800 text-slate-400'}`}
              >
                <i className={`fas ${isDone ? 'fa-check-circle' : 'fa-circle-notch'} text-lg mb-2`}></i>
                <p className="font-black text-[11px] uppercase tracking-tighter capitalize">{t(p)}</p>
                <p className={`text-[8px] font-bold uppercase mt-0.5 ${isDone ? 'text-emerald-200' : 'text-slate-300'}`}>{state.todayTimings![p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings]}</p>
              </button>
            );
          })}
        </div>
      </div>

      {/* Home Quick Actions */}
      <div className="grid grid-cols-2 gap-4 animate-fade-up stagger-3">
        <button onClick={() => setCurrentView('quran')} className="card-premium h-24 flex flex-col justify-between group">
          <i className="fas fa-book-quran text-amber-500 text-xl group-hover:scale-110 transition-transform"></i>
          <p className="font-black text-[10px] uppercase text-slate-900 dark:text-emerald-50 tracking-tight">{t('quran')}</p>
        </button>
        <button onClick={() => setCurrentView('qibla')} className="card-premium h-24 flex flex-col justify-between group">
          <i className="fas fa-compass text-blue-500 text-xl group-hover:rotate-12 transition-transform"></i>
          <p className="font-black text-[10px] uppercase text-slate-900 dark:text-emerald-50 tracking-tight">{t('qibla')}</p>
        </button>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface PrayerCalendarProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const PrayerCalendar: React.FC<PrayerCalendarProps> = ({ state, updatePrayerStatus, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const month = viewDate.getMonth(), year = viewDate.getFullYear();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();

  const days = Array.from({ length: daysInMonth }, (_, i) => {
    const d = i + 1;
    return `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  });

  const isExcused = (date: string) => state.healthPeriods.some(p => {
    const d = new Date(date).getTime();
    const start = new Date(p.start).getTime();
    const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + 86400000;
    return d >= start && d <= end;
  });

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-950 overflow-hidden">
      <header className="p-4 pt-10 bg-emerald-900 text-white shrink-0 shadow-lg">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-xl font-black tracking-tighter">{viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</h1>
          <div className="flex gap-2">
            <button onClick={() => setViewDate(new Date(year, month - 1, 1))} className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center"><i className="fas fa-chevron-left text-xs"></i></button>
            <button onClick={() => setViewDate(new Date(year, month + 1, 1))} className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center"><i className="fas fa-chevron-right text-xs"></i></button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-1 px-1">
          {['S','M','T','W','T','F','S'].map((d, i) => <div key={i} className="text-center text-[8px] font-black text-emerald-300 uppercase">{d}</div>)}
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 pb-24 no-scrollbar">
        <div className="grid grid-cols-7 gap-3 mb-8">
          {Array(firstDay).fill(null).map((_, i) => <div key={i} className="h-14"></div>)}
          {days.map(d => {
            const log = state.prayerLogs[d] || {};
            const excused = isExcused(d);
            const done = PRAYERS.filter(p => log[p] === 'completed').length;
            const missed = PRAYERS.filter(p => log[p] === 'missed').length;

            return (
              <div key={d} className={`h-14 rounded-xl border flex flex-col items-center justify-center gap-1 transition-all ${excused ? 'bg-pink-50/20 border-pink-100' : 'bg-white dark:bg-slate-900 border-slate-50 dark:border-slate-800 shadow-sm'}`}>
                <span className="text-[10px] font-black text-slate-900 dark:text-emerald-100">{d.split('-')[2]}</span>
                <div className="flex gap-0.5">
                  {excused ? <i className="fas fa-leaf text-[7px] text-pink-300"></i> : (
                    <>
                      {done > 0 && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>}
                      {missed > 0 && <div className="w-1.5 h-1.5 rounded-full bg-rose-500"></div>}
                    </>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="space-y-4">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t('qadah')} Table</h3>
          <div className="bg-white dark:bg-slate-900 rounded-[32px] overflow-hidden border border-slate-50 dark:border-slate-800 shadow-sm">
             <div className="grid grid-cols-6 bg-emerald-50 dark:bg-emerald-950/20 p-3 border-b dark:border-slate-800">
                <div className="text-[7px] font-black text-emerald-600 uppercase">Day</div>
                {PRAYERS.map(p => <div key={p} className="text-[7px] font-black text-emerald-600 uppercase text-center">{t(p).charAt(0)}</div>)}
             </div>
             {days.slice().reverse().map(d => {
               const l = state.prayerLogs[d] || {};
               const excused = isExcused(d);
               return (
                 <div key={d} className={`grid grid-cols-6 p-3 border-b last:border-0 dark:border-slate-800/50 ${excused ? 'bg-pink-50/5' : ''}`}>
                    <div className="text-[9px] font-black text-slate-400">{d.split('-')[2]}</div>
                    {PRAYERS.map(p => (
                      <button 
                        key={p} 
                        onClick={() => !excused && updatePrayerStatus(d, p, l[p] === 'completed' ? 'pending' : 'completed')}
                        className="flex justify-center items-center"
                      >
                         <i className={`fas ${excused ? 'fa-minus opacity-10' : l[p] === 'completed' ? 'fa-check-circle text-emerald-500' : l[p] === 'missed' ? 'fa-times-circle text-rose-500' : 'fa-circle text-slate-100 dark:text-slate-800'} text-[10px]`}></i>
                      </button>
                    ))}
                 </div>
               );
             })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PrayerCalendar;

