import React, { useMemo } from 'react';
import { UserData, PrayerStatus } from '../types';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleNotifications: () => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleNotifications }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0, missedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
        if (status === PrayerStatus.MISSED) missedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;

    let level = 'levelBeginner', color = 'text-slate-400', bg = 'bg-slate-100 dark:bg-slate-800', icon = 'fa-seedling';
    if (ratio >= 0.9) { level = 'levelElite'; color = 'text-amber-500'; bg = 'bg-amber-50 dark:bg-amber-900/20'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { level = 'levelAdvanced'; color = 'text-emerald-500'; bg = 'bg-emerald-50 dark:bg-emerald-900/20'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { level = 'levelConsistent'; color = 'text-teal-500'; bg = 'bg-teal-50 dark:bg-teal-900/20'; icon = 'fa-leaf'; }

    return { totalFard, completedFard, missedFard, ratio, level, color, bg, icon };
  }, [state]);

  const isDark = state.settings.theme === 'dark';

  return (
    <div className="scroll-container px-4 pt-10 content-limit w-full pb-32">
      <div className="flex items-center justify-between mb-8">
         <div>
            <h1 className="text-3xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{state.profile.name}</h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">@{state.profile.username}</p>
         </div>
         <button onClick={onLogout} className="w-10 h-10 bg-rose-50 dark:bg-rose-900/20 text-rose-500 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-sm"><i className="fas fa-power-off"></i></button>
      </div>

      {/* Consistency Level */}
      <div className={`card-premium mb-8 flex items-center gap-5 !p-6 border-none ${stats.bg}`}>
         <div className={`w-16 h-16 rounded-3xl flex items-center justify-center text-3xl shadow-lg shadow-black/5 ${stats.color} bg-white dark:bg-slate-900`}><i className={`fas ${stats.icon}`}></i></div>
         <div>
            <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('consistency')}</p>
            <h3 className={`text-2xl font-black tracking-tight ${stats.color}`}>{t(stats.level)}</h3>
            <p className="text-[10px] font-black text-slate-400 mt-0.5">{(stats.ratio * 100).toFixed(0)}% Commitment</p>
         </div>
      </div>

      {/* Summary Grid */}
      <div className="grid grid-cols-2 gap-4 mb-8">
         <div className="card-premium">
            <i className="fas fa-check-double text-emerald-500 mb-2"></i>
            <p className="text-xl font-black text-emerald-950 dark:text-emerald-50">{stats.completedFard}</p>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{t('completed')}</p>
         </div>
         <div className="card-premium">
            <i className="fas fa-history text-rose-500 mb-2"></i>
            <p className="text-xl font-black text-emerald-950 dark:text-emerald-50">{stats.missedFard}</p>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{t('missed')}</p>
         </div>
         <div className="card-premium">
            <i className="fas fa-star-and-crescent text-teal-500 mb-2"></i>
            <p className="text-xl font-black text-emerald-950 dark:text-emerald-50">{state.dhikrCount}</p>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{t('dhikr')}</p>
         </div>
         <div onClick={() => setCurrentView('quran')} className="card-premium cursor-pointer">
            <i className="fas fa-book-open text-amber-500 mb-2"></i>
            <p className="text-xl font-black text-emerald-950 dark:text-emerald-50 truncate">{state.quranProgress.surah || '0'}</p>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{t('quran')}</p>
         </div>
      </div>

      {/* App Settings */}
      <div className="space-y-3">
         <h4 className="text-[10px] font-black text-slate-300 uppercase tracking-widest px-1">Settings</h4>
         <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between !p-5">
            <div className="flex items-center gap-4">
               <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${isDark ? 'bg-slate-700 text-amber-400' : 'bg-amber-50 text-amber-600'}`}><i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i></div>
               <span className="font-black text-sm text-emerald-950 dark:text-emerald-50">Theme Appearance</span>
            </div>
            <span className="text-[9px] font-black text-emerald-500 uppercase">{isDark ? 'Dark' : 'Light'}</span>
         </button>
         <button onClick={toggleNotifications} className="card-premium w-full flex items-center justify-between !p-5">
            <div className="flex items-center gap-4">
               <div className="w-10 h-10 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 rounded-xl flex items-center justify-center text-lg"><i className="fas fa-bell"></i></div>
               <span className="font-black text-sm text-emerald-950 dark:text-emerald-50">Worship Alerts</span>
            </div>
            <div className={`w-10 h-5 rounded-full p-1 transition-colors ${state.settings.notificationsEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-slate-800'}`}>
               <div className={`w-3 h-3 bg-white rounded-full transition-transform ${state.settings.notificationsEnabled ? 'translate-x-5' : 'translate-x-0'}`}></div>
            </div>
         </button>
      </div>
    </div>
  );
};

