import React, { useState } from 'react';
import { UserData, FastingLog, PrayerTimings } from '../types';

interface FastingTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updateFasting: (date: string, log: FastingLog) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const FastingTracker: React.FC<FastingTrackerProps> = ({ state, updateFasting, setCurrentView, t }) => {
  const ramadanDays = Array.from({ length: 30 }, (_, i) => i + 1);
  const year = '1446H';

  const getLog = (day: number) => state.fastingLogs[`ramadan-${year}-${day}`] || { status: 'none', type: 'ramadan' };

  const toggle = (day: number) => {
    const current = getLog(day);
    const next: FastingLog['status'] = current.status === 'none' ? 'completed' : current.status === 'completed' ? 'missed' : 'none';
    updateFasting(`ramadan-${year}-${day}`, { status: next, type: 'ramadan' });
  };

  const stats = ramadanDays.reduce((acc, d) => {
    const l = getLog(d);
    if (l.status === 'completed') acc.c++;
    if (l.status === 'missed') acc.m++;
    return acc;
  }, { c: 0, m: 0 });

  return (
    <div className="scroll-container px-4 pt-10 content-limit w-full pb-32">
      <div className="flex items-center gap-3 mb-8">
        <button onClick={() => setCurrentView(null)} className="w-10 h-10 bg-white dark:bg-slate-900 rounded-xl flex items-center justify-center shadow-sm"><i className="fas fa-chevron-left text-xs"></i></button>
        <h1 className="text-3xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">Holy Fasting</h1>
      </div>

      <div className="card-premium bg-emerald-900 text-white mb-8 !p-6 flex justify-around items-center border-none shadow-xl shadow-emerald-900/20">
         <div className="text-center">
            <p className="text-3xl font-black text-emerald-300">{stats.c}</p>
            <p className="text-[8px] font-black uppercase tracking-widest text-white/50">{t('completed')}</p>
         </div>
         <div className="h-10 w-px bg-white/10"></div>
         <div className="text-center">
            <p className="text-3xl font-black text-rose-400">{stats.m}</p>
            <p className="text-[8px] font-black uppercase tracking-widest text-white/50">Qada Due</p>
         </div>
      </div>

      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 px-1">Ramadan {year} Calendar</h3>
      <div className="grid grid-cols-5 gap-3">
         {ramadanDays.map(d => {
           const log = getLog(d);
           return (
             <button 
               key={d} 
               onClick={() => toggle(d)}
               className={`h-16 rounded-2xl border-2 flex flex-col items-center justify-center transition-all active:scale-95 ${log.status === 'completed' ? 'bg-emerald-500 border-emerald-400 text-white' : log.status === 'missed' ? 'bg-rose-500 border-rose-400 text-white' : 'bg-white dark:bg-slate-900 border-slate-50 dark:border-slate-800 text-slate-300'}`}
             >
                <span className="text-xs font-black">{d}</span>
                <i className={`fas ${log.status === 'completed' ? 'fa-check' : log.status === 'missed' ? 'fa-xmark' : 'fa-moon'} text-[8px] mt-1`}></i>
             </button>
           );
         })}
      </div>
    </div>
  );
};

export default FastingTracker;

import React, { useState, useMemo } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface PrayerCalendarProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const PrayerCalendar: React.FC<PrayerCalendarProps> = ({ state, updatePrayerStatus, setCurrentView, t }) => {
  const [viewDate, setViewDate] = useState(new Date());
  const month = viewDate.getMonth(), year = viewDate.getFullYear();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();

  const days = Array.from({ length: daysInMonth }, (_, i) => {
    const d = i + 1;
    return `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  });

  const isExcused = (date: string) => state.healthPeriods.some(p => {
    const d = new Date(date).getTime();
    const start = new Date(p.start).getTime();
    const end = p.end ? new Date(p.end).getTime() : new Date().getTime() + 86400000;
    return d >= start && d <= end;
  });

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-950 overflow-hidden">
      <header className="p-4 pt-10 bg-emerald-900 text-white shrink-0 shadow-lg">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-xl font-black tracking-tighter">{viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</h1>
          <div className="flex gap-2">
            <button onClick={() => setViewDate(new Date(year, month - 1, 1))} className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center"><i className="fas fa-chevron-left text-xs"></i></button>
            <button onClick={() => setViewDate(new Date(year, month + 1, 1))} className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center"><i className="fas fa-chevron-right text-xs"></i></button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-1 px-1">
          {['S','M','T','W','T','F','S'].map((d, i) => <div key={i} className="text-center text-[8px] font-black text-emerald-300 uppercase">{d}</div>)}
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 pb-24 no-scrollbar">
        <div className="grid grid-cols-7 gap-3 mb-8">
          {Array(firstDay).fill(null).map((_, i) => <div key={i} className="h-14"></div>)}
          {days.map(d => {
            const log = state.prayerLogs[d] || {};
            const excused = isExcused(d);
            // Use PrayerStatus enum for comparisons
            const done = PRAYERS.filter(p => log[p] === PrayerStatus.COMPLETED).length;
            const missed = PRAYERS.filter(p => log[p] === PrayerStatus.MISSED).length;

            return (
              <div key={d} className={`h-14 rounded-xl border flex flex-col items-center justify-center gap-1 transition-all ${excused ? 'bg-pink-50/20 border-pink-100' : 'bg-white dark:bg-slate-900 border-slate-50 dark:border-slate-800 shadow-sm'}`}>
                <span className="text-[10px] font-black text-slate-900 dark:text-emerald-100">{d.split('-')[2]}</span>
                <div className="flex gap-0.5">
                  {excused ? <i className="fas fa-leaf text-[7px] text-pink-300"></i> : (
                    <>
                      {done > 0 && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>}
                      {missed > 0 && <div className="w-1.5 h-1.5 rounded-full bg-rose-500"></div>}
                    </>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="space-y-4">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">{t('qadah')} Table</h3>
          <div className="bg-white dark:bg-slate-900 rounded-[32px] overflow-hidden border border-slate-50 dark:border-slate-800 shadow-sm">
             <div className="grid grid-cols-6 bg-emerald-50 dark:bg-emerald-950/20 p-3 border-b dark:border-slate-800">
                <div className="text-[7px] font-black text-emerald-600 uppercase">Day</div>
                {PRAYERS.map(p => <div key={p} className="text-[7px] font-black text-emerald-600 uppercase text-center">{t(p).charAt(0)}</div>)}
             </div>
             {days.slice().reverse().map(d => {
               const l = state.prayerLogs[d] || {};
               const excused = isExcused(d);
               return (
                 <div key={d} className={`grid grid-cols-6 p-3 border-b last:border-0 dark:border-slate-800/50 ${excused ? 'bg-pink-50/5' : ''}`}>
                    <div className="text-[9px] font-black text-slate-400">{d.split('-')[2]}</div>
                    {PRAYERS.map(p => (
                      <button 
                        key={p} 
                        // Fix: Use PrayerStatus enum instead of string literals for updatePrayerStatus call
                        onClick={() => !excused && updatePrayerStatus(d, p, l[p] === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                        className="flex justify-center items-center"
                      >
                         <i className={`fas ${excused ? 'fa-minus opacity-10' : l[p] === PrayerStatus.COMPLETED ? 'fa-check-circle text-emerald-500' : l[p] === PrayerStatus.MISSED ? 'fa-times-circle text-rose-500' : 'fa-circle text-slate-100 dark:text-slate-800'} text-[10px]`}></i>
                      </button>
                    ))}
                 </div>
               );
             })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PrayerCalendar;

