              >
                <div className="flex justify-between w-full">
                  <span className={`text-[11px] font-black ${isSelected ? 'text-emerald-700 dark:text-emerald-400' : isHayd ? 'text-pink-500' : isToday ? 'text-teal-600' : 'text-slate-400'}`}>
                    {parseInt(dayNum)}
                  </span>
                  {isFast && (
                    <i className="fas fa-moon text-[8px] text-gold-500 drop-shadow-[0_0_5px_rgba(245,158,11,0.3)]"></i>
                  )}
                </div>

                {!isHayd && logs ? (
                  <div className="grid grid-cols-3 gap-1 px-1">
                    {PRAYERS.map(p => {
                      const s = logs[p];
                      return (
                        <div 
                          key={p} 
                          className={`w-1.5 h-1.5 rounded-full transition-all duration-500 ${
                            s === PrayerStatus.COMPLETED ? 'bg-emerald-500 scale-110 shadow-[0_0_4px_rgba(16,185,129,0.4)]' : 
                            s === PrayerStatus.MISSED ? 'bg-rose-500 scale-110 shadow-[0_0_4px_rgba(244,63,94,0.4)]' : 
                            'bg-slate-100 dark:bg-slate-800'
                          }`}
                        ></div>
                      );
                    })}
                  </div>
                ) : isHayd ? (
                  <div className="flex items-center justify-center mb-1">
                    <i className="fas fa-leaf text-[11px] text-pink-300/80 animate-pulse"></i>
                  </div>
                ) : (
                  <div className="h-4"></div>
                )}

                {isSelected && (
                  <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1 h-1 bg-emerald-500 rounded-full"></div>
                )}
              </button>
            );
          })}
        </div>

        {/* Selected Day Details Section */}
        {selectedDate && (
          <div className="content-limit animate-fade-up px-2">
            <div className="flex items-center justify-between mb-5">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-emerald-500 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-emerald-500/20">
                  <i className="fas fa-calendar-day"></i>
                </div>
                <div>
                  <h2 className="text-lg font-black text-slate-900 dark:text-white leading-none">
                    {new Date(selectedDate).toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'short' })}
                  </h2>
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Detailed Log</p>
                </div>
              </div>
              {isDateInHayd(selectedDate) && (
                <span className="px-3 py-1.5 bg-pink-50 dark:bg-pink-900/30 text-pink-600 dark:text-pink-400 text-[10px] font-black uppercase tracking-widest rounded-full border border-pink-100 dark:border-pink-800/30 flex items-center gap-2">
                  <i className="fas fa-leaf text-[8px]"></i> {t('excused')}
                </span>
              )}
            </div>

            <div className="space-y-3">
              {PRAYERS.map((prayer) => {
                const logs = state.prayerLogs[selectedDate] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };
                const s = isDateInHayd(selectedDate) ? PrayerStatus.EXCUSED : (logs[prayer as keyof typeof logs] || PrayerStatus.PENDING);

                return (
                  <div 
                    key={prayer} 
                    className={`
                      card-premium !p-5 flex items-center justify-between transition-all border-2
                      ${s === PrayerStatus.COMPLETED ? 'border-emerald-500/20 bg-emerald-50/20 dark:bg-emerald-900/10' : 
                        s === PrayerStatus.MISSED ? 'border-rose-500/20 bg-rose-50/20 dark:bg-rose-900/10' : 
                        'border-slate-50 dark:border-slate-800 bg-white dark:bg-slate-900'}
                      ${isDateInHayd(selectedDate) ? 'opacity-60' : ''}
                    `}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`w-14 h-14 rounded-[1.25rem] flex items-center justify-center text-xl transition-all duration-500 ${
                        s === PrayerStatus.COMPLETED ? 'bg-emerald-500 text-white shadow-xl shadow-emerald-500/20 scale-105' : 
                        s === PrayerStatus.MISSED ? 'bg-rose-500 text-white shadow-xl shadow-rose-500/20 scale-105' : 
                        'bg-slate-50 dark:bg-slate-800 text-slate-300'
                      }`}>
                        <i className={`fas ${s === PrayerStatus.COMPLETED ? 'fa-check' : s === PrayerStatus.MISSED ? 'fa-history' : 'fa-kaaba'}`}></i>
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 dark:text-white capitalize text-base">{t(prayer)}</h4>
                        <div className="flex items-center gap-2 mt-0.5">
                          <span className={`text-[9px] font-black uppercase tracking-widest ${
                            s === PrayerStatus.COMPLETED ? 'text-emerald-600' : s === PrayerStatus.MISSED ? 'text-rose-600' : 'text-slate-400'
                          }`}>
                            {s === PrayerStatus.COMPLETED ? 'Alhamdulillah' : s === PrayerStatus.MISSED ? 'Qada Required' : t('pending')}
                          </span>
                        </div>
                      </div>
                    </div>

                    {!isDateInHayd(selectedDate) && (
                      <div className="flex gap-2">
                        <button 
                          onClick={() => handleStatus(prayer, s === PrayerStatus.COMPLETED ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                          className={`w-11 h-11 rounded-2xl flex items-center justify-center border-2 transition-all active:scale-95 ${
                            s === PrayerStatus.COMPLETED ? 'bg-emerald-600 border-emerald-500 text-white shadow-lg' : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-300 hover:border-emerald-200'
                          }`}
                        >
                          <i className="fas fa-check"></i>
                        </button>
                        <button 
                          onClick={() => handleStatus(prayer, s === PrayerStatus.MISSED ? PrayerStatus.PENDING : PrayerStatus.MISSED)}
                          className={`w-11 h-11 rounded-2xl flex items-center justify-center border-2 transition-all active:scale-95 ${
                            s === PrayerStatus.MISSED ? 'bg-rose-600 border-rose-500 text-white shadow-lg' : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-300 hover:border-rose-200'
                          }`}
                        >
                          <i className="fas fa-history text-[10px]"></i>
                        </button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

