import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const todayStr = currentTime.toISOString().split('T')[0];
  const logs = state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const randomHadith = useMemo(() => {
    const dayOfYear = Math.floor((currentTime.getTime() - new Date(currentTime.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24);
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const timingKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![timingKey].split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![timingKey] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  const streak = useMemo(() => {
    return Math.floor(state.dhikrCount / 100) + 3; 
  }, [state.dhikrCount]);

  return (
    <div className="scroll-container px-6 pt-10 content-limit w-full">
      {/* Header Greeting */}
      <div className="flex justify-between items-center mb-8 animate-fade-up">
        <div>
          <h2 className="text-sm font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Assalamu Alaikum</h2>
          <h1 className="text-3xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{state.profile.name}</h1>
        </div>
        <div className="flex gap-3">
          <div className="flex flex-col items-center justify-center bg-white dark:bg-slate-800 p-2 px-3 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm">
             <i className="fas fa-fire text-orange-500 mb-1"></i>
             <span className="text-[10px] font-black text-slate-900 dark:text-white">{streak}</span>
          </div>
        </div>
      </div>

      {/* Next Prayer Floating Card */}
      <div className="relative mb-10 animate-fade-up stagger-1">
        <div className="absolute inset-0 bg-emerald-500 blur-3xl opacity-10 rounded-full scale-90"></div>
        <div className="card-premium relative bg-gradient-to-br from-emerald-600 via-teal-600 to-emerald-800 border-none !p-6 flex items-center justify-between text-white overflow-hidden shadow-2xl shadow-emerald-900/40">
          <i className="fas fa-mosque absolute -right-6 -bottom-6 text-9xl opacity-10 rotate-12"></i>

          <div className="relative z-10">
            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-100 mb-1">{t('nextPrayer')}</h3>
            <div className="flex items-baseline gap-2">
              <span className="text-4xl font-black tracking-tighter capitalize">{nextPrayer ? t(nextPrayer.name) : '---'}</span>
              <span className="text-lg font-bold opacity-60">@ {nextPrayer?.time}</span>
            </div>
          </div>

          <div className="relative z-10 text-right">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-2 px-4 border border-white/20">
               <p className="text-[9px] font-black uppercase tracking-widest text-emerald-200">{t('time')}</p>
               <p className="text-xl font-black tabular-nums">-{nextPrayer?.diffH}h {nextPrayer?.diffM}m</p>
            </div>
          </div>
        </div>
      </div>

      {/* Daily Reflection / Hadith */}
      <div className="mb-10 animate-fade-up stagger-2">
        <div className="flex items-center gap-3 mb-4">
          <div className="h-px flex-1 bg-slate-200 dark:bg-slate-800"></div>
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.4em]">{t('hadithTitle')}</span>
          <div className="h-px flex-1 bg-slate-200 dark:bg-slate-800"></div>
        </div>
        <div className="card-premium dark:bg-slate-900/50 dark:border-slate-800 p-6 relative bg-gradient-to-br from-white to-emerald-50/20 dark:from-slate-900 dark:to-emerald-900/10">
          <i className="fas fa-quote-left text-emerald-500/10 text-4xl absolute top-4 left-4"></i>
          <p className="arabic-font text-2xl mb-4 leading-relaxed text-right text-emerald-900 dark:text-emerald-400" dir="rtl">{randomHadith.arabic}</p>
          <p className="text-xs font-medium leading-relaxed text-slate-600 dark:text-slate-400 italic">"{randomHadith[state.profile.preferredLanguage as keyof typeof randomHadith]}"</p>
          <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-3 text-right">— {randomHadith.reference}</p>
        </div>
      </div>

      {/* Fard Prayer Tracker Horizontal Line */}
      <div className="mb-12 animate-fade-up stagger-3">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xs font-black text-slate-900 dark:text-emerald-50 uppercase tracking-widest">Daily Obligation</h3>
          <span className="text-[10px] font-black text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 px-3 py-1 rounded-full">{PRAYERS.filter(p => logs[p as keyof typeof logs] === 'completed').length}/5 Done</span>
        </div>

        <div className="flex gap-4 overflow-x-auto no-scrollbar pb-4 -mx-2 px-2">
          {PRAYERS.map(p => {
            const status = logs[p as keyof typeof logs];
            const isDone = status === PrayerStatus.COMPLETED;
            const time = state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings];

            return (
              <button 
                key={p} 
                onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                className={`flex-none w-24 aspect-[3/4] rounded-[2.5rem] border-2 transition-all duration-500 flex flex-col items-center justify-center py-6 ${
                  isDone 
                    ? 'bg-gradient-to-br from-emerald-600 to-teal-700 border-emerald-500 text-white shadow-xl shadow-emerald-500/20 translate-y-[-4px]' 
                    : 'bg-gradient-to-br from-white to-slate-50 dark:from-slate-900 dark:to-slate-800 border-slate-50 dark:border-slate-800 text-slate-400 hover:border-emerald-200'
                }`}
              >
                <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{time}</span>
                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm ${isDone ? 'bg-white/20' : 'bg-slate-50 dark:bg-slate-800 text-slate-300'}`}>
                   <i className={`fas ${isDone ? 'fa-check' : 'fa-circle-notch'}`}></i>
                </div>
                <span className="text-[10px] font-black uppercase tracking-tighter capitalize mt-2">{t(p)}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Quick Actions Grid */}
      <div className="grid grid-cols-2 gap-4 animate-fade-up stagger-4 mb-20">
        <button onClick={() => setCurrentView('quran')} className="card-premium h-28 flex flex-col items-start justify-between group overflow-hidden hover:scale-[1.02] active:scale-95 transition-all bg-gradient-to-br from-white to-amber-50/30 dark:from-slate-900 dark:to-amber-900/10">
          <div className="w-10 h-10 bg-amber-50 dark:bg-amber-900/20 text-amber-600 rounded-xl flex items-center justify-center text-lg shadow-sm group-hover:scale-110 transition-transform">
            <i className="fas fa-book-quran"></i>
          </div>
          <div>
            <p className="font-black text-[11px] uppercase text-slate-900 dark:text-emerald-50 tracking-widest">{t('quran')}</p>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Surah {state.quranProgress.surah || '---'}</p>
          </div>
        </button>

        <button onClick={() => setCurrentView('qibla')} className="card-premium h-28 flex flex-col items-start justify-between group overflow-hidden hover:scale-[1.02] active:scale-95 transition-all bg-gradient-to-br from-white to-blue-50/30 dark:from-slate-900 dark:to-blue-900/10">
          <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl flex items-center justify-center text-lg shadow-sm group-hover:rotate-12 transition-transform">
            <i className="fas fa-compass"></i>
          </div>
          <div>
            <p className="font-black text-[11px] uppercase text-slate-900 dark:text-emerald-50 tracking-widest">{t('qibla')}</p>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Direction Finder</p>
          </div>
        </button>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserData, PrayerStatus, PrayerTimings } from '../types';
import { PRAYERS } from '../constants';

interface FardPrayersProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  toggleSunnahStatus: (date: string, sunnahName: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const SUNNAH_PRAYERS = ['Fajr Sunnah', 'Dhuhr Before', 'Dhuhr After', 'Maghrib Sunnah', 'Isha Sunnah', 'Witr'];

const FardPrayers: React.FC<FardPrayersProps> = ({ state, updatePrayerStatus, toggleSunnahStatus, setCurrentView, t }) => {
  const [activeTab, setActiveTab] = useState<'fard' | 'sunnah'>('fard');
  const today = new Date().toISOString().split('T')[0];
  const fardLogs = state.prayerLogs[today] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
  const sunnahLogs = state.sunnahLogs[today] || [];
  const isExcused = state.isHaydNifas;

  const handleToggle = (prayer: any, type: 'fard' | 'sunnah') => {
    if (type === 'fard') {
      const currentStatus = fardLogs[prayer as keyof typeof fardLogs];
      // Cycle: Pending -> Completed -> Missed -> Pending
      let nextStatus: PrayerStatus = PrayerStatus.PENDING;
      if (currentStatus === PrayerStatus.PENDING) nextStatus = PrayerStatus.COMPLETED;
      else if (currentStatus === PrayerStatus.COMPLETED) nextStatus = PrayerStatus.MISSED;
      else if (currentStatus === PrayerStatus.MISSED) nextStatus = PrayerStatus.PENDING;

      updatePrayerStatus(today, prayer, nextStatus);
    } else {
      toggleSunnahStatus(today, prayer);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#fdfbf7] dark:bg-slate-950 overflow-hidden">
      <header className="bg-gradient-to-br from-emerald-900 via-teal-900 to-emerald-950 px-6 pt-12 pb-8 flex flex-col gap-6 z-10 shrink-0 rounded-b-[40px] shadow-2xl relative">
        <div className="absolute top-0 right-0 w-32 h-32 bg-gold-500/5 rounded-full -mr-16 -mt-16 blur-3xl"></div>
        <div className="flex justify-between items-center w-full content-limit relative z-10">
          <div className="flex flex-col">
            <h1 className="text-2xl font-black text-white tracking-tight">{t('fard')}</h1>
            <p className="text-[9px] font-black text-emerald-300 uppercase tracking-widest mt-1">Daily Divine Schedule</p>
          </div>
          <div className="bg-white/10 p-1.5 rounded-2xl border border-white/10 backdrop-blur-md">
             <div className="flex">
               <button onClick={() => setActiveTab('fard')} className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'fard' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/40'}`}>{t('fard')}</button>
               <button onClick={() => setActiveTab('sunnah')} className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sunnah' ? 'bg-white text-emerald-900 shadow-lg' : 'text-white/40'}`}>{t('sunnah')}</button>
             </div>
          </div>
        </div>
      </header>

      <div className="scroll-container px-6 pt-8 space-y-4 w-full flex flex-col items-center no-scrollbar">
        <div className="w-full content-limit space-y-3 pb-24">
          {(activeTab === 'fard' ? PRAYERS : SUNNAH_PRAYERS).map((p, idx) => {
            const status = activeTab === 'fard' ? fardLogs[p as keyof typeof fardLogs] : (sunnahLogs.includes(p) ? PrayerStatus.COMPLETED : PrayerStatus.PENDING);
            const isDone = status === PrayerStatus.COMPLETED;
            const isMissed = status === PrayerStatus.MISSED;
            const time = activeTab === 'fard' ? state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings] : null;

            return (
              <button 
                key={p} 
                onClick={() => !isExcused && handleToggle(p, activeTab)} 
                className={`card-premium !p-5 flex items-center justify-between border-2 transition-all duration-500 animate-fade-up ${
                  isDone 
                    ? `border-emerald-500 dark:border-emerald-500/30 bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-900/10 dark:to-teal-900/10 shadow-lg shadow-emerald-500/10 animate-pop` 
                    : isMissed 
                    ? `border-rose-400 dark:border-rose-900/30 bg-rose-50/30 dark:bg-rose-950/20 shadow-sm`
                    : 'border-slate-50 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-emerald-200'
                } ${isExcused ? 'opacity-30 grayscale cursor-not-allowed' : 'cursor-pointer active:scale-95'}`}
                style={{ animationDelay: `${idx * 0.05}s` }}
              >
                <div className="flex items-center gap-5">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl transition-all duration-500 ${
                    isDone 
                      ? `bg-gradient-to-br from-emerald-500 to-teal-600 text-white shadow-xl shadow-emerald-500/20 scale-110` 
                      : isMissed
                      ? `bg-rose-500 text-white shadow-md`
                      : 'bg-slate-50 dark:bg-slate-800 text-slate-300'
                  }`}>
                    <i className={`fas ${isDone ? 'fa-check' : isMissed ? 'fa-xmark' : 'fa-kaaba'}`}></i>
                  </div>
                  <div className="text-left">
                    <h3 className="font-black text-slate-900 dark:text-emerald-50 text-base tracking-tight">{t(p)}</h3>
                    <div className="flex items-center gap-2 mt-0.5">
                       {time && <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{time}</p>}
                       {isDone && (
                         <span className="text-[9px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest bg-emerald-100 dark:bg-emerald-900/30 px-2 py-0.5 rounded-full flex items-center gap-1">
                            <i className="fas fa-sparkles text-[7px]"></i> {t('completed')}
                         </span>
                       )}
                       {isMissed && (
                         <div className="flex items-center gap-1.5">
                            <span className="text-[9px] font-black text-rose-600 dark:text-rose-400 uppercase tracking-widest bg-rose-100 dark:bg-rose-900/30 px-2 py-0.5 rounded-full">
                               {t('missed')}
                            </span>
                            <span className="text-[8px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-[0.2em] flex items-center gap-1">
                               <i className="fas fa-history text-[7px]"></i> Qada
                            </span>
                         </div>
                       )}
                    </div>
                  </div>
                </div>

                {!isExcused && (
                   <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isDone ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600' : isMissed ? 'bg-rose-100 dark:bg-rose-900/30 text-rose-600' : 'bg-slate-50 dark:bg-slate-800 text-slate-200'}`}>
                      <i className={`fas ${isDone ? 'fa-star' : isMissed ? 'fa-rotate-right' : 'fa-plus'} text-[10px]`}></i>
                   </div>
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default FardPrayers;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { UserData, QuranProgress, PrayerTimings } from '../types';
import { SURAHS } from '../constants';

interface QuranTrackerProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  onUpdate: (progress: QuranProgress) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const QuranTracker: React.FC<QuranTrackerProps> = ({ state, onUpdate, setCurrentView, t }) => {
  const [surahInput, setSurahInput] = useState(state.quranProgress.surah || '');
  const [ayahInput, setAyahInput] = useState(state.quranProgress.ayah || '');
  const [juzInput, setJuzInput] = useState(state.quranProgress.juz || '');
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSurahs = useMemo(() => {
    if (!surahInput) return SURAHS.slice(0, 5);
    return SURAHS.filter(s => s.toLowerCase().includes(surahInput.toLowerCase())).slice(0, 5);
  }, [surahInput]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSave = () => {
    onUpdate({
      surah: surahInput,
      ayah: ayahInput,
      juz: juzInput,
      lastUpdated: new Date().toISOString()
    });
    if ('vibrate' in navigator) navigator.vibrate(40);
  };

  const inputClasses = "w-full p-3.5 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl focus:ring-4 focus:ring-amber-500/10 outline-none shadow-sm font-black text-emerald-950 dark:text-emerald-50 text-sm";
  const labelClasses = "text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-900 animate-fade-up">
      <div className="p-4 pt-10 pb-6 bg-gradient-to-br from-amber-600 via-amber-700 to-orange-800 text-white shadow-xl rounded-b-[32px] z-20 shrink-0">
        <div className="flex items-center gap-3">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-xl border border-white/20 active:scale-90">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-xl font-black tracking-tight">{t('quran')}</h1>
            <p className="text-[9px] text-amber-200 font-black uppercase tracking-widest">Divine Journey</p>
          </div>
        </div>
      </div>

      <div className="flex-1 p-4 flex flex-col gap-5 overflow-y-auto">
        <div className="card-premium !p-5 text-center relative overflow-hidden bg-gradient-to-br from-white to-amber-50/20 dark:from-slate-800 dark:to-amber-900/10 border-amber-100/50">
          <div className="absolute top-0 right-0 w-24 h-24 bg-amber-50 dark:bg-amber-900/10 rounded-full -mr-12 -mt-12 blur-2xl opacity-50"></div>
          <div className="w-12 h-12 bg-amber-50 dark:bg-amber-900/30 rounded-2xl flex items-center justify-center mx-auto mb-3 text-amber-600 text-xl shadow-md">
            <i className="fas fa-book-open"></i>
          </div>
          <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest block mb-1">{t('lastRead')}</span>
          <h2 className="text-lg font-black text-emerald-950 dark:text-emerald-50 leading-tight">
            {state.quranProgress.surah ? `${state.quranProgress.surah}, ${t('ayah')} ${state.quranProgress.ayah}` : 'Not started'}
          </h2>
          {state.quranProgress.juz && <p className="text-[8px] font-black text-amber-600 mt-0.5 uppercase tracking-widest">{t('juz')} {state.quranProgress.juz}</p>}
        </div>

        <div className="space-y-4">
          <div className="space-y-1 relative" ref={dropdownRef}>
            <label className={labelClasses}>{t('surah')}</label>
            <input 
              type="text" 
              placeholder="e.g. Al-Baqarah"
              className={inputClasses}
              value={surahInput}
              onFocus={() => setShowDropdown(true)}
              onChange={(e) => { setSurahInput(e.target.value); setShowDropdown(true); }}
            />
            {showDropdown && filteredSurahs.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-100 dark:border-slate-700 p-1 z-50">
                {filteredSurahs.map(s => (
                  <button key={s} onClick={() => { setSurahInput(s); setShowDropdown(false); }} className="w-full text-left px-4 py-2 hover:bg-amber-50 dark:hover:bg-slate-700 rounded-lg text-xs font-black text-emerald-950 dark:text-emerald-50">{s}</button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className={labelClasses}>{t('juz')}</label>
              <input type="number" placeholder="1-30" className={inputClasses} value={juzInput} onChange={(e) => setJuzInput(e.target.value)} />
            </div>
            <div className="space-y-1">
              <label className={labelClasses}>{t('ayah')}</label>
              <input type="number" placeholder="Verse #" className={inputClasses} value={ayahInput} onChange={(e) => setAyahInput(e.target.value)} />
            </div>
          </div>

          <button onClick={handleSave} className="w-full py-4 bg-amber-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-amber-900/10 active:scale-95 transition-transform">
            {t('save')}
          </button>
        </div>

        <div className="bg-gradient-to-br from-amber-50 to-white dark:from-amber-900/10 dark:to-slate-900 p-4 rounded-3xl border border-amber-100 dark:border-amber-900/30 mt-2">
          <h3 className="text-[9px] font-black text-amber-600 uppercase tracking-widest mb-2 flex items-center gap-2">
            <i className="fas fa-sparkles"></i> {t('quranVirtue')}
          </h3>
          <p className="text-emerald-950 dark:text-emerald-50 arabic-font text-lg leading-relaxed text-right font-black mb-2" dir="rtl">مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ</p>
          <p className="text-slate-500 dark:text-slate-400 text-[10px] italic border-l-2 border-amber-200 dark:border-amber-800 pl-3 font-black">"Whoever reads a letter from the Book of Allah, he will have a reward ten-fold..."</p>
        </div>
      </div>
    </div>
  );
};

export default QuranTracker;

import React, { useState } from 'react';
import { UserData, PrayerTimings, HealthPeriod } from '../types';

interface WomensSpaceProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  toggleHayd: (active: boolean) => void;
  addHealthPeriod: (start: string, end: string | null) => void;
  removeHealthPeriod: (id: string) => void;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
}

const WomensSpace: React.FC<WomensSpaceProps> = ({ state, toggleHayd, addHealthPeriod, removeHealthPeriod, setCurrentView, t }) => {
  const [newStart, setNewStart] = useState(new Date().toISOString().split('T')[0]);
  const [newEnd, setNewEnd] = useState<string>('');
  const [showAdd, setShowAdd] = useState(false);

  const handleAdd = () => {
    if (!newStart) return;
    addHealthPeriod(newStart, newEnd || null);
    setShowAdd(false);
    setNewEnd('');
  };

  const recentPeriods = state.healthPeriods.slice(-2).reverse();

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-950 view-transition overflow-hidden">
      <div className="p-4 pt-10 pb-6 bg-gradient-to-br from-emerald-900 via-teal-900 to-emerald-950 text-white shrink-0 shadow-lg rounded-b-[32px]">
        <div className="flex items-center gap-3">
          <button onClick={() => setCurrentView('dashboard')} className="w-10 h-10 flex items-center justify-center bg-white/10 rounded-xl active:scale-95 transition-transform"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-lg font-black tracking-tight">{t('womensSpace')}</h1>
        </div>
      </div>

      <div className="flex-1 p-4 flex flex-col justify-around overflow-hidden gap-4">
        <div className={`p-6 rounded-3xl text-center border-2 transition-all duration-500 ${state.isHaydNifas ? 'border-rose-200 bg-gradient-to-br from-rose-50 to-white dark:from-rose-950/20 dark:to-slate-900' : 'border-emerald-50 bg-gradient-to-br from-emerald-50 to-white dark:from-emerald-950/10 dark:to-slate-900 shadow-sm'} shrink-0`}>
          <div className={`w-14 h-14 mx-auto rounded-2xl flex items-center justify-center mb-3 text-2xl transition-all duration-500 ${state.isHaydNifas ? 'bg-rose-500 text-white shadow-lg rotate-12 scale-110' : 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700'}`}><i className="fas fa-droplet"></i></div>
          <h2 className="text-xs font-black text-emerald-950 dark:text-emerald-50 mb-3">{t('haydMode')}</h2>
          <button onClick={() => toggleHayd(!state.isHaydNifas)} className={`w-full py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl active:scale-95 ${state.isHaydNifas ? 'bg-rose-600 text-white shadow-rose-900/20' : 'bg-emerald-950 dark:bg-emerald-600 text-white shadow-emerald-950/20'}`}>{state.isHaydNifas ? t('inactive') : t('active')}</button>
        </div>

        <div className="flex-1 flex flex-col justify-start overflow-hidden">
          <div className="flex items-center justify-between mb-3 shrink-0 px-1">
            <h3 className="text-[10px] font-black text-emerald-950 dark:text-emerald-50 uppercase tracking-widest flex items-center gap-2"><i className="fas fa-history text-gold-500"></i> Recent Records</h3>
            <button onClick={() => setShowAdd(!showAdd)} className={`w-8 h-8 rounded-xl flex items-center justify-center transition-all ${showAdd ? 'bg-rose-50 text-rose-500 border border-rose-100' : 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 border border-emerald-100 dark:border-emerald-800'}`}><i className={`fas ${showAdd ? 'fa-times' : 'fa-plus'} text-[10px]`}></i></button>
          </div>

          <div className="flex-1 flex flex-col gap-3 overflow-y-auto no-scrollbar">
            {showAdd ? (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-3xl border border-emerald-100 dark:border-emerald-800 shadow-xl animate-fade-up space-y-4 shrink-0">
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1"><label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Start Date</label><input type="date" value={newStart} onChange={e => setNewStart(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl text-[10px] outline-none font-black text-emerald-950 dark:text-emerald-50" /></div>
                  <div className="space-y-1"><label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">End Date</label><input type="date" value={newEnd} onChange={e => setNewEnd(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl text-[10px] outline-none font-black text-emerald-950 dark:text-emerald-50" /></div>
                </div>
                <button onClick={handleAdd} className="w-full py-4 bg-emerald-950 dark:bg-emerald-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-transform">Save Entry</button>
              </div>
            ) : (
              recentPeriods.map(p => (
                <div key={p.id} className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-emerald-50 dark:border-emerald-900/10 shadow-sm flex items-center justify-between shrink-0 hover:bg-emerald-50/10 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-rose-50 dark:bg-rose-900/20 text-rose-500 rounded-xl flex items-center justify-center text-sm shadow-sm"><i className="fas fa-tint"></i></div>
                    <div>
                      <p className="text-[11px] font-black text-emerald-950 dark:text-emerald-50 leading-none mb-1">{p.start.split('T')[0]}</p>
                      <p className="text-[8px] text-slate-400 uppercase font-black tracking-widest">Excused Period</p>
                    </div>
                  </div>
                  <button onClick={() => removeHealthPeriod(p.id)} className="w-8 h-8 text-rose-300 hover:text-rose-500 transition-colors active:scale-90"><i className="fas fa-trash text-[10px]"></i></button>
                </div>
              ))
            )}
            {!showAdd && recentPeriods.length === 0 && <div className="flex-1 min-h-[100px] border-2 border-dashed border-emerald-100 dark:border-emerald-900/20 rounded-[32px] flex flex-col items-center justify-center text-[10px] text-slate-300 font-black uppercase tracking-widest gap-2 opacity-50"><i className="fas fa-scroll text-xl"></i> No history</div>}
          </div>
        </div>

        <div className="bg-gradient-to-br from-amber-50 to-white dark:from-amber-900/10 dark:to-slate-900 p-4 rounded-3xl border border-amber-100 dark:border-amber-900/20 shrink-0">
          <h3 className="font-black text-amber-800 dark:text-amber-500 text-[10px] mb-2 flex items-center gap-2 uppercase tracking-widest"><i className="fas fa-circle-info"></i> Divine Ease</h3>
          <ul className="space-y-2 text-[9px] text-amber-900/80 dark:text-slate-400 font-bold leading-relaxed">
            <li className="flex gap-2"><i className="fas fa-check-circle text-amber-500 shrink-0"></i> <span>Daily prayers during periods are <b>exempted</b> and do not need to be made up.</span></li>
            <li className="flex gap-2"><i className="fas fa-exclamation-circle text-amber-500 shrink-0"></i> <span>Ramadan fasts missed must be made up (Qada) later in the year.</span></li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default WomensSpace;

