import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';
import Logo from './Logo';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
  initialMode?: 'login' | 'register';
  onBack?: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users, initialMode = 'login', onBack }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  // Real-time username availability logic
  const [usernameStatus, setUsernameStatus] = useState<'idle' | 'available' | 'taken'>('idle');
  const [suggestions, setSuggestions] = useState<string[]>([]);

  useEffect(() => {
    setMode(initialMode);
    setUsernameStatus('idle');
    setSuggestions([]);
  }, [initialMode]);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  // Real-time check effect
  useEffect(() => {
    if (mode !== 'register' || !usernameNormalized) {
      setUsernameStatus('idle');
      setSuggestions([]);
      return;
    }

    const checkAvailability = () => {
      if (users[usernameNormalized]) {
        setUsernameStatus('taken');
        // Generate 3 unique alternatives
        const alts = [
          `${usernameNormalized}${Math.floor(Math.random() * 999)}`,
          `${usernameNormalized}_${new Date().getFullYear()}`,
          `${usernameNormalized}786`
        ].filter(s => !users[s.toLowerCase()]);
        setSuggestions(alts);
      } else {
        setUsernameStatus('available');
        setSuggestions([]);
      }
    };

    const timeout = setTimeout(checkAvailability, 200);
    return () => clearTimeout(timeout);
  }, [usernameNormalized, users, mode]);

  const validate = () => {
    if (!usernameNormalized) return "Username required.";
    if (!formData.password) return "Password required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age required.";
      if (!formData.place.trim()) return "Place required.";
      if (usernameStatus === 'taken') return "This username is already taken.";
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setIsAuthenticating(true);
    // Simulating smooth auth transition
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "User not found." : "Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age),
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const applySuggestion = (s: string) => {
    setFormData({ ...formData, username: s });
  };

  const inputClasses = "w-full px-5 py-4 bg-white dark:bg-slate-800 border-2 border-slate-50 dark:border-slate-700/50 rounded-2xl focus:border-emerald-500/50 focus:ring-4 focus:ring-emerald-500/5 outline-none transition-all font-bold text-slate-900 dark:text-emerald-50 text-sm placeholder:text-slate-300 dark:placeholder:text-slate-600 shadow-sm";
  const labelClasses = "block text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1.5";

  return (
    <div className="flex flex-col h-full bg-[#fdfbf7] dark:bg-slate-950 w-full overflow-hidden animate-fade-in relative">
      <div className="absolute inset-0 bg-mesh opacity-20 pointer-events-none"></div>

      <header className="px-6 pt-12 pb-6 flex items-center justify-between shrink-0 relative z-10">
        <button 
          onClick={onBack} 
          className="w-11 h-11 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center border border-slate-100 dark:border-slate-700 active:scale-90 transition-transform shadow-sm"
        >
          <i className="fas fa-chevron-left text-xs text-slate-500"></i>
        </button>
        <Logo size="sm" withText={true} className="flex-row-reverse gap-3" />
      </header>

      <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col items-center no-scrollbar relative z-10">
        <div className="flex bg-slate-100 dark:bg-slate-900/50 p-1.5 rounded-2xl mb-8 w-full max-w-[300px] shrink-0 border border-slate-200/50 dark:border-slate-800">
          <button 
            onClick={() => setMode('login')} 
            className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 ${mode === 'login' ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
          >
            Login
          </button>
          <button 
            onClick={() => setMode('register')} 
            className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 ${mode === 'register' ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
          >
            Join
          </button>
        </div>

        <form onSubmit={handleSubmit} className="w-full max-w-[340px] space-y-5 flex flex-col animate-fade-up">
          {error && (
            <div className="bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 p-4 rounded-2xl text-[10px] font-bold text-center border border-rose-100 dark:border-rose-900/30 flex items-center justify-center gap-2">
              <i className="fas fa-circle-exclamation"></i> {error}
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>Username</label>
            <div className="relative">
              <input 
                type="text" 
                placeholder="e.g. believer_1"
                className={`${inputClasses} ${usernameStatus === 'taken' ? 'border-rose-200 ring-4 ring-rose-500/5' : usernameStatus === 'available' ? 'border-emerald-200 ring-4 ring-emerald-500/5' : ''}`} 
                value={formData.username} 
                onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, '')})} 
                required 
              />
              {usernameStatus !== 'idle' && mode === 'register' && (
                <div className="absolute right-4 top-1/2 -translate-y-1/2">
                  {usernameStatus === 'available' ? (
                    <i className="fas fa-check-circle text-emerald-500"></i>
                  ) : (
                    <i className="fas fa-times-circle text-rose-500"></i>
                  )}
                </div>
              )}
            </div>

            {mode === 'register' && usernameStatus !== 'idle' && (
              <div className="mt-2 px-1 animate-fade-in">
                {usernameStatus === 'available' ? (
                  <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-1.5">
                    Username available
                  </p>
                ) : (
                  <div className="space-y-2">
                    <p className="text-[9px] font-black text-rose-500 uppercase tracking-widest">
                      Username already taken
                    </p>
                    {suggestions.length > 0 && (
                      <div className="flex flex-wrap gap-2 items-center">
                        <span className="text-[8px] font-black text-slate-400 uppercase">Try:</span>
                        {suggestions.map(s => (
                          <button 
                            key={s} 
                            type="button" 
                            onClick={() => applySuggestion(s)}
                            className="px-3 py-1 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 text-emerald-600 dark:text-emerald-400 text-[9px] font-black rounded-full hover:bg-emerald-50 transition-colors shadow-sm"
                          >
                            {s}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>

          {mode === 'register' && (
            <div className="space-y-5 animate-fade-in">
              <div className="space-y-1">
                <label className={labelClasses}>Full Name</label>
                <input type="text" placeholder="Your Name" className={inputClasses} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className={labelClasses}>Age</label>
                  <input type="number" placeholder="24" className={inputClasses} value={formData.age} onChange={e => setFormData({...formData, age: e.target.value})} required />
                </div>
                <div className="space-y-1">
                  <label className={labelClasses}>Gender</label>
                  <div className="flex bg-white dark:bg-slate-800 p-1.5 rounded-2xl border-2 border-slate-50 dark:border-slate-700/50 shadow-sm h-[58px]">
                    <button type="button" onClick={() => setFormData({...formData, sex: 'male'})} className={`flex-1 rounded-xl text-[9px] font-black uppercase transition-all ${formData.sex === 'male' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-400'}`}>Male</button>
                    <button type="button" onClick={() => setFormData({...formData, sex: 'female'})} className={`flex-1 rounded-xl text-[9px] font-black uppercase transition-all ${formData.sex === 'female' ? 'bg-rose-500 text-white shadow-sm' : 'text-slate-400'}`}>Female</button>
                  </div>
                </div>
              </div>
              <div className="space-y-1">
                <label className={labelClasses}>Place</label>
                <input type="text" placeholder="e.g. Makkah" className={inputClasses} value={formData.place} onChange={e => setFormData({...formData, place: e.target.value})} required />
              </div>
            </div>
          )}

          <div className="space-y-1">
            <label className={labelClasses}>Password</label>
            <input 
              type="password" 
              placeholder="••••••••" 
              className={inputClasses} 
              value={formData.password} 
              onChange={e => setFormData({...formData, password: e.target.value})} 
              required 
            />
          </div>

          <div className="pt-4">
            <button 
              type="submit"
              disabled={isAuthenticating}
              className="w-full bg-emerald-950 dark:bg-emerald-600 text-white font-black py-4 rounded-[1.5rem] transition-all active:scale-95 uppercase tracking-[0.3em] text-[11px] flex items-center justify-center gap-3 disabled:opacity-50 shadow-xl shadow-emerald-950/20"
            >
              {isAuthenticating ? (
                <i className="fas fa-spinner fa-spin"></i>
              ) : (
                <>
                  {mode === 'login' ? 'Enter Space' : 'Create Account'}
                  <i className="fas fa-arrow-right text-[8px] opacity-40"></i>
                </>
              )}
            </button>
          </div>
        </form>

        <div className="mt-12 text-slate-300 dark:text-slate-700 text-[8px] font-black uppercase tracking-[0.5em] pb-8">
          End-to-End Local Storage
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';
import Logo from './Logo';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const todayStr = currentTime.toISOString().split('T')[0];
  const logs = state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const randomHadith = useMemo(() => {
    const dayOfYear = Math.floor((currentTime.getTime() - new Date(currentTime.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24);
    return HADITHS[dayOfYear % HADITHS.length];
  }, []);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const timingKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![timingKey].split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![timingKey] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  const streak = useMemo(() => {
    return Math.floor(state.dhikrCount / 100) + 3; 
  }, [state.dhikrCount]);

  return (
    <div className="scroll-container px-6 pt-10 content-limit w-full">
      {/* Header Greeting */}
      <div className="flex justify-between items-center mb-8 animate-fade-up">
        <div className="flex items-center gap-4">
          <Logo size="sm" />
          <div>
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-0.5">Assalamu Alaikum</h2>
            <h1 className="text-2xl font-black text-emerald-950 dark:text-emerald-50 tracking-tighter">{state.profile.name}</h1>
          </div>
        </div>
        <div className="flex gap-3">
          <div className="flex flex-col items-center justify-center bg-white dark:bg-slate-800 p-2 px-3 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm">
             <i className="fas fa-fire text-orange-500 mb-1"></i>
             <span className="text-[10px] font-black text-slate-900 dark:text-white">{streak}</span>
          </div>
        </div>
      </div>

      {/* Next Prayer Floating Card */}
      <div className="relative mb-10 animate-fade-up stagger-1">
        <div className="absolute inset-0 bg-emerald-500 blur-3xl opacity-10 rounded-full scale-90"></div>
        <div className="card-premium relative bg-gradient-to-br from-emerald-600 via-teal-600 to-emerald-800 border-none !p-6 flex items-center justify-between text-white overflow-hidden shadow-2xl shadow-emerald-900/40">
          <i className="fas fa-mosque absolute -right-6 -bottom-6 text-9xl opacity-10 rotate-12"></i>

          <div className="relative z-10">
            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-100 mb-1">{t('nextPrayer')}</h3>
            <div className="flex items-baseline gap-2">
              <span className="text-4xl font-black tracking-tighter capitalize">{nextPrayer ? t(nextPrayer.name) : '---'}</span>
              <span className="text-lg font-bold opacity-60">@ {nextPrayer?.time}</span>
            </div>
          </div>

          <div className="relative z-10 text-right">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-2 px-4 border border-white/20">
               <p className="text-[9px] font-black uppercase tracking-widest text-emerald-200">{t('time')}</p>
               <p className="text-xl font-black tabular-nums">-{nextPrayer?.diffH}h {nextPrayer?.diffM}m</p>
            </div>
          </div>
        </div>
      </div>

      {/* Daily Reflection / Hadith */}
      <div className="mb-10 animate-fade-up stagger-2">
        <div className="flex items-center gap-3 mb-4">
          <div className="h-px flex-1 bg-slate-200 dark:bg-slate-800"></div>
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.4em]">{t('hadithTitle')}</span>
          <div className="h-px flex-1 bg-slate-200 dark:bg-slate-800"></div>
        </div>
        <div className="card-premium dark:bg-slate-900/50 dark:border-slate-800 p-6 relative bg-gradient-to-br from-white to-emerald-50/20 dark:from-slate-900 dark:to-emerald-900/10">
          <i className="fas fa-quote-left text-emerald-500/10 text-4xl absolute top-4 left-4"></i>
          <p className="arabic-font text-2xl mb-4 leading-relaxed text-right text-emerald-900 dark:text-emerald-400" dir="rtl">{randomHadith.arabic}</p>
          <p className="text-xs font-medium leading-relaxed text-slate-600 dark:text-slate-400 italic">"{randomHadith[state.profile.preferredLanguage as keyof typeof randomHadith]}"</p>
          <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-3 text-right">— {randomHadith.reference}</p>
        </div>
      </div>

      {/* Fard Prayer Tracker Horizontal Line */}
      <div className="mb-12 animate-fade-up stagger-3">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xs font-black text-slate-900 dark:text-emerald-50 uppercase tracking-widest">Daily Obligation</h3>
          <span className="text-[10px] font-black text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 px-3 py-1 rounded-full">{PRAYERS.filter(p => logs[p as keyof typeof logs] === 'completed').length}/5 Done</span>
        </div>

        <div className="flex gap-4 overflow-x-auto no-scrollbar pb-4 -mx-2 px-2">
          {PRAYERS.map(p => {
            const status = logs[p as keyof typeof logs];
            const isDone = status === PrayerStatus.COMPLETED;
            const time = state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings];

            return (
              <button 
                key={p} 
                onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                className={`flex-none w-24 aspect-[3/4] rounded-[2.5rem] border-2 transition-all duration-500 flex flex-col items-center justify-center py-6 ${
                  isDone 
                    ? 'bg-gradient-to-br from-emerald-600 to-teal-700 border-emerald-500 text-white shadow-xl shadow-emerald-500/20 translate-y-[-4px]' 
                    : 'bg-gradient-to-br from-white to-slate-50 dark:from-slate-900 dark:to-slate-800 border-slate-50 dark:border-slate-800 text-slate-400 hover:border-emerald-200'
                }`}
              >
                <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{time}</span>
                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm ${isDone ? 'bg-white/20' : 'bg-slate-50 dark:bg-slate-800 text-slate-300'}`}>
                   <i className={`fas ${isDone ? 'fa-check' : 'fa-circle-notch'}`}></i>
                </div>
                <span className="text-[10px] font-black uppercase tracking-tighter capitalize mt-2">{t(p)}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Quick Actions Grid */}
      <div className="grid grid-cols-2 gap-4 animate-fade-up stagger-4 mb-20">
        <button onClick={() => setCurrentView('quran')} className="card-premium h-28 flex flex-col items-start justify-between group overflow-hidden hover:scale-[1.02] active:scale-95 transition-all bg-gradient-to-br from-white to-amber-50/30 dark:from-slate-900 dark:to-amber-900/10">
          <div className="w-10 h-10 bg-amber-50 dark:bg-amber-900/20 text-amber-600 rounded-xl flex items-center justify-center text-lg shadow-sm group-hover:scale-110 transition-transform">
            <i className="fas fa-book-quran"></i>
          </div>
          <div>
            <p className="font-black text-[11px] uppercase text-slate-900 dark:text-emerald-50 tracking-widest">{t('quran')}</p>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Surah {state.quranProgress.surah || '---'}</p>
          </div>
        </button>

        <button onClick={() => setCurrentView('qibla')} className="card-premium h-28 flex flex-col items-start justify-between group overflow-hidden hover:scale-[1.02] active:scale-95 transition-all bg-gradient-to-br from-white to-blue-50/30 dark:from-slate-900 dark:to-blue-900/10">
          <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl flex items-center justify-center text-lg shadow-sm group-hover:rotate-12 transition-transform">
            <i className="fas fa-compass"></i>
          </div>
          <div>
            <p className="font-black text-[11px] uppercase text-slate-900 dark:text-emerald-50 tracking-widest">{t('qibla')}</p>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Direction Finder</p>
          </div>
        </button>
      </div>
    </div>
  );
};

export default Dashboard;

