          <span className="text-[9px] font-black text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/30 px-3 py-1.5 rounded-full border border-emerald-100 dark:border-emerald-800/30">
            {PRAYERS.filter(p => logs[p as keyof typeof logs] === 'completed').length}/5 Done
          </span>
        </div>

        <div className="flex gap-4 overflow-x-auto no-scrollbar pb-6 -mx-2 px-2">
          {PRAYERS.map(p => {
            const status = logs[p as keyof typeof logs];
            const isDone = status === PrayerStatus.COMPLETED;
            const isMissed = status === PrayerStatus.MISSED;
            const time = state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings];

            return (
              <button 
                key={p} 
                onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                className={`flex-none w-28 aspect-[3/4.2] rounded-[2.5rem] border-2 transition-all duration-500 flex flex-col items-center justify-between py-6 px-2 relative ${
                  isDone 
                    ? 'bg-gradient-to-br from-emerald-500 to-teal-600 border-emerald-400 text-white shadow-xl shadow-emerald-500/30 scale-105 z-10 animate-pop' 
                    : isMissed
                    ? 'bg-gradient-to-br from-rose-50 to-white dark:from-rose-950 dark:to-slate-900 border-rose-200 dark:border-rose-900/50 text-rose-600'
                    : 'bg-gradient-to-br from-white to-slate-50 dark:from-slate-900 dark:to-slate-800 border-slate-100 dark:border-slate-800 text-slate-400 hover:border-emerald-200'
                }`}
              >
                {/* Visual Status Indicator Background glow for active states */}
                {isDone && <div className="absolute inset-0 bg-emerald-400/20 blur-xl rounded-full scale-75 animate-pulse"></div>}

                <div className="relative z-10 flex flex-col items-center">
                  <span className={`text-[9px] font-black uppercase tracking-widest mb-1 ${isDone ? 'text-emerald-100' : 'text-slate-400 opacity-60'}`}>
                    {time}
                  </span>
                  <span className={`text-[11px] font-black uppercase tracking-tight capitalize ${isDone ? 'text-white' : 'text-slate-900 dark:text-emerald-50'}`}>
                    {t(p)}
                  </span>
                </div>

                <div className={`relative z-10 w-12 h-12 rounded-2xl flex items-center justify-center text-lg transition-all duration-500 ${
                  isDone 
                    ? 'bg-white text-emerald-600 shadow-lg rotate-[360deg]' 
                    : isMissed
                    ? 'bg-rose-500 text-white shadow-md'
                    : 'bg-slate-50 dark:bg-slate-800 text-slate-300'
                }`}>
                   <i className={`fas ${isDone ? 'fa-check' : isMissed ? 'fa-xmark' : 'fa-clock'}`}></i>
                </div>

                <div className="relative z-10">
                  {isDone ? (
                    <span className="text-[7px] font-black text-emerald-100 uppercase tracking-widest">Alhamdulillah</span>
                  ) : isMissed ? (
                    <span className="text-[7px] font-black text-rose-500 uppercase tracking-widest">Qada Due</span>
                  ) : (
                    <span className="text-[7px] font-black text-slate-300 uppercase tracking-widest">Upcoming</span>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* 5. Quick Actions Grid */}
      <div className="grid grid-cols-2 gap-4 animate-fade-up stagger-4 mb-20">
        <button onClick={() => setCurrentView('quran')} className="card-premium h-28 flex flex-col items-start justify-between group overflow-hidden hover:scale-[1.02] active:scale-95 transition-all bg-gradient-to-br from-white to-amber-50/30 dark:from-slate-900 dark:to-amber-900/10 border-amber-100/50">
          <div className="w-10 h-10 bg-amber-50 dark:bg-amber-900/20 text-amber-600 rounded-xl flex items-center justify-center text-lg shadow-sm group-hover:scale-110 transition-transform">
            <i className="fas fa-book-quran"></i>
          </div>
          <div>
            <p className="font-black text-[11px] uppercase text-slate-900 dark:text-emerald-50 tracking-widest">{t('quran')}</p>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest truncate w-full">Surah {state.quranProgress.surah || '---'}</p>
          </div>
        </button>

        <button onClick={() => setCurrentView('qibla')} className="card-premium h-28 flex flex-col items-start justify-between group overflow-hidden hover:scale-[1.02] active:scale-95 transition-all bg-gradient-to-br from-white to-blue-50/30 dark:from-slate-900 dark:to-blue-900/10 border-blue-100/50">
          <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl flex items-center justify-center text-lg shadow-sm group-hover:rotate-12 transition-transform">
            <i className="fas fa-compass"></i>
          </div>
          <div>
            <p className="font-black text-[11px] uppercase text-slate-900 dark:text-emerald-50 tracking-widest">{t('qibla')}</p>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Direction Finder</p>
          </div>
        </button>
      </div>
    </div>
  );
};

