      {/* 1. Daily Hadith - Premium Illuminated Design */}
      <div className="mb-10 animate-fade-up stagger-1">
        <div className="card-premium relative bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-950 border-emerald-500/20 !p-0 overflow-hidden shadow-2xl">
