          </div>

          <div className="relative z-10 p-8">
            <div className="flex justify-between items-center mb-8">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-emerald-500/20 flex items-center justify-center text-emerald-400">
                  <i className="fas fa-bookmark text-xs"></i>
                </div>
                <span className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em]">{t('hadithTitle')}</span>
              </div>
              <button 
                onClick={handleCopyHadith}
                className="w-8 h-8 rounded-lg bg-white/5 hover:bg-white/10 flex items-center justify-center text-slate-400 transition-colors"
                title="Copy Hadith"
              >
                <i className={`fas ${copied ? 'fa-check text-emerald-500' : 'fa-share-nodes'}`}></i>
              </button>
            </div>

            <div className="space-y-6">
              <p className="arabic-font text-3xl font-bold text-white text-center leading-relaxed drop-shadow-sm" dir="rtl">
