      <div className="flex-1 overflow-y-auto px-4 pt-6 pb-32 no-scrollbar">
        <div className="content-limit w-full">

          {/* Monthly Grid */}
          <div className="grid grid-cols-7 gap-3 mb-8 animate-fade-up">
            {Array(firstDay).fill(null).map((_, i) => <div key={`empty-${i}`} className="aspect-square" />)}
            {days.map(d => {
              const { fardCount, missedCount, isFasting, dhikrDone, quranDone, excused } = getDayWorshipData(d);
              const isSelected = selectedDateStr === d;
              const isToday = d === new Date().toISOString().split('T')[0];
              const dayNum = d.split('-')[2];
              const hijriDay = getHijriDay(d);

              return (
                <button 
                  key={d} 
                  onClick={() => setSelectedDateStr(d)}
                  className={`
                    relative aspect-square rounded-[1.25rem] border-2 flex flex-col items-center justify-center gap-1 transition-all duration-300
                    ${isSelected ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 shadow-xl shadow-emerald-500/10 scale-110 z-10' : 
                      excused ? 'bg-rose-50/10 border-rose-100/50 dark:bg-rose-900/10 dark:border-rose-900/30' : 
                      isToday ? 'border-teal-500/30 bg-white dark:bg-slate-900 shadow-sm' :
                      'bg-white dark:bg-slate-900 border-slate-50 dark:border-slate-800 shadow-sm'}
                  `}
                >
                  <div className="flex flex-col items-center">
                    <span className={`text-[11px] font-black leading-none ${isSelected ? 'text-emerald-600 dark:text-emerald-400' : excused ? 'text-rose-400' : 'text-slate-900 dark:text-emerald-100'}`}>
                      {parseInt(dayNum)}
                    </span>
                    <span className="text-[6px] font-bold text-slate-400 mt-0.5 opacity-60">{hijriDay}</span>
                  </div>

                  <div className="flex flex-wrap justify-center gap-[2px] px-1">
                    {excused ? (
                      <i className="fas fa-leaf text-[7px] text-rose-300/60"></i>
                    ) : (
                      <>
                        {fardCount > 0 && <div className="w-1 h-1 rounded-full bg-emerald-500"></div>}
                        {missedCount > 0 && <div className="w-1 h-1 rounded-full bg-rose-500"></div>}
                        {dhikrDone && <div className="w-1 h-1 rounded-full bg-blue-500"></div>}
                        {quranDone && <div className="w-1 h-1 rounded-full bg-purple-500"></div>}
                        {isFasting && <div className="w-1 h-1 rounded-full bg-amber-500"></div>}
                      </>
                    )}
                  </div>
                </button>
              );
            })}
          </div>

          {/* Selected Day Details Card */}
          <div className="animate-fade-up stagger-1">
            <div className="card-premium !p-6 bg-white dark:bg-slate-900/50 border-emerald-50 dark:border-slate-800 shadow-xl shadow-slate-200/50 dark:shadow-none">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{t('summary')}</h3>
                  <h2 className="text-xl font-black text-emerald-950 dark:text-white tracking-tight">
                    {new Date(selectedDateStr).toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'short' })}
                  </h2>
                </div>
                {selectedData.excused && (
                  <span className="px-3 py-1 bg-rose-50 dark:bg-rose-900/20 text-rose-500 text-[8px] font-black uppercase tracking-widest rounded-full border border-rose-100 dark:border-rose-800/30">
                    <i className="fas fa-leaf mr-1"></i> {t('excused')}
                  </span>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="flex items-center gap-4 p-4 rounded-2xl bg-emerald-50/50 dark:bg-emerald-900/10 border border-emerald-100/50 dark:border-emerald-900/20">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${selectedData.fardCount === 5 ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-white dark:bg-slate-800 text-emerald-600'}`}>
                    <i className="fas fa-kaaba"></i>
                  </div>
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{t('fard')}</p>
                    <p className="text-sm font-black text-emerald-950 dark:text-white">{selectedData.fardCount}/5</p>
                  </div>
                </div>

                <div className="flex items-center gap-4 p-4 rounded-2xl bg-blue-50/50 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-900/20">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${selectedData.dhikrDone ? 'bg-blue-500 text-white shadow-lg shadow-blue-500/20' : 'bg-white dark:bg-slate-800 text-blue-600'}`}>
                    <i className="fas fa-fingerprint"></i>
                  </div>
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{t('dhikr')}</p>
                    <p className="text-sm font-black text-emerald-950 dark:text-white">{selectedData.dhikrDone ? 'Active' : 'Pending'}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4 p-4 rounded-2xl bg-purple-50/50 dark:bg-purple-900/10 border border-purple-100/50 dark:border-purple-900/20">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${selectedData.quranDone ? 'bg-purple-500 text-white shadow-lg shadow-purple-500/20' : 'bg-white dark:bg-slate-800 text-purple-600'}`}>
                    <i className="fas fa-book-quran"></i>
                  </div>
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{t('quran')}</p>
                    <p className="text-sm font-black text-emerald-950 dark:text-white">{selectedData.quranDone ? 'Read' : 'Pending'}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4 p-4 rounded-2xl bg-amber-50/50 dark:bg-amber-900/10 border border-amber-100/50 dark:border-amber-900/20">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${selectedData.isFasting ? 'bg-amber-500 text-white shadow-lg shadow-amber-500/20' : 'bg-white dark:bg-slate-800 text-amber-600'}`}>
                    <i className="fas fa-moon"></i>
                  </div>
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{t('fasting')}</p>
                    <p className="text-sm font-black text-emerald-950 dark:text-white">{selectedData.isFasting ? 'Fasting' : 'None'}</p>
                  </div>
                </div>
              </div>

              {/* Legend Summary */}
              <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-800 flex flex-wrap justify-center gap-4">
                 <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
                    <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest">Prayers</span>
                 </div>
                 <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>
                    <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest">Dhikr</span>
                 </div>
                 <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-purple-500"></div>
                    <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest">Quran</span>
                 </div>
                 <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div>
                    <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest">Fast</span>
                 </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PrayerCalendar;

import React, { useState, useEffect } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PersonalDhikr, PrayerTimings, QadaReminder, DhikrHistoryEntry, HealthPeriod, FastingLog, QuranProgress } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import FardPrayers from './components/FardPrayers';
import PrayerCalendar from './components/PrayerCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

const USERS_DB_KEY = 'ibadathi_v6_users_database';
const SESSION_KEY = 'ibadathi_v6_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'لا إله إلا الله', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const INITIAL_PRAYER_REMINDERS = [
  { prayer: 'fajr', time: '05:30', enabled: false },
  { prayer: 'dhuhr', time: '12:30', enabled: false },
  { prayer: 'asr', time: '15:30', enabled: false },
  { prayer: 'maghrib', time: '18:30', enabled: false },
  { prayer: 'isha', time: '19:30', enabled: false },
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let parsedUsers: Record<string, UserData> = {};
    try { parsedUsers = savedUsers ? JSON.parse(savedUsers) : {}; } catch (e) { console.error("Data Parse Error", e); }
    const currentUser = (activeSession && parsedUsers[activeSession.toLowerCase()]) ? activeSession.toLowerCase() : null;
    return { currentUser, users: parsedUsers, todayTimings: DEFAULT_TIMINGS };
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    const session = localStorage.getItem(SESSION_KEY);
    const savedUsers = localStorage.getItem(USERS_DB_KEY);
    let users = {};
    try { users = savedUsers ? JSON.parse(savedUsers) : {}; } catch(e) {}
    if (session && users[session.toLowerCase()]) {
      return users[session.toLowerCase()].profile.preferredLanguage;
    }
    return 'en';
  });

  useEffect(() => {
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
    if (state.currentUser) {
      localStorage.setItem(SESSION_KEY, state.currentUser);
    } else {
      localStorage.removeItem(SESSION_KEY);
    }
  }, [state.users, state.currentUser]);

  // Sync Language with User profile
  useEffect(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      setCurrentLanguage(state.users[state.currentUser].profile.preferredLanguage);
    }
  }, [state.currentUser]);

  // Sync Global Theme classes for background elements
  useEffect(() => {
    // Default to dark if no user logged in, or use the user's saved preference
    const isDark = state.currentUser ? state.users[state.currentUser].settings.theme === 'dark' : true;
    if (isDark) {
      document.body.classList.add('dark', 'dark-mode-active');
    } else {
      document.body.classList.remove('dark', 'dark-mode-active');
    }
  }, [state.currentUser, state.users]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      const updated = updater(prev.users[current]);
      return { ...prev, users: { ...prev.users, [current]: updated } };
    });
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const username = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { 
          notificationsEnabled: false, 
          locationEnabled: false, 
          theme: 'dark', // SET DARK AS DEFAULT FOR NEW USERS
          ecoMode: false,
          qadaReminders: [],
          prayerReminders: INITIAL_PRAYER_REMINDERS
        }
      };
      setState(prev => ({ ...prev, currentUser: username, users: { ...prev.users, [username]: newUserData } }));
    } else {
      setState(prev => ({ ...prev, currentUser: username }));
    }
    setSubView(null);
    setActiveTab('home');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('home');
    setSubView(null);
  };

  const updatePrayerStatus = (date: string, prayer: any, status: PrayerStatus) => {
    updateActiveUser(user => {
      const logs = user.prayerLogs[date] || { fajr: PrayerStatus.PENDING, dhuhr: PrayerStatus.PENDING, asr: PrayerStatus.PENDING, maghrib: PrayerStatus.PENDING, isha: PrayerStatus.PENDING };
      return { ...user, prayerLogs: { ...user.prayerLogs, [date]: { ...logs, [prayer]: status } } };
    });
  };

  const updatePrayerReminder = (prayer: string, time: string, enabled: boolean) => {
    updateActiveUser(user => {
      const currentReminders = user.settings.prayerReminders || INITIAL_PRAYER_REMINDERS;
      const updatedReminders = currentReminders.map(r => 
        r.prayer === prayer ? { ...r, time, enabled } : r
      );
      return {
        ...user,
        settings: {
          ...user.settings,
          prayerReminders: updatedReminders
        }
      };
    });
  };

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;
  const compositeState = state.currentUser ? { ...state.users[state.currentUser], todayTimings: state.todayTimings } : null;

  // Render Logic
  if (!state.currentUser) {
    const isDark = true; // Default to dark when logged out
    return (
      <div className={`app-viewport ${isDark ? 'dark bg-slate-950' : 'bg-ivory'} animate-fade-in`}>
        {subView === 'auth' ? (
          <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} onBack={() => setSubView(null)} />
        ) : (
          <Welcome onEnter={() => setSubView('auth')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
        )}
      </div>
    );
  }

  const renderView = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeState!} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeState!} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeState!} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home': return <Dashboard state={compositeState!} setCurrentView={setSubView} t={t} updatePrayerStatus={updatePrayerStatus} onLogout={handleLogout} />;
      case 'prayer': return <PrayerCalendar state={compositeState!} updatePrayerStatus={updatePrayerStatus} setCurrentView={setSubView} t={t} />;
      case 'challenges': return (
        <DhikrCounter 
          state={compositeState!} 
          updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
          updatePersonalProgress={(id, d) => updateActiveUser(u => {
            const today = new Date().toISOString().split('T')[0];
            const upd = u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd);
            return { ...u, personalDhikrs: upd, dhikrCount: u.dhikrCount + d };
          })}
          addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
          resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
          deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
          archiveChallenge={(id) => updateActiveUser(u => {
            const c = u.activeChallenges.find(x => x.id === id);
            if (!c) return u;
            return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [...u.dhikrHistory, { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() }], activeDhikrId: null };
          })}
          setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))}
          setCurrentView={setSubView} t={t} 
        />
      );
      case 'tracker': return (
        <div className="scroll-container px-6 pt-12 content-limit w-full">
          <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-8 tracking-tighter">My Spiritual Path</h1>
          <div className="grid grid-cols-1 gap-4">
             <div onClick={() => setSubView('quran')} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                <div className="w-16 h-16 bg-amber-50 dark:bg-amber-900/30 text-amber-600 rounded-3xl flex items-center justify-center text-3xl"><i className="fas fa-book-open"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-xl tracking-tight">{t('quran')}</h3>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{compositeState?.quranProgress.surah || 'Not Started'}</p>
                </div>
                <i className="fas fa-chevron-right text-slate-200"></i>
             </div>
             <div onClick={() => setSubView('fasting')} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-3xl flex items-center justify-center text-3xl"><i className="fas fa-moon"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-xl tracking-tight">{t('fasting')}</h3>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Holy Ramadan Log</p>
                </div>
                <i className="fas fa-chevron-right text-slate-200"></i>
             </div>
             <div onClick={() => setSubView('women')} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                <div className="w-16 h-16 bg-rose-50 dark:bg-rose-900/30 text-rose-600 rounded-3xl flex items-center justify-center text-3xl"><i className="fas fa-leaf"></i></div>
                <div className="flex-1">
                  <h3 className="font-black text-emerald-900 dark:text-emerald-50 text-xl tracking-tight">{t('womensSpace')}</h3>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Exemption Tracker</p>
                </div>
                <i className="fas fa-chevron-right text-slate-200"></i>
             </div>
          </div>
        </div>
      );
      case 'account': return <MyAccount state={compositeState!} setCurrentView={setSubView} t={t} onLogout={handleLogout} toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} toggleEcoMode={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, ecoMode: !u.settings.ecoMode } }))} toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} updatePrayerReminder={updatePrayerReminder} />;
      default: return null;
    }
  };

  const isDarkMode = compositeState ? compositeState.settings.theme === 'dark' : true;

  return (
    <div className={`app-viewport ${isDarkMode ? 'dark bg-slate-950' : 'bg-ivory'}`} dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative w-full h-full flex flex-col">
        {renderView()}
      </main>
      {!subView && (
        <nav className="bottom-nav">
          <button onClick={() => setActiveTab('home')} className={`nav-item ${activeTab === 'home' ? 'active' : ''}`}><i className="fas fa-mosque"></i><span className="text-[9px] font-black uppercase tracking-widest">Home</span></button>
          <button onClick={() => setActiveTab('prayer')} className={`nav-item ${activeTab === 'prayer' ? 'active' : ''}`}><i className="fas fa-kaaba"></i><span className="text-[9px] font-black uppercase tracking-widest">Worship</span></button>
          <button onClick={() => setActiveTab('tracker')} className={`nav-item ${activeTab === 'tracker' ? 'active' : ''}`}><i className="fas fa-compass"></i><span className="text-[9px] font-black uppercase tracking-widest">Path</span></button>
          <button onClick={() => setActiveTab('challenges')} className={`nav-item ${activeTab === 'challenges' ? 'active' : ''}`}><i className="fas fa-star-and-crescent"></i><span className="text-[9px] font-black uppercase tracking-widest">Dhikr</span></button>
          <button onClick={() => setActiveTab('account')} className={`nav-item ${activeTab === 'account' ? 'active' : ''}`}><i className="fas fa-user"></i><span className="text-[9px] font-black uppercase tracking-widest">Me</span></button>
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [copied, setCopied] = useState(false);
  const todayStr = currentTime.toISOString().split('T')[0];
  const logs = state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' };

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Update body class for eco mode based on user setting
  useEffect(() => {
    if (state.settings.ecoMode) {
      document.body.classList.add('eco-mode');
    } else {
      // Re-evaluate automatic eco mode logic if needed, but manual setting takes priority
      const isLowEnd = (navigator.hardwareConcurrency && navigator.hardwareConcurrency <= 4);
      if (!isLowEnd) document.body.classList.remove('eco-mode');
    }
  }, [state.settings.ecoMode]);

  const hijriDate = useMemo(() => {
    try {
      return new Intl.DateTimeFormat('en-u-ca-islamic-uma-nu-latn', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      }).format(currentTime);
    } catch (e) {
      return '';
    }
  }, [currentTime]);

  const dailyHadith = useMemo(() => {
    const start = new Date(currentTime.getFullYear(), 0, 0);
    const diff = currentTime.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    const day = Math.floor(diff / oneDay);
    return HADITHS[day % HADITHS.length];
  }, [currentTime.getFullYear()]);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const timingKey = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = state.todayTimings![timingKey].split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![timingKey] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  const handleCopyHadith = () => {
    const text = `${dailyHadith.arabic}\n\n"${dailyHadith[state.profile.preferredLanguage as keyof typeof dailyHadith] || dailyHadith.en}"\n— ${dailyHadith.reference}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="scroll-container px-5 pt-8 content-limit w-full">
      {/* 1. Header - Compact Profile + Hijri Date */}
      <div className="flex justify-between items-start mb-6 animate-fade-up">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center border border-emerald-500/20 text-emerald-500">
            <i className="fas fa-mosque text-sm"></i>
          </div>
          <div>
            <h2 className="text-[8px] font-black text-slate-500 uppercase tracking-widest leading-none mb-1">Assalamu Alaikum</h2>
            <h1 className="text-lg font-black text-emerald-950 dark:text-white tracking-tight leading-none">{state.profile.name}</h1>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <div className="px-3 py-1.5 bg-white/5 dark:bg-white/5 border border-black/5 dark:border-white/10 rounded-xl text-right">
             <p className="text-[7px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest leading-none mb-1">Hijri Date</p>
             <p className="text-[10px] font-bold text-emerald-950 dark:text-white leading-none whitespace-nowrap">{hijriDate}</p>
          </div>
        </div>
      </div>

      {/* 2. Daily Hadith - Minimalist Card */}
      <div className="mb-6 animate-fade-up stagger-1">
        <div className="card-premium relative overflow-hidden">
          <div className="flex justify-between items-center mb-4">
            <span className="text-[8px] font-black text-emerald-600 dark:text-emerald-500 uppercase tracking-[0.2em]">{t('hadithTitle')}</span>
            <button onClick={handleCopyHadith} className="text-slate-400 hover:text-emerald-600 dark:text-slate-500 dark:hover:text-white transition-colors">
              <i className={`fas ${copied ? 'fa-check text-emerald-500' : 'fa-copy'} text-[10px]`}></i>
            </button>
          </div>
          <p className="arabic-font text-xl font-bold text-emerald-950 dark:text-white text-center leading-relaxed mb-4" dir="rtl">
            {dailyHadith.arabic}
          </p>
          <p className="text-xs font-medium text-slate-600 dark:text-slate-400 italic leading-snug text-center px-2">
            "{dailyHadith[state.profile.preferredLanguage as keyof typeof dailyHadith] || dailyHadith.en}"
          </p>
          <div className="mt-4 pt-3 border-t border-black/5 dark:border-white/5 text-center">
            <span className="text-[8px] font-black text-slate-500 dark:text-slate-600 uppercase tracking-widest">{dailyHadith.reference}</span>
          </div>
        </div>
      </div>

      {/* 3. Next Prayer - Condensed Card */}
      <div className="mb-6 animate-fade-up stagger-2">
        <div className="card-premium bg-gradient-to-r from-emerald-600 to-emerald-700 border-none !p-5 flex items-center justify-between shadow-lg">
          <div>
            <h3 className="text-[8px] font-black uppercase tracking-widest text-emerald-100/70 mb-1">{t('nextPrayer')}</h3>
            <div className="flex items-baseline gap-2">
              <span className="text-2xl font-black text-white tracking-tight capitalize">{nextPrayer ? t(nextPrayer.name) : '---'}</span>
              <span className="text-xs font-bold text-emerald-100/60 tabular-nums">@ {nextPrayer?.time}</span>
            </div>
          </div>
          <div className="bg-white/10 backdrop-blur-sm rounded-xl py-2 px-4 border border-white/20 text-center">
             <p className="text-[10px] font-black text-white tabular-nums leading-none">-{nextPrayer?.diffH}h {nextPrayer?.diffM}m</p>
          </div>
        </div>
      </div>

      {/* 4. Prayer Tracker - Smaller & Tighter */}
      <div className="mb-8 animate-fade-up stagger-3">
        <div className="flex justify-between items-center mb-4 px-1">
          <h3 className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Today's Worship</h3>
          <span className="text-[8px] font-black text-emerald-600 dark:text-emerald-500">{PRAYERS.filter(p => logs[p as keyof typeof logs] === 'completed').length}/5 Complete</span>
        </div>

        <div className="flex gap-3 overflow-x-auto no-scrollbar -mx-1 px-1">
          {PRAYERS.map(p => {
            const status = logs[p as keyof typeof logs];
            const isDone = status === PrayerStatus.COMPLETED;
            const isMissed = status === PrayerStatus.MISSED;
            const time = state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings];

            return (
              <button 
                key={p} 
                onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)}
                className={`flex-none w-24 aspect-[4/5] rounded-[1.5rem] border transition-all duration-300 flex flex-col items-center justify-center gap-3 ${
                  isDone 
                    ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-600 dark:text-emerald-500' 
                    : isMissed
                    ? 'bg-rose-500/10 border-rose-500/30 text-rose-600 dark:text-rose-500'
                    : 'bg-white dark:bg-white/5 border-black/5 dark:border-white/10 text-slate-500 dark:text-slate-600'
                }`}
              >
                <div className="text-center">
                  <p className={`text-[7px] font-black uppercase tracking-widest mb-0.5 ${isDone ? 'text-emerald-600 dark:text-emerald-500' : 'text-slate-500 dark:text-slate-600'}`}>{time}</p>
                  <p className={`text-[11px] font-black capitalize ${isDone ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-800 dark:text-slate-300'}`}>{t(p)}</p>
                </div>
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs ${
                  isDone ? 'bg-emerald-500 text-white' : isMissed ? 'bg-rose-500 text-white' : 'bg-black/5 dark:bg-white/5 text-slate-400'
                }`}>
                   <i className={`fas ${isDone ? 'fa-check' : isMissed ? 'fa-xmark' : 'fa-clock'}`}></i>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* 5. Tools Grid - Smaller Heights */}
      <div className="grid grid-cols-2 gap-3 animate-fade-up stagger-4 mb-16">
        <button onClick={() => setCurrentView('quran')} className="card-premium h-20 flex items-center gap-3 !p-3">
          <div className="w-10 h-10 bg-amber-600/10 text-amber-600 rounded-xl flex items-center justify-center text-lg"><i className="fas fa-book-quran"></i></div>
          <div className="text-left overflow-hidden">
            <h4 className="font-black text-xs text-emerald-950 dark:text-white truncate">{t('quran')}</h4>
            <p className="text-[7px] font-bold text-slate-500 dark:text-slate-600 uppercase tracking-widest truncate">{state.quranProgress.surah || 'Track'}</p>
          </div>
        </button>

        <button onClick={() => setCurrentView('qibla')} className="card-premium h-20 flex items-center gap-3 !p-3">
          <div className="w-10 h-10 bg-blue-600/10 text-blue-500 rounded-xl flex items-center justify-center text-lg"><i className="fas fa-compass"></i></div>
          <div className="text-left overflow-hidden">
            <h4 className="font-black text-xs text-emerald-950 dark:text-white truncate">{t('qibla')}</h4>
            <p className="text-[7px] font-bold text-slate-500 dark:text-slate-600 uppercase tracking-widest truncate">Finder</p>
          </div>
        </button>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, UserData, Language } from '../types';

interface LoginProps {
  onLogin: (profile: UserProfile, isNew: boolean) => void;
  t: (key: string) => string;
  initialLanguage: Language;
  users: Record<string, UserData>;
  initialMode?: 'login' | 'register';
  onBack?: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, t, initialLanguage, users, initialMode = 'login', onBack }) => {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    age: '',
    sex: 'male' as 'male' | 'female',
    place: '',
    password: '',
    preferredLanguage: initialLanguage
  });
  const [error, setError] = useState<string | null>(null);

  const usernameNormalized = useMemo(() => formData.username.trim().toLowerCase(), [formData.username]);

  const validate = () => {
    if (!usernameNormalized) return "Username required.";
    if (!formData.password) return "Password required.";
    if (mode === 'register') {
      if (!formData.name.trim()) return "Full name required.";
      if (!formData.age || isNaN(parseInt(formData.age))) return "Valid age required.";
      if (!formData.place.trim()) return "Place required.";
      if (users[usernameNormalized]) return "This username is already taken.";
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }

    setIsAuthenticating(true);
    setTimeout(() => {
      if (mode === 'login') {
        const user = users[usernameNormalized];
        if (!user || user.profile.password !== formData.password) {
          setError(!user ? "User not found." : "Incorrect password.");
          setIsAuthenticating(false);
          return;
        }
        onLogin(user.profile, false);
      } else {
        const newProfile: UserProfile = {
          username: usernameNormalized,
          name: formData.name.trim(),
          age: parseInt(formData.age),
          sex: formData.sex,
          place: formData.place.trim(),
          preferredLanguage: formData.preferredLanguage,
          password: formData.password
        };
        onLogin(newProfile, true);
      }
      setIsAuthenticating(false);
    }, 800);
  };

  const inputClasses = "w-full px-6 py-4 bg-black/5 dark:bg-white/5 border border-black/10 dark:border-white/10 rounded-2xl focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all font-bold text-emerald-950 dark:text-emerald-50 text-sm placeholder:text-slate-400 dark:placeholder:text-slate-500";
  const labelClasses = "block text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2";

  return (
    <div className="flex flex-col h-full bg-ivory dark:bg-[#020617] w-full overflow-hidden animate-fade-up relative">
      <div className="absolute inset-0 bg-mesh opacity-20 pointer-events-none"></div>

      <header className="px-8 pt-12 pb-6 flex items-center justify-between shrink-0 relative z-10">
        <button 
          onClick={onBack} 
          className="w-12 h-12 bg-black/5 dark:bg-white/5 rounded-2xl flex items-center justify-center border border-black/10 dark:border-white/10 active:scale-90 transition-transform"
        >
          <i className="fas fa-chevron-left text-sm text-emerald-900 dark:text-slate-400"></i>
        </button>
      </header>

      <div className="flex-1 overflow-y-auto px-8 py-4 flex flex-col items-center no-scrollbar relative z-10">
        <div className="w-full max-w-[400px]">
          <h2 className="text-3xl font-black text-emerald-950 dark:text-white tracking-tighter mb-2">{mode === 'login' ? 'Welcome Back' : 'Create Account'}</h2>
          <p className="text-slate-500 text-xs font-medium mb-8">{mode === 'login' ? 'Continue your journey of worship.' : 'Join the global community of Ibadathi.'}</p>

          <div className="flex bg-black/5 dark:bg-white/5 p-1 rounded-2xl mb-8 border border-black/5 dark:border-white/10">
            <button 
              onClick={() => setMode('login')} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'login' ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-500'}`}
            >
              Login
            </button>
            <button 
              onClick={() => setMode('register')} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'register' ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-500'}`}
            >
              Register
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-rose-500/10 text-rose-600 dark:text-rose-500 p-4 rounded-2xl text-[10px] font-bold text-center border border-rose-500/20 animate-pop">
                <i className="fas fa-circle-exclamation mr-2"></i> {error}
              </div>
            )}

            <div className="space-y-2">
              <label className={labelClasses}>Username</label>
              <input 
                type="text" 
                placeholder="e.g. believer_1"
                className={inputClasses} 
                value={formData.username} 
                onChange={e => setFormData({...formData, username: e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, '')})} 
                required 
              />
            </div>

            {mode === 'register' && (
              <>
                <div className="space-y-2">
                  <label className={labelClasses}>Full Name</label>
                  <input type="text" placeholder="Your Name" className={inputClasses} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className={labelClasses}>Age</label>
                    <input type="number" placeholder="24" className={inputClasses} value={formData.age} onChange={e => setFormData({...formData, age: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className={labelClasses}>Gender</label>
                    <div className="flex bg-black/5 dark:bg-white/5 p-1 rounded-2xl border border-black/5 dark:border-white/10 h-[58px]">
                      <button type="button" onClick={() => setFormData({...formData, sex: 'male'})} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${formData.sex === 'male' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-500'}`}>M</button>
                      <button type="button" onClick={() => setFormData({...formData, sex: 'female'})} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${formData.sex === 'female' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-500'}`}>F</button>
                    </div>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className={labelClasses}>Place</label>
                  <input type="text" placeholder="e.g. Kerala" className={inputClasses} value={formData.place} onChange={e => setFormData({...formData, place: e.target.value})} required />
                </div>
              </>
            )}

            <div className="space-y-2">
              <label className={labelClasses}>Password</label>
              <input 
                type="password" 
                placeholder="••••••••" 
                className={inputClasses} 
                value={formData.password} 
                onChange={e => setFormData({...formData, password: e.target.value})} 
                required 
              />
            </div>

            <button 
              type="submit"
              disabled={isAuthenticating}
              className="w-full bg-emerald-600 text-white font-black py-5 rounded-2xl transition-all active:scale-95 uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-xl shadow-emerald-500/20 mt-8"
            >
              {isAuthenticating ? (
                <i className="fas fa-spinner fa-spin"></i>
              ) : (
                <>
                  {mode === 'login' ? 'Login' : 'Create Account'}
                  <i className="fas fa-arrow-right text-[8px] opacity-40"></i>
                </>
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo } from 'react';
import { UserData, PrayerStatus, PrayerReminder } from '../types';
import { PRAYERS } from '../constants';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleEcoMode: () => void;
  updatePrayerReminder: (prayer: string, time: string, enabled: boolean) => void;
}

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleEcoMode, updatePrayerReminder }) => {
  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0, missedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
        if (status === PrayerStatus.MISSED) missedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;

    let level = 'levelBeginner', color = 'text-slate-400', icon = 'fa-seedling';
    if (ratio >= 0.9) { level = 'levelElite'; color = 'text-amber-500'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { level = 'levelAdvanced'; color = 'text-emerald-500'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { level = 'levelConsistent'; color = 'text-teal-500'; icon = 'fa-leaf'; }

    return { totalFard, completedFard, missedFard, ratio, level, color, icon };
  }, [state]);

  const prayerReminders = state.settings.prayerReminders || [];
  const isDark = state.settings.theme === 'dark';

  return (
    <div className="scroll-container px-6 pt-12 content-limit w-full">
      {/* Profile Header */}
      <div className="flex items-center justify-between mb-10 animate-fade-up">
         <div>
            <h1 className="text-3xl font-black text-emerald-950 dark:text-white tracking-tighter">{state.profile.name}</h1>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1">@{state.profile.username}</p>
         </div>
         <button onClick={onLogout} className="w-12 h-12 bg-rose-500/10 text-rose-500 rounded-2xl flex items-center justify-center border border-rose-500/20 active:scale-90 transition-transform">
           <i className="fas fa-power-off"></i>
         </button>
      </div>

      {/* Commitment Card */}
      <div className={`card-premium mb-10 flex items-center gap-6 !p-8 animate-fade-up stagger-1`}>
         <div className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center text-4xl shadow-2xl bg-white/5 border border-white/10 ${stats.color}`}>
           <i className={`fas ${stats.icon}`}></i>
         </div>
         <div>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">{t('consistency')}</p>
            <h3 className={`text-2xl font-black tracking-tight ${stats.color}`}>{t(stats.level)}</h3>
            <p className="text-xs font-medium text-slate-500 mt-1">{(stats.ratio * 100).toFixed(0)}% Commitment</p>
         </div>
      </div>

      {/* Detailed Stats */}
      <div className="grid grid-cols-2 gap-4 mb-12 animate-fade-up stagger-2">
         <div className="card-premium flex flex-col items-center !p-6">
            <div className="w-10 h-10 bg-emerald-500/10 text-emerald-500 rounded-xl flex items-center justify-center mb-4"><i className="fas fa-check-double text-xs"></i></div>
            <p className="text-2xl font-black text-emerald-950 dark:text-white">{stats.completedFard}</p>
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">{t('completed')}</p>
         </div>
         <div className="card-premium flex flex-col items-center !p-6">
            <div className="w-10 h-10 bg-rose-500/10 text-rose-500 rounded-xl flex items-center justify-center mb-4"><i className="fas fa-history text-xs"></i></div>
            <p className="text-2xl font-black text-emerald-950 dark:text-white">{stats.missedFard}</p>
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">{t('missed')}</p>
         </div>
      </div>

      {/* Reminders Section */}
      <div className="space-y-6 mb-12 animate-fade-up stagger-3">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Prayer Alerts</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <div className="space-y-3">
           {PRAYERS.map(p => {
             const reminder = prayerReminders.find(r => r.prayer === p) || { prayer: p, time: '12:00', enabled: false };
             return (
               <div key={p} className="card-premium flex items-center justify-between !p-5 group">
                 <div className="flex items-center gap-5">
                   <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-lg ${reminder.enabled ? 'bg-emerald-600 text-white' : 'bg-slate-50 dark:bg-white/5 text-slate-400 dark:text-slate-600'}`}>
                     <i className="fas fa-bell"></i>
                   </div>
                   <div>
                     <span className="font-black text-sm text-emerald-950 dark:text-white capitalize">{t(p)}</span>
                     <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Custom Reminder</p>
                   </div>
                 </div>
                 <div className="flex items-center gap-4">
                   <input 
                     type="time" 
                     className="bg-transparent border-none text-xs font-black text-emerald-600 focus:ring-0 cursor-pointer" 
                     value={reminder.time} 
                     onChange={(e) => updatePrayerReminder(p, e.target.value, reminder.enabled)}
                   />
                   <button 
                     onClick={() => updatePrayerReminder(p, reminder.time, !reminder.enabled)}
                     className={`w-12 h-6 rounded-full p-1 transition-all ${reminder.enabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}
                   >
                     <div className={`w-4 h-4 bg-white rounded-full transition-transform ${reminder.enabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
                   </button>
                 </div>
               </div>
             );
           })}
         </div>
      </div>

      {/* System Settings */}
      <div className="space-y-6 animate-fade-up stagger-4 pb-20">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Preferences</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>

         <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between !p-6 mb-3">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${isDark ? 'bg-indigo-500/10 text-indigo-400' : 'bg-amber-500/10 text-amber-500'}`}>
                 <i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i>
               </div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">{isDark ? 'Dark Theme' : 'Light Theme'}</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Visual Appearance</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${isDark ? 'bg-indigo-600' : 'bg-amber-500'}`}>
               <div className={`w-4 h-4 bg-white rounded-full transition-transform ${isDark ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </div>
         </button>

         <button onClick={toggleEcoMode} className="card-premium w-full flex items-center justify-between !p-6">
            <div className="flex items-center gap-5">
               <div className="w-12 h-12 bg-teal-500/10 text-teal-500 rounded-2xl flex items-center justify-center text-xl"><i className="fas fa-bolt-lightning"></i></div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">Eco Mode</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Performance Optimizer</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${state.settings.ecoMode ? 'bg-teal-600' : 'bg-slate-200 dark:bg-white/10'}`}>
               <div className={`w-4 h-4 bg-white rounded-full transition-transform ${state.settings.ecoMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </div>
         </button>
      </div>
    </div>
  );
};

