                    : isMissed
                    ? 'bg-rose-500/10 border-rose-500/30 text-rose-600 dark:text-rose-500'
                    : 'bg-white dark:bg-slate-900/50 border-black/5 dark:border-white/10 text-slate-500 dark:text-slate-600'
