import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    setIsClient(true);
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = useMemo(() => currentTime.toISOString().split('T')[0], [currentTime]);
  const logs = useMemo(() => state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' }, [state.prayerLogs, todayStr]);

  // Safe client-only Hijri calculation
  const hijriData = useMemo(() => {
    if (!isClient) return { dayMonth: '', year: '---' };
    try {
      const locale = 'en-u-ca-islamic-uma-nu-latn';
      const formatter = new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long', year: 'numeric' });
      const parts = formatter.formatToParts(currentTime);
      const day = parts.find(p => p.type === 'day')?.value;
      const month = parts.find(p => p.type === 'month')?.value;
      const year = parts.find(p => p.type === 'year')?.value;
      return { dayMonth: `${day} ${month}`, year: `${year} AH` };
    } catch (e) {
      return { dayMonth: '---', year: '---' };
    }
  }, [currentTime, isClient]);

  const dailyHadith = useMemo(() => {
    const start = new Date(currentTime.getFullYear(), 0, 0);
    const diff = currentTime.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    const dayIndex = Math.floor(diff / oneDay);
    return HADITHS[dayIndex % HADITHS.length];
  }, [currentTime]);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = (state.todayTimings![key] || "00:00").split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![key] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  return (
    <div className="scroll-container px-5 pt-8 content-limit w-full">
      {/* Header & Hijri Date */}
      <div className="flex flex-col gap-6 mb-8 animate-fade-up">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-emerald-500/10 rounded-2xl flex items-center justify-center border border-emerald-500/20 text-emerald-500">
              <i className="fas fa-mosque text-lg"></i>
            </div>
            <div>
              <h2 className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest leading-none mb-1.5">Assalamu Alaikum</h2>
              <h1 className="text-xl font-black text-emerald-950 dark:text-white tracking-tight leading-none truncate max-w-[150px]">{state.profile.name}</h1>
            </div>
          </div>
          <button onClick={onLogout} className="w-10 h-10 flex items-center justify-center bg-black/5 dark:bg-white/5 rounded-xl text-slate-400 hover:text-rose-500 transition-colors">
            <i className="fas fa-power-off text-sm"></i>
          </button>
        </div>

        {/* Hijri Banner */}
        <div className="card-premium !p-5 bg-gradient-to-br from-white to-emerald-50/30 dark:from-slate-900 dark:to-emerald-950/20 border-emerald-100/50 dark:border-emerald-900/20 flex items-center justify-between shadow-xl shadow-slate-200/50 dark:shadow-none">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-emerald-600 text-white rounded-2xl flex flex-col items-center justify-center shadow-lg shadow-emerald-600/20">
              <span className="text-xs font-black leading-none mb-0.5">{currentTime.getDate()}</span>
              <span className="text-[7px] font-black uppercase tracking-widest leading-none">{currentTime.toLocaleString('default', { month: 'short' })}</span>
            </div>
            <div>
              <h3 className="text-sm font-black text-emerald-900 dark:text-emerald-400 tracking-tight">{hijriData.dayMonth}</h3>
              <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mt-0.5">{hijriData.year} AH • {currentTime.toLocaleDateString(undefined, { weekday: 'long' })}</p>
            </div>
          </div>
          <i className="fas fa-moon text-emerald-200 dark:text-emerald-800 text-3xl opacity-30"></i>
        </div>
      </div>

      {/* Daily Hadith */}
      <div className="mb-8 animate-fade-up stagger-1">
        <div className="card-premium relative overflow-hidden group">
          <span className="text-[8px] font-black text-emerald-600 dark:text-emerald-500 uppercase tracking-[0.2em] block mb-4">{t('hadithTitle')}</span>
          <p className="arabic-font text-2xl font-bold text-emerald-950 dark:text-white text-center leading-relaxed mb-6" dir="rtl">{dailyHadith.arabic}</p>
          <p className="text-xs font-semibold text-slate-600 dark:text-slate-300 italic leading-relaxed text-center opacity-80">"{dailyHadith.en}"</p>
          <div className="mt-6 pt-4 border-t border-black/5 dark:border-white/5 text-center">
            <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em]">{dailyHadith.reference}</span>
          </div>
        </div>
      </div>

      {/* Next Prayer Highlight */}
      <div className="mb-8 animate-fade-up stagger-2">
        <div className="card-premium bg-gradient-to-r from-emerald-600 to-emerald-700 border-none !p-6 flex items-center justify-between shadow-2xl shadow-emerald-600/20">
          <div className="flex items-center gap-5 text-white">
            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md border border-white/20"><i className="fas fa-clock"></i></div>
            <div>
              <h3 className="text-[9px] font-black uppercase tracking-[0.2em] text-emerald-100/70 mb-1">{t('nextPrayer')}</h3>
              <div className="flex items-baseline gap-2">
                <span className="text-2xl font-black tracking-tight capitalize">{nextPrayer ? t(nextPrayer.name) : '---'}</span>
                <span className="text-xs font-bold text-emerald-100/60 tabular-nums">@ {nextPrayer?.time}</span>
              </div>
            </div>
          </div>
          <div className="bg-white/10 backdrop-blur-md rounded-2xl py-2 px-4 border border-white/20 text-center text-white">
             <p className="text-[11px] font-black tabular-nums leading-none">-{nextPrayer?.diffH}h {nextPrayer?.diffM}m</p>
          </div>
        </div>
      </div>

      {/* Prayers Tracker - Compact Version */}
      <div className="mb-8 animate-fade-up stagger-3">
        <div className="flex justify-between items-center mb-5 px-1">
          <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Worship Tracker</h3>
          <span className="text-[9px] font-black text-emerald-600 dark:text-emerald-500">{PRAYERS.filter(p => logs[p as keyof typeof logs] === 'completed').length}/5</span>
        </div>
        <div className="flex gap-3 overflow-x-auto no-scrollbar -mx-1 px-1 py-1">
          {PRAYERS.map(p => {
            const status = logs[p as keyof typeof logs];
            const isDone = status === PrayerStatus.COMPLETED;
            const time = state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings];
            return (
              <button 
                key={p} 
                onClick={() => updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                className={`flex-none w-20 aspect-[4/5] rounded-[1.5rem] border-2 transition-all duration-300 flex flex-col items-center justify-center gap-2 ${
                  isDone 
                    ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-600' 
                    : 'bg-white dark:bg-slate-900 border-black/5 dark:border-white/10 text-slate-400'
                }`}
              >
                <div className="text-center">
                  <p className="text-[7px] font-black uppercase tracking-widest mb-0.5 opacity-60 leading-none">{time}</p>
                  <p className="text-[10px] font-black capitalize leading-none">{t(p)}</p>
                </div>
                <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs transition-all ${
                  isDone ? 'bg-emerald-500 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-800 text-slate-300'
                }`}>
                   <i className={`fas ${isDone ? 'fa-check' : 'fa-clock'}`}></i>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Navigation Tools */}
      <div className="grid grid-cols-2 gap-4 animate-fade-up stagger-4 mb-24">
        <button onClick={() => setCurrentView('quran')} className="card-premium h-24 flex items-center gap-4 !p-4 hover:border-amber-200 transition-colors">
          <div className="w-12 h-12 bg-amber-500/10 text-amber-600 rounded-2xl flex items-center justify-center text-2xl shadow-sm"><i className="fas fa-book-quran"></i></div>
          <div className="text-left overflow-hidden">
            <h4 className="font-black text-sm text-emerald-950 dark:text-white truncate">{t('quran')}</h4>
            <p className="text-[8px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest truncate">{state.quranProgress.surah || 'Not Started'}</p>
          </div>
        </button>
        <button onClick={() => setCurrentView('qibla')} className="card-premium h-24 flex items-center gap-4 !p-4 hover:border-blue-200 transition-colors">
          <div className="w-12 h-12 bg-blue-500/10 text-blue-500 rounded-2xl flex items-center justify-center text-2xl shadow-sm"><i className="fas fa-compass"></i></div>
          <div className="text-left overflow-hidden">
            <h4 className="font-black text-sm text-emerald-950 dark:text-white truncate">{t('qibla')}</h4>
            <p className="text-[8px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest truncate">Direction</p>
          </div>
        </button>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import PrayerCalendar from './components/PrayerCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// External dependency for prayer times calculation
import { PrayerTimes, Coordinates, CalculationMethod } from 'https://esm.sh/adhan@4.4.0';

const USERS_DB_KEY = 'ibadathi_v6_users_database';
const SESSION_KEY = 'ibadathi_v6_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'ലാ ഇലാഹ ഇല്ലല്ലാഹ്', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [isMounted, setIsMounted] = useState(false);
  const [state, setState] = useState<AppState>({
    currentUser: null,
    users: {},
    todayTimings: DEFAULT_TIMINGS,
    location: null
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState<Language>('en');
  const [qadahWarning, setQadahWarning] = useState<{ name: string; minutes: number } | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const lastAlertedPrayer = useRef<string | null>(null);

  // Initialize client-side data
  useEffect(() => {
    setIsMounted(true);
    try {
      const savedUsers = localStorage.getItem(USERS_DB_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      let parsedUsers: Record<string, UserData> = {};
      if (savedUsers) parsedUsers = JSON.parse(savedUsers);
      const currentUser = (activeSession && parsedUsers[activeSession.toLowerCase()]) ? activeSession.toLowerCase() : null;

      setState(prev => ({
        ...prev,
        users: parsedUsers,
        currentUser: currentUser
      }));
    } catch (e) {
      console.error("Local Storage Initialization Error", e);
    }
  }, []);

  // Sync Global Theme & Body Classes
  useEffect(() => {
    if (!isMounted) return;

    if (state.currentUser && state.users[state.currentUser]) {
      const user = state.users[state.currentUser];
      setCurrentLanguage(user.profile.preferredLanguage);
      const isDark = user.settings.theme === 'dark';
      document.body.classList.toggle('dark', isDark);
      document.body.classList.toggle('dark-mode-active', isDark);

      if (user.settings.ecoMode) {
        document.body.classList.add('eco-mode');
      } else {
        document.body.classList.remove('eco-mode');
      }
    } else {
      document.body.classList.add('dark', 'dark-mode-active');
    }
  }, [state.currentUser, state.users, isMounted]);

  // Persist Data Changes
  useEffect(() => {
    if (!isMounted) return;
    try {
      localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
      if (state.currentUser) {
        localStorage.setItem(SESSION_KEY, state.currentUser);
      } else {
        localStorage.removeItem(SESSION_KEY);
      }
    } catch (e) {
      console.warn("Storage Sync Failed", e);
    }
  }, [state.users, state.currentUser, isMounted]);

  // Automated Location-Based Prayer Timings
  useEffect(() => {
    if (!isMounted) return;

    const updateTimings = () => {
      if (!("geolocation" in navigator)) return;

      navigator.geolocation.getCurrentPosition((pos) => {
        try {
          const coords = new Coordinates(pos.coords.latitude, pos.coords.longitude);
          const params = CalculationMethod.MuslimWorldLeague();
          const date = new Date();
          const prayerTimes = new PrayerTimes(coords, date, params);
          const format = (t: Date) => t.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

          const newTimings: PrayerTimings = {
            Fajr: format(prayerTimes.fajr),
            Sunrise: format(prayerTimes.sunrise),
            Dhuhr: format(prayerTimes.dhuhr),
            Asr: format(prayerTimes.asr),
            Maghrib: format(prayerTimes.maghrib),
            Isha: format(prayerTimes.isha),
          };

          setState(prev => ({ 
            ...prev, 
            location: { lat: pos.coords.latitude, lng: pos.coords.longitude }, 
            todayTimings: newTimings 
          }));
        } catch (e) {
          console.error("Adhan Calculation Error", e);
        }
      }, (err) => {
        console.warn("Location Access Denied. Falling back to default timings.");
      });
    };

    updateTimings();
    const interval = setInterval(updateTimings, 1800000); // Sync every 30 mins
    return () => clearInterval(interval);
  }, [isMounted]);

  // Global Warning Logic: Nearly Qadah
  useEffect(() => {
    if (!isMounted || !state.currentUser || !state.todayTimings || !state.location) return;

    const checkQadahWarning = () => {
      const now = new Date();
      const coords = new Coordinates(state.location!.lat, state.location!.lng);
      const params = CalculationMethod.MuslimWorldLeague();
      const prayerTimes = new PrayerTimes(coords, now, params);

      // Determine the current prayer and its end time
      const current = prayerTimes.currentPrayer();
      let endTime: Date | null = null;
      let prayerName = "";

      switch(current) {
        case "fajr": endTime = prayerTimes.sunrise; prayerName = "fajr"; break;
        case "dhuhr": endTime = prayerTimes.asr; prayerName = "dhuhr"; break;
        case "asr": endTime = prayerTimes.maghrib; prayerName = "asr"; break;
        case "maghrib": endTime = prayerTimes.isha; prayerName = "maghrib"; break;
        case "isha": 
          const tomorrow = new Date(); tomorrow.setDate(now.getDate() + 1);
          const nextDayPrayers = new PrayerTimes(coords, tomorrow, params);
          endTime = nextDayPrayers.fajr; prayerName = "isha"; 
          break;
        default: endTime = null;
      }

      if (endTime && prayerName) {
        const diffMs = endTime.getTime() - now.getTime();
        const diffMins = Math.floor(diffMs / 60000);

        const todayStr = now.toISOString().split('T')[0];
        const user = state.users[state.currentUser!];
        const logs = user.prayerLogs[todayStr] || {};
        const isDone = logs[prayerName as keyof typeof logs] === PrayerStatus.COMPLETED;

        // Trigger warning bar if less than 15 minutes left and not completed
        if (diffMins > 0 && diffMins <= 15 && !isDone) {
          setQadahWarning({ name: prayerName, minutes: diffMins });
        } else {
          setQadahWarning(null);
        }
      } else {
        setQadahWarning(null);
      }
    };

    checkQadahWarning();
    const interval = setInterval(checkQadahWarning, 30000);
    return () => clearInterval(interval);
  }, [state.todayTimings, state.currentUser, state.users, state.location, isMounted]);

  // Fully Automated Background Alarm System
  useEffect(() => {
    if (!isMounted || !state.currentUser || !state.todayTimings) return;

    const checkAlarms = () => {
      const user = state.users[state.currentUser!];
      // Only trigger if global notifications are enabled for the profile
      if (!user?.settings.notificationsEnabled) return;

      const now = new Date();
      const timeStr = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

      // Find if any prayer time matches current minute exactly
      const matchingPrayer = PRAYERS.find(p => {
        const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
        return state.todayTimings![key] === timeStr;
      });

      if (matchingPrayer && lastAlertedPrayer.current !== `${matchingPrayer}-${timeStr}`) {
        // Handle Browser Notification
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification(TRANSLATIONS[currentLanguage]['prayerAlertTitle'] || 'Ibadathi (عبادتي)', {
            body: (TRANSLATIONS[currentLanguage]['prayerAlertBody'] || 'It is time for {prayer} prayer.').replace('{prayer}', TRANSLATIONS[currentLanguage][matchingPrayer] || matchingPrayer),
            icon: 'https://picsum.photos/192/192'
          });
        }

        // Handle Subtle Audio Notification
        if (!audioRef.current) {
          audioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
          audioRef.current.volume = 0.4;
        }
        audioRef.current.play().catch(() => {
          // Quietly fail if audio blocked by browser policy
        });

        lastAlertedPrayer.current = `${matchingPrayer}-${timeStr}`;
      }
    };

    const interval = setInterval(checkAlarms, 30000); // Check every 30 seconds
    return () => clearInterval(interval);
  }, [state.todayTimings, state.currentUser, state.users, currentLanguage, isMounted]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const userKey = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username: userKey },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { 
          notificationsEnabled: true, 
          locationEnabled: true, 
          theme: 'dark', 
          ecoMode: false
        }
      };
      setState(prev => ({ ...prev, currentUser: userKey, users: { ...prev.users, [userKey]: newUserData } }));
    } else {
      setState(prev => ({ ...prev, currentUser: userKey }));
    }
    setSubView(null);
    setActiveTab('home');
    if ("Notification" in window) Notification.requestPermission();
  };

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;
  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  if (!isMounted) return <div className="app-viewport bg-slate-950"></div>;

  if (!state.currentUser) {
    return (
      <div className="app-viewport dark bg-slate-950 animate-fade-in">
        {subView === 'auth' ? (
          <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} onBack={() => setSubView(null)} />
        ) : (
          <Welcome onEnter={() => setSubView('auth')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
        )}
      </div>
    );
  }

  const compositeData = { ...currentUserData!, todayTimings: state.todayTimings };

  const renderActiveView = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeData} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeData} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeData} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home': return <Dashboard state={compositeData} setCurrentView={setSubView} t={t} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} />;
      case 'prayer': return <PrayerCalendar state={compositeData} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} setCurrentView={setSubView} t={t} />;
      case 'challenges': return (
        <DhikrCounter 
          state={compositeData} 
          updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
          updatePersonalProgress={(id, d) => updateActiveUser(u => {
            const today = new Date().toISOString().split('T')[0];
            return { ...u, personalDhikrs: u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd), dhikrCount: u.dhikrCount + d };
          })}
          addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
          resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
          deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
          archiveChallenge={(id) => updateActiveUser(u => {
            const c = u.activeChallenges.find(x => x.id === id);
            if (!c) return u;
            return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [...u.dhikrHistory, { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() }], activeDhikrId: null };
          })}
          setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))}
          setCurrentView={setSubView} t={t} 
        />
      );
      case 'tracker': return (
        <div className="scroll-container px-6 pt-12 content-limit w-full">
          <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-8 tracking-tighter">My Path</h1>
          <div className="grid grid-cols-1 gap-4">
             {[{ view: 'quran', icon: 'fa-book-open', title: 'quran', color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/30' },
               { view: 'fasting', icon: 'fa-moon', title: 'fasting', color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/30' },
               { view: 'women', icon: 'fa-leaf', title: 'womensSpace', color: 'text-rose-600', bg: 'bg-rose-50 dark:bg-rose-900/30' }].map(item => (
                <div key={item.view} onClick={() => setSubView(item.view)} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                   <div className={`w-16 h-16 ${item.bg} ${item.color} rounded-3xl flex items-center justify-center text-3xl`}><i className={`fas ${item.icon}`}></i></div>
                   <div className="flex-1">
                     <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tight">{t(item.title)}</h3>
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Worship Insights</p>
                   </div>
                   <i className="fas fa-chevron-right text-slate-200"></i>
                </div>
             ))}
          </div>
        </div>
      );
      case 'account': return <MyAccount state={compositeData} setCurrentView={setSubView} t={t} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} toggleEcoMode={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, ecoMode: !u.settings.ecoMode } }))} toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} />;
      default: return null;
    }
  };

  return (
    <div className={`app-viewport ${compositeData.settings.theme === 'dark' ? 'dark bg-slate-950' : 'bg-ivory'}`} dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      {/* Visual Qadah Warning Bar */}
      {qadahWarning && (
        <div className="fixed top-0 left-0 right-0 z-[1000] animate-fade-down">
          <div className="mx-auto max-w-lg mt-4 px-4">
            <div className="bg-rose-600 text-white py-3 px-6 rounded-2xl shadow-2xl flex items-center justify-between border border-rose-500/30 backdrop-blur-md relative overflow-hidden group">
              <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite] pointer-events-none"></div>
              <div className="flex items-center gap-4 relative z-10">
                <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center text-xs animate-[bounce_1s_infinite]">
                  <i className="fas fa-clock"></i>
                </div>
                <div>
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] leading-none opacity-80 mb-1">Time Alert</p>
                  <p className="text-xs font-black tracking-tight capitalize leading-none">
                    {t(qadahWarning.name)} ends in {qadahWarning.minutes}m
                  </p>
                </div>
              </div>
              <button 
                onClick={() => setActiveTab('home')}
                className="relative z-10 bg-white/20 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest active:scale-95 transition-transform"
              >
                Log Now
              </button>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 overflow-hidden relative w-full h-full flex flex-col">
        {renderActiveView()}
      </main>
      {!subView && (
        <nav className="bottom-nav">
          {[
            { id: 'home', icon: 'fa-mosque' },
            { id: 'prayer', icon: 'fa-kaaba' },
            { id: 'tracker', icon: 'fa-compass' },
            { id: 'challenges', icon: 'fa-star-and-crescent' },
            { id: 'account', icon: 'fa-user' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`nav-item ${activeTab === tab.id ? 'active' : ''}`}>
              <i className={`fas ${tab.icon}`}></i>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.id}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

export type Language = 'en' | 'ml' | 'ta' | 'ar';

export enum PrayerStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  MISSED = 'missed',
  EXCUSED = 'excused'
}

export interface UserProfile {
  username: string;
  name: string;
  age: number;
  sex: 'male' | 'female';
  place: string;
  preferredLanguage: Language;
  password?: string; // Stored in mock backend
}

export interface PrayerLog {
  fajr: PrayerStatus;
  dhuhr: PrayerStatus;
  asr: PrayerStatus;
  maghrib: PrayerStatus;
  isha: PrayerStatus;
}

export interface FastingLog {
  status: 'none' | 'completed' | 'missed' | 'excused';
  type: 'ramadan' | 'sunnah';
}

export interface QuranProgress {
  surah: string;
  ayah: string;
  // Added juz property to track Quran progress by Juz
  juz: string;
  lastUpdated: string;
}

export interface DhikrChallenge {
  id: string;
  title: string;
  arabic: string;
  target: number;
  current: number;
  lastReset?: string;
}

export interface PersonalDhikr {
  id: string;
  name: string;
  totalCount: number;
  dailyCount: number;
  sessionCount: number;
  lastUpdated: string;
}

export interface DhikrHistoryEntry {
  id: string;
  title: string;
  target: number;
  current: number;
  date: string;
}

export interface PrayerTimings {
  Fajr: string;
  Dhuhr: string;
  Asr: string;
  Maghrib: string;
  Isha: string;
  Sunrise: string;
}

export interface QadaReminder {
  id: string;
  time: string;
  enabled: boolean;
}

export interface PrayerReminder {
  prayer: string;
  time: string;
  enabled: boolean;
}

export interface HealthPeriod {
  id: string;
  start: string; // ISO Date string
  end: string | null; // null if active
}

// This represents the data for a SINGLE user
export interface UserData {
  profile: UserProfile;
  prayerLogs: Record<string, PrayerLog>;
  sunnahLogs: Record<string, string[]>;
  fastingLogs: Record<string, FastingLog>;
  quranProgress: QuranProgress;
  dhikrCount: number;
  activeChallenges: DhikrChallenge[];
  personalDhikrs: PersonalDhikr[];
  activeDhikrId: string | null; // Tracked active challenge for the counter
  dhikrHistory: DhikrHistoryEntry[];
  isHaydNifas: boolean;
  haydStartDate: string | null;
  healthPeriods: HealthPeriod[];
  settings: {
    notificationsEnabled: boolean;
    locationEnabled: boolean;
    theme: 'light' | 'dark';
    ecoMode: boolean; // Optimize for low-end devices
    qadaReminders: QadaReminder[];
    prayerReminders: PrayerReminder[];
  };
}

export interface AppState {
  currentUser: string | null; // username
  users: Record<string, UserData>; // Mock database
  todayTimings: PrayerTimings | null;
  // Added location property to AppState to resolve type errors in App.tsx state management.
  location: { lat: number; lng: number } | null;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import PrayerCalendar from './components/PrayerCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

// External dependency for prayer times calculation
import { PrayerTimes, Coordinates, CalculationMethod } from 'https://esm.sh/adhan@4.4.0';

const USERS_DB_KEY = 'ibadathi_v6_users_database';
const SESSION_KEY = 'ibadathi_v6_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'ലാ ഇലാഹ ഇല്ലല്ലാഹ്', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [isMounted, setIsMounted] = useState(false);
  const [state, setState] = useState<AppState>({
    currentUser: null,
    users: {},
    todayTimings: DEFAULT_TIMINGS,
    location: null
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState<Language>('en');
  const [qadahWarning, setQadahWarning] = useState<{ name: string; minutes: number } | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const lastAlertedPrayer = useRef<string | null>(null);

  // Initialize client-side data
  useEffect(() => {
    setIsMounted(true);
    try {
      const savedUsers = localStorage.getItem(USERS_DB_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      let parsedUsers: Record<string, UserData> = {};
      if (savedUsers) parsedUsers = JSON.parse(savedUsers);
      const currentUser = (activeSession && parsedUsers[activeSession.toLowerCase()]) ? activeSession.toLowerCase() : null;

      setState(prev => ({
        ...prev,
        users: parsedUsers,
        currentUser: currentUser
      }));
    } catch (e) {
      console.error("Local Storage Initialization Error", e);
    }
  }, []);

  // Sync Global Theme & Body Classes
  useEffect(() => {
    if (!isMounted) return;

    if (state.currentUser && state.users[state.currentUser]) {
      const user = state.users[state.currentUser];
      setCurrentLanguage(user.profile.preferredLanguage);
      const isDark = user.settings.theme === 'dark';
      document.body.classList.toggle('dark', isDark);
      document.body.classList.toggle('dark-mode-active', isDark);

      if (user.settings.ecoMode) {
        document.body.classList.add('eco-mode');
      } else {
        document.body.classList.remove('eco-mode');
      }
    } else {
      document.body.classList.add('dark', 'dark-mode-active');
    }
  }, [state.currentUser, state.users, isMounted]);

  // Persist Data Changes
  useEffect(() => {
    if (!isMounted) return;
    try {
      localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
      if (state.currentUser) {
        localStorage.setItem(SESSION_KEY, state.currentUser);
      } else {
        localStorage.removeItem(SESSION_KEY);
      }
    } catch (e) {
      console.warn("Storage Sync Failed", e);
    }
  }, [state.users, state.currentUser, isMounted]);

  // Automated Location-Based Prayer Timings
  useEffect(() => {
    if (!isMounted) return;

    const updateTimings = () => {
      if (!("geolocation" in navigator)) return;

      navigator.geolocation.getCurrentPosition((pos) => {
        try {
          const coords = new Coordinates(pos.coords.latitude, pos.coords.longitude);
          const params = CalculationMethod.MuslimWorldLeague();
          const date = new Date();
          const prayerTimes = new PrayerTimes(coords, date, params);
          const format = (t: Date) => t.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

          const newTimings: PrayerTimings = {
            Fajr: format(prayerTimes.fajr),
            Sunrise: format(prayerTimes.sunrise),
            Dhuhr: format(prayerTimes.dhuhr),
            Asr: format(prayerTimes.asr),
            Maghrib: format(prayerTimes.maghrib),
            Isha: format(prayerTimes.isha),
          };

          setState(prev => ({ 
            ...prev, 
            location: { lat: pos.coords.latitude, lng: pos.coords.longitude }, 
            todayTimings: newTimings 
          }));
        } catch (e) {
          console.error("Adhan Calculation Error", e);
        }
      }, (err) => {
        console.warn("Location Access Denied. Falling back to default timings.");
      });
    };

    updateTimings();
    const interval = setInterval(updateTimings, 1800000); // Sync every 30 mins
    return () => clearInterval(interval);
  }, [isMounted]);

  // Global Warning Logic: Nearly Qadah
  useEffect(() => {
    if (!isMounted || !state.currentUser || !state.todayTimings || !state.location) return;

    const checkQadahWarning = () => {
      const now = new Date();
      const coords = new Coordinates(state.location!.lat, state.location!.lng);
      const params = CalculationMethod.MuslimWorldLeague();
      const prayerTimes = new PrayerTimes(coords, now, params);

      // Determine the current prayer and its end time
      const current = prayerTimes.currentPrayer();
      let endTime: Date | null = null;
      let prayerName = "";

      switch(current) {
        case "fajr": endTime = prayerTimes.sunrise; prayerName = "fajr"; break;
        case "dhuhr": endTime = prayerTimes.asr; prayerName = "dhuhr"; break;
        case "asr": endTime = prayerTimes.maghrib; prayerName = "asr"; break;
        case "maghrib": endTime = prayerTimes.isha; prayerName = "maghrib"; break;
        case "isha": 
          const tomorrow = new Date(); tomorrow.setDate(now.getDate() + 1);
          const nextDayPrayers = new PrayerTimes(coords, tomorrow, params);
          endTime = nextDayPrayers.fajr; prayerName = "isha"; 
          break;
        default: endTime = null;
      }

      if (endTime && prayerName) {
        const diffMs = endTime.getTime() - now.getTime();
        const diffMins = Math.floor(diffMs / 60000);

        const todayStr = now.toISOString().split('T')[0];
        const user = state.users[state.currentUser!];
        const logs = user.prayerLogs[todayStr] || {};
        const isDone = logs[prayerName as keyof typeof logs] === PrayerStatus.COMPLETED;

        // Trigger warning bar if less than 15 minutes left and not completed
        if (diffMins > 0 && diffMins <= 15 && !isDone) {
          setQadahWarning({ name: prayerName, minutes: diffMins });
        } else {
          setQadahWarning(null);
        }
      } else {
        setQadahWarning(null);
      }
    };

    checkQadahWarning();
    const interval = setInterval(checkQadahWarning, 30000);
    return () => clearInterval(interval);
  }, [state.todayTimings, state.currentUser, state.users, state.location, isMounted]);

  // Fully Automated Background Alarm System
  useEffect(() => {
    if (!isMounted || !state.currentUser || !state.todayTimings) return;

    const checkAlarms = () => {
      const user = state.users[state.currentUser!];
      // Only trigger if global notifications are enabled for the profile
      if (!user?.settings.notificationsEnabled) return;

      const now = new Date();
      const timeStr = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

      // Find if any prayer time matches current minute exactly
      const matchingPrayer = PRAYERS.find(p => {
        const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
        return state.todayTimings![key] === timeStr;
      });

      if (matchingPrayer && lastAlertedPrayer.current !== `${matchingPrayer}-${timeStr}`) {
        // Handle Browser Notification
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification(TRANSLATIONS[currentLanguage]['prayerAlertTitle'] || 'Ibadathi (عبادتي)', {
            body: (TRANSLATIONS[currentLanguage]['prayerAlertBody'] || 'It is time for {prayer} prayer.').replace('{prayer}', TRANSLATIONS[currentLanguage][matchingPrayer] || matchingPrayer),
            icon: 'https://picsum.photos/192/192'
          });
        }

        // Handle Subtle Audio Notification
        if (!audioRef.current) {
          audioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
          audioRef.current.volume = 0.4;
        }
        audioRef.current.play().catch(() => {
          // Quietly fail if audio blocked by browser policy
        });

        lastAlertedPrayer.current = `${matchingPrayer}-${timeStr}`;
      }
    };

    const interval = setInterval(checkAlarms, 30000); // Check every 30 seconds
    return () => clearInterval(interval);
  }, [state.todayTimings, state.currentUser, state.users, currentLanguage, isMounted]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const userKey = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username: userKey },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { 
          notificationsEnabled: true, 
          locationEnabled: true, 
          theme: 'dark', 
          ecoMode: false,
          // Fixed: Added missing qadaReminders and prayerReminders to initialize user settings correctly.
          qadaReminders: [],
          prayerReminders: []
        }
      };
      setState(prev => ({ ...prev, currentUser: userKey, users: { ...prev.users, [userKey]: newUserData } }));
    } else {
      setState(prev => ({ ...prev, currentUser: userKey }));
    }
    setSubView(null);
    setActiveTab('home');
    if ("Notification" in window) Notification.requestPermission();
  };

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;
  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  if (!isMounted) return <div className="app-viewport bg-slate-950"></div>;

  if (!state.currentUser) {
    return (
      <div className="app-viewport dark bg-slate-950 animate-fade-in">
        {subView === 'auth' ? (
          <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} onBack={() => setSubView(null)} />
        ) : (
          <Welcome onEnter={() => setSubView('auth')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
        )}
      </div>
    );
  }

  const compositeData = { ...currentUserData!, todayTimings: state.todayTimings };

  const renderActiveView = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeData} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeData} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeData} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home': return <Dashboard state={compositeData} setCurrentView={setSubView} t={t} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} />;
      case 'prayer': return <PrayerCalendar state={compositeData} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} setCurrentView={setSubView} t={t} />;
      case 'challenges': return (
        <DhikrCounter 
          state={compositeData} 
          updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
          updatePersonalProgress={(id, d) => updateActiveUser(u => {
            const today = new Date().toISOString().split('T')[0];
            return { ...u, personalDhikrs: u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd), dhikrCount: u.dhikrCount + d };
          })}
          addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
          resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
          deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
          archiveChallenge={(id) => updateActiveUser(u => {
            const c = u.activeChallenges.find(x => x.id === id);
            if (!c) return u;
            return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [...u.dhikrHistory, { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() }], activeDhikrId: null };
          })}
          setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))}
          setCurrentView={setSubView} t={t} 
        />
      );
      case 'tracker': return (
        <div className="scroll-container px-6 pt-12 content-limit w-full">
          <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-8 tracking-tighter">My Path</h1>
          <div className="grid grid-cols-1 gap-4">
             {[{ view: 'quran', icon: 'fa-book-open', title: 'quran', color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/30' },
               { view: 'fasting', icon: 'fa-moon', title: 'fasting', color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/30' },
               { view: 'women', icon: 'fa-leaf', title: 'womensSpace', color: 'text-rose-600', bg: 'bg-rose-50 dark:bg-rose-900/30' }].map(item => (
                <div key={item.view} onClick={() => setSubView(item.view)} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                   <div className={`w-16 h-16 ${item.bg} ${item.color} rounded-3xl flex items-center justify-center text-3xl`}><i className={`fas ${item.icon}`}></i></div>
                   <div className="flex-1">
                     <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tight">{t(item.title)}</h3>
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Worship Insights</p>
                   </div>
                   <i className="fas fa-chevron-right text-slate-200"></i>
                </div>
             ))}
          </div>
        </div>
      );
      case 'account': return <MyAccount state={compositeData} setCurrentView={setSubView} t={t} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} toggleEcoMode={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, ecoMode: !u.settings.ecoMode } }))} toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} />;
      default: return null;
    }
  };

  return (
    <div className={`app-viewport ${compositeData.settings.theme === 'dark' ? 'dark bg-slate-950' : 'bg-ivory'}`} dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      {/* Visual Qadah Warning Bar */}
      {qadahWarning && (
        <div className="fixed top-0 left-0 right-0 z-[1000] animate-fade-down">
          <div className="mx-auto max-w-lg mt-4 px-4">
            <div className="bg-rose-600 text-white py-3 px-6 rounded-2xl shadow-2xl flex items-center justify-between border border-rose-500/30 backdrop-blur-md relative overflow-hidden group">
              <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite] pointer-events-none"></div>
              <div className="flex items-center gap-4 relative z-10">
                <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center text-xs animate-[bounce_1s_infinite]">
                  <i className="fas fa-clock"></i>
                </div>
                <div>
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] leading-none opacity-80 mb-1">Time Alert</p>
                  <p className="text-xs font-black tracking-tight capitalize leading-none">
                    {t(qadahWarning.name)} ends in {qadahWarning.minutes}m
                  </p>
                </div>
              </div>
              <button 
                onClick={() => setActiveTab('home')}
                className="relative z-10 bg-white/20 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest active:scale-95 transition-transform"
              >
                Log Now
              </button>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 overflow-hidden relative w-full h-full flex flex-col">
        {renderActiveView()}
      </main>
      {!subView && (
        <nav className="bottom-nav">
          {[
            { id: 'home', icon: 'fa-mosque' },
            { id: 'prayer', icon: 'fa-kaaba' },
            { id: 'tracker', icon: 'fa-compass' },
            { id: 'challenges', icon: 'fa-star-and-crescent' },
            { id: 'account', icon: 'fa-user' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`nav-item ${activeTab === tab.id ? 'active' : ''}`}>
              <i className={`fas ${tab.icon}`}></i>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.id}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { UserData, PrayerStatus, PrayerReminder, FastingLog } from '../types';
import { PRAYERS } from '../constants';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleEcoMode: () => void;
  updatePrayerReminder: (prayer: string, time: string, enabled: boolean) => void;
}

type Period = 'weekly' | 'monthly' | 'yearly';

const MyAccount: React.FC<MyAccountProps> = ({ state, setCurrentView, t, onLogout, toggleTheme, toggleEcoMode, updatePrayerReminder }) => {
  const [activePeriod, setActivePeriod] = useState<Period>('weekly');

  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0, missedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
        if (status === PrayerStatus.MISSED) missedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;

    let level = 'levelBeginner', color = 'text-slate-400', icon = 'fa-seedling';
    if (ratio >= 0.9) { level = 'levelElite'; color = 'text-amber-500'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { level = 'levelAdvanced'; color = 'text-emerald-500'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { level = 'levelConsistent'; color = 'text-teal-500'; icon = 'fa-leaf'; }

    return { totalFard, completedFard, missedFard, ratio, level, color, icon };
  }, [state]);

  const periodStats = useMemo(() => {
    const now = new Date();
    const days = activePeriod === 'weekly' ? 7 : activePeriod === 'monthly' ? 30 : 365;
    const dateRange = Array.from({ length: days }, (_, i) => {
      const d = new Date();
      d.setDate(now.getDate() - i);
      return d.toISOString().split('T')[0];
    });

    let fardComp = 0, sunnahDays = 0, fastingComp = 0, dhikrDays = 0;

    dateRange.forEach(date => {
      // Fard
      const fLog = state.prayerLogs[date];
      if (fLog) {
        PRAYERS.forEach(p => { if (fLog[p] === PrayerStatus.COMPLETED) fardComp++; });
      }
      // Sunnah
      if (state.sunnahLogs[date] && state.sunnahLogs[date].length > 0) sunnahDays++;
      // Fasting
      const fastLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(date))?.[1] as FastingLog | undefined;
      if (fastLog?.status === 'completed') fastingComp++;
    });

    // Dhikr history - check unique dates in history within range
    const dhikrHistoryInRange = state.dhikrHistory.filter(h => {
      const hDate = h.date.split('T')[0];
      return dateRange.includes(hDate);
    });
    dhikrDays = new Set(dhikrHistoryInRange.map(h => h.date.split('T')[0])).size;

    return {
      fard: Math.min(100, (fardComp / (days * 5)) * 100),
      sunnah: Math.min(100, (sunnahDays / days) * 100),
      fasting: Math.min(100, (fastingComp / (activePeriod === 'yearly' ? 30 : days)) * 100), // Normalize fasting for yearly (approx ramadan)
      dhikr: Math.min(100, (dhikrDays / days) * 100)
    };
  }, [activePeriod, state]);

  const prayerReminders = state.settings.prayerReminders || [];
  const isDark = state.settings.theme === 'dark';

  const ProgressStat = ({ label, value, color, icon }: { label: string, value: number, color: string, icon: string }) => (
    <div className="space-y-2">
      <div className="flex justify-between items-end px-1">
        <div className="flex items-center gap-2">
          <i className={`fas ${icon} ${color} text-[10px]`}></i>
          <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{label}</span>
        </div>
        <span className={`text-[11px] font-black ${color}`}>{value.toFixed(0)}%</span>
      </div>
      <div className="h-2 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
        <div 
          className={`h-full ${color.replace('text', 'bg')} transition-all duration-1000 ease-out`} 
          style={{ width: `${value}%` }}
        ></div>
      </div>
    </div>
  );

  return (
    <div className="scroll-container px-6 pt-12 content-limit w-full">
      {/* Profile Header */}
      <div className="flex items-center justify-between mb-10 animate-fade-up">
         <div>
            <h1 className="text-3xl font-black text-emerald-950 dark:text-white tracking-tighter">{state.profile.name}</h1>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1">@{state.profile.username}</p>
         </div>
         <button onClick={onLogout} className="w-12 h-12 bg-rose-500/10 text-rose-500 rounded-2xl flex items-center justify-center border border-rose-500/20 active:scale-90 transition-transform">
           <i className="fas fa-power-off"></i>
         </button>
      </div>

      {/* Commitment Card */}
      <div className={`card-premium mb-10 flex items-center gap-6 !p-8 animate-fade-up stagger-1`}>
         <div className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center text-4xl shadow-2xl bg-white/5 border border-white/10 ${stats.color}`}>
           <i className={`fas ${stats.icon}`}></i>
         </div>
         <div>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">{t('consistency')}</p>
            <h3 className={`text-2xl font-black tracking-tight ${stats.color}`}>{t(stats.level)}</h3>
            <p className="text-xs font-medium text-slate-500 mt-1">{(stats.ratio * 100).toFixed(0)}% Commitment</p>
         </div>
      </div>

      {/* NEW: Progress Overview Section */}
      <div className="mb-12 animate-fade-up stagger-1.5">
        <div className="flex items-center justify-between mb-6 px-1">
          <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Progress Overview</h4>
          <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-xl">
            {(['weekly', 'monthly', 'yearly'] as Period[]).map(p => (
              <button
                key={p}
                onClick={() => setActivePeriod(p)}
                className={`px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${activePeriod === p ? 'bg-white dark:bg-emerald-600 text-emerald-600 dark:text-white shadow-sm' : 'text-slate-400'}`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        <div className="card-premium space-y-6 !p-7">
          <ProgressStat label={t('fard')} value={periodStats.fard} color="text-emerald-500" icon="fa-kaaba" />
          <ProgressStat label={t('sunnah')} value={periodStats.sunnah} color="text-teal-500" icon="fa-sun" />
          <ProgressStat label={t('fasting')} value={periodStats.fasting} color="text-amber-500" icon="fa-moon" />
          <ProgressStat label={t('dhikr')} value={periodStats.dhikr} color="text-blue-500" icon="fa-fingerprint" />

          <div className="pt-2">
            <div className="flex items-center justify-between px-1">
              <div className="flex items-center gap-2">
                <i className="fas fa-book-quran text-purple-500 text-[10px]"></i>
                <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{t('quran')}</span>
              </div>
              <span className="text-[9px] font-black text-purple-500 uppercase tracking-widest">
                {state.quranProgress.surah || 'Not Started'}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Detailed Stats */}
      <div className="grid grid-cols-2 gap-4 mb-12 animate-fade-up stagger-2">
         <div className="card-premium flex flex-col items-center !p-6">
            <div className="w-10 h-10 bg-emerald-500/10 text-emerald-500 rounded-xl flex items-center justify-center mb-4"><i className="fas fa-check-double text-xs"></i></div>
            <p className="text-2xl font-black text-emerald-950 dark:text-white">{stats.completedFard}</p>
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">{t('completed')}</p>
         </div>
         <div className="card-premium flex flex-col items-center !p-6">
            <div className="w-10 h-10 bg-rose-500/10 text-rose-500 rounded-xl flex items-center justify-center mb-4"><i className="fas fa-history text-xs"></i></div>
            <p className="text-2xl font-black text-emerald-950 dark:text-white">{stats.missedFard}</p>
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">{t('missed')}</p>
         </div>
      </div>

      {/* Reminders Section */}
      <div className="space-y-6 mb-12 animate-fade-up stagger-3">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Prayer Alerts</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <div className="space-y-3">
           {PRAYERS.map(p => {
             const reminder = prayerReminders.find(r => r.prayer === p) || { prayer: p, time: '12:00', enabled: false };
             return (
               <div key={p} className="card-premium flex items-center justify-between !p-5 group">
                 <div className="flex items-center gap-5">
                   <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-lg ${reminder.enabled ? 'bg-emerald-600 text-white' : 'bg-slate-50 dark:bg-white/5 text-slate-400 dark:text-slate-600'}`}>
                     <i className="fas fa-bell"></i>
                   </div>
                   <div>
                     <span className="font-black text-sm text-emerald-950 dark:text-white capitalize">{t(p)}</span>
                     <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Custom Reminder</p>
                   </div>
                 </div>
                 <div className="flex items-center gap-4">
                   <input 
                     type="time" 
                     className="bg-transparent border-none text-xs font-black text-emerald-600 focus:ring-0 cursor-pointer" 
                     value={reminder.time} 
                     onChange={(e) => updatePrayerReminder(p, e.target.value, reminder.enabled)}
                   />
                   <button 
                     onClick={() => updatePrayerReminder(p, reminder.time, !reminder.enabled)}
                     className={`w-12 h-6 rounded-full p-1 transition-all ${reminder.enabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}
                   >
                     <div className={`w-4 h-4 bg-white rounded-full transition-transform ${reminder.enabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
                   </button>
                 </div>
               </div>
             );
           })}
         </div>
      </div>

      {/* System Settings */}
      <div className="space-y-6 animate-fade-up stagger-4 pb-20">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Preferences</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>

         <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between !p-6 mb-3">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${isDark ? 'bg-indigo-500/10 text-indigo-400' : 'bg-amber-500/10 text-amber-500'}`}>
                 <i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i>
               </div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">{isDark ? 'Dark Theme' : 'Light Theme'}</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Visual Appearance</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${isDark ? 'bg-indigo-600' : 'bg-amber-500'}`}>
               <div className={`w-4 h-4 bg-white rounded-full transition-transform ${isDark ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </div>
         </button>

         <button onClick={toggleEcoMode} className="card-premium w-full flex items-center justify-between !p-6">
            <div className="flex items-center gap-5">
               <div className="w-12 h-12 bg-teal-500/10 text-teal-500 rounded-2xl flex items-center justify-center text-xl"><i className="fas fa-bolt-lightning"></i></div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">Eco Mode</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Performance Optimizer</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${state.settings.ecoMode ? 'bg-teal-600' : 'bg-slate-200 dark:bg-white/10'}`}>
               <div className={`w-4 h-4 bg-white rounded-full transition-transform ${state.settings.ecoMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </div>
         </button>
      </div>
    </div>
  );
};

export default MyAccount;

export type Language = 'en' | 'ml' | 'ta' | 'ar';

export enum PrayerStatus {
  PENDING = 'pending',
  COMPLETED = 'completed',
  MISSED = 'missed',
  EXCUSED = 'excused'
}

export interface UserProfile {
  username: string;
  name: string;
  age: number;
  sex: 'male' | 'female';
  place: string;
  preferredLanguage: Language;
  password?: string; // Stored in mock backend
}

export interface PrayerLog {
  fajr: PrayerStatus;
  dhuhr: PrayerStatus;
  asr: PrayerStatus;
  maghrib: PrayerStatus;
  isha: PrayerStatus;
}

export interface FastingLog {
  status: 'none' | 'completed' | 'missed' | 'excused';
  type: 'ramadan' | 'sunnah';
}

export interface QuranProgress {
  surah: string;
  ayah: string;
  // Added juz property to track Quran progress by Juz
  juz: string;
  lastUpdated: string;
}

export interface DhikrChallenge {
  id: string;
  title: string;
  arabic: string;
  target: number;
  current: number;
  lastReset?: string;
}

export interface PersonalDhikr {
  id: string;
  name: string;
  totalCount: number;
  dailyCount: number;
  sessionCount: number;
  lastUpdated: string;
}

export interface DhikrHistoryEntry {
  id: string;
  title: string;
  target: number;
  current: number;
  date: string;
}

export interface PrayerTimings {
  Fajr: string;
  Dhuhr: string;
  Asr: string;
  Maghrib: string;
  Isha: string;
  Sunrise: string;
}

export interface QadaReminder {
  id: string;
  time: string;
  enabled: boolean;
}

export interface PrayerReminder {
  prayer: string;
  time: string;
  enabled: boolean;
}

export interface HealthPeriod {
  id: string;
  start: string; // ISO Date string
  end: string | null; // null if active
}

// This represents the data for a SINGLE user
export interface UserData {
  profile: UserProfile;
  prayerLogs: Record<string, PrayerLog>;
  sunnahLogs: Record<string, string[]>;
  fastingLogs: Record<string, FastingLog>;
  quranProgress: QuranProgress;
  dhikrCount: number;
  activeChallenges: DhikrChallenge[];
  personalDhikrs: PersonalDhikr[];
  activeDhikrId: string | null; // Tracked active challenge for the counter
  dhikrHistory: DhikrHistoryEntry[];
  isHaydNifas: boolean;
  haydStartDate: string | null;
  healthPeriods: HealthPeriod[];
  settings: {
    notificationsEnabled: boolean;
    locationEnabled: boolean;
    theme: 'light' | 'dark';
    ecoMode: boolean; // Optimize for low-end devices
    qadaReminders: QadaReminder[];
    prayerReminders: PrayerReminder[];
  };
}

export interface AppState {
  currentUser: string | null; // username
  users: Record<string, UserData>; // Mock database
  todayTimings: PrayerTimings | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings } from './types';
import { TRANSLATIONS, PRAYERS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import PrayerCalendar from './components/PrayerCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

const USERS_DB_KEY = 'ibadathi_v6_users_database';
const SESSION_KEY = 'ibadathi_v6_active_session';

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'ലാ ഇലാഹ ഇല്ലല്ലാഹ്', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [isMounted, setIsMounted] = useState(false);
  const [state, setState] = useState<AppState>({
    currentUser: null,
    users: {},
    todayTimings: DEFAULT_TIMINGS
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState<Language>('en');

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const lastAlertedPrayer = useRef<string | null>(null);

  // Initialize client-side data
  useEffect(() => {
    setIsMounted(true);
    try {
      const savedUsers = localStorage.getItem(USERS_DB_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      let parsedUsers: Record<string, UserData> = {};
      if (savedUsers) parsedUsers = JSON.parse(savedUsers);
      const currentUser = (activeSession && parsedUsers[activeSession.toLowerCase()]) ? activeSession.toLowerCase() : null;

      setState(prev => ({
        ...prev,
        users: parsedUsers,
        currentUser: currentUser
      }));
    } catch (e) {
      console.error("Local Storage Initialization Error", e);
    }
  }, []);

  // Sync Global Theme & Body Classes
  useEffect(() => {
    if (!isMounted) return;

    if (state.currentUser && state.users[state.currentUser]) {
      const user = state.users[state.currentUser];
      setCurrentLanguage(user.profile.preferredLanguage);
      const isDark = user.settings.theme === 'dark';
      document.body.classList.toggle('dark', isDark);
      document.body.classList.toggle('dark-mode-active', isDark);

      if (user.settings.ecoMode) {
        document.body.classList.add('eco-mode');
      } else {
        document.body.classList.remove('eco-mode');
      }
    } else {
      document.body.classList.add('dark', 'dark-mode-active');
    }
  }, [state.currentUser, state.users, isMounted]);

  // Persist Data Changes
  useEffect(() => {
    if (!isMounted) return;
    try {
      localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
      if (state.currentUser) {
        localStorage.setItem(SESSION_KEY, state.currentUser);
      } else {
        localStorage.removeItem(SESSION_KEY);
      }
    } catch (e) {
      console.warn("Storage Sync Failed", e);
    }
  }, [state.users, state.currentUser, isMounted]);

  // Isolated Background Alarm System - Safe execution after load
  useEffect(() => {
    if (!isMounted || !state.currentUser || !state.todayTimings) return;

    const checkAlarms = () => {
      const user = state.users[state.currentUser!];
      if (!user?.settings.notificationsEnabled) return;

      const now = new Date();
      const timeStr = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

      const matchingPrayer = PRAYERS.find(p => {
        const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
        return state.todayTimings![key] === timeStr;
      });

      if (matchingPrayer && lastAlertedPrayer.current !== `${matchingPrayer}-${timeStr}`) {
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification(TRANSLATIONS[currentLanguage]['prayerAlertTitle'] || 'Ibadathi (عبادتي)', {
            body: (TRANSLATIONS[currentLanguage]['prayerAlertBody'] || 'It is time for {prayer} prayer.').replace('{prayer}', TRANSLATIONS[currentLanguage][matchingPrayer] || matchingPrayer),
            icon: 'https://picsum.photos/192/192'
          });
        }

        if (!audioRef.current) {
          audioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
          audioRef.current.volume = 0.4;
        }
        audioRef.current.play().catch(() => {});

        lastAlertedPrayer.current = `${matchingPrayer}-${timeStr}`;
      }
    };

    const interval = setInterval(checkAlarms, 30000);
    return () => clearInterval(interval);
  }, [state.todayTimings, state.currentUser, state.users, currentLanguage, isMounted]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const userKey = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username: userKey },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { 
          notificationsEnabled: true, 
          locationEnabled: true, 
          theme: 'dark', 
          ecoMode: false,
          qadaReminders: [],
          prayerReminders: []
        }
      };
      setState(prev => ({ ...prev, currentUser: userKey, users: { ...prev.users, [userKey]: newUserData } }));
    } else {
      setState(prev => ({ ...prev, currentUser: userKey }));
    }
    setSubView(null);
    setActiveTab('home');
    if ("Notification" in window) Notification.requestPermission();
  };

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;
  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  if (!isMounted) return <div className="app-viewport bg-slate-950"></div>;

  if (!state.currentUser) {
    return (
      <div className="app-viewport dark bg-slate-950 animate-fade-in">
        {subView === 'auth' ? (
          <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} onBack={() => setSubView(null)} />
        ) : (
          <Welcome onEnter={() => setSubView('auth')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
        )}
      </div>
    );
  }

  const compositeData = { ...currentUserData!, todayTimings: state.todayTimings };

  const renderActiveView = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeData} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeData} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeData} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home': return <Dashboard state={compositeData} setCurrentView={setSubView} t={t} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} />;
      case 'prayer': return <PrayerCalendar state={compositeData} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} setCurrentView={setSubView} t={t} />;
      case 'challenges': return (
        <DhikrCounter 
          state={compositeData} 
          updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
          updatePersonalProgress={(id, d) => updateActiveUser(u => {
            const today = new Date().toISOString().split('T')[0];
            return { ...u, personalDhikrs: u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd), dhikrCount: u.dhikrCount + d };
          })}
          addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
          resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
          deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
          archiveChallenge={(id) => updateActiveUser(u => {
            const c = u.activeChallenges.find(x => x.id === id);
            if (!c) return u;
            return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [...u.dhikrHistory, { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() }], activeDhikrId: null };
          })}
          setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))}
          setCurrentView={setSubView} t={t} 
        />
      );
      case 'tracker': return (
        <div className="scroll-container px-6 pt-12 content-limit w-full">
          <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-8 tracking-tighter">My Path</h1>
          <div className="grid grid-cols-1 gap-4">
             {[{ view: 'quran', icon: 'fa-book-open', title: 'quran', color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/30' },
               { view: 'fasting', icon: 'fa-moon', title: 'fasting', color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/30' },
               { view: 'women', icon: 'fa-leaf', title: 'womensSpace', color: 'text-rose-600', bg: 'bg-rose-50 dark:bg-rose-900/30' }].map(item => (
                <div key={item.view} onClick={() => setSubView(item.view)} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                   <div className={`w-16 h-16 ${item.bg} ${item.color} rounded-3xl flex items-center justify-center text-3xl`}><i className={`fas ${item.icon}`}></i></div>
                   <div className="flex-1">
                     <h3 className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tight">{t(item.title)}</h3>
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Worship Insights</p>
                   </div>
                   <i className="fas fa-chevron-right text-slate-200"></i>
                </div>
             ))}
          </div>
        </div>
      );
      case 'account': return <MyAccount state={compositeData} setCurrentView={setSubView} t={t} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} toggleEcoMode={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, ecoMode: !u.settings.ecoMode } }))} toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} />;
      default: return null;
    }
  };

  return (
    <div className={`app-viewport ${compositeData.settings.theme === 'dark' ? 'dark bg-slate-950' : 'bg-ivory'}`} dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative w-full h-full flex flex-col">
        {renderActiveView()}
      </main>
      {!subView && (
        <nav className="bottom-nav">
          {[
            { id: 'home', icon: 'fa-mosque' },
            { id: 'prayer', icon: 'fa-kaaba' },
            { id: 'tracker', icon: 'fa-compass' },
            { id: 'challenges', icon: 'fa-star-and-crescent' },
            { id: 'account', icon: 'fa-user' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`nav-item ${activeTab === tab.id ? 'active' : ''}`}>
