import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null; isExcusedToday?: boolean };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = useMemo(() => currentTime.toISOString().split('T')[0], [currentTime]);
  const logs = useMemo(() => state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' }, [state.prayerLogs, todayStr]);

  const dailyHadith = useMemo(() => {
    const start = new Date(currentTime.getFullYear(), 0, 0);
    const diff = currentTime.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    const dayIndex = Math.floor(diff / oneDay);
    return HADITHS[dayIndex % HADITHS.length];
  }, [currentTime]);

  const hijriDate = useMemo(() => {
    try {
      return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      }).format(currentTime);
    } catch (e) {
      return "";
    }
  }, [currentTime]);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = (state.todayTimings![key] || "00:00").split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![key] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  return (
    <div className="flex flex-col h-full overflow-hidden w-full">
      {/* Sticky Header Section */}
      <div className="sticky top-0 z-30 bg-ivory/80 dark:bg-slate-950/80 backdrop-blur-xl px-5 pt-8 pb-4 border-b border-black/5 dark:border-white/5 shadow-sm transition-colors duration-500">
        <div className="content-limit w-full space-y-6">
          {/* Header & Greeting */}
          <div className="flex justify-between items-center animate-fade-up">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center border border-emerald-500/20 text-emerald-500">
                <i className="fas fa-mosque text-sm"></i>
              </div>
              <div>
                <h2 className="text-[8px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest leading-none mb-1">Assalamu Alaikum</h2>
                <h1 className="text-lg font-black text-emerald-950 dark:text-white tracking-tight leading-none truncate max-w-[150px]">{state.profile.name}</h1>
              </div>
            </div>
            <button onClick={onLogout} className="w-9 h-9 flex items-center justify-center bg-black/5 dark:bg-white/5 rounded-xl text-slate-400 hover:text-rose-500 transition-colors">
              <i className="fas fa-power-off text-xs"></i>
            </button>
          </div>

          {/* Date Banner & Hijri Date */}
          <div className="card-premium !p-4 bg-gradient-to-br from-white to-emerald-50/30 dark:from-slate-900 dark:to-emerald-950/20 border-emerald-100/30 dark:border-emerald-900/10 flex flex-col gap-2 shadow-lg animate-fade-up stagger-1">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 bg-emerald-600 text-white rounded-xl flex flex-col items-center justify-center shadow-md shadow-emerald-600/10">
                  <span className="text-[10px] font-black leading-none mb-0.5">{currentTime.getDate()}</span>
                  <span className="text-[6px] font-black uppercase tracking-widest leading-none">{currentTime.toLocaleString('default', { month: 'short' })}</span>
                </div>
                <div>
                  <h3 className="text-xs font-black text-emerald-900 dark:text-emerald-400 tracking-tight">{currentTime.toLocaleDateString(undefined, { weekday: 'long' })}</h3>
                  <p className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{currentTime.getFullYear()}</p>
                </div>
              </div>

              <div className="text-right">
                <p className="arabic-font text-sm font-bold text-emerald-800 dark:text-emerald-400" dir="rtl">{hijriDate}</p>
                {state.isExcusedToday && (
                  <div className="mt-1 py-1 px-2 bg-rose-500/10 dark:bg-rose-950/30 border border-rose-500/20 rounded-lg flex items-center gap-1.5 animate-pop justify-end">
                    <div className="w-1 h-1 rounded-full bg-rose-500 animate-pulse"></div>
                    <span className="text-[6px] font-black text-rose-600 dark:text-rose-400 uppercase tracking-widest">Excuse Active</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Daily Hadith (Sticky) */}
          <div className="animate-fade-up stagger-2">
            <div className="card-premium !p-4 relative overflow-hidden group !bg-transparent border-emerald-500/10 dark:border-emerald-400/10 shadow-none">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[7px] font-black text-emerald-600 dark:text-emerald-500 uppercase tracking-widest">{t('hadithTitle')}</span>
                <span className="text-[7px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{dailyHadith.reference}</span>
              </div>
              <p className="arabic-font text-xl font-bold text-emerald-950 dark:text-white text-center leading-relaxed" dir="rtl">{dailyHadith.arabic}</p>
              <p className="text-[10px] font-semibold text-slate-600 dark:text-slate-300 italic leading-relaxed text-center opacity-80 mt-2 line-clamp-2">"{dailyHadith.en}"</p>
            </div>
          </div>
        </div>
      </div>

      {/* Scrollable Content Section */}
      <div className="flex-1 overflow-y-auto no-scrollbar scroll-container px-5 pt-4 pb-32">
        <div className="content-limit w-full">
          {/* Next Prayer Highlight */}
          <div className="mb-8 animate-fade-up stagger-3">
            <div className={`card-premium !p-6 flex items-center justify-between shadow-2xl transition-all duration-500 ${state.isExcusedToday ? 'bg-gradient-to-r from-rose-500 to-rose-600 shadow-rose-600/20' : 'bg-gradient-to-r from-emerald-600 to-emerald-700 shadow-emerald-600/20'} border-none`}>
              <div className="flex items-center gap-5 text-white">
                <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md border border-white/20">
                  <i className={`fas ${state.isExcusedToday ? 'fa-leaf' : 'fa-clock'}`}></i>
                </div>
                <div>
                  <h3 className={`text-[9px] font-black uppercase tracking-[0.2em] mb-1 ${state.isExcusedToday ? 'text-rose-100/70' : 'text-emerald-100/70'}`}>{t('nextPrayer')}</h3>
                  <div className="flex items-baseline gap-2">
                    <span className="text-2xl font-black tracking-tight capitalize">{nextPrayer ? t(nextPrayer.name) : '---'}</span>
                    <span className={`text-xs font-bold tabular-nums ${state.isExcusedToday ? 'text-rose-100/60' : 'text-emerald-100/60'}`}>@ {nextPrayer?.time}</span>
                  </div>
                </div>
              </div>
              <div className="bg-white/10 backdrop-blur-md rounded-2xl py-2 px-4 border border-white/20 text-center text-white">
                 <p className="text-[11px] font-black tabular-nums leading-none">
                   {state.isExcusedToday ? 'Excused' : `-${nextPrayer?.diffH}h ${nextPrayer?.diffM}m`}
                 </p>
              </div>
            </div>
          </div>

          {/* Prayers Tracker */}
          <div className="mb-8 animate-fade-up stagger-4">
            <div className="flex justify-between items-center mb-5 px-1">
              <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-400 uppercase tracking-widest">Worship Tracker</h3>
              <span className={`text-[9px] font-black uppercase tracking-widest ${state.isExcusedToday ? 'text-rose-500' : 'text-emerald-600 dark:text-emerald-50'}`}>
                {state.isExcusedToday ? 'EXCUSED' : `${PRAYERS.filter(p => logs[p as keyof typeof logs] === 'completed').length}/5`}
              </span>
            </div>
            <div className="flex gap-3 overflow-x-auto no-scrollbar -mx-1 px-1 py-1">
              {PRAYERS.map(p => {
                const status = logs[p as keyof typeof logs];
                const isDone = status === PrayerStatus.COMPLETED;
                const isExcused = status === PrayerStatus.EXCUSED || state.isExcusedToday;
                const time = state.todayTimings?.[p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings];

                return (
                  <button 
                    key={p} 
                    disabled={isExcused}
                    onClick={() => !isExcused && updatePrayerStatus(todayStr, p, isDone ? PrayerStatus.PENDING : PrayerStatus.COMPLETED)} 
                    className={`flex-none w-20 aspect-[4/5] rounded-[1.5rem] border-2 transition-all duration-300 flex flex-col items-center justify-center gap-2 ${
                      isDone 
                        ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-600' 
                        : isExcused
                        ? 'bg-rose-500/10 border-rose-500/20 text-rose-500/60 opacity-80'
                        : 'bg-white dark:bg-slate-900 border-black/5 dark:border-white/10 text-slate-400 hover:border-emerald-200'
                    }`}
                  >
                    <div className="text-center">
                      <p className="text-[7px] font-black uppercase tracking-widest mb-0.5 opacity-60 leading-none">{time}</p>
                      <p className="text-[10px] font-black capitalize leading-none">{t(p)}</p>
                    </div>
                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs transition-all ${
                      isDone ? 'bg-emerald-500 text-white shadow-md' : isExcused ? 'bg-rose-100 dark:bg-rose-950/40 text-rose-400' : 'bg-slate-100 dark:bg-slate-800 text-slate-300'
                    }`}>
                       <i className={`fas ${isDone ? 'fa-check' : isExcused ? 'fa-leaf' : 'fa-clock'}`}></i>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Navigation Tools */}
          <div className="grid grid-cols-2 gap-4 animate-fade-up stagger-5 mb-8">
            <button onClick={() => setCurrentView('quran')} className="card-premium h-24 flex items-center gap-4 !p-4 hover:border-amber-200 transition-colors">
              <div className="w-12 h-12 bg-amber-500/10 text-amber-600 rounded-2xl flex items-center justify-center text-2xl shadow-sm"><i className="fas fa-book-quran"></i></div>
              <div className="text-left overflow-hidden">
                <h4 className="font-black text-sm text-emerald-950 dark:text-white truncate">{t('quran')}</h4>
                <p className="text-[8px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest truncate">{state.quranProgress.surah || 'Not Started'}</p>
              </div>
            </button>
            <button onClick={() => setCurrentView('qibla')} className="card-premium h-24 flex items-center gap-4 !p-4 hover:border-blue-200 transition-colors">
              <div className="w-12 h-12 bg-blue-500/10 text-blue-500 rounded-2xl flex items-center justify-center text-2xl shadow-sm"><i className="fas fa-compass"></i></div>
              <div className="text-left overflow-hidden">
                <h4 className="font-black text-sm text-emerald-950 dark:text-white truncate">{t('qibla')}</h4>
                <p className="text-[8px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest truncate">Direction</p>
              </div>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, PrayerLog, AlarmSettings } from './types';
import { TRANSLATIONS, PRAYERS, BUILTIN_ALARM_SOUNDS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import PrayerCalendar from './components/PrayerCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

const USERS_DB_KEY = 'ibadathi_v6_users_database';
const SESSION_KEY = 'ibadathi_v6_active_session';

const INITIAL_ALARM: AlarmSettings = {
  ringtoneId: 'azan_makkah',
  customRingtoneData: null,
  vibrationEnabled: true,
  autoAlarmEnabled: true
};

const INITIAL_OFFSETS = { fajr: 0, dhuhr: 0, asr: 0, maghrib: 0, isha: 0 };

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'ലാ ഇലാഹ ഇല്ലല്ലാഹ്', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [isMounted, setIsMounted] = useState(false);
  const [state, setState] = useState<AppState>({
    currentUser: null,
    users: {},
    todayTimings: DEFAULT_TIMINGS
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState<Language>('en');
  const [currentTime, setCurrentTime] = useState(new Date());

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const lastAlertedPrayer = useRef<string | null>(null);

  const fetchTimings = useCallback(async (lat: number, lng: number, method: number = 1) => {
    try {
      const now = new Date();
      const dateStr = `${String(now.getDate()).padStart(2, '0')}-${String(now.getMonth() + 1).padStart(2, '0')}-${now.getFullYear()}`;
      const response = await fetch(`https://api.aladhan.com/v1/timings/${dateStr}?latitude=${lat}&longitude=${lng}&method=${method}`);
      const data = await response.json();
      if (data && data.data && data.data.timings) {
        const t = data.data.timings;
        const newTimings: PrayerTimings = {
          Fajr: t.Fajr, Sunrise: t.Sunrise, Dhuhr: t.Dhuhr, Asr: t.Asr, Maghrib: t.Maghrib, Isha: t.Isha
        };
        setState(prev => ({ ...prev, todayTimings: newTimings }));
      }
    } catch (error) {
      console.error("Failed to fetch timings:", error);
    }
  }, []);

  const refreshLocationAndTimings = useCallback(() => {
    const user = state.currentUser ? state.users[state.currentUser] : null;
    const method = user?.settings.calculationMethod || 1;
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, method),
        (err) => console.warn("Location permission denied", err),
        { enableHighAccuracy: true }
      );
    }
  }, [state.currentUser, state.users, fetchTimings]);

  useEffect(() => {
    setIsMounted(true);
    try {
      const savedUsers = localStorage.getItem(USERS_DB_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      let parsedUsers: Record<string, UserData> = {};
      if (savedUsers) parsedUsers = JSON.parse(savedUsers);
      const currentUser = (activeSession && parsedUsers[activeSession.toLowerCase()]) ? activeSession.toLowerCase() : null;
      setState(prev => ({ ...prev, users: parsedUsers, currentUser: currentUser }));

      if (currentUser) {
        const user = parsedUsers[currentUser];
        if (user) setCurrentLanguage(user.profile.preferredLanguage);

        if ("geolocation" in navigator) {
          const userMethod = user?.settings.calculationMethod || 1;
          navigator.geolocation.getCurrentPosition(
            (pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, userMethod),
            (err) => console.warn("Location not permitted on startup", err),
            { enableHighAccuracy: true }
          );
        }
      }
    } catch (e) {
      console.error("Local Storage Initialization Error", e);
    }
    const clockInterval = setInterval(() => setCurrentTime(new Date()), 10000);
    return () => clearInterval(clockInterval);
  }, [fetchTimings]);

  // Sync language with user profile changes
  useEffect(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      const userLang = state.users[state.currentUser].profile.preferredLanguage;
      if (userLang !== currentLanguage) {
        setCurrentLanguage(userLang);
      }
    }
  }, [state.currentUser, state.users, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  const adjustedTimings = useMemo(() => {
    if (!state.todayTimings || !state.currentUser) return state.todayTimings;
    const user = state.users[state.currentUser];
    const offsets = user.settings.prayerOffsets || INITIAL_OFFSETS;

    const newTimings = { ...state.todayTimings };
    PRAYERS.forEach(p => {
      const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const originalTime = newTimings[key];
      if (!originalTime) return;

      const [h, m] = originalTime.split(':').map(Number);
      const date = new Date();
      date.setHours(h, m, 0, 0);
      date.setMinutes(date.getMinutes() + (offsets[p] || 0));

      newTimings[key] = date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    });
    return newTimings;
  }, [state.todayTimings, state.currentUser, state.users]);

  const isCurrentlyExcused = useMemo(() => {
    if (!state.currentUser || !state.users[state.currentUser]) return false;
    const user = state.users[state.currentUser];
    if (user.profile.sex !== 'female') return false;
    if (user.isHaydNifas) return true;
    const nowTime = currentTime.getTime();
    return user.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : Infinity;
      return nowTime >= start && nowTime <= end;
    });
  }, [state.currentUser, state.users, currentTime]);

  useEffect(() => {
    if (!isMounted || !state.currentUser || !adjustedTimings) return;

    const checkAlarms = () => {
      const user = state.users[state.currentUser!];
      const alarmCfg = user?.settings.alarm || INITIAL_ALARM;
      if (!alarmCfg.autoAlarmEnabled || isCurrentlyExcused) return;

      const now = new Date();
      const h = now.getHours().toString().padStart(2, '0');
      const m = now.getMinutes().toString().padStart(2, '0');
      const timeStr = `${h}:${m}`;

      const matchingPrayer = PRAYERS.find(p => {
        const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
        return adjustedTimings![key] === timeStr;
      });

      if (matchingPrayer && lastAlertedPrayer.current !== `${matchingPrayer}-${timeStr}`) {
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification(TRANSLATIONS[currentLanguage]['prayerAlertTitle'] || 'Ibadathi', {
            body: (TRANSLATIONS[currentLanguage]['prayerAlertBody'] || 'Time for {prayer}').replace('{prayer}', TRANSLATIONS[currentLanguage][matchingPrayer] || matchingPrayer),
          });
        }

        let soundUrl = '';
        if (alarmCfg.ringtoneId === 'custom' && alarmCfg.customRingtoneData) {
          soundUrl = alarmCfg.customRingtoneData;
        } else {
          soundUrl = BUILTIN_ALARM_SOUNDS.find(s => s.id === alarmCfg.ringtoneId)?.url || BUILTIN_ALARM_SOUNDS[0].url;
        }

        if (soundUrl) {
          if (!audioRef.current) audioRef.current = new Audio();
          audioRef.current.src = soundUrl;
          audioRef.current.play().catch(e => console.warn("Autoplay blocked", e));
        }

        if (alarmCfg.vibrationEnabled && "vibrate" in navigator) {
          navigator.vibrate([1000, 500, 1000, 500, 1000]);
        }

        lastAlertedPrayer.current = `${matchingPrayer}-${timeStr}`;
      }
    };

    checkAlarms();
  }, [adjustedTimings, state.currentUser, state.users, currentLanguage, isMounted, isCurrentlyExcused, currentTime]);

  useEffect(() => {
    if (!isMounted) return;
    try {
      localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
      if (state.currentUser) localStorage.setItem(SESSION_KEY, state.currentUser);
      else localStorage.removeItem(SESSION_KEY);
    } catch (e) {
      console.warn("Storage Sync Failed", e);
    }
  }, [state.users, state.currentUser, isMounted]);

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const userKey = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username: userKey },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { 
          notificationsEnabled: true, locationEnabled: true, theme: 'dark', ecoMode: false,
          qadaReminders: [], prayerReminders: [], calculationMethod: 1, alarm: INITIAL_ALARM,
          prayerOffsets: INITIAL_OFFSETS
        }
      };
      setState(prev => ({ ...prev, currentUser: userKey, users: { ...prev.users, [userKey]: newUserData } }));
      setCurrentLanguage(newUserData.profile.preferredLanguage);
      if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition((pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, 1), null, { enableHighAccuracy: true });
      }
    } else {
      setState(prev => ({ ...prev, currentUser: userKey }));
      const user = state.users[userKey];
      if (user) setCurrentLanguage(user.profile.preferredLanguage);
      if ("geolocation" in navigator) {
        const userMethod = user?.settings.calculationMethod || 1;
        navigator.geolocation.getCurrentPosition((pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, userMethod), null, { enableHighAccuracy: true });
      }
    }
    setSubView(null);
    setActiveTab('home');
    if ("Notification" in window) Notification.requestPermission();
  };

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;
  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  if (!isMounted) return <div className="app-viewport bg-slate-950"></div>;
  if (!state.currentUser) {
    return (
      <div className="app-viewport dark bg-slate-950 animate-fade-in">
        {subView === 'auth' ? (
          <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} onBack={() => setSubView(null)} />
        ) : (
          <Welcome onEnter={() => setSubView('auth')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
        )}
      </div>
    );
  }

  const compositeData = { ...currentUserData!, todayTimings: adjustedTimings, isExcusedToday: isCurrentlyExcused };

  const renderActiveView = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeData} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeData} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeData} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home': return <Dashboard state={compositeData} setCurrentView={setSubView} t={t} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} />;
      case 'prayer': return <PrayerCalendar state={compositeData} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} setCurrentView={setSubView} t={t} />;
      case 'challenges': return (
        <DhikrCounter 
          state={compositeData} updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
          updatePersonalProgress={(id, d) => updateActiveUser(u => { const today = new Date().toISOString().split('T')[0]; return { ...u, personalDhikrs: u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd), dhikrCount: u.dhikrCount + d }; })}
          addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
          resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
          deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
          archiveChallenge={(id) => updateActiveUser(u => { const c = u.activeChallenges.find(x => x.id === id); if (!c) return u; return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [...u.dhikrHistory, { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() }], activeDhikrId: null }; })}
          setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))} setCurrentView={setSubView} t={t} 
        />
      );
      case 'tracker': return (
        <div className="scroll-container px-6 pt-12 content-limit w-full">
          <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-8 tracking-tighter">My Path</h1>
          <div className="grid grid-cols-1 gap-4">
             {[
               { view: 'quran', icon: 'fa-book-open', title: 'quran', color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/30' },
               { view: 'fasting', icon: 'fa-moon', title: 'fasting', color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/30' },
               { view: 'qibla', icon: 'fa-compass', title: 'qibla', color: 'text-emerald-600', bg: 'bg-emerald-50 dark:bg-emerald-900/30' },
               ...(currentUserData?.profile.sex === 'female' ? [{ view: 'women', icon: 'fa-leaf', title: 'womensSpace', color: 'text-rose-600', bg: 'bg-rose-50 dark:bg-rose-900/30' }] : [])
             ].map(item => (
                <div key={item.view} onClick={() => setSubView(item.view)} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                   <div className={`w-16 h-16 ${item.bg} ${item.color} rounded-3xl flex items-center justify-center text-3xl`}><i className={`fas ${item.icon}`}></i></div>
                   <div className="flex-1"><h3 className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tight">{t(item.title)}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Worship Insights</p></div>
                   <i className="fas fa-chevron-right text-slate-200"></i>
                </div>
             ))}
          </div>
        </div>
      );
      case 'account': return (
        <MyAccount 
          state={compositeData} setCurrentView={setSubView} t={t} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} 
          toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} 
          toggleEcoMode={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, ecoMode: !u.settings.ecoMode } }))} 
          toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} 
          updatePrayerReminder={(p, time, enabled) => updateActiveUser(u => { const r = u.settings.prayerReminders || []; const i = r.findIndex(x => x.prayer === p); const nr = [...r]; if (i > -1) nr[i] = { prayer: p, time, enabled }; else nr.push({ prayer: p, time, enabled }); return { ...u, settings: { ...u.settings, prayerReminders: nr } }; })} 
          setCalculationMethod={(m) => { updateActiveUser(u => ({ ...u, settings: { ...u.settings, calculationMethod: m } })); refreshLocationAndTimings(); }} 
          refreshTimings={refreshLocationAndTimings}
          updateAlarmSettings={(cfg) => updateActiveUser(u => ({ ...u, settings: { ...u.settings, alarm: { ...u.settings.alarm, ...cfg } } }))}
          setPrayerOffset={(p, m) => updateActiveUser(u => ({ ...u, settings: { ...u.settings, prayerOffsets: { ...(u.settings.prayerOffsets || INITIAL_OFFSETS), [p]: m } } }))}
          updateProfile={(p) => updateActiveUser(u => ({ ...u, profile: { ...u.profile, ...p } }))}
        />
      );
      default: return null;
    }
  };

  return (
    <div className={`app-viewport ${compositeData.settings.theme === 'dark' ? 'dark bg-slate-950' : 'bg-ivory'}`} dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative w-full h-full flex flex-col">{renderActiveView()}</main>
      {!subView && (
        <nav className="bottom-nav">
          {[ { id: 'home', icon: 'fa-mosque' }, { id: 'prayer', icon: 'fa-kaaba' }, { id: 'tracker', icon: 'fa-chart-line' }, { id: 'challenges', icon: 'fa-star-and-crescent' }, { id: 'account', icon: 'fa-user' } ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`nav-item ${activeTab === tab.id ? 'active' : ''}`}>
              <i className={`fas ${tab.icon}`}></i>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.id}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef } from 'react';
import { UserData, PrayerStatus, PrayerReminder, FastingLog, AlarmSettings, UserProfile, Language } from '../types';
import { PRAYERS, PRAYER_METHODS, BUILTIN_ALARM_SOUNDS } from '../constants';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleEcoMode: () => void;
  toggleNotifications: () => void;
  updatePrayerReminder: (prayer: string, time: string, enabled: boolean) => void;
  setCalculationMethod: (method: number) => void;
  refreshTimings: () => void;
  updateAlarmSettings: (cfg: Partial<AlarmSettings>) => void;
  setPrayerOffset: (prayer: string, mins: number) => void;
  updateProfile: (profile: Partial<UserProfile>) => void;
}

type Period = 'weekly' | 'monthly' | 'yearly';

const MyAccount: React.FC<MyAccountProps> = ({ 
  state, setCurrentView, t, onLogout, toggleTheme, toggleEcoMode, 
  toggleNotifications, updatePrayerReminder, setCalculationMethod, refreshTimings, updateAlarmSettings, updateProfile
}) => {
  const [activePeriod, setActivePeriod] = useState<Period>('weekly');
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState({
    name: state.profile.name,
    age: state.profile.age.toString(),
    place: state.profile.place,
    preferredLanguage: state.profile.preferredLanguage
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const alarmCfg = state.settings.alarm || {
    ringtoneId: 'azan_makkah',
    customRingtoneData: null,
    vibrationEnabled: true,
    autoAlarmEnabled: true
  };

  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;
    let level = 'levelBeginner', color = 'text-slate-400', icon = 'fa-seedling';
    if (ratio >= 0.9) { level = 'levelElite'; color = 'text-amber-500'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { level = 'levelAdvanced'; color = 'text-emerald-500'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { level = 'levelConsistent'; color = 'text-teal-500'; icon = 'fa-leaf'; }
    return { ratio, level, color, icon };
  }, [state.prayerLogs]);

  const periodStats = useMemo(() => {
    const now = new Date();
    const days = activePeriod === 'weekly' ? 7 : activePeriod === 'monthly' ? 30 : 365;
    const dateRange = Array.from({ length: days }, (_, i) => {
      const d = new Date();
      d.setDate(now.getDate() - i);
      return d.toISOString().split('T')[0];
    });
    let fardComp = 0, sunnahDays = 0, fastingComp = 0, dhikrDays = 0;
    dateRange.forEach(date => {
      const fLog = state.prayerLogs[date];
      if (fLog) PRAYERS.forEach(p => { if (fLog[p] === PrayerStatus.COMPLETED) fardComp++; });
      if (state.sunnahLogs[date]?.length > 0) sunnahDays++;
      const fastLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(date))?.[1] as FastingLog | undefined;
      if (fastLog?.status === 'completed') fastingComp++;
    });
    const dhikrHistoryInRange = state.dhikrHistory.filter(h => dateRange.includes(h.date.split('T')[0]));
    dhikrDays = new Set(dhikrHistoryInRange.map(h => h.date.split('T')[0])).size;
    return {
      fard: Math.min(100, (fardComp / (days * 5)) * 100),
      sunnah: Math.min(100, (sunnahDays / days) * 100),
      fasting: Math.min(100, (fastingComp / (activePeriod === 'yearly' ? 30 : days)) * 100),
      dhikr: Math.min(100, (dhikrDays / days) * 100)
    };
  }, [activePeriod, state]);

  const isDark = state.settings.theme === 'dark';

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const data = event.target?.result as string;
      updateAlarmSettings({ ringtoneId: 'custom', customRingtoneData: data });
    };
    reader.readAsDataURL(file);
  };

  const testAlarm = () => {
    let url = '';
    if (alarmCfg.ringtoneId === 'custom' && alarmCfg.customRingtoneData) {
      url = alarmCfg.customRingtoneData;
    } else {
      url = BUILTIN_ALARM_SOUNDS.find(s => s.id === alarmCfg.ringtoneId)?.url || '';
    }
    if (url) {
      const audio = new Audio(url);
      audio.play();
      setTimeout(() => audio.pause(), 3000);
    }
    if (alarmCfg.vibrationEnabled && "vibrate" in navigator) {
      navigator.vibrate([200, 100, 200]);
    }
  };

  const handleProfileSave = () => {
    updateProfile({
      name: profileForm.name,
      age: parseInt(profileForm.age) || state.profile.age,
      place: profileForm.place,
      preferredLanguage: profileForm.preferredLanguage as Language
    });
    setIsEditingProfile(false);
  };

  const ProgressStat = ({ label, value, color, icon }: { label: string, value: number, color: string, icon: string }) => (
    <div className="space-y-2">
      <div className="flex justify-between items-end px-1">
        <div className="flex items-center gap-2">
          <i className={`fas ${icon} ${color} text-[10px]`}></i>
          <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{label}</span>
        </div>
        <span className={`text-[11px] font-black ${color}`}>{value.toFixed(0)}%</span>
      </div>
      <div className="h-2 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
        <div className={`h-full ${color.replace('text', 'bg')} transition-all duration-1000 ease-out`} style={{ width: `${value}%` }}></div>
      </div>
    </div>
  );

  return (
    <div className="scroll-container px-6 pt-12 content-limit w-full">
      <div className="flex items-center justify-between mb-10 animate-fade-up">
         <div className="flex items-center gap-4">
            <div className="relative group">
              <div className="w-16 h-16 bg-emerald-500/10 text-emerald-600 rounded-2xl flex items-center justify-center text-2xl border border-emerald-500/20">
                <i className="fas fa-user-circle"></i>
              </div>
              <button 
                onClick={() => setIsEditingProfile(!isEditingProfile)} 
                className="absolute -bottom-1 -right-1 w-6 h-6 bg-emerald-600 text-white rounded-lg flex items-center justify-center text-[10px] shadow-lg border border-white dark:border-slate-900 active:scale-90 transition-transform"
              >
                <i className={`fas ${isEditingProfile ? 'fa-times' : 'fa-pen'}`}></i>
              </button>
            </div>
            <div>
              <h1 className="text-2xl font-black text-emerald-950 dark:text-white tracking-tighter">{state.profile.name}</h1>
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-0.5">@{state.profile.username}</p>
            </div>
         </div>
         <button onClick={onLogout} className="w-12 h-12 bg-rose-500/10 text-rose-500 rounded-2xl flex items-center justify-center border border-rose-500/20 active:scale-90 transition-transform">
           <i className="fas fa-power-off"></i>
         </button>
      </div>

      {isEditingProfile ? (
        <div className="card-premium mb-10 animate-fade-up !p-6 space-y-4">
          <div className="flex items-center gap-4 mb-2">
            <h4 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Edit Profile</h4>
            <span className="h-px flex-1 bg-emerald-500/10"></span>
          </div>

          <div className="space-y-3">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Full Name</label>
              <input 
                type="text" 
                value={profileForm.name} 
                onChange={e => setProfileForm({...profileForm, name: e.target.value})}
                className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Age</label>
                <input 
                  type="number" 
                  value={profileForm.age} 
                  onChange={e => setProfileForm({...profileForm, age: e.target.value})}
                  className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Place</label>
                <input 
                  type="text" 
                  value={profileForm.place} 
                  onChange={e => setProfileForm({...profileForm, place: e.target.value})}
                  className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Preferred Language</label>
              <div className="relative">
                <select 
                  value={profileForm.preferredLanguage}
                  onChange={e => setProfileForm({...profileForm, preferredLanguage: e.target.value as Language})}
                  className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none appearance-none"
                >
                  <option value="en">English</option>
                  <option value="ar">العربية</option>
                  <option value="ml">മലയാളം</option>
                  <option value="ta">தமிழ்</option>
                </select>
                <i className="fas fa-chevron-down absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-emerald-500 pointer-events-none"></i>
              </div>
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <button 
              onClick={handleProfileSave}
              className="flex-1 py-3 bg-emerald-600 text-white rounded-xl font-black text-[9px] uppercase tracking-widest shadow-lg shadow-emerald-500/20 active:scale-95 transition-all"
            >
              Save Changes
            </button>
            <button 
              onClick={() => setIsEditingProfile(false)}
              className="px-6 py-3 bg-slate-100 dark:bg-white/5 text-slate-400 rounded-xl font-black text-[9px] uppercase tracking-widest active:scale-95 transition-all"
            >
              Cancel
            </button>
          </div>
        </div>
      ) : (
        /* Commitment Card */
        <div className="card-premium mb-10 flex items-center gap-6 !p-8 animate-fade-up stagger-1">
           <div className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center text-4xl shadow-2xl bg-white/5 border border-white/10 ${stats.color}`}>
             <i className={`fas ${stats.icon}`}></i>
           </div>
           <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">{t('consistency')}</p>
              <h3 className={`text-2xl font-black tracking-tight ${stats.color}`}>{t(stats.level)}</h3>
              <p className="text-xs font-medium text-slate-500 mt-1">{(stats.ratio * 100).toFixed(0)}% Commitment</p>
           </div>
        </div>
      )}

      {/* Alarm Settings Section */}
      <div className="space-y-6 mb-12 animate-fade-up stagger-2.5">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">{t('alarmSettings')}</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <div className="card-premium !p-6 space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <h5 className="font-black text-xs text-emerald-950 dark:text-emerald-50 mb-1">{t('autoAlarm')}</h5>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Automatic Azan Alerts</p>
              </div>
              <button 
                onClick={() => updateAlarmSettings({ autoAlarmEnabled: !alarmCfg.autoAlarmEnabled })}
                className={`w-12 h-6 rounded-full p-1 transition-all ${alarmCfg.autoAlarmEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform ${alarmCfg.autoAlarmEnabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
              </button>
            </div>

            <div className="space-y-3">
              <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1">{t('ringtone')}</label>
              <div className="relative">
                <select 
                  value={alarmCfg.ringtoneId}
                  onChange={(e) => updateAlarmSettings({ ringtoneId: e.target.value })}
                  className="w-full p-4 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-2xl text-[10px] font-black uppercase tracking-wider text-emerald-950 dark:text-emerald-50 appearance-none outline-none"
                >
                  {BUILTIN_ALARM_SOUNDS.map(s => <option key={s.id} value={s.id} className="bg-white dark:bg-slate-900">{s.name}</option>)}
                  <option value="custom" className="bg-white dark:bg-slate-900">Custom Ringtone</option>
                </select>
                <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 pointer-events-none text-[10px]"></i>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="py-4 bg-slate-100 dark:bg-white/5 text-emerald-700 dark:text-emerald-400 rounded-2xl font-black text-[9px] uppercase tracking-widest border border-emerald-500/10 flex items-center justify-center gap-2 active:scale-95 transition-all"
              >
                <i className="fas fa-file-audio"></i> {t('customRingtone')}
              </button>
              <button 
                onClick={testAlarm}
                className="py-4 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 rounded-2xl font-black text-[9px] uppercase tracking-widest border border-emerald-500/10 flex items-center justify-center gap-2 active:scale-95 transition-all"
              >
                <i className="fas fa-play"></i> {t('testAlarm')}
              </button>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />

            <div className="flex items-center justify-between pt-2 border-t border-black/5 dark:border-white/5">
              <div>
                <h5 className="font-black text-xs text-emerald-950 dark:text-emerald-50 mb-1">{t('vibration')}</h5>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Haptic Feedback</p>
              </div>
              <button 
                onClick={() => updateAlarmSettings({ vibrationEnabled: !alarmCfg.vibrationEnabled })}
                className={`w-12 h-6 rounded-full p-1 transition-all ${alarmCfg.vibrationEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform ${alarmCfg.vibrationEnabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
              </button>
            </div>
         </div>
      </div>

      {/* Calculation Method Section */}
      <div className="space-y-6 mb-12 animate-fade-up stagger-3">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">{t('calcMethod')}</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <div className="card-premium !p-6 space-y-4">
            <div className="relative">
              <select 
                value={state.settings.calculationMethod || 3}
                onChange={(e) => setCalculationMethod(parseInt(e.target.value))}
                className="w-full p-4 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-2xl text-[10px] font-black uppercase tracking-wider text-emerald-950 dark:text-emerald-50 appearance-none outline-none"
              >
                {PRAYER_METHODS.map(m => <option key={m.id} value={m.id} className="bg-white dark:bg-slate-900">{m.name}</option>)}
              </select>
              <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 pointer-events-none text-[10px]"></i>
            </div>
            <button onClick={refreshTimings} className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-black text-[9px] uppercase tracking-[0.2em] shadow-lg shadow-emerald-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
              <i className="fas fa-location-dot"></i> {t('locationRefresh')}
            </button>
         </div>
      </div>

      {/* Progress Overview Section */}
      <div className="mb-12 animate-fade-up stagger-3.5">
        <div className="flex items-center justify-between mb-6 px-1">
          <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Progress Overview</h4>
          <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-xl">
            {(['weekly', 'monthly', 'yearly'] as Period[]).map(p => (
              <button key={p} onClick={() => setActivePeriod(p)} className={`px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${activePeriod === p ? 'bg-white dark:bg-emerald-600 text-emerald-600 dark:text-white shadow-sm' : 'text-slate-400'}`}>{p}</button>
            ))}
          </div>
        </div>
        <div className="card-premium space-y-6 !p-7">
          <ProgressStat label={t('fard')} value={periodStats.fard} color="text-emerald-500" icon="fa-kaaba" />
          <ProgressStat label={t('sunnah')} value={periodStats.sunnah} color="text-teal-500" icon="fa-sun" />
          <ProgressStat label={t('fasting')} value={periodStats.fasting} color="text-amber-500" icon="fa-moon" />
          <ProgressStat label={t('dhikr')} value={periodStats.dhikr} color="text-blue-500" icon="fa-fingerprint" />
        </div>
      </div>

      {/* Preferences */}
      <div className="space-y-6 animate-fade-up stagger-4 pb-20">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Preferences</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between !p-6 mb-3">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${isDark ? 'bg-indigo-500/10 text-indigo-400' : 'bg-amber-500/10 text-amber-500'}`}>
                 <i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i>
               </div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">{isDark ? 'Dark Theme' : 'Light Theme'}</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Visual Appearance</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${isDark ? 'bg-indigo-600' : 'bg-amber-500'}`}><div className={`w-4 h-4 bg-white rounded-full transition-transform ${isDark ? 'translate-x-6' : 'translate-x-0'}`}></div></div>
         </button>
         <button onClick={toggleNotifications} className="card-premium w-full flex items-center justify-between !p-6 mb-3">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${state.settings.notificationsEnabled ? 'bg-emerald-500/10 text-emerald-500' : 'bg-slate-500/10 text-slate-400'}`}>
                 <i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'}`}></i>
               </div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">Notifications</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Push Alerts</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${state.settings.notificationsEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}><div className={`w-4 h-4 bg-white rounded-full transition-transform ${state.settings.notificationsEnabled ? 'translate-x-6' : 'translate-x-0'}`}></div></div>
         </button>
      </div>
    </div>
  );
};

export default MyAccount;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { AppState, UserProfile, UserData, Language, PrayerStatus, DhikrChallenge, PrayerTimings, PrayerLog, AlarmSettings } from './types';
import { TRANSLATIONS, PRAYERS, BUILTIN_ALARM_SOUNDS } from './constants';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import PrayerCalendar from './components/PrayerCalendar';
import WomensSpace from './components/WomensSpace';
import DhikrCounter from './components/DhikrCounter';
import QuranTracker from './components/QuranTracker';
import FastingTracker from './components/FastingTracker';
import Welcome from './components/Welcome';
import QiblaFinder from './components/QiblaFinder';
import AboutHelp from './components/AboutHelp';
import MyAccount from './components/MyAccount';

const USERS_DB_KEY = 'ibadathi_v6_users_database';
const SESSION_KEY = 'ibadathi_v6_active_session';

const INITIAL_ALARM: AlarmSettings = {
  ringtoneId: 'azan_makkah',
  customRingtoneData: null,
  vibrationEnabled: true,
  autoAlarmEnabled: true
};

const INITIAL_OFFSETS = { fajr: 0, dhuhr: 0, asr: 0, maghrib: 0, isha: 0 };

const INITIAL_DHIKRS: DhikrChallenge[] = [
  { id: 'salawat', title: 'dhikrSalawat', arabic: 'اللهم صل على محمد', target: 100, current: 0 },
  { id: 'subhanallah', title: 'dhikrSubhanAllah', arabic: 'سبحان الله', target: 33, current: 0 },
  { id: 'alhamdulillah', title: 'dhikrAlhamdulillah', arabic: 'الحمد لله', target: 33, current: 0 },
  { id: 'allahuakbar', title: 'dhikrAllahuAkbar', arabic: 'الله أكبر', target: 34, current: 0 },
  { id: 'astaghfirullah', title: 'dhikrAstaghfirullah', arabic: 'أستغفر الله', target: 100, current: 0 },
  { id: 'lailaha', title: 'dhikrLaIlaha', arabic: 'ലാ ഇലാഹ ഇല്ലല്ലാഹ്', target: 100, current: 0 }
];

const DEFAULT_TIMINGS: PrayerTimings = {
  Fajr: "05:12", Sunrise: "06:34", Dhuhr: "12:28", Asr: "15:42", Maghrib: "18:22", Isha: "19:38"
};

const App: React.FC = () => {
  const [isMounted, setIsMounted] = useState(false);
  const [state, setState] = useState<AppState>({
    currentUser: null,
    users: {},
    todayTimings: DEFAULT_TIMINGS
  });

  const [activeTab, setActiveTab] = useState<'home' | 'prayer' | 'tracker' | 'challenges' | 'account'>('home');
  const [subView, setSubView] = useState<string | null>(null);
  const [currentLanguage, setCurrentLanguage] = useState<Language>('en');
  const [currentTime, setCurrentTime] = useState(new Date());

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const lastAlertedPrayer = useRef<string | null>(null);

  const fetchTimings = useCallback(async (lat: number, lng: number, method: number = 1) => {
    try {
      const now = new Date();
      const dateStr = `${String(now.getDate()).padStart(2, '0')}-${String(now.getMonth() + 1).padStart(2, '0')}-${now.getFullYear()}`;
      const response = await fetch(`https://api.aladhan.com/v1/timings/${dateStr}?latitude=${lat}&longitude=${lng}&method=${method}`);
      const data = await response.json();
      if (data && data.data && data.data.timings) {
        const t = data.data.timings;
        const newTimings: PrayerTimings = {
          Fajr: t.Fajr, Sunrise: t.Sunrise, Dhuhr: t.Dhuhr, Asr: t.Asr, Maghrib: t.Maghrib, Isha: t.Isha
        };
        setState(prev => ({ ...prev, todayTimings: newTimings }));
      }
    } catch (error) {
      console.error("Failed to fetch timings:", error);
    }
  }, []);

  const refreshLocationAndTimings = useCallback(() => {
    const user = state.currentUser ? state.users[state.currentUser] : null;
    const method = user?.settings.calculationMethod || 1;
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, method),
        (err) => console.warn("Location permission denied", err),
        { enableHighAccuracy: true }
      );
    }
  }, [state.currentUser, state.users, fetchTimings]);

  useEffect(() => {
    setIsMounted(true);
    try {
      const savedUsers = localStorage.getItem(USERS_DB_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      let parsedUsers: Record<string, UserData> = {};
      if (savedUsers) parsedUsers = JSON.parse(savedUsers);
      const currentUser = (activeSession && parsedUsers[activeSession.toLowerCase()]) ? activeSession.toLowerCase() : null;
      setState(prev => ({ ...prev, users: parsedUsers, currentUser: currentUser }));

      if (currentUser) {
        const user = parsedUsers[currentUser];
        if (user) setCurrentLanguage(user.profile.preferredLanguage);

        if ("geolocation" in navigator) {
          const userMethod = user?.settings.calculationMethod || 1;
          navigator.geolocation.getCurrentPosition(
            (pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, userMethod),
            (err) => console.warn("Location not permitted on startup", err),
            { enableHighAccuracy: true }
          );
        }
      }
    } catch (e) {
      console.error("Local Storage Initialization Error", e);
    }
    const clockInterval = setInterval(() => setCurrentTime(new Date()), 10000);
    return () => clearInterval(clockInterval);
  }, [fetchTimings]);

  // Sync language with user profile changes
  useEffect(() => {
    if (state.currentUser && state.users[state.currentUser]) {
      const userLang = state.users[state.currentUser].profile.preferredLanguage;
      if (userLang !== currentLanguage) {
        setCurrentLanguage(userLang);
      }
    }
  }, [state.currentUser, state.users, currentLanguage]);

  const updateActiveUser = (updater: (prev: UserData) => UserData) => {
    if (!state.currentUser) return;
    setState(prev => {
      const current = prev.currentUser!;
      if (!prev.users[current]) return prev;
      return { ...prev, users: { ...prev.users, [current]: updater(prev.users[current]) } };
    });
  };

  const adjustedTimings = useMemo(() => {
    if (!state.todayTimings || !state.currentUser) return state.todayTimings;
    const user = state.users[state.currentUser];
    const offsets = user.settings.prayerOffsets || INITIAL_OFFSETS;

    const newTimings = { ...state.todayTimings };
    PRAYERS.forEach(p => {
      const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const originalTime = newTimings[key];
      if (!originalTime) return;

      const [h, m] = originalTime.split(':').map(Number);
      const date = new Date();
      date.setHours(h, m, 0, 0);
      date.setMinutes(date.getMinutes() + (offsets[p] || 0));

      newTimings[key] = date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    });
    return newTimings;
  }, [state.todayTimings, state.currentUser, state.users]);

  const isCurrentlyExcused = useMemo(() => {
    if (!state.currentUser || !state.users[state.currentUser]) return false;
    const user = state.users[state.currentUser];
    if (user.profile.sex !== 'female') return false;
    if (user.isHaydNifas) return true;
    const nowTime = currentTime.getTime();
    return user.healthPeriods.some(p => {
      const start = new Date(p.start).getTime();
      const end = p.end ? new Date(p.end).getTime() : Infinity;
      return nowTime >= start && nowTime <= end;
    });
  }, [state.currentUser, state.users, currentTime]);

  useEffect(() => {
    if (!isMounted || !state.currentUser || !adjustedTimings) return;

    const checkAlarms = () => {
      const user = state.users[state.currentUser!];
      const alarmCfg = user?.settings.alarm || INITIAL_ALARM;
      if (!alarmCfg.autoAlarmEnabled || isCurrentlyExcused) return;

      const now = new Date();
      const h = now.getHours().toString().padStart(2, '0');
      const m = now.getMinutes().toString().padStart(2, '0');
      const timeStr = `${h}:${m}`;

      const matchingPrayer = PRAYERS.find(p => {
        const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
        return adjustedTimings![key] === timeStr;
      });

      if (matchingPrayer && lastAlertedPrayer.current !== `${matchingPrayer}-${timeStr}`) {
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification(TRANSLATIONS[currentLanguage]['prayerAlertTitle'] || 'Ibadathi', {
            body: (TRANSLATIONS[currentLanguage]['prayerAlertBody'] || 'Time for {prayer}').replace('{prayer}', TRANSLATIONS[currentLanguage][matchingPrayer] || matchingPrayer),
          });
        }

        let soundUrl = '';
        if (alarmCfg.ringtoneId === 'custom' && alarmCfg.customRingtoneData) {
          soundUrl = alarmCfg.customRingtoneData;
        } else {
          soundUrl = BUILTIN_ALARM_SOUNDS.find(s => s.id === alarmCfg.ringtoneId)?.url || BUILTIN_ALARM_SOUNDS[0].url;
        }

        if (soundUrl) {
          if (!audioRef.current) audioRef.current = new Audio();
          audioRef.current.src = soundUrl;
          audioRef.current.play().catch(e => console.warn("Autoplay blocked", e));
        }

        if (alarmCfg.vibrationEnabled && "vibrate" in navigator) {
          navigator.vibrate([1000, 500, 1000, 500, 1000]);
        }

        lastAlertedPrayer.current = `${matchingPrayer}-${timeStr}`;
      }
    };

    checkAlarms();
  }, [adjustedTimings, state.currentUser, state.users, currentLanguage, isMounted, isCurrentlyExcused, currentTime]);

  useEffect(() => {
    if (!isMounted) return;
    try {
      localStorage.setItem(USERS_DB_KEY, JSON.stringify(state.users));
      if (state.currentUser) localStorage.setItem(SESSION_KEY, state.currentUser);
      else localStorage.removeItem(SESSION_KEY);
    } catch (e) {
      console.warn("Storage Sync Failed", e);
    }
  }, [state.users, state.currentUser, isMounted]);

  const handleLogin = (profile: UserProfile, isNew: boolean) => {
    const userKey = profile.username.toLowerCase();
    if (isNew) {
      const newUserData: UserData = {
        profile: { ...profile, username: userKey },
        prayerLogs: {}, sunnahLogs: {}, fastingLogs: {},
        quranProgress: { surah: '', ayah: '', juz: '', lastUpdated: '' },
        dhikrCount: 0, activeChallenges: INITIAL_DHIKRS, personalDhikrs: [],
        activeDhikrId: null, dhikrHistory: [], isHaydNifas: false, haydStartDate: null, healthPeriods: [],
        settings: { 
          notificationsEnabled: true, locationEnabled: true, theme: 'dark', ecoMode: false,
          qadaReminders: [], prayerReminders: [], calculationMethod: 1, alarm: INITIAL_ALARM,
          prayerOffsets: INITIAL_OFFSETS
        }
      };
      setState(prev => ({ ...prev, currentUser: userKey, users: { ...prev.users, [userKey]: newUserData } }));
      setCurrentLanguage(newUserData.profile.preferredLanguage);
      if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition((pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, 1), null, { enableHighAccuracy: true });
      }
    } else {
      setState(prev => ({ ...prev, currentUser: userKey }));
      const user = state.users[userKey];
      if (user) setCurrentLanguage(user.profile.preferredLanguage);
      if ("geolocation" in navigator) {
        const userMethod = user?.settings.calculationMethod || 1;
        navigator.geolocation.getCurrentPosition((pos) => fetchTimings(pos.coords.latitude, pos.coords.longitude, userMethod), null, { enableHighAccuracy: true });
      }
    }
    setSubView(null);
    setActiveTab('home');
    if ("Notification" in window) Notification.requestPermission();
  };

  const t = (key: string) => TRANSLATIONS[currentLanguage][key] || key;
  const currentUserData = state.currentUser ? state.users[state.currentUser] : null;

  if (!isMounted) return <div className="app-viewport bg-slate-950"></div>;
  if (!state.currentUser) {
    return (
      <div className="app-viewport dark bg-slate-950 animate-fade-in">
        {subView === 'auth' ? (
          <Login onLogin={handleLogin} t={t} initialLanguage={currentLanguage} users={state.users} onBack={() => setSubView(null)} />
        ) : (
          <Welcome onEnter={() => setSubView('auth')} language={currentLanguage} setLanguage={setCurrentLanguage} t={t} />
        )}
      </div>
    );
  }

  const compositeData = { ...currentUserData!, todayTimings: adjustedTimings, isExcusedToday: isCurrentlyExcused };

  const renderActiveView = () => {
    if (subView === 'qibla') return <QiblaFinder setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'about') return <AboutHelp setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'quran') return <QuranTracker state={compositeData} onUpdate={(p) => updateActiveUser(u => ({ ...u, quranProgress: p }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'fasting') return <FastingTracker state={compositeData} updateFasting={(d, l) => updateActiveUser(u => ({ ...u, fastingLogs: { ...u.fastingLogs, [d]: l } }))} setCurrentView={() => setSubView(null)} t={t} />;
    if (subView === 'women') return <WomensSpace state={compositeData} toggleHayd={(a) => updateActiveUser(u => ({ ...u, isHaydNifas: a }))} addHealthPeriod={(s, e) => updateActiveUser(u => ({ ...u, healthPeriods: [...u.healthPeriods, { id: Date.now().toString(), start: s, end: e }] }))} removeHealthPeriod={(id) => updateActiveUser(u => ({ ...u, healthPeriods: u.healthPeriods.filter(p => p.id !== id) }))} setCurrentView={() => setSubView(null)} t={t} />;

    switch (activeTab) {
      case 'home': return <Dashboard state={compositeData} setCurrentView={setSubView} t={t} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} />;
      case 'prayer': return <PrayerCalendar state={compositeData} updatePrayerStatus={(d, p, s) => updateActiveUser(u => ({ ...u, prayerLogs: { ...u.prayerLogs, [d]: { ...(u.prayerLogs[d] || {}), [p]: s } as any } }))} setCurrentView={setSubView} t={t} />;
      case 'challenges': return (
        <DhikrCounter 
          state={compositeData} updateProgress={(id, d) => updateActiveUser(u => ({ ...u, activeChallenges: u.activeChallenges.map(c => c.id === id ? { ...c, current: c.current + d } : c), dhikrCount: u.dhikrCount + d }))}
          updatePersonalProgress={(id, d) => updateActiveUser(u => { const today = new Date().toISOString().split('T')[0]; return { ...u, personalDhikrs: u.personalDhikrs.map(pd => pd.id === id ? { ...pd, totalCount: pd.totalCount + d, dailyCount: (pd.lastUpdated.split('T')[0] !== today ? d : pd.dailyCount + d), sessionCount: pd.sessionCount + d, lastUpdated: new Date().toISOString() } : pd), dhikrCount: u.dhikrCount + d }; })}
          addPersonalDhikr={(n) => updateActiveUser(u => ({ ...u, personalDhikrs: [{ id: `p-${Date.now()}`, name: n, totalCount: 0, dailyCount: 0, sessionCount: 0, lastUpdated: new Date().toISOString() }, ...u.personalDhikrs] }))}
          resetPersonalSession={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.map(d => d.id === id ? { ...d, sessionCount: 0 } : d) }))}
          deletePersonalDhikr={(id) => updateActiveUser(u => ({ ...u, personalDhikrs: u.personalDhikrs.filter(d => d.id !== id) }))}
          archiveChallenge={(id) => updateActiveUser(u => { const c = u.activeChallenges.find(x => x.id === id); if (!c) return u; return { ...u, activeChallenges: u.activeChallenges.map(x => x.id === id ? { ...x, current: 0 } : x), dhikrHistory: [...u.dhikrHistory, { id: `${id}-${Date.now()}`, title: c.title, target: c.target, current: c.current, date: new Date().toISOString() }], activeDhikrId: null }; })}
          setActiveDhikr={(id) => updateActiveUser(u => ({ ...u, activeDhikrId: id }))} setCurrentView={setSubView} t={t} 
        />
      );
      case 'tracker': return (
        <div className="scroll-container px-6 pt-12 content-limit w-full">
          <h1 className="text-4xl font-black text-emerald-950 dark:text-emerald-50 mb-8 tracking-tighter">My Path</h1>
          <div className="grid grid-cols-1 gap-4">
             {[
               { view: 'quran', icon: 'fa-book-open', title: 'quran', color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/30' },
               { view: 'fasting', icon: 'fa-moon', title: 'fasting', color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/30' },
               { view: 'qibla', icon: 'fa-compass', title: 'qibla', color: 'text-emerald-600', bg: 'bg-emerald-50 dark:bg-emerald-900/30' },
               ...(currentUserData?.profile.sex === 'female' ? [{ view: 'women', icon: 'fa-leaf', title: 'womensSpace', color: 'text-rose-600', bg: 'bg-rose-50 dark:bg-rose-900/30' }] : [])
             ].map(item => (
                <div key={item.view} onClick={() => setSubView(item.view)} className="card-premium flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all !p-5">
                   <div className={`w-16 h-16 ${item.bg} ${item.color} rounded-3xl flex items-center justify-center text-3xl`}><i className={`fas ${item.icon}`}></i></div>
                   <div className="flex-1"><h3 className="font-black text-emerald-950 dark:text-emerald-50 text-xl tracking-tight">{t(item.title)}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Worship Insights</p></div>
                   <i className="fas fa-chevron-right text-slate-200"></i>
                </div>
             ))}
          </div>
        </div>
      );
      case 'account': return (
        <MyAccount 
          state={compositeData} setCurrentView={setSubView} t={t} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} 
          toggleTheme={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, theme: u.settings.theme === 'dark' ? 'light' : 'dark' } }))} 
          toggleEcoMode={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, ecoMode: !u.settings.ecoMode } }))} 
          toggleNotifications={() => updateActiveUser(u => ({ ...u, settings: { ...u.settings, notificationsEnabled: !u.settings.notificationsEnabled } }))} 
          updatePrayerReminder={(p, time, enabled) => updateActiveUser(u => { const r = u.settings.prayerReminders || []; const i = r.findIndex(x => x.prayer === p); const nr = [...r]; if (i > -1) nr[i] = { prayer: p, time, enabled }; else nr.push({ prayer: p, time, enabled }); return { ...u, settings: { ...u.settings, prayerReminders: nr } }; })} 
          setCalculationMethod={(m) => { updateActiveUser(u => ({ ...u, settings: { ...u.settings, calculationMethod: m } })); refreshLocationAndTimings(); }} 
          refreshTimings={refreshLocationAndTimings}
          updateAlarmSettings={(cfg) => updateActiveUser(u => ({ ...u, settings: { ...u.settings, alarm: { ...u.settings.alarm, ...cfg } } }))}
          updateProfile={(p) => updateActiveUser(u => ({ ...u, profile: { ...u.profile, ...p } }))}
        />
      );
      default: return null;
    }
  };

  return (
    <div className={`app-viewport ${compositeData.settings.theme === 'dark' ? 'dark bg-slate-950' : 'bg-ivory'}`} dir={currentLanguage === 'ar' ? 'rtl' : 'ltr'}>
      <main className="flex-1 overflow-hidden relative w-full h-full flex flex-col">{renderActiveView()}</main>
      {!subView && (
        <nav className="bottom-nav">
          {[ { id: 'home', icon: 'fa-mosque' }, { id: 'prayer', icon: 'fa-kaaba' }, { id: 'tracker', icon: 'fa-chart-line' }, { id: 'challenges', icon: 'fa-star-and-crescent' }, { id: 'account', icon: 'fa-user' } ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`nav-item ${activeTab === tab.id ? 'active' : ''}`}>
              <i className={`fas ${tab.icon}`}></i>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.id}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef } from 'react';
import { UserData, PrayerStatus, PrayerReminder, FastingLog, AlarmSettings, UserProfile, Language } from '../types';
import { PRAYERS, PRAYER_METHODS, BUILTIN_ALARM_SOUNDS } from '../constants';

interface MyAccountProps {
  state: UserData;
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  onLogout: () => void;
  toggleTheme: () => void;
  toggleEcoMode: () => void;
  toggleNotifications: () => void;
  updatePrayerReminder: (prayer: string, time: string, enabled: boolean) => void;
  setCalculationMethod: (method: number) => void;
  refreshTimings: () => void;
  updateAlarmSettings: (cfg: Partial<AlarmSettings>) => void;
  updateProfile: (profile: Partial<UserProfile>) => void;
}

type Period = 'weekly' | 'monthly' | 'yearly';

const MyAccount: React.FC<MyAccountProps> = ({ 
  state, setCurrentView, t, onLogout, toggleTheme, toggleEcoMode, 
  toggleNotifications, updatePrayerReminder, setCalculationMethod, refreshTimings, updateAlarmSettings, updateProfile
}) => {
  const [activePeriod, setActivePeriod] = useState<Period>('weekly');
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState({
    name: state.profile.name,
    age: state.profile.age.toString(),
    place: state.profile.place,
    preferredLanguage: state.profile.preferredLanguage
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const alarmCfg = state.settings.alarm || {
    ringtoneId: 'azan_makkah',
    customRingtoneData: null,
    vibrationEnabled: true,
    autoAlarmEnabled: true
  };

  const stats = useMemo(() => {
    let totalFard = 0, completedFard = 0;
    Object.values(state.prayerLogs).forEach(log => {
      Object.values(log).forEach(status => {
        totalFard++;
        if (status === PrayerStatus.COMPLETED) completedFard++;
      });
    });
    const ratio = totalFard > 0 ? (completedFard / totalFard) : 0;
    let level = 'levelBeginner', color = 'text-slate-400', icon = 'fa-seedling';
    if (ratio >= 0.9) { level = 'levelElite'; color = 'text-amber-500'; icon = 'fa-crown'; }
    else if (ratio >= 0.7) { level = 'levelAdvanced'; color = 'text-emerald-500'; icon = 'fa-shield-heart'; }
    else if (ratio >= 0.4) { level = 'levelConsistent'; color = 'text-teal-500'; icon = 'fa-leaf'; }
    return { ratio, level, color, icon };
  }, [state.prayerLogs]);

  const periodStats = useMemo(() => {
    const now = new Date();
    const days = activePeriod === 'weekly' ? 7 : activePeriod === 'monthly' ? 30 : 365;
    const dateRange = Array.from({ length: days }, (_, i) => {
      const d = new Date();
      d.setDate(now.getDate() - i);
      return d.toISOString().split('T')[0];
    });
    let fardComp = 0, sunnahDays = 0, fastingComp = 0, dhikrDays = 0;
    dateRange.forEach(date => {
      const fLog = state.prayerLogs[date];
      if (fLog) PRAYERS.forEach(p => { if (fLog[p] === PrayerStatus.COMPLETED) fardComp++; });
      if (state.sunnahLogs[date]?.length > 0) sunnahDays++;
      const fastLog = Object.entries(state.fastingLogs).find(([k]) => k.includes(date))?.[1] as FastingLog | undefined;
      if (fastLog?.status === 'completed') fastingComp++;
    });
    const dhikrHistoryInRange = state.dhikrHistory.filter(h => dateRange.includes(h.date.split('T')[0]));
    dhikrDays = new Set(dhikrHistoryInRange.map(h => h.date.split('T')[0])).size;
    return {
      fard: Math.min(100, (fardComp / (days * 5)) * 100),
      sunnah: Math.min(100, (sunnahDays / days) * 100),
      fasting: Math.min(100, (fastingComp / (activePeriod === 'yearly' ? 30 : days)) * 100),
      dhikr: Math.min(100, (dhikrDays / days) * 100)
    };
  }, [activePeriod, state]);

  const isDark = state.settings.theme === 'dark';

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const data = event.target?.result as string;
      updateAlarmSettings({ ringtoneId: 'custom', customRingtoneData: data });
    };
    reader.readAsDataURL(file);
  };

  const testAlarm = () => {
    let url = '';
    if (alarmCfg.ringtoneId === 'custom' && alarmCfg.customRingtoneData) {
      url = alarmCfg.customRingtoneData;
    } else {
      url = BUILTIN_ALARM_SOUNDS.find(s => s.id === alarmCfg.ringtoneId)?.url || '';
    }
    if (url) {
      const audio = new Audio(url);
      audio.play();
      setTimeout(() => audio.pause(), 3000);
    }
    if (alarmCfg.vibrationEnabled && "vibrate" in navigator) {
      navigator.vibrate([200, 100, 200]);
    }
  };

  const handleProfileSave = () => {
    updateProfile({
      name: profileForm.name,
      age: parseInt(profileForm.age) || state.profile.age,
      place: profileForm.place,
      preferredLanguage: profileForm.preferredLanguage as Language
    });
    setIsEditingProfile(false);
  };

  const ProgressStat = ({ label, value, color, icon }: { label: string, value: number, color: string, icon: string }) => (
    <div className="space-y-2">
      <div className="flex justify-between items-end px-1">
        <div className="flex items-center gap-2">
          <i className={`fas ${icon} ${color} text-[10px]`}></i>
          <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{label}</span>
        </div>
        <span className={`text-[11px] font-black ${color}`}>{value.toFixed(0)}%</span>
      </div>
      <div className="h-2 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
        <div className={`h-full ${color.replace('text', 'bg')} transition-all duration-1000 ease-out`} style={{ width: `${value}%` }}></div>
      </div>
    </div>
  );

  return (
    <div className="scroll-container px-6 pt-12 content-limit w-full">
      <div className="flex items-center justify-between mb-10 animate-fade-up">
         <div className="flex items-center gap-4">
            <div className="relative group">
              <div className="w-16 h-16 bg-emerald-500/10 text-emerald-600 rounded-2xl flex items-center justify-center text-2xl border border-emerald-500/20">
                <i className="fas fa-user-circle"></i>
              </div>
              <button 
                onClick={() => setIsEditingProfile(!isEditingProfile)} 
                className="absolute -bottom-1 -right-1 w-6 h-6 bg-emerald-600 text-white rounded-lg flex items-center justify-center text-[10px] shadow-lg border border-white dark:border-slate-900 active:scale-90 transition-transform"
              >
                <i className={`fas ${isEditingProfile ? 'fa-times' : 'fa-pen'}`}></i>
              </button>
            </div>
            <div>
              <h1 className="text-2xl font-black text-emerald-950 dark:text-white tracking-tighter">{state.profile.name}</h1>
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-0.5">@{state.profile.username}</p>
            </div>
         </div>
         <button onClick={onLogout} className="w-12 h-12 bg-rose-500/10 text-rose-500 rounded-2xl flex items-center justify-center border border-rose-500/20 active:scale-90 transition-transform">
           <i className="fas fa-power-off"></i>
         </button>
      </div>

      {isEditingProfile ? (
        <div className="card-premium mb-10 animate-fade-up !p-6 space-y-4">
          <div className="flex items-center gap-4 mb-2">
            <h4 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Edit Profile</h4>
            <span className="h-px flex-1 bg-emerald-500/10"></span>
          </div>

          <div className="space-y-3">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Full Name</label>
              <input 
                type="text" 
                value={profileForm.name} 
                onChange={e => setProfileForm({...profileForm, name: e.target.value})}
                className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Age</label>
                <input 
                  type="number" 
                  value={profileForm.age} 
                  onChange={e => setProfileForm({...profileForm, age: e.target.value})}
                  className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Place</label>
                <input 
                  type="text" 
                  value={profileForm.place} 
                  onChange={e => setProfileForm({...profileForm, place: e.target.value})}
                  className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Preferred Language</label>
              <div className="relative">
                <select 
                  value={profileForm.preferredLanguage}
                  onChange={e => setProfileForm({...profileForm, preferredLanguage: e.target.value as Language})}
                  className="w-full p-3 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-xl text-xs font-black text-emerald-950 dark:text-emerald-50 outline-none appearance-none"
                >
                  <option value="en">English</option>
                  <option value="ar">العربية</option>
                  <option value="ml">മലയാളം</option>
                  <option value="ta">தமிழ்</option>
                </select>
                <i className="fas fa-chevron-down absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-emerald-500 pointer-events-none"></i>
              </div>
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <button 
              onClick={handleProfileSave}
              className="flex-1 py-3 bg-emerald-600 text-white rounded-xl font-black text-[9px] uppercase tracking-widest shadow-lg shadow-emerald-500/20 active:scale-95 transition-all"
            >
              Save Changes
            </button>
            <button 
              onClick={() => setIsEditingProfile(false)}
              className="px-6 py-3 bg-slate-100 dark:bg-white/5 text-slate-400 rounded-xl font-black text-[9px] uppercase tracking-widest active:scale-95 transition-all"
            >
              Cancel
            </button>
          </div>
        </div>
      ) : (
        /* Commitment Card */
        <div className="card-premium mb-10 flex items-center gap-6 !p-8 animate-fade-up stagger-1">
           <div className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center text-4xl shadow-2xl bg-white/5 border border-white/10 ${stats.color}`}>
             <i className={`fas ${stats.icon}`}></i>
           </div>
           <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">{t('consistency')}</p>
              <h3 className={`text-2xl font-black tracking-tight ${stats.color}`}>{t(stats.level)}</h3>
              <p className="text-xs font-medium text-slate-500 mt-1">{(stats.ratio * 100).toFixed(0)}% Commitment</p>
           </div>
        </div>
      )}

      {/* Alarm Settings Section */}
      <div className="space-y-6 mb-12 animate-fade-up stagger-2.5">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">{t('alarmSettings')}</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <div className="card-premium !p-6 space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <h5 className="font-black text-xs text-emerald-950 dark:text-emerald-50 mb-1">{t('autoAlarm')}</h5>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Automatic Azan Alerts</p>
              </div>
              <button 
                onClick={() => updateAlarmSettings({ autoAlarmEnabled: !alarmCfg.autoAlarmEnabled })}
                className={`w-12 h-6 rounded-full p-1 transition-all ${alarmCfg.autoAlarmEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform ${alarmCfg.autoAlarmEnabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
              </button>
            </div>

            <div className="space-y-3">
              <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1">{t('ringtone')}</label>
              <div className="relative">
                <select 
                  value={alarmCfg.ringtoneId}
                  onChange={(e) => updateAlarmSettings({ ringtoneId: e.target.value })}
                  className="w-full p-4 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-2xl text-[10px] font-black uppercase tracking-wider text-emerald-950 dark:text-emerald-50 appearance-none outline-none"
                >
                  {BUILTIN_ALARM_SOUNDS.map(s => <option key={s.id} value={s.id} className="bg-white dark:bg-slate-900">{s.name}</option>)}
                  <option value="custom" className="bg-white dark:bg-slate-900">Custom Ringtone</option>
                </select>
                <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 pointer-events-none text-[10px]"></i>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="py-4 bg-slate-100 dark:bg-white/5 text-emerald-700 dark:text-emerald-400 rounded-2xl font-black text-[9px] uppercase tracking-widest border border-emerald-500/10 flex items-center justify-center gap-2 active:scale-95 transition-all"
              >
                <i className="fas fa-file-audio"></i> {t('customRingtone')}
              </button>
              <button 
                onClick={testAlarm}
                className="py-4 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 rounded-2xl font-black text-[9px] uppercase tracking-widest border border-emerald-500/10 flex items-center justify-center gap-2 active:scale-95 transition-all"
              >
                <i className="fas fa-play"></i> {t('testAlarm')}
              </button>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />

            <div className="flex items-center justify-between pt-2 border-t border-black/5 dark:border-white/5">
              <div>
                <h5 className="font-black text-xs text-emerald-950 dark:text-emerald-50 mb-1">{t('vibration')}</h5>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Haptic Feedback</p>
              </div>
              <button 
                onClick={() => updateAlarmSettings({ vibrationEnabled: !alarmCfg.vibrationEnabled })}
                className={`w-12 h-6 rounded-full p-1 transition-all ${alarmCfg.vibrationEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform ${alarmCfg.vibrationEnabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
              </button>
            </div>
         </div>
      </div>

      {/* Calculation Method Section */}
      <div className="space-y-6 mb-12 animate-fade-up stagger-3">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">{t('calcMethod')}</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <div className="card-premium !p-6 space-y-4">
            <div className="relative">
              <select 
                value={state.settings.calculationMethod || 3}
                onChange={(e) => setCalculationMethod(parseInt(e.target.value))}
                className="w-full p-4 bg-slate-50 dark:bg-white/5 border border-transparent focus:border-emerald-500 rounded-2xl text-[10px] font-black uppercase tracking-wider text-emerald-950 dark:text-emerald-50 appearance-none outline-none"
              >
                {PRAYER_METHODS.map(m => <option key={m.id} value={m.id} className="bg-white dark:bg-slate-900">{m.name}</option>)}
              </select>
              <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 pointer-events-none text-[10px]"></i>
            </div>
            <button onClick={refreshTimings} className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-black text-[9px] uppercase tracking-[0.2em] shadow-lg shadow-emerald-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
              <i className="fas fa-location-dot"></i> {t('locationRefresh')}
            </button>
         </div>
      </div>

      {/* Progress Overview Section */}
      <div className="mb-12 animate-fade-up stagger-3.5">
        <div className="flex items-center justify-between mb-6 px-1">
          <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Progress Overview</h4>
          <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-xl">
            {(['weekly', 'monthly', 'yearly'] as Period[]).map(p => (
              <button key={p} onClick={() => setActivePeriod(p)} className={`px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all ${activePeriod === p ? 'bg-white dark:bg-emerald-600 text-emerald-600 dark:text-white shadow-sm' : 'text-slate-400'}`}>{p}</button>
            ))}
          </div>
        </div>
        <div className="card-premium space-y-6 !p-7">
          <ProgressStat label={t('fard')} value={periodStats.fard} color="text-emerald-500" icon="fa-kaaba" />
          <ProgressStat label={t('sunnah')} value={periodStats.sunnah} color="text-teal-500" icon="fa-sun" />
          <ProgressStat label={t('fasting')} value={periodStats.fasting} color="text-amber-500" icon="fa-moon" />
          <ProgressStat label={t('dhikr')} value={periodStats.dhikr} color="text-blue-500" icon="fa-fingerprint" />
        </div>
      </div>

      {/* Preferences */}
      <div className="space-y-6 animate-fade-up stagger-4 pb-20">
         <div className="flex items-center gap-4 px-1">
            <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Preferences</h4>
            <span className="h-px flex-1 bg-black/5 dark:bg-white/5"></span>
         </div>
         <button onClick={toggleTheme} className="card-premium w-full flex items-center justify-between !p-6 mb-3">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${isDark ? 'bg-indigo-500/10 text-indigo-400' : 'bg-amber-500/10 text-amber-500'}`}>
                 <i className={`fas ${isDark ? 'fa-moon' : 'fa-sun'}`}></i>
               </div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">{isDark ? 'Dark Theme' : 'Light Theme'}</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Visual Appearance</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${isDark ? 'bg-indigo-600' : 'bg-amber-500'}`}><div className={`w-4 h-4 bg-white rounded-full transition-transform ${isDark ? 'translate-x-6' : 'translate-x-0'}`}></div></div>
         </button>
         <button onClick={toggleNotifications} className="card-premium w-full flex items-center justify-between !p-6 mb-3">
            <div className="flex items-center gap-5">
               <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${state.settings.notificationsEnabled ? 'bg-emerald-500/10 text-emerald-500' : 'bg-slate-500/10 text-slate-400'}`}>
                 <i className={`fas ${state.settings.notificationsEnabled ? 'fa-bell' : 'fa-bell-slash'}`}></i>
               </div>
               <div className="text-left">
                 <span className="font-black text-sm text-emerald-950 dark:text-white">Notifications</span>
                 <p className="text-[9px] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest mt-0.5">Push Alerts</p>
               </div>
            </div>
            <div className={`w-12 h-6 rounded-full p-1 transition-colors ${state.settings.notificationsEnabled ? 'bg-emerald-600' : 'bg-slate-200 dark:bg-white/10'}`}><div className={`w-4 h-4 bg-white rounded-full transition-transform ${state.settings.notificationsEnabled ? 'translate-x-6' : 'translate-x-0'}`}></div></div>
         </button>
      </div>
    </div>
  );
};

export default MyAccount;

import React, { useMemo, useState, useEffect } from 'react';
import { UserData, PrayerTimings, PrayerStatus } from '../types';
import { PRAYERS, HADITHS } from '../constants';

interface DashboardProps {
  state: UserData & { todayTimings: PrayerTimings | null; isExcusedToday?: boolean };
  setCurrentView: (view: any) => void;
  t: (key: string) => string;
  updatePrayerStatus: (date: string, prayer: any, status: PrayerStatus) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setCurrentView, t, updatePrayerStatus, onLogout }) => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = useMemo(() => currentTime.toISOString().split('T')[0], [currentTime]);
  const logs = useMemo(() => state.prayerLogs[todayStr] || { fajr: 'pending', dhuhr: 'pending', asr: 'pending', maghrib: 'pending', isha: 'pending' }, [state.prayerLogs, todayStr]);

  const dailyHadith = useMemo(() => {
    const start = new Date(currentTime.getFullYear(), 0, 0);
    const diff = currentTime.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    const dayIndex = Math.floor(diff / oneDay);
    return HADITHS[dayIndex % HADITHS.length];
  }, [currentTime]);

  const hijriDate = useMemo(() => {
    try {
      return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      }).format(currentTime);
    } catch (e) {
      return "";
    }
  }, [currentTime]);

  const nextPrayer = useMemo(() => {
    if (!state.todayTimings) return null;
    const nowMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const timings = PRAYERS.map(p => {
      const key = p.charAt(0).toUpperCase() + p.slice(1) as keyof PrayerTimings;
      const [h, m] = (state.todayTimings![key] || "00:00").split(':').map(Number);
      return { name: p, minutes: h * 60 + m, time: state.todayTimings![key] };
    });
    let next = timings.find(t => t.minutes > nowMinutes);
    if (!next) next = { ...timings[0], minutes: timings[0].minutes + 1440 };
    const diff = next.minutes - nowMinutes;
    return { ...next, diffH: Math.floor(diff / 60), diffM: diff % 60 };
  }, [state.todayTimings, currentTime]);

  return (
    <div className="flex flex-col h-full overflow-hidden w-full">
      {/* Sticky Header Section */}
      <div className="sticky top-0 z-30 bg-ivory/80 dark:bg-slate-950/80 backdrop-blur-xl px-5 pt-8 pb-4 border-b border-black/5 dark:border-white/5 shadow-sm transition-colors duration-500">
        <div className="content-limit w-full space-y-6">
          {/* Header & Greeting */}
          <div className="flex justify-between items-center animate-fade-up">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center border border-emerald-500/20 text-emerald-500">
                <i className="fas fa-mosque text-sm"></i>
              </div>
              <div>
                <h2 className="text-[8px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest leading-none mb-1">Assalamu Alaikum</h2>
                <h1 className="text-lg font-black text-emerald-950 dark:text-white tracking-tight leading-none truncate max-w-[150px]">{state.profile.name}</h1>
              </div>
            </div>
