          <div className="glass-card p-6 space-y-3 shadow-md border-l-4 border-rose-800">
            <h3 className="font-black text-[#1E2E4F] text-lg">{t('hijb_title')}</h3>
            <p className="text-slate-600 leading-relaxed text-sm">{t('hijb_desc')}</p>
