export interface EstateData {
  totalAssets: number;
  debts: number;
  funeral: number;
  will: number;
  detailed?: DetailedAssets;
}

export interface CalculationResult {
  shares: Array<{ 
    label: string, 
    type: string, 
    symbol: string, 
    fraction: string, 
    percentage: string, 
    amount: number, // Cash component
    landAmount: number,
    goldAmount: number,
    silverAmount: number,
    count: number,
    amountEach: number,
    landEach: number,
    goldEach: number,
    silverEach: number
  }>;
  netEstate: number; // Net Cash Estate
  totalLand: number;
  totalGold: number;
  totalSilver: number;
