    fixedTotal: number;
    residueTotal: number;
    aulApplied: boolean;
    raddApplied: boolean;
  };
  warnings: string[];
}

import { Heir, CalculationResult, HeirType, EstateData, HEIR_METADATA, HEIR_ORDER, Language } from '../types';

/**
 * Shāfiʿī Faraid Engine
 * Strictly follows Shāfiʿī rules for Zawil Furud, Asabah, Hijb, Aul, and Radd.
 */
export const calculateShares = (
  heirs: Heir[], 
  deceasedGender: 'Male' | 'Female', 
  estate: EstateData, 
  lang: Language = 'en'
): CalculationResult => {
  // Determine total value for Will (Wasiyyah) compliance check only
  const landValue = estate.detailed?.enabled ? (estate.detailed.land.area * estate.detailed.land.valuePerUnit) : 0;
  const goldValue = estate.detailed?.enabled ? (estate.detailed.gold.weight * estate.detailed.gold.ratePerGram) : 0;
  const silverValue = estate.detailed?.enabled ? (estate.detailed.silver.weight * estate.detailed.silver.ratePerGram) : 0;
  const cashValue = estate.detailed?.enabled ? estate.detailed.otherCash : estate.totalAssets;

  const totalEstateValue = cashValue + landValue + goldValue + silverValue;
  const totalLiabilities = estate.debts + estate.funeral;
  const netValueBeforeWill = Math.max(0, totalEstateValue - totalLiabilities);
  const maxWillAllowedValue = netValueBeforeWill / 3;
  const actualWillValue = Math.min(estate.will, maxWillAllowedValue);

  // Independent Asset Totals for Distribution
  const totalLand = estate.detailed?.enabled ? estate.detailed.land.area : 0;
  const totalGold = estate.detailed?.enabled ? estate.detailed.gold.weight : 0;
  const totalSilver = estate.detailed?.enabled ? estate.detailed.silver.weight : 0;

  // For liabilities, fiqh applies them to the total value. 
  // However, to keep asset types "independent" in calculation as requested:
  // We determine the "ratio" of the net estate value to the gross estate value.
  const netGrossRatio = totalEstateValue > 0 ? (netValueBeforeWill - actualWillValue) / totalEstateValue : 0;

  const netCash = cashValue * netGrossRatio;
  const netLand = totalLand * netGrossRatio;
  const netGold = totalGold * netGrossRatio;
  const netSilver = totalSilver * netGrossRatio;

  const hMap = heirs.reduce((acc, h) => {
    acc[h.type] = h.count;
    return acc;
  }, {} as Record<string, number>);

  const getCount = (t: string) => hMap[t] || 0;

  // --- 1. HIJB (BLOCKING) ---
  const blocked = new Set<string>();
  const sons = getCount('Sons');
  const daughters = getCount('Daughters');
  const gsons = getCount('Grandsons');
  const gdaughters = getCount('Granddaughters');
  const father = getCount('Father');
  const mother = getCount('Mother');
  const gfather = getCount('Grandfather');
  const hasDescendant = sons > 0 || daughters > 0 || gsons > 0 || gdaughters > 0;

  if (father > 0) {
    ['Grandfather', 'Paternal Grandmother', 'Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters', 'Maternal Brothers', 'Maternal Sisters'].forEach(t => blocked.add(t));
  }
  if (mother > 0) {
    ['Paternal Grandmother', 'Maternal Grandmother'].forEach(t => blocked.add(t));
  }
  if (sons > 0) {
    ['Grandsons', 'Granddaughters', 'Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters', 'Maternal Brothers', 'Maternal Sisters', 'Full Nephews', 'Paternal Nephews', 'Full Nephew’s Sons', 'Paternal Nephew’s Sons', 'Full Paternal Uncles', 'Paternal Paternal Uncles', 'Full Cousins', 'Paternal Cousins', 'Full Cousin’s Sons', 'Paternal Cousin’s Sons', 'Full Cousin’s Grandsons', 'Paternal Cousin’s Grandsons'].forEach(t => blocked.add(t));
  }
  if (hasDescendant) {
    ['Maternal Brothers', 'Maternal Sisters'].forEach(t => blocked.add(t));
  }
  if (gsons > 0) {
    ['Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters', 'Full Nephews', 'Paternal Nephews'].forEach(t => blocked.add(t));
  }

  // --- 2. FIXED SHARES (Zawil Furud) ---
  const sharers: Array<{ type: string, num: number, den: number, symbol: string }> = [];

  if (deceasedGender === 'Female' && getCount('Husband') > 0) sharers.push({ type: 'Husband', num: 1, den: hasDescendant ? 4 : 2, symbol: '1/4 | 1/2' });
  if (deceasedGender === 'Male' && getCount('Wives') > 0) sharers.push({ type: 'Wives', num: 1, den: hasDescendant ? 8 : 4, symbol: '1/8 | 1/4' });
  if (mother > 0) {
    const sibCount = (getCount('Full Brothers') + getCount('Full Sisters') + getCount('Paternal Brothers') + getCount('Paternal Sisters') + getCount('Maternal Brothers') + getCount('Maternal Sisters'));
    sharers.push({ type: 'Mother', num: 1, den: (hasDescendant || sibCount >= 2) ? 6 : 3, symbol: '1/6 | 1/3' });
  }
  if (father > 0 && hasDescendant) sharers.push({ type: 'Father', num: 1, den: 6, symbol: '1/6' });
  if (gfather > 0 && !blocked.has('Grandfather') && hasDescendant) sharers.push({ type: 'Grandfather', num: 1, den: 6, symbol: '1/6' });
  if (daughters > 0 && sons === 0) sharers.push({ type: 'Daughters', num: (daughters === 1 ? 1 : 2), den: (daughters === 1 ? 2 : 3), symbol: '1/2 | 2/3' });
  if (gdaughters > 0 && sons === 0 && daughters < 2 && !blocked.has('Granddaughters')) {
     if (daughters === 0) sharers.push({ type: 'Granddaughters', num: (gdaughters === 1 ? 1 : 2), den: (gdaughters === 1 ? 2 : 3), symbol: '1/2 | 2/3' });
     else sharers.push({ type: 'Granddaughters', num: 1, den: 6, symbol: '1/6' });
  }
  if ((getCount('Paternal Grandmother') > 0 && !blocked.has('Paternal Grandmother')) || (getCount('Maternal Grandmother') > 0 && !blocked.has('Maternal Grandmother'))) {
    sharers.push({ type: 'Grandmothers_Combined', num: 1, den: 6, symbol: '1/6' });
  }
  const matSibCount = getCount('Maternal Brothers') + getCount('Maternal Sisters');
  if (matSibCount > 0 && !blocked.has('Maternal Brothers')) sharers.push({ type: 'Maternal_Siblings_Combined', num: 1, den: (matSibCount === 1 ? 6 : 3), symbol: '1/6 | 1/3' });

  const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
  const lcm = (a: number, b: number): number => (a * b) / (gcd(a, b) || 1);
  const commonDenom = sharers.length > 0 ? sharers.reduce((acc, s) => lcm(acc, s.den), 1) : 1;
  let totalNum = sharers.reduce((acc, s) => acc + (s.num * (commonDenom / s.den)), 0);
  const aulApplied = totalNum > commonDenom;
  const finalDenom = aulApplied ? totalNum : commonDenom;

  const result: CalculationResult = {
    shares: [],
    netEstate: netCash,
    totalLand: netLand,
    totalGold: netGold,
    totalSilver: netSilver,
    summary: { fixedTotal: 0, residueTotal: 0, aulApplied, raddApplied: false },
    warnings: []
  };

  if (estate.will > maxWillAllowedValue) result.warnings.push('error_will_limit');

  sharers.forEach(s => {
    let actualCount = 1;
    if (s.type === 'Grandmothers_Combined') actualCount = (getCount('Paternal Grandmother') > 0 ? 1 : 0) + (getCount('Maternal Grandmother') > 0 ? 1 : 0);
    else if (s.type === 'Maternal_Siblings_Combined') actualCount = matSibCount;
    else actualCount = getCount(s.type);

    const shareTotal = (s.num * (commonDenom / s.den)) / finalDenom;

    if (s.type === 'Grandmothers_Combined') {
        if (getCount('Maternal Grandmother') > 0) result.shares.push(createShareObj('Maternal Grandmother', 'Fixed', s.symbol, shareTotal/actualCount, netCash, netLand, netGold, netSilver, 1, lang));
        if (getCount('Paternal Grandmother') > 0 && !blocked.has('Paternal Grandmother')) result.shares.push(createShareObj('Paternal Grandmother', 'Fixed', s.symbol, shareTotal/actualCount, netCash, netLand, netGold, netSilver, 1, lang));
    } else if (s.type === 'Maternal_Siblings_Combined') {
        if (getCount('Maternal Brothers') > 0) result.shares.push(createShareObj('Maternal Brothers', 'Fixed', s.symbol, (shareTotal/actualCount) * getCount('Maternal Brothers'), netCash, netLand, netGold, netSilver, getCount('Maternal Brothers'), lang));
        if (getCount('Maternal Sisters') > 0) result.shares.push(createShareObj('Maternal Sisters', 'Fixed', s.symbol, (shareTotal/actualCount) * getCount('Maternal Sisters'), netCash, netLand, netGold, netSilver, getCount('Maternal Sisters'), lang));
    } else {
        result.shares.push(createShareObj(s.type, 'Fixed', s.symbol, shareTotal, netCash, netLand, netGold, netSilver, actualCount, lang));
    }
    result.summary.fixedTotal += shareTotal;
  });

  let residueRatio = 1 - result.summary.fixedTotal;
  if (residueRatio > 0.000001) {
    let asabaAssigned = false;
    if (sons > 0) {
      const units = (sons * 2) + daughters;
      const sonPart = (residueRatio * (2 / units));
      const daughterPart = (residueRatio * (1 / units));
      result.shares.push(createShareObj('Sons', 'Asabah', 'Asaba (2:1)', sonPart * sons, netCash, netLand, netGold, netSilver, sons, lang));
      if (daughters > 0) result.shares.push(createShareObj('Daughters', 'Asabah', 'Asaba (2:1)', daughterPart * daughters, netCash, netLand, netGold, netSilver, daughters, lang));
      asabaAssigned = true;
    } else if (gsons > 0) {
      const units = (gsons * 2) + gdaughters;
      const gsonPart = (residueRatio * (2 / units));
      const gdaughterPart = (residueRatio * (1 / units));
      result.shares.push(createShareObj('Grandsons', 'Asabah', 'Asaba (2:1)', gsonPart * gsons, netCash, netLand, netGold, netSilver, gsons, lang));
      if (gdaughters > 0) result.shares.push(createShareObj('Granddaughters', 'Asabah', 'Asaba (2:1)', gdaughterPart * gdaughters, netCash, netLand, netGold, netSilver, gdaughters, lang));
      asabaAssigned = true;
    } else if (father > 0) {
      result.shares.push(createShareObj('Father', 'Asabah', 'Asaba (F)', residueRatio, netCash, netLand, netGold, netSilver, 1, lang));
      asabaAssigned = true;
    } else if (gfather > 0 && !blocked.has('Grandfather')) {
        result.shares.push(createShareObj('Grandfather', 'Asabah', 'Asaba (F)', residueRatio, netCash, netLand, netGold, netSilver, 1, lang));
        asabaAssigned = true;
    } else if (getCount('Full Brothers') > 0) {
        const b = getCount('Full Brothers'), s = getCount('Full Sisters'), units = (b * 2) + s;
        const bPart = (residueRatio * (2 / units)), sPart = (residueRatio * (1 / units));
        result.shares.push(createShareObj('Full Brothers', 'Asabah', 'Asaba (2:1)', bPart * b, netCash, netLand, netGold, netSilver, b, lang));
        if (s > 0) result.shares.push(createShareObj('Full Sisters', 'Asabah', 'Asaba (2:1)', sPart * s, netCash, netLand, netGold, netSilver, s, lang));
        asabaAssigned = true;
    } else {
        const otherAsabaOrder = ['Paternal Brothers', 'Full Nephews', 'Paternal Nephews', 'Full Nephew’s Sons', 'Paternal Nephew’s Sons', 'Full Paternal Uncles', 'Paternal Paternal Uncles', 'Full Cousins', 'Paternal Cousins', 'Full Cousin’s Sons', 'Paternal Cousin’s Sons', 'Full Cousin’s Grandsons', 'Paternal Cousin’s Grandsons'];
        for (const type of otherAsabaOrder) {
            if (getCount(type) > 0 && !blocked.has(type)) {
                result.shares.push(createShareObj(type, 'Asabah', 'Asaba', residueRatio, netCash, netLand, netGold, netSilver, getCount(type), lang));
                asabaAssigned = true;
                break;
            }
        }
    }
    if (asabaAssigned) result.summary.residueTotal = residueRatio;
    else {
        const nonSpouseSharers = result.shares.filter(s => {
          const m = Object.values(HEIR_METADATA).find(x => x[lang] === s.label);
          return m !== HEIR_METADATA['Husband'] && m !== HEIR_METADATA['Wives'] && s.amount > 0;
        });
        if (nonSpouseSharers.length > 0) {
            result.summary.raddApplied = true;
            const totalSharerRatio = nonSpouseSharers.reduce((acc, s) => acc + (s.amount / (netCash || 1)), 0);
            nonSpouseSharers.forEach(s => {
                const added = (s.amount / ((netCash || 1) * (totalSharerRatio || 1))) * residueRatio;
                const newRatio = (s.amount / (netCash || 1)) + added;
                s.amount = netCash * newRatio;
                s.landAmount = netLand * newRatio;
                s.goldAmount = netGold * newRatio;
                s.silverAmount = netSilver * newRatio;
                s.amountEach = s.amount / s.count;
                s.landEach = s.landAmount / s.count;
                s.goldEach = s.goldAmount / s.count;
                s.silverEach = s.silverAmount / s.count;
                s.percentage = `${(newRatio * 100).toFixed(2)}%`;
                s.fraction = ratioToFraction(newRatio);
            });
        }
    }
  }

  HEIR_ORDER.forEach(type => {
      if (getCount(type) > 0 && !result.shares.some(s => s.label === HEIR_METADATA[type][lang])) {
          result.shares.push({
              label: HEIR_METADATA[type][lang], type: 'Excluded', symbol: 'U', fraction: '0', percentage: '0%', 
              amount: 0, landAmount: 0, goldAmount: 0, silverAmount: 0, count: getCount(type), 
              amountEach: 0, landEach: 0, goldEach: 0, silverEach: 0
          });
      }
  });
  return result;
};

const createShareObj = (type: string, sType: string, symbol: string, ratio: number, netCash: number, netLand: number, netGold: number, netSilver: number, count: number, lang: Language) => {
    return {
        label: HEIR_METADATA[type] ? HEIR_METADATA[type][lang] : type,
        type: sType,
        symbol,
        fraction: ratioToFraction(ratio),
        percentage: `${(ratio * 100).toFixed(2)}%`,
        amount: netCash * ratio,
        landAmount: netLand * ratio,
        goldAmount: netGold * ratio,
        silverAmount: netSilver * ratio,
        count: count,
        amountEach: (netCash * ratio) / count,
        landEach: (netLand * ratio) / count,
        goldEach: (netGold * ratio) / count,
        silverEach: (netSilver * ratio) / count
    };
};

const ratioToFraction = (r: number): string => {
    if (r === 0) return '0';
    const tolerance = 1.0e-6;
    let h1 = 1, h2 = 0, k1 = 0, k2 = 1, b = r;
    do {
        let a = Math.floor(b);
        let aux = h1; h1 = a * h1 + h2; h2 = aux;
        aux = k1; k1 = a * k1 + k2; k2 = aux;
        if (Math.abs(b - a) < tolerance) break;
        b = 1 / (b - a);
    } while (Math.abs(r - h1 / k1) > r * tolerance && k1 < 10000);
    return `${h1}/${k1}`;
};

import React, { useState, useEffect } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, HEIR_ORDER, EstateData, Language, DetailedAssets, LandUnit } from './types';
import { calculateShares } from './logic/faraidEngine';
import { translations } from './translations';
import { QRCodeCanvas } from 'qrcode.react';

/** 
 * ScreenWrapper provides a strict layout grid to prevent UI intersections
 */
interface ScreenWrapperProps {
  children: React.ReactNode;
  currentStep: AppStep;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
  disabled?: boolean;
  hideFooter?: boolean;
  lang: Language;
}

const stepsOrder = [
  AppStep.LANGUAGE_SELECT,
  AppStep.WELCOME,
  AppStep.DESCRIPTION,
  AppStep.HADITH,
  AppStep.AYAH,
  AppStep.RULES,
  AppStep.ASSETS,
  AppStep.GENDER,
  AppStep.SELECTION,
  AppStep.RESULT
];

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  currentStep,
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel, 
  disabled = false,
  hideFooter = false,
  lang
}) => {
  const stepIndex = stepsOrder.indexOf(currentStep);
  const t = (key: string) => (translations[lang] as any)[key] || key;
  const isRtl = lang === 'ar';

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent pt-safe" dir={isRtl ? 'rtl' : 'ltr'}>
      {/* Fixed Progress Header */}
      <div className="shrink-0 z-[70]">
        {stepIndex >= 1 && (
          <div className="h-1.5 bg-slate-200/50 w-full">
            <div 
              className="h-full bg-[#D89F37] transition-all duration-700 ease-in-out shadow-[0_0_8px_rgba(216,159,55,0.4)]" 
              style={{ 
                width: `${((stepIndex) / (stepsOrder.length - 1)) * 100}%`,
                [isRtl ? 'right' : 'left']: 0 
              }}
            />
          </div>
        )}
      </div>

      {/* Main Content Area - Strictly non-overlapping */}
      <main className="flex-1 min-h-0 relative z-10 flex flex-col max-w-md mx-auto w-full px-5 overflow-hidden">
        {children}
      </main>

      {/* Persistent Glass Footer */}
      {!hideFooter && (
        <div className="px-6 py-6 glass flex justify-center gap-4 shrink-0 rounded-t-[32px] shadow-[0_-8px_30px_rgba(0,0,0,0.05)] pb-safe">
          {prevStep && (
            <button 
              onClick={() => setStep(prevStep)} 
              className="w-14 h-14 rounded-2xl flex items-center justify-center bg-white border border-slate-200 text-[#1E2E4F] active-press transition-all shadow-sm"
            >
              <svg className={`w-6 h-6 ${isRtl ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          {nextStep && (
            <button 
              disabled={disabled} 
              onClick={() => setStep(nextStep)} 
              className="flex-1 h-14 bg-[#006B46] text-white rounded-2xl font-bold text-lg transition-all active-press shadow-lg shadow-[#006B46]/20 disabled:opacity-40"
            >
              {nextLabel || t('continue')}
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.LANGUAGE_SELECT);
  const [lang, setLang] = useState<Language>('en');
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
  const [detailedAssets, setDetailedAssets] = useState<DetailedAssets>({
    enabled: false,
    land: { area: 0, unit: 'cent', valuePerUnit: 0 },
    gold: { weight: 0, ratePerGram: 0 },
    silver: { weight: 0, ratePerGram: 0 },
    otherCash: 0
  });
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [showQR, setShowQR] = useState(false);
  const [uiError, setUiError] = useState<string | null>(null);

  useEffect(() => {
    const savedLang = localStorage.getItem('appLanguage') as Language;
    if (savedLang && Object.keys(translations).includes(savedLang)) {
      setLang(savedLang);
      setStep(AppStep.WELCOME);
    }
  }, []);

  const handleLangSelect = (l: Language) => {
    setLang(l);
    localStorage.setItem('appLanguage', l);
    setStep(AppStep.WELCOME);
  };

  const t = (key: string) => (translations[lang] as any)[key] || key;

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type as string];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = Math.max(0, existing.count + delta);
        if (meta.max) newCount = Math.min(newCount, meta.max);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) return [...prev, { type, count: 1 }];
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    setUiError(null);

    const landValue = detailedAssets.enabled ? (detailedAssets.land.area * detailedAssets.land.valuePerUnit) : 0;
    const goldValue = detailedAssets.enabled ? (detailedAssets.gold.weight * detailedAssets.gold.ratePerGram) : 0;
    const silverValue = detailedAssets.enabled ? (detailedAssets.silver.weight * detailedAssets.silver.ratePerGram) : 0;
    const cashValue = detailedAssets.enabled ? detailedAssets.otherCash : estate.totalAssets;

    const finalTotalValue = cashValue + landValue + goldValue + silverValue;

    if (heirs.length === 0) {
      setUiError(t('error_no_heirs'));
      return;
    }

    if (finalTotalValue <= (estate.debts + estate.funeral)) {
      setUiError(t('error_liabilities_exceed_assets'));
      return;
    }

    if (finalTotalValue <= 0) {
      setUiError(t('error_invalid_assets'));
      return;
    }

    try {
      if (deceasedGender) {
        // We pass the individual totals in the estate object's 'detailed' property.
        // The engine now handles multi-asset distribution.
        const res = calculateShares(heirs, deceasedGender, { ...estate, totalAssets: cashValue, detailed: detailedAssets }, lang);
        setResult(res);
        setStep(AppStep.RESULT);
      }
    } catch (e) {
      console.error(e);
      setUiError(t('error_general'));
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setDetailedAssets({
      enabled: false,
      land: { area: 0, unit: 'cent', valuePerUnit: 0 },
      gold: { weight: 0, ratePerGram: 0 },
      silver: { weight: 0, ratePerGram: 0 },
