export type HeirType = keyof typeof HEIR_METADATA;

export interface Heir {
  type: HeirType;
  count: number;
}

export interface EstateData {
  totalAssets: number;
  debts: number;
  funeral: number;
  will: number;
  detailed?: DetailedAssets;
  detailedWill?: DetailedWasiyyah;
}

export interface CalculationResult {
  shares: Array<{ 
    label: string, 
    type: string, 
    symbol: string, 
    fraction: string, 
    percentage: string, 
    amount: number, 
    landAmount: number,
    goldAmount: number,
    silverAmount: number,
    count: number,
    amountEach: number,
    landEach: number,
    goldEach: number,
    silverEach: number
  }>;
  netEstate: number;
  totalLand: number;
  totalGold: number;
  totalSilver: number;
  summary: {
    fixedTotal: number;
    residueTotal: number;
    aulApplied: boolean;
    raddApplied: boolean;
  };
  warnings: string[];
}

import { Heir, CalculationResult, HeirType, EstateData, HEIR_METADATA, HEIR_ORDER, Language } from '../types';

export const calculateShares = (
  heirs: Heir[], 
  deceasedGender: 'Male' | 'Female', 
  estate: EstateData, 
  lang: Language = 'en'
): CalculationResult => {
  const rawLand = estate.detailed?.enabled ? estate.detailed.land.area : 0;
  const rawGold = estate.detailed?.enabled ? estate.detailed.gold.weight : 0;
  const rawSilver = estate.detailed?.enabled ? estate.detailed.silver.weight : 0;
  const rawCash = estate.detailed?.enabled ? estate.detailed.otherCash : estate.totalAssets;

  const landVal = estate.detailed?.enabled ? (rawLand * estate.detailed.land.valuePerUnit) : 0;
  const goldVal = estate.detailed?.enabled ? (rawGold * estate.detailed.gold.ratePerGram) : 0;
  const silverVal = estate.detailed?.enabled ? (rawSilver * estate.detailed.silver.ratePerGram) : 0;
  const cashVal = rawCash;

  const totalGrossValue = cashVal + landVal + goldVal + silverVal;
  const totalLiabilitiesVal = estate.debts + estate.funeral;
  const netValueBeforeWill = Math.max(0, totalGrossValue - totalLiabilitiesVal);
  const maxWasiyyahAllowedValue = netValueBeforeWill / 3;

  let willCash = estate.detailedWill?.cash || 0;
  let willLand = estate.detailedWill?.landArea || 0;
  let willGold = estate.detailedWill?.goldWeight || 0;
  let willSilver = estate.detailedWill?.silverWeight || 0;

  if (!estate.detailed?.enabled) {
    willCash = estate.will;
    willLand = 0;
    willGold = 0;
    willSilver = 0;
  }

  const proposedWillValue = (willCash) + 
                            (willLand * (estate.detailed?.land.valuePerUnit || 0)) + 
                            (willGold * (estate.detailed?.gold.ratePerGram || 0)) + 
                            (willSilver * (estate.detailed?.silver.ratePerGram || 0));

  let scalingFactor = 1;
  let willWarning = false;
  if (proposedWillValue > maxWasiyyahAllowedValue && proposedWillValue > 0) {
    scalingFactor = maxWasiyyahAllowedValue / proposedWillValue;
    willWarning = true;
  }

  const finalWillCash = willCash * scalingFactor;
  const finalWillLand = willLand * scalingFactor;
  const finalWillGold = willGold * scalingFactor;
  const finalWillSilver = willSilver * scalingFactor;

  const liabilitiesRatio = totalGrossValue > 0 ? (totalGrossValue - totalLiabilitiesVal) / totalGrossValue : 0;

  const distributableCash = Math.max(0, (rawCash * liabilitiesRatio) - finalWillCash);
  const distributableLand = Math.max(0, (rawLand * liabilitiesRatio) - finalWillLand);
  const distributableGold = Math.max(0, (rawGold * liabilitiesRatio) - finalWillGold);
  const distributableSilver = Math.max(0, (rawSilver * liabilitiesRatio) - finalWillSilver);

  const hMap = heirs.reduce((acc, h) => { acc[h.type] = h.count; return acc; }, {} as Record<string, number>);
  const getCount = (t: string) => hMap[t] || 0;

  const blocked = new Set<string>();
  const sons = getCount('Sons'), daughters = getCount('Daughters');
  const gsons = getCount('Grandsons'), gdaughters = getCount('Granddaughters');
  const father = getCount('Father'), mother = getCount('Mother'), gfather = getCount('Grandfather');
  const hasDescendant = sons > 0 || daughters > 0 || gsons > 0 || gdaughters > 0;

  if (father > 0) ['Grandfather', 'Paternal Grandmother', 'Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters', 'Maternal Brothers', 'Maternal Sisters'].forEach(t => blocked.add(t));
  if (mother > 0) ['Paternal Grandmother', 'Maternal Grandmother'].forEach(t => blocked.add(t));
  if (sons > 0) ['Grandsons', 'Granddaughters', 'Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters', 'Maternal Brothers', 'Maternal Sisters', 'Full Nephews', 'Paternal Nephews', 'Full Nephew’s Sons', 'Paternal Nephew’s Sons', 'Full Paternal Uncles', 'Paternal Paternal Uncles', 'Full Cousins', 'Paternal Cousins', 'Full Cousin’s Sons', 'Paternal Cousin’s Sons', 'Full Cousin’s Grandsons', 'Paternal Cousin’s Grandsons'].forEach(t => blocked.add(t));
  if (hasDescendant) ['Maternal Brothers', 'Maternal Sisters'].forEach(t => blocked.add(t));
  if (gsons > 0) ['Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters', 'Full Nephews', 'Paternal Nephews'].forEach(t => blocked.add(t));

  const sharers: Array<{ type: string, num: number, den: number, symbol: string }> = [];
  if (deceasedGender === 'Female' && getCount('Husband') > 0) sharers.push({ type: 'Husband', num: 1, den: hasDescendant ? 4 : 2, symbol: '1/4 | 1/2' });
  if (deceasedGender === 'Male' && getCount('Wives') > 0) sharers.push({ type: 'Wives', num: 1, den: hasDescendant ? 8 : 4, symbol: '1/8 | 1/4' });
  if (mother > 0) {
    const sibCount = (getCount('Full Brothers') + getCount('Full Sisters') + getCount('Paternal Brothers') + getCount('Paternal Sisters') + getCount('Maternal Brothers') + getCount('Maternal Sisters'));
    sharers.push({ type: 'Mother', num: 1, den: (hasDescendant || sibCount >= 2) ? 6 : 3, symbol: '1/6 | 1/3' });
  }
  if (father > 0 && hasDescendant) sharers.push({ type: 'Father', num: 1, den: 6, symbol: '1/6' });
  if (gfather > 0 && !blocked.has('Grandfather') && hasDescendant) sharers.push({ type: 'Grandfather', num: 1, den: 6, symbol: '1/6' });
  if (daughters > 0 && sons === 0) sharers.push({ type: 'Daughters', num: (daughters === 1 ? 1 : 2), den: (daughters === 1 ? 2 : 3), symbol: '1/2 | 2/3' });
  if (gdaughters > 0 && sons === 0 && daughters < 2 && !blocked.has('Granddaughters')) {
    if (daughters === 0) sharers.push({ type: 'Granddaughters', num: (gdaughters === 1 ? 1 : 2), den: (gdaughters === 1 ? 2 : 3), symbol: '1/2 | 2/3' });
    else sharers.push({ type: 'Granddaughters', num: 1, den: 6, symbol: '1/6' });
  }
  if ((getCount('Paternal Grandmother') > 0 && !blocked.has('Paternal Grandmother')) || (getCount('Maternal Grandmother') > 0 && !blocked.has('Maternal Grandmother'))) {
    sharers.push({ type: 'Grandmothers_Combined', num: 1, den: 6, symbol: '1/6' });
  }
  const matSibCount = getCount('Maternal Brothers') + getCount('Maternal Sisters');
  if (matSibCount > 0 && !blocked.has('Maternal Brothers')) sharers.push({ type: 'Maternal_Siblings_Combined', num: 1, den: (matSibCount === 1 ? 6 : 3), symbol: '1/6 | 1/3' });

  const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
  const lcm = (a: number, b: number): number => (a * b) / (gcd(a, b) || 1);
  const commonDenom = sharers.length > 0 ? sharers.reduce((acc, s) => lcm(acc, s.den), 1) : 1;
  let totalNum = sharers.reduce((acc, s) => acc + (s.num * (commonDenom / s.den)), 0);
  const aulApplied = totalNum > commonDenom;
  const finalDenom = aulApplied ? totalNum : commonDenom;

  const result: CalculationResult = {
    shares: [],
    netEstate: distributableCash, totalLand: distributableLand, totalGold: distributableGold, totalSilver: distributableSilver,
    summary: { fixedTotal: 0, residueTotal: 0, aulApplied, raddApplied: false },
    warnings: []
  };

  if (willWarning) result.warnings.push('error_will_limit');

  sharers.forEach(s => {
    let actualCount = 1;
    if (s.type === 'Grandmothers_Combined') actualCount = (getCount('Paternal Grandmother') > 0 ? 1 : 0) + (getCount('Maternal Grandmother') > 0 ? 1 : 0);
    else if (s.type === 'Maternal_Siblings_Combined') actualCount = matSibCount;
    else actualCount = getCount(s.type);

    const ratio = (s.num * (commonDenom / s.den)) / finalDenom;
    if (s.type === 'Grandmothers_Combined') {
        if (getCount('Maternal Grandmother') > 0) result.shares.push(createShareObj('Maternal Grandmother', 'Fixed', s.symbol, ratio/actualCount, distributableCash, distributableLand, distributableGold, distributableSilver, 1, lang));
        if (getCount('Paternal Grandmother') > 0 && !blocked.has('Paternal Grandmother')) result.shares.push(createShareObj('Paternal Grandmother', 'Fixed', s.symbol, ratio/actualCount, distributableCash, distributableLand, distributableGold, distributableSilver, 1, lang));
    } else if (s.type === 'Maternal_Siblings_Combined') {
        if (getCount('Maternal Brothers') > 0) result.shares.push(createShareObj('Maternal Brothers', 'Fixed', s.symbol, (ratio/actualCount) * getCount('Maternal Brothers'), distributableCash, distributableLand, distributableGold, distributableSilver, getCount('Maternal Brothers'), lang));
        if (getCount('Maternal Sisters') > 0) result.shares.push(createShareObj('Maternal Sisters', 'Fixed', s.symbol, (ratio/actualCount) * getCount('Maternal Sisters'), distributableCash, distributableLand, distributableGold, distributableSilver, getCount('Maternal Sisters'), lang));
    } else {
        result.shares.push(createShareObj(s.type, 'Fixed', s.symbol, ratio, distributableCash, distributableLand, distributableGold, distributableSilver, actualCount, lang));
    }
    result.summary.fixedTotal += ratio;
  });

  let resRatio = 1 - result.summary.fixedTotal;
  if (resRatio > 0.000001) {
    let assigned = false;
    if (sons > 0) {
      const u = (sons * 2) + daughters;
      result.shares.push(createShareObj('Sons', 'Asabah', '2:1', resRatio * (sons * 2 / u), distributableCash, distributableLand, distributableGold, distributableSilver, sons, lang));
      if (daughters > 0) result.shares.push(createShareObj('Daughters', 'Asabah', '2:1', resRatio * (daughters / u), distributableCash, distributableLand, distributableGold, distributableSilver, daughters, lang));
      assigned = true;
    } else if (gsons > 0) {
      const u = (gsons * 2) + gdaughters;
      result.shares.push(createShareObj('Grandsons', 'Asabah', '2:1', resRatio * (gsons * 2 / u), distributableCash, distributableLand, distributableGold, distributableSilver, gsons, lang));
      if (gdaughters > 0) result.shares.push(createShareObj('Granddaughters', 'Asabah', '2:1', resRatio * (gdaughters / u), distributableCash, distributableLand, distributableGold, distributableSilver, gdaughters, lang));
      assigned = true;
    } else if (father > 0) { result.shares.push(createShareObj('Father', 'Asabah', 'Asabah', resRatio, distributableCash, distributableLand, distributableGold, distributableSilver, 1, lang)); assigned = true; }
    else if (gfather > 0 && !blocked.has('Grandfather')) { result.shares.push(createShareObj('Grandfather', 'Asabah', 'Asabah', resRatio, distributableCash, distributableLand, distributableGold, distributableSilver, 1, lang)); assigned = true; }
    else if (getCount('Full Brothers') > 0) {
      const b = getCount('Full Brothers'), s = getCount('Full Sisters'), u = (b * 2) + s;
      result.shares.push(createShareObj('Full Brothers', 'Asabah', '2:1', resRatio * (b * 2 / u), distributableCash, distributableLand, distributableGold, distributableSilver, b, lang));
      if (s > 0) result.shares.push(createShareObj('Full Sisters', 'Asabah', '2:1', resRatio * (s / u), distributableCash, distributableLand, distributableGold, distributableSilver, s, lang));
      assigned = true;
    } else {
        const others = ['Paternal Brothers', 'Full Nephews', 'Paternal Nephews', 'Full Nephew’s Sons', 'Paternal Nephew’s Sons', 'Full Paternal Uncles', 'Paternal Paternal Uncles', 'Full Cousins', 'Paternal Cousins', 'Full Cousin’s Sons', 'Paternal Cousin’s Sons', 'Full Cousin’s Grandsons', 'Paternal Cousin’s Grandsons'];
        for (const type of others) if (getCount(type) > 0 && !blocked.has(type)) { result.shares.push(createShareObj(type, 'Asabah', 'Asabah', resRatio, distributableCash, distributableLand, distributableGold, distributableSilver, getCount(type), lang)); assigned = true; break; }
    }
    if (assigned) result.summary.residueTotal = resRatio;
    else {
      const sharersToRadd = result.shares.filter(s => HEIR_METADATA[s.type] && s.label !== HEIR_METADATA['Husband'][lang] && s.label !== HEIR_METADATA['Wives'][lang] && s.amountEach > 0);
      if (sharersToRadd.length > 0) {
        result.summary.raddApplied = true;
        const currentSum = sharersToRadd.reduce((acc, s) => acc + (s.amount / (distributableCash || 1)), 0);
        sharersToRadd.forEach(s => {
          const newR = (s.amount / (distributableCash || 1)) + ((s.amount / (distributableCash || 1)) / currentSum) * resRatio;
          s.amount = distributableCash * newR; s.landAmount = distributableLand * newR; s.goldAmount = distributableGold * newR; s.silverAmount = distributableSilver * newR;
          s.amountEach = s.amount / s.count; s.landEach = s.landAmount / s.count; s.goldEach = s.goldAmount / s.count; s.silverEach = s.silverAmount / s.count;
          s.percentage = `${(newR * 100).toFixed(2)}%`; s.fraction = ratioToFraction(newR);
        });
      }
    }
  }

  HEIR_ORDER.forEach(t => {
    if (getCount(t) > 0 && !result.shares.some(s => s.label === HEIR_METADATA[t][lang])) 
      result.shares.push({ label: HEIR_METADATA[t][lang], type: 'Excluded', symbol: 'U', fraction: '0', percentage: '0%', amount: 0, landAmount: 0, goldAmount: 0, silverAmount: 0, count: getCount(t), amountEach: 0, landEach: 0, goldEach: 0, silverEach: 0 });
  });

  return result;
};

const createShareObj = (type: string, sType: string, sym: string, ratio: number, nc: number, nl: number, ng: number, ns: number, c: number, lang: Language) => ({
  label: HEIR_METADATA[type] ? HEIR_METADATA[type][lang] : type, type: sType, symbol: sym, fraction: ratioToFraction(ratio), percentage: `${(ratio * 100).toFixed(2)}%`,
  amount: nc * ratio, landAmount: nl * ratio, goldAmount: ng * ratio, silverAmount: ns * ratio, count: c, amountEach: (nc * ratio) / c, landEach: (nl * ratio) / c, goldEach: (ng * ratio) / c, silverEach: (ns * ratio) / c
});

const ratioToFraction = (r: number): string => {
    if (r === 0) return '0';
    const tol = 1.0e-6;
    let h1 = 1, h2 = 0, k1 = 0, k2 = 1, b = r;
    do { let a = Math.floor(b), aux = h1; h1 = a * h1 + h2; h2 = aux; aux = k1; k1 = a * k1 + k2; k2 = aux; if (Math.abs(b - a) < tol) break; b = 1 / (b - a); } while (Math.abs(r - h1 / k1) > r * tol && k1 < 10000);
    return `${h1}/${k1}`;
};

import React, { useState, useEffect } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, HEIR_ORDER, EstateData, Language, DetailedAssets, LandUnit, DetailedWasiyyah } from './types';
import { calculateShares } from './logic/faraidEngine';
import { translations } from './translations';
import { QRCodeCanvas } from 'qrcode.react';

interface ScreenWrapperProps {
  children: React.ReactNode;
  currentStep: AppStep;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
  disabled?: boolean;
  hideFooter?: boolean;
  lang: Language;
}

const stepsOrder = [
  AppStep.LANGUAGE_SELECT,
  AppStep.WELCOME,
  AppStep.DESCRIPTION,
  AppStep.HADITH,
  AppStep.AYAH,
  AppStep.RULES,
  AppStep.ASSETS,
  AppStep.GENDER,
  AppStep.SELECTION,
  AppStep.RESULT
];

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ children, currentStep, nextStep, prevStep, setStep, nextLabel, disabled = false, hideFooter = false, lang }) => {
  const stepIndex = stepsOrder.indexOf(currentStep);
  const t = (key: string) => (translations[lang] as any)[key] || key;
  const isRtl = lang === 'ar';

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent pt-safe" dir={isRtl ? 'rtl' : 'ltr'}>
      <div className="shrink-0 z-[70]">
        {stepIndex >= 1 && (
          <div className="h-1.5 bg-slate-200/50 w-full">
            <div className="h-full bg-[#D89F37] transition-all duration-700 ease-in-out shadow-[0_0_8px_rgba(216,159,55,0.4)]" style={{ width: `${((stepIndex) / (stepsOrder.length - 1)) * 100}%`, [isRtl ? 'right' : 'left']: 0 }} />
          </div>
        )}
      </div>
      <main className="flex-1 min-h-0 relative z-10 flex flex-col max-w-md mx-auto w-full px-5 overflow-hidden">{children}</main>
      {!hideFooter && (
        <div className="px-6 py-6 glass flex justify-center gap-4 shrink-0 rounded-t-[32px] shadow-[0_-8px_30px_rgba(0,0,0,0.05)] pb-safe">
          {prevStep && (
            <button onClick={() => setStep(prevStep)} className="w-14 h-14 rounded-2xl flex items-center justify-center bg-white border border-slate-200 text-[#1E2E4F] active-press transition-all shadow-sm">
              <svg className={`w-6 h-6 ${isRtl ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          {nextStep && (
            <button disabled={disabled} onClick={() => setStep(nextStep)} className="flex-1 h-14 bg-[#006B46] text-white rounded-2xl font-bold text-lg transition-all active-press shadow-lg shadow-[#006B46]/20 disabled:opacity-40">
              {nextLabel || t('continue')}
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.LANGUAGE_SELECT);
  const [lang, setLang] = useState<Language>('en');
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
  const [detailedAssets, setDetailedAssets] = useState<DetailedAssets>({ enabled: false, land: { area: 0, unit: 'cent', valuePerUnit: 0 }, gold: { weight: 0, ratePerGram: 0 }, silver: { weight: 0, ratePerGram: 0 }, otherCash: 0 });
  const [detailedWill, setDetailedWill] = useState<DetailedWasiyyah>({ cash: 0, landArea: 0, goldWeight: 0, silverWeight: 0 });
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [showQR, setShowQR] = useState(false);
  const [uiError, setUiError] = useState<string | null>(null);

  useEffect(() => {
    const savedLang = localStorage.getItem('appLanguage') as Language;
    if (savedLang && Object.keys(translations).includes(savedLang)) { setLang(savedLang); setStep(AppStep.WELCOME); }
  }, []);

  const handleLangSelect = (l: Language) => { setLang(l); localStorage.setItem('appLanguage', l); setStep(AppStep.WELCOME); };
  const t = (key: string) => (translations[lang] as any)[key] || key;

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type as string];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = Math.max(0, existing.count + delta);
        if (meta.max) newCount = Math.min(newCount, meta.max);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) return [...prev, { type, count: 1 }];
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    setUiError(null);
    const cashValue = detailedAssets.enabled ? detailedAssets.otherCash : estate.totalAssets;
    if (heirs.length === 0) { setUiError(t('error_no_heirs')); return; }
    if (cashValue <= 0 && !detailedAssets.enabled) { setUiError(t('error_invalid_assets')); return; }

    try {
      if (deceasedGender) {
        const res = calculateShares(heirs, deceasedGender, { ...estate, totalAssets: cashValue, detailed: detailedAssets, detailedWill }, lang);
        setResult(res);
        setStep(AppStep.RESULT);
      }
    } catch (e) { setUiError(t('error_general')); }
  };

  const reset = () => {
    setHeirs([]); setDeceasedGender(null); setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setDetailedAssets({ enabled: false, land: { area: 0, unit: 'cent', valuePerUnit: 0 }, gold: { weight: 0, ratePerGram: 0 }, silver: { weight: 0, ratePerGram: 0 }, otherCash: 0 });
    setDetailedWill({ cash: 0, landArea: 0, goldWeight: 0, silverWeight: 0 });
    setResult(null); setShowQR(false); setUiError(null); setStep(AppStep.WELCOME);
  };

  const getShareSummary = () => {
    if (!result) return "";
    let s = `*${t('distribution_result')}*\n\n`;
    result.shares.forEach(sh => {
      if (sh.amountEach > 0 || sh.landEach > 0) {
        s += `• ${sh.label} (${sh.count}):\n`;
        if (sh.amountEach > 0) s += `  - Cash: ₹${Math.floor(sh.amountEach).toLocaleString()}\n`;
        if (sh.landEach > 0) s += `  - Land: ${sh.landEach.toFixed(3)} ${detailedAssets.land.unit}\n`;
        s += `\n`;
      }
    });
    return s;
  };

  if (step === AppStep.LANGUAGE_SELECT) {
    return (
      <div className="h-full bg-[#1E2E4F] flex flex-col items-center justify-center p-8 space-y-12 overflow-hidden text-center">
        <div className="space-y-4">
          <h1 className="text-3xl font-black text-white">Select Language</h1>
          <h1 className="text-2xl font-black text-white/80 malayalam">ഭാഷ തിരഞ്ഞെടുക്കുക</h1>
          <h1 className="text-2xl font-black text-white/70 arabic" dir="rtl">اختر اللغة</h1>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full max-w-sm mx-auto">
          {[{ id: 'en', l: 'English' }, { id: 'ml', l: 'മലയാളം' }, { id: 'ta', l: 'தமிழ்' }, { id: 'ar', l: 'العربية' }].map(x => (
            <button key={x.id} onClick={() => handleLangSelect(x.id as Language)} className="glass-card p-6 flex flex-col items-center justify-center gap-2 border-white/20 hover:bg-white/20 transition-all active-press">
              <span className="text-white font-bold text-lg">{x.l}</span>
              <span className="text-white/40 text-[10px] uppercase tracking-widest">{x.id}</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (step === AppStep.WELCOME) {
    return (
      <div className="h-full bg-[#1E2E4F] flex flex-col items-center justify-center p-10 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-[#006B46]/20 rounded-full -mr-32 -mt-32 blur-3xl" />
        <div className="relative z-10 animate-in space-y-12 w-full">
          <div className="w-32 h-32 bg-white/10 backdrop-blur-xl rounded-[40px] flex items-center justify-center mx-auto shadow-2xl border border-white/20">
            <svg className="w-16 h-16 text-[#D89F37]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
          </div>
          <div className="space-y-4">
            <h1 className="text-4xl font-extrabold tracking-tight text-white drop-shadow-md">{t('app_title')}</h1>
            <p className="text-slate-300 text-lg opacity-80 font-medium">{t('app_subtitle')}</p>
          </div>
          <div className="flex flex-col gap-4 max-w-xs mx-auto w-full">
            <button onClick={() => setStep(AppStep.DESCRIPTION)} className="w-full bg-[#006B46] text-white py-5 rounded-2xl font-bold text-xl active-press shadow-2xl">{t('start')}</button>
            <button onClick={() => setStep(AppStep.LANGUAGE_SELECT)} className="text-white/40 text-xs font-bold uppercase tracking-widest underline">Change Language</button>
          </div>
        </div>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="flex-1 overflow-y-auto scroll-container py-8 space-y-8 animate-in text-center">
          <h2 className="text-3xl font-black text-[#1E2E4F]">{t('what_is_faraid')}</h2>
          <div className="glass-card p-8 space-y-6 text-slate-700 text-lg shadow-lg">
            <p>{t('faraid_desc_1')}</p>
            <p>{t('faraid_desc_2')}</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.HADITH || step === AppStep.AYAH) {
    const isHadith = step === AppStep.HADITH;
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={isHadith ? AppStep.AYAH : AppStep.RULES} prevStep={isHadith ? AppStep.DESCRIPTION : AppStep.HADITH} setStep={setStep}>
        <div className="flex-1 flex flex-col justify-center py-8 animate-in space-y-8">
          <div className="glass-card p-10 w-full shadow-xl">
            <div className="arabic-display mb-8" dir="rtl">{t(isHadith ? 'hadith_arabic' : 'ayah_arabic')}</div>
            <p className="text-center text-[#1E2E4F] font-bold text-lg leading-relaxed">{t(isHadith ? 'hadith_translation' : 'ayah_translation')}</p>
            <p className="mt-8 text-center text-slate-400 font-bold text-sm tracking-widest uppercase">{t(isHadith ? 'hadith_ref' : 'ayah_ref')}</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.RULES) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.ASSETS} prevStep={AppStep.AYAH} setStep={setStep}>
        <header className="shrink-0 py-6 text-center"><h2 className="text-3xl font-black text-[#1E2E4F]">{t('rules_title')}</h2></header>
        <div className="flex-1 overflow-y-auto scroll-container hide-scrollbar space-y-5 pb-8">
          {['fixed_shares', 'asabah', 'hijb'].map(k => (
            <div key={k} className="glass-card p-6 space-y-3 shadow-md border-l-4 border-[#006B46]">
              <h3 className="font-black text-[#1E2E4F] text-lg">{t(`${k}_title`)}</h3>
              <p className="text-slate-600 text-sm">{t(`${k}_desc`)}</p>
            </div>
          ))}
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    const isRtl = lang === 'ar';
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.GENDER} prevStep={AppStep.RULES} setStep={setStep}>
        <header className="shrink-0 py-6 text-center space-y-2">
          <h2 className="text-3xl font-black text-[#1E2E4F]">{t('estate_info')}</h2>
          <div className="flex justify-center gap-2">
            <button onClick={() => setDetailedAssets({...detailedAssets, enabled: false})} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase ${!detailedAssets.enabled ? 'bg-[#1E2E4F] text-white' : 'bg-slate-200 text-slate-500'}`}>{t('simple_assets')}</button>
            <button onClick={() => setDetailedAssets({...detailedAssets, enabled: true})} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase ${detailedAssets.enabled ? 'bg-[#006B46] text-white' : 'bg-slate-200 text-slate-500'}`}>{t('advanced_assets')}</button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto scroll-container hide-scrollbar space-y-5 pb-8">
          {!detailedAssets.enabled ? (
            <div className="glass-card p-6 space-y-3 shadow-md">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('total_assets')}</label>
              <div className="relative">
                <span className={`absolute ${isRtl ? 'right-0' : 'left-0'} top-1/2 -translate-y-1/2 text-2xl font-black text-slate-300 ml-1`}>₹</span>
                <input type="number" value={estate.totalAssets || ''} onChange={e => setEstate({...estate, totalAssets: Math.max(0, Number(e.target.value))})} className={`w-full bg-transparent border-b-2 border-slate-100 py-3 ${isRtl ? 'pr-8' : 'pl-8'} text-2xl font-black text-[#1E2E4F] outline-none focus:border-[#006B46]`} />
              </div>
            </div>
          ) : (
            <>
              <div className="glass-card p-6 space-y-4 shadow-md bg-white/40">
                <div className="flex items-center justify-between"><h3 className="text-[10px] font-black uppercase text-[#006B46]">{t('land_details')}</h3>
                <div className="flex gap-1">{(['acre', 'cent', 'sqft', 'sqm'] as LandUnit[]).map(u => (
                  <button key={u} onClick={() => setDetailedAssets({ ...detailedAssets, land: { ...detailedAssets.land, unit: u } })} className={`px-2 py-1 rounded text-[8px] font-bold ${detailedAssets.land.unit === u ? 'bg-[#006B46] text-white' : 'bg-slate-100 text-slate-400'}`}>{t(u)}</button>
                ))}</div></div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400 uppercase">{t('land_area')}</label><input type="number" value={detailedAssets.land.area || ''} onChange={e => setDetailedAssets({...detailedAssets, land: {...detailedAssets.land, area: Math.max(0, Number(e.target.value))}})} className="w-full bg-slate-50 p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                  <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400 uppercase">{t('value_per_unit')}</label><input type="number" value={detailedAssets.land.valuePerUnit || ''} onChange={e => setDetailedAssets({...detailedAssets, land: {...detailedAssets.land, valuePerUnit: Math.max(0, Number(e.target.value))}})} className="w-full bg-slate-50 p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                </div>
              </div>
              <div className="grid grid-cols-1 gap-4">
                <div className="glass-card p-6 space-y-4 bg-white/40 shadow-md">
                  <h3 className="text-[10px] font-black uppercase text-[#D89F37]">{t('gold_details')}</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400">Weight (g)</label><input type="number" value={detailedAssets.gold.weight || ''} onChange={e => setDetailedAssets({...detailedAssets, gold: {...detailedAssets.gold, weight: Math.max(0, Number(e.target.value))}})} className="w-full bg-slate-50 p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                    <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400">Rate (₹)</label><input type="number" value={detailedAssets.gold.ratePerGram || ''} onChange={e => setDetailedAssets({...detailedAssets, gold: {...detailedAssets.gold, ratePerGram: Math.max(0, Number(e.target.value))}})} className="w-full bg-slate-50 p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                  </div>
                </div>
              </div>
              <div className="glass-card p-6 space-y-4 bg-white/40 shadow-md">
                <h3 className="text-[10px] font-black uppercase text-blue-600">{t('other_cash')}</h3>
                <input type="number" value={detailedAssets.otherCash || ''} onChange={e => setDetailedAssets({...detailedAssets, otherCash: Math.max(0, Number(e.target.value))})} className="w-full bg-slate-50 p-3 text-2xl font-black text-[#1E2E4F] rounded-xl" />
              </div>
              <div className="pt-6 pb-2"><h3 className="text-[11px] font-black uppercase text-[#D89F37] px-2">{t('will_wasiyyah')}</h3></div>
              <div className="glass-card p-6 space-y-5 bg-[#D89F37]/5 border-[#D89F37]/20 shadow-md">
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400 uppercase">{t('wasiyyah_cash')} (₹)</label><input type="number" value={detailedWill.cash || ''} onChange={e => setDetailedWill({...detailedWill, cash: Math.max(0, Number(e.target.value))})} className="w-full bg-white p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                  <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400 uppercase">{t('wasiyyah_land')} ({t(detailedAssets.land.unit)})</label><input type="number" value={detailedWill.landArea || ''} onChange={e => setDetailedWill({...detailedWill, landArea: Math.max(0, Number(e.target.value))})} className="w-full bg-white p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400 uppercase">Gold Will (g)</label><input type="number" value={detailedWill.goldWeight || ''} onChange={e => setDetailedWill({...detailedWill, goldWeight: Math.max(0, Number(e.target.value))})} className="w-full bg-white p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                    <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400 uppercase">Silver Will (g)</label><input type="number" value={detailedWill.silverWeight || ''} onChange={e => setDetailedWill({...detailedWill, silverWeight: Math.max(0, Number(e.target.value))})} className="w-full bg-white p-2 text-lg font-black text-[#1E2E4F] rounded-lg" /></div>
                  </div>
                </div>
              </div>
            </>
          )}
          {[{l: t('debts'), k: 'debts', i: '📉'}, {l: t('funeral_expenses'), k: 'funeral', i: '🕯️'}, ...(!detailedAssets.enabled ? [{l: t('will_wasiyyah'), k: 'will', i: '📜'}] : [])].map(f => (
            <div key={f.k} className="glass-card p-6 space-y-3 shadow-md">
