              <div className="relative"><span className="absolute left-0 top-1/2 -translate-y-1/2 text-2xl font-black text-slate-300 ml-1">₹</span>
              <input type="number" value={(estate as any)[f.k] || ''} onChange={e => setEstate({...estate, [f.k]: Math.max(0, Number(e.target.value))})} className="w-full bg-transparent border-b-2 border-slate-100 py-3 pl-8 text-2xl font-black text-[#1E2E4F] outline-none focus:border-[#006B46]" /></div>
            </div>
          ))}
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep} disabled={!deceasedGender}>
