              <button key={g} onClick={() => setDeceasedGender(g as any)} className={`p-10 rounded-[40px] font-black text-3xl transition-all border-4 ${deceasedGender === g ? 'bg-[#1E2E4F] text-white border-[#D89F37]' : 'bg-white text-slate-400 border-white shadow-lg'}`}>
                <span>{g === 'Male' ? t('male') : t('female')}</span>
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
