          {result.warnings.map((w, i) => <div key={i} className={`p-5 rounded-2xl bg-amber-50 text-amber-800 text-[13px] font-bold border border-amber-100 flex items-center gap-3 ${isAr ? 'arabic' : ''}`}><span>⚠️</span> {t(w)}</div>)}
