              <button onClick={() => setShowQR(false)} className={`w-full bg-[#1E2E4F] text-white py-4 rounded-2xl font-bold text-lg active-press ${isAr ? 'arabic text-xl' : ''}`}>{t('close')}</button>
            </div>
          </div>
        )}
      </div>
    );
